ATA_WAIT_DATA equ 4
BLOCK_DEVICE_NONE equ 0
BLOCK_DEVICE_ATA_PIO equ 1
BLOCK_DEVICE_AHCI equ 2
AHCI_BAR_STATE_NONE equ 0
AHCI_BAR_STATE_MMIO equ 1
AHCI_BAR_STATE_INVALID equ 2
AHCI_PROOF_REQ_PCI_CLASS equ 0x00000001
AHCI_PROOF_REQ_BAR5_MMIO equ 0x00000002
AHCI_PROOF_REQ_HBA_RESET equ 0x00000004
AHCI_PROOF_REQ_PORT_DETECT equ 0x00000008
AHCI_PROOF_REQ_IDENTIFY equ 0x00000010
AHCI_PROOF_REQ_SECTOR_IO equ 0x00000020
AHCI_PROOF_REQ_NO_IDE_FALLBACK equ 0x00000040
AHCI_PROOF_REQUIRED_MASK equ 0x0000007f
AHCI_GUARD_NO_SILENT_BIND equ 0x00000001
AHCI_GUARD_UNSUPPORTED_REJECTED equ 0x00000002
AHCI_GUARD_ATA_ONLY_OPS equ 0x00000004
BLOCK_OPS_READ_OFFSET equ 0
BLOCK_OPS_WRITE_OFFSET equ 4
BLOCK_OPS_FLUSH_OFFSET equ 8
BLOCK_OPS_DWORDS equ 3
BLOCK_OP_NONE equ 0
BLOCK_OP_READ equ 1
BLOCK_OP_WRITE equ 2
BLOCK_OP_FLUSH equ 3
BLOCK_STATUS_IDLE equ 0
BLOCK_STATUS_OK equ 1
BLOCK_STATUS_FAIL equ 2
BLOCK_SECTOR_BYTES equ 512
BLOCK_ERROR_NONE equ 0
BLOCK_ERROR_NO_DEVICE equ 1
BLOCK_ERROR_ATA_IO equ 2
BLOCK_ERROR_ATA_FLUSH equ 3
BLOCK_ERROR_MBR_READ equ 4
BLOCK_ERROR_NO_FAT_PARTITION equ 5
BLOCK_ERROR_PARTITION_RANGE equ 6
BLOCK_ERROR_UNSUPPORTED_CONTROLLER equ 7
BLOCK_PARTITION_NONE equ 0
BLOCK_PARTITION_RAW equ 1
BLOCK_PARTITION_MBR_FAT16 equ 2
BLOCK_PARTITION_FAIL equ 3
MBR_SIGNATURE_OFFSET equ 510
MBR_SIGNATURE_VALUE equ 0xaa55
MBR_PARTITION_TABLE_OFFSET equ 446
MBR_PARTITION_ENTRY_BYTES equ 16
MBR_PARTITION_COUNT equ 4
MBR_PARTITION_TYPE_OFFSET equ 4
MBR_PARTITION_LBA_OFFSET equ 8
MBR_PARTITION_SECTORS_OFFSET equ 12
MBR_PARTITION_TYPE_FAT16_CHS equ 0x04
MBR_PARTITION_TYPE_FAT16_LARGE equ 0x06
MBR_PARTITION_TYPE_FAT16_LBA equ 0x0e
ACPI_PM1A_CNT_PORT equ 0x0604
ACPI_PM1_CNT_S5_ENABLE equ 0x2000
BOCHS_PM1A_CNT_PORT equ 0xb004
VIRTUALBOX_PM1A_CNT_PORT equ 0x4004
VIRTUALBOX_PM1_CNT_S5_ENABLE equ 0x3400
RESET_CONTROL_PORT equ 0x0cf9
RESET_CONTROL_SYSTEM equ 0x02
RESET_CONTROL_FULL_RESET equ 0x06
CMOS_INDEX_PORT equ 0x70
CMOS_DATA_PORT equ 0x71
CMOS_RTC_SECONDS_REGISTER equ 0x00
DEBUGCON_PORT equ 0x00e9
UEFI_DEBUGCON_PORT equ 0x0402
SERIAL_COM1_BASE equ 0x03f8
SERIAL_COM1_DATA equ SERIAL_COM1_BASE + 0
SERIAL_COM1_IER equ SERIAL_COM1_BASE + 1
SERIAL_COM1_FCR equ SERIAL_COM1_BASE + 2
SERIAL_COM1_LCR equ SERIAL_COM1_BASE + 3
SERIAL_COM1_MCR equ SERIAL_COM1_BASE + 4
SERIAL_COM1_LSR equ SERIAL_COM1_BASE + 5
SERIAL_LCR_DLAB equ 0x80
SERIAL_LCR_8N1 equ 0x03
SERIAL_FCR_ENABLE_CLEAR equ 0xc7
SERIAL_MCR_DTR_RTS_OUT2 equ 0x0b
SERIAL_LSR_THR_EMPTY equ 0x20
SERIAL_POLL_LIMIT equ 0x1000
SHUTDOWN_PROOF_DELAY_SECONDS equ 20

SC_LSHIFT equ 0x2a
SC_RSHIFT equ 0x36
PAYLOAD_KEY_RIGHTARROW equ 0xae
PAYLOAD_KEY_LEFTARROW equ 0xac
PAYLOAD_KEY_UPARROW equ 0xad
PAYLOAD_KEY_DOWNARROW equ 0xaf
PAYLOAD_KEY_ESCAPE equ 27
PAYLOAD_KEY_ENTER equ 13
PAYLOAD_KEY_TAB equ 9
PAYLOAD_KEY_F1 equ 0xbb
PAYLOAD_KEY_F2 equ 0xbc
PAYLOAD_KEY_F3 equ 0xbd
PAYLOAD_KEY_F4 equ 0xbe
PAYLOAD_KEY_F5 equ 0xbf
PAYLOAD_KEY_F6 equ 0xc0
PAYLOAD_KEY_F7 equ 0xc1
PAYLOAD_KEY_F8 equ 0xc2
PAYLOAD_KEY_F9 equ 0xc3
PAYLOAD_KEY_F10 equ 0xc4
PAYLOAD_KEY_F11 equ 0xd7
PAYLOAD_KEY_F12 equ 0xd8
PAYLOAD_KEY_BACKSPACE equ 127
PAYLOAD_KEY_PAUSE equ 0xff
PAYLOAD_KEY_EQUALS equ 0x3d
PAYLOAD_KEY_MINUS equ 0x2d
PAYLOAD_KEY_RSHIFT equ 0xb6
PAYLOAD_KEY_RCTRL equ 0x9d
PAYLOAD_KEY_RALT equ 0xb8

start:
    cli
    mov [boot_entry_eax], eax
    mov [boot_entry_ebx], ebx
    mov [boot_entry_ecx], ecx
    mov [boot_entry_edx], edx
    mov [boot_entry_esi], esi
    mov [boot_entry_esp], esp
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    mov ss, ax
    mov esp, KERNEL_STACK_TOP

    cld
    call bios_boot_probe
    call uefi_entry_probe
    call serial_debug_init
    call cpu_tables_init
    call cpu_probe_features
    call fpu_init
    call pic_remap_and_mask
    call pit_init_100hz
    call paging_init
    call kernel_relocation_probe
    call pmm_init
    call pmm_self_test
    call framebuffer_map_lfb
    call framebuffer_init
    call vmm_self_test
    call kernel_enter_persistent_high_mainline

kernel_mainline:
    call kernel_relocation_probe
    call kernel_high_mainline_entry_checkpoint
    call heap_init
    call heap_self_test
    call fpu_self_test
    call libc_self_test
    call storage_init
    call pci_scan_qemu
    call block_driver_probe_storage_classes
    call acpi_probe_tables
    call audio_init
    call ps2_mouse_init
    call scheduler_init
    call scheduler_preempt_self_test
    call c_runtime_self_test
    cmp eax, C_RUNTIME_MAGIC
    je .c_runtime_ok
    mov byte [c_runtime_status], 2
    jmp .c_runtime_done

.c_runtime_ok:
    mov byte [c_runtime_status], 1

.c_runtime_done:
    call kernel_high_mainline_late_checkpoint
    call write_smoke_status
%ifdef SHUTDOWN_PANIC_PROOF_PANIC
    ud2
%endif
%ifdef SHUTDOWN_PANIC_PROOF_HALT
    mov dword [shutdown_state], SHUTDOWN_HALT
    call write_smoke_status
    call shutdown_report_status
.proof_halt_loop:
    cli
    hlt
    jmp .proof_halt_loop
%endif
%ifdef SHUTDOWN_PANIC_PROOF_REBOOT
    mov dword [shutdown_state], SHUTDOWN_REBOOT
    call write_smoke_status
    call shutdown_report_status
    call shutdown_proof_wait_before_guest_exit
    call keyboard_controller_reboot
%endif
%ifdef SHUTDOWN_PANIC_PROOF_POWEROFF
    mov dword [shutdown_state], SHUTDOWN_POWEROFF
    call write_smoke_status
    call shutdown_report_status
    call shutdown_proof_wait_before_guest_exit
    call acpi_poweroff
%endif
%ifdef LINUX_M1_SMOKE
    call linux_m1_smoke_launch
%else
    call user_probe_run
%endif

user_probe_finished:
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    mov ss, ax
    call kernel_switch_main_stack_and_return
    call process_return_to_kernel
%ifdef LINUX_M1_SMOKE
    call linux_m1_smoke_launch
    call process_boot_launch_payload
%else
    call process_boot_launch_payload
%endif

payload_user_finished:
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    mov ss, ax
    call kernel_switch_main_stack_and_return
    call process_return_to_kernel
    call clear_screen
    mov esi, banner
    call print_string
    call draw_primary_payload_status
    call draw_heap_status
    call draw_timer_status
    call write_smoke_status
    call irq_unmask_timer
    sti

main_loop:
    mov esi, prompt
    call print_string
    call read_line
    call handle_command
    jmp main_loop

handle_command:
    mov esi, input_buffer
    call skip_spaces
    mov [command_start], esi

    cmp byte [esi], 0
    je .done

    mov edi, cmd_help
    call match_exact
    cmp al, 1
    je .help

    mov esi, [command_start]
    mov edi, cmd_about
    call match_exact
    cmp al, 1
    je .about

    mov esi, [command_start]
    mov edi, cmd_clear
    call match_exact
    cmp al, 1
    je .clear

    mov esi, [command_start]
    mov edi, cmd_mem
    call match_exact
    cmp al, 1
    je .mem

    mov esi, [command_start]
    mov edi, cmd_mode
    call match_exact
    cmp al, 1
    je .mode

    mov esi, [command_start]
    mov edi, cmd_ticks
    call match_exact
    cmp al, 1
    je .ticks

    mov esi, [command_start]
    mov edi, cmd_heap
    call match_exact
    cmp al, 1
    je .heap

    mov esi, [command_start]
    mov edi, cmd_paging
    call match_exact
    cmp al, 1
    je .paging

    mov esi, [command_start]
    mov edi, cmd_libc
    call match_exact
    cmp al, 1
    je .libc

    mov esi, [command_start]
    mov edi, cmd_c
    call match_exact
    cmp al, 1
    je .cprobe

    mov esi, [command_start]
    mov edi, cmd_user
    call match_exact
    cmp al, 1
    je .user

    mov esi, [command_start]
    mov edi, cmd_primary_asset
    call match_exact
    cmp al, 1
    je .primary_asset

    mov esi, [command_start]
    mov edi, cmd_primary_asset_legacy
    call match_exact
    cmp al, 1
    je .primary_asset

    mov esi, [command_start]
    mov edi, cmd_reboot
    call match_exact
    cmp al, 1
    je .reboot

    mov esi, [command_start]
    mov edi, cmd_halt
    call match_exact
    cmp al, 1
    je .halt

    mov esi, [command_start]
    mov edi, cmd_poweroff
    call match_exact
    cmp al, 1
    je .poweroff

    mov esi, [command_start]
    mov edi, cmd_echo
    call starts_with_word
    cmp al, 1
    je .echo

    mov esi, unknown_message
    call print_string
    mov esi, [command_start]
    call print_string
    call newline
    ret

.help:
    mov esi, help_text
    call print_string
    ret

.about:
    mov esi, about_text
    call print_string
    ret

.clear:
    call clear_screen
    ret

.mem:
    mov esi, conventional_prefix
    call print_string
    movzx eax, word [BOOT_INFO_ADDR]
    call print_dec
    mov esi, kb_suffix
    call print_string
    mov esi, extended_prefix
    call print_string
    movzx eax, word [BOOT_INFO_ADDR + 4]
    call print_dec
    mov esi, kb_suffix
    call print_string
    ret

.mode:
    mov esi, mode_text
    call print_string
    ret

.ticks:
    mov esi, ticks_prefix
    call print_string
    mov eax, [timer_ticks]
    call print_dec
    mov esi, ticks_suffix
    call print_string
    ret

.heap:
    mov esi, heap_start_prefix
    call print_string
    mov eax, [heap_start]
    call print_hex32
    call newline

    mov esi, heap_free_head_prefix
    call print_string
    mov eax, [heap_free_head]
    call print_hex32
    call newline

    mov esi, heap_free_prefix
    call print_string
    call heap_free_bytes
    call print_hex32
    call newline

    mov esi, heap_alloc_prefix
    call print_string
    mov eax, [heap_alloc_count]
    call print_dec
    call newline

    mov esi, heap_test_prefix
    call print_string
    cmp byte [heap_test_status], 1
    je .heap_ok
    mov esi, fail_text
    call print_string
    ret

.heap_ok:
    mov esi, ok_text
    call print_string
    ret

.paging:
    mov esi, paging_state_prefix
    call print_string
    cmp byte [paging_status], 1
    je .paging_on
    mov esi, off_text
    call print_string
    jmp .paging_dir

.paging_on:
    mov esi, on_text
    call print_string

.paging_dir:
    mov esi, paging_dir_prefix
    call print_string
    mov eax, PAGING_DIR_ADDR
    call print_hex32
    call newline

    mov esi, paging_mapped_prefix
    call print_string
    mov eax, PAGING_MAPPED_BYTES / 0x00100000
    call print_dec
    mov esi, mib_suffix
    call print_string

    mov esi, pmm_total_prefix
    call print_string
    mov eax, [pmm_total_pages]
    call print_dec
    mov esi, pages_suffix
    call print_string

    mov esi, pmm_free_prefix
    call print_string
    mov eax, [pmm_free_pages]
    call print_dec
    mov esi, pages_suffix
    call print_string

    mov esi, pmm_used_prefix
    call print_string
    mov eax, [pmm_used_pages]
    call print_dec
    mov esi, pages_suffix
    call print_string

    mov esi, pmm_test_prefix
    call print_string
    cmp byte [pmm_test_status], 1
    je .pmm_ok
    mov esi, fail_text
    call print_string
    jmp .vmm_report

.pmm_ok:
    mov esi, ok_text
    call print_string

.vmm_report:
    mov esi, vmm_test_prefix
    call print_string
    cmp byte [vmm_test_status], 1
    je .vmm_ok
    mov esi, fail_text
    call print_string
    ret

.vmm_ok:
    mov esi, ok_text
    call print_string
    ret

.libc:
    cmp byte [libc_test_status], 1
    je .libc_ok
    push dword fail_text_plain
    push dword libc_status_fmt
    call kprintf
    add esp, 8
    ret

.libc_ok:
    push dword ok_text_plain
    push dword libc_status_fmt
    call kprintf
    add esp, 8

    push dword ok_text_plain
    push dword fpu_status_fmt
    call kprintf
    add esp, 8

    push dword libc_test_source
    call libc_strlen
    add esp, 4
    push eax
    push dword libc_strlen_fmt
    call kprintf
    add esp, 8

    push dword [libc_last_remainder]
    push dword [libc_last_quotient]
    push dword libc_math_fmt
    call kprintf
    add esp, 12
    ret

.cprobe:
    call c_runtime_report
    ret

.user:
    mov esi, user_elf_prefix
    call print_string
    cmp byte [user_elf_status], 1
    jne .user_elf_fail
    cmp byte [user_elf_parse_status], 1
    jne .user_elf_fail
    mov esi, ok_text
    call print_string
    jmp .user_entry

.user_elf_fail:
    mov esi, fail_text
    call print_string

.user_entry:
    mov esi, user_entry_prefix
    call print_string
    mov eax, [user_entry_addr]
    call print_hex32
    call newline
    mov esi, user_flags_prefix
    call print_string
    mov eax, [user_probe_flags_seen]
    call print_hex32
    call newline
    mov esi, user_primary_asset_magic_prefix
    call print_string
    mov eax, [user_primary_asset_magic_seen]
    call print_hex32
    call newline

    mov esi, user_status_prefix
    call print_string
    cmp byte [user_probe_status], 3
    je .user_ok
    mov esi, fail_text
    call print_string
    jmp .user_details

.user_ok:
    mov esi, ok_text
    call print_string

.user_details:
    mov esi, user_magic_prefix
    call print_string
    mov eax, [user_probe_magic_seen]
    call print_hex32
    call newline
    mov esi, user_cs_prefix
    call print_string
    movzx eax, word [user_probe_cs]
    call print_hex32
    mov esi, user_ss_prefix
    call print_string
    movzx eax, word [user_probe_ss]
    call print_hex32
    call newline
    mov esi, user_fault_prefix
    call print_string
    cmp byte [user_fault_status], 1
    je .user_fault_ok
    mov esi, fail_text
    call print_string
    ret

.user_fault_ok:
    mov esi, ok_text_plain
    call print_string
    mov esi, user_fault_addr_prefix
    call print_string
    mov eax, [user_fault_addr]
    call print_hex32
    call newline
    ret

.primary_asset:
    mov esi, ata_status_prefix
    call print_string
    cmp byte [ata_status], 1
    je .ata_ok
    mov esi, fail_text
    call print_string
    jmp .primary_asset_fat

.ata_ok:
    mov esi, ok_text
    call print_string

.primary_asset_fat:
    mov esi, fat_status_prefix
    call print_string
    cmp byte [fat_status], 1
    je .fat_ok
    mov esi, fail_text
    call print_string
    jmp .primary_asset_file

.fat_ok:
    mov esi, ok_text
    call print_string

.primary_asset_file:
    mov esi, primary_asset_status_prefix
    call print_string
    cmp byte [primary_asset_status], 1
    je .primary_asset_ok
    mov esi, fail_text
    call print_string
    ret

.primary_asset_ok:
    mov esi, ok_text
    call print_string

    mov esi, primary_package_parse_prefix
    call print_string
    cmp byte [primary_package_parse_status], 1
    je .primary_package_parse_ok
    mov esi, fail_text
    call print_string
    ret

.primary_package_parse_ok:
    mov esi, ok_text
    call print_string

    mov esi, primary_asset_size_prefix
    call print_string
    mov eax, [primary_asset_size]
    call print_dec
    mov esi, bytes_suffix
    call print_string

    mov esi, primary_package_member_count_prefix
    call print_string
    mov eax, [primary_package_member_count]
    call print_dec
    call newline

    mov esi, primary_package_dir_prefix
    call print_string
    mov eax, [primary_package_directory_offset]
    call print_hex32
    call newline

    mov esi, primary_palette_prefix
    call print_string
    mov eax, [primary_palette_offset]
    call print_hex32
    mov esi, package_member_size_mid
    call print_string
    mov eax, [primary_palette_size]
    call print_dec
    call newline

    mov esi, primary_colormap_prefix
    call print_string
    mov eax, [primary_colormap_offset]
    call print_hex32
    mov esi, package_member_size_mid
    call print_string
    mov eax, [primary_colormap_size]
    call print_dec
    call newline

    mov esi, primary_asset_cluster_prefix
    call print_string
    movzx eax, word [primary_asset_first_cluster]
    call print_dec
    call newline

    mov esi, primary_payload_elf_prefix
    call print_string
    cmp dword [payload_exec_status + USER_KIND_PAYLOAD_PRIMARY * 4], 1
    je .primary_payload_elf_ok
    mov esi, fail_text
    call print_string
    jmp .primary_asset_load_address

.primary_payload_elf_ok:
    mov esi, ok_text
    call print_string

    mov esi, primary_payload_elf_size_prefix
    call print_string
    mov eax, [payload_exec_size + USER_KIND_PAYLOAD_PRIMARY * 4]
    call print_dec
    mov esi, bytes_suffix
    call print_string

    mov esi, primary_payload_elf_cluster_prefix
    call print_string
    mov eax, [payload_exec_first_cluster + USER_KIND_PAYLOAD_PRIMARY * 4]
    call print_dec
    call newline

    mov esi, primary_payload_elf_load_prefix
    call print_string
    cmp dword [payload_exec_load_status + USER_KIND_PAYLOAD_PRIMARY * 4], 1
    je .primary_payload_elf_load_ok
    mov esi, fail_text
    call print_string
    jmp .primary_asset_load_address

.primary_payload_elf_load_ok:
    mov esi, ok_text
    call print_string

    mov esi, primary_payload_elf_parse_prefix
    call print_string
    cmp dword [payload_exec_parse_status + USER_KIND_PAYLOAD_PRIMARY * 4], 1
    je .primary_payload_elf_parse_ok
    mov esi, fail_text
    call print_string
    jmp .primary_asset_load_address

.primary_payload_elf_parse_ok:
    mov esi, ok_text
    call print_string

    mov esi, primary_payload_elf_entry_prefix
    call print_string
    mov eax, [payload_exec_entry + USER_KIND_PAYLOAD_PRIMARY * 4]
    call print_hex32
    call newline

    mov esi, primary_payload_elf_mem_prefix
    call print_string
    mov eax, [payload_exec_segment_memsz + USER_KIND_PAYLOAD_PRIMARY * 4]
    call print_dec
    mov esi, bytes_suffix
    call print_string

    mov esi, primary_payload_elf_end_prefix
    call print_string
    mov eax, [payload_exec_segment_end + USER_KIND_PAYLOAD_PRIMARY * 4]
    call print_hex32
    call newline

    mov esi, payload_user_window_prefix
    call print_string
    cmp byte [payload_user_window_status], 1
    je .payload_user_window_ok
    mov esi, fail_text
    call print_string
    jmp .primary_asset_load_address

.payload_user_window_ok:
    mov esi, ok_text
    call print_string

    mov esi, process_exec_prefix
    call print_string
    cmp byte [process_exec_status], 1
    je .process_exec_ok
    mov esi, fail_text
    call print_string
    jmp .primary_asset_load_address

.process_exec_ok:
    mov esi, ok_text
    call print_string

    mov esi, process_exec_path_prefix
    call print_string
    cmp dword [process_exec_path_ptr], 0
    je .process_exec_path_empty
    mov esi, [process_exec_path_ptr]
    call print_string
    call newline
    jmp .process_exec_syscall_status

.process_exec_path_empty:
    mov esi, null_text
    call print_string
    call newline

.process_exec_syscall_status:
    mov esi, process_exec_syscall_prefix
    call print_string
    mov eax, [sys_exec_attempts]
    call print_dec
    mov al, '/'
    call put_char
    mov eax, [sys_exec_successes]
    call print_dec
    mov al, '/'
    call put_char
    mov eax, [sys_exec_failures]
    call print_dec
    mov al, '/'
    call put_char
    mov eax, [sys_exec_handoffs]
    call print_dec
    mov al, '/'
    call put_char
    mov eax, [sys_exec_scheduled]
    call print_dec
    mov al, '/'
    call put_char
    mov eax, [sys_exec_rollbacks]
    call print_dec
    call newline

.primary_asset_load_address:
    mov esi, primary_asset_load_prefix
    call print_string
    mov eax, PRIMARY_ASSET_LOAD_ADDR
    call print_hex32
    call newline
    ret

.reboot:
    mov esi, reboot_message
    call print_string
    mov dword [shutdown_state], SHUTDOWN_REBOOT
    call write_smoke_status
    call shutdown_report_status
    call keyboard_controller_reboot
    ret

.halt:
    mov esi, halt_message
    call print_string
    mov dword [shutdown_state], SHUTDOWN_HALT
    call write_smoke_status
    call shutdown_report_status

.halt_loop:
    cli
    hlt
    jmp .halt_loop

.poweroff:
    mov esi, poweroff_message
    call print_string
    mov dword [shutdown_state], SHUTDOWN_POWEROFF
    call write_smoke_status
    call shutdown_report_status
    call acpi_poweroff
    ret

.echo:
    mov esi, ebx
    call print_string
    call newline

.done:
    ret

read_line:
    push eax
    push ecx
    push edi

    mov edi, input_buffer
    mov ecx, INPUT_MAX - 1

.key_loop:
    call read_key
    cmp al, 13
    je .enter
    cmp al, 8
    je .backspace
    cmp al, 0
    je .key_loop
    cmp ecx, 0
    je .key_loop

    stosb
    dec ecx
    call put_char
    jmp .key_loop

.backspace:
    cmp edi, input_buffer
    je .key_loop
    dec edi
    inc ecx
    mov byte [edi], 0
    mov al, 8
    call put_char
    mov al, ' '
    call put_char
    mov al, 8
    call put_char
    jmp .key_loop

.enter:
    mov byte [edi], 0
    call newline
    pop edi
    pop ecx
    pop eax
    ret

read_key:
    push ebx

.next_scancode:
    call wait_scancode
    cmp al, 0xe0
    je .next_scancode

    mov bl, al
    test bl, 0x80
    jnz .release

    cmp bl, SC_LSHIFT
    je .shift_down
    cmp bl, SC_RSHIFT
    je .shift_down

    movzx ebx, bl
    cmp byte [shift_down], 0
    jne .shifted
    mov al, [keymap_normal + ebx]
    pop ebx
    ret

.shifted:
    mov al, [keymap_shift + ebx]
    pop ebx
    ret

.shift_down:
    mov byte [shift_down], 1
    jmp .next_scancode

.release:
    and bl, 0x7f
    cmp bl, SC_LSHIFT
    je .shift_up
    cmp bl, SC_RSHIFT
    je .shift_up
    jmp .next_scancode

.shift_up:
    mov byte [shift_down], 0
    jmp .next_scancode

wait_scancode:
    in al, 0x64
    test al, 0x01
    jz wait_scancode
    in al, 0x60
    ret

keyboard_controller_reboot:
    mov dx, RESET_CONTROL_PORT
    mov al, RESET_CONTROL_SYSTEM
    out dx, al
    call io_wait
    mov al, RESET_CONTROL_FULL_RESET
    out dx, al
    call io_wait

    in al, 0x64
    test al, 0x02
    jnz keyboard_controller_reboot
    mov al, 0xfe
    out 0x64, al

.wait:
    cli
    hlt
    jmp .wait

acpi_poweroff:
    mov dx, ACPI_PM1A_CNT_PORT
    mov ax, ACPI_PM1_CNT_S5_ENABLE
    out dx, ax
    mov dx, BOCHS_PM1A_CNT_PORT
    out dx, ax
    mov dx, VIRTUALBOX_PM1A_CNT_PORT
    mov ax, VIRTUALBOX_PM1_CNT_S5_ENABLE
    out dx, ax

.wait:
    cli
    hlt
    jmp .wait

acpi_probe_tables:
    pushad
    mov byte [acpi_status], ACPI_STATUS_NONE
    mov byte [acpi_scan_source], 0
    mov byte [acpi_root_kind], 0
    mov dword [acpi_rsdp_addr], 0
    mov dword [acpi_rsdp_length], 0
    mov dword [acpi_revision], 0
    mov dword [acpi_checksum_flags], 0
    mov dword [acpi_rsdt_addr], 0
    mov dword [acpi_xsdt_addr_low], 0
    mov dword [acpi_xsdt_addr_high], 0
    mov dword [acpi_selected_sdt_addr], 0
    mov dword [acpi_root_entry_count], 0
    mov dword [acpi_valid_sdt_count], 0
    mov dword [acpi_madt_addr], 0
    mov dword [acpi_hpet_addr], 0
    mov dword [acpi_mapped_pages], 0
    mov dword [acpi_map_failures], 0
    mov dword [acpi_last_mapped_page], 0
    mov dword [acpi_last_map_length], 0
    mov dword [mmio_process_pde_installs], 0
    mov dword [mmio_last_pde_index], 0
    mov dword [mmio_last_pde_entry], 0
    mov byte [acpi_madt_parse_status], 0
    mov byte [acpi_hpet_parse_status], 0
    mov dword [acpi_madt_lapic_addr], 0
    mov dword [acpi_madt_flags], 0
    mov dword [acpi_madt_entry_count], 0
    mov dword [acpi_madt_end_ptr], 0
    mov dword [acpi_lapic_count], 0
    mov dword [acpi_lapic_enabled_count], 0
    mov dword [acpi_lapic_first_uid], 0
    mov dword [acpi_lapic_first_id], 0
    mov dword [acpi_ioapic_count], 0
    mov dword [acpi_ioapic_first_id], 0
    mov dword [acpi_ioapic_first_addr], 0
    mov dword [acpi_ioapic_first_gsi_base], 0
    mov dword [acpi_iso_count], 0
    mov dword [acpi_iso_first_bus], 0
    mov dword [acpi_iso_first_source], 0
    mov dword [acpi_iso_first_gsi], 0
    mov dword [acpi_iso_first_flags], 0
    mov dword [acpi_lapic_nmi_count], 0
    mov dword [acpi_lapic_override_count], 0
    mov dword [acpi_lapic_override_low], 0
    mov dword [acpi_lapic_override_high], 0
    mov dword [acpi_hpet_block_id], 0
    mov dword [acpi_hpet_gas_info], 0
    mov dword [acpi_hpet_addr_low], 0
    mov dword [acpi_hpet_addr_high], 0
    mov dword [acpi_hpet_number], 0
    mov dword [acpi_hpet_min_tick], 0
    mov dword [acpi_hpet_page_prot], 0
    mov byte [lapic_mmio_status], MMIO_PROBE_NONE
    mov byte [lapic_live_status], LAPIC_LIVE_STATUS_NONE
    mov byte [apic_irq_status], APIC_IRQ_STATUS_NONE
    mov byte [ioapic_mmio_status], MMIO_PROBE_NONE
    mov byte [hpet_mmio_status], MMIO_PROBE_NONE
    mov dword [lapic_mmio_addr], 0
    mov dword [lapic_mmio_id], 0
    mov dword [lapic_mmio_version], 0
    mov dword [lapic_mmio_spurious], 0
    mov dword [lapic_live_svr_before], 0
    mov dword [lapic_live_svr_written], 0
    mov dword [lapic_live_svr_after], 0
    mov dword [lapic_spurious_irq_count], 0
    mov dword [apic_irq_route_count], 0
    mov dword [apic_irq_match_count], 0
    mov dword [apic_irq_last_index], 0xffffffff
    mov dword [apic_irq_expected_low], 0
    mov dword [apic_irq_expected_high], 0
    mov dword [apic_irq_read_low], 0
    mov dword [apic_irq_read_high], 0
    mov dword [ioapic_mmio_addr], 0
    mov dword [ioapic_mmio_id], 0
    mov dword [ioapic_mmio_version], 0
    mov byte [ioapic_redir_status], MMIO_PROBE_NONE
    mov dword [ioapic_redir_entry_count], 0
    mov dword [ioapic_redir_gsi0_low], 0
    mov dword [ioapic_redir_gsi0_high], 0
    mov dword [ioapic_redir_iso_gsi], 0
    mov dword [ioapic_redir_iso_index], 0
    mov dword [ioapic_redir_iso_low], 0
    mov dword [ioapic_redir_iso_high], 0
    mov byte [irq_route_status], IRQ_ROUTE_STATUS_NONE
    mov dword [irq_route_count], 0
    mov dword [irq_route_iso_hits], 0
    mov dword [irq_route_timer_gsi], IRQ_LEGACY_TIMER
    mov dword [irq_route_keyboard_gsi], IRQ_LEGACY_KEYBOARD
    mov dword [irq_route_audio_gsi], IRQ_LEGACY_AUDIO
    mov dword [irq_route_mouse_gsi], IRQ_LEGACY_MOUSE
    mov dword [irq_route_ide_primary_gsi], IRQ_LEGACY_IDE_PRIMARY
    mov dword [irq_route_timer_flags], 0
    mov dword [irq_route_keyboard_flags], 0
    mov dword [irq_route_audio_flags], 0
    mov dword [irq_route_mouse_flags], 0
    mov dword [irq_route_ide_primary_flags], 0
    mov byte [ioapic_program_status], IRQ_IOAPIC_PROGRAM_STATUS_NONE
    mov dword [ioapic_program_route_count], 0
    mov dword [ioapic_program_dest_id], 0
    mov dword [ioapic_program_last_index], 0xffffffff
    mov dword [ioapic_plan_timer_index], 0xffffffff
    mov dword [ioapic_plan_keyboard_index], 0xffffffff
    mov dword [ioapic_plan_audio_index], 0xffffffff
    mov dword [ioapic_plan_mouse_index], 0xffffffff
    mov dword [ioapic_plan_ide_primary_index], 0xffffffff
    mov dword [ioapic_plan_timer_low], 0
    mov dword [ioapic_plan_keyboard_low], 0
    mov dword [ioapic_plan_audio_low], 0
    mov dword [ioapic_plan_mouse_low], 0
    mov dword [ioapic_plan_ide_primary_low], 0
    mov dword [ioapic_plan_timer_high], 0
    mov dword [ioapic_plan_keyboard_high], 0
    mov dword [ioapic_plan_audio_high], 0
    mov dword [ioapic_plan_mouse_high], 0
    mov dword [ioapic_plan_ide_primary_high], 0
    mov byte [ioapic_masked_arm_status], IRQ_IOAPIC_ARM_STATUS_NONE
    mov dword [ioapic_masked_arm_route_count], 0
    mov dword [ioapic_masked_arm_match_count], 0
    mov dword [ioapic_masked_arm_last_index], 0xffffffff
    mov dword [ioapic_masked_arm_expected_low], 0
    mov dword [ioapic_masked_arm_expected_high], 0
    mov dword [ioapic_masked_arm_read_low], 0
    mov dword [ioapic_masked_arm_read_high], 0
    mov dword [hpet_mmio_addr], 0
    mov dword [hpet_mmio_cap_low], 0
    mov dword [hpet_mmio_cap_high], 0
    mov byte [hpet_counter_status], MMIO_PROBE_NONE
    mov byte [hpet_live_status], MMIO_PROBE_NONE
    mov dword [hpet_counter_config], 0
    mov dword [hpet_counter_start_low], 0
    mov dword [hpet_counter_end_low], 0
    mov dword [hpet_counter_delta_low], 0
    mov dword [hpet_live_config], 0
    mov dword [hpet_live_current_low], 0
    mov dword [hpet_live_delta_low], 0
    mov dword [hpet_live_period_fs], 0
    mov dword [hpet_live_last_tick], 0xffffffff
    mov byte [hpet_clock_status], HPET_CLOCK_STATUS_NONE
    mov dword [hpet_clock_ticks_per_ms], 0
    mov dword [hpet_clock_last_counter_low], 0
    mov dword [hpet_clock_last_delta], 0
    mov dword [hpet_clock_last_ms], 0
    mov dword [hpet_clock_remainder_ticks], 0
    mov dword [hpet_clock_sample_count], 0

    movzx esi, word [ACPI_RSDP_EBDA_SEG_PTR]
    shl esi, 4
    cmp esi, 0x00080000
    jb .scan_bios_area
    cmp esi, 0x000a0000
    jae .scan_bios_area
    mov ecx, ACPI_EBDA_SCAN_BYTES
    call acpi_find_rsdp_in_range
    jc .scan_bios_area
    mov byte [acpi_scan_source], ACPI_SCAN_SOURCE_EBDA
    jmp .found

.scan_bios_area:
    mov esi, ACPI_BIOS_SCAN_START
    mov ecx, ACPI_BIOS_SCAN_BYTES
    call acpi_find_rsdp_in_range
    jc .done
    mov byte [acpi_scan_source], ACPI_SCAN_SOURCE_BIOS

.found:
    mov [acpi_rsdp_addr], eax
    mov esi, eax
    or dword [acpi_checksum_flags], ACPI_CHECKSUM_RSDP20
    call acpi_parse_rsdp
    call acpi_probe_mmio_devices

.done:
    popad
    ret

acpi_find_rsdp_in_range:
    push ebx
    push ecx
    push edx
    push esi
    shr ecx, 4

.next:
    test ecx, ecx
    jz .miss
    cmp dword [esi], ACPI_RSDP_SIG_LO
    jne .advance
    cmp dword [esi + 4], ACPI_RSDP_SIG_HI
    jne .advance
    call acpi_rsdp20_valid
    jnc .hit

.advance:
    add esi, 16
    dec ecx
    jmp .next

.hit:
    mov eax, esi
    clc
    jmp .done

.miss:
    stc

.done:
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

acpi_rsdp20_valid:
    push eax
    push ecx
    push esi
    cmp dword [esi], ACPI_RSDP_SIG_LO
    jne .bad
    cmp dword [esi + 4], ACPI_RSDP_SIG_HI
    jne .bad
    mov ecx, ACPI_RSDP_BASE_BYTES
    call acpi_checksum8
    test al, al
    jnz .bad
    clc
    jmp .done

.bad:
    stc

.done:
    pop esi
    pop ecx
    pop eax
    ret

acpi_parse_rsdp:
    pushad
    mov byte [acpi_status], ACPI_STATUS_BAD
    mov dword [acpi_rsdp_length], ACPI_RSDP_BASE_BYTES
    movzx eax, byte [esi + ACPI_RSDP_REVISION_OFF]
    mov [acpi_revision], eax
    mov eax, [esi + ACPI_RSDP_RSDT_OFF]
    mov [acpi_rsdt_addr], eax

    cmp byte [esi + ACPI_RSDP_REVISION_OFF], 2
    jb .try_rsdt
    mov eax, [esi + ACPI_RSDP_LENGTH_OFF]
    mov [acpi_rsdp_length], eax
    cmp eax, ACPI_RSDP_EXT_MIN_BYTES
    jb .try_rsdt
    cmp eax, ACPI_RSDP_MAX_BYTES
    ja .try_rsdt
    push esi
    mov ecx, eax
    call acpi_checksum8
    pop esi
    test al, al
    jnz .try_rsdt
    or dword [acpi_checksum_flags], ACPI_CHECKSUM_RSDP_EXT
    mov eax, [esi + ACPI_RSDP_XSDT_OFF]
    mov [acpi_xsdt_addr_low], eax
    mov eax, [esi + ACPI_RSDP_XSDT_HIGH_OFF]
    mov [acpi_xsdt_addr_high], eax
    cmp dword [acpi_xsdt_addr_high], 0
    jne .try_rsdt
    mov esi, [acpi_xsdt_addr_low]
    test esi, esi
    jz .try_rsdt
    mov edx, ACPI_SDT_SIG_XSDT
    call acpi_validate_sdt
    jc .try_rsdt
    or dword [acpi_checksum_flags], ACPI_CHECKSUM_XSDT
    mov [acpi_selected_sdt_addr], esi
    mov byte [acpi_root_kind], ACPI_ROOT_XSDT
    call acpi_parse_xsdt_entries
    call acpi_parse_device_tables
    mov byte [acpi_status], ACPI_STATUS_OK
    jmp .done

.try_rsdt:
    mov esi, [acpi_rsdt_addr]
    test esi, esi
    jz .done
    mov edx, ACPI_SDT_SIG_RSDT
    call acpi_validate_sdt
    jc .done
    or dword [acpi_checksum_flags], ACPI_CHECKSUM_RSDT
    mov [acpi_selected_sdt_addr], esi
    mov byte [acpi_root_kind], ACPI_ROOT_RSDT
    call acpi_parse_rsdt_entries
    call acpi_parse_device_tables
    mov byte [acpi_status], ACPI_STATUS_OK

.done:
    popad
    ret

acpi_validate_sdt:
    push eax
    push ebx
    push esi
    mov eax, esi
    mov ecx, ACPI_SDT_HEADER_BYTES
    call acpi_identity_map_range
    jc .bad
    test edx, edx
    jz .signature_ok
    cmp [esi], edx
    jne .bad

.signature_ok:
    mov ecx, [esi + ACPI_SDT_LENGTH_OFF]
    cmp ecx, ACPI_SDT_HEADER_BYTES
    jb .bad
    cmp ecx, ACPI_MAX_TABLE_BYTES
    ja .bad
    mov eax, esi
    add eax, ecx
    jc .bad
    mov eax, esi
    call acpi_identity_map_range
    jc .bad
    push ecx
    call acpi_checksum8
    pop ecx
    test al, al
    jnz .bad
    clc
    jmp .done

.bad:
    stc

.done:
    pop esi
    pop ebx
    pop eax
    ret

acpi_identity_map_range:
    push eax
    push ebx
    push ecx
    push edx
    test ecx, ecx
    jz .ok
    mov [acpi_last_map_length], ecx
    mov ebx, eax
    and ebx, 0xfffff000
    mov edx, eax
    add edx, ecx
    jc .fail
    dec edx
    and edx, 0xfffff000
    cmp edx, ACPI_MAX_MAPPED_PHYS
    jae .fail

.map_next:
    mov eax, ebx
    call vmm_identity_page
    jc .fail
    mov [acpi_last_mapped_page], ebx
    inc dword [acpi_mapped_pages]
    cmp ebx, edx
    je .ok
    add ebx, PAGE_SIZE
    jc .fail
    jmp .map_next

.ok:
    clc
    jmp .done

.fail:
    inc dword [acpi_map_failures]
    stc

.done:
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

acpi_parse_rsdt_entries:
    pushad
    mov eax, [esi + ACPI_SDT_LENGTH_OFF]
    sub eax, ACPI_SDT_HEADER_BYTES
    shr eax, 2
    mov [acpi_root_entry_count], eax
    lea edi, [esi + ACPI_SDT_HEADER_BYTES]
    mov ecx, eax

.next:
    test ecx, ecx
    jz .done
    mov ebx, [edi]
    add edi, 4
    call acpi_record_sdt_entry
    dec ecx
    jmp .next

.done:
    popad
    ret

acpi_parse_xsdt_entries:
    pushad
    mov eax, [esi + ACPI_SDT_LENGTH_OFF]
    sub eax, ACPI_SDT_HEADER_BYTES
    shr eax, 3
    mov [acpi_root_entry_count], eax
    lea edi, [esi + ACPI_SDT_HEADER_BYTES]
    mov ecx, eax

.next:
    test ecx, ecx
    jz .done
    mov ebx, [edi]
    cmp dword [edi + 4], 0
    jne .skip
    call acpi_record_sdt_entry

.skip:
    add edi, 8
    dec ecx
    jmp .next

.done:
    popad
    ret

acpi_record_sdt_entry:
    pushad
    test ebx, ebx
    jz .done
    mov esi, ebx
    mov edx, 0
    call acpi_validate_sdt
    jc .done
    inc dword [acpi_valid_sdt_count]
    mov eax, [esi]
    cmp eax, ACPI_SDT_SIG_APIC
    jne .check_hpet
    mov [acpi_madt_addr], esi
    jmp .done

.check_hpet:
    cmp eax, ACPI_SDT_SIG_HPET
    jne .done
    mov [acpi_hpet_addr], esi

.done:
    popad
    ret

acpi_parse_device_tables:
    pushad
    cmp dword [acpi_madt_addr], 0
    je .hpet
    call acpi_parse_madt_table

.hpet:
    cmp dword [acpi_hpet_addr], 0
    je .done
    call acpi_parse_hpet_table

.done:
    popad
    ret

acpi_parse_madt_table:
    pushad
    mov byte [acpi_madt_parse_status], ACPI_STATUS_BAD
    mov esi, [acpi_madt_addr]
    test esi, esi
    jz .done
    mov eax, esi
    mov ecx, ACPI_MADT_ENTRIES_OFF
    call acpi_identity_map_range
    jc .done
    mov ecx, [esi + ACPI_SDT_LENGTH_OFF]
    cmp ecx, ACPI_MADT_ENTRIES_OFF
    jb .done
    mov eax, esi
    call acpi_identity_map_range
    jc .done
    mov eax, [esi + ACPI_MADT_LAPIC_ADDR_OFF]
    mov [acpi_madt_lapic_addr], eax
    mov eax, [esi + ACPI_MADT_FLAGS_OFF]
    mov [acpi_madt_flags], eax
    lea edi, [esi + ACPI_MADT_ENTRIES_OFF]
    lea edx, [esi + ecx]
    mov [acpi_madt_end_ptr], edx

.next_entry:
    cmp edi, [acpi_madt_end_ptr]
    jae .ok
    movzx ecx, byte [edi + 1]
    cmp ecx, ACPI_MADT_ENTRY_HEADER_BYTES
    jb .done
    mov eax, edi
    add eax, ecx
    jc .done
    cmp eax, [acpi_madt_end_ptr]
    ja .done
    inc dword [acpi_madt_entry_count]
    movzx eax, byte [edi]
    cmp eax, ACPI_MADT_TYPE_LOCAL_APIC
    je .local_apic
    cmp eax, ACPI_MADT_TYPE_IO_APIC
    je .io_apic
    cmp eax, ACPI_MADT_TYPE_INTERRUPT_OVERRIDE
    je .interrupt_override
    cmp eax, ACPI_MADT_TYPE_LOCAL_APIC_NMI
    je .local_apic_nmi
    cmp eax, ACPI_MADT_TYPE_LAPIC_ADDR_OVERRIDE
    je .lapic_override
    jmp .advance

.local_apic:
    cmp ecx, ACPI_MADT_LOCAL_APIC_MIN_BYTES
    jb .advance
    cmp dword [acpi_lapic_count], 0
    jne .local_apic_count
    movzx eax, byte [edi + 2]
    mov [acpi_lapic_first_uid], eax
    movzx eax, byte [edi + 3]
    mov [acpi_lapic_first_id], eax

.local_apic_count:
    inc dword [acpi_lapic_count]
    test dword [edi + 4], ACPI_MADT_LOCAL_APIC_ENABLED
    jz .advance
    inc dword [acpi_lapic_enabled_count]
    jmp .advance

.io_apic:
    cmp ecx, ACPI_MADT_IO_APIC_MIN_BYTES
    jb .advance
    cmp dword [acpi_ioapic_count], 0
    jne .io_apic_count
    movzx eax, byte [edi + 2]
    mov [acpi_ioapic_first_id], eax
    mov eax, [edi + 4]
    mov [acpi_ioapic_first_addr], eax
    mov eax, [edi + 8]
    mov [acpi_ioapic_first_gsi_base], eax

.io_apic_count:
    inc dword [acpi_ioapic_count]
    jmp .advance

.interrupt_override:
    cmp ecx, ACPI_MADT_ISO_MIN_BYTES
    jb .advance
    cmp dword [acpi_iso_count], 0
    jne .interrupt_override_count
    movzx eax, byte [edi + 2]
    mov [acpi_iso_first_bus], eax
    movzx eax, byte [edi + 3]
    mov [acpi_iso_first_source], eax
    mov eax, [edi + 4]
    mov [acpi_iso_first_gsi], eax
    movzx eax, word [edi + 8]
    mov [acpi_iso_first_flags], eax

.interrupt_override_count:
    inc dword [acpi_iso_count]
    jmp .advance

.local_apic_nmi:
    cmp ecx, ACPI_MADT_LAPIC_NMI_MIN_BYTES
    jb .advance
    inc dword [acpi_lapic_nmi_count]
    jmp .advance

.lapic_override:
    cmp ecx, ACPI_MADT_LAPIC_OVERRIDE_MIN_BYTES
    jb .advance
    cmp dword [acpi_lapic_override_count], 0
    jne .lapic_override_count
    mov eax, [edi + 4]
    mov [acpi_lapic_override_low], eax
    mov eax, [edi + 8]
    mov [acpi_lapic_override_high], eax

.lapic_override_count:
    inc dword [acpi_lapic_override_count]

.advance:
    add edi, ecx
    jmp .next_entry

.ok:
    mov byte [acpi_madt_parse_status], ACPI_STATUS_OK

.done:
    popad
    ret

acpi_parse_hpet_table:
    pushad
    mov byte [acpi_hpet_parse_status], ACPI_STATUS_BAD
    mov esi, [acpi_hpet_addr]
    test esi, esi
    jz .done
    mov eax, esi
    mov ecx, ACPI_HPET_MIN_BYTES
    call acpi_identity_map_range
    jc .done
    cmp dword [esi + ACPI_SDT_LENGTH_OFF], ACPI_HPET_MIN_BYTES
    jb .done
    mov eax, [esi + ACPI_HPET_BLOCK_ID_OFF]
    mov [acpi_hpet_block_id], eax
    movzx eax, byte [esi + ACPI_HPET_GAS_SPACE_OFF]
    mov ebx, eax
    movzx eax, byte [esi + ACPI_HPET_GAS_WIDTH_OFF]
    shl eax, 8
    or ebx, eax
    movzx eax, byte [esi + ACPI_HPET_GAS_ACCESS_OFF]
    shl eax, 16
    or ebx, eax
    mov [acpi_hpet_gas_info], ebx
    mov eax, [esi + ACPI_HPET_GAS_ADDR_LOW_OFF]
    mov [acpi_hpet_addr_low], eax
    mov eax, [esi + ACPI_HPET_GAS_ADDR_HIGH_OFF]
    mov [acpi_hpet_addr_high], eax
    movzx eax, byte [esi + ACPI_HPET_NUMBER_OFF]
    mov [acpi_hpet_number], eax
    movzx eax, word [esi + ACPI_HPET_MIN_TICK_OFF]
    mov [acpi_hpet_min_tick], eax
    movzx eax, byte [esi + ACPI_HPET_PAGE_PROT_OFF]
    mov [acpi_hpet_page_prot], eax
    mov byte [acpi_hpet_parse_status], ACPI_STATUS_OK

.done:
    popad
    ret

acpi_probe_mmio_devices:
    pushad
    cmp byte [acpi_madt_parse_status], ACPI_STATUS_OK
    jne .hpet
    cmp dword [acpi_lapic_count], 0
    je .ioapic
    call acpi_probe_lapic_mmio

.ioapic:
    cmp dword [acpi_ioapic_count], 0
    je .hpet
    call acpi_probe_ioapic_mmio

.hpet:
    cmp byte [acpi_hpet_parse_status], ACPI_STATUS_OK
    jne .done
    call acpi_probe_hpet_mmio
    call hpet_clock_init

.done:
    call irq_build_route_plan
    call irq_build_ioapic_program_plan
    call ioapic_arm_masked_program_plan
    call lapic_enable_software
%ifndef VIBE_DISABLE_APIC_IRQ
    call apic_enable_irq_controller_live
%endif
    popad
    ret

irq_build_route_plan:
    pushad
    mov byte [irq_route_status], IRQ_ROUTE_STATUS_BAD
    mov dword [irq_route_count], IRQ_ROUTE_LEGACY_COUNT
    mov dword [irq_route_iso_hits], 0
    mov dword [irq_route_timer_gsi], IRQ_LEGACY_TIMER
    mov dword [irq_route_keyboard_gsi], IRQ_LEGACY_KEYBOARD
    mov dword [irq_route_audio_gsi], IRQ_LEGACY_AUDIO
    mov dword [irq_route_mouse_gsi], IRQ_LEGACY_MOUSE
    mov dword [irq_route_ide_primary_gsi], IRQ_LEGACY_IDE_PRIMARY
    mov dword [irq_route_timer_flags], 0
    mov dword [irq_route_keyboard_flags], 0
    mov dword [irq_route_audio_flags], 0
    mov dword [irq_route_mouse_flags], 0
    mov dword [irq_route_ide_primary_flags], 0

    cmp byte [acpi_madt_parse_status], ACPI_STATUS_OK
    jne .done
    cmp dword [acpi_ioapic_count], 0
    je .done
    cmp dword [acpi_lapic_enabled_count], 0
    je .done
    cmp byte [ioapic_redir_status], MMIO_PROBE_OK
    jne .done

    cmp dword [acpi_iso_count], 0
    je .ready
    mov eax, [acpi_iso_first_source]
    mov ebx, [acpi_iso_first_gsi]
    mov ecx, [acpi_iso_first_flags]
    or ecx, IRQ_ROUTE_FLAG_ISO
    call irq_apply_iso_route

.ready:
    mov byte [irq_route_status], IRQ_ROUTE_STATUS_READY

.done:
    popad
    ret

irq_apply_iso_route:
    cmp eax, IRQ_LEGACY_TIMER
    je .timer
    cmp eax, IRQ_LEGACY_KEYBOARD
    je .keyboard
    cmp eax, IRQ_LEGACY_AUDIO
    je .audio
    cmp eax, IRQ_LEGACY_MOUSE
    je .mouse
    cmp eax, IRQ_LEGACY_IDE_PRIMARY
    je .ide
    ret

.timer:
    mov [irq_route_timer_gsi], ebx
    mov [irq_route_timer_flags], ecx
    inc dword [irq_route_iso_hits]
    ret

.keyboard:
    mov [irq_route_keyboard_gsi], ebx
    mov [irq_route_keyboard_flags], ecx
    inc dword [irq_route_iso_hits]
    ret

.audio:
    mov [irq_route_audio_gsi], ebx
    mov [irq_route_audio_flags], ecx
    inc dword [irq_route_iso_hits]
    ret

.mouse:
    mov [irq_route_mouse_gsi], ebx
    mov [irq_route_mouse_flags], ecx
    inc dword [irq_route_iso_hits]
    ret

.ide:
    mov [irq_route_ide_primary_gsi], ebx
    mov [irq_route_ide_primary_flags], ecx
    inc dword [irq_route_iso_hits]
    ret

irq_build_ioapic_program_plan:
    pushad
    mov byte [ioapic_program_status], IRQ_IOAPIC_PROGRAM_STATUS_BAD
    mov dword [ioapic_program_route_count], 0
    mov dword [ioapic_program_dest_id], 0
    mov dword [ioapic_program_last_index], 0xffffffff
    mov dword [ioapic_plan_timer_index], 0xffffffff
    mov dword [ioapic_plan_keyboard_index], 0xffffffff
    mov dword [ioapic_plan_audio_index], 0xffffffff
    mov dword [ioapic_plan_mouse_index], 0xffffffff
    mov dword [ioapic_plan_ide_primary_index], 0xffffffff
    mov dword [ioapic_plan_timer_low], 0
    mov dword [ioapic_plan_keyboard_low], 0
    mov dword [ioapic_plan_audio_low], 0
    mov dword [ioapic_plan_mouse_low], 0
    mov dword [ioapic_plan_ide_primary_low], 0
    mov dword [ioapic_plan_timer_high], 0
    mov dword [ioapic_plan_keyboard_high], 0
    mov dword [ioapic_plan_audio_high], 0
    mov dword [ioapic_plan_mouse_high], 0
    mov dword [ioapic_plan_ide_primary_high], 0

    cmp byte [irq_route_status], IRQ_ROUTE_STATUS_READY
    jne .done
    cmp byte [lapic_mmio_status], MMIO_PROBE_OK
    jne .done
    cmp byte [ioapic_mmio_status], MMIO_PROBE_OK
    jne .done

    mov eax, [lapic_mmio_id]
    shr eax, 24
    and eax, 0xff
    mov [ioapic_program_dest_id], eax

    mov eax, [irq_route_timer_gsi]
    mov ebx, IRQ_VECTOR_TIMER
    mov ecx, [irq_route_timer_flags]
    call irq_make_ioapic_redir_entry
    jc .done
    mov [ioapic_plan_timer_low], eax
    mov [ioapic_plan_timer_high], edx
    mov eax, [ioapic_program_last_index]
    mov [ioapic_plan_timer_index], eax
    inc dword [ioapic_program_route_count]

    mov eax, [irq_route_keyboard_gsi]
    mov ebx, IRQ_VECTOR_KEYBOARD
    mov ecx, [irq_route_keyboard_flags]
    call irq_make_ioapic_redir_entry
    jc .done
    mov [ioapic_plan_keyboard_low], eax
    mov [ioapic_plan_keyboard_high], edx
    mov eax, [ioapic_program_last_index]
    mov [ioapic_plan_keyboard_index], eax
    inc dword [ioapic_program_route_count]

    mov eax, [irq_route_audio_gsi]
    mov ebx, IRQ_VECTOR_AUDIO
    mov ecx, [irq_route_audio_flags]
    call irq_make_ioapic_redir_entry
    jc .done
    mov [ioapic_plan_audio_low], eax
    mov [ioapic_plan_audio_high], edx
    mov eax, [ioapic_program_last_index]
    mov [ioapic_plan_audio_index], eax
    inc dword [ioapic_program_route_count]

    mov eax, [irq_route_mouse_gsi]
    mov ebx, IRQ_VECTOR_MOUSE
    mov ecx, [irq_route_mouse_flags]
    call irq_make_ioapic_redir_entry
    jc .done
    mov [ioapic_plan_mouse_low], eax
    mov [ioapic_plan_mouse_high], edx
    mov eax, [ioapic_program_last_index]
    mov [ioapic_plan_mouse_index], eax
    inc dword [ioapic_program_route_count]

    mov eax, [irq_route_ide_primary_gsi]
    mov ebx, IRQ_VECTOR_IDE_PRIMARY
    mov ecx, [irq_route_ide_primary_flags]
    call irq_make_ioapic_redir_entry
    jc .done
    mov [ioapic_plan_ide_primary_low], eax
    mov [ioapic_plan_ide_primary_high], edx
    mov eax, [ioapic_program_last_index]
    mov [ioapic_plan_ide_primary_index], eax
    inc dword [ioapic_program_route_count]

    mov byte [ioapic_program_status], IRQ_IOAPIC_PROGRAM_STATUS_READY

.done:
    popad
    ret

ioapic_arm_masked_program_plan:
    pushad
    mov byte [ioapic_masked_arm_status], IRQ_IOAPIC_ARM_STATUS_BAD
    mov dword [ioapic_masked_arm_route_count], 0
    mov dword [ioapic_masked_arm_match_count], 0
    mov dword [ioapic_masked_arm_last_index], 0xffffffff
    mov dword [ioapic_masked_arm_expected_low], 0
    mov dword [ioapic_masked_arm_expected_high], 0
    mov dword [ioapic_masked_arm_read_low], 0
    mov dword [ioapic_masked_arm_read_high], 0

    cmp byte [ioapic_program_status], IRQ_IOAPIC_PROGRAM_STATUS_READY
    jne .done
    cmp byte [ioapic_mmio_status], MMIO_PROBE_OK
    jne .done

    mov eax, [ioapic_plan_timer_index]
    mov ebx, [ioapic_plan_timer_low]
    mov ecx, [ioapic_plan_timer_high]
    call ioapic_arm_one_masked_entry
    jc .done
    inc dword [ioapic_masked_arm_route_count]
    inc dword [ioapic_masked_arm_match_count]

    mov eax, [ioapic_plan_keyboard_index]
    mov ebx, [ioapic_plan_keyboard_low]
    mov ecx, [ioapic_plan_keyboard_high]
    call ioapic_arm_one_masked_entry
    jc .done
    inc dword [ioapic_masked_arm_route_count]
    inc dword [ioapic_masked_arm_match_count]

    mov eax, [ioapic_plan_audio_index]
    mov ebx, [ioapic_plan_audio_low]
    mov ecx, [ioapic_plan_audio_high]
    call ioapic_arm_one_masked_entry
    jc .done
    inc dword [ioapic_masked_arm_route_count]
    inc dword [ioapic_masked_arm_match_count]

    mov eax, [ioapic_plan_mouse_index]
    mov ebx, [ioapic_plan_mouse_low]
    mov ecx, [ioapic_plan_mouse_high]
    call ioapic_arm_one_masked_entry
    jc .done
    inc dword [ioapic_masked_arm_route_count]
    inc dword [ioapic_masked_arm_match_count]

    mov eax, [ioapic_plan_ide_primary_index]
    mov ebx, [ioapic_plan_ide_primary_low]
    mov ecx, [ioapic_plan_ide_primary_high]
    call ioapic_arm_one_masked_entry
    jc .done
    inc dword [ioapic_masked_arm_route_count]
    inc dword [ioapic_masked_arm_match_count]

    mov byte [ioapic_masked_arm_status], IRQ_IOAPIC_ARM_STATUS_READY

.done:
    popad
    ret

ioapic_arm_one_masked_entry:
    cmp eax, 0xffffffff
    je .fail
    cmp eax, [ioapic_redir_entry_count]
    jae .fail
    mov [ioapic_masked_arm_last_index], eax
    or ebx, IOAPIC_REDIR_MASKED
    mov [ioapic_masked_arm_expected_low], ebx
    mov [ioapic_masked_arm_expected_high], ecx
    call ioapic_write_redir_entry
    jc .fail
    mov eax, [ioapic_masked_arm_last_index]
    call ioapic_read_redir_entry
    jc .fail
    mov [ioapic_masked_arm_read_low], eax
    mov [ioapic_masked_arm_read_high], edx
    cmp eax, [ioapic_masked_arm_expected_low]
    jne .fail
    cmp edx, [ioapic_masked_arm_expected_high]
    jne .fail
    clc
    ret

.fail:
    stc
    ret

apic_enable_irq_controller_live:
    pushad
    mov byte [apic_irq_status], APIC_IRQ_STATUS_NONE
    mov dword [apic_irq_route_count], 0
    mov dword [apic_irq_match_count], 0
    mov dword [apic_irq_last_index], 0xffffffff
    mov dword [apic_irq_expected_low], 0
    mov dword [apic_irq_expected_high], 0
    mov dword [apic_irq_read_low], 0
    mov dword [apic_irq_read_high], 0

    cmp byte [lapic_live_status], LAPIC_LIVE_STATUS_READY
    jne .done
    cmp byte [ioapic_masked_arm_status], IRQ_IOAPIC_ARM_STATUS_READY
    jne .done
    mov byte [apic_irq_status], APIC_IRQ_STATUS_BAD

    mov eax, [ioapic_plan_timer_index]
    mov ebx, [ioapic_plan_timer_low]
    mov ecx, [ioapic_plan_timer_high]
    call apic_arm_one_live_entry
    jc .done
    inc dword [apic_irq_route_count]
    inc dword [apic_irq_match_count]

    mov eax, [ioapic_plan_keyboard_index]
    mov ebx, [ioapic_plan_keyboard_low]
    mov ecx, [ioapic_plan_keyboard_high]
    call apic_arm_one_live_entry
    jc .done
    inc dword [apic_irq_route_count]
    inc dword [apic_irq_match_count]

    mov eax, [ioapic_plan_audio_index]
    mov ebx, [ioapic_plan_audio_low]
    mov ecx, [ioapic_plan_audio_high]
    call apic_arm_one_live_entry
    jc .done
    inc dword [apic_irq_route_count]
    inc dword [apic_irq_match_count]

    mov eax, [ioapic_plan_mouse_index]
    mov ebx, [ioapic_plan_mouse_low]
    mov ecx, [ioapic_plan_mouse_high]
    call apic_arm_one_live_entry
    jc .done
    inc dword [apic_irq_route_count]
    inc dword [apic_irq_match_count]

    mov eax, [ioapic_plan_ide_primary_index]
    mov ebx, [ioapic_plan_ide_primary_low]
    mov ecx, [ioapic_plan_ide_primary_high]
    call apic_arm_one_live_entry
    jc .done
    inc dword [apic_irq_route_count]
    inc dword [apic_irq_match_count]

    call pic_mask_all
    mov dword [irq_controller_mode], IRQ_CONTROLLER_APIC
    mov byte [apic_irq_status], APIC_IRQ_STATUS_READY

.done:
    popad
    ret

apic_arm_one_live_entry:
    cmp eax, 0xffffffff
    je .fail
    cmp eax, [ioapic_redir_entry_count]
    jae .fail
    mov [apic_irq_last_index], eax
    mov [apic_irq_expected_low], ebx
    mov [apic_irq_expected_high], ecx
    call ioapic_write_redir_entry
    jc .fail
    mov eax, [apic_irq_last_index]
    call ioapic_read_redir_entry
    jc .fail
    mov [apic_irq_read_low], eax
    mov [apic_irq_read_high], edx
    cmp eax, [apic_irq_expected_low]
    jne .fail
    cmp edx, [apic_irq_expected_high]
    jne .fail
    clc
    ret

.fail:
    stc
    ret

ioapic_write_redir_entry:
    push edx
    push esi
    cmp eax, [ioapic_redir_entry_count]
    jae .fail
    mov esi, [ioapic_mmio_addr]
    test esi, esi
    jz .fail
    mov edx, eax
    shl edx, 1
    add edx, IOAPIC_REG_REDIR_BASE
    inc edx
    mov [esi + IOAPIC_REGSEL], edx
    mov [esi + IOAPIC_WINDOW], ecx
    dec edx
    mov [esi + IOAPIC_REGSEL], edx
    mov [esi + IOAPIC_WINDOW], ebx
    clc
    jmp .done

.fail:
    stc

.done:
    pop esi
    pop edx
    ret

irq_make_ioapic_redir_entry:
    cmp eax, [acpi_ioapic_first_gsi_base]
    jb .fail
    sub eax, [acpi_ioapic_first_gsi_base]
    cmp eax, [ioapic_redir_entry_count]
    jae .fail
    mov [ioapic_program_last_index], eax

    mov eax, ebx
    and eax, 0x000000ff
    push ecx
    and ecx, IRQ_ROUTE_ACPI_FLAGS_MASK
    mov ebx, ecx
    and ebx, 0x00000003
    cmp ebx, 0x00000003
    jne .trigger
    or eax, IOAPIC_REDIR_POLARITY_LOW

.trigger:
    mov ebx, ecx
    shr ebx, 2
    and ebx, 0x00000003
    cmp ebx, 0x00000003
    jne .dest
    or eax, IOAPIC_REDIR_TRIGGER_LEVEL

.dest:
    pop ecx
    mov edx, [ioapic_program_dest_id]
    and edx, 0x000000ff
    shl edx, 24
    clc
    ret

.fail:
    stc
    ret

mmio_identity_map_page:
    push ebx
    push ecx
    mov ebx, eax
    mov ecx, PTE_KERNEL_MMIO_FLAGS
    call vmm_map_page
    jc .done
    call mmio_install_process_dirs
    clc

.done:
    pop ecx
    pop ebx
    ret

mmio_install_process_dirs:
    push eax
    push ebx
    push edx
    push edi

    and eax, 0xfffff000
    mov edx, eax
    shr edx, 22
    mov edi, PAGING_DIR_ADDR
    mov ebx, [edi + edx * 4]
    test ebx, PTE_PRESENT
    jz .done

    mov [mmio_last_pde_index], edx
    mov [mmio_last_pde_entry], ebx
    inc dword [mmio_process_pde_installs]

    mov edi, PROC_PROBE_PAGE_DIR_ADDR
    mov [edi + edx * 4], ebx
    mov edi, PROC_PREEMPT_PAGE_DIR_ADDR
    mov [edi + edx * 4], ebx
    mov edi, PROC_PAYLOAD_PAGE_DIR_ADDR
    mov [edi + edx * 4], ebx
    mov edi, PROC_GENERIC0_PAGE_DIR_ADDR
    mov [edi + edx * 4], ebx
    mov edi, PROC_GENERIC1_PAGE_DIR_ADDR
    mov [edi + edx * 4], ebx
    mov edi, PROC_GENERIC2_PAGE_DIR_ADDR
    mov [edi + edx * 4], ebx

.done:
    pop edi
    pop edx
    pop ebx
    pop eax
    ret

acpi_probe_lapic_mmio:
    pushad
    mov byte [lapic_mmio_status], MMIO_PROBE_BAD
    mov eax, [acpi_madt_lapic_addr]
    cmp dword [acpi_lapic_override_count], 0
    je .have_addr
    cmp dword [acpi_lapic_override_high], 0
    jne .done
    mov eax, [acpi_lapic_override_low]

.have_addr:
    test eax, eax
    jz .done
    mov [lapic_mmio_addr], eax
    call mmio_identity_map_page
    jc .done
    mov esi, [lapic_mmio_addr]
    mov eax, [esi + LAPIC_REG_ID]
    mov [lapic_mmio_id], eax
    mov eax, [esi + LAPIC_REG_VERSION]
    mov [lapic_mmio_version], eax
    mov eax, [esi + LAPIC_REG_SPURIOUS]
    mov [lapic_mmio_spurious], eax
    mov byte [lapic_mmio_status], MMIO_PROBE_OK

.done:
    popad
    ret

lapic_enable_software:
    pushad
    mov byte [lapic_live_status], LAPIC_LIVE_STATUS_BAD
    mov dword [lapic_live_svr_before], 0
    mov dword [lapic_live_svr_written], 0
    mov dword [lapic_live_svr_after], 0

    cmp byte [cpu_feature_status], CPU_FEATURE_STATUS_READY
    jne .done
    mov eax, [cpu_cpuid_features_edx]
    test eax, CPUID_FEATURE_APIC
    jz .done
    test eax, CPUID_FEATURE_MSR
    jz .done
    mov eax, [cpu_apic_base_flags]
    test eax, IA32_APIC_BASE_ENABLE
    jz .done
    cmp byte [lapic_mmio_status], MMIO_PROBE_OK
    jne .done
    mov esi, [lapic_mmio_addr]
    test esi, esi
    jz .done

    mov eax, [esi + LAPIC_REG_SPURIOUS]
    mov [lapic_live_svr_before], eax
    mov ebx, eax
    and ebx, 0xffffff00
    or ebx, LAPIC_SPURIOUS_ENABLE | LAPIC_SPURIOUS_VECTOR
    mov [lapic_live_svr_written], ebx
    mov [esi + LAPIC_REG_SPURIOUS], ebx
    mov eax, [esi + LAPIC_REG_SPURIOUS]
    mov [lapic_live_svr_after], eax
    mov edx, eax
    and edx, 0x000001ff
    mov ecx, ebx
    and ecx, 0x000001ff
    cmp edx, ecx
    jne .done
    mov byte [lapic_live_status], LAPIC_LIVE_STATUS_READY

.done:
    popad
    ret

acpi_probe_ioapic_mmio:
    pushad
    mov byte [ioapic_mmio_status], MMIO_PROBE_BAD
    mov eax, [acpi_ioapic_first_addr]
    test eax, eax
    jz .done
    mov [ioapic_mmio_addr], eax
    call mmio_identity_map_page
    jc .done
    mov esi, [ioapic_mmio_addr]
    mov dword [esi + IOAPIC_REGSEL], IOAPIC_REG_ID
    mov eax, [esi + IOAPIC_WINDOW]
    mov [ioapic_mmio_id], eax
    mov dword [esi + IOAPIC_REGSEL], IOAPIC_REG_VERSION
    mov eax, [esi + IOAPIC_WINDOW]
    mov [ioapic_mmio_version], eax
    call acpi_probe_ioapic_redirection
    mov byte [ioapic_mmio_status], MMIO_PROBE_OK

.done:
    popad
    ret

acpi_probe_ioapic_redirection:
    pushad
    mov byte [ioapic_redir_status], MMIO_PROBE_BAD
    mov eax, [ioapic_mmio_version]
    shr eax, 16
    and eax, 0x000000ff
    inc eax
    mov [ioapic_redir_entry_count], eax
    xor eax, eax
    call ioapic_read_redir_entry
    jc .done
    mov [ioapic_redir_gsi0_low], eax
    mov [ioapic_redir_gsi0_high], edx
    cmp dword [acpi_iso_count], 0
    je .ok
    mov eax, [acpi_iso_first_gsi]
    mov [ioapic_redir_iso_gsi], eax
    sub eax, [acpi_ioapic_first_gsi_base]
    jc .ok
    mov [ioapic_redir_iso_index], eax
    call ioapic_read_redir_entry
    jc .ok
    mov [ioapic_redir_iso_low], eax
    mov [ioapic_redir_iso_high], edx

.ok:
    mov byte [ioapic_redir_status], MMIO_PROBE_OK

.done:
    popad
    ret

ioapic_read_redir_entry:
    push ebx
    push ecx
    push esi
    cmp eax, [ioapic_redir_entry_count]
    jae .fail
    mov esi, [ioapic_mmio_addr]
    test esi, esi
    jz .fail
    mov ebx, eax
    shl ebx, 1
    add ebx, IOAPIC_REG_REDIR_BASE
    mov [esi + IOAPIC_REGSEL], ebx
    mov ecx, [esi + IOAPIC_WINDOW]
    inc ebx
    mov [esi + IOAPIC_REGSEL], ebx
    mov edx, [esi + IOAPIC_WINDOW]
    mov eax, ecx
    clc
    jmp .done

.fail:
    stc

.done:
    pop esi
    pop ecx
    pop ebx
    ret

acpi_probe_hpet_mmio:
    pushad
    mov byte [hpet_mmio_status], MMIO_PROBE_BAD
    cmp dword [acpi_hpet_addr_high], 0
    jne .done
    mov eax, [acpi_hpet_gas_info]
    and eax, 0x000000ff
    cmp eax, HPET_GAS_SYSTEM_MEMORY
    jne .done
    mov eax, [acpi_hpet_addr_low]
    test eax, eax
    jz .done
    mov [hpet_mmio_addr], eax
    call mmio_identity_map_page
    jc .done
    mov esi, [hpet_mmio_addr]
    mov eax, [esi + HPET_REG_GENERAL_CAP_ID]
    mov [hpet_mmio_cap_low], eax
    mov eax, [esi + HPET_REG_GENERAL_CAP_ID + 4]
    mov [hpet_mmio_cap_high], eax
    call acpi_probe_hpet_counter
    mov byte [hpet_mmio_status], MMIO_PROBE_OK

.done:
    popad
    ret

acpi_probe_hpet_counter:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    mov byte [hpet_counter_status], MMIO_PROBE_BAD
    mov eax, [esi + HPET_REG_GENERAL_CONFIG]
    mov [hpet_counter_config], eax
    mov ebx, eax
    or eax, HPET_CONFIG_ENABLE
    mov [esi + HPET_REG_GENERAL_CONFIG], eax
    mov eax, [esi + HPET_REG_MAIN_COUNTER]
    mov [hpet_counter_start_low], eax
    mov ecx, HPET_COUNTER_SPIN_READS

.spin:
    mov edx, [esi + HPET_REG_MAIN_COUNTER]
    loop .spin

    mov [hpet_counter_end_low], edx
    mov eax, edx
    sub eax, [hpet_counter_start_low]
    mov [hpet_counter_delta_low], eax
    test eax, eax
    jz .restore
    mov byte [hpet_counter_status], MMIO_PROBE_OK

.restore:
    test ebx, HPET_CONFIG_ENABLE
    jnz .done
    mov [esi + HPET_REG_GENERAL_CONFIG], ebx

.done:
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

hpet_refresh_live_counter:
    pushad
    cmp byte [hpet_live_status], MMIO_PROBE_NONE
    je .sample
    mov eax, [timer_ticks]
    sub eax, [hpet_live_last_tick]
    cmp eax, CLOCK_MONOTONIC_HZ
    jb .done

.sample:
    mov byte [hpet_live_status], MMIO_PROBE_BAD
    cmp byte [hpet_mmio_status], MMIO_PROBE_OK
    jne .done
    mov esi, [hpet_mmio_addr]
    test esi, esi
    jz .done
    mov eax, [esi + HPET_REG_GENERAL_CONFIG]
    mov [hpet_live_config], eax
    mov ebx, eax
    or eax, HPET_CONFIG_ENABLE
    mov [esi + HPET_REG_GENERAL_CONFIG], eax
    mov ecx, HPET_LIVE_SPIN_READS

.spin:
    mov eax, [esi + HPET_REG_MAIN_COUNTER]
    loop .spin

    mov [hpet_live_current_low], eax
    mov edx, eax
    sub edx, [hpet_counter_end_low]
    mov [hpet_live_delta_low], edx
    mov eax, [hpet_mmio_cap_high]
    mov [hpet_live_period_fs], eax
    mov eax, [timer_ticks]
    mov [hpet_live_last_tick], eax
    mov byte [hpet_live_status], MMIO_PROBE_OK
    test ebx, HPET_CONFIG_ENABLE
    jnz .done
    mov [esi + HPET_REG_GENERAL_CONFIG], ebx

.done:
    popad
    ret

hpet_clock_init:
    pushad
    mov byte [hpet_clock_status], HPET_CLOCK_STATUS_BAD
    mov dword [hpet_clock_ticks_per_ms], 0
    mov dword [hpet_clock_last_counter_low], 0
    mov dword [hpet_clock_last_delta], 0
    mov dword [hpet_clock_last_ms], 0
    mov dword [hpet_clock_remainder_ticks], 0
    mov dword [hpet_clock_sample_count], 0
    cmp byte [hpet_counter_status], MMIO_PROBE_OK
    jne .done
    cmp byte [hpet_mmio_status], MMIO_PROBE_OK
    jne .done
    mov esi, [hpet_mmio_addr]
    test esi, esi
    jz .done
    mov ecx, [hpet_mmio_cap_high]
    test ecx, ecx
    jz .done
    cmp ecx, HPET_FS_PER_MS_HIGH
    jbe .done
    mov eax, HPET_FS_PER_MS_LOW
    mov edx, HPET_FS_PER_MS_HIGH
    div ecx
    test eax, eax
    jz .done
    mov [hpet_clock_ticks_per_ms], eax
    mov eax, [esi + HPET_REG_GENERAL_CONFIG]
    or eax, HPET_CONFIG_ENABLE
    mov [esi + HPET_REG_GENERAL_CONFIG], eax
    mov [hpet_live_config], eax
    mov eax, [esi + HPET_REG_MAIN_COUNTER]
    mov [hpet_clock_last_counter_low], eax
    mov [hpet_live_current_low], eax
    mov eax, [hpet_mmio_cap_high]
    mov [hpet_live_period_fs], eax
    mov byte [hpet_clock_status], HPET_CLOCK_STATUS_READY
    mov byte [clock_source_status], CLOCK_STATUS_HPET_MONOTONIC

.done:
    popad
    ret

hpet_clock_update_from_counter:
    push ebx
    push ecx
    push edx
    push esi
    cmp byte [hpet_clock_status], HPET_CLOCK_STATUS_READY
    jne .fail
    mov esi, [hpet_mmio_addr]
    test esi, esi
    jz .fail
    mov eax, [esi + HPET_REG_MAIN_COUNTER]
    mov [hpet_live_current_low], eax
    mov ebx, eax
    sub ebx, [hpet_clock_last_counter_low]
    mov [hpet_clock_last_counter_low], eax
    mov [hpet_clock_last_delta], ebx
    add ebx, [hpet_clock_remainder_ticks]
    jc .fail
    mov eax, ebx
    xor edx, edx
    mov ecx, [hpet_clock_ticks_per_ms]
    test ecx, ecx
    jz .fail
    div ecx
    mov [hpet_clock_remainder_ticks], edx
    mov [hpet_clock_last_ms], eax
    add [clock_milliseconds], eax
    inc dword [hpet_clock_sample_count]
    mov byte [hpet_live_status], MMIO_PROBE_OK
    mov eax, [hpet_mmio_cap_high]
    mov [hpet_live_period_fs], eax
    clc
    jmp .done

.fail:
    stc

.done:
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

acpi_checksum8:
    xor eax, eax

.next:
    test ecx, ecx
    jz .done
    add al, [esi]
    inc esi
    dec ecx
    jmp .next

.done:
    ret

shutdown_report_status:
    push esi

    mov esi, shutdown_report_prefix
    call print_string
    cmp dword [shutdown_state], SHUTDOWN_HALT
    je .halt
    cmp dword [shutdown_state], SHUTDOWN_REBOOT
    je .reboot
    cmp dword [shutdown_state], SHUTDOWN_POWEROFF
    je .poweroff
    mov esi, smoke_none_text
    jmp .write

.halt:
    mov esi, smoke_halt_text
    jmp .write

.reboot:
    mov esi, smoke_reboot_text
    jmp .write

.poweroff:
    mov esi, smoke_poweroff_text

.write:
    call print_string
    call newline
    pop esi
    ret

read_cmos_seconds:
    mov al, CMOS_RTC_SECONDS_REGISTER
    out CMOS_INDEX_PORT, al
    call io_wait
    in al, CMOS_DATA_PORT
    ret

shutdown_proof_wait_before_guest_exit:
    cli
    call read_cmos_seconds
    mov bl, al
    mov ecx, SHUTDOWN_PROOF_DELAY_SECONDS

.wait_next_second:
    call read_cmos_seconds
    cmp al, bl
    je .wait_next_second
    mov bl, al
    loop .wait_next_second
    ret

skip_spaces:
    cmp byte [esi], ' '
    jne .done
    inc esi
    jmp skip_spaces

.done:
    ret

match_exact:
    push ebx

.loop:
    mov al, [edi]
    cmp al, 0
    je .check_tail
    mov bl, [esi]
    cmp bl, al
    jne .no
    inc esi
    inc edi
    jmp .loop

.check_tail:
    mov bl, [esi]
    cmp bl, 0
    je .yes
    cmp bl, ' '
    jne .no
    inc esi
    jmp .check_tail

.yes:
    mov al, 1
    pop ebx
    ret

.no:
    xor al, al
    pop ebx
    ret

starts_with_word:
    push edx

.loop:
    mov al, [edi]
    cmp al, 0
    je .word_end
    cmp [esi], al
    jne .no
    inc esi
    inc edi
    jmp .loop

.word_end:
    mov dl, [esi]
    cmp dl, 0
    je .yes
    cmp dl, ' '
    jne .no

.skip_argument_spaces:
    cmp byte [esi], ' '
    jne .yes
    inc esi
    jmp .skip_argument_spaces

.yes:
    mov ebx, esi
    mov al, 1
    pop edx
    ret

.no:
    xor al, al
    pop edx
    ret

clear_screen:
    push eax
    push ecx
    push edi

    mov edi, VGA_BUFFER
    mov ax, (VGA_ATTR << 8) | ' '
    mov ecx, VGA_COLS * VGA_ROWS

.clear_next:
    mov [edi], ax
    add edi, 2
    loop .clear_next

    mov dword [cursor_row], 0
    mov dword [cursor_col], 0
    call update_cursor

    pop edi
    pop ecx
    pop eax
    ret

newline:
    call vga_newline
    ret

print_string:
    push eax

.next:
    lodsb
    test al, al
    jz .done
    call put_char
    jmp .next

.done:
    pop eax
    ret

put_char:
    call debug_output_char
    cmp al, 13
    je .done
    cmp al, 10
    je .newline
    cmp al, 8
    je .backspace

    call vga_put_visible
    ret

.newline:
    call vga_newline
    ret

.backspace:
    call vga_backspace

.done:
    ret

serial_debug_init:
    push eax
    push edx

    mov dx, SERIAL_COM1_IER
    xor al, al
    out dx, al
    mov dx, SERIAL_COM1_LCR
    mov al, SERIAL_LCR_DLAB
    out dx, al
    mov dx, SERIAL_COM1_DATA
    mov al, 3
    out dx, al
    mov dx, SERIAL_COM1_IER
    xor al, al
    out dx, al
    mov dx, SERIAL_COM1_LCR
    mov al, SERIAL_LCR_8N1
    out dx, al
    mov dx, SERIAL_COM1_FCR
    mov al, SERIAL_FCR_ENABLE_CLEAR
    out dx, al
    mov dx, SERIAL_COM1_MCR
    mov al, SERIAL_MCR_DTR_RTS_OUT2
    out dx, al

    pop edx
    pop eax
    ret

debug_output_char:
    push eax
    push ecx
    push edx
    call debugcon_write_char
    call serial_write_char
    pop edx
    pop ecx
    pop eax
    ret

debugcon_write_char:
    push edx
    mov dx, DEBUGCON_PORT
    out dx, al
    pop edx
    ret

serial_write_char:
    push eax
    push ecx
    push edx

    mov ah, al
    mov dx, SERIAL_COM1_LSR
    mov ecx, SERIAL_POLL_LIMIT

.wait_ready:
    in al, dx
    test al, SERIAL_LSR_THR_EMPTY
    jnz .ready
    loop .wait_ready
    jmp .done

.ready:
    mov dx, SERIAL_COM1_DATA
    mov al, ah
    out dx, al

.done:
    pop edx
    pop ecx
    pop eax
    ret

vga_put_visible:
    push eax
    push ebx
    push edi

    mov ebx, [cursor_row]
    imul ebx, VGA_COLS
    add ebx, [cursor_col]
    shl ebx, 1
    mov edi, VGA_BUFFER
    add edi, ebx
    mov ah, VGA_ATTR
    mov [edi], ax

    inc dword [cursor_col]
    cmp dword [cursor_col], VGA_COLS
    jb .update
    call vga_newline
    jmp .done

.update:
    call update_cursor

.done:
    pop edi
    pop ebx
    pop eax
    ret

vga_newline:
    push eax
    mov dword [cursor_col], 0
    inc dword [cursor_row]
    cmp dword [cursor_row], VGA_ROWS
    jb .update
    call vga_scroll
    mov dword [cursor_row], VGA_ROWS - 1

.update:
    call update_cursor
    pop eax
    ret

vga_backspace:
    push eax
    push ebx
    push edi

    cmp dword [cursor_col], 0
    jne .move_left
    cmp dword [cursor_row], 0
    je .done
    dec dword [cursor_row]
    mov dword [cursor_col], VGA_COLS

.move_left:
    dec dword [cursor_col]
    mov ebx, [cursor_row]
    imul ebx, VGA_COLS
    add ebx, [cursor_col]
    shl ebx, 1
    mov edi, VGA_BUFFER
    add edi, ebx
    mov ax, (VGA_ATTR << 8) | ' '
    mov [edi], ax
    call update_cursor

.done:
    pop edi
    pop ebx
    pop eax
    ret

vga_scroll:
    push eax
    push ecx
    push esi
    push edi

    mov esi, VGA_BUFFER + (VGA_COLS * 2)
    mov edi, VGA_BUFFER
    mov ecx, (VGA_ROWS - 1) * VGA_COLS

.copy_next:
    mov ax, [esi]
    mov [edi], ax
    add esi, 2
    add edi, 2
    loop .copy_next

    mov edi, VGA_BUFFER + ((VGA_ROWS - 1) * VGA_COLS * 2)
    mov ax, (VGA_ATTR << 8) | ' '
    mov ecx, VGA_COLS

.clear_last_row:
    mov [edi], ax
    add edi, 2
    loop .clear_last_row

    pop edi
    pop esi
    pop ecx
    pop eax
    ret

update_cursor:
    ret

pic_remap_and_mask:
    mov al, 0x11
    out 0x20, al
    call io_wait
    out 0xa0, al
    call io_wait
    mov al, 0x20
    out 0x21, al
    call io_wait
    mov al, 0x28
    out 0xa1, al
    call io_wait
    mov al, 0x04
    out 0x21, al
    call io_wait
    mov al, 0x02
    out 0xa1, al
    call io_wait
    mov al, 0x01
    out 0x21, al
    call io_wait
    out 0xa1, al
    call io_wait
    mov al, 0xff
    out 0x21, al
    call io_wait
    out 0xa1, al
    call io_wait
    mov dword [irq_controller_mode], IRQ_CONTROLLER_PIC
    ret

pic_mask_all:
    mov al, 0xff
    out 0x21, al
    call io_wait
    out 0xa1, al
    call io_wait
    ret

pic_unmask_timer:
    mov al, 0xfe
    out 0x21, al
    call io_wait
    mov al, 0xff
    out 0xa1, al
    call io_wait
    ret

irq_unmask_timer:
    cmp dword [irq_controller_mode], IRQ_CONTROLLER_APIC
    je .apic
    call pic_unmask_timer
    ret

.apic:
    call pic_mask_all
    ret

pic_unmask_timer_keyboard:
    cmp byte [mouse_status], INPUT_DEVICE_STATUS_READY
    je .with_mouse
    cmp byte [audio_status], 1
    je .with_audio
    mov al, 0xfc
    out 0x21, al
    call io_wait
    mov al, 0xff
    out 0xa1, al
    call io_wait
    ret

.with_audio:
    mov al, 0xdc
    out 0x21, al
    call io_wait
    mov al, 0xff
    out 0xa1, al
    call io_wait
    ret

.with_mouse:
    cmp byte [audio_status], 1
    je .with_mouse_audio
    mov al, 0xf8
    out 0x21, al
    call io_wait
    mov al, 0xef
    out 0xa1, al
    call io_wait
    ret

.with_mouse_audio:
    mov al, 0xd8
    out 0x21, al
    call io_wait
    mov al, 0xef
    out 0xa1, al
    call io_wait
    ret

irq_unmask_timer_keyboard:
    cmp dword [irq_controller_mode], IRQ_CONTROLLER_APIC
    je .apic
    call pic_unmask_timer_keyboard
    ret

.apic:
    call pic_mask_all
    ret

io_wait:
    push eax
    xor al, al
    out 0x80, al
    pop eax
    ret

pci_scan_qemu:
    pushad

    mov byte [pci_config_status], 0
    mov byte [pci_table_api_status], 0
    mov byte [pci_table_consumer_status], 0
    mov dword [pci_probe_count], 0
    mov dword [pci_absent_count], 0
    mov dword [pci_function_count], 0
    mov dword [pci_table_count], 0
    mov dword [pci_table_overflow_count], 0
    mov dword [pci_highest_bus], 0
    mov dword [pci_first_bdf], 0
    mov dword [pci_first_id], 0
    mov dword [pci_first_class], 0
    mov dword [pci_last_bdf], 0
    mov dword [pci_class_table_hash], 0
    mov dword [pci_multifunction_device_count], 0
    mov dword [pci_mass_storage_class_count], 0
    mov dword [pci_bridge_class_count], 0
    mov dword [pci_pci_bridge_class_count], 0
    mov dword [pci_multimedia_class_count], 0
    mov dword [pci_bridge_bus_info], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_diag_flags], 0
    mov dword [pci_lookup_mass_storage_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_bridge_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_ide_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_ahci_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_audio_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_hda_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_first_id_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_miss_bdf], PCI_LOOKUP_NOT_FOUND

    mov edi, pci_device_table
    xor eax, eax
    mov ecx, PCI_TABLE_MAX_ENTRIES * PCI_TABLE_ENTRY_DWORDS
    rep stosd

    mov dword [pci_scan_bus_index], 0

.bus_loop:
    cmp dword [pci_scan_bus_index], PCI_SCAN_BUS_COUNT
    jae .done
    xor esi, esi

.device_loop:
    cmp esi, PCI_SCAN_DEVICE_COUNT
    jae .next_bus
    xor edi, edi

.function_loop:
    cmp edi, PCI_SCAN_FUNCTION_COUNT
    jae .next_device

    inc dword [pci_probe_count]
    mov eax, PCI_CONFIG_ENABLE
    mov ebx, [pci_scan_bus_index]
    shl ebx, 16
    or eax, ebx
    mov ebx, esi
    shl ebx, 11
    or eax, ebx
    mov ebx, edi
    shl ebx, 8
    or eax, ebx
    mov dx, PCI_CONFIG_ADDRESS
    out dx, eax
    mov dx, PCI_CONFIG_DATA
    in eax, dx
    cmp eax, 0xffffffff
    je .absent_function
    cmp ax, 0xffff
    je .absent_function

    mov ebp, eax

    mov eax, PCI_CONFIG_ENABLE
    mov ebx, [pci_scan_bus_index]
    shl ebx, 16
    or eax, ebx
    mov ebx, esi
    shl ebx, 11
    or eax, ebx
    mov ebx, edi
    shl ebx, 8
    or eax, ebx
    or eax, PCI_CONFIG_CLASS_REG
    mov dx, PCI_CONFIG_ADDRESS
    out dx, eax
    mov dx, PCI_CONFIG_DATA
    in eax, dx
    mov ecx, eax

    mov eax, PCI_CONFIG_ENABLE
    mov ebx, [pci_scan_bus_index]
    shl ebx, 16
    or eax, ebx
    mov ebx, esi
    shl ebx, 11
    or eax, ebx
    mov ebx, edi
    shl ebx, 8
    or eax, ebx
    or eax, PCI_CONFIG_HEADER_REG
    mov dx, PCI_CONFIG_ADDRESS
    out dx, eax
    mov dx, PCI_CONFIG_DATA
    in eax, dx
    mov ebx, eax

    mov edx, [pci_scan_bus_index]
    shl edx, 16
    mov eax, esi
    shl eax, 8
    or edx, eax
    or edx, edi

    mov eax, [pci_scan_bus_index]
    cmp eax, [pci_highest_bus]
    jbe .highest_bus_ok
    mov [pci_highest_bus], eax

.highest_bus_ok:
    mov eax, [pci_table_count]
    cmp eax, PCI_TABLE_MAX_ENTRIES
    jae .record_table_overflow
    shl eax, PCI_TABLE_ENTRY_SHIFT
    mov [pci_device_table + eax + PCI_TABLE_LOCATION_OFFSET], edx
    mov [pci_device_table + eax + PCI_TABLE_VENDOR_DEVICE_OFFSET], ebp
    mov [pci_device_table + eax + PCI_TABLE_CLASS_OFFSET], ecx
    mov [pci_device_table + eax + PCI_TABLE_HEADER_OFFSET], ebx
    inc dword [pci_table_count]
    jmp .skip_table_store

.record_table_overflow:
    inc dword [pci_table_overflow_count]

.skip_table_store:
    cmp byte [pci_config_status], 1
    je .not_first_device
    mov byte [pci_config_status], 1
    mov [pci_first_id], ebp
    mov [pci_first_bdf], edx
    mov [pci_first_class], ecx

.not_first_device:
    mov [pci_last_bdf], edx

    mov eax, [pci_class_table_hash]
    rol eax, 5
    xor eax, edx
    xor eax, ebp
    xor eax, ecx
    xor eax, ebx
    mov [pci_class_table_hash], eax

    cmp edi, 0
    jne .skip_multifunction_count
    test ebx, PCI_HEADER_MULTIFUNCTION_FLAG
    jz .skip_multifunction_count
    inc dword [pci_multifunction_device_count]

.skip_multifunction_count:
    mov eax, ecx
    shr eax, 24
    cmp al, PCI_CLASS_MASS_STORAGE
    jne .not_mass_storage_class
    inc dword [pci_mass_storage_class_count]

.not_mass_storage_class:
    mov eax, ecx
    shr eax, 24
    cmp al, PCI_CLASS_BRIDGE
    jne .not_bridge_class
    inc dword [pci_bridge_class_count]
    mov eax, ecx
    shr eax, 16
    cmp al, PCI_SUBCLASS_PCI_BRIDGE
    jne .not_bridge_class
    inc dword [pci_pci_bridge_class_count]
    cmp dword [pci_bridge_bus_info], PCI_LOOKUP_NOT_FOUND
    jne .not_bridge_class
    push eax
    push ebx
    push ecx
    push edx
    mov eax, PCI_CONFIG_ENABLE
    mov ebx, [pci_scan_bus_index]
    shl ebx, 16
    or eax, ebx
    mov ebx, esi
    shl ebx, 11
    or eax, ebx
    mov ebx, edi
    shl ebx, 8
    or eax, ebx
    or eax, PCI_CONFIG_BRIDGE_BUS_REG
    mov dx, PCI_CONFIG_ADDRESS
    out dx, eax
    mov dx, PCI_CONFIG_DATA
    in eax, dx
    mov [pci_bridge_bus_info], eax
    pop edx
    pop ecx
    pop ebx
    pop eax

.not_bridge_class:
    mov eax, ecx
    shr eax, 24
    cmp al, PCI_CLASS_MULTIMEDIA
    jne .not_multimedia_class
    inc dword [pci_multimedia_class_count]

.not_multimedia_class:
    inc dword [pci_function_count]
    jmp .next_function

.absent_function:
    inc dword [pci_absent_count]

.next_function:
    inc edi
    jmp .function_loop

.next_device:
    inc esi
    jmp .device_loop

.next_bus:
    inc dword [pci_scan_bus_index]
    jmp .bus_loop

.done:
    mov eax, [pci_probe_count]
    cmp eax, PCI_SCAN_FUNCTION_PROBES
    jne .diag_table_bounded
    or dword [pci_diag_flags], PCI_DIAG_SCAN_COMPLETE

.diag_table_bounded:
    mov eax, [pci_table_count]
    cmp eax, PCI_TABLE_MAX_ENTRIES
    ja .diag_absent_counted
    or dword [pci_diag_flags], PCI_DIAG_TABLE_BOUNDED

.diag_absent_counted:
    mov eax, [pci_absent_count]
    add eax, [pci_function_count]
    cmp eax, [pci_probe_count]
    jne .disable_config_address
    or dword [pci_diag_flags], PCI_DIAG_ABSENT_COUNTED

.disable_config_address:
    xor eax, eax
    mov dx, PCI_CONFIG_ADDRESS
    out dx, eax
    or dword [pci_diag_flags], PCI_DIAG_CONFIG_DISABLED
    popad
    call pci_table_probe_lookup_contract
    ret

; Read-only PCI table API for future in-kernel drivers. Callers pass an index
; in eax and receive esi=entry with CF clear, or esi=0 with CF set.
pci_table_entry_by_index:
    cmp eax, [pci_table_count]
    jae .missing
    shl eax, PCI_TABLE_ENTRY_SHIFT
    lea esi, [pci_device_table + eax]
    clc
    ret

.missing:
    xor esi, esi
    stc
    ret

; Class lookup API. Inputs are al=class, ah=subclass, bl=prog-if; use
; PCI_LOOKUP_ANY for wildcard subclass/prog-if. On success CF is clear, esi
; points at the table entry, eax is the index, and edx is the packed BDF.
pci_table_find_first_by_class:
    push ebx
    push ecx
    push edi
    mov cl, al
    mov ch, ah
    mov dl, bl
    xor edi, edi

.entry_loop:
    cmp edi, [pci_table_count]
    jae .not_found
    mov esi, edi
    shl esi, PCI_TABLE_ENTRY_SHIFT
    add esi, pci_device_table
    mov eax, [esi + PCI_TABLE_CLASS_OFFSET]

    mov ebx, eax
    shr ebx, 24
    cmp cl, PCI_LOOKUP_ANY
    je .check_subclass
    cmp bl, cl
    jne .next_entry

.check_subclass:
    mov ebx, eax
    shr ebx, 16
    cmp ch, PCI_LOOKUP_ANY
    je .check_prog_if
    cmp bl, ch
    jne .next_entry

.check_prog_if:
    mov ebx, eax
    shr ebx, 8
    cmp dl, PCI_LOOKUP_ANY
    je .found
    cmp bl, dl
    jne .next_entry

.found:
    mov eax, edi
    mov edx, [esi + PCI_TABLE_LOCATION_OFFSET]
    pop edi
    pop ecx
    pop ebx
    clc
    ret

.next_entry:
    inc edi
    jmp .entry_loop

.not_found:
    xor esi, esi
    mov eax, PCI_LOOKUP_NOT_FOUND
    mov edx, PCI_LOOKUP_NOT_FOUND
    pop edi
    pop ecx
    pop ebx
    stc
    ret

; Vendor/device lookup API. Inputs are ax=vendor-id, bx=device-id; use
; PCI_LOOKUP_ID_ANY for either wildcard. On success CF is clear, esi points at
; the table entry, eax is the index, and edx is the packed BDF.
pci_table_find_first_by_id:
    push ebx
    push ecx
    push edi
    mov cx, ax
    mov dx, bx
    xor edi, edi

.entry_loop:
    cmp edi, [pci_table_count]
    jae .not_found
    mov esi, edi
    shl esi, PCI_TABLE_ENTRY_SHIFT
    add esi, pci_device_table
    mov eax, [esi + PCI_TABLE_VENDOR_DEVICE_OFFSET]

    mov ebx, eax
    and ebx, 0xffff
    cmp cx, PCI_LOOKUP_ID_ANY
    je .check_device
    cmp bx, cx
    jne .next_entry

.check_device:
    mov ebx, eax
    shr ebx, 16
    cmp dx, PCI_LOOKUP_ID_ANY
    je .found
    cmp bx, dx
    jne .next_entry

.found:
    mov eax, edi
    mov edx, [esi + PCI_TABLE_LOCATION_OFFSET]
    pop edi
    pop ecx
    pop ebx
    clc
    ret

.next_entry:
    inc edi
    jmp .entry_loop

.not_found:
    xor esi, esi
    mov eax, PCI_LOOKUP_NOT_FOUND
    mov edx, PCI_LOOKUP_NOT_FOUND
    pop edi
    pop ecx
    pop ebx
    stc
    ret

pci_config_read_dword_by_bdf:
    push ebx
    push ecx
    push edx
    mov ecx, eax
    mov eax, PCI_CONFIG_ENABLE
    mov edx, ecx
    and edx, 0x00ff0000
    or eax, edx
    mov edx, ecx
    and edx, 0x0000ff00
    shl edx, 3
    or eax, edx
    mov edx, ecx
    and edx, 0x000000ff
    shl edx, 8
    or eax, edx
    and ebx, 0xfc
    or eax, ebx
    mov dx, PCI_CONFIG_ADDRESS
    out dx, eax
    mov dx, PCI_CONFIG_DATA
    in eax, dx
    push eax
    xor eax, eax
    mov dx, PCI_CONFIG_ADDRESS
    out dx, eax
    pop eax
    pop edx
    pop ecx
    pop ebx
    ret

pci_table_probe_lookup_contract:
    pushad
    mov byte [pci_table_api_status], 0
    mov byte [pci_table_consumer_status], 0
    mov dword [pci_lookup_mass_storage_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_bridge_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_ide_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_ahci_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_audio_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_hda_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_first_id_bdf], PCI_LOOKUP_NOT_FOUND
    mov dword [pci_lookup_miss_bdf], 0

    mov eax, [pci_table_count]
    call pci_table_entry_by_index
    jnc .done
    test esi, esi
    jnz .done
    mov dword [pci_lookup_miss_bdf], PCI_LOOKUP_NOT_FOUND
    or dword [pci_diag_flags], PCI_DIAG_INDEX_GUARD

    cmp dword [pci_table_count], 0
    je .lookup_mass_storage
    mov eax, [pci_device_table + PCI_TABLE_VENDOR_DEVICE_OFFSET]
    mov ebx, eax
    shr ebx, 16
    call pci_table_find_first_by_id
    jc .lookup_mass_storage
    mov [pci_lookup_first_id_bdf], edx
    or dword [pci_diag_flags], PCI_DIAG_ID_LOOKUP

.lookup_mass_storage:
    mov al, PCI_CLASS_MASS_STORAGE
    mov ah, PCI_LOOKUP_ANY
    mov bl, PCI_LOOKUP_ANY
    call pci_table_find_first_by_class
    jc .lookup_bridge
    mov [pci_lookup_mass_storage_bdf], edx

.lookup_bridge:
    mov al, PCI_CLASS_BRIDGE
    mov ah, PCI_LOOKUP_ANY
    mov bl, PCI_LOOKUP_ANY
    call pci_table_find_first_by_class
    jc .lookup_ide
    mov [pci_lookup_bridge_bdf], edx

.lookup_ide:
    mov al, PCI_CLASS_MASS_STORAGE
    mov ah, PCI_SUBCLASS_IDE
    mov bl, PCI_LOOKUP_ANY
    call pci_table_find_first_by_class
    jc .lookup_ahci
    mov [pci_lookup_ide_bdf], edx

.lookup_ahci:
    mov al, PCI_CLASS_MASS_STORAGE
    mov ah, PCI_SUBCLASS_AHCI
    mov bl, PCI_PROGIF_AHCI
    call pci_table_find_first_by_class
    jc .lookup_audio
    mov [pci_lookup_ahci_bdf], edx

.lookup_audio:
    mov al, PCI_CLASS_MULTIMEDIA
    mov ah, PCI_SUBCLASS_AUDIO
    mov bl, PCI_LOOKUP_ANY
    call pci_table_find_first_by_class
    jc .lookup_hda
    mov [pci_lookup_audio_bdf], edx

.lookup_hda:
    mov al, PCI_CLASS_MULTIMEDIA
    mov ah, PCI_SUBCLASS_HDA
    mov bl, PCI_LOOKUP_ANY
    call pci_table_find_first_by_class
    jc .lookup_ok
    mov [pci_lookup_hda_bdf], edx

.lookup_ok:
    or dword [pci_diag_flags], PCI_DIAG_CLASS_LOOKUP
    mov byte [pci_table_api_status], 1
    mov byte [pci_table_consumer_status], 1

.done:
    popad
    ret

pit_init_100hz:
    call clock_init_pit_100hz
    mov al, 0x36
    out 0x43, al
    mov ax, PIT_DIVISOR_100HZ
    out 0x40, al
    mov al, ah
    out 0x40, al
    ret

clock_init_pit_100hz:
    mov byte [clock_source_status], CLOCK_STATUS_PIT_100HZ
    mov dword [timer_ticks], 0
    mov dword [clock_irq_count], 0
    mov dword [clock_milliseconds], 0
    mov dword [clock_compat35_ticks], 0
    mov dword [clock_compat35_remainder], 0
    mov dword [clock_scheduler_tick_count], 0
    mov dword [clock_scheduler_irq_switches], 0
    ret

clock_tick_from_timer_irq:
    inc dword [clock_irq_count]
    cmp byte [clock_source_status], CLOCK_STATUS_HPET_MONOTONIC
    jne .pit_milliseconds
    call hpet_clock_update_from_counter
    jnc .compat35_ticks

.pit_milliseconds:
    add dword [clock_milliseconds], CLOCK_TICK_MILLISECONDS

.compat35_ticks:
    add dword [clock_compat35_remainder], CLOCK_COMPAT_35HZ
    cmp dword [clock_compat35_remainder], CLOCK_MONOTONIC_HZ
    jb .done
    sub dword [clock_compat35_remainder], CLOCK_MONOTONIC_HZ
    inc dword [clock_compat35_ticks]

.done:
    ret

clock_note_scheduler_irq_path:
    push eax
    mov eax, [scheduler_tick_count]
    mov [clock_scheduler_tick_count], eax
    mov eax, [scheduler_irq_context_switches]
    mov [clock_scheduler_irq_switches], eax
    pop eax
    ret

clock_write_monotonic_time:
    mov eax, [timer_ticks]
    mov [edi + CLOCK_TIME_TICKS], eax
    mov dword [edi + CLOCK_TIME_FREQUENCY_HZ], CLOCK_MONOTONIC_HZ
    mov eax, [clock_milliseconds]
    mov [edi + CLOCK_TIME_MILLISECONDS], eax
    mov eax, CLOCK_TIME_FLAG_KERNEL_OWNED
    cmp byte [clock_source_status], CLOCK_STATUS_HPET_MONOTONIC
    jne .flags_ready
    or eax, CLOCK_TIME_FLAG_HPET_BACKED

.flags_ready:
    mov [edi + CLOCK_TIME_FLAGS], eax
    ret

cpu_tables_init:
    mov byte [cpu_table_status], CPU_TABLE_STATUS_UNKNOWN
    mov byte [cpu_gdt_status], CPU_TABLE_STATUS_UNKNOWN
    mov byte [cpu_idt_status], CPU_TABLE_STATUS_UNKNOWN
    mov byte [cpu_tss_status], CPU_TABLE_STATUS_UNKNOWN
    call gdt_init
    call idt_init
    lidt [idt_descriptor]
    mov byte [cpu_table_status], CPU_TABLE_STATUS_READY
    ret

gdt_init:
    mov dword [tss_esp0], KERNEL_STACK_TOP
    mov word [tss_ss0], DATA_SEG
    mov dword [cpu_tss_esp0_last], KERNEL_STACK_TOP
    mov word [cpu_tss_ss0_last], DATA_SEG

    mov eax, tss_start
    mov word [kernel_gdt_tss + 2], ax
    shr eax, 16
    mov byte [kernel_gdt_tss + 4], al
    mov byte [kernel_gdt_tss + 7], ah

    lgdt [kernel_gdt_descriptor]
    jmp CODE_SEG:.reload_cs

.reload_cs:
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    mov ss, ax
    mov ax, TSS_SEG
    ltr ax
    str ax
    mov [cpu_task_register_selector], ax
    mov word [cpu_kernel_cs_selector], CODE_SEG
    mov word [cpu_kernel_ds_selector], DATA_SEG
    mov word [cpu_user_cs_selector], USER_CODE_SEG
    mov word [cpu_user_ds_selector], USER_DATA_SEG
    mov word [cpu_tss_selector], TSS_SEG
    mov byte [cpu_gdt_status], CPU_TABLE_STATUS_READY
    mov byte [cpu_tss_status], CPU_TABLE_STATUS_READY
    ret

linux_tls_write_descriptor:
    mov [kernel_gdt_linux_tls + 2], ax
    shr eax, 16
    mov [kernel_gdt_linux_tls + 4], al
    mov [kernel_gdt_linux_tls + 7], ah
    ret

cpu_probe_features:
    pushad

    mov byte [cpu_feature_status], CPU_FEATURE_STATUS_UNKNOWN
    mov dword [cpu_cpuid_max_basic], 0
    mov dword [cpu_cpuid_vendor_ebx], 0
    mov dword [cpu_cpuid_vendor_edx], 0
    mov dword [cpu_cpuid_vendor_ecx], 0
    mov dword [cpu_cpuid_features_ecx], 0
    mov dword [cpu_cpuid_features_edx], 0
    mov dword [cpu_apic_base_msr_low], 0
    mov dword [cpu_apic_base_msr_high], 0
    mov dword [cpu_apic_base_addr], 0
    mov dword [cpu_apic_base_flags], 0

    pushfd
    pop eax
    mov esi, eax
    xor eax, EFLAGS_ID_BIT
    push eax
    popfd
    pushfd
    pop eax
    push esi
    popfd
    xor eax, esi
    test eax, EFLAGS_ID_BIT
    jz .no_cpuid

    xor eax, eax
    cpuid
    mov [cpu_cpuid_max_basic], eax
    mov [cpu_cpuid_vendor_ebx], ebx
    mov [cpu_cpuid_vendor_edx], edx
    mov [cpu_cpuid_vendor_ecx], ecx
    mov byte [cpu_feature_status], CPU_FEATURE_STATUS_READY

    cmp eax, 1
    jb .done
    mov eax, 1
    cpuid
    mov [cpu_cpuid_features_ecx], ecx
    mov [cpu_cpuid_features_edx], edx
    test edx, CPUID_FEATURE_MSR
    jz .done
    test edx, CPUID_FEATURE_APIC
    jz .done

    mov ecx, IA32_APIC_BASE_MSR
    rdmsr
    mov [cpu_apic_base_msr_low], eax
    mov [cpu_apic_base_msr_high], edx
    mov ebx, eax
    and ebx, IA32_APIC_BASE_ADDR_MASK
    mov [cpu_apic_base_addr], ebx
    and eax, 0x00000fff
    mov [cpu_apic_base_flags], eax
    jmp .done

.no_cpuid:
    mov byte [cpu_feature_status], CPU_FEATURE_STATUS_NO_CPUID

.done:
    popad
    ret

paging_init:
    pushad

    mov dword [vmm_static_page_tables], PAGING_TABLE_COUNT
    mov dword [vmm_dynamic_page_tables], 0
    mov dword [vmm_active_page_tables], PAGING_TABLE_COUNT
    mov dword [vmm_reclaimed_page_tables], 0
    mov dword [vmm_last_reclaimed_page_table], 0
    mov dword [vmm_user_guard_pages], 0
    mov dword [vmm_guard_probe_count], 0
    mov dword [vmm_guard_present_failures], 0
    mov byte [vmm_high_mapping_status], 0
    mov dword [vmm_high_test_phys], 0
    mov dword [vmm_high_test_table], 0
    mov dword [vmm_high_test_reclaimed], 0

    mov edi, PAGING_DIR_ADDR
    xor eax, eax
    mov ecx, 1024
    rep stosd

    mov edi, PAGING_TABLES_ADDR
    xor eax, eax
    mov ecx, PAGING_TOTAL_PAGES

.pte_next:
    mov ebx, eax
    shl ebx, 12
    or ebx, PTE_KERNEL_FLAGS
    mov [edi], ebx
    add edi, 4
    inc eax
    loop .pte_next

    mov edi, PAGING_DIR_ADDR
    mov eax, PAGING_TABLES_ADDR | PTE_KERNEL_FLAGS
    mov ecx, PAGING_TABLE_COUNT

.pde_next:
    mov [edi], eax
    add eax, PAGE_SIZE
    add edi, 4
    loop .pde_next

    call process_vm_init_page_spaces

    mov eax, PAGING_DIR_ADDR
    mov cr3, eax
    mov eax, cr0
    or eax, 0x80000000
    mov cr0, eax
    jmp short .flush

.flush:
    mov byte [paging_status], 1
    popad
    ret

kernel_relocation_probe:
    mov [kernel_relocation_esp], esp
    pushad

    mov eax, cr3
    mov [kernel_relocation_cr3], eax
    call .capture_eip

.capture_eip:
    pop eax
    mov [kernel_relocation_eip], eax
    mov eax, start
    mov [kernel_relocation_virt], eax
    call kernel_translate_current_vaddr
    mov [kernel_relocation_phys], eax
    call kernel_capture_low_identity_probe

    mov byte [kernel_relocation_status], KERNEL_RELOCATION_STATUS_MISMATCH
    mov eax, [kernel_relocation_eip]
    cmp eax, KERNEL_HIGHER_HALF_BASE
    jae .check_high_alias
    mov eax, [kernel_relocation_esp]
    cmp eax, KERNEL_HIGHER_HALF_BASE
    jae .done
    mov eax, [kernel_relocation_cr3]
    cmp eax, PAGING_DIR_ADDR
    jne .done
    mov eax, [kernel_relocation_phys]
    cmp eax, [kernel_relocation_virt]
    jne .done
    mov byte [kernel_relocation_status], KERNEL_RELOCATION_STATUS_LOW_IDENTITY
    jmp .done

.check_high_alias:
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_BASE
    jb .done
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_BASE + KERNEL_PERSISTENT_ALIAS_BYTES
    jae .done
    mov eax, [kernel_relocation_esp]
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_STACK_LOW
    jb .done
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_STACK_TOP
    jae .done
    mov eax, [kernel_relocation_cr3]
    cmp eax, PAGING_DIR_ADDR
    jne .done
    mov eax, [kernel_relocation_phys]
    cmp eax, start
    jne .done
    mov eax, KERNEL_HIGHER_HALF_BASE + start
    mov [kernel_relocation_virt], eax
    mov byte [kernel_relocation_status], KERNEL_RELOCATION_STATUS_HIGH_ALIAS

.done:
    popad
    ret

kernel_enter_persistent_high_mainline:
    cmp byte [kernel_persistent_alias_status], KERNEL_PERSISTENT_ALIAS_STATUS_OK
    jne .done
    cmp byte [kernel_persistent_exec_status], KERNEL_PERSISTENT_EXEC_STATUS_OK
    jne .done
    mov dword [idt_gate_offset_bias], KERNEL_HIGHER_HALF_BASE
    call idt_init
    lidt [idt_descriptor]
    mov dword [tss_esp0], KERNEL_HIGHER_HALF_BASE + KERNEL_STACK_TOP
    mov dword [cpu_tss_esp0_last], KERNEL_HIGHER_HALF_BASE + KERNEL_STACK_TOP
    mov byte [kernel_high_mainline_active], KERNEL_HIGH_MAINLINE_ACTIVE
    mov dword [kernel_high_mainline_abi_mask], 0
    mov dword [kernel_high_mainline_abi_last_op], 0
    mov dword [kernel_high_mainline_high_data_writes], 0
    mov dword [kernel_high_mainline_high_data_last_op], 0
    mov eax, KERNEL_HIGHER_HALF_BASE + kernel_mainline
    mov esp, KERNEL_HIGHER_HALF_BASE + KERNEL_STACK_TOP
    jmp eax

.done:
    ret

kernel_switch_main_stack_and_return:
    pop eax
    cmp byte [kernel_high_mainline_active], KERNEL_HIGH_MAINLINE_ACTIVE
    jne .low_stack
    mov esp, KERNEL_HIGHER_HALF_BASE + KERNEL_STACK_TOP
    jmp eax

.low_stack:
    mov esp, KERNEL_STACK_TOP
    jmp eax

kernel_high_mainline_entry_checkpoint:
    pushad
    call .capture_eip

.capture_eip:
    pop eax
    mov [kernel_high_mainline_entry_eip], eax
    mov [kernel_high_mainline_entry_esp], esp
    mov eax, KERNEL_HIGH_ABI_ENTRY_CHECKPOINT
    call kernel_high_mainline_record_abi
    call kernel_high_mainline_capture_entry_map
    call kernel_high_mainline_capture_common
    popad
    ret

kernel_high_mainline_late_checkpoint:
    pushad
    call .capture_eip

.capture_eip:
    pop eax
    mov [kernel_high_mainline_late_eip], eax
    mov [kernel_high_mainline_late_esp], esp
    mov eax, KERNEL_HIGH_ABI_LATE_CHECKPOINT
    call kernel_high_mainline_record_abi
    call kernel_high_mainline_capture_late_map
    call kernel_high_mainline_capture_common
    popad
    ret

kernel_high_mainline_record_abi:
    push edi
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_high_mainline_abi_mask
    or dword [edi], eax
    or dword [edi], KERNEL_HIGH_ABI_HIGH_DATA_WRITE
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_high_mainline_abi_last_op
    mov [edi], eax
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_high_mainline_high_data_writes
    inc dword [edi]
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_high_mainline_high_data_last_op
    mov [edi], eax
    pop edi
    ret

kernel_high_mainline_capture_entry_map:
    pushad

    mov eax, [kernel_high_mainline_entry_eip]
    call kernel_translate_current_vaddr
    mov [kernel_high_mainline_entry_xlat], eax
    mov eax, [kernel_translate_last_pde]
    mov [kernel_high_mainline_pde], eax
    mov eax, [kernel_translate_last_pte]
    mov [kernel_high_mainline_entry_pte], eax

    mov eax, [kernel_high_mainline_entry_esp]
    call kernel_translate_current_vaddr
    mov [kernel_high_mainline_entry_stack_xlat], eax
    mov eax, [kernel_translate_last_pte]
    mov [kernel_high_mainline_entry_stack_pte], eax

    call kernel_capture_low_identity_probe
    popad
    ret

kernel_high_mainline_capture_late_map:
    pushad

    mov eax, [kernel_high_mainline_late_eip]
    call kernel_translate_current_vaddr
    mov [kernel_high_mainline_late_xlat], eax
    mov eax, [kernel_translate_last_pde]
    mov [kernel_high_mainline_pde], eax
    mov eax, [kernel_translate_last_pte]
    mov [kernel_high_mainline_late_pte], eax

    mov eax, [kernel_high_mainline_late_esp]
    call kernel_translate_current_vaddr
    mov [kernel_high_mainline_late_stack_xlat], eax
    mov eax, [kernel_translate_last_pte]
    mov [kernel_high_mainline_late_stack_pte], eax

    call kernel_capture_low_identity_probe
    popad
    ret

kernel_high_mainline_capture_common:
    inc dword [kernel_high_mainline_checkpoints]
    mov eax, cr3
    mov [kernel_high_mainline_cr3], eax
    mov eax, [tss_esp0]
    mov [kernel_high_mainline_tss_esp0], eax
    mov eax, [idt_gate_offset_bias]
    mov [kernel_high_mainline_idt_bias], eax
    call kernel_high_mainline_validate
    ret

kernel_high_mainline_validate:
    mov byte [kernel_high_mainline_status], KERNEL_HIGH_MAINLINE_STATUS_FAIL

    cmp byte [kernel_high_mainline_active], KERNEL_HIGH_MAINLINE_ACTIVE
    jne .done
    cmp dword [kernel_high_mainline_checkpoints], 2
    jb .done
    cmp dword [kernel_high_mainline_idt_bias], KERNEL_HIGHER_HALF_BASE
    jne .done
    mov eax, KERNEL_HIGH_ABI_IDT_BIAS
    call kernel_high_mainline_record_abi
    cmp dword [kernel_high_mainline_tss_esp0], KERNEL_HIGHER_HALF_BASE + KERNEL_STACK_TOP
    jne .done
    mov eax, KERNEL_HIGH_ABI_TSS_ESP0
    call kernel_high_mainline_record_abi

    mov eax, [kernel_high_mainline_entry_eip]
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_BASE
    jb .done
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_BASE + KERNEL_PERSISTENT_ALIAS_BYTES
    jae .done

    mov eax, [kernel_high_mainline_late_eip]
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_BASE
    jb .done
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_BASE + KERNEL_PERSISTENT_ALIAS_BYTES
    jae .done
    cmp eax, [kernel_high_mainline_entry_eip]
    je .done
    mov eax, KERNEL_HIGH_ABI_HIGH_EIP
    call kernel_high_mainline_record_abi

    mov eax, [kernel_high_mainline_entry_esp]
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_STACK_LOW
    jb .done
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_STACK_TOP
    jae .done

    mov eax, [kernel_high_mainline_late_esp]
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_STACK_LOW
    jb .done
    cmp eax, KERNEL_HIGHER_HALF_BASE + KERNEL_STACK_TOP
    jae .done
    mov eax, KERNEL_HIGH_ABI_HIGH_ESP
    call kernel_high_mainline_record_abi

    mov eax, [kernel_high_mainline_cr3]
    cmp eax, PAGING_DIR_ADDR
    jne .done

    mov eax, [kernel_high_mainline_entry_xlat]
    cmp eax, 0xffffffff
    je .done
    mov ebx, [kernel_high_mainline_entry_eip]
    sub ebx, KERNEL_HIGHER_HALF_BASE
    cmp eax, ebx
    jne .done

    mov eax, [kernel_high_mainline_late_xlat]
    cmp eax, 0xffffffff
    je .done
    mov ebx, [kernel_high_mainline_late_eip]
    sub ebx, KERNEL_HIGHER_HALF_BASE
    cmp eax, ebx
    jne .done
    mov eax, KERNEL_HIGH_ABI_TEXT_XLAT
    call kernel_high_mainline_record_abi

    mov eax, [kernel_high_mainline_entry_stack_xlat]
    cmp eax, 0xffffffff
    je .done
    mov ebx, [kernel_high_mainline_entry_esp]
    sub ebx, KERNEL_HIGHER_HALF_BASE
    cmp eax, ebx
    jne .done

    mov eax, [kernel_high_mainline_late_stack_xlat]
    cmp eax, 0xffffffff
    je .done
    mov ebx, [kernel_high_mainline_late_esp]
    sub ebx, KERNEL_HIGHER_HALF_BASE
    cmp eax, ebx
    jne .done
    mov eax, KERNEL_HIGH_ABI_STACK_XLAT
    call kernel_high_mainline_record_abi

    mov eax, [kernel_high_mainline_pde]
    mov ebx, eax
    and ebx, PTE_KERNEL_FLAGS
    cmp ebx, PTE_KERNEL_FLAGS
    jne .done
    and eax, 0xfffff000
    cmp eax, [kernel_persistent_alias_table]
    jne .done

    mov eax, [kernel_high_mainline_entry_pte]
    mov ebx, [kernel_high_mainline_entry_xlat]
    call kernel_high_mainline_validate_pte
    jc .done
    mov eax, [kernel_high_mainline_late_pte]
    mov ebx, [kernel_high_mainline_late_xlat]
    call kernel_high_mainline_validate_pte
    jc .done
    mov eax, [kernel_high_mainline_entry_stack_pte]
    mov ebx, [kernel_high_mainline_entry_stack_xlat]
    call kernel_high_mainline_validate_pte
    jc .done
    mov eax, [kernel_high_mainline_late_stack_pte]
    mov ebx, [kernel_high_mainline_late_stack_xlat]
    call kernel_high_mainline_validate_pte
    jc .done
    mov eax, KERNEL_HIGH_ABI_PTE_CHECK
    call kernel_high_mainline_record_abi

    cmp dword [kernel_low_identity_policy], KERNEL_LOW_IDENTITY_PRESENT
    jne .done
    mov eax, [kernel_low_identity_vaddr]
    cmp eax, start
    jne .done
    mov eax, [kernel_low_identity_xlat]
    cmp eax, [kernel_low_identity_vaddr]
    jne .done
    mov eax, [kernel_low_identity_pte]
    test eax, PTE_PRESENT
    jz .done
    mov eax, KERNEL_HIGH_ABI_LOW_ID_RETAINED
    call kernel_high_mainline_record_abi

    mov byte [kernel_high_mainline_status], KERNEL_HIGH_MAINLINE_STATUS_OK

.done:
    ret

kernel_high_mainline_validate_pte:
    push ecx

    mov ecx, eax
    and ecx, PTE_KERNEL_FLAGS
    cmp ecx, PTE_KERNEL_FLAGS
    jne .fail
    and eax, 0xfffff000
    and ebx, 0xfffff000
    cmp eax, ebx
    jne .fail
    clc
    jmp .done

.fail:
    stc

.done:
    pop ecx
    ret

kernel_translate_current_vaddr:
    push ebx
    push ecx
    push edx
    push edi

    mov ebx, eax
    mov [kernel_translate_last_vaddr], eax
    mov dword [kernel_translate_last_pde], 0
    mov dword [kernel_translate_last_pte], 0
    mov edx, cr3
    and edx, 0xfffff000
    mov ecx, ebx
    shr ecx, 22
    lea edi, [edx + ecx * 4]
    mov edx, [edi]
    mov [kernel_translate_last_pde], edx
    test edx, PTE_PRESENT
    jz .missing

    and edx, 0xfffff000
    mov ecx, ebx
    shr ecx, 12
    and ecx, 0x000003ff
    lea edi, [edx + ecx * 4]
    mov edx, [edi]
    mov [kernel_translate_last_pte], edx
    test edx, PTE_PRESENT
    jz .missing

    mov eax, edx
    and eax, 0xfffff000
    and ebx, 0x00000fff
    add eax, ebx
    jmp .done

.missing:
    mov eax, 0xffffffff

.done:
    pop edi
    pop edx
    pop ecx
    pop ebx
    ret

kernel_translate_dir_vaddr:
    push ebx
    push ecx
    push edx
    push edi

    mov edi, eax
    and edi, 0xfffff000
    mov [kernel_translate_last_vaddr], ebx
    mov dword [kernel_translate_last_pde], 0
    mov dword [kernel_translate_last_pte], 0
    mov ecx, ebx
    shr ecx, 22
    lea edi, [edi + ecx * 4]
    mov edx, [edi]
    mov [kernel_translate_last_pde], edx
    test edx, PTE_PRESENT
    jz .missing

    and edx, 0xfffff000
    mov ecx, ebx
    shr ecx, 12
    and ecx, 0x000003ff
    lea edi, [edx + ecx * 4]
    mov edx, [edi]
    mov [kernel_translate_last_pte], edx
    test edx, PTE_PRESENT
    jz .missing

    mov eax, edx
    and eax, 0xfffff000
    and ebx, 0x00000fff
    add eax, ebx
    jmp .done

.missing:
    mov eax, 0xffffffff

.done:
    pop edi
    pop edx
    pop ecx
    pop ebx
    ret

kernel_capture_low_identity_probe:
    pushad

    mov eax, start
    and eax, 0xfffff000
    mov [kernel_low_identity_vaddr], eax
    call kernel_translate_current_vaddr
    mov [kernel_low_identity_xlat], eax
    mov eax, [kernel_translate_last_pte]
    mov [kernel_low_identity_pte], eax
    mov dword [kernel_low_identity_policy], KERNEL_LOW_IDENTITY_TRAPPED
    cmp dword [kernel_low_identity_xlat], 0xffffffff
    je .done
    test dword [kernel_low_identity_pte], PTE_PRESENT
    jz .done
    mov dword [kernel_low_identity_policy], KERNEL_LOW_IDENTITY_PRESENT

.done:
    popad
    ret

kernel_relocation_dir_self_test:
    pushad

    mov byte [kernel_relocation_dir_status], KERNEL_RELOCATION_DIR_STATUS_FAIL
    mov byte [kernel_relocation_live_status], KERNEL_RELOCATION_LIVE_STATUS_FAIL
    mov dword [kernel_relocation_dir_addr], 0
    mov dword [kernel_relocation_dir_high_pde], 0
    mov dword [kernel_relocation_dir_low_pde], 0
    mov dword [kernel_relocation_dir_entry_xlat], 0
    mov dword [kernel_relocation_dir_stack_xlat], 0
    mov dword [kernel_relocation_dir_low_xlat], 0
    mov dword [kernel_relocation_dir_entry_pte], 0
    mov dword [kernel_relocation_dir_stack_pte], 0
    mov dword [kernel_relocation_dir_low_pte], 0
    mov dword [kernel_relocation_abi_mask], 0
    mov dword [kernel_relocation_abi_last_op], 0
    call kernel_relocation_live_clear

    cmp byte [kernel_persistent_alias_status], KERNEL_PERSISTENT_ALIAS_STATUS_OK
    jne .done
    cmp byte [kernel_persistent_exec_status], KERNEL_PERSISTENT_EXEC_STATUS_OK
    jne .done

    call pmm_alloc_page
    test eax, eax
    jz .done
    mov [kernel_relocation_dir_addr], eax

    mov edi, eax
    xor eax, eax
    mov ecx, 1024
    cld
    rep stosd

    mov eax, [PAGING_DIR_ADDR + (KERNEL_HIGHER_HALF_PDE_INDEX * 4)]
    mov [kernel_relocation_dir_high_pde], eax
    test eax, PTE_PRESENT
    jz .done
    mov edi, [kernel_relocation_dir_addr]
    mov [edi + (KERNEL_HIGHER_HALF_PDE_INDEX * 4)], eax
    mov eax, [edi]
    mov [kernel_relocation_dir_low_pde], eax
    test eax, PTE_PRESENT
    jnz .done

    mov eax, [kernel_relocation_dir_addr]
    mov ebx, [kernel_persistent_alias_vaddr]
    call kernel_translate_dir_vaddr
    mov [kernel_relocation_dir_entry_xlat], eax
    mov eax, [kernel_translate_last_pte]
    mov [kernel_relocation_dir_entry_pte], eax

    mov eax, [kernel_relocation_dir_addr]
    mov ebx, [kernel_persistent_stack_vaddr]
    call kernel_translate_dir_vaddr
    mov [kernel_relocation_dir_stack_xlat], eax
    mov eax, [kernel_translate_last_pte]
    mov [kernel_relocation_dir_stack_pte], eax

    mov eax, [kernel_relocation_dir_addr]
    mov ebx, start
    and ebx, 0xfffff000
    call kernel_translate_dir_vaddr
    mov [kernel_relocation_dir_low_xlat], eax
    mov eax, [kernel_translate_last_pte]
    mov [kernel_relocation_dir_low_pte], eax

    call kernel_relocation_dir_validate
    jc .done
    mov byte [kernel_relocation_dir_status], KERNEL_RELOCATION_DIR_STATUS_OK
    call kernel_relocation_live_switch_self_test

.done:
    popad
    ret

kernel_relocation_record_abi:
    or [kernel_relocation_abi_mask], eax
    mov [kernel_relocation_abi_last_op], eax
    ret

kernel_relocation_dir_validate:
    push eax
    push ebx

    mov eax, [kernel_relocation_dir_addr]
    cmp eax, PMM_MANAGED_START
    jb .fail
    cmp eax, [pmm_managed_end]
    jae .fail
    test eax, 0x00000fff
    jnz .fail
    cmp eax, PAGING_DIR_ADDR
    je .fail
    cmp eax, PROC_PROBE_PAGE_DIR_ADDR
    je .fail
    cmp eax, PROC_PAYLOAD_PAGE_DIR_ADDR
    je .fail
    cmp eax, PROC_PREEMPT_PAGE_DIR_ADDR
    je .fail
    cmp eax, PROC_GENERIC0_PAGE_DIR_ADDR
    je .fail
    cmp eax, PROC_GENERIC1_PAGE_DIR_ADDR
    je .fail
    cmp eax, PROC_GENERIC2_PAGE_DIR_ADDR
    je .fail
    mov eax, KERNEL_RELOC_ABI_DIR_ALLOC
    call kernel_relocation_record_abi

    mov eax, [kernel_relocation_dir_high_pde]
    mov ebx, eax
    and ebx, PTE_KERNEL_FLAGS
    cmp ebx, PTE_KERNEL_FLAGS
    jne .fail
    and eax, 0xfffff000
    cmp eax, [kernel_persistent_alias_table]
    jne .fail
    mov eax, KERNEL_RELOC_ABI_HIGH_PDE
    call kernel_relocation_record_abi

    mov eax, [kernel_relocation_dir_low_pde]
    test eax, PTE_PRESENT
    jnz .fail
    mov eax, KERNEL_RELOC_ABI_LOW_PDE_ABSENT
    call kernel_relocation_record_abi

    mov eax, [kernel_relocation_dir_entry_xlat]
    cmp eax, [kernel_persistent_alias_phys]
    jne .fail
    mov eax, KERNEL_RELOC_ABI_TEXT_XLAT
    call kernel_relocation_record_abi
    mov eax, [kernel_relocation_dir_stack_xlat]
    cmp eax, [kernel_persistent_stack_phys]
    jne .fail
    mov eax, KERNEL_RELOC_ABI_STACK_XLAT
    call kernel_relocation_record_abi
    mov eax, [kernel_relocation_dir_low_xlat]
    cmp eax, 0xffffffff
    jne .fail

    mov eax, [kernel_relocation_dir_entry_pte]
    mov ebx, [kernel_relocation_dir_entry_xlat]
    call kernel_high_mainline_validate_pte
    jc .fail
    mov eax, [kernel_relocation_dir_stack_pte]
    mov ebx, [kernel_relocation_dir_stack_xlat]
    call kernel_high_mainline_validate_pte
    jc .fail
    mov eax, [kernel_relocation_dir_low_pte]
    test eax, PTE_PRESENT
    jnz .fail
    mov eax, KERNEL_RELOC_ABI_LOW_XLAT_ABSENT
    call kernel_relocation_record_abi

    clc
    jmp .done

.fail:
    stc

.done:
    pop ebx
    pop eax
    ret

kernel_relocation_live_clear:
    pushad

    mov byte [kernel_relocation_live_status], KERNEL_RELOCATION_LIVE_STATUS_FAIL
    mov dword [kernel_relocation_live_eip], 0
    mov dword [kernel_relocation_live_esp], 0
    mov dword [kernel_relocation_live_cr3], 0
    mov dword [kernel_relocation_live_return_cr3], 0
    mov dword [kernel_relocation_live_code_vaddr], 0
    mov dword [kernel_relocation_live_code_phys], 0
    mov dword [kernel_relocation_live_stack_vaddr], 0
    mov dword [kernel_relocation_live_stack_phys], 0
    mov dword [kernel_relocation_live_data_vaddr], 0
    mov dword [kernel_relocation_live_data_phys], 0
    mov dword [kernel_relocation_live_code_xlat], 0
    mov dword [kernel_relocation_live_stack_xlat], 0
    mov dword [kernel_relocation_live_data_xlat], 0
    mov dword [kernel_relocation_live_low_xlat], 0
    mov dword [kernel_relocation_live_return_vaddr], 0
    mov dword [kernel_relocation_live_return_xlat], 0
    mov dword [kernel_relocation_live_expected_return], 0
    mov dword [kernel_relocation_live_magic], 0
    mov dword [kernel_relocation_live_saved_low_esp], 0

    popad
    ret

kernel_relocation_live_switch_self_test:
    pushad

    call kernel_relocation_live_clear
    mov [kernel_relocation_live_saved_low_esp], esp

    cmp byte [kernel_relocation_dir_status], KERNEL_RELOCATION_DIR_STATUS_OK
    jne .done

    mov eax, kernel_relocation_live_switch_trampoline
    and eax, 0xfffff000
    mov [kernel_relocation_live_code_phys], eax
    add eax, KERNEL_HIGHER_HALF_BASE
    mov [kernel_relocation_live_code_vaddr], eax
    mov ebx, eax
    mov eax, [kernel_relocation_dir_addr]
    call kernel_translate_dir_vaddr
    mov [kernel_relocation_live_code_xlat], eax
    cmp eax, [kernel_relocation_live_code_phys]
    jne .done

    mov eax, [kernel_relocation_live_saved_low_esp]
    and eax, 0xfffff000
    mov [kernel_relocation_live_stack_phys], eax
    add eax, KERNEL_HIGHER_HALF_BASE
    mov [kernel_relocation_live_stack_vaddr], eax
    mov ebx, eax
    mov eax, [kernel_relocation_dir_addr]
    call kernel_translate_dir_vaddr
    mov [kernel_relocation_live_stack_xlat], eax
    cmp eax, [kernel_relocation_live_stack_phys]
    jne .done

    mov eax, kernel_relocation_live_magic
    mov [kernel_relocation_live_data_phys], eax
    add eax, KERNEL_HIGHER_HALF_BASE
    mov [kernel_relocation_live_data_vaddr], eax
    mov ebx, eax
    mov eax, [kernel_relocation_dir_addr]
    call kernel_translate_dir_vaddr
    mov [kernel_relocation_live_data_xlat], eax
    cmp eax, [kernel_relocation_live_data_phys]
    jne .done

    mov ebx, start
    and ebx, 0xfffff000
    mov eax, [kernel_relocation_dir_addr]
    call kernel_translate_dir_vaddr
    mov [kernel_relocation_live_low_xlat], eax
    cmp eax, 0xffffffff
    jne .done

    mov ebx, [kernel_relocation_live_saved_low_esp]
    and ebx, 0x00000fff
    add ebx, [kernel_relocation_live_stack_vaddr]
    mov eax, .after_live_call
    mov [kernel_relocation_live_expected_return], eax
    mov eax, kernel_relocation_live_switch_trampoline
    and eax, 0x00000fff
    add eax, [kernel_relocation_live_code_vaddr]
    mov esp, ebx
    call eax

.after_live_call:
    mov esp, [kernel_relocation_live_saved_low_esp]
    mov ebx, [kernel_relocation_live_return_vaddr]
    mov eax, [kernel_relocation_dir_addr]
    call kernel_translate_dir_vaddr
    mov [kernel_relocation_live_return_xlat], eax

    cmp byte [kernel_relocation_live_status], KERNEL_RELOCATION_LIVE_STATUS_OK
    jne .done
    cmp dword [kernel_relocation_live_magic], KERNEL_RELOCATION_LIVE_MAGIC
    jne .mark_fail
    mov eax, cr3
    cmp eax, PAGING_DIR_ADDR
    jne .mark_fail
    cmp dword [kernel_relocation_live_return_cr3], PAGING_DIR_ADDR
    jne .mark_fail
    mov eax, [kernel_relocation_live_cr3]
    cmp eax, [kernel_relocation_dir_addr]
    jne .mark_fail
    mov eax, [kernel_relocation_live_return_vaddr]
    cmp eax, [kernel_relocation_live_expected_return]
    jne .mark_fail
    cmp dword [kernel_relocation_live_return_xlat], 0xffffffff
    jne .mark_fail
    mov eax, KERNEL_RELOC_ABI_LOW_RETURN_BLOCKED
    call kernel_relocation_record_abi
    mov eax, KERNEL_RELOC_ABI_RETURN_CR3_RESTORED
    call kernel_relocation_record_abi
    mov eax, [kernel_relocation_live_eip]
    cmp eax, [kernel_relocation_live_code_vaddr]
    jb .mark_fail
    mov ebx, [kernel_relocation_live_code_vaddr]
    add ebx, PAGE_SIZE
    cmp eax, ebx
    jae .mark_fail
    mov eax, [kernel_relocation_live_esp]
    cmp eax, [kernel_relocation_live_stack_vaddr]
    jb .mark_fail
    mov ebx, [kernel_relocation_live_stack_vaddr]
    add ebx, PAGE_SIZE
    cmp eax, ebx
    jae .mark_fail
    jmp .done

.mark_fail:
    mov byte [kernel_relocation_live_status], KERNEL_RELOCATION_LIVE_STATUS_FAIL

.done:
    popad
    ret

kernel_relocation_live_switch_trampoline:
    mov eax, [kernel_relocation_dir_addr]
    mov cr3, eax
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_relocation_abi_mask
    or dword [edi], KERNEL_RELOC_ABI_LIVE_CR3_SWITCH
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_relocation_abi_last_op
    mov dword [edi], KERNEL_RELOC_ABI_LIVE_CR3_SWITCH
    call .capture_eip

.capture_eip:
    pop eax
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_relocation_live_eip
    mov [edi], eax
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_relocation_live_esp
    mov [edi], esp
    mov eax, [esp]
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_relocation_live_return_vaddr
    mov [edi], eax
    mov eax, cr3
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_relocation_live_cr3
    mov [edi], eax
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_relocation_live_magic
    mov dword [edi], KERNEL_RELOCATION_LIVE_MAGIC
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_relocation_abi_mask
    or dword [edi], KERNEL_RELOC_ABI_HIGH_DATA_WRITE
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_relocation_abi_last_op
    mov dword [edi], KERNEL_RELOC_ABI_HIGH_DATA_WRITE
    mov edi, KERNEL_HIGHER_HALF_BASE + kernel_relocation_live_status
    mov byte [edi], KERNEL_RELOCATION_LIVE_STATUS_OK
    mov eax, PAGING_DIR_ADDR
    mov cr3, eax
    mov eax, cr3
    mov [kernel_relocation_live_return_cr3], eax
    ret

kernel_high_alias_self_test:
    pushad

    mov byte [kernel_high_alias_status], KERNEL_HIGH_ALIAS_STATUS_FAIL
    mov eax, start
    and eax, 0xfffff000
    add eax, KERNEL_HIGHER_HALF_BASE
    mov [kernel_high_alias_vaddr], eax

    mov eax, start
    call kernel_translate_current_vaddr
    cmp eax, 0xffffffff
    je .done
    and eax, 0xfffff000
    cmp eax, KERNEL_HIGHER_HALF_BASE
    jae .done
    mov [kernel_high_alias_phys], eax

    mov eax, [kernel_high_alias_vaddr]
    cmp eax, [kernel_high_alias_phys]
    je .done

    mov ebx, [kernel_high_alias_phys]
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .done
    mov eax, [vmm_map_table_addr]
    mov [kernel_high_alias_table], eax

    mov esi, start
    mov eax, [esi]
    mov [kernel_high_alias_low_word], eax

    mov edi, [kernel_high_alias_vaddr]
    mov edx, start
    and edx, 0x00000fff
    add edi, edx
    mov ebx, [edi]
    mov [kernel_high_alias_high_word], ebx

    cmp eax, ebx
    jne .unmap
    test eax, eax
    jz .unmap
    mov byte [kernel_high_alias_status], KERNEL_HIGH_ALIAS_STATUS_OK

.unmap:
    mov eax, [kernel_high_alias_vaddr]
    call vmm_unmap_page
    mov eax, [vmm_last_reclaimed_page_table]
    mov [kernel_high_alias_reclaimed], eax
    cmp byte [kernel_high_alias_status], KERNEL_HIGH_ALIAS_STATUS_OK
    jne .done
    cmp eax, [kernel_high_alias_table]
    je .done
    mov byte [kernel_high_alias_status], KERNEL_HIGH_ALIAS_STATUS_FAIL

.done:
    popad
    ret

kernel_high_exec_self_test:
    pushad

    mov byte [kernel_high_exec_status], KERNEL_HIGH_EXEC_STATUS_FAIL
    mov dword [kernel_high_exec_eip], 0
    mov dword [kernel_high_exec_esp], 0
    mov dword [kernel_high_exec_cr3], 0
    mov dword [kernel_high_exec_vaddr], 0
    mov dword [kernel_high_exec_phys], 0
    mov dword [kernel_high_exec_stack_vaddr], 0
    mov dword [kernel_high_exec_stack_phys], 0
    mov dword [kernel_high_exec_table], 0
    mov dword [kernel_high_exec_reclaimed], 0
    mov dword [kernel_high_exec_xlat], 0
    mov dword [kernel_high_exec_stack_xlat], 0
    mov dword [kernel_high_exec_stack_probe_vaddr], 0
    mov dword [kernel_high_exec_stack_probe_phys], 0
    mov dword [kernel_high_exec_stack_probe_word], 0
    mov dword [kernel_high_exec_return_eip], 0
    mov [kernel_high_exec_saved_low_esp], esp

    mov eax, kernel_high_exec_trampoline
    and eax, 0xfffff000
    add eax, KERNEL_HIGHER_HALF_BASE
    mov [kernel_high_exec_vaddr], eax

    mov eax, kernel_high_exec_trampoline
    call kernel_translate_current_vaddr
    cmp eax, 0xffffffff
    je .done
    and eax, 0xfffff000
    cmp eax, KERNEL_HIGHER_HALF_BASE
    jae .done
    mov [kernel_high_exec_phys], eax

    mov eax, [kernel_high_exec_saved_low_esp]
    call kernel_translate_current_vaddr
    cmp eax, 0xffffffff
    je .done
    and eax, 0xfffff000
    cmp eax, KERNEL_STACK_LOW
    jb .done
    cmp eax, KERNEL_STACK_TOP
    jae .done
    mov [kernel_high_exec_stack_phys], eax
    add eax, KERNEL_HIGHER_HALF_BASE
    mov [kernel_high_exec_stack_vaddr], eax

    mov eax, [kernel_high_exec_vaddr]
    cmp eax, [kernel_high_exec_phys]
    je .done
    mov ebx, [kernel_high_exec_phys]
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .done
    mov eax, [vmm_map_table_addr]
    mov [kernel_high_exec_table], eax

    mov eax, [kernel_high_exec_vaddr]
    add eax, PAGE_SIZE
    mov ebx, [kernel_high_exec_phys]
    add ebx, PAGE_SIZE
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .unmap_code

    mov eax, [kernel_high_exec_stack_vaddr]
    cmp eax, [kernel_high_exec_stack_phys]
    je .unmap_code
    mov ebx, [kernel_high_exec_stack_phys]
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .unmap_code

    mov eax, [kernel_high_exec_vaddr]
    call kernel_translate_current_vaddr
    mov [kernel_high_exec_xlat], eax
    cmp eax, [kernel_high_exec_phys]
    jne .mark_fail_unmap_both

    mov eax, [kernel_high_exec_stack_vaddr]
    call kernel_translate_current_vaddr
    mov [kernel_high_exec_stack_xlat], eax
    cmp eax, [kernel_high_exec_stack_phys]
    jne .mark_fail_unmap_both

