kernel_persistent_map_range:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

.map_next:
    test ecx, ecx
    jz .ok
    push ecx
    mov eax, edi
    mov ebx, esi
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    pop ecx
    jc .fail
    cmp dword [kernel_persistent_alias_table], 0
    jne .mapped
    mov eax, [vmm_map_table_addr]
    mov [kernel_persistent_alias_table], eax

.mapped:
    add esi, PAGE_SIZE
    add edi, PAGE_SIZE
    dec ecx
    jmp .map_next

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

kernel_persistent_alias_install_process_dirs:
    push eax

    mov eax, [PAGING_DIR_ADDR + (KERNEL_HIGHER_HALF_PDE_INDEX * 4)]
    test eax, PTE_PRESENT
    jz .done
    mov dword [kernel_persistent_alias_dir_mask], 0x00000001
    mov [PROC_PROBE_PAGE_DIR_ADDR + (KERNEL_HIGHER_HALF_PDE_INDEX * 4)], eax
    or dword [kernel_persistent_alias_dir_mask], 0x00000002
    mov [PROC_PREEMPT_PAGE_DIR_ADDR + (KERNEL_HIGHER_HALF_PDE_INDEX * 4)], eax
    or dword [kernel_persistent_alias_dir_mask], 0x00000004
    mov [PROC_PAYLOAD_PAGE_DIR_ADDR + (KERNEL_HIGHER_HALF_PDE_INDEX * 4)], eax
    or dword [kernel_persistent_alias_dir_mask], 0x00000008
    mov [PROC_GENERIC0_PAGE_DIR_ADDR + (KERNEL_HIGHER_HALF_PDE_INDEX * 4)], eax
    or dword [kernel_persistent_alias_dir_mask], 0x00000010
    mov [PROC_GENERIC1_PAGE_DIR_ADDR + (KERNEL_HIGHER_HALF_PDE_INDEX * 4)], eax
    or dword [kernel_persistent_alias_dir_mask], 0x00000020
    mov [PROC_GENERIC2_PAGE_DIR_ADDR + (KERNEL_HIGHER_HALF_PDE_INDEX * 4)], eax
    or dword [kernel_persistent_alias_dir_mask], 0x00000040

.done:
    pop eax
    ret

framebuffer_map_lfb:
    pushad

    mov byte [framebuffer_map_status], 0
    mov dword [framebuffer_pde_index], 0
    mov dword [framebuffer_pte_index], 0
    mov dword [framebuffer_pde_count], 0
    cmp dword [BOOT_INFO_ADDR + 8], VIDEO_BOOT_MAGIC
    jne .done
    call framebuffer_capture_mmio_metadata
    jc .fail

    mov eax, [framebuffer_mmio_phys_base]
    shr eax, 22
    mov [framebuffer_pde_index], eax

    mov edx, [framebuffer_mmio_phys_base]
    shr edx, 12
    and edx, 0x000003ff
    mov [framebuffer_pte_index], edx
    mov eax, [framebuffer_page_count]
    add eax, edx
    add eax, 1023
    shr eax, 10
    mov [framebuffer_pde_count], eax

    mov eax, [framebuffer_pde_index]
    cmp eax, PAGING_TABLE_COUNT
    jb .mapped

    mov eax, [framebuffer_mmio_phys_base]
    mov ebx, eax
    mov esi, [framebuffer_page_count]

.map_next:
    cmp esi, 0
    je .mapped
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .fail
    add ebx, PAGE_SIZE
    add eax, PAGE_SIZE
    dec esi
    jmp .map_next

.mapped:
    call framebuffer_install_process_dirs
    mov byte [framebuffer_map_status], 1
    jmp .done

.fail:
    mov byte [framebuffer_map_status], 2

.done:
    popad
    ret

framebuffer_capture_mmio_metadata:
    push eax
    push ebx
    push ecx
    push edx

    mov dword [framebuffer_mmio_phys_base], 0
    mov dword [framebuffer_mmio_page_count], 0
    mov dword [framebuffer_page_count], 0
    cmp dword [BOOT_INFO_ADDR + 8], VIDEO_BOOT_MAGIC
    jne .fail
    mov ax, [BOOT_VIDEO_FLAGS]
    test ax, BOOT_VIDEO_FLAG_LFB
    jz .fail
    test ax, BOOT_VIDEO_FLAG_XRGB8888 | BOOT_VIDEO_FLAG_XBGR8888
    jz .fail
    mov dx, ax
    and dx, BOOT_VIDEO_FLAG_XRGB8888 | BOOT_VIDEO_FLAG_XBGR8888
    cmp dx, BOOT_VIDEO_FLAG_XRGB8888 | BOOT_VIDEO_FLAG_XBGR8888
    je .fail
    cmp byte [BOOT_VIDEO_BPP], 32
    jne .fail
    cmp dword [BOOT_VIDEO_FB_ADDR], 0
    je .fail

    mov eax, [BOOT_VIDEO_FB_ADDR]
    and eax, 0xfffff000
    mov [framebuffer_mmio_phys_base], eax

    mov eax, [BOOT_VIDEO_FB_ADDR]
    and eax, 0x00000fff
    mov ebx, eax
    mov eax, [BOOT_VIDEO_PITCH]
    movzx ecx, word [BOOT_VIDEO_HEIGHT]
    mul ecx
    test edx, edx
    jnz .fail
    add eax, ebx
    jc .fail
    add eax, PAGE_SIZE - 1
    jc .fail
    shr eax, 12
    cmp eax, FRAMEBUFFER_LFB_MAX_PAGES
    ja .fail
    mov [framebuffer_page_count], eax
    mov [framebuffer_mmio_page_count], eax
    clc
    jmp .done

.fail:
    stc

.done:
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

framebuffer_install_process_dirs:
    push eax
    push ebx
    push ecx
    push edi

    mov eax, [framebuffer_pde_index]
    mov ecx, [framebuffer_pde_count]
    test ecx, ecx
    jz .done

.copy_next:
    mov edi, PAGING_DIR_ADDR
    mov ebx, [edi + eax * 4]
    test ebx, PTE_PRESENT
    jz .next
    mov edi, PROC_PROBE_PAGE_DIR_ADDR
    mov [edi + eax * 4], ebx
    mov edi, PROC_PREEMPT_PAGE_DIR_ADDR
    mov [edi + eax * 4], ebx
    mov edi, PROC_PAYLOAD_PAGE_DIR_ADDR
    mov [edi + eax * 4], ebx
    mov edi, PROC_GENERIC0_PAGE_DIR_ADDR
    mov [edi + eax * 4], ebx
    mov edi, PROC_GENERIC1_PAGE_DIR_ADDR
    mov [edi + eax * 4], ebx
    mov edi, PROC_GENERIC2_PAGE_DIR_ADDR
    mov [edi + eax * 4], ebx

.next:
    inc eax
    dec ecx
    jnz .copy_next

.done:
    pop edi
    pop ecx
    pop ebx
    pop eax
    ret

framebuffer_init:
    mov byte [video_backend], VIDEO_BACKEND_MODE13
    mov byte [framebuffer_status], 1
    mov dword [framebuffer_handoff_source], FRAMEBUFFER_HANDOFF_SOURCE_VGA_MODE13
    mov dword [framebuffer_capabilities], VIBE_FB_CAP_PRESENT_INDEXED | VIBE_FB_CAP_PRESENT_RGB_PALETTE | VIBE_FB_CAP_MODE13_SHADOW | VIBE_FB_CAP_DIRTY_SOURCE_RECT | VIBE_FB_CAP_FIXED_PRESENT_SIZE
    mov dword [framebuffer_addr], VGA_GRAPHICS_BUFFER
    mov dword [framebuffer_pitch], FB_PRESENT_WIDTH
    mov dword [framebuffer_width], FB_PRESENT_WIDTH
    mov dword [framebuffer_height], FB_PRESENT_HEIGHT
    mov dword [framebuffer_color_order], 0

    cmp dword [BOOT_INFO_ADDR + 8], VIDEO_BOOT_MAGIC
    jne .done
    cmp byte [framebuffer_map_status], 1
    jne .done
    mov ax, [BOOT_VIDEO_FLAGS]
    test ax, BOOT_VIDEO_FLAG_LFB
    jz .done
    test ax, BOOT_VIDEO_FLAG_XRGB8888 | BOOT_VIDEO_FLAG_XBGR8888
    jz .done
    mov dx, ax
    and dx, BOOT_VIDEO_FLAG_XRGB8888 | BOOT_VIDEO_FLAG_XBGR8888
    cmp dx, BOOT_VIDEO_FLAG_XRGB8888 | BOOT_VIDEO_FLAG_XBGR8888
    je .done
    cmp byte [BOOT_VIDEO_BPP], 32
    jne .done
    cmp byte [BOOT_VIDEO_MEMORY_MODEL], 6
    jne .done
    cmp byte [BOOT_VIDEO_RED_MASK], 8
    jb .done
    cmp byte [BOOT_VIDEO_GREEN_MASK], 8
    jb .done
    cmp byte [BOOT_VIDEO_GREEN_POS], 8
    jne .done
    cmp byte [BOOT_VIDEO_BLUE_MASK], 8
    jb .done
    mov dword [framebuffer_color_order], 0
    cmp byte [BOOT_VIDEO_RED_POS], 16
    jne .maybe_xbgr
    cmp byte [BOOT_VIDEO_BLUE_POS], 0
    jne .done
    mov dword [framebuffer_color_order], FRAMEBUFFER_COLOR_ORDER_XRGB
    jmp .color_order_ready
.maybe_xbgr:
    cmp byte [BOOT_VIDEO_RED_POS], 0
    jne .done
    cmp byte [BOOT_VIDEO_BLUE_POS], 16
    jne .done
    mov dword [framebuffer_color_order], FRAMEBUFFER_COLOR_ORDER_XBGR
.color_order_ready:
    movzx eax, word [BOOT_VIDEO_WIDTH]
    cmp eax, 640
    jb .done
    movzx ebx, word [BOOT_VIDEO_HEIGHT]
    cmp ebx, 400
    jb .done
    mov ecx, [BOOT_VIDEO_PITCH]
    cmp ecx, 640 * 4
    jb .done

    mov byte [video_backend], VIDEO_BACKEND_LFB_XRGB8888
    cmp dword [framebuffer_color_order], FRAMEBUFFER_COLOR_ORDER_XBGR
    je .set_xbgr_cap
    or dword [framebuffer_capabilities], VIBE_FB_CAP_XRGB8888_LFB
    jmp .cap_ready
.set_xbgr_cap:
    or dword [framebuffer_capabilities], VIBE_FB_CAP_XBGR8888_LFB
.cap_ready:
    mov dword [framebuffer_handoff_source], FRAMEBUFFER_HANDOFF_SOURCE_VBE
    cmp word [BOOT_VIDEO_MODE], FRAMEBUFFER_GOP_BOOT_MODE
    jne .handoff_source_ready
    mov dword [framebuffer_handoff_source], FRAMEBUFFER_HANDOFF_SOURCE_GOP

.handoff_source_ready:
    mov eax, [BOOT_VIDEO_FB_ADDR]
    mov [framebuffer_addr], eax
    mov eax, [BOOT_VIDEO_PITCH]
    mov [framebuffer_pitch], eax
    movzx eax, word [BOOT_VIDEO_WIDTH]
    mov [framebuffer_width], eax
    movzx eax, word [BOOT_VIDEO_HEIGHT]
    mov [framebuffer_height], eax
    and dword [framebuffer_capabilities], 0xffffffdf
    mov eax, [framebuffer_width]
    mov [framebuffer_source_width], eax
    mov [framebuffer_source_aspect_width], eax
    mov eax, [framebuffer_height]
    mov [framebuffer_source_height], eax
    mov [framebuffer_source_aspect_height], eax
    mov eax, [framebuffer_width]
    mul dword [framebuffer_height]
    mov [framebuffer_source_frame_bytes], eax

.done:
    ret

process_vm_init_page_spaces:
    pushad

    mov esi, PAGING_DIR_ADDR
    mov edi, PROC_PROBE_PAGE_DIR_ADDR
    mov ecx, 1024
    cld
    rep movsd

    mov esi, PAGING_DIR_ADDR
    mov edi, PROC_PAYLOAD_PAGE_DIR_ADDR
    mov ecx, 1024
    cld
    rep movsd

    mov esi, PAGING_DIR_ADDR
    mov edi, PROC_PREEMPT_PAGE_DIR_ADDR
    mov ecx, 1024
    cld
    rep movsd

    mov esi, PAGING_DIR_ADDR
    mov edi, PROC_GENERIC0_PAGE_DIR_ADDR
    mov ecx, 1024
    cld
    rep movsd

    mov esi, PAGING_DIR_ADDR
    mov edi, PROC_GENERIC1_PAGE_DIR_ADDR
    mov ecx, 1024
    cld
    rep movsd

    mov esi, PAGING_DIR_ADDR
    mov edi, PROC_GENERIC2_PAGE_DIR_ADDR
    mov ecx, 1024
    cld
    rep movsd

    mov esi, PAGING_TABLES_ADDR + (4 * PAGE_SIZE)
    mov edi, PROC_USER_PDE4_TABLE_ADDR
    mov ecx, 1024
    cld
    rep movsd

    mov esi, PAGING_TABLES_ADDR + (3 * PAGE_SIZE)
    mov edi, PROC_PROBE_PDE3_TABLE_ADDR
    mov ecx, 1024
    cld
    rep movsd
    mov dword [PROC_PROBE_PAGE_DIR_ADDR + (3 * 4)], PROC_PROBE_PDE3_TABLE_ADDR | PTE_USER_FLAGS
    mov dword [PROC_PROBE_PAGE_DIR_ADDR + (4 * 4)], PROC_USER_PDE4_TABLE_ADDR | PTE_USER_FLAGS

    mov ebx, PROC_PROBE_PAGE_DIR_ADDR
    mov eax, USER_CODE_ADDR
    mov edx, USER_STACK_TOP
    call vmm_mark_process_user_range
    mov eax, USER_CODE_ADDR - PAGE_SIZE
    call vmm_clear_process_guard_page
    mov eax, USER_STACK_BOTTOM
    call vmm_clear_process_guard_page
    mov eax, USER_HEAP_END
    call vmm_clear_process_guard_page

    mov esi, PAGING_TABLES_ADDR + (3 * PAGE_SIZE)
    mov edi, PROC_PREEMPT_PDE3_TABLE_ADDR
    mov ecx, 1024
    cld
    rep movsd
    mov dword [PROC_PREEMPT_PAGE_DIR_ADDR + (3 * 4)], PROC_PREEMPT_PDE3_TABLE_ADDR | PTE_USER_FLAGS
    mov dword [PROC_PREEMPT_PAGE_DIR_ADDR + (4 * 4)], PROC_USER_PDE4_TABLE_ADDR | PTE_USER_FLAGS

    mov ebx, PROC_PREEMPT_PAGE_DIR_ADDR
    mov eax, USER_CODE_ADDR
    mov edx, USER_STACK_TOP
    call vmm_mark_process_user_range
    mov eax, USER_CODE_ADDR - PAGE_SIZE
    call vmm_clear_process_guard_page
    mov eax, USER_STACK_BOTTOM
    call vmm_clear_process_guard_page
    mov eax, USER_HEAP_END
    call vmm_clear_process_guard_page

    mov esi, PAGING_TABLES_ADDR + (3 * PAGE_SIZE)
    mov edi, PROC_GENERIC0_PDE3_TABLE_ADDR
    mov ecx, 1024
    cld
    rep movsd
    mov dword [PROC_GENERIC0_PAGE_DIR_ADDR + (3 * 4)], PROC_GENERIC0_PDE3_TABLE_ADDR | PTE_USER_FLAGS
    mov dword [PROC_GENERIC0_PAGE_DIR_ADDR + (4 * 4)], PROC_USER_PDE4_TABLE_ADDR | PTE_USER_FLAGS

    mov ebx, PROC_GENERIC0_PAGE_DIR_ADDR
    mov eax, USER_CODE_ADDR
    mov edx, USER_STACK_TOP
    call vmm_mark_process_user_range
    mov eax, USER_CODE_ADDR - PAGE_SIZE
    call vmm_clear_process_guard_page
    mov eax, USER_STACK_BOTTOM
    call vmm_clear_process_guard_page
    mov eax, USER_HEAP_END
    call vmm_clear_process_guard_page

    mov esi, PAGING_TABLES_ADDR + (3 * PAGE_SIZE)
    mov edi, PROC_GENERIC1_PDE3_TABLE_ADDR
    mov ecx, 1024
    cld
    rep movsd
    mov dword [PROC_GENERIC1_PAGE_DIR_ADDR + (3 * 4)], PROC_GENERIC1_PDE3_TABLE_ADDR | PTE_USER_FLAGS
    mov dword [PROC_GENERIC1_PAGE_DIR_ADDR + (4 * 4)], PROC_USER_PDE4_TABLE_ADDR | PTE_USER_FLAGS

    mov ebx, PROC_GENERIC1_PAGE_DIR_ADDR
    mov eax, USER_CODE_ADDR
    mov edx, USER_STACK_TOP
    call vmm_mark_process_user_range
    mov eax, USER_CODE_ADDR - PAGE_SIZE
    call vmm_clear_process_guard_page
    mov eax, USER_STACK_BOTTOM
    call vmm_clear_process_guard_page
    mov eax, USER_HEAP_END
    call vmm_clear_process_guard_page

    mov esi, PAGING_TABLES_ADDR + (3 * PAGE_SIZE)
    mov edi, PROC_GENERIC2_PDE3_TABLE_ADDR
    mov ecx, 1024
    cld
    rep movsd
    mov dword [PROC_GENERIC2_PAGE_DIR_ADDR + (3 * 4)], PROC_GENERIC2_PDE3_TABLE_ADDR | PTE_USER_FLAGS
    mov dword [PROC_GENERIC2_PAGE_DIR_ADDR + (4 * 4)], PROC_USER_PDE4_TABLE_ADDR | PTE_USER_FLAGS

    mov ebx, PROC_GENERIC2_PAGE_DIR_ADDR
    mov eax, USER_CODE_ADDR
    mov edx, USER_STACK_TOP
    call vmm_mark_process_user_range
    mov eax, USER_CODE_ADDR - PAGE_SIZE
    call vmm_clear_process_guard_page
    mov eax, USER_STACK_BOTTOM
    call vmm_clear_process_guard_page
    mov eax, USER_HEAP_END
    call vmm_clear_process_guard_page

    mov esi, PAGING_TABLES_ADDR + (4 * PAGE_SIZE)
    mov edi, PROC_PAYLOAD_PDE4_TABLE_ADDR
    mov ecx, 1024
    cld
    rep movsd
    mov dword [PROC_PAYLOAD_PAGE_DIR_ADDR + (4 * 4)], PROC_PAYLOAD_PDE4_TABLE_ADDR | PTE_USER_FLAGS

    mov esi, PAGING_TABLES_ADDR + (5 * PAGE_SIZE)
    mov edi, PROC_PAYLOAD_PDE5_TABLE_ADDR
    mov ecx, 1024
    cld
    rep movsd
    mov dword [PROC_PAYLOAD_PAGE_DIR_ADDR + (5 * 4)], PROC_PAYLOAD_PDE5_TABLE_ADDR | PTE_USER_FLAGS

    mov esi, PAGING_TABLES_ADDR + (6 * PAGE_SIZE)
    mov edi, PROC_PAYLOAD_PDE6_TABLE_ADDR
    mov ecx, 1024
    cld
    rep movsd
    mov dword [PROC_PAYLOAD_PAGE_DIR_ADDR + (6 * 4)], PROC_PAYLOAD_PDE6_TABLE_ADDR | PTE_USER_FLAGS

    mov esi, PAGING_TABLES_ADDR + (7 * PAGE_SIZE)
    mov edi, PROC_PAYLOAD_PDE7_TABLE_ADDR
    mov ecx, 1024
    cld
    rep movsd
    mov dword [PROC_PAYLOAD_PAGE_DIR_ADDR + (7 * 4)], PROC_PAYLOAD_PDE7_TABLE_ADDR | PTE_USER_FLAGS

    mov ebx, PROC_PAYLOAD_PAGE_DIR_ADDR
    mov eax, PAYLOAD_USER_BASE
    mov edx, PAYLOAD_USER_HEAP_START
    call vmm_mark_process_user_range
    mov eax, PAYLOAD_USER_STACK_BOTTOM
    mov edx, PAYLOAD_USER_STACK_TOP
    call vmm_mark_process_user_range
    mov eax, PAYLOAD_USER_BASE - PAGE_SIZE
    call vmm_clear_process_guard_page
    mov eax, PAYLOAD_USER_STACK_BOTTOM
    call vmm_clear_process_guard_page
    mov eax, PAYLOAD_USER_STACK_TOP
    call vmm_clear_process_guard_page

    call vmm_probe_user_guard_pages

    popad
    ret

vmm_mark_process_user_range:
    mov ecx, PTE_USER_WRITE_FLAGS
    jmp vmm_mark_process_user_range_with_flags

vmm_mark_process_user_read_range:
    mov ecx, PTE_USER_READ_FLAGS
    jmp vmm_mark_process_user_range_with_flags

vmm_mark_process_user_write_range:
    mov ecx, PTE_USER_WRITE_FLAGS

vmm_mark_process_user_range_with_flags:
    push eax
    push ecx
    push edx

    and eax, 0xfffff000
    add edx, PAGE_SIZE - 1
    and edx, 0xfffff000

.next:
    cmp eax, edx
    jae .done
    call vmm_mark_process_user_page
    add eax, PAGE_SIZE
    jmp .next

.done:
    pop edx
    pop ecx
    pop eax
    ret

vmm_mark_process_user_page:
    push eax
    push ebx
    push ecx
    push edx
    push edi

    mov edx, eax
    shr edx, 22
    lea edi, [ebx + edx * 4]
    mov edx, [edi]
    and edx, 0xfffff000
    or edx, PTE_USER_WRITE_FLAGS
    mov [edi], edx
    and edx, 0xfffff000

    shr eax, 12
    and eax, 0x3ff
    lea edi, [edx + eax * 4]
    mov ebx, [edi]
    and ebx, 0xfffff000
    or ebx, ecx
    mov [edi], ebx

    pop edi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

vmm_update_process_present_user_range_flags:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push ebp

    mov ebp, ecx
    and eax, 0xfffff000
    add edx, PAGE_SIZE - 1
    and edx, 0xfffff000
    mov esi, edx

.next:
    cmp eax, esi
    jae .done
    call vmm_find_process_pte
    jc .advance
    test edx, PTE_PRESENT
    jz .advance
    test edx, PTE_USER
    jz .advance
    and edx, 0xfffff000
    or edx, ebp
    mov ecx, edx
    call vmm_write_process_pte
    jc .fail
    invlpg [eax]

.advance:
    add eax, PAGE_SIZE
    jmp .next

.done:
    clc
    jmp .finish

.fail:
    stc

.finish:
    pop ebp
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

vmm_clear_process_page:
    push eax
    push ebx
    push ecx
    push edx
    push edi

    mov edx, eax
    shr edx, 22
    lea edi, [ebx + edx * 4]
    mov edx, [edi]
    test edx, PTE_PRESENT
    jz .absent
    and edx, 0xfffff000
    shr eax, 12
    and eax, 0x3ff
    cmp edx, PAGING_MAPPED_BYTES
    jae .alias_table
    lea edi, [edx + eax * 4]
    test dword [edi], PTE_PRESENT
    jz .absent
    and dword [edi], 0xfffffffe
    clc
    jmp .done

.alias_table:
    pushfd
    cli
    push eax
    mov eax, FORK_COPY_DST_ALIAS
    mov ebx, edx
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    pop eax
    jc .alias_fail
    lea edi, [FORK_COPY_DST_ALIAS + eax * 4]
    test dword [edi], PTE_PRESENT
    jz .alias_absent
    and dword [edi], 0xfffffffe
    mov eax, FORK_COPY_DST_ALIAS
    call vmm_unmap_page
    popfd
    clc
    jmp .done

.alias_absent:
    mov eax, FORK_COPY_DST_ALIAS
    call vmm_unmap_page
    popfd
    stc
    jmp .done

.alias_fail:
    popfd
    stc
    jmp .done

.absent:
    stc

.done:
    pop edi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

vmm_find_process_pte:
    push eax
    push ebx
    push ecx

    mov edx, eax
    shr edx, 22
    lea edi, [ebx + edx * 4]
    mov edx, [edi]
    test edx, PTE_PRESENT
    jz .fail
    and edx, 0xfffff000
    mov ecx, eax
    shr ecx, 12
    and ecx, 0x000003ff
    cmp edx, PAGING_MAPPED_BYTES
    jae .alias_table
    lea edi, [edx + ecx * 4]
    mov edx, [edi]
    clc
    jmp .done

.alias_table:
    pushfd
    cli
    mov eax, FORK_COPY_SRC_ALIAS
    mov ebx, edx
    push ecx
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    pop ecx
    jc .alias_fail
    lea edi, [FORK_COPY_SRC_ALIAS + ecx * 4]
    mov edx, [edi]
    mov eax, FORK_COPY_SRC_ALIAS
    call vmm_unmap_page
    popfd
    clc
    jmp .done

.alias_fail:
    popfd
    stc
    jmp .done

.fail:
    stc

.done:
    pop ecx
    pop ebx
    pop eax
    ret

vmm_write_process_pte:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    and eax, 0xfffff000
    mov [vmm_process_pte_vaddr], eax
    mov [vmm_process_pte_entry], ecx
    mov edx, eax
    shr edx, 22
    lea esi, [ebx + edx * 4]
    mov [vmm_process_pte_pde_ptr], esi
    mov edx, [esi]
    test edx, PTE_PRESENT
    jz .new_table
    test edx, PTE_USER
    jnz .have_table

.new_table:
    call pmm_alloc_page
    test eax, eax
    jz .fail
    mov [vmm_process_pte_table], eax

    pushfd
    cli
    mov eax, FORK_COPY_DST_ALIAS
    mov ebx, [vmm_process_pte_table]
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .new_table_alias_fail
    mov edi, FORK_COPY_DST_ALIAS
    xor eax, eax
    mov ecx, 1024
    cld
    rep stosd
    mov eax, FORK_COPY_DST_ALIAS
    call vmm_unmap_page
    popfd

    mov esi, [vmm_process_pte_pde_ptr]
    mov eax, [vmm_process_pte_table]
    or eax, PTE_USER_FLAGS
    mov [esi], eax
    inc dword [vmm_dynamic_page_tables]
    inc dword [vmm_active_page_tables]
    jmp .have_table

.new_table_alias_fail:
    popfd
    mov eax, [vmm_process_pte_table]
    call pmm_free_page
    jmp .fail

.have_table:
    mov esi, [vmm_process_pte_pde_ptr]
    mov edx, [esi]
    and edx, 0xfffff000
    mov [vmm_process_pte_table], edx
    mov eax, [vmm_process_pte_vaddr]
    shr eax, 12
    and eax, 0x000003ff
    cmp edx, PAGING_MAPPED_BYTES
    jae .write_alias
    lea edi, [edx + eax * 4]
    mov ecx, [vmm_process_pte_entry]
    mov [edi], ecx
    clc
    jmp .done

.write_alias:
    pushfd
    cli
    push eax
    mov eax, FORK_COPY_DST_ALIAS
    mov ebx, [vmm_process_pte_table]
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    pop eax
    jc .write_alias_fail
    lea edi, [FORK_COPY_DST_ALIAS + eax * 4]
    mov ecx, [vmm_process_pte_entry]
    mov [edi], ecx
    mov eax, FORK_COPY_DST_ALIAS
    call vmm_unmap_page
    popfd
    clc
    jmp .done

.write_alias_fail:
    popfd
    stc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

vmm_ensure_process_pte:
    push eax
    push ebx
    push ecx
    push esi

    and eax, 0xfffff000
    mov [vmm_map_vaddr], eax
    mov edx, eax
    shr edx, 22
    lea esi, [ebx + edx * 4]
    mov [vmm_map_pde_ptr], esi
    mov edx, [esi]
    test edx, PTE_PRESENT
    jz .new_table
    test edx, PTE_USER
    jnz .have_table

.new_table:
    call pmm_alloc_page
    test eax, eax
    jz .fail
    mov [vmm_map_table_addr], eax

    pushfd
    cli
    push dword [vmm_map_vaddr]
    push dword [vmm_map_pde_ptr]
    push dword [vmm_map_table_addr]
    mov eax, FORK_COPY_DST_ALIAS
    mov ebx, [vmm_map_table_addr]
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .new_table_alias_fail
    mov edi, FORK_COPY_DST_ALIAS
    xor eax, eax
    mov ecx, 1024
    cld
    rep stosd
    mov eax, FORK_COPY_DST_ALIAS
    call vmm_unmap_page
    pop eax
    mov [vmm_map_table_addr], eax
    pop esi
    mov [vmm_map_pde_ptr], esi
    pop eax
    mov [vmm_map_vaddr], eax
    popfd

    mov esi, [vmm_map_pde_ptr]
    mov eax, [vmm_map_table_addr]
    or eax, PTE_USER_FLAGS
    mov [esi], eax
    inc dword [vmm_dynamic_page_tables]
    inc dword [vmm_active_page_tables]
    jmp .have_table

.new_table_alias_fail:
    pop eax
    mov [vmm_map_table_addr], eax
    pop esi
    mov [vmm_map_pde_ptr], esi
    pop eax
    mov [vmm_map_vaddr], eax
    popfd
    mov eax, [vmm_map_table_addr]
    call pmm_free_page
    jmp .fail

.have_table:
    mov edx, [esi]
    and edx, 0xfffff000
    mov eax, [vmm_map_vaddr]
    shr eax, 12
    and eax, 0x000003ff
    lea edi, [edx + eax * 4]
    mov edx, [edi]
    clc
    jmp .done

.fail:
    stc

.done:
    pop esi
    pop ecx
    pop ebx
    pop eax
    ret

vmm_clear_process_guard_page:
    call vmm_clear_process_page
    inc dword [vmm_user_guard_pages]
    ret

vmm_probe_user_guard_pages:
    pushad

    mov dword [vmm_guard_probe_count], 0
    mov dword [vmm_guard_present_failures], 0

    mov ebx, PROC_PROBE_PAGE_DIR_ADDR
    mov eax, USER_CODE_ADDR - PAGE_SIZE
    call vmm_probe_absent_guard_page
    mov eax, USER_STACK_BOTTOM
    call vmm_probe_absent_guard_page
    mov eax, USER_HEAP_END
    call vmm_probe_absent_guard_page

    mov ebx, PROC_PREEMPT_PAGE_DIR_ADDR
    mov eax, USER_CODE_ADDR - PAGE_SIZE
    call vmm_probe_absent_guard_page
    mov eax, USER_STACK_BOTTOM
    call vmm_probe_absent_guard_page
    mov eax, USER_HEAP_END
    call vmm_probe_absent_guard_page

    mov ebx, PROC_GENERIC0_PAGE_DIR_ADDR
    mov eax, USER_CODE_ADDR - PAGE_SIZE
    call vmm_probe_absent_guard_page
    mov eax, USER_STACK_BOTTOM
    call vmm_probe_absent_guard_page
    mov eax, USER_HEAP_END
    call vmm_probe_absent_guard_page

    mov ebx, PROC_GENERIC1_PAGE_DIR_ADDR
    mov eax, USER_CODE_ADDR - PAGE_SIZE
    call vmm_probe_absent_guard_page
    mov eax, USER_STACK_BOTTOM
    call vmm_probe_absent_guard_page
    mov eax, USER_HEAP_END
    call vmm_probe_absent_guard_page

    mov ebx, PROC_GENERIC2_PAGE_DIR_ADDR
    mov eax, USER_CODE_ADDR - PAGE_SIZE
    call vmm_probe_absent_guard_page
    mov eax, USER_STACK_BOTTOM
    call vmm_probe_absent_guard_page
    mov eax, USER_HEAP_END
    call vmm_probe_absent_guard_page

    mov ebx, PROC_PAYLOAD_PAGE_DIR_ADDR
    mov eax, PAYLOAD_USER_BASE - PAGE_SIZE
    call vmm_probe_absent_guard_page
    mov eax, PAYLOAD_USER_STACK_BOTTOM
    call vmm_probe_absent_guard_page
    mov eax, PAYLOAD_USER_STACK_TOP
    call vmm_probe_absent_guard_page

    popad
    ret

vmm_probe_absent_guard_page:
    inc dword [vmm_guard_probe_count]
    call vmm_find_process_pte
    jc .ok
    test edx, PTE_PRESENT
    jz .ok
    inc dword [vmm_guard_present_failures]

.ok:
    ret

pmm_init:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov dword [pmm_total_pages], 0
    mov dword [pmm_free_pages], 0
    mov dword [pmm_used_pages], 0
    mov dword [pmm_managed_start], PMM_MANAGED_START
    mov dword [pmm_managed_end], PMM_MANAGED_START
    mov dword [pmm_frame_map_pages], PMM_MANAGED_PAGES
    mov dword [pmm_e820_entries], 0
    mov dword [pmm_e820_entry_size], 0
    mov dword [pmm_e820_map_ptr], 0
    mov dword [pmm_e820_map_end], 0
    mov dword [pmm_e820_usable_entries], 0
    mov dword [pmm_e820_usable_pages], 0
    mov dword [pmm_e820_reserved_pages], 0
    mov dword [pmm_e820_reserved_override_pages], 0
    mov dword [pmm_e820_acpi_pages], 0
    mov dword [pmm_e820_bad_pages], 0
    mov dword [pmm_e820_highest_usable_end], PMM_MANAGED_START
    mov dword [pmm_e820_last_base], 0
    mov dword [pmm_e820_last_end], 0
    mov dword [pmm_low_guard_pages], PMM_LOW_GUARD_PAGES
    mov dword [pmm_reserved_pages], 0
    mov dword [pmm_dma_base], 0
    mov dword [pmm_dma_end], 0
    mov dword [pmm_dma_pages], 0
    mov dword [pmm_mmio_base], 0
    mov dword [pmm_mmio_pages], 0
    mov dword [pmm_self_test_alloc_phys], 0
    mov dword [pmm_self_test_free_before], 0
    mov dword [pmm_self_test_free_after], 0
    mov dword [pmm_self_test_used_before], 0
    mov dword [pmm_self_test_used_after], 0
    mov dword [pmm_exclusion_low_guard], 0
    mov dword [pmm_exclusion_kernel_reserved], 0
    mov dword [pmm_exclusion_user_reserved], 0
    mov dword [pmm_exclusion_dma_reserved], 0
    mov dword [pmm_exclusion_mmio_reserved], 0
    mov dword [pmm_scan_free_pages], 0
    mov dword [pmm_scan_used_pages], 0
    mov dword [pmm_scan_reserved_pages], 0
    mov dword [pmm_scan_invalid_pages], 0
    mov byte [pmm_source], PMM_SOURCE_NONE
    mov byte [pmm_e820_handoff_status], 0
    mov byte [pmm_frame_accounting_status], 0
    mov byte [pmm_test_status], 0

    call pmm_capture_guard_metadata

    mov edi, PMM_FRAME_MAP_ADDR
    mov al, PMM_FRAME_RESERVED
    mov ecx, PMM_MANAGED_PAGES
    rep stosb

    cmp dword [BOOT_E820_MAGIC_ADDR], BOOT_E820_MAGIC
    jne .legacy_int15
    movzx ecx, word [BOOT_E820_COUNT]
    test ecx, ecx
    jz .legacy_int15
    movzx eax, word [BOOT_E820_ENTRY_SIZE_ADDR]
    cmp eax, PMM_E820_MIN_ENTRY_SIZE
    jb .legacy_int15
    cmp eax, E820_ENTRY_SIZE
    jbe .e820_entry_size_ok
    mov eax, E820_ENTRY_SIZE

.e820_entry_size_ok:
    mov [pmm_e820_entry_size], eax
    cmp ecx, E820_MAX_ENTRIES
    jbe .e820_count_ok
    mov ecx, E820_MAX_ENTRIES

.e820_count_ok:
    mov [pmm_e820_entries], ecx
    mov esi, [BOOT_E820_MAP_ADDR_PTR]
    test esi, esi
    jnz .e820_map_ready
    mov esi, E820_MAP_ADDR

.e820_map_ready:
    mov [pmm_e820_map_ptr], esi
    call pmm_validate_e820_handoff
    cmp byte [pmm_e820_handoff_status], 1
    jne .legacy_int15

.e820_scan_loop:
    call pmm_scan_e820_entry
    mov eax, [pmm_e820_entry_size]
    add esi, eax
    loop .e820_scan_loop

    mov eax, [pmm_e820_highest_usable_end]
    cmp eax, PMM_MANAGED_START
    jbe .legacy_int15
    mov [pmm_managed_end], eax
    sub eax, PMM_MANAGED_START
    shr eax, 12
    cmp eax, PMM_MANAGED_PAGES
    jbe .e820_total_ok
    mov eax, PMM_MANAGED_PAGES

.e820_total_ok:
    mov [pmm_total_pages], eax
    mov [pmm_used_pages], eax
    mov esi, [pmm_e820_map_ptr]
    mov ecx, [pmm_e820_entries]

.e820_mark_loop:
    cmp dword [esi + 16], E820_TYPE_USABLE
    jne .e820_next
    call pmm_mark_e820_usable_entry

.e820_next:
    mov eax, [pmm_e820_entry_size]
    add esi, eax
    loop .e820_mark_loop

    mov esi, [pmm_e820_map_ptr]
    mov ecx, [pmm_e820_entries]

.e820_reserve_loop:
    cmp dword [esi + 16], E820_TYPE_USABLE
    je .e820_reserve_next
    call pmm_reserve_e820_entry

.e820_reserve_next:
    mov eax, [pmm_e820_entry_size]
    add esi, eax
    loop .e820_reserve_loop

    cmp dword [pmm_free_pages], 0
    je .legacy_int15
    mov byte [pmm_source], PMM_SOURCE_E820
    jmp .reserve_fixed

.legacy_int15:
    mov byte [pmm_source], PMM_SOURCE_LEGACY_INT15
    movzx eax, word [BOOT_INFO_ADDR + 4]
    shr eax, 2
    cmp eax, PMM_MANAGED_PAGES
    jbe .page_count_ok
    mov eax, PMM_MANAGED_PAGES

.page_count_ok:
    mov [pmm_total_pages], eax
    mov [pmm_free_pages], eax
    mov edx, eax
    shl edx, 12
    add edx, PMM_MANAGED_START
    mov [pmm_managed_end], edx
    mov edi, PMM_FRAME_MAP_ADDR
    mov ecx, eax
    mov al, PMM_FRAME_FREE
    rep stosb

.reserve_fixed:
    mov eax, HEAP_START
    mov ecx, HEAP_SIZE / PAGE_SIZE
    call pmm_reserve_pages

    mov eax, PRIMARY_ASSET_LOAD_ADDR
    mov ecx, PRIMARY_ASSET_MAX_BYTES / PAGE_SIZE
    call pmm_reserve_pages

    mov eax, USER_CODE_ADDR - PAGE_SIZE
    mov ecx, 1
    call pmm_reserve_pages

    mov eax, USER_CODE_ADDR
    mov ecx, (USER_IDENTITY_RESERVE_END - USER_CODE_ADDR) / PAGE_SIZE
    call pmm_reserve_pages

    mov eax, PAYLOAD_USER_BASE - PAGE_SIZE
    mov ecx, 1
    call pmm_reserve_pages

    mov eax, PAYLOAD_USER_BASE
    mov ecx, (PAYLOAD_USER_END - PAYLOAD_USER_BASE) / PAGE_SIZE
    call pmm_reserve_pages

    mov eax, PAYLOAD_USER_STACK_TOP
    mov ecx, 1
    call pmm_reserve_pages

    mov eax, FAT_TABLE_CACHE_ADDR
    mov ecx, (FAT_CACHE_BYTES + PAGE_SIZE - 1) / PAGE_SIZE
    call pmm_reserve_pages

    call pmm_reserve_tracked_hardware_ranges
    call pmm_probe_exclusions
    call pmm_refresh_frame_counters

    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

pmm_validate_e820_handoff:
    push eax
    push ebx
    push ecx
    push edx

    mov byte [pmm_e820_handoff_status], 0
    mov dword [pmm_e820_map_end], 0

    mov eax, [pmm_e820_map_ptr]
    cmp eax, E820_MAP_ADDR
    jb .done
    mov ebx, E820_MAP_ADDR + (E820_ENTRY_SIZE * E820_MAX_ENTRIES)
    cmp eax, ebx
    jae .done

    mov ecx, [pmm_e820_entries]
    test ecx, ecx
    jz .done
    cmp ecx, E820_MAX_ENTRIES
    ja .done

    mov edx, [pmm_e820_entry_size]
    cmp edx, PMM_E820_MIN_ENTRY_SIZE
    jb .done
    cmp edx, E820_ENTRY_SIZE
    ja .done

    imul ecx, edx
    add ecx, eax
    jc .done
    cmp ecx, ebx
    ja .done

    mov [pmm_e820_map_end], ecx
    mov byte [pmm_e820_handoff_status], 1

.done:
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

pmm_probe_exclusions:
    push eax

    mov eax, PMM_MANAGED_START - PAGE_SIZE
    call pmm_probe_rejected_page
    mov [pmm_exclusion_low_guard], eax

    mov eax, HEAP_START
    call pmm_probe_rejected_page
    mov [pmm_exclusion_kernel_reserved], eax

    mov eax, USER_CODE_ADDR
    call pmm_probe_rejected_page
    mov [pmm_exclusion_user_reserved], eax

    mov eax, [pmm_dma_base]
    call pmm_probe_rejected_page
    mov [pmm_exclusion_dma_reserved], eax

    mov dword [pmm_exclusion_mmio_reserved], 0
    cmp dword [pmm_mmio_pages], 0
    je .done
    mov eax, [pmm_mmio_base]
    call pmm_probe_rejected_page
    mov [pmm_exclusion_mmio_reserved], eax

.done:
    pop eax
    ret

pmm_refresh_frame_counters:
    push eax
    push ecx
    push esi

    mov dword [pmm_scan_free_pages], 0
    mov dword [pmm_scan_used_pages], 0
    mov dword [pmm_scan_reserved_pages], 0
    mov dword [pmm_scan_invalid_pages], 0
    mov byte [pmm_frame_accounting_status], 0

    mov ecx, [pmm_total_pages]
    mov esi, PMM_FRAME_MAP_ADDR

.scan_next:
    cmp ecx, 0
    je .validate
    cmp byte [esi], PMM_FRAME_FREE
    je .free
    cmp byte [esi], PMM_FRAME_USED
    je .used
    cmp byte [esi], PMM_FRAME_RESERVED
    je .reserved
    inc dword [pmm_scan_invalid_pages]
    jmp .advance

.free:
    inc dword [pmm_scan_free_pages]
    jmp .advance

.used:
    inc dword [pmm_scan_used_pages]
    jmp .advance

.reserved:
    inc dword [pmm_scan_reserved_pages]

.advance:
    inc esi
    dec ecx
    jmp .scan_next

.validate:
    cmp dword [pmm_scan_invalid_pages], 0
    jne .done

    mov eax, [pmm_scan_free_pages]
    cmp eax, [pmm_free_pages]
    jne .done

    mov eax, [pmm_scan_used_pages]
    add eax, [pmm_scan_reserved_pages]
    cmp eax, [pmm_used_pages]
    jne .done

    add eax, [pmm_scan_free_pages]
    cmp eax, [pmm_total_pages]
    jne .done

    cmp dword [pmm_total_pages], 0
    je .done
    mov byte [pmm_frame_accounting_status], 1

.done:
    pop esi
    pop ecx
    pop eax
    ret

pmm_probe_rejected_page:
    call pmm_page_is_free
    jc .rejected
    xor eax, eax
    ret

.rejected:
    mov eax, 1
    ret

pmm_page_is_free:
    push ebx
    push edi

    cmp eax, PMM_MANAGED_START
    jb .not_free
    cmp eax, [pmm_managed_end]
    jae .not_free
    mov ebx, eax
    sub ebx, PMM_MANAGED_START
    shr ebx, 12
    cmp ebx, [pmm_total_pages]
    jae .not_free
    mov edi, PMM_FRAME_MAP_ADDR
    add edi, ebx
    cmp byte [edi], PMM_FRAME_FREE
    jne .not_free
    clc
    jmp .done

.not_free:
    stc

.done:
    pop edi
    pop ebx
    ret

pmm_reserve_tracked_hardware_ranges:
    push eax
    push ecx

    mov eax, [pmm_dma_base]
    mov ecx, [pmm_dma_pages]
    call pmm_reserve_pages

    mov eax, [pmm_mmio_base]
    mov ecx, [pmm_mmio_pages]
    call pmm_reserve_pages

    pop ecx
    pop eax
    ret

pmm_capture_guard_metadata:
    push eax
    push ebx

    mov eax, sb16_dma_buffer
    and eax, 0xfffff000
    mov [pmm_dma_base], eax
    mov ebx, sb16_dma_buffer + SB16_DMA_BUFFER_BYTES + PAGE_SIZE - 1
    and ebx, 0xfffff000
    mov [pmm_dma_end], ebx
    sub ebx, eax
    shr ebx, 12
    mov [pmm_dma_pages], ebx

    call framebuffer_capture_mmio_metadata
    jc .done
    mov eax, [framebuffer_mmio_phys_base]
    mov [pmm_mmio_base], eax
    mov eax, [framebuffer_mmio_page_count]
    mov [pmm_mmio_pages], eax

.done:
    pop ebx
    pop eax
    ret

pmm_scan_e820_entry:
    push eax
    push ebx
    push ecx
    push edx
    push edi

    cmp dword [esi + 4], 0
    jne .done

    mov eax, [esi]
    mov ebx, [esi + 8]
    mov edx, [esi + 12]
    mov ecx, ebx
    or ecx, edx
    jz .done

    mov edi, eax
    add edi, ebx
    jc .saturate_end
    test edx, edx
    jz .end_ready

.saturate_end:
    mov edi, 0xffffffff

.end_ready:
    cmp edi, PMM_MANAGED_START
    jbe .done
    cmp eax, PMM_MANAGED_END
    jae .done
    cmp eax, PMM_MANAGED_START
    jae .start_ready
    mov eax, PMM_MANAGED_START

.start_ready:
    cmp edi, PMM_MANAGED_END
    jbe .clip_ready
    mov edi, PMM_MANAGED_END

.clip_ready:
    add eax, PAGE_SIZE - 1
    and eax, 0xfffff000
    and edi, 0xfffff000
    cmp eax, edi
    jae .done

    mov ebx, edi
    sub ebx, eax
    shr ebx, 12
    cmp dword [esi + 16], E820_TYPE_USABLE
    je .usable
    cmp dword [esi + 16], E820_TYPE_ACPI_RECLAIMABLE
    je .acpi
    cmp dword [esi + 16], E820_TYPE_ACPI_NVS
    je .acpi
    cmp dword [esi + 16], E820_TYPE_BAD_MEMORY
    je .bad
    add [pmm_e820_reserved_pages], ebx
    jmp .done

.usable:
    inc dword [pmm_e820_usable_entries]
    cmp edi, [pmm_e820_highest_usable_end]
    jbe .done
    mov [pmm_e820_highest_usable_end], edi
    jmp .done

.acpi:
    add [pmm_e820_acpi_pages], ebx
    jmp .done

.bad:
    add [pmm_e820_bad_pages], ebx

.done:
    pop edi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

pmm_mark_e820_usable_entry:
    push eax
    push ebx
    push ecx
    push edx
    push edi

    cmp dword [esi + 4], 0
    jne .done

    mov eax, [esi]
    mov ebx, [esi + 8]
    mov edx, [esi + 12]
    mov ecx, ebx
    or ecx, edx
    jz .done

    mov edi, eax
    add edi, ebx
    jc .saturate_end
    test edx, edx
    jz .end_ready

.saturate_end:
    mov edi, 0xffffffff

.end_ready:
    cmp edi, PMM_MANAGED_START
    jbe .done
    cmp eax, [pmm_managed_end]
    jae .done
    cmp eax, PMM_MANAGED_START
    jae .start_ready
    mov eax, PMM_MANAGED_START

.start_ready:
    cmp edi, [pmm_managed_end]
    jbe .clip_ready
    mov edi, [pmm_managed_end]

.clip_ready:
    add eax, PAGE_SIZE - 1
    and eax, 0xfffff000
    and edi, 0xfffff000
    cmp eax, edi
    jae .done

    mov [pmm_e820_last_base], eax
    mov [pmm_e820_last_end], edi
    sub eax, PMM_MANAGED_START
    shr eax, 12
    mov ebx, eax
    sub edi, PMM_MANAGED_START
    shr edi, 12
    mov ecx, edi
    sub ecx, ebx
    mov edi, PMM_FRAME_MAP_ADDR
    add edi, ebx

.mark_next:
    cmp ecx, 0
    je .done
    cmp byte [edi], PMM_FRAME_FREE
    je .advance
    mov byte [edi], PMM_FRAME_FREE
    inc dword [pmm_free_pages]
    dec dword [pmm_used_pages]
    inc dword [pmm_e820_usable_pages]

.advance:
    inc edi
    dec ecx
    jmp .mark_next

.done:
    pop edi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

pmm_reserve_e820_entry:
    push eax
    push ebx
    push ecx
    push edx
    push edi

    cmp dword [esi + 4], 0
    jne .done

    mov eax, [esi]
    mov ebx, [esi + 8]
    mov edx, [esi + 12]
    mov ecx, ebx
    or ecx, edx
    jz .done

    mov edi, eax
    add edi, ebx
    jc .saturate_end
    test edx, edx
    jz .end_ready

.saturate_end:
    mov edi, 0xffffffff

.end_ready:
    cmp edi, PMM_MANAGED_START
    jbe .done
    cmp eax, [pmm_managed_end]
    jae .done
    cmp eax, PMM_MANAGED_START
    jae .start_ready
    mov eax, PMM_MANAGED_START

.start_ready:
    cmp edi, [pmm_managed_end]
    jbe .clip_ready
    mov edi, [pmm_managed_end]

.clip_ready:
    add eax, PAGE_SIZE - 1
    and eax, 0xfffff000
    and edi, 0xfffff000
    cmp eax, edi
    jae .done

    sub eax, PMM_MANAGED_START
    shr eax, 12
    mov ebx, eax
    sub edi, PMM_MANAGED_START
    shr edi, 12
    mov ecx, edi
    sub ecx, ebx
    mov edi, PMM_FRAME_MAP_ADDR
    add edi, ebx

.reserve_next:
    cmp ecx, 0
    je .done
    cmp byte [edi], PMM_FRAME_FREE
    jne .advance
    mov byte [edi], PMM_FRAME_RESERVED
    dec dword [pmm_free_pages]
    inc dword [pmm_used_pages]
    inc dword [pmm_e820_reserved_override_pages]

.advance:
    inc edi
    dec ecx
    jmp .reserve_next

.done:
    pop edi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

pmm_reserve_pages:
    push eax
    push ebx
    push ecx
    push edi

    cmp eax, PMM_MANAGED_START
    jb .done
    cmp eax, [pmm_managed_end]
    jae .done
    sub eax, PMM_MANAGED_START
    shr eax, 12
    mov ebx, eax

.reserve_next:
    cmp ecx, 0
    je .done
    cmp ebx, [pmm_total_pages]
    jae .done
    mov edi, PMM_FRAME_MAP_ADDR
    add edi, ebx
    cmp byte [edi], PMM_FRAME_FREE
    jne .advance
    mov byte [edi], PMM_FRAME_RESERVED
    dec dword [pmm_free_pages]
    inc dword [pmm_used_pages]
    inc dword [pmm_reserved_pages]

.advance:
    inc ebx
    dec ecx
    jmp .reserve_next

.done:
    pop edi
    pop ecx
    pop ebx
    pop eax
    ret

pmm_alloc_page:
    push ebx
    push ecx
    push edi

    xor ebx, ebx
    mov ecx, [pmm_total_pages]
    mov edi, PMM_FRAME_MAP_ADDR

.scan_next:
    cmp ecx, 0
    je .fail
    cmp byte [edi], PMM_FRAME_FREE
    je .found
    inc edi
    inc ebx
    dec ecx
    jmp .scan_next

.found:
    mov byte [edi], PMM_FRAME_USED
    dec dword [pmm_free_pages]
    inc dword [pmm_used_pages]
    mov eax, ebx
    shl eax, 12
    add eax, PMM_MANAGED_START
    pop edi
    pop ecx
    pop ebx
    ret

.fail:
    xor eax, eax
    pop edi
    pop ecx
    pop ebx
    ret

pmm_free_page:
    push ebx
    push edi

    cmp eax, PMM_MANAGED_START
    jb .done
    cmp eax, PMM_MANAGED_END
    jae .done
    cmp eax, [pmm_managed_end]
    jae .done
    sub eax, PMM_MANAGED_START
    shr eax, 12
    mov ebx, eax
    cmp ebx, [pmm_total_pages]
    jae .done
    mov edi, PMM_FRAME_MAP_ADDR
    add edi, ebx
    cmp byte [edi], PMM_FRAME_USED
    jne .done
    mov byte [edi], PMM_FRAME_FREE
    inc dword [pmm_free_pages]
    dec dword [pmm_used_pages]

.done:
    pop edi
    pop ebx
    ret

pmm_self_test:
    push ebx
    push ecx
    push edx
    push edi

    call pmm_refresh_frame_counters
    cmp byte [pmm_frame_accounting_status], 1
    jne .fail

    mov eax, [pmm_free_pages]
    mov [pmm_self_test_free_before], eax
    mov eax, [pmm_used_pages]
    mov [pmm_self_test_used_before], eax
    call pmm_alloc_page
    test eax, eax
    jz .fail
    mov ebx, eax
    mov [pmm_self_test_alloc_phys], eax
    mov eax, [pmm_free_pages]
    mov ecx, [pmm_self_test_free_before]
    dec ecx
    cmp eax, ecx
    jne .fail_after_alloc
    mov eax, [pmm_used_pages]
    mov ecx, [pmm_self_test_used_before]
    inc ecx
    cmp eax, ecx
    jne .fail_after_alloc
    mov edx, ebx
    sub edx, PMM_MANAGED_START
    shr edx, 12
    mov edi, PMM_FRAME_MAP_ADDR
    cmp byte [edi + edx], PMM_FRAME_USED
    jne .fail_after_alloc
    call pmm_refresh_frame_counters
    cmp byte [pmm_frame_accounting_status], 1
    jne .fail_after_alloc
    mov dword [ebx], 0x50414745
    cmp dword [ebx], 0x50414745
    jne .fail_after_alloc
    mov eax, ebx
    call pmm_free_page
    mov eax, [pmm_free_pages]
    cmp eax, [pmm_self_test_free_before]
    jne .fail
    mov [pmm_self_test_free_after], eax
    mov eax, [pmm_used_pages]
    cmp eax, [pmm_self_test_used_before]
    jne .fail
    mov [pmm_self_test_used_after], eax
    mov edx, ebx
    sub edx, PMM_MANAGED_START
    shr edx, 12
    mov edi, PMM_FRAME_MAP_ADDR
    cmp byte [edi + edx], PMM_FRAME_FREE
    jne .fail
    call pmm_refresh_frame_counters
    cmp byte [pmm_frame_accounting_status], 1
    jne .fail
    mov byte [pmm_test_status], 1
    jmp .done

.fail_after_alloc:
    mov eax, ebx
    call pmm_free_page

.fail:
    call pmm_refresh_frame_counters
    mov eax, [pmm_free_pages]
    mov [pmm_self_test_free_after], eax
    mov eax, [pmm_used_pages]
    mov [pmm_self_test_used_after], eax
    mov byte [pmm_test_status], 2

.done:
    pop edi
    pop edx
    pop ecx
    pop ebx
    ret

vmm_map_page:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    and eax, 0xfffff000
    mov [vmm_map_vaddr], eax
    and ebx, 0xfffff000
    or ebx, ecx
    or ebx, 0x001
    mov [vmm_map_entry], ebx

    mov edx, eax
    shr edx, 22
    mov edi, PAGING_DIR_ADDR
    lea edi, [edi + edx * 4]
    mov edx, [edi]
    test edx, PTE_PRESENT
    jnz .have_table

    call pmm_alloc_page
    test eax, eax
    jz .fail
    mov [vmm_map_table_addr], eax
    mov [vmm_map_pde_ptr], edi
    mov edi, eax
    xor eax, eax
    mov ecx, 1024
    cld
    rep stosd
    mov edi, [vmm_map_pde_ptr]
    mov eax, [vmm_map_table_addr]
    or eax, PTE_KERNEL_FLAGS
    mov ebx, [vmm_map_entry]
    and ebx, PTE_USER
    or eax, ebx
    mov [edi], eax
    inc dword [vmm_dynamic_page_tables]
    inc dword [vmm_active_page_tables]

.have_table:
    mov edx, [edi]
    and edx, 0xfffff000
    mov eax, [vmm_map_vaddr]
    shr eax, 12
    and eax, 0x000003ff
    lea edi, [edx + eax * 4]
    mov ebx, [vmm_map_entry]
    mov [edi], ebx
    mov eax, [vmm_map_vaddr]
    invlpg [eax]
    mov byte [vmm_status], 1
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

vmm_unmap_page:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    and eax, 0xfffff000
    mov [vmm_map_vaddr], eax
    mov edx, eax
    shr edx, 22
    mov edi, PAGING_DIR_ADDR
    lea edi, [edi + edx * 4]
    mov [vmm_map_pde_ptr], edi
    mov edx, [edi]
    test edx, PTE_PRESENT
    jz .done
    and edx, 0xfffff000
    mov [vmm_map_table_addr], edx
    mov eax, [vmm_map_vaddr]
    shr eax, 12
    and eax, 0x000003ff
    lea edi, [edx + eax * 4]
    mov dword [edi], 0
    mov eax, [vmm_map_vaddr]
    invlpg [eax]

    mov esi, [vmm_map_table_addr]
    mov ecx, 1024

.scan_table:
    cmp dword [esi], 0
    jne .done
    add esi, 4
    loop .scan_table

    mov eax, [vmm_map_table_addr]
    cmp eax, PMM_MANAGED_START
    jb .done
    cmp eax, PMM_MANAGED_END
    jae .done
    cmp eax, [pmm_managed_end]
    jae .done
    mov edi, [vmm_map_pde_ptr]
    mov dword [edi], 0
    mov [vmm_last_reclaimed_page_table], eax
    call pmm_free_page
    dec dword [vmm_active_page_tables]
    inc dword [vmm_reclaimed_page_tables]

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

vmm_identity_page:
    push ebx
    push ecx

    mov ebx, eax
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page

    pop ecx
    pop ebx
    ret

vmm_self_test:
    call pmm_alloc_page
    test eax, eax
    jz .fail
    mov ebx, eax

    mov eax, VMM_TEST_VADDR
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .free_fail

    mov dword [VMM_TEST_VADDR], VMM_TEST_MAGIC
    cmp dword [ebx], VMM_TEST_MAGIC
    jne .restore_fail

    mov eax, VMM_TEST_VADDR
    call vmm_identity_page
    mov eax, ebx
    call pmm_free_page
    call pmm_alloc_page
    test eax, eax
    jz .fail
    mov ebx, eax

    mov eax, VMM_HIGH_TEST_VADDR
    cmp eax, ebx
    je .high_free_fail
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .high_free_fail
    mov [vmm_high_test_phys], ebx
    mov eax, [vmm_map_table_addr]
    mov [vmm_high_test_table], eax

    mov dword [VMM_HIGH_TEST_VADDR], VMM_HIGH_TEST_MAGIC
    cmp dword [ebx], VMM_HIGH_TEST_MAGIC
    jne .high_unmap_fail

    mov eax, VMM_HIGH_TEST_VADDR
    call vmm_unmap_page
    mov eax, [vmm_last_reclaimed_page_table]
    mov [vmm_high_test_reclaimed], eax
    cmp eax, [vmm_high_test_table]
    jne .high_free_fail
    mov eax, ebx
    call pmm_free_page
    call kernel_high_alias_self_test
    cmp byte [kernel_high_alias_status], KERNEL_HIGH_ALIAS_STATUS_OK
    jne .fail
    call kernel_high_exec_self_test
    cmp byte [kernel_high_exec_status], KERNEL_HIGH_EXEC_STATUS_OK
    jne .fail
    call kernel_persistent_alias_self_test
    cmp byte [kernel_persistent_alias_status], KERNEL_PERSISTENT_ALIAS_STATUS_OK
    jne .fail
    call kernel_relocation_dir_self_test
    cmp byte [kernel_relocation_dir_status], KERNEL_RELOCATION_DIR_STATUS_OK
    jne .fail
    mov byte [vmm_high_mapping_status], 1
    mov byte [vmm_test_status], 1
    ret

.high_unmap_fail:
    mov eax, VMM_HIGH_TEST_VADDR
    call vmm_unmap_page

.high_free_fail:
    mov eax, ebx
    call pmm_free_page
    mov byte [vmm_high_mapping_status], 2
    jmp .fail

.restore_fail:
    mov eax, VMM_TEST_VADDR
    call vmm_identity_page

.free_fail:
    mov eax, ebx
    call pmm_free_page

.fail:
    cmp byte [vmm_high_mapping_status], 1
    je .status_only
    mov byte [vmm_high_mapping_status], 2

.status_only:
    mov byte [vmm_test_status], 2
    ret

heap_init:
    mov dword [heap_start], 0
    mov dword [heap_free_head], 0
    mov dword [heap_end], 0
    mov dword [heap_alloc_count], 0
    mov dword [heap_alloc_bytes], 0
    mov dword [heap_last_ptr], 0
    mov byte [heap_test_status], 0

    mov eax, [pmm_managed_end]
    cmp eax, HEAP_START + HEAP_SIZE
    jb .done

    mov dword [heap_start], HEAP_START
    mov dword [heap_end], HEAP_START + HEAP_SIZE
    mov dword [heap_free_head], HEAP_START
    mov dword [HEAP_START], HEAP_SIZE
    mov dword [HEAP_START + 4], 0
    mov dword [HEAP_START + 8], HEAP_BLOCK_MAGIC_FREE
    mov dword [HEAP_START + 12], 0

.done:
    ret

kalloc:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov ebx, eax
    add ebx, HEAP_ALIGN - 1
    and ebx, 0xfffffff0
    cmp ebx, 0
    je .fail

    mov edx, ebx
    add edx, HEAP_HEADER_SIZE

    xor esi, esi
    mov edi, [heap_free_head]

.find_block:
    cmp edi, 0
    je .fail
    mov ecx, [edi]
    cmp ecx, edx
    jae .use_block
    mov esi, edi
    mov edi, [edi + 4]
    jmp .find_block

.use_block:
    mov eax, ecx
    sub eax, edx
    cmp eax, HEAP_MIN_SPLIT_SIZE
    jb .take_whole

    mov ecx, edi
    add ecx, edx
    mov [ecx], eax
    mov eax, [edi + 4]
    mov [ecx + 4], eax
    mov dword [ecx + 8], HEAP_BLOCK_MAGIC_FREE
    mov dword [ecx + 12], 0
    test esi, esi
    jz .split_head
    mov [esi + 4], ecx
    jmp .mark_used

.split_head:
    mov [heap_free_head], ecx
    jmp .mark_used

.take_whole:
    mov edx, [edi]
    mov ecx, [edi + 4]
    test esi, esi
    jz .take_head
    mov [esi + 4], ecx
    jmp .mark_used

.take_head:
    mov [heap_free_head], ecx

.mark_used:
    mov [edi], edx
    mov dword [edi + 4], 0
    mov dword [edi + 8], HEAP_BLOCK_MAGIC_USED
    mov [edi + 12], ebx
    inc dword [heap_alloc_count]
    add [heap_alloc_bytes], ebx
    lea eax, [edi + HEAP_HEADER_SIZE]
    mov [heap_last_ptr], eax
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

.fail:
    xor eax, eax
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

kfree:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    test eax, eax
    jz .done
    mov edi, eax
    sub edi, HEAP_HEADER_SIZE
    cmp dword [edi + 8], HEAP_BLOCK_MAGIC_USED
    jne .done

    mov ebx, [edi + 12]
    sub [heap_alloc_bytes], ebx
    cmp dword [heap_alloc_count], 0
    je .mark_free
    dec dword [heap_alloc_count]

.mark_free:
    mov dword [edi + 8], HEAP_BLOCK_MAGIC_FREE
    mov dword [edi + 12], 0

    xor esi, esi
    mov edx, [heap_free_head]

.find_slot:
    test edx, edx
    jz .insert
    cmp edx, edi
    ja .insert
    mov esi, edx
    mov edx, [edx + 4]
    jmp .find_slot

.insert:
    mov [edi + 4], edx
    test esi, esi
    jz .insert_head
    mov [esi + 4], edi
    jmp .coalesce_next

.insert_head:
    mov [heap_free_head], edi

.coalesce_next:
    mov edx, [edi + 4]
    test edx, edx
    jz .coalesce_prev
    mov ecx, edi
    add ecx, [edi]
    cmp ecx, edx
    jne .coalesce_prev
    mov eax, [edx]
    add [edi], eax
    mov eax, [edx + 4]
    mov [edi + 4], eax

.coalesce_prev:
    test esi, esi
    jz .done
    mov ecx, esi
    add ecx, [esi]
    cmp ecx, edi
    jne .done
    mov eax, [edi]
    add [esi], eax
    mov eax, [edi + 4]
    mov [esi + 4], eax

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

heap_free_bytes:
    push ebx

    xor eax, eax
    mov ebx, [heap_free_head]

.sum_next:
    test ebx, ebx
    jz .done
    add eax, [ebx]
    mov ebx, [ebx + 4]
    jmp .sum_next

.done:
    pop ebx
    ret

heap_self_test:
    mov eax, 64
    call kalloc
    test eax, eax
    jz .fail
    mov dword [eax], 0x41555241
    cmp dword [eax], 0x41555241
    jne .fail

    mov eax, 256
    call kalloc
    test eax, eax
    jz .fail
    mov dword [eax + 252], 0x48454150
    cmp dword [eax + 252], 0x48454150
    jne .fail

    mov eax, HEAP_PROBE_SIZE
    call kalloc
    test eax, eax
    jz .fail
    mov ebx, eax
    mov dword [eax + HEAP_PROBE_LAST_DWORD], HEAP_PROBE_MAGIC
    cmp dword [eax + HEAP_PROBE_LAST_DWORD], HEAP_PROBE_MAGIC
    jne .fail
    mov eax, ebx
    call kfree

    mov eax, 128
    call kalloc
    test eax, eax
    jz .fail
    mov ebx, eax
    call kfree

    mov eax, 128
    call kalloc
    cmp eax, ebx
    jne .fail
    call kfree

    mov byte [heap_test_status], 1
    ret

.fail:
    mov byte [heap_test_status], 2
    ret

fpu_init:
    push eax
    push edx

    mov byte [fpu_status], FPU_STATUS_UNKNOWN
    mov byte [fpu_test_status], 0
    mov dword [fpu_context_init_count], 0
    mov dword [fpu_context_save_count], 0
    mov dword [fpu_context_restore_count], 0
    mov dword [fpu_exception_count], 0
    mov dword [fpu_nm_exception_count], 0
    mov dword [fpu_mf_exception_count], 0
    mov dword [fpu_simd_exception_count], 0
    mov dword [fpu_last_exception_vector], 0

    mov eax, cr0
    mov [fpu_cr0_before], eax
    and eax, CR0_FPU_CLEAR_MASK
    or eax, CR0_FPU_REQUIRED_BITS
    mov cr0, eax
    clts
    mov eax, cr0
    mov [fpu_cr0_after], eax
    mov eax, cr4
    or eax, CR4_OSFXSR | CR4_OSXMMEXCPT
    mov cr4, eax
    mov [fpu_cr4_snapshot], eax

    fninit
    fnclex
    fnstcw [fpu_control_word]
    fnstsw [fpu_status_word]

    mov eax, [fpu_cr0_after]
    test eax, CR0_EM | CR0_TS
    jnz .fail
    and eax, CR0_FPU_REQUIRED_BITS
    cmp eax, CR0_FPU_REQUIRED_BITS
    jne .fail
    movzx eax, word [fpu_control_word]
    cmp eax, FPU_CONTROL_WORD_INIT
    jne .fail

    mov byte [fpu_status], FPU_STATUS_READY
    jmp .done

.fail:
    mov byte [fpu_status], FPU_STATUS_FAILED

.done:
    pop edx
    pop eax
    ret

fpu_self_test:
    cmp byte [fpu_status], FPU_STATUS_READY
    jne .fail

    fnclex
    fild dword [fpu_test_three]
    fimul dword [fpu_test_three]
    fild dword [fpu_test_four]
    fimul dword [fpu_test_four]
    faddp st1, st0
    fsqrt
    fistp dword [fpu_test_result]
    fnstsw [fpu_test_status_word]
    cmp dword [fpu_test_result], 5
    jne .fail
    movzx eax, word [fpu_test_status_word]
    test eax, 0x0041
    jnz .fail

    mov byte [fpu_test_status], FPU_STATUS_READY
    ret

.fail:
    mov byte [fpu_test_status], FPU_STATUS_FAILED
    ret

libc_strlen:
    mov edx, [esp + 4]
    xor eax, eax

.next:
    cmp byte [edx + eax], 0
    je .done
    inc eax
    jmp .next

.done:
    ret

libc_strcpy:
    push esi
    push edi

    mov edi, [esp + 12]
    mov esi, [esp + 16]
    mov eax, edi

.next:
    mov dl, [esi]
    mov [edi], dl
    inc esi
    inc edi
    test dl, dl
    jne .next

    pop edi
    pop esi
    ret

libc_strcmp:
    push esi
    push edi

    mov esi, [esp + 12]
    mov edi, [esp + 16]

.next:
    mov al, [esi]
    mov dl, [edi]
    cmp al, dl
    jne .different
    test al, al
    je .equal
    inc esi
    inc edi
    jmp .next

.different:
    movzx eax, al
    movzx edx, dl
    sub eax, edx
    pop edi
    pop esi
    ret

.equal:
    xor eax, eax
    pop edi
    pop esi
    ret

libc_memcpy:
    push esi
    push edi

    mov edi, [esp + 12]
    mov esi, [esp + 16]
    mov ecx, [esp + 20]
    mov eax, edi
    rep movsb

    pop edi
    pop esi
    ret

libc_memset:
    push edi

    mov edi, [esp + 8]
    mov eax, [esp + 12]
    mov ecx, [esp + 16]
    mov edx, edi
    rep stosb
    mov eax, edx

    pop edi
    ret

libc_abs:
    mov eax, [esp + 4]
    test eax, eax
    jns .done
    neg eax

.done:
    ret

libc_idivmod:
    push ebx

    mov eax, [esp + 8]
    mov ebx, [esp + 12]
    cmp ebx, 0
    je .zero
    cdq
    idiv ebx
    mov ebx, [esp + 16]
    test ebx, ebx
    jz .done
    mov [ebx], edx
    jmp .done

.zero:
    xor eax, eax

.done:
    pop ebx
    ret

libc_self_test:
    mov byte [libc_test_status], 0

    push dword libc_test_source
    call libc_strlen
    add esp, 4
    cmp eax, 4
    jne .fail

    push dword libc_test_source
    push dword libc_copy_buffer
    call libc_strcpy
    add esp, 8
    cmp eax, libc_copy_buffer
    jne .fail

    push dword libc_test_source
    push dword libc_copy_buffer
    call libc_strcmp
    add esp, 8
    cmp eax, 0
    jne .fail

    push dword 5
    push dword 'Z'
    push dword libc_mem_buffer
    call libc_memset
    add esp, 12
    cmp byte [libc_mem_buffer], 'Z'
    jne .fail
    cmp byte [libc_mem_buffer + 4], 'Z'
    jne .fail

    push dword 5
    push dword libc_mem_buffer
    push dword libc_copy_buffer
    call libc_memcpy
    add esp, 12
    cmp byte [libc_copy_buffer + 4], 'Z'
    jne .fail

    push dword -42
    call libc_abs
    add esp, 4
    cmp eax, 42
    jne .fail

    push dword libc_last_remainder
    push dword 5
    push dword 42
    call libc_idivmod
    add esp, 12
    mov [libc_last_quotient], eax
    cmp eax, 8
    jne .fail
    cmp dword [libc_last_remainder], 2
    jne .fail

    cmp byte [fpu_test_status], 1
    jne .fail

    mov byte [libc_test_status], 1
    ret

.fail:
    mov byte [libc_test_status], 2
    ret

kprintf:
    push ebp
    mov ebp, esp
    push ebx
    push esi
    push edi

    mov esi, [ebp + 8]
    lea ebx, [ebp + 12]

.next:
    lodsb
    test al, al
    je .done
    cmp al, '%'
    je .specifier
    call put_char
    jmp .next

.specifier:
    lodsb
    cmp al, 0
    je .done
    cmp al, '%'
    je .literal_percent
    cmp al, 's'
    je .string
    cmp al, 'd'
    je .signed_decimal
    cmp al, 'i'
    je .signed_decimal
    cmp al, 'u'
    je .unsigned_decimal
    cmp al, 'x'
    je .hex
    cmp al, 'X'
    je .hex
    cmp al, 'c'
    je .character
    mov dl, al
    mov al, '%'
    call put_char
    mov al, dl
    call put_char
    jmp .next

.literal_percent:
    mov al, '%'
    call put_char
    jmp .next

.string:
    push esi
    mov esi, [ebx]
    add ebx, 4
    test esi, esi
    jnz .string_ok
    mov esi, null_text

.string_ok:
    call print_string
    pop esi
    jmp .next

.signed_decimal:
    mov eax, [ebx]
    add ebx, 4
    call print_signed_dec
    jmp .next

.unsigned_decimal:
    mov eax, [ebx]
    add ebx, 4
    call print_dec
    jmp .next

.hex:
    mov eax, [ebx]
    add ebx, 4
    call print_hex32
    jmp .next

.character:
    mov eax, [ebx]
    add ebx, 4
    call put_char
    jmp .next

.done:
    xor eax, eax
    pop edi
    pop esi
    pop ebx
    pop ebp
    ret

