    mov dword [sb16_music_stream_buffer_bytes], 0
    mov dword [sb16_music_stream_under_count], 0
    mov dword [sb16_music_stream_drop_count], 0
    mov dword [sb16_music_stream_mode], AUDIO_MUSIC_STREAM_NONE
    mov dword [sb16_music_pull_request_count], 0
    mov dword [sb16_music_pull_refill_count], 0
    mov dword [sb16_music_render_format], 0
    mov dword [sb16_music_render_chunk_count], 0
    mov dword [sb16_music_render_note_count], 0
    mov dword [sb16_music_render_event_count], 0
    mov dword [sb16_music_render_active_peak], 0
    mov dword [sb16_music_render_sample_count], 0
    mov dword [audio_pcm_stream_next_handle], AUDIO_PCM_HANDLE_BASE + 1
    mov dword [audio_pcm_stream_handle], 0
    mov dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    mov dword [audio_pcm_stream_active_count], 0
    mov dword [audio_pcm_stream_queued_bytes], 0
    mov dword [audio_pcm_stream_under_count], 0
    mov dword [audio_pcm_stream_drop_count], 0
    mov dword [audio_pcm_stream_pull_request_count], 0
    mov dword [audio_pcm_stream_pull_refill_count], 0
    mov dword [audio_pcm_stream_position_bytes], 0
    mov dword [audio_pcm_stream_write_count], 0
    mov dword [audio_pcm_stream_write_bytes], 0
    mov dword [audio_pcm_stream_last_write_bytes], 0
    mov dword [audio_pcm_stream_last_error], 0
    mov dword [audio_pcm_stream_last_flags], 0
    mov dword [audio_pcm_stream_source_flags], 0
    mov dword [audio_pcm_stream_final_pending], 0
    mov dword [audio_pcm_stream_open_count], 0
    mov dword [audio_pcm_stream_drain_count], 0
    mov dword [audio_pcm_stream_close_count], 0
    mov dword [audio_pcm_user_stream_write_count], 0
    mov dword [audio_pcm_user_stream_write_bytes], 0
    mov dword [audio_pcm_stream_last_open_handle], 0
    mov dword [audio_pcm_stream_last_drain_handle], 0
    mov dword [audio_pcm_stream_last_close_handle], 0
    mov dword [audio_pcm_device_last_error], 0
    mov dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_IDLE
    mov dword [audio_pcm_lifecycle_error_count], 0
    mov dword [audio_pcm_lifecycle_seq], 0
    mov dword [audio_pcm_lifecycle_open_seq], 0
    mov dword [audio_pcm_lifecycle_write_seq], 0
    mov dword [audio_pcm_lifecycle_drain_seq], 0
    mov dword [audio_pcm_lifecycle_close_seq], 0
    mov dword [audio_generic_abi_mask], 0
    mov dword [audio_generic_last_op], 0
    mov dword [audio_generic_last_cmd], 0
    mov dword [audio_pcm_ring_mixed_bytes], 0
    mov dword [audio_pcm_queue_buffer], 0
    mov dword [audio_pcm_queue_capacity], 0
    mov dword [audio_pcm_queue_head], 0
    mov dword [audio_pcm_queue_tail], 0
    mov dword [audio_pcm_queue_bytes], 0
    mov dword [audio_pcm_queue_drop_bytes], 0
    mov dword [audio_pcm_queue_overflow_count], 0
    mov dword [audio_pcm_queue_trim_count], 0
    mov dword [audio_pcm_queue_high_water_bytes], 0
    mov dword [audio_irq_count], 0
    mov dword [audio_irq_ack8_count], 0
    mov dword [audio_irq_ack16_count], 0
    mov dword [audio_irq_refill_count], 0
    mov dword [audio_irq_spurious_count], 0
    mov dword [audio_irq_last_status8], 0
    mov dword [audio_irq_last_status16], 0
    mov dword [sb16_dma_status], SB16_DMA_STATUS_IDLE
    mov dword [sb16_dma_last_error], SB16_DMA_ERROR_NONE
    mov dword [sb16_dma_last_addr], 0
    mov dword [sb16_dma_last_page], 0
    mov dword [sb16_dma_last_count], 0
    mov dword [sb16_dma_boundary_error_count], 0
    mov dword [sb16_playback_error_count], 0
    mov dword [sb16_pan_left_arg], 0
    mov dword [sb16_pan_right_arg], 0
    mov dword [sb16_mix_source_pos], 0
    mov dword [sb16_mix_source_step], AUDIO_PITCH_STEP_NORMAL
    mov dword [sb16_mix_left_volume], 0
    mov dword [sb16_mix_right_volume], 0
    mov dword [sb16_mix_frames_mixed], 0
    mov dword [sb16_mix_voice_slot], 0
    mov dword [audio_sfx_rate_arg], 0
    mov byte [audio_pcm_force_stream_arg], 0
    mov eax, AUDIO_PCM_QUEUE_BYTES
    call kalloc
    mov [audio_pcm_queue_buffer], eax
    cmp eax, 0
    je .pcm_queue_ready
    mov dword [audio_pcm_queue_capacity], AUDIO_PCM_QUEUE_BYTES
    call audio_pcm_queue_reset

.pcm_queue_ready:
    mov dword [sb16_dma_buffer_phys], sb16_dma_buffer
    mov dword [sb16_dma_buffer_size], SB16_DMA_BUFFER_BYTES
    mov dword [sb16_dma_block_size], SB16_DMA_BLOCK_BYTES
    mov byte [sb16_playback_active], 0
    call sb16_clear_dma_buffer
    call sb16_clear_active_voices
    call sb16_probe
    ret

ps2_mouse_init:
    mov byte [mouse_status], INPUT_DEVICE_STATUS_UNKNOWN
    mov byte [ps2_mouse_command_byte], 0
    call mouse_reset_queue

    mov al, PS2_COMMAND_ENABLE_AUX
    call ps2_write_command
    jc .absent

    mov al, PS2_COMMAND_READ_CONFIG
    call ps2_write_command
    jc .absent
    call ps2_read_data
    jc .absent
    or al, PS2_CONFIG_AUX_IRQ
    and al, ~PS2_CONFIG_AUX_CLOCK_DISABLE
    mov [ps2_mouse_command_byte], al

    mov al, PS2_COMMAND_WRITE_CONFIG
    call ps2_write_command
    jc .absent
    mov al, [ps2_mouse_command_byte]
    call ps2_write_data
    jc .absent

    mov al, PS2_MOUSE_SET_DEFAULTS
    call ps2_mouse_send_command
    jc .absent
    mov al, PS2_MOUSE_ENABLE_DATA
    call ps2_mouse_send_command
    jc .absent

    mov byte [mouse_status], INPUT_DEVICE_STATUS_READY
    clc
    ret

.absent:
    mov byte [mouse_status], INPUT_DEVICE_STATUS_ERROR
    stc
    ret

ps2_wait_input_clear:
    push ecx
    mov ecx, 0x00010000

.wait:
    in al, PS2_STATUS_PORT
    test al, PS2_STATUS_INPUT_FULL
    jz .ready
    loop .wait
    stc
    pop ecx
    ret

.ready:
    clc
    pop ecx
    ret

ps2_wait_output_full:
    push ecx
    mov ecx, 0x00010000

.wait:
    in al, PS2_STATUS_PORT
    test al, PS2_STATUS_OUTPUT_FULL
    jnz .ready
    loop .wait
    stc
    pop ecx
    ret

.ready:
    clc
    pop ecx
    ret

ps2_write_command:
    push edx
    push eax
    call ps2_wait_input_clear
    jc .done
    mov dx, PS2_COMMAND_PORT
    pop eax
    out dx, al
    clc
    pop edx
    ret

.done:
    pop eax
    pop edx
    ret

ps2_write_data:
    push edx
    push eax
    call ps2_wait_input_clear
    jc .done
    mov dx, PS2_DATA_PORT
    pop eax
    out dx, al
    clc
    pop edx
    ret

.done:
    pop eax
    pop edx
    ret

ps2_read_data:
    push edx
    call ps2_wait_output_full
    jc .done
    mov dx, PS2_DATA_PORT
    in al, dx
    clc

.done:
    pop edx
    ret

ps2_mouse_send_command:
    mov [ps2_mouse_command_byte], al
    mov al, PS2_COMMAND_WRITE_AUX
    call ps2_write_command
    jc .fail
    mov al, [ps2_mouse_command_byte]
    call ps2_write_data
    jc .fail
    call ps2_read_data
    jc .fail
    cmp al, PS2_MOUSE_ACK
    jne .fail
    clc
    ret

.fail:
    stc
    ret

sb16_probe:
    call sb16_reset_dsp
    jc .absent

    mov al, SB16_DSP_GET_VERSION
    call sb16_write_dsp
    jc .absent
    call sb16_read_dsp
    jc .absent
    mov [sb16_major_version], al
    call sb16_read_dsp
    jc .absent
    mov [sb16_minor_version], al
    mov byte [audio_status], 1
    call sb16_configure_mixer
    clc
    ret

.absent:
    mov byte [audio_status], 2
    stc
    ret

sb16_reset_dsp:
    mov dx, SB16_DSP_RESET
    mov al, 1
    out dx, al
    call sb16_io_delay
    xor al, al
    out dx, al
    call sb16_read_dsp
    jc .fail
    cmp al, SB16_DSP_RESET_ACK
    jne .fail
    clc
    ret

.fail:
    stc
    ret

sb16_io_delay:
    push ecx
    mov ecx, 0x1000

.delay_next:
    loop .delay_next
    pop ecx
    ret

sb16_configure_mixer:
    mov al, SB16_MIXER_IRQ_SELECT
    mov ah, SB16_MIXER_IRQ5_BIT
    call sb16_write_mixer
    mov al, SB16_MIXER_DMA_SELECT
    mov ah, SB16_MIXER_DMA_CH1_BIT | SB16_MIXER_DMA_CH5_BIT
    call sb16_write_mixer
    ret

sb16_write_mixer:
    push edx
    mov dx, SB16_MIXER_ADDR
    out dx, al
    call sb16_io_delay
    mov dx, SB16_MIXER_DATA
    mov al, ah
    out dx, al
    call sb16_io_delay
    pop edx
    ret

sb16_clear_dma_buffer:
    push eax
    push ecx
    push edi
    mov edi, sb16_dma_buffer
    mov eax, 0x80808080
    mov ecx, SB16_DMA_BUFFER_BYTES / 4
    cld
    rep stosd
    mov dword [sb16_dma_write_pos], 0
    mov dword [sb16_irq_half_index], 0
    pop edi
    pop ecx
    pop eax
    ret

sb16_clear_active_voices:
    push eax
    push ecx
    push edi

    mov edi, sb16_voice_active
    xor eax, eax
    mov ecx, AUDIO_MAX_SFX_VOICES
    cld
    rep stosb

    mov edi, sb16_voice_handles
    mov ecx, AUDIO_MAX_SFX_VOICES * 15
    cld
    rep stosd

    mov dword [sb16_active_voice_count], 0
    mov dword [sb16_active_sfx_voice_count], 0
    mov dword [sb16_active_music_voice_count], 0
    mov dword [sb16_voice_age_counter], 0
    mov dword [sb16_music_stream_buffer_bytes], 0
    mov dword [sb16_music_stream_mode], AUDIO_STREAM_NONE
    call audio_pcm_stream_stop_current

    pop edi
    pop ecx
    pop eax
    ret

audio_sync_pcm_stream_state:
    push eax

    cmp dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    jne .generic_active
    cmp dword [audio_pcm_queue_bytes], 0
    jne .generic_active
    cmp dword [audio_pcm_stream_handle], 0
    jne .generic_active

    mov eax, [sb16_active_music_voice_count]
    mov [audio_pcm_stream_active_count], eax
    mov eax, [sb16_music_stream_buffer_bytes]
    mov [audio_pcm_stream_queued_bytes], eax
    mov eax, [sb16_music_stream_under_count]
    mov [audio_pcm_stream_under_count], eax
    mov eax, [sb16_music_stream_drop_count]
    mov [audio_pcm_stream_drop_count], eax
    mov eax, [sb16_music_pull_request_count]
    mov [audio_pcm_stream_pull_request_count], eax
    mov eax, [sb16_music_pull_refill_count]
    mov [audio_pcm_stream_pull_refill_count], eax
    cmp dword [audio_pcm_stream_active_count], 0
    jne .active
    mov dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    mov dword [audio_pcm_stream_handle], 0
    mov dword [audio_pcm_stream_source_flags], 0
    mov dword [audio_pcm_stream_final_pending], 0
    jmp .done

.active:
    mov eax, [sb16_music_stream_mode]
    mov [audio_pcm_stream_mode], eax
    mov dword [audio_pcm_stream_source_flags], AUDIO_FLAG_MUSIC | AUDIO_FLAG_STREAM
    jmp .done

.generic_active:
    mov eax, [audio_pcm_queue_bytes]
    mov [audio_pcm_stream_queued_bytes], eax
    cmp dword [audio_pcm_stream_handle], 0
    jne .generic_has_handle
    cmp eax, 0
    jne .generic_has_handle
    mov dword [audio_pcm_stream_active_count], 0
    mov dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    jmp .done

.generic_has_handle:
    mov dword [audio_pcm_stream_active_count], 1
    mov dword [audio_pcm_stream_mode], AUDIO_STREAM_PULL
    test dword [audio_pcm_stream_source_flags], AUDIO_FLAG_MUSIC
    jz .generic_not_music
    mov dword [sb16_active_music_voice_count], 1
    mov dword [sb16_music_stream_mode], AUDIO_MUSIC_STREAM_PULL
    mov eax, [audio_pcm_queue_bytes]
    mov [sb16_music_stream_buffer_bytes], eax
    mov eax, [audio_pcm_stream_under_count]
    mov [sb16_music_stream_under_count], eax
    mov eax, [audio_pcm_stream_drop_count]
    mov [sb16_music_stream_drop_count], eax
    mov eax, [audio_pcm_stream_pull_request_count]
    mov [sb16_music_pull_request_count], eax
    mov eax, [audio_pcm_stream_pull_refill_count]
    mov [sb16_music_pull_refill_count], eax
    jmp .done

.generic_not_music:
    mov dword [sb16_active_music_voice_count], 0
    mov dword [sb16_music_stream_mode], AUDIO_MUSIC_STREAM_NONE
    mov dword [sb16_music_stream_buffer_bytes], 0
    mov dword [sb16_music_pull_request_count], 0
    mov dword [sb16_music_pull_refill_count], 0

.done:
    pop eax
    ret

audio_note_pcm_stream_write:
    push eax

    inc dword [audio_pcm_stream_write_count]
    mov eax, [audio_sfx_length_arg]
    add [audio_pcm_stream_write_bytes], eax
    mov [audio_pcm_stream_last_write_bytes], eax
    mov eax, [audio_sfx_flags_arg]
    mov [audio_pcm_stream_last_flags], eax
    mov eax, [audio_sfx_handle_arg]
    mov [audio_pcm_stream_handle], eax
    mov dword [audio_pcm_stream_mode], AUDIO_STREAM_PULL
    mov dword [audio_pcm_stream_last_error], 0

    pop eax
    ret

audio_pcm_queue_reset:
    push eax
    push ecx
    push edi

    mov edi, [audio_pcm_queue_buffer]
    cmp edi, 0
    je .offsets_ready
    mov eax, 0x80808080
    mov ecx, AUDIO_PCM_QUEUE_BYTES / 4
    cld
    rep stosd

.offsets_ready:
    mov dword [audio_pcm_queue_head], 0
    mov dword [audio_pcm_queue_tail], 0
    mov dword [audio_pcm_queue_bytes], 0
    mov dword [audio_pcm_stream_queued_bytes], 0

    pop edi
    pop ecx
    pop eax
    ret

audio_pcm_stream_stop_current:
    push eax

    call audio_pcm_queue_reset
    mov dword [audio_pcm_stream_handle], 0
    mov dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    mov dword [audio_pcm_stream_active_count], 0
    mov dword [audio_pcm_stream_source_flags], 0
    mov dword [audio_pcm_stream_final_pending], 0
    mov dword [sb16_music_stream_buffer_bytes], 0
    mov dword [sb16_music_stream_mode], AUDIO_MUSIC_STREAM_NONE
    mov dword [sb16_active_music_voice_count], 0

    pop eax
    ret

audio_pcm_mark_pull_refill:
    push eax

    mov eax, [audio_pcm_stream_pull_request_count]
    cmp [audio_pcm_stream_pull_refill_count], eax
    jae .mirror_music
    inc dword [audio_pcm_stream_pull_refill_count]

.mirror_music:
    test dword [audio_pcm_stream_source_flags], AUDIO_FLAG_MUSIC
    jz .done
    mov eax, [audio_pcm_stream_pull_request_count]
    mov [sb16_music_pull_request_count], eax
    mov eax, [audio_pcm_stream_pull_refill_count]
    mov [sb16_music_pull_refill_count], eax

.done:
    pop eax
    ret

audio_pcm_note_pull_request:
    push eax

    cmp dword [audio_pcm_stream_mode], AUDIO_STREAM_PULL
    jne .done
    cmp dword [audio_pcm_stream_active_count], 0
    je .done
    cmp dword [audio_pcm_stream_final_pending], 0
    jne .done
    mov eax, [audio_pcm_queue_bytes]
    cmp eax, AUDIO_PCM_PULL_LOW_WATER_BYTES
    ja .done
    mov eax, [audio_pcm_stream_pull_request_count]
    cmp eax, [audio_pcm_stream_pull_refill_count]
    jne .done
    inc dword [audio_pcm_stream_pull_request_count]
    test dword [audio_pcm_stream_source_flags], AUDIO_FLAG_MUSIC
    jz .done
    mov eax, [audio_pcm_stream_pull_request_count]
    mov [sb16_music_pull_request_count], eax
    mov eax, [audio_pcm_stream_pull_refill_count]
    mov [sb16_music_pull_refill_count], eax

.done:
    pop eax
    ret

audio_pcm_note_lifecycle_open:
    push eax

    inc dword [audio_pcm_lifecycle_seq]
    mov eax, [audio_pcm_lifecycle_seq]
    mov [audio_pcm_lifecycle_open_seq], eax
    mov dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_OPEN

    pop eax
    ret

audio_pcm_note_lifecycle_write:
    push eax

    cmp dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_IDLE
    je .implicit_open
    cmp dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_CLOSED
    je .implicit_open
    cmp dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_OPEN
    je .state_ok
    cmp dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_WRITTEN
    je .state_ok
    inc dword [audio_pcm_lifecycle_error_count]
    jmp .state_ok

.implicit_open:
    inc dword [audio_pcm_lifecycle_seq]
    mov eax, [audio_pcm_lifecycle_seq]
    mov [audio_pcm_lifecycle_open_seq], eax
    mov dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_OPEN

.state_ok:
    inc dword [audio_pcm_lifecycle_seq]
    mov eax, [audio_pcm_lifecycle_seq]
    mov [audio_pcm_lifecycle_write_seq], eax
    mov dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_WRITTEN

    pop eax
    ret

audio_pcm_note_lifecycle_drain:
    push eax

    cmp dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_WRITTEN
    je .state_ok
    cmp dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_DRAINING
    je .state_ok
    inc dword [audio_pcm_lifecycle_error_count]

.state_ok:
    inc dword [audio_pcm_lifecycle_seq]
    mov eax, [audio_pcm_lifecycle_seq]
    mov [audio_pcm_lifecycle_drain_seq], eax
    mov dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_DRAINING

    pop eax
    ret

audio_pcm_note_lifecycle_close:
    push eax

    cmp dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_DRAINING
    je .state_ok
    inc dword [audio_pcm_lifecycle_error_count]

.state_ok:
    inc dword [audio_pcm_lifecycle_seq]
    mov eax, [audio_pcm_lifecycle_seq]
    mov [audio_pcm_lifecycle_close_seq], eax
    mov dword [audio_pcm_lifecycle_state], AUDIO_PCM_LIFECYCLE_CLOSED

    pop eax
    ret

audio_pcm_open_stream:
    push ebx
    push ecx
    push edx
    push esi

    cmp dword [audio_pcm_queue_buffer], 0
    je .io_error
    cmp dword [audio_pcm_queue_capacity], AUDIO_PCM_QUEUE_BYTES
    jne .io_error
    cmp edx, 0
    je .format_ready

    mov eax, edx
    mov ebx, AUDIO_PCM_DESC_BYTES
    call user_range_validate
    jc .invalid
    mov esi, edx
    cmp dword [esi + AUDIO_PCM_DESC_SAMPLE_RATE], SB16_SAMPLE_RATE
    jne .invalid
    cmp dword [esi + AUDIO_PCM_DESC_CHANNELS], 2
    jne .invalid
    cmp dword [esi + AUDIO_PCM_DESC_FORMAT], AUDIO_PCM_FORMAT_U8_STEREO
    jne .invalid

.format_ready:
    call audio_pcm_queue_reset
    mov dword [audio_pcm_stream_pull_request_count], 0
    mov dword [audio_pcm_stream_pull_refill_count], 0
    mov dword [audio_pcm_stream_under_count], 0
    mov dword [audio_pcm_stream_drop_count], 0
    mov dword [audio_pcm_stream_position_bytes], 0
    mov dword [audio_pcm_stream_write_count], 0
    mov dword [audio_pcm_stream_write_bytes], 0
    mov dword [audio_pcm_stream_last_write_bytes], 0
    mov dword [audio_pcm_stream_last_flags], 0
    mov dword [audio_pcm_stream_source_flags], AUDIO_FLAG_STREAM
    mov dword [audio_pcm_stream_final_pending], 0
    mov eax, [audio_pcm_stream_next_handle]
    mov [audio_pcm_stream_handle], eax
    mov [audio_pcm_stream_last_open_handle], eax
    inc dword [audio_pcm_stream_next_handle]
    mov dword [audio_pcm_stream_mode], AUDIO_STREAM_PULL
    mov dword [audio_pcm_stream_active_count], 1
    inc dword [audio_pcm_stream_open_count]
    call audio_pcm_note_lifecycle_open

    mov dword [audio_pcm_stream_last_error], 0
    mov dword [audio_pcm_device_last_error], 0
    call audio_sync_pcm_stream_state
    mov eax, [audio_pcm_stream_last_open_handle]
    clc
    jmp .done

.io_error:
    mov dword [audio_pcm_stream_last_error], -ERRNO_EIO
    mov dword [audio_pcm_device_last_error], -ERRNO_EIO
    mov eax, -ERRNO_EIO
    stc
    jmp .done

.invalid:
    inc dword [audio_pcm_stream_under_count]
    inc dword [audio_pcm_stream_drop_count]
    mov dword [audio_pcm_stream_last_error], -ERRNO_EINVAL
    mov dword [audio_pcm_device_last_error], -ERRNO_EINVAL
    mov eax, -ERRNO_EINVAL
    stc

.done:
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

audio_pcm_drain_stream:
    push ebx

    cmp ecx, 0
    je .invalid
    cmp ecx, [audio_pcm_stream_handle]
    jne .invalid
    cmp dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    je .invalid

    inc dword [audio_pcm_stream_drain_count]
    mov [audio_pcm_stream_last_drain_handle], ecx
    call audio_pcm_note_lifecycle_drain

    mov dword [audio_pcm_stream_final_pending], 1
    mov dword [audio_pcm_stream_last_error], 0
    mov dword [audio_pcm_device_last_error], 0
    call audio_sync_pcm_stream_state
    mov eax, [audio_pcm_stream_queued_bytes]
    clc
    jmp .done

.invalid:
    mov dword [audio_pcm_stream_last_error], -ERRNO_EINVAL
    mov dword [audio_pcm_device_last_error], -ERRNO_EINVAL
    mov eax, -ERRNO_EINVAL
    stc

.done:
    pop ebx
    ret

audio_pcm_close_stream:
    push ebx

    cmp ecx, 0
    je .invalid
    cmp ecx, [audio_pcm_stream_handle]
    jne .invalid
    cmp dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    je .invalid

    inc dword [audio_pcm_stream_close_count]
    mov [audio_pcm_stream_last_close_handle], ecx
    call audio_pcm_note_lifecycle_close

    mov dword [audio_pcm_stream_last_error], 0
    mov dword [audio_pcm_device_last_error], 0
    call audio_pcm_stream_stop_current
    xor eax, eax
    clc
    jmp .done

.invalid:
    mov dword [audio_pcm_stream_last_error], -ERRNO_EINVAL
    mov dword [audio_pcm_device_last_error], -ERRNO_EINVAL
    mov eax, -ERRNO_EINVAL
    stc

.done:
    pop ebx
    ret

audio_pcm_stream_write:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi
    push ebp

    mov dword [audio_pcm_stream_last_write_bytes], 0
    mov dword [audio_pcm_stream_last_error], 0
    cmp dword [audio_pcm_queue_buffer], 0
    je .io_error
    cmp dword [audio_pcm_queue_capacity], AUDIO_PCM_QUEUE_BYTES
    jne .io_error

    mov eax, [audio_sfx_desc_arg]
    mov ebx, AUDIO_SFX_DESC_BYTES
    call user_range_validate
    jc .invalid

    mov esi, [audio_sfx_desc_arg]
    mov eax, [esi + AUDIO_SFX_DESC_SAMPLES]
    mov [audio_sfx_sample_arg], eax
    mov ebx, [esi + AUDIO_SFX_DESC_LENGTH]
    mov [audio_sfx_length_arg], ebx
    mov eax, [esi + AUDIO_SFX_DESC_VOLUME]
    and eax, 0xff
    mov [audio_sfx_volume_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_SEPARATION]
    and eax, 0xff
    mov [audio_sfx_separation_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_PITCH]
    and eax, 0xff
    mov [audio_sfx_pitch_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_SOUND_ID]
    mov [audio_sfx_id_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_FLAGS]
    or eax, AUDIO_FLAG_STREAM
    mov [audio_sfx_flags_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_SAMPLE_RATE]
    mov [audio_sfx_rate_arg], eax
    mov eax, [audio_sfx_handle_arg]
    and eax, AUDIO_MUSIC_HANDLE_MASK
    cmp eax, AUDIO_MUSIC_HANDLE_BASE
    jne .music_flag_ready
    or dword [audio_sfx_flags_arg], AUDIO_FLAG_MUSIC

.music_flag_ready:
    cmp dword [audio_sfx_length_arg], 0
    je .invalid
    cmp dword [audio_sfx_length_arg], AUDIO_PCM_QUEUE_BYTES
    jbe .length_ready
    mov eax, [audio_sfx_length_arg]
    sub eax, AUDIO_PCM_QUEUE_BYTES
    add [audio_sfx_sample_arg], eax
    add [audio_pcm_queue_drop_bytes], eax
    add [audio_pcm_stream_drop_count], eax
    inc dword [audio_pcm_queue_trim_count]
    mov dword [audio_sfx_length_arg], AUDIO_PCM_QUEUE_BYTES

.length_ready:
    mov eax, [audio_sfx_sample_arg]
    mov ebx, [audio_sfx_length_arg]
    call user_range_validate
    jc .invalid

    xor ebp, ebp
    mov eax, [audio_sfx_handle_arg]
    cmp eax, [audio_pcm_stream_handle]
    je .same_handle
    mov ebp, 1
    call audio_pcm_queue_reset
    mov dword [audio_pcm_stream_pull_request_count], 0
    mov dword [audio_pcm_stream_pull_refill_count], 0
    mov dword [audio_pcm_stream_under_count], 0
    mov dword [audio_pcm_stream_drop_count], 0
    mov dword [audio_pcm_stream_position_bytes], 0

.same_handle:
    cmp dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    jne .handle_ready
    mov ebp, 1

.handle_ready:
    test dword [audio_sfx_flags_arg], AUDIO_FLAG_MUSIC
    jz .render_stats_ready
    call sb16_record_music_render_stats

.render_stats_ready:
    mov esi, [audio_sfx_sample_arg]
    mov ecx, [audio_sfx_length_arg]
    mov ebx, [audio_pcm_queue_buffer]
    cld

.copy_next:
    cmp ecx, 0
    je .copy_done
    cmp dword [audio_pcm_queue_bytes], AUDIO_PCM_QUEUE_BYTES
    jb .space_ready
    mov eax, [audio_pcm_queue_tail]
    inc eax
    and eax, AUDIO_PCM_QUEUE_MASK
    mov [audio_pcm_queue_tail], eax
    inc dword [audio_pcm_queue_drop_bytes]
    inc dword [audio_pcm_stream_drop_count]
    inc dword [audio_pcm_queue_overflow_count]
    jmp .write_byte

.space_ready:
    inc dword [audio_pcm_queue_bytes]
    mov eax, [audio_pcm_queue_bytes]
    cmp eax, [audio_pcm_queue_high_water_bytes]
    jbe .write_byte
    mov [audio_pcm_queue_high_water_bytes], eax

.write_byte:
    mov edi, ebx
    add edi, [audio_pcm_queue_head]
    lodsb
    mov [edi], al
    mov eax, [audio_pcm_queue_head]
    inc eax
    and eax, AUDIO_PCM_QUEUE_MASK
    mov [audio_pcm_queue_head], eax
    dec ecx
    jmp .copy_next

.copy_done:
    inc dword [audio_pcm_stream_write_count]
    mov eax, [audio_sfx_length_arg]
    add [audio_pcm_stream_write_bytes], eax
    mov [audio_pcm_stream_last_write_bytes], eax
    inc dword [audio_pcm_user_stream_write_count]
    add [audio_pcm_user_stream_write_bytes], eax
    call audio_pcm_note_lifecycle_write
    mov dword [audio_pcm_device_last_error], 0

    mov eax, [audio_sfx_flags_arg]
    mov [audio_pcm_stream_last_flags], eax
    mov [audio_pcm_stream_source_flags], eax
    mov eax, [audio_sfx_handle_arg]
    mov [audio_pcm_stream_handle], eax
    mov dword [audio_pcm_stream_mode], AUDIO_STREAM_PULL
    mov dword [audio_pcm_stream_active_count], 1
    mov eax, [audio_pcm_queue_bytes]
    mov [audio_pcm_stream_queued_bytes], eax
    test dword [audio_sfx_flags_arg], AUDIO_FLAG_STREAM_FINAL
    jz .clear_final_pending
    mov dword [audio_pcm_stream_final_pending], 1
    jmp .final_ready

.clear_final_pending:
    mov dword [audio_pcm_stream_final_pending], 0

.final_ready:
    call audio_pcm_mark_pull_refill
    test dword [audio_sfx_flags_arg], AUDIO_FLAG_MUSIC
    jz .sync_done
    cmp ebp, 0
    je .music_started
    inc dword [sb16_music_start_count]

.music_started:
    mov dword [sb16_active_music_voice_count], 1
    mov dword [sb16_music_stream_mode], AUDIO_MUSIC_STREAM_PULL
    mov eax, [audio_pcm_queue_bytes]
    mov [sb16_music_stream_buffer_bytes], eax

.sync_done:
    call audio_sync_pcm_stream_state
    clc
    jmp .done

.io_error:
    mov dword [audio_pcm_stream_last_error], -ERRNO_EIO
    mov dword [audio_pcm_device_last_error], -ERRNO_EIO

    stc
    jmp .done

.invalid:
    inc dword [audio_pcm_stream_under_count]
    inc dword [audio_pcm_stream_drop_count]
    mov dword [audio_pcm_stream_last_error], -ERRNO_EINVAL
    mov dword [audio_pcm_device_last_error], -ERRNO_EINVAL

    stc

.done:
    pop ebp
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

audio_pcm_desc_stream_write:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi
    push ebp

    mov dword [audio_pcm_stream_last_write_bytes], 0
    mov dword [audio_pcm_stream_last_error], 0
    cmp dword [audio_pcm_queue_buffer], 0
    je .io_error
    cmp dword [audio_pcm_queue_capacity], AUDIO_PCM_QUEUE_BYTES
    jne .io_error

    mov eax, [audio_sfx_desc_arg]
    mov ebx, AUDIO_PCM_DESC_BYTES
    call user_range_validate
    jc .invalid

    mov esi, [audio_sfx_desc_arg]
    mov eax, [esi + AUDIO_PCM_DESC_SAMPLES]
    mov [audio_sfx_sample_arg], eax
    mov ebx, [esi + AUDIO_PCM_DESC_LENGTH]
    mov [audio_sfx_length_arg], ebx
    mov eax, [esi + AUDIO_PCM_DESC_SAMPLE_RATE]
    mov [audio_sfx_rate_arg], eax
    cmp eax, SB16_SAMPLE_RATE
    jne .invalid
    mov eax, [esi + AUDIO_PCM_DESC_CHANNELS]
    cmp eax, 2
    jne .invalid
    mov eax, [esi + AUDIO_PCM_DESC_FORMAT]
    cmp eax, AUDIO_PCM_FORMAT_U8_STEREO
    jne .invalid
    mov dword [audio_sfx_volume_arg], 127
    mov dword [audio_sfx_separation_arg], AUDIO_PITCH_NORMAL
    mov dword [audio_sfx_pitch_arg], AUDIO_PITCH_NORMAL
    mov dword [audio_sfx_id_arg], 0
    mov eax, [esi + AUDIO_PCM_DESC_FLAGS]
    and eax, AUDIO_FLAG_STREAM_FINAL
    or eax, AUDIO_FLAG_STREAM
    mov [audio_sfx_flags_arg], eax

    cmp dword [audio_sfx_length_arg], 0
    je .invalid
    cmp dword [audio_sfx_length_arg], AUDIO_PCM_QUEUE_BYTES
    jbe .length_ready
    mov eax, [audio_sfx_length_arg]
    sub eax, AUDIO_PCM_QUEUE_BYTES
    add [audio_sfx_sample_arg], eax
    add [audio_pcm_queue_drop_bytes], eax
    add [audio_pcm_stream_drop_count], eax
    inc dword [audio_pcm_queue_trim_count]
    mov dword [audio_sfx_length_arg], AUDIO_PCM_QUEUE_BYTES

.length_ready:
    mov eax, [audio_sfx_sample_arg]
    mov ebx, [audio_sfx_length_arg]
    call user_range_validate
    jc .invalid

    xor ebp, ebp
    mov eax, [audio_sfx_handle_arg]
    cmp eax, [audio_pcm_stream_handle]
    je .same_handle
    mov ebp, 1
    call audio_pcm_queue_reset
    mov dword [audio_pcm_stream_pull_request_count], 0
    mov dword [audio_pcm_stream_pull_refill_count], 0
    mov dword [audio_pcm_stream_under_count], 0
    mov dword [audio_pcm_stream_drop_count], 0
    mov dword [audio_pcm_stream_position_bytes], 0

.same_handle:
    cmp dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    jne .handle_ready
    mov ebp, 1

.handle_ready:
    mov esi, [audio_sfx_sample_arg]
    mov ecx, [audio_sfx_length_arg]
    mov ebx, [audio_pcm_queue_buffer]
    cld

.copy_next:
    cmp ecx, 0
    je .copy_done
    cmp dword [audio_pcm_queue_bytes], AUDIO_PCM_QUEUE_BYTES
    jb .space_ready
    mov eax, [audio_pcm_queue_tail]
    inc eax
    and eax, AUDIO_PCM_QUEUE_MASK
    mov [audio_pcm_queue_tail], eax
    inc dword [audio_pcm_queue_drop_bytes]
    inc dword [audio_pcm_stream_drop_count]
    inc dword [audio_pcm_queue_overflow_count]
    jmp .write_byte

.space_ready:
    inc dword [audio_pcm_queue_bytes]
    mov eax, [audio_pcm_queue_bytes]
    cmp eax, [audio_pcm_queue_high_water_bytes]
    jbe .write_byte
    mov [audio_pcm_queue_high_water_bytes], eax

.write_byte:
    mov edi, ebx
    add edi, [audio_pcm_queue_head]
    lodsb
    mov [edi], al
    mov eax, [audio_pcm_queue_head]
    inc eax
    and eax, AUDIO_PCM_QUEUE_MASK
    mov [audio_pcm_queue_head], eax
    dec ecx
    jmp .copy_next

.copy_done:
    inc dword [audio_pcm_stream_write_count]
    mov eax, [audio_sfx_length_arg]
    add [audio_pcm_stream_write_bytes], eax
    mov [audio_pcm_stream_last_write_bytes], eax
    inc dword [audio_pcm_user_stream_write_count]
    add [audio_pcm_user_stream_write_bytes], eax
    call audio_pcm_note_lifecycle_write
    mov dword [audio_pcm_device_last_error], 0

    mov eax, [audio_sfx_flags_arg]
    mov [audio_pcm_stream_last_flags], eax
    mov [audio_pcm_stream_source_flags], eax
    mov eax, [audio_sfx_handle_arg]
    mov [audio_pcm_stream_handle], eax
    mov dword [audio_pcm_stream_mode], AUDIO_STREAM_PULL
    mov dword [audio_pcm_stream_active_count], 1
    mov eax, [audio_pcm_queue_bytes]
    mov [audio_pcm_stream_queued_bytes], eax
    test dword [audio_sfx_flags_arg], AUDIO_FLAG_STREAM_FINAL
    jz .clear_final_pending
    mov dword [audio_pcm_stream_final_pending], 1
    jmp .final_ready

.clear_final_pending:
    mov dword [audio_pcm_stream_final_pending], 0

.final_ready:
    call audio_pcm_mark_pull_refill
    call audio_sync_pcm_stream_state
    clc
    jmp .done

.io_error:
    mov dword [audio_pcm_stream_last_error], -ERRNO_EIO
    mov dword [audio_pcm_device_last_error], -ERRNO_EIO

    stc
    jmp .done

.invalid:
    inc dword [audio_pcm_stream_under_count]
    inc dword [audio_pcm_stream_drop_count]
    mov dword [audio_pcm_stream_last_error], -ERRNO_EINVAL
    mov dword [audio_pcm_device_last_error], -ERRNO_EINVAL

    stc

.done:
    pop ebp
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

audio_pcm_drain_to_dma:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    cmp dword [audio_pcm_stream_mode], AUDIO_STREAM_PULL
    jne .done
    cmp dword [audio_pcm_stream_active_count], 0
    je .done
    cmp dword [audio_pcm_queue_buffer], 0
    je .underrun
    mov ecx, [audio_pcm_queue_bytes]
    cmp ecx, 0
    je .empty
    cmp ecx, SB16_DMA_BLOCK_BYTES
    jbe .count_ready
    mov ecx, SB16_DMA_BLOCK_BYTES

.count_ready:
    mov edx, ecx
    mov ebx, [audio_pcm_queue_buffer]
    mov edi, [sb16_refill_dest_base]

.drain_next:
    cmp ecx, 0
    je .drain_done
    mov esi, ebx
    add esi, [audio_pcm_queue_tail]
    mov al, [esi]
    mov [edi], al
    inc edi
    mov eax, [audio_pcm_queue_tail]
    inc eax
    and eax, AUDIO_PCM_QUEUE_MASK
    mov [audio_pcm_queue_tail], eax
    dec dword [audio_pcm_queue_bytes]
    dec ecx
    jmp .drain_next

.drain_done:
    add [audio_pcm_stream_position_bytes], edx
    add [audio_pcm_ring_mixed_bytes], edx
    mov eax, [audio_pcm_queue_bytes]
    mov [audio_pcm_stream_queued_bytes], eax
    test dword [audio_pcm_stream_source_flags], AUDIO_FLAG_MUSIC
    jz .post_drain
    inc dword [sb16_music_mix_count]
    add [sb16_music_mix_bytes], edx
    add [sb16_music_stream_pos_bytes], edx
    mov [sb16_music_stream_buffer_bytes], eax
    mov dword [sb16_active_music_voice_count], 1
    mov dword [sb16_music_stream_mode], AUDIO_MUSIC_STREAM_PULL

.post_drain:
    cmp edx, SB16_DMA_BLOCK_BYTES
    je .request_check
    inc dword [audio_pcm_stream_under_count]
    test dword [audio_pcm_stream_source_flags], AUDIO_FLAG_MUSIC
    jz .request_check
    inc dword [sb16_music_stream_under_count]

.request_check:
    cmp dword [audio_pcm_queue_bytes], 0
    jne .note_request
    cmp dword [audio_pcm_stream_final_pending], 0
    je .note_request
    test dword [audio_pcm_stream_source_flags], AUDIO_FLAG_MUSIC
    jz .stop_final
    inc dword [sb16_music_stop_count]

.stop_final:
    call audio_pcm_stream_stop_current
    jmp .done

.note_request:
    call audio_pcm_note_pull_request
    jmp .done

.empty:
    cmp dword [audio_pcm_stream_final_pending], 0
    jne .stop_final

.underrun:
    inc dword [audio_pcm_stream_under_count]
    test dword [audio_pcm_stream_source_flags], AUDIO_FLAG_MUSIC
    jz .empty_request
    inc dword [sb16_music_stream_under_count]

.empty_request:
    call audio_pcm_note_pull_request

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

sb16_recount_active_voices:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi
    push ebp

    xor eax, eax
    xor ebx, ebx
    xor edx, edx
    xor esi, esi
    xor ebp, ebp
    mov ecx, AUDIO_MAX_SFX_VOICES

.next:
    cmp byte [sb16_voice_active + ebx], 1
    jne .skip
    inc eax
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_MUSIC
    jnz .count_music
    inc esi
    jmp .skip

.count_music:
    inc edx
    mov edi, [sb16_voice_positions + ebx * 4]
    shr edi, 16
    mov [sb16_music_stream_calc_pos], edi
    mov edi, [sb16_voice_lengths + ebx * 4]
    cmp edi, [sb16_music_stream_calc_pos]
    jbe .count_pending
    sub edi, [sb16_music_stream_calc_pos]
    add ebp, edi

.count_pending:
    mov edi, [sb16_voice_pending_lengths + ebx * 4]
    add ebp, edi
    jmp .skip

.skip:
    inc ebx
    loop .next
    mov [sb16_active_voice_count], eax
    mov [sb16_active_sfx_voice_count], esi
    mov [sb16_active_music_voice_count], edx
    mov [sb16_music_stream_buffer_bytes], ebp
    call audio_sync_pcm_stream_state

    pop ebp
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

sb16_find_voice_by_handle:
    push ebx
    push ecx

    mov eax, [audio_sfx_handle_arg]
    xor ebx, ebx
    mov ecx, AUDIO_MAX_SFX_VOICES

.next:
    cmp byte [sb16_voice_active + ebx], 1
    jne .skip
    cmp [sb16_voice_handles + ebx * 4], eax
    je .found

.skip:
    inc ebx
    loop .next
    stc
    jmp .done

.found:
    mov eax, ebx
    clc

.done:
    pop ecx
    pop ebx
    ret

sb16_find_free_voice:
    push ebx
    push ecx

    xor ebx, ebx
    mov ecx, AUDIO_MAX_SFX_VOICES

.next:
    cmp byte [sb16_voice_active + ebx], 0
    je .found
    inc ebx
    loop .next
    stc
    jmp .done

.found:
    mov eax, ebx
    clc

.done:
    pop ecx
    pop ebx
    ret

sb16_find_steal_voice:
    push ebx
    push ecx
    push edx
    push esi

    xor esi, esi
    xor eax, eax
    xor ebx, ebx
    mov edx, 0xffffffff
    mov ecx, AUDIO_MAX_SFX_VOICES

.next:
    cmp byte [sb16_voice_active + ebx], 1
    jne .skip
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_MUSIC
    jnz .skip
    cmp [sb16_voice_started_at + ebx * 4], edx
    jae .skip
    mov edx, [sb16_voice_started_at + ebx * 4]
    mov eax, ebx
    mov esi, 1

.skip:
    inc ebx
    loop .next
    cmp esi, 1
    je .found

    xor eax, eax
    xor ebx, ebx
    mov edx, [sb16_voice_started_at]
    mov ecx, AUDIO_MAX_SFX_VOICES

.fallback_next:
    cmp [sb16_voice_started_at + ebx * 4], edx
    jae .fallback_skip
    mov edx, [sb16_voice_started_at + ebx * 4]
    mov eax, ebx

.fallback_skip:
    inc ebx
    loop .fallback_next

.found:
    inc dword [sb16_voice_steal_count]
    clc

    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

sb16_pitch_to_step:
    push ebx

    and eax, 0xff
    cmp eax, AUDIO_PITCH_NORMAL
    jae .high_pitch

    mov ebx, AUDIO_PITCH_NORMAL
    sub ebx, eax
    cmp ebx, 64
    ja .low_outer_octave
    mov eax, ebx
    shl eax, 9
    mov ebx, AUDIO_PITCH_STEP_NORMAL
    sub ebx, eax
    mov eax, ebx
    jmp .done

.low_outer_octave:
    sub ebx, 64
    mov eax, ebx
    shl eax, 8
    mov ebx, 0x00008000
    sub ebx, eax
    cmp ebx, AUDIO_PITCH_STEP_MIN
    jae .low_ready
    mov ebx, AUDIO_PITCH_STEP_MIN
    inc dword [sb16_pitch_clamp_count]

.low_ready:
    mov eax, ebx
    jmp .done

.high_pitch:
    sub eax, AUDIO_PITCH_NORMAL
    cmp eax, 64
    ja .high_outer_octave
    shl eax, 10
    add eax, AUDIO_PITCH_STEP_NORMAL
    jmp .done

.high_outer_octave:
    sub eax, 64
    shl eax, 11
    add eax, 0x00020000

.done:
    pop ebx
    ret

sb16_compute_pan_from_args:
    push eax
    push ebx
    push ecx
    push edx

    mov ecx, [audio_sfx_volume_arg]
    and ecx, 0xff
    cmp ecx, 127
    jbe .volume_ready
    mov ecx, 127
    inc dword [sb16_pan_clamp_count]

.volume_ready:
    mov eax, [audio_sfx_separation_arg]
    and eax, 0xff
    inc eax
    mov ebx, eax
    imul ebx, ebx
    mov eax, ecx
    imul eax, ebx
    shr eax, 16
    mov edx, ecx
    sub edx, eax
    cmp edx, 127
    jle .left_low_check
    mov edx, 127
    inc dword [sb16_pan_clamp_count]
    jmp .left_ready

.left_low_check:
    cmp edx, 0
    jge .left_ready
    xor edx, edx
    inc dword [sb16_pan_clamp_count]

.left_ready:
    mov [sb16_pan_left_arg], edx

    mov eax, [audio_sfx_separation_arg]
    and eax, 0xff
    inc eax
    sub eax, 257
    imul eax, eax
    mov ebx, eax
    mov eax, ecx
    imul eax, ebx
    shr eax, 16
    mov edx, ecx
    sub edx, eax
    cmp edx, 127
    jle .right_low_check
    mov edx, 127
    inc dword [sb16_pan_clamp_count]
    jmp .right_ready

.right_low_check:
    cmp edx, 0
    jge .right_ready
    xor edx, edx
    inc dword [sb16_pan_clamp_count]

.right_ready:
    mov [sb16_pan_right_arg], edx

    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

audio_mix_sfx_descriptor:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi
    push ebp

    mov eax, [audio_sfx_desc_arg]
    mov ebx, AUDIO_SFX_DESC_BYTES
    call user_range_validate
    jc .underrun

    mov esi, [audio_sfx_desc_arg]
    mov eax, [esi + AUDIO_SFX_DESC_SAMPLES]
    mov ebx, [esi + AUDIO_SFX_DESC_LENGTH]
    mov [audio_sfx_sample_arg], eax
    mov [audio_sfx_length_arg], ebx
    mov eax, [esi + AUDIO_SFX_DESC_VOLUME]
    and eax, 0xff
    mov [audio_sfx_volume_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_SEPARATION]
    and eax, 0xff
    mov [audio_sfx_separation_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_PITCH]
    and eax, 0xff
    mov [audio_sfx_pitch_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_SOUND_ID]
    mov [audio_sfx_id_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_FLAGS]
    mov [audio_sfx_flags_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_SAMPLE_RATE]
    mov [audio_sfx_rate_arg], eax

    mov eax, [audio_sfx_sample_arg]
    mov ebx, [audio_sfx_length_arg]
    cmp ebx, 0
    je .underrun
    cmp ebx, SB16_DMA_BUFFER_BYTES
    jbe .length_ready
    mov ebx, SB16_DMA_BUFFER_BYTES
    mov [audio_sfx_length_arg], ebx

.length_ready:
    call user_range_validate
    jc .underrun

    mov esi, [audio_sfx_sample_arg]
    mov ecx, [audio_sfx_length_arg]
    mov ebp, [audio_sfx_volume_arg]
    mov edi, sb16_dma_buffer
    add edi, [sb16_dma_write_pos]
    cld

.mix_next:
    cmp ecx, 0
    je .done_mix

    xor eax, eax
    lodsb
    sub eax, 128
    imul eax, ebp
    sar eax, 7

    movzx edx, byte [edi]
    sub edx, 128
    add eax, edx
    cmp eax, 127
    jle .check_low
    mov eax, 127
    inc dword [sb16_mix_clip_count]
    jmp .store

.check_low:
    cmp eax, -128
    jge .store
    mov eax, -128
    inc dword [sb16_mix_clip_count]

.store:
    push eax
    cmp byte [sb16_playback_active], 1
    jne .overwrite_done
    mov eax, [sb16_dma_write_pos]
    cmp eax, SB16_DMA_BLOCK_BYTES
    jb .write_half_ready
    mov eax, 1
    jmp .check_overwrite

.write_half_ready:
    xor eax, eax

.check_overwrite:
    cmp eax, [sb16_irq_half_index]
    jne .overwrite_done
    inc dword [sb16_mix_overwrite_count]

.overwrite_done:
    pop eax
    add eax, 128
    mov [edi], al
    inc edi
    inc dword [sb16_dma_write_pos]
    cmp dword [sb16_dma_write_pos], SB16_DMA_BUFFER_BYTES
    jb .advance_done
    mov dword [sb16_dma_write_pos], 0
    inc dword [sb16_mix_wrap_count]
    mov edi, sb16_dma_buffer

.advance_done:
    dec ecx
    jmp .mix_next

.done_mix:
    inc dword [sb16_sfx_mix_count]
    mov eax, [audio_sfx_length_arg]
    add [sb16_sfx_mix_bytes], eax
    add [audio_pcm_ring_mixed_bytes], eax
    jmp .done

.underrun:
    inc dword [sb16_mix_underrun_count]

.done:
    pop ebp
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

sb16_record_music_render_stats:
    push eax
    push edx

    mov eax, [esi + AUDIO_SFX_DESC_MUSIC_FORMAT]
    cmp eax, 0
    je .done
    cmp eax, 2
    ja .done
    mov [sb16_music_render_format], eax
    inc dword [sb16_music_render_chunk_count]

    mov eax, [esi + AUDIO_SFX_DESC_MUSIC_NOTE_EVENTS]
    add [sb16_music_render_note_count], eax
    mov edx, eax
    mov eax, [esi + AUDIO_SFX_DESC_MUSIC_CONTROL_EVENTS]
    add edx, eax
    add [sb16_music_render_event_count], edx

    mov eax, [esi + AUDIO_SFX_DESC_MUSIC_ACTIVE_VOICE_PEAK]
    cmp eax, [sb16_music_render_active_peak]
    jbe .sample_count
    mov [sb16_music_render_active_peak], eax

.sample_count:
    mov eax, [esi + AUDIO_SFX_DESC_MUSIC_EMITTED_SAMPLES]
    add [sb16_music_render_sample_count], eax

.done:
    pop edx
    pop eax
    ret

audio_write_device_info:
    push eax
    push ebx
    push ecx
    push edi

    mov eax, ecx
    mov ebx, AUDIO_DEVICE_INFO_BYTES
    call user_range_validate
    jc .fail

    mov edi, ecx
    mov dword [edi + AUDIO_DEVICE_INFO_KIND], AUDIO_DEVICE_NONE
    cmp byte [audio_status], 1
    jne .kind_ready
    mov dword [edi + AUDIO_DEVICE_INFO_KIND], AUDIO_DEVICE_SB16

.kind_ready:
    movzx eax, byte [audio_status]
    mov [edi + AUDIO_DEVICE_INFO_STATUS], eax
    mov dword [edi + AUDIO_DEVICE_INFO_SAMPLE_RATE], SB16_SAMPLE_RATE
    mov dword [edi + AUDIO_DEVICE_INFO_CHANNELS], 2
    mov dword [edi + AUDIO_DEVICE_INFO_FORMAT], AUDIO_PCM_FORMAT_U8_STEREO
    mov eax, [sb16_dma_buffer_size]
    mov [edi + AUDIO_DEVICE_INFO_RING_BYTES], eax
    mov eax, [sb16_dma_block_size]
    mov [edi + AUDIO_DEVICE_INFO_PERIOD_BYTES], eax
    xor eax, eax
    cmp byte [audio_status], 1
    jne .capabilities_ready
    mov eax, AUDIO_CAP_PCM_RING | AUDIO_CAP_MIXER_VOICES | AUDIO_CAP_PULL_STREAM | AUDIO_CAP_SB16_DMA

.capabilities_ready:
    mov [edi + AUDIO_DEVICE_INFO_CAPABILITIES], eax
    mov eax, [sb16_active_voice_count]
    mov [edi + AUDIO_DEVICE_INFO_ACTIVE_VOICES], eax
    mov eax, [sb16_irq_count]
    mov [edi + AUDIO_DEVICE_INFO_IRQ_COUNT], eax
    mov eax, [audio_irq_count]
    mov [edi + AUDIO_DEVICE_INFO_IRQ_COUNT], eax
    mov eax, [sb16_irq_refill_count]
    mov [edi + AUDIO_DEVICE_INFO_REFILL_COUNT], eax
    mov eax, [audio_irq_refill_count]
    mov [edi + AUDIO_DEVICE_INFO_REFILL_COUNT], eax
    mov eax, [sb16_playback_start_count]
    mov [edi + AUDIO_DEVICE_INFO_PLAYBACK_START_COUNT], eax
    xor eax, eax
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop ecx
    pop ebx
    pop eax
    ret

audio_write_pcm_ring_info:
    push eax
    push ebx
    push ecx
    push edi

    mov eax, ecx
    mov ebx, AUDIO_PCM_RING_INFO_BYTES
    call user_range_validate
    jc .fail

    call audio_sync_pcm_stream_state
    mov edi, ecx
    mov dword [edi + AUDIO_PCM_RING_INFO_FORMAT], AUDIO_PCM_FORMAT_U8_STEREO
    mov dword [edi + AUDIO_PCM_RING_INFO_CHANNELS], 2
    mov dword [edi + AUDIO_PCM_RING_INFO_SAMPLE_RATE], SB16_SAMPLE_RATE
    mov eax, [sb16_dma_buffer_size]
    mov [edi + AUDIO_PCM_RING_INFO_RING_BYTES], eax
    mov eax, [sb16_dma_block_size]
    mov [edi + AUDIO_PCM_RING_INFO_PERIOD_BYTES], eax
    mov eax, [sb16_dma_write_pos]
    mov [edi + AUDIO_PCM_RING_INFO_WRITE_OFFSET], eax
    mov eax, [sb16_irq_half_index]
    mov [edi + AUDIO_PCM_RING_INFO_ACTIVE_HALF], eax
    mov eax, [sb16_music_stream_buffer_bytes]
    mov [edi + AUDIO_PCM_RING_INFO_QUEUED_BYTES], eax
    mov eax, [audio_pcm_stream_queued_bytes]
    mov [edi + AUDIO_PCM_RING_INFO_QUEUED_BYTES], eax
    mov eax, [sb16_sfx_output_bytes]
    add eax, [sb16_music_mix_bytes]
    mov [edi + AUDIO_PCM_RING_INFO_MIXED_BYTES], eax
    mov eax, [audio_pcm_ring_mixed_bytes]
    cmp eax, 0
    je .mixed_bytes_ready
    mov [edi + AUDIO_PCM_RING_INFO_MIXED_BYTES], eax

.mixed_bytes_ready:
    mov eax, [sb16_mix_underrun_count]
    mov [edi + AUDIO_PCM_RING_INFO_UNDERRUN_COUNT], eax
    mov eax, [sb16_mix_overwrite_count]
    mov [edi + AUDIO_PCM_RING_INFO_OVERWRITE_COUNT], eax
    mov eax, [sb16_mix_clip_count]
    mov [edi + AUDIO_PCM_RING_INFO_CLIP_COUNT], eax
    xor eax, eax
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop ecx
    pop ebx
    pop eax
    ret

audio_current_process_page_dir:
    mov eax, [current_process_ptr]
    test eax, eax
    jz .use_cr3
    mov eax, [eax + PROC_PAGE_DIR]
    test eax, eax
    jnz .done

.use_cr3:
    mov eax, cr3

.done:
    ret

audio_register_sfx_voice:
    push eax
    push ebx
    push ecx
    push edx
    push esi

    mov eax, [audio_sfx_desc_arg]
    mov ebx, AUDIO_SFX_DESC_BYTES
    call user_range_validate
    jc .underrun

    mov esi, [audio_sfx_desc_arg]
    mov eax, [esi + AUDIO_SFX_DESC_SAMPLES]
    mov ebx, [esi + AUDIO_SFX_DESC_LENGTH]
    mov [audio_sfx_sample_arg], eax
    mov [audio_sfx_length_arg], ebx
    mov eax, [esi + AUDIO_SFX_DESC_VOLUME]
    and eax, 0xff
    mov [audio_sfx_volume_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_SEPARATION]
    and eax, 0xff
    mov [audio_sfx_separation_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_PITCH]
    and eax, 0xff
    mov [audio_sfx_pitch_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_SOUND_ID]
    mov [audio_sfx_id_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_FLAGS]
    mov [audio_sfx_flags_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_SAMPLE_RATE]
    mov [audio_sfx_rate_arg], eax
    mov eax, [audio_sfx_handle_arg]
    and eax, AUDIO_MUSIC_HANDLE_MASK
    cmp eax, AUDIO_MUSIC_HANDLE_BASE
    jne .flags_ready
    or dword [audio_sfx_flags_arg], AUDIO_FLAG_MUSIC

.flags_ready:
    cmp byte [audio_pcm_force_stream_arg], 1
    jne .force_stream_ready
    or dword [audio_sfx_flags_arg], AUDIO_FLAG_STREAM

.force_stream_ready:

    mov eax, [audio_sfx_sample_arg]
    mov ebx, [audio_sfx_length_arg]
    cmp ebx, 0
    je .underrun
    call user_range_validate
    jc .underrun

    call sb16_find_voice_by_handle
    jnc .slot_ready
    call sb16_find_free_voice
    jnc .slot_ready
    call sb16_find_steal_voice

.slot_ready:
    mov [audio_sfx_voice_slot], eax
    mov ebx, eax
    mov byte [sb16_voice_active + ebx], 1
    mov eax, [audio_sfx_handle_arg]
    mov [sb16_voice_handles + ebx * 4], eax
    mov eax, [audio_sfx_sample_arg]
    mov [sb16_voice_samples + ebx * 4], eax
    call audio_current_process_page_dir
    mov [sb16_voice_page_dirs + ebx * 4], eax
    mov eax, [audio_sfx_length_arg]
    mov [sb16_voice_lengths + ebx * 4], eax
    mov dword [sb16_voice_positions + ebx * 4], 0
    mov eax, [audio_sfx_flags_arg]
    mov [sb16_voice_flags + ebx * 4], eax
    mov dword [sb16_voice_loop_counts + ebx * 4], 0
    mov dword [sb16_voice_pending_samples + ebx * 4], 0
    mov dword [sb16_voice_pending_lengths + ebx * 4], 0
    mov dword [sb16_voice_pending_page_dirs + ebx * 4], 0
    mov eax, [audio_sfx_volume_arg]
    mov [sb16_voice_volumes + ebx * 4], eax
    mov eax, [audio_sfx_separation_arg]
    mov [sb16_voice_separations + ebx * 4], eax
    mov eax, [audio_sfx_pitch_arg]
    mov [sb16_voice_pitches + ebx * 4], eax
    call sb16_pitch_to_step
    mov [sb16_voice_steps + ebx * 4], eax
    call sb16_compute_pan_from_args
    mov eax, [sb16_pan_left_arg]
    mov [sb16_voice_left_volumes + ebx * 4], eax
    mov eax, [sb16_pan_right_arg]
    mov [sb16_voice_right_volumes + ebx * 4], eax
    inc dword [sb16_voice_age_counter]
    mov eax, [sb16_voice_age_counter]
    mov [sb16_voice_started_at + ebx * 4], eax
    inc dword [sb16_voice_start_count]
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_STREAM
    jz .sfx_started
    inc dword [sb16_music_start_count]
    mov dword [sb16_music_stream_mode], AUDIO_STREAM_PULL
    mov eax, [audio_sfx_length_arg]
    mov [sb16_music_stream_buffer_bytes], eax
    call audio_note_pcm_stream_write
    call sb16_record_music_render_stats
    jmp .recount

.sfx_started:
    inc dword [sb16_sfx_voice_start_count]
    mov eax, [audio_sfx_length_arg]
    add [sb16_sfx_submit_bytes], eax
    mov eax, [audio_sfx_id_arg]
    mov [sb16_sfx_last_id], eax
    mov eax, [audio_sfx_rate_arg]
    mov [sb16_sfx_last_rate], eax
    mov eax, [audio_sfx_length_arg]
    mov [sb16_sfx_last_length], eax
    test dword [audio_sfx_flags_arg], AUDIO_FLAG_PACKAGE_MEMBER_SFX
    jz .recount
    inc dword [sb16_sfx_asset_start_count]

.recount:
    call sb16_recount_active_voices
    clc
    jmp .done

.underrun:
    inc dword [sb16_mix_underrun_count]
    cmp byte [audio_pcm_force_stream_arg], 1
    jne .underrun_error
    inc dword [audio_pcm_stream_under_count]
    inc dword [audio_pcm_stream_drop_count]

.underrun_error:
    mov dword [audio_pcm_stream_last_error], -ERRNO_EINVAL
    stc

.done:
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

audio_stop_sfx_voice:
    push eax
    push ebx

    call sb16_find_voice_by_handle
    jc .maybe_stop_pcm_stream
    mov ebx, eax
    mov byte [sb16_voice_active + ebx], 0
    mov dword [sb16_voice_handles + ebx * 4], 0
    mov dword [sb16_voice_positions + ebx * 4], 0
    mov dword [sb16_voice_started_at + ebx * 4], 0
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_STREAM
    jz .count_sfx_stop
    inc dword [sb16_music_stop_count]
    mov dword [sb16_music_stream_buffer_bytes], 0
    mov eax, [audio_sfx_handle_arg]
    cmp [audio_pcm_stream_handle], eax
    jne .clear_flags
    mov dword [audio_pcm_stream_handle], 0
    mov dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    jmp .clear_flags

.count_sfx_stop:
    inc dword [sb16_sfx_voice_stop_count]

.clear_flags:
    mov dword [sb16_voice_flags + ebx * 4], 0
    mov dword [sb16_voice_loop_counts + ebx * 4], 0
    mov dword [sb16_voice_pending_samples + ebx * 4], 0
    mov dword [sb16_voice_pending_lengths + ebx * 4], 0
    inc dword [sb16_voice_stop_count]
    call sb16_recount_active_voices
    clc
    jmp .done

.maybe_stop_pcm_stream:
    mov eax, [audio_sfx_handle_arg]
    cmp eax, [audio_pcm_stream_handle]
    jne .done
    cmp dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    je .done
    test dword [audio_pcm_stream_source_flags], AUDIO_FLAG_MUSIC
    jz .stop_generic_stream
    inc dword [sb16_music_stop_count]

.stop_generic_stream:
    call audio_pcm_stream_stop_current
    clc

.done:
    pop ebx
    pop eax
    ret

audio_update_sfx_voice:
    push eax
    push ebx
    push edx
    push esi

    mov eax, [audio_sfx_desc_arg]
    mov ebx, AUDIO_SFX_DESC_BYTES
    call user_range_validate
    jc .maybe_drop_music
    call sb16_find_voice_by_handle
    jc .maybe_drop_music
    mov ebx, eax
    mov esi, [audio_sfx_desc_arg]
    mov eax, [esi + AUDIO_SFX_DESC_SAMPLES]
    mov [audio_sfx_sample_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_LENGTH]
    mov [audio_sfx_length_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_FLAGS]
    mov [audio_sfx_flags_arg], eax
    mov eax, [esi + AUDIO_SFX_DESC_SAMPLE_RATE]
    mov [audio_sfx_rate_arg], eax
    mov eax, [audio_sfx_handle_arg]
    and eax, AUDIO_MUSIC_HANDLE_MASK
    cmp eax, AUDIO_MUSIC_HANDLE_BASE
    jne .update_flags_ready
    or dword [audio_sfx_flags_arg], AUDIO_FLAG_MUSIC

.update_flags_ready:
    cmp byte [audio_pcm_force_stream_arg], 1
    jne .update_force_stream_ready
    or dword [audio_sfx_flags_arg], AUDIO_FLAG_STREAM

.update_force_stream_ready:
    mov eax, [esi + AUDIO_SFX_DESC_VOLUME]
    and eax, 0xff
    mov [audio_sfx_volume_arg], eax
    mov [sb16_voice_volumes + ebx * 4], eax
    mov eax, [esi + AUDIO_SFX_DESC_SEPARATION]
    and eax, 0xff
    mov [audio_sfx_separation_arg], eax
    mov [sb16_voice_separations + ebx * 4], eax
    mov eax, [esi + AUDIO_SFX_DESC_PITCH]
    and eax, 0xff
    mov [audio_sfx_pitch_arg], eax
    mov [sb16_voice_pitches + ebx * 4], eax
    call sb16_pitch_to_step
    mov [sb16_voice_steps + ebx * 4], eax
    call sb16_compute_pan_from_args
    mov eax, [sb16_pan_left_arg]
    mov [sb16_voice_left_volumes + ebx * 4], eax
    mov eax, [sb16_pan_right_arg]
    mov [sb16_voice_right_volumes + ebx * 4], eax

    mov eax, [audio_sfx_sample_arg]
    cmp eax, 0
    je .count_update
    mov edx, [audio_sfx_length_arg]
    cmp edx, 0
    je .count_update
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_STREAM
    jnz .refresh_stream_window
    test dword [audio_sfx_flags_arg], AUDIO_FLAG_STREAM
    jz .count_update

.refresh_stream_window:
    push ebx
    mov eax, [audio_sfx_sample_arg]
    mov ebx, [audio_sfx_length_arg]
    call user_range_validate
    pop ebx
    jc .stream_underrun
    mov eax, [audio_sfx_flags_arg]
    or eax, AUDIO_FLAG_STREAM
    mov [sb16_voice_flags + ebx * 4], eax
    mov dword [sb16_music_stream_mode], AUDIO_STREAM_PULL
    call audio_note_pcm_stream_write
    call sb16_record_music_render_stats
    mov eax, [sb16_voice_positions + ebx * 4]
    shr eax, 16
    cmp eax, [sb16_voice_lengths + ebx * 4]
    jae .store_stream_window
    cmp dword [sb16_voice_pending_lengths + ebx * 4], 0
    jne .replace_pending_window
    mov eax, [audio_sfx_sample_arg]
    mov [sb16_voice_pending_samples + ebx * 4], eax
    call audio_current_process_page_dir
    mov [sb16_voice_pending_page_dirs + ebx * 4], eax
    mov eax, [audio_sfx_length_arg]
    mov [sb16_voice_pending_lengths + ebx * 4], eax
    call sb16_mark_music_pull_refill
    call sb16_recount_active_voices
    jmp .count_update

.replace_pending_window:
    inc dword [sb16_music_stream_drop_count]
    mov eax, [audio_sfx_sample_arg]
    mov [sb16_voice_pending_samples + ebx * 4], eax
    call audio_current_process_page_dir
    mov [sb16_voice_pending_page_dirs + ebx * 4], eax
    mov eax, [audio_sfx_length_arg]
    mov [sb16_voice_pending_lengths + ebx * 4], eax
    call sb16_mark_music_pull_refill
    call sb16_recount_active_voices
    jmp .count_update

.store_stream_window:
    mov eax, [audio_sfx_sample_arg]
    mov [sb16_voice_samples + ebx * 4], eax
    call audio_current_process_page_dir
    mov [sb16_voice_page_dirs + ebx * 4], eax
    mov eax, [audio_sfx_length_arg]
    mov [sb16_voice_lengths + ebx * 4], eax
    mov [sb16_music_stream_buffer_bytes], eax
    mov dword [sb16_voice_positions + ebx * 4], 0
    mov dword [sb16_voice_pending_samples + ebx * 4], 0
    mov dword [sb16_voice_pending_lengths + ebx * 4], 0
    mov dword [sb16_voice_pending_page_dirs + ebx * 4], 0
    call sb16_mark_music_pull_refill
    call sb16_recount_active_voices
    jmp .count_update

.stream_underrun:
    inc dword [sb16_mix_underrun_count]
    inc dword [sb16_music_stream_under_count]
    inc dword [sb16_music_stream_drop_count]
    inc dword [audio_pcm_stream_under_count]
    inc dword [audio_pcm_stream_drop_count]
    mov dword [audio_pcm_stream_last_error], -ERRNO_EINVAL
    stc
    jmp .done

.count_update:
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_STREAM
    jnz .count_global_update
    inc dword [sb16_sfx_voice_update_count]

.count_global_update:
    inc dword [sb16_voice_update_count]
    clc

.done:
    pop esi
    pop edx
    pop ebx
    pop eax
    ret

.maybe_drop_music:
    cmp byte [audio_pcm_force_stream_arg], 1
    je .drop_stream_update
    mov eax, [audio_sfx_handle_arg]
    and eax, AUDIO_MUSIC_HANDLE_MASK
    cmp eax, AUDIO_MUSIC_HANDLE_BASE
    jne .done

.drop_stream_update:
    inc dword [sb16_music_stream_drop_count]
    inc dword [audio_pcm_stream_drop_count]
    mov dword [audio_pcm_stream_last_error], -ERRNO_EINVAL
    stc
    jmp .done

sb16_mark_music_pull_refill:
    push eax
    mov eax, [sb16_music_pull_request_count]
    cmp dword [sb16_music_pull_refill_count], eax
    jae .done
    inc dword [sb16_music_pull_refill_count]
    mov eax, [sb16_music_pull_refill_count]
    mov [audio_pcm_stream_pull_refill_count], eax

.done:
    pop eax
    ret

sb16_music_pull_service_pending:
    push eax
    cmp dword [sb16_music_stream_mode], AUDIO_MUSIC_STREAM_PULL
    jne .none
    mov eax, [sb16_music_pull_request_count]
    cmp eax, dword [sb16_music_pull_refill_count]
    ja .pending

.none:
    pop eax
    stc
    ret

.pending:
    pop eax
    clc
    ret

sb16_note_music_pull_request:
    push eax
    push ebx
    push ecx
    cmp dword [sb16_music_stream_mode], AUDIO_MUSIC_STREAM_PULL
    jne .done
    cmp dword [sb16_active_music_voice_count], 0
    je .done
    xor ebx, ebx
    mov ecx, AUDIO_MAX_SFX_VOICES

.voice_next:
    cmp byte [sb16_voice_active + ebx], 1
    jne .voice_advance
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_MUSIC
    jz .voice_advance
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_STREAM_FINAL
    jz .maybe_request

.voice_advance:
    inc ebx
    loop .voice_next
    jmp .done

.maybe_request:
    mov eax, [sb16_music_stream_buffer_bytes]
    cmp eax, AUDIO_MUSIC_PULL_LOW_WATER_BYTES
    ja .done
    mov eax, [sb16_music_pull_request_count]
    cmp eax, dword [sb16_music_pull_refill_count]
    jne .done
    inc dword [sb16_music_pull_request_count]
    mov eax, [sb16_music_pull_request_count]
    mov [audio_pcm_stream_pull_request_count], eax

.done:
    pop ecx
    pop ebx
    pop eax
    ret

sb16_music_promote_pending_window:
    push eax

    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_MUSIC
    jz .none
    cmp dword [sb16_voice_pending_lengths + ebx * 4], 0
    je .none

    mov eax, [sb16_voice_pending_samples + ebx * 4]
    mov [sb16_voice_samples + ebx * 4], eax
    mov eax, [sb16_voice_pending_page_dirs + ebx * 4]
    mov [sb16_voice_page_dirs + ebx * 4], eax
    mov eax, [sb16_voice_pending_lengths + ebx * 4]
    mov [sb16_voice_lengths + ebx * 4], eax
    mov dword [sb16_voice_pending_samples + ebx * 4], 0
    mov dword [sb16_voice_pending_lengths + ebx * 4], 0
    mov dword [sb16_voice_pending_page_dirs + ebx * 4], 0
    mov dword [sb16_voice_positions + ebx * 4], 0
    mov dword [sb16_mix_source_pos], 0
    clc
    jmp .done

.none:
    stc

.done:
    pop eax
    ret

sb16_refill_active_half:
    pushad

    mov edi, sb16_dma_buffer
    cmp dword [sb16_irq_half_index], 0
    je .dest_ready
    add edi, SB16_DMA_BLOCK_BYTES

.dest_ready:
    mov [sb16_refill_dest_base], edi
    mov eax, 0x80808080
    mov ecx, SB16_DMA_BLOCK_BYTES / 4
    cld
    rep stosd

    call audio_pcm_drain_to_dma
    cmp dword [sb16_active_voice_count], 0
    jne .have_voices
    cmp dword [audio_pcm_stream_active_count], 0
    jne .have_voices
    inc dword [sb16_mix_underrun_count]

.have_voices:
    xor ebx, ebx

.voice_next:
    cmp ebx, AUDIO_MAX_SFX_VOICES
    jae .done_voices
    cmp byte [sb16_voice_active + ebx], 1
    jne .advance_voice

    mov [sb16_mix_voice_slot], ebx
    mov eax, [sb16_voice_positions + ebx * 4]
    mov edx, eax
    shr edx, 16
    cmp edx, [sb16_voice_lengths + ebx * 4]
    jae .finish_voice
    mov [sb16_mix_source_pos], eax
    mov eax, [sb16_voice_steps + ebx * 4]
    mov [sb16_mix_source_step], eax
    mov eax, [sb16_voice_left_volumes + ebx * 4]
    mov [sb16_mix_left_volume], eax
    mov eax, [sb16_voice_right_volumes + ebx * 4]
    mov [sb16_mix_right_volume], eax
    mov edi, [sb16_refill_dest_base]
    mov ecx, SB16_DMA_BLOCK_BYTES / 2
    mov dword [sb16_mix_frames_mixed], 0
    pushfd
    cli
    mov eax, cr3
    push eax
    mov eax, [sb16_voice_page_dirs + ebx * 4]
    test eax, eax
    jz .mix_address_space_ready
    cmp eax, [esp]
    je .mix_address_space_ready
    mov cr3, eax

.mix_address_space_ready:

.mix_next:
    cmp ecx, 0
    je .voice_mixed
    mov eax, [sb16_mix_source_pos]
    mov edx, eax
    shr edx, 16
    mov ebx, [sb16_mix_voice_slot]
    cmp edx, [sb16_voice_lengths + ebx * 4]
    jb .source_ready
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_LOOP
    jz .maybe_promote_pending
    cmp dword [sb16_voice_lengths + ebx * 4], 0
    je .voice_mixed
    mov dword [sb16_mix_source_pos], 0
    inc dword [sb16_voice_loop_counts + ebx * 4]
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_MUSIC
    jz .mix_next
    inc dword [sb16_music_loop_count]
    jmp .mix_next

.maybe_promote_pending:
    call sb16_music_promote_pending_window
    jnc .mix_next
    jmp .voice_mixed

.source_ready:
    mov esi, [sb16_voice_samples + ebx * 4]
    add esi, edx
    movzx eax, byte [esi]
    sub eax, 128
    mov ebp, eax
    mov edx, [sb16_mix_left_volume]
    imul eax, edx
    sar eax, 7
    movzx edx, byte [edi]
    sub edx, 128
    add eax, edx
    cmp eax, 127
    jle .check_low
    mov eax, 127
    inc dword [sb16_mix_clip_count]
    jmp .store

.check_low:
    cmp eax, -128
    jge .store
    mov eax, -128
    inc dword [sb16_mix_clip_count]

.store:
    add eax, 128
    mov [edi], al
    mov eax, ebp
    mov edx, [sb16_mix_right_volume]
    imul eax, edx
    sar eax, 7
    movzx edx, byte [edi + 1]
    sub edx, 128
    add eax, edx
    cmp eax, 127
    jle .right_check_low
    mov eax, 127
    inc dword [sb16_mix_clip_count]
    jmp .right_store

.right_check_low:
    cmp eax, -128
    jge .right_store
    mov eax, -128
    inc dword [sb16_mix_clip_count]

.right_store:
    add eax, 128
    mov [edi + 1], al
    add edi, 2
    mov eax, [sb16_mix_source_step]
    add [sb16_mix_source_pos], eax
    inc dword [sb16_mix_frames_mixed]
    dec ecx
    jmp .mix_next

.voice_mixed:
    pop eax
    mov cr3, eax
    popfd
    mov ebx, [sb16_mix_voice_slot]
    mov eax, [sb16_mix_source_pos]
    mov [sb16_voice_positions + ebx * 4], eax
    mov eax, [sb16_mix_frames_mixed]
    cmp eax, 0
    je .check_finished
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_MUSIC
    jz .count_sfx_mix
    add [sb16_music_stream_pos_bytes], eax
    shl eax, 1
    add [audio_pcm_stream_position_bytes], eax
    add [audio_pcm_ring_mixed_bytes], eax
    inc dword [sb16_music_mix_count]
    add [sb16_music_mix_bytes], eax
    cmp [sb16_music_stream_buffer_bytes], eax
    jae .drain_music_buffer
    mov dword [sb16_music_stream_buffer_bytes], 0
    jmp .check_finished

.drain_music_buffer:
    sub [sb16_music_stream_buffer_bytes], eax
    jmp .check_finished

.count_sfx_mix:
    shl eax, 1
    add [audio_pcm_ring_mixed_bytes], eax
    inc dword [sb16_sfx_mix_count]
    add [sb16_sfx_mix_bytes], eax
    add [sb16_sfx_output_bytes], eax
    inc dword [sb16_sfx_dma_mix_count]
    add [sb16_sfx_dma_mix_bytes], eax

.check_finished:
    mov eax, [sb16_voice_positions + ebx * 4]
    shr eax, 16
    cmp eax, [sb16_voice_lengths + ebx * 4]
    jb .advance_voice
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_LOOP
    jz .maybe_promote_pending_after_half
    cmp dword [sb16_voice_lengths + ebx * 4], 0
    je .finish_voice
    mov dword [sb16_voice_positions + ebx * 4], 0
    inc dword [sb16_voice_loop_counts + ebx * 4]
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_MUSIC
    jz .advance_voice
    inc dword [sb16_music_loop_count]
    jmp .advance_voice

.maybe_promote_pending_after_half:
    call sb16_music_promote_pending_window
    jnc .advance_voice
    jmp .finish_voice

.finish_voice:
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_MUSIC
    jz .finish_sfx
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_STREAM_FINAL
    jnz .finish_terminal_music
    call sb16_music_pull_service_pending
    jnc .hold_pending_music_refill
    inc dword [sb16_music_stream_under_count]
.finish_terminal_music:
    mov dword [sb16_music_stream_buffer_bytes], 0
    jmp .finish_clear

.hold_pending_music_refill:
    mov dword [sb16_music_stream_buffer_bytes], 0
    jmp .advance_voice

.finish_sfx:
    inc dword [sb16_sfx_voice_finished_count]

.finish_clear:
    mov byte [sb16_voice_active + ebx], 0
    mov dword [sb16_voice_handles + ebx * 4], 0
    mov dword [sb16_voice_started_at + ebx * 4], 0
    mov dword [sb16_voice_flags + ebx * 4], 0
    mov dword [sb16_voice_loop_counts + ebx * 4], 0
    mov dword [sb16_voice_pending_samples + ebx * 4], 0
    mov dword [sb16_voice_pending_lengths + ebx * 4], 0
    mov dword [sb16_voice_page_dirs + ebx * 4], 0
    mov dword [sb16_voice_pending_page_dirs + ebx * 4], 0
    inc dword [sb16_voice_finished_count]

.advance_voice:
    inc ebx
    jmp .voice_next

.done_voices:
    inc dword [sb16_voice_refill_count]
    call sb16_recount_active_voices
    call sb16_note_music_pull_request
    popad
    ret

sb16_mask_dma8:
    push eax
    mov al, 0x04 | SB16_DMA8_CHANNEL
    out DMA8_MASK_REG, al
    pop eax
    ret

sb16_program_dma8:
    push eax
    push ebx
    push ecx
    push edx

    mov dword [sb16_dma_status], SB16_DMA_STATUS_IDLE
    mov dword [sb16_dma_last_error], SB16_DMA_ERROR_NONE
    mov eax, sb16_dma_buffer
    mov [sb16_dma_last_addr], eax
    cmp eax, ISA_DMA_ADDRESS_LIMIT
    jae .boundary_fail
    mov ebx, eax
    and ebx, 0x0000ffff
    add ebx, SB16_DMA_BUFFER_BYTES - 1
    cmp ebx, ISA_DMA_64K_WINDOW
    jae .boundary_fail

    mov al, 0x04 | SB16_DMA8_CHANNEL
    out DMA8_MASK_REG, al
    out DMA8_CLEAR_FLIPFLOP_REG, al

    mov eax, sb16_dma_buffer
    mov dx, DMA8_CH1_ADDR_REG
    out dx, al
    shr eax, 8
    out dx, al
    shr eax, 8
    mov dx, DMA8_CH1_PAGE_REG
    out dx, al
    movzx eax, al
    mov [sb16_dma_last_page], eax

    out DMA8_CLEAR_FLIPFLOP_REG, al
    mov ecx, SB16_DMA_BUFFER_BYTES - 1
    mov [sb16_dma_last_count], ecx
    mov dx, DMA8_CH1_COUNT_REG
    mov al, cl
    out dx, al
    mov al, ch
    out dx, al

    mov al, DMA8_CH1_AUTO_READ_MODE
    out DMA8_MODE_REG, al
    mov al, SB16_DMA8_CHANNEL
    out DMA8_MASK_REG, al
    inc dword [sb16_dma_program_count]
    mov dword [sb16_dma_status], SB16_DMA_STATUS_OK
    clc
    jmp .done

.boundary_fail:
    call sb16_mask_dma8
    mov dword [sb16_dma_status], SB16_DMA_STATUS_FAIL
    mov dword [sb16_dma_last_error], SB16_DMA_ERROR_BOUNDARY
    inc dword [sb16_dma_boundary_error_count]
    stc

.done:
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

sb16_start_playback:
    cmp byte [audio_status], 1
    jne .not_ready
    cmp byte [sb16_playback_active], 1
    je .not_ready
    call sb16_clear_dma_buffer
    call sb16_program_dma8
    jc .fail

    mov al, SB16_DSP_SPEAKER_ON
    call sb16_write_dsp
    jc .fail
    mov al, SB16_DSP_SET_TIME_CONSTANT
    call sb16_write_dsp
    jc .fail
    mov al, SB16_TIME_CONSTANT
    call sb16_write_dsp
    jc .fail
    mov al, SB16_DSP_SET_OUTPUT_RATE
    call sb16_write_dsp
    jc .fail
    mov al, SB16_SAMPLE_RATE_HIGH
    call sb16_write_dsp
    jc .fail
    mov al, SB16_SAMPLE_RATE_LOW
    call sb16_write_dsp
    jc .fail
    mov al, SB16_DSP_SET_BLOCK_SIZE
    call sb16_write_dsp
    jc .fail
    mov ax, SB16_DMA_BLOCK_BYTES - 1
    call sb16_write_dsp
    jc .fail
    mov al, ah
    call sb16_write_dsp
    jc .fail
    mov al, SB16_DSP_8BIT_AUTO_OUT
    call sb16_write_dsp
    jc .fail
    mov al, SB16_DSP_MODE_UNSIGNED_STEREO
    call sb16_write_dsp
    jc .fail
    mov ax, SB16_DMA_BLOCK_BYTES - 1
    call sb16_write_dsp
    jc .fail
    mov al, ah
    call sb16_write_dsp
    jc .fail

    mov byte [sb16_playback_active], 1
    inc dword [sb16_playback_start_count]
    clc
    ret

.not_ready:
    clc
    ret

.fail:
    call sb16_mask_dma8
    mov byte [sb16_playback_active], 0
    mov dword [sb16_dma_status], SB16_DMA_STATUS_FAIL
    cmp dword [sb16_dma_last_error], SB16_DMA_ERROR_NONE
    jne .fail_counted
    mov dword [sb16_dma_last_error], SB16_DMA_ERROR_DSP

.fail_counted:
    inc dword [sb16_playback_error_count]
    stc
    ret

sb16_stop_playback:
    cmp byte [audio_status], 1
    jne .not_ready
    mov al, SB16_DSP_EXIT_8BIT_AUTO
    call sb16_write_dsp
    mov al, SB16_DSP_SPEAKER_OFF
    call sb16_write_dsp
    call sb16_mask_dma8
    mov byte [sb16_playback_active], 0
    inc dword [sb16_playback_stop_count]
    call sb16_clear_active_voices

.not_ready:
    clc
    ret

sb16_write_dsp:
    push ecx
    push edx
    push eax
    mov ah, al
    mov ecx, 0x10000
    mov dx, SB16_DSP_WRITE

.wait_next:
    in al, dx
    test al, SB16_DSP_READY
    jz .write_ok
    loop .wait_next
    pop eax
    stc
    jmp .done

.write_ok:
    mov al, ah
    out dx, al
    pop eax
    clc

.done:
    pop edx
    pop ecx
    ret

sb16_read_dsp:
    push ecx
    push edx
    mov ecx, 0x10000
    mov dx, SB16_DSP_READ_STATUS

.wait_next:
    in al, dx
    test al, SB16_DSP_READY
    jnz .read_ok
    loop .wait_next
    stc
    jmp .done

.read_ok:
    mov dx, SB16_DSP_READ
    in al, dx
    clc

.done:
    pop edx
    pop ecx
    ret

