.have_total_sectors:
    mov [fat_total_sectors], eax

    mov eax, [fat_lba_base]
    add eax, [fat_reserved_sectors]
    mov [fat_start_lba], eax

    mov eax, [fat_sectors_per_fat]
    mov ebx, [fat_count]
    mul ebx
    add eax, [fat_start_lba]
    mov [fat_root_lba], eax
    add eax, [fat_root_sectors]
    mov [fat_data_lba], eax
    mov eax, [fat_total_sectors]
    sub eax, [fat_reserved_sectors]
    mov ebx, [fat_sectors_per_fat]
    mov ecx, [fat_count]
    imul ebx, ecx
    sub eax, ebx
    sub eax, [fat_root_sectors]
    xor edx, edx
    movzx ebx, byte [fat_sectors_per_cluster]
    div ebx
    inc eax
    mov [fat_last_data_cluster], eax
    mov byte [fat_status], 1
    cmp dword [fat_sectors_per_fat], FAT_TABLE_CACHE_SECTORS
    ja .fat_fail
    call fat_cache_table
    jc .fat_fail
    call fat_build_alloc_map
    jc .fat_fail
    call fat_refresh_cluster_accounting
    jc .fat_fail
    cmp dword [fat_root_sectors], FAT_ROOT_CACHE_SECTORS
    ja .fat_fail
    call fat_cache_root_dir
    jc .fat_fail

    call fat_find_primary_asset
    jc .primary_asset_fail
    mov eax, [primary_asset_size]
    add eax, PAGE_SIZE - 1
    shr eax, 12
    mov ecx, eax
    mov eax, PRIMARY_ASSET_LOAD_ADDR
    call pmm_reserve_pages
    call fat_load_primary_asset
    jc .primary_asset_fail
    call primary_package_parse
    jc .primary_package_parse_fail
    call fat_find_writable_files
    call fat_find_persistence_markers

    clc
    ret

.ata_fail:
    mov byte [ata_status], 2
    ret

.fat_fail:
    mov byte [fat_status], 2
    ret

.primary_asset_fail:
    mov byte [primary_asset_status], 2
    ret

.primary_package_parse_fail:
    mov byte [primary_package_parse_status], 2
    ret

ata_io_delay:
    push ecx
    push edx

    mov ecx, 4
    mov dx, ATA_COMMAND_STATUS

.delay_next:
    in al, dx
    loop .delay_next

    pop edx
    pop ecx
    ret

ata_wait_not_busy:
    push ecx
    push edx

    mov dword [ata_wait_phase], ATA_WAIT_BUSY
    mov ecx, ATA_WAIT_POLL_LIMIT
    mov dx, ATA_COMMAND_STATUS

.wait_next:
    in al, dx
    movzx eax, al
    mov [ata_last_status], eax
    test al, ATA_STATUS_BSY
    jz .not_busy
    loop .wait_next
    inc dword [ata_wait_failures]
    inc dword [ata_wait_timeouts]
    mov dword [ata_last_error], 0
    stc
    jmp .done

.not_busy:
    test al, ATA_STATUS_DF | ATA_STATUS_ERR
    jnz .error

.ok:
    mov dword [ata_wait_phase], ATA_WAIT_IDLE
    clc
    jmp .done

.error:
    mov dx, ATA_ERROR
    in al, dx
    movzx eax, al
    mov [ata_last_error], eax
    inc dword [ata_wait_failures]
    inc dword [ata_wait_error_failures]
    stc

.done:
    pop edx
    pop ecx
    ret

ata_wait_drq:
    push ecx
    push edx

    mov dword [ata_wait_phase], ATA_WAIT_DRQ
    mov ecx, ATA_WAIT_POLL_LIMIT
    mov dx, ATA_COMMAND_STATUS

.wait_next:
    in al, dx
    movzx eax, al
    mov [ata_last_status], eax
    test al, ATA_STATUS_BSY
    jnz .advance
    test al, ATA_STATUS_DF | ATA_STATUS_ERR
    jnz .error
    test al, ATA_STATUS_DRQ
    jnz .ok

.advance:
    loop .wait_next

    inc dword [ata_wait_failures]
    inc dword [ata_wait_timeouts]
    mov dword [ata_last_error], 0
    stc
    jmp .done

.error:
    mov dx, ATA_ERROR
    in al, dx
    movzx eax, al
    mov [ata_last_error], eax
    inc dword [ata_wait_failures]
    inc dword [ata_wait_error_failures]
    stc
    jmp .done

.ok:
    mov dword [ata_wait_phase], ATA_WAIT_IDLE
    clc

.done:
    pop edx
    pop ecx
    ret

ata_wait_ready:
    push ecx
    push edx

    mov dword [ata_wait_phase], ATA_WAIT_READY
    mov ecx, ATA_WAIT_POLL_LIMIT
    mov dx, ATA_COMMAND_STATUS

.wait_next:
    in al, dx
    movzx eax, al
    mov [ata_last_status], eax
    test al, ATA_STATUS_BSY
    jnz .advance
    test al, ATA_STATUS_DF | ATA_STATUS_ERR
    jnz .error
    test al, ATA_STATUS_DRQ
    jz .ok

.advance:
    loop .wait_next

    inc dword [ata_wait_failures]
    inc dword [ata_wait_timeouts]
    mov dword [ata_last_error], 0
    stc
    jmp .done

.error:
    mov dx, ATA_ERROR
    in al, dx
    movzx eax, al
    mov [ata_last_error], eax
    inc dword [ata_wait_failures]
    inc dword [ata_wait_error_failures]
    stc
    jmp .done

.ok:
    mov dword [ata_wait_phase], ATA_WAIT_IDLE
    clc

.done:
    pop edx
    pop ecx
    ret

ata_select_lba28_sector:
    push eax
    push ebx
    push ecx
    push edx

    mov ebx, eax
    mov eax, ebx
    shr eax, 24
    and al, 0x0f
    or al, 0xe0
    mov dx, ATA_DRIVE_HEAD
    out dx, al
    call ata_io_delay

    mov dx, ATA_SECTOR_COUNT
    mov al, cl
    out dx, al

    mov eax, ebx
    mov dx, ATA_LBA_LOW
    out dx, al

    mov eax, ebx
    shr eax, 8
    mov dx, ATA_LBA_MID
    out dx, al

    mov eax, ebx
    shr eax, 16
    mov dx, ATA_LBA_HIGH
    out dx, al

    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

ata_read_sector:
    push ebx
    push ecx
    push edx

    mov ebx, eax
    mov dword [ata_last_op], ATA_OP_READ
    mov [ata_last_lba], eax
    mov dword [ata_last_error], 0
    call ata_wait_ready
    jc .fail

    mov eax, ebx
    mov cl, 1
    call ata_select_lba28_sector

    mov dx, ATA_COMMAND_STATUS
    mov al, ATA_CMD_READ_SECTORS
    out dx, al
    call ata_io_delay

    call ata_wait_drq
    jc .fail

    cld
    mov dword [ata_wait_phase], ATA_WAIT_DATA
    mov dx, ATA_DATA
    mov ecx, 256
.read_word:
    in ax, dx
    mov [edi], ax
    add edi, 2
    loop .read_word
    mov dword [ata_wait_phase], ATA_WAIT_IDLE
    call ata_io_delay
    mov byte [ata_status], 1
    clc
    jmp .done

.fail:
    mov byte [ata_status], 2
    stc

.done:
    pop edx
    pop ecx
    pop ebx
    ret

ata_write_sector:
    push ebx
    push ecx
    push edx
    push esi

    mov ebx, eax
    mov dword [ata_last_op], ATA_OP_WRITE
    mov [ata_last_lba], eax
    mov dword [ata_last_error], 0
    call ata_wait_ready
    jc .fail

    mov eax, ebx
    mov cl, 1
    call ata_select_lba28_sector

    mov dx, ATA_COMMAND_STATUS
    mov al, ATA_CMD_WRITE_SECTORS
    out dx, al
    call ata_io_delay

    call ata_wait_drq
    jc .fail

    cld
    mov dword [ata_wait_phase], ATA_WAIT_DATA
    mov dx, ATA_DATA
    mov ecx, 256
.write_word:
    mov ax, [esi]
    out dx, ax
    add esi, 2
    loop .write_word
    mov dword [ata_wait_phase], ATA_WAIT_IDLE
    call ata_io_delay
    call ata_wait_ready
    jc .fail
    mov byte [ata_status], 1
    clc
    jmp .done

.fail:
    mov byte [ata_status], 2
    stc

.done:
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

ata_flush_cache:
    push edx

    mov dword [ata_last_op], ATA_OP_FLUSH
    mov dword [ata_last_error], 0
    ; CACHE FLUSH is a non-data command: completion is BSY clear with no error.
    ; Some emulated IDE targets can leave DRQ visible in the status byte after
    ; the command, so do not use the data-command ready predicate here.
    call ata_wait_not_busy
    jc .fail

    mov dx, ATA_COMMAND_STATUS
    mov al, ATA_CMD_CACHE_FLUSH
    out dx, al
    call ata_io_delay

    call ata_wait_not_busy
    jc .fail
    inc dword [ata_flush_count]
    clc
    jmp .done

.fail:
    inc dword [ata_flush_failures]
    mov byte [ata_status], 2
    stc

.done:
    pop edx
    ret

block_device_init:
    call block_driver_install_ata_pio_ops
    jc .fail_install
    mov dword [block_device_status], BLOCK_STATUS_IDLE
    mov dword [block_last_error], BLOCK_ERROR_NONE
    call ata_wait_ready
    jc .fail
    mov dword [block_device_status], BLOCK_STATUS_OK
    mov dword [block_last_error], BLOCK_ERROR_NONE
    clc
    ret

.fail_install:
    mov dword [block_device_status], BLOCK_STATUS_FAIL
    inc dword [block_error_count]
    stc
    ret

.fail:
    mov dword [block_device_status], BLOCK_STATUS_FAIL
    mov dword [block_last_error], BLOCK_ERROR_ATA_IO
    inc dword [block_error_count]
    stc
    ret

block_driver_install_ata_pio_ops:
    push esi
    mov eax, BLOCK_DEVICE_ATA_PIO
    mov esi, block_ata_pio_ops
    call block_driver_install_ops
    pop esi
    ret

block_driver_install_ops:
    push ebx
    mov ebx, eax
    mov eax, [esi + BLOCK_OPS_READ_OFFSET]
    test eax, eax
    jz .bad_ops
    mov [block_driver_read_op], eax
    mov eax, [esi + BLOCK_OPS_WRITE_OFFSET]
    test eax, eax
    jz .bad_ops
    mov [block_driver_write_op], eax
    mov eax, [esi + BLOCK_OPS_FLUSH_OFFSET]
    test eax, eax
    jz .bad_ops
    mov [block_driver_flush_op], eax
    mov [block_device_kind], ebx
    mov dword [block_last_error], BLOCK_ERROR_NONE
    clc
    jmp .done

.bad_ops:
    mov dword [block_device_kind], BLOCK_DEVICE_NONE
    mov dword [block_driver_read_op], 0
    mov dword [block_driver_write_op], 0
    mov dword [block_driver_flush_op], 0
    mov dword [block_last_error], BLOCK_ERROR_UNSUPPORTED_CONTROLLER
    stc

.done:
    pop ebx
    ret

block_driver_probe_storage_classes:
    push eax
    or dword [pci_diag_flags], PCI_DIAG_STATUS_ONLY_CONSUMER
    mov dword [ahci_required_mask], AHCI_PROOF_REQUIRED_MASK
    mov dword [ahci_observed_mask], 0
    mov dword [ahci_guard_mask], AHCI_GUARD_NO_SILENT_BIND
    cmp dword [block_device_kind], BLOCK_DEVICE_ATA_PIO
    jne .probe_storage
    or dword [ahci_guard_mask], AHCI_GUARD_ATA_ONLY_OPS

.probe_storage:
    mov eax, [pci_lookup_ide_bdf]
    mov [block_driver_supported_bdf], eax
    mov eax, [pci_lookup_ahci_bdf]
    mov [block_driver_ahci_bdf], eax
    call block_driver_record_ahci_probe
    cmp eax, PCI_LOOKUP_NOT_FOUND
    je .done
    mov eax, BLOCK_DEVICE_AHCI
    call block_driver_reject_unsupported_controller

.done:
    pop eax
    ret

block_driver_reject_unsupported_controller:
    inc dword [block_driver_reject_count]
    mov [block_driver_last_rejected_kind], eax
    cmp eax, BLOCK_DEVICE_AHCI
    jne .done
    or dword [ahci_guard_mask], AHCI_GUARD_UNSUPPORTED_REJECTED

.done:
    ret

block_driver_record_ahci_probe:
    push eax
    push ebx
    push edx
    mov [ahci_probe_bdf], eax
    mov dword [ahci_bar5_raw], 0xffffffff
    mov dword [ahci_bar5_base], 0
    mov dword [ahci_bar_state], AHCI_BAR_STATE_NONE
    cmp eax, PCI_LOOKUP_NOT_FOUND
    je .done
    or dword [ahci_observed_mask], AHCI_PROOF_REQ_PCI_CLASS
    mov ebx, PCI_CONFIG_BAR5_REG
    call pci_config_read_dword_by_bdf
    mov [ahci_bar5_raw], eax
    test eax, 1
    jnz .invalid_bar
    mov edx, eax
    and edx, 0xfffffff0
    mov [ahci_bar5_base], edx
    test edx, edx
    jz .invalid_bar
    mov dword [ahci_bar_state], AHCI_BAR_STATE_MMIO
    or dword [ahci_observed_mask], AHCI_PROOF_REQ_BAR5_MMIO
    jmp .done

.invalid_bar:
    mov dword [ahci_bar_state], AHCI_BAR_STATE_INVALID

.done:
    pop edx
    pop ebx
    pop eax
    ret

block_read_sector:
    cmp dword [block_device_kind], BLOCK_DEVICE_NONE
    je .fail_no_device
    mov dword [block_last_op], BLOCK_OP_READ
    mov [block_last_lba], eax
    mov dword [block_last_count], 1
    mov dword [block_last_error], BLOCK_ERROR_NONE
    call dword [block_driver_read_op]
    jc .fail
    inc dword [block_transfer_count]
    mov dword [block_device_status], BLOCK_STATUS_OK
    mov dword [block_last_error], BLOCK_ERROR_NONE
    clc
    ret

.fail_no_device:
    mov byte [ata_status], 2
    mov dword [block_last_error], BLOCK_ERROR_NO_DEVICE
    jmp .record_fail

.fail:
    mov dword [block_last_error], BLOCK_ERROR_ATA_IO

.record_fail:
    mov dword [block_device_status], BLOCK_STATUS_FAIL
    inc dword [block_error_count]
    stc
    ret

block_write_sector:
    cmp dword [block_device_kind], BLOCK_DEVICE_NONE
    je .fail_no_device
    mov dword [block_last_op], BLOCK_OP_WRITE
    mov [block_last_lba], eax
    mov dword [block_last_count], 1
    mov dword [block_last_error], BLOCK_ERROR_NONE
    call dword [block_driver_write_op]
    jc .fail
    call dword [block_driver_flush_op]
    jc .flush_fail
    inc dword [block_transfer_count]
    inc dword [block_flush_count]
    mov dword [block_device_status], BLOCK_STATUS_OK
    mov dword [block_last_error], BLOCK_ERROR_NONE
    clc
    ret

.fail_no_device:
    mov byte [ata_status], 2
    mov dword [block_last_error], BLOCK_ERROR_NO_DEVICE
    jmp .record_fail

.fail:
    mov dword [block_last_error], BLOCK_ERROR_ATA_IO
    jmp .record_fail

.flush_fail:
    mov dword [block_last_error], BLOCK_ERROR_ATA_FLUSH

.record_fail:
    mov dword [block_device_status], BLOCK_STATUS_FAIL
    inc dword [block_error_count]
    stc
    ret

block_flush:
    cmp dword [block_device_kind], BLOCK_DEVICE_NONE
    je .fail_no_device
    mov dword [block_last_op], BLOCK_OP_FLUSH
    mov dword [block_last_count], 0
    mov dword [block_last_error], BLOCK_ERROR_NONE
    call dword [block_driver_flush_op]
    jc .fail
    inc dword [block_flush_count]
    mov dword [block_device_status], BLOCK_STATUS_OK
    mov dword [block_last_error], BLOCK_ERROR_NONE
    clc
    ret

.fail_no_device:
    mov byte [ata_status], 2
    mov dword [block_last_error], BLOCK_ERROR_NO_DEVICE
    jmp .record_fail

.fail:
    mov dword [block_last_error], BLOCK_ERROR_ATA_FLUSH

.record_fail:
    mov dword [block_device_status], BLOCK_STATUS_FAIL
    inc dword [block_error_count]
    stc
    ret

block_read_sectors:
    push ebx
    push ecx
    push edx

    cmp dword [block_device_kind], BLOCK_DEVICE_NONE
    je .fail_no_device
    mov ebx, eax
    mov edx, ecx
    mov dword [block_last_op], BLOCK_OP_READ
    mov [block_last_lba], eax
    mov [block_last_count], ecx
    mov dword [block_last_error], BLOCK_ERROR_NONE
    cmp edx, 0
    je .ok

.read_loop:
    mov eax, ebx
    call dword [block_driver_read_op]
    jc .fail
    inc dword [block_transfer_count]
    inc ebx
    dec edx
    jnz .read_loop

.ok:
    mov dword [block_device_status], BLOCK_STATUS_OK
    mov dword [block_last_error], BLOCK_ERROR_NONE
    clc
    jmp .done

.fail_no_device:
    mov byte [ata_status], 2
    mov dword [block_last_error], BLOCK_ERROR_NO_DEVICE
    jmp .record_fail

.fail:
    mov dword [block_last_error], BLOCK_ERROR_ATA_IO

.record_fail:
    mov dword [block_device_status], BLOCK_STATUS_FAIL
    inc dword [block_error_count]
    stc

.done:
    pop edx
    pop ecx
    pop ebx
    ret

block_write_sectors:
    push ebx
    push ecx
    push edx
    push esi

    cmp dword [block_device_kind], BLOCK_DEVICE_NONE
    je .fail_no_device
    mov ebx, eax
    mov edx, ecx
    mov dword [block_last_op], BLOCK_OP_WRITE
    mov [block_last_lba], eax
    mov [block_last_count], ecx
    mov dword [block_last_error], BLOCK_ERROR_NONE
    cmp edx, 0
    je .ok

.write_loop:
    mov eax, ebx
    call dword [block_driver_write_op]
    jc .fail
    inc dword [block_transfer_count]
    add esi, BLOCK_SECTOR_BYTES
    inc ebx
    dec edx
    jnz .write_loop
    call dword [block_driver_flush_op]
    jc .flush_fail
    inc dword [block_flush_count]

.ok:
    mov dword [block_device_status], BLOCK_STATUS_OK
    mov dword [block_last_error], BLOCK_ERROR_NONE
    clc
    jmp .done

.fail_no_device:
    mov byte [ata_status], 2
    mov dword [block_last_error], BLOCK_ERROR_NO_DEVICE
    jmp .record_fail

.fail:
    mov dword [block_last_error], BLOCK_ERROR_ATA_IO
    jmp .record_fail

.flush_fail:
    mov dword [block_last_error], BLOCK_ERROR_ATA_FLUSH

.record_fail:
    mov dword [block_device_status], BLOCK_STATUS_FAIL
    inc dword [block_error_count]
    stc

.done:
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

block_partition_select_fat16:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov dword [block_partition_status], BLOCK_PARTITION_NONE
    mov dword [block_partition_error], BLOCK_ERROR_NONE
    mov dword [block_partition_index], 0xffffffff
    mov dword [block_partition_type], 0
    mov dword [block_partition_lba_base], 0
    mov dword [block_partition_sector_count], 0

    xor eax, eax
    mov edi, SECTOR_BUFFER_ADDR
    call block_read_sector
    jc .read_fail

    cmp word [SECTOR_BUFFER_ADDR + MBR_SIGNATURE_OFFSET], MBR_SIGNATURE_VALUE
    jne .raw_device

    mov esi, SECTOR_BUFFER_ADDR + MBR_PARTITION_TABLE_OFFSET
    xor ebx, ebx

.scan_next:
    cmp ebx, MBR_PARTITION_COUNT
    jae .maybe_raw_bpb
    movzx eax, byte [esi + MBR_PARTITION_TYPE_OFFSET]
    cmp al, MBR_PARTITION_TYPE_FAT16_CHS
    je .candidate
    cmp al, MBR_PARTITION_TYPE_FAT16_LARGE
    je .candidate
    cmp al, MBR_PARTITION_TYPE_FAT16_LBA
    je .candidate
    add esi, MBR_PARTITION_ENTRY_BYTES
    inc ebx
    jmp .scan_next

.candidate:
    mov edx, [esi + MBR_PARTITION_SECTORS_OFFSET]
    cmp edx, 0
    je .next_entry
    mov ecx, [esi + MBR_PARTITION_LBA_OFFSET]
    cmp ecx, 0
    je .next_entry
    mov eax, ecx
    add eax, edx
    jc .next_entry
    movzx eax, byte [esi + MBR_PARTITION_TYPE_OFFSET]
    mov [block_partition_type], eax
    mov [block_partition_index], ebx
    mov [block_partition_lba_base], ecx
    mov [block_partition_sector_count], edx
    mov dword [block_partition_status], BLOCK_PARTITION_MBR_FAT16
    mov dword [block_partition_error], BLOCK_ERROR_NONE
    clc
    jmp .done

.next_entry:
    add esi, MBR_PARTITION_ENTRY_BYTES
    inc ebx
    jmp .scan_next

.maybe_raw_bpb:
    cmp word [SECTOR_BUFFER_ADDR + 11], BLOCK_SECTOR_BYTES
    jne .no_fat_partition
    cmp word [SECTOR_BUFFER_ADDR + 22], 0
    jne .raw_device

.no_fat_partition:
    mov dword [block_partition_status], BLOCK_PARTITION_FAIL
    mov dword [block_partition_error], BLOCK_ERROR_NO_FAT_PARTITION
    mov dword [block_last_error], BLOCK_ERROR_NO_FAT_PARTITION
    mov dword [block_device_status], BLOCK_STATUS_FAIL
    inc dword [block_error_count]
    stc
    jmp .done

.raw_device:
    mov dword [block_partition_status], BLOCK_PARTITION_RAW
    mov dword [block_partition_error], BLOCK_ERROR_NONE
    mov dword [block_partition_index], 0xffffffff
    mov dword [block_partition_type], 0
    mov dword [block_partition_lba_base], 0
    mov dword [block_partition_sector_count], 0
    clc
    jmp .done

.read_fail:
    mov dword [block_partition_status], BLOCK_PARTITION_FAIL
    mov dword [block_partition_error], BLOCK_ERROR_MBR_READ
    mov dword [block_last_error], BLOCK_ERROR_MBR_READ
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

block_selected_validate:
    push edx

    cmp dword [block_partition_status], BLOCK_PARTITION_RAW
    je .ok
    cmp dword [block_partition_status], BLOCK_PARTITION_MBR_FAT16
    jne .fail_no_partition

    mov edx, eax
    cmp ecx, 0
    je .check_zero_count
    add edx, ecx
    jc .fail_range
    cmp edx, [block_partition_sector_count]
    ja .fail_range
    jmp .ok

.check_zero_count:
    cmp eax, [block_partition_sector_count]
    ja .fail_range
    jmp .ok

.ok:
    mov dword [block_partition_error], BLOCK_ERROR_NONE
    clc
    jmp .done

.fail_no_partition:
    mov dword [block_partition_error], BLOCK_ERROR_NO_FAT_PARTITION
    mov dword [block_last_error], BLOCK_ERROR_NO_FAT_PARTITION
    jmp .record_fail

.fail_range:
    mov dword [block_partition_error], BLOCK_ERROR_PARTITION_RANGE
    mov dword [block_last_error], BLOCK_ERROR_PARTITION_RANGE

.record_fail:
    mov dword [block_device_status], BLOCK_STATUS_FAIL
    inc dword [block_error_count]
    stc

.done:
    pop edx
    ret

block_selected_translate_lba:
    push edx

    mov [block_last_partition_lba], eax
    call block_selected_validate
    jc .done
    cmp dword [block_partition_status], BLOCK_PARTITION_MBR_FAT16
    jne .ok
    add eax, [block_partition_lba_base]
    jc .fail_range

.ok:
    clc
    jmp .done

.fail_range:
    mov dword [block_partition_error], BLOCK_ERROR_PARTITION_RANGE
    mov dword [block_last_error], BLOCK_ERROR_PARTITION_RANGE
    mov dword [block_device_status], BLOCK_STATUS_FAIL
    inc dword [block_error_count]
    stc

.done:
    pop edx
    ret

block_selected_read_sector:
    push ecx
    mov dword [block_last_op], BLOCK_OP_READ
    mov dword [block_last_count], 1
    mov ecx, 1
    call block_selected_translate_lba
    pop ecx
    jc .fail
    call block_read_sector
    ret

.fail:
    stc
    ret

block_selected_write_sector:
    push ecx
    mov dword [block_last_op], BLOCK_OP_WRITE
    mov dword [block_last_count], 1
    mov ecx, 1
    call block_selected_translate_lba
    pop ecx
    jc .fail
    call block_write_sector
    ret

.fail:
    stc
    ret

block_selected_read_sectors:
    mov dword [block_last_op], BLOCK_OP_READ
    mov [block_last_count], ecx
    call block_selected_translate_lba
    jc .fail
    call block_read_sectors
    ret

.fail:
    stc
    ret

block_selected_write_sectors:
    mov dword [block_last_op], BLOCK_OP_WRITE
    mov [block_last_count], ecx
    call block_selected_translate_lba
    jc .fail
    call block_write_sectors
    ret

.fail:
    stc
    ret

fat_cache_root_dir:
    push ecx
    push edi

    mov eax, [fat_root_lba]
    mov ecx, [fat_root_sectors]
    mov edi, fat_root_cache
    call block_selected_read_sectors
    jc .fail

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop ecx
    ret

fat_cache_table:
    xor eax, eax
    call fat_cache_table_copy
    ret

fat_cache_table_copy:
    push ecx
    push edx
    push edi

    mov [fat_cache_copy_index], eax
    mov ecx, [fat_sectors_per_fat]
    mul ecx
    add eax, [fat_start_lba]
    mov [fat_cache_copy_lba], eax
    mov ecx, [fat_sectors_per_fat]
    mov edi, fat_table_cache
    call block_selected_read_sectors
    jc .fail

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop edx
    pop ecx
    ret

fat_probe_free_clusters:
    push eax
    push ebx
    push ecx

    mov dword [fat_alloc_probe_free_count], 0
    mov dword [fat_alloc_probe_first_free], 0
    mov ebx, 2

.probe_loop:
    cmp ebx, [fat_last_data_cluster]
    ja .ok
    mov eax, ebx
    call fat_next_cluster
    jc .fail
    cmp ax, 0
    jne .next
    inc dword [fat_alloc_probe_free_count]
    cmp dword [fat_alloc_probe_first_free], 0
    jne .next
    mov [fat_alloc_probe_first_free], ebx

.next:
    inc ebx
    jmp .probe_loop

.ok:
    clc
    jmp .done

.fail:
    mov dword [fat_alloc_probe_first_free], 0xffffffff
    stc

.done:
    pop ecx
    pop ebx
    pop eax
    ret

fat_refresh_cluster_accounting:
    push eax
    push ebx
    push ecx
    push edx

    mov dword [fat_account_free_clusters], 0
    mov dword [fat_account_used_clusters], 0
    mov dword [fat_accounted_clusters], 0
    mov dword [fat_account_status], 0xffffffff
    cmp byte [fat_status], 1
    jne .fail
    mov ebx, 2
    mov ecx, [fat_last_data_cluster]
    cmp ecx, ebx
    jb .fail

.scan_loop:
    cmp ebx, [fat_last_data_cluster]
    ja .ok
    mov eax, ebx
    call fat_next_cluster
    jc .fail
    cmp ax, 0
    jne .used_cluster
    inc dword [fat_account_free_clusters]
    jmp .accounted

.used_cluster:
    inc dword [fat_account_used_clusters]

.accounted:
    inc dword [fat_accounted_clusters]
    inc ebx
    jmp .scan_loop

.ok:
    mov dword [fat_account_status], 0
    or dword [fat_generic_abi_mask], FAT_ABI_ACCOUNTING
    mov dword [fat_generic_last_op], FAT_ABI_ACCOUNTING
    clc
    jmp .done

.fail:
    stc

.done:
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fat_build_alloc_map:
    push eax
    push ebx
    push ecx
    push edi

    mov edi, fat_alloc_map
    mov al, 1
    mov ecx, FAT_ALLOC_MAP_BYTES
    cld
    rep stosb
    mov ebx, 2

.loop:
    cmp ebx, [fat_last_data_cluster]
    ja .ok
    cmp ebx, FAT_ALLOC_MAP_BYTES
    jae .fail
    mov eax, ebx
    call fat_next_cluster
    jc .fail
    mov byte [fat_alloc_map + ebx], 1
    cmp ax, 0
    jne .next
    mov byte [fat_alloc_map + ebx], 0

.next:
    inc ebx
    jmp .loop

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop ecx
    pop ebx
    pop eax
    ret

fat_name_match:
    push ecx
    push esi
    push edi

    mov ecx, 11
    repe cmpsb
    sete al

    pop edi
    pop esi
    pop ecx
    ret

fat_find_file:
    mov [fat_search_name], edi
    xor ebx, ebx

.sector_loop:
    cmp ebx, [fat_root_sectors]
    jae .fail
    mov esi, ebx
    shl esi, 9
    add esi, fat_root_cache
    mov ecx, 16

.entry_loop:
    cmp byte [esi], 0
    je .fail
    cmp byte [esi], 0xe5
    je .next_entry
    mov al, [esi + 11]
    test al, 0x18
    jnz .next_entry
    push ebx
    push ecx
    mov edi, [fat_search_name]
    call fat_name_match
    pop ecx
    pop ebx
    cmp al, 1
    je .found

.next_entry:
    add esi, 32
    loop .entry_loop
    inc ebx
    jmp .sector_loop

.found:
    mov eax, [fat_root_lba]
    add eax, ebx
    mov [fat_found_root_lba], eax
    mov al, [esi + 11]
    mov [fat_found_attributes], al
    mov eax, esi
    sub eax, fat_root_cache
    and eax, 511
    mov [fat_found_root_offset], eax
    mov ax, [esi + 26]
    mov [fat_found_first_cluster], ax
    mov eax, [esi + 28]
    mov [fat_found_size], eax
    clc
    ret

.fail:
    stc
    ret

fat_find_root_entry_any:
    mov [fat_search_name], edi
    xor ebx, ebx

.sector_loop:
    cmp ebx, [fat_root_sectors]
    jae .fail
    mov esi, ebx
    shl esi, 9
    add esi, fat_root_cache
    mov ecx, 16

.entry_loop:
    cmp byte [esi], 0
    je .fail
    cmp byte [esi], 0xe5
    je .next_entry
    mov al, [esi + 11]
    test al, FAT_ATTR_VOLUME_ID
    jnz .next_entry
    push ebx
    push ecx
    mov edi, [fat_search_name]
    call fat_name_match
    pop ecx
    pop ebx
    cmp al, 1
    je .found

.next_entry:
    add esi, 32
    loop .entry_loop
    inc ebx
    jmp .sector_loop

.found:
    mov eax, [fat_root_lba]
    add eax, ebx
    mov [fat_found_root_lba], eax
    mov al, [esi + 11]
    mov [fat_found_attributes], al
    mov eax, esi
    sub eax, fat_root_cache
    and eax, 511
    mov [fat_found_root_offset], eax
    mov ax, [esi + 26]
    mov [fat_found_first_cluster], ax
    mov eax, [esi + 28]
    mov [fat_found_size], eax
    clc
    ret

.fail:
    stc
    ret

fat_find_primary_asset:
    mov edi, primary_asset_name_83
    call fat_find_file
    jc .fail
    mov ax, [fat_found_first_cluster]
    mov [primary_asset_first_cluster], ax
    mov eax, [fat_found_size]
    mov [primary_asset_size], eax
    clc
    ret

.fail:
    stc
    ret

fat_next_cluster:
    push ebx
    push ecx
    push edx

    shl eax, 1
    mov ebx, eax
    mov eax, [fat_sectors_per_fat]
    shl eax, 9
    cmp ebx, eax
    jae .fail
    movzx eax, word [fat_table_cache + ebx]
    clc
    jmp .done

.fail:
    stc

.done:
    pop edx
    pop ecx
    pop ebx
    ret

fat_write_cluster_entry:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [fat_mut_cluster], eax
    mov [fat_mut_value], dx
    shl eax, 1
    xor edx, edx
    mov ecx, 512
    div ecx
    mov [fat_mut_sector_index], eax
    mov [fat_mut_entry_offset], edx
    cmp eax, [fat_sectors_per_fat]
    jae .fail
    mov esi, eax
    shl esi, 9
    add esi, fat_table_cache
    mov edx, [fat_mut_entry_offset]
    mov ax, [fat_mut_value]
    mov [esi + edx], ax
    xor ebx, ebx

.fat_copy_loop:
    cmp ebx, [fat_count]
    jae .ok
    mov eax, [fat_sectors_per_fat]
    mul ebx
    add eax, [fat_start_lba]
    add eax, [fat_mut_sector_index]
    mov esi, [fat_mut_sector_index]
    shl esi, 9
    add esi, fat_table_cache
    ; FAT uses the selected block interface; the block layer owns low-level ATA writes.
    call block_selected_write_sector
    jc .fail
    inc ebx
    jmp .fat_copy_loop

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fat_store_cached_cluster_entry:
    push eax
    push ebx

    mov ebx, eax
    shl ebx, 1
    mov eax, [fat_sectors_per_fat]
    shl eax, 9
    cmp ebx, eax
    jae .fail
    mov [fat_table_cache + ebx], dx
    clc
    jmp .done

.fail:
    stc

.done:
    pop ebx
    pop eax
    ret

fat_flush_table:
    push ebx
    push ecx
    push edx
    push esi

    xor ebx, ebx

.copy_loop:
    cmp ebx, [fat_count]
    jae .ok
    mov eax, [fat_sectors_per_fat]
    mul ebx
    add eax, [fat_start_lba]
    mov ecx, [fat_sectors_per_fat]
    mov esi, fat_table_cache
    call block_selected_write_sectors
    jc .fail

    inc ebx
    jmp .copy_loop

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

fat_free_tail_after_current:
    push eax
    push ebx
    push ecx
    push edx

    movzx ebx, ax
    mov [fat_lba_tail_free_cluster], ebx
    mov dword [fat_lba_tail_free_count], 0
    cmp ebx, 2
    jb .fail
    cmp ebx, [fat_last_data_cluster]
    ja .fail
    mov ecx, [fat_last_data_cluster]

.validate_loop:
    cmp ebx, 0xfff8
    jae .validated
    cmp ebx, 2
    jb .fail
    cmp ebx, [fat_last_data_cluster]
    ja .fail
    cmp ecx, 0
    je .fail
    mov eax, ebx
    call fat_next_cluster
    jc .fail
    cmp ax, 0
    je .fail
    movzx ebx, ax
    dec ecx
    jmp .validate_loop

.validated:
    inc dword [fat_free_operation_count]
    movzx eax, word [fat_current_cluster]
    mov dx, 0xffff
    call fat_store_cached_cluster_entry
    jc .fail
    movzx ebx, word [fat_lba_tail_free_cluster]

.free_loop:
    cmp ebx, 0xfff8
    jae .flush
    mov eax, ebx
    call fat_next_cluster
    jc .fail
    mov [fat_free_next_cluster], ax
    mov eax, ebx
    xor edx, edx
    call fat_store_cached_cluster_entry
    jc .fail
    mov byte [fat_alloc_map + ebx], 0
    inc dword [fat_free_cluster_count]
    inc dword [fat_lba_tail_free_count]
    movzx ebx, word [fat_free_next_cluster]
    jmp .free_loop

.flush:
    mov dword [fat_next_free_hint], 2
    call fat_flush_table
    jc .fail
    or dword [fat_generic_abi_mask], FAT_ABI_FREE_TAIL
    mov dword [fat_generic_last_op], FAT_ABI_FREE_TAIL
    clc
    jmp .done

.fail:
    stc

.done:
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fat_zero_cluster:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    cmp eax, 2
    jb .fail
    cmp eax, [fat_last_data_cluster]
    ja .fail
    sub eax, 2
    movzx ebx, byte [fat_sectors_per_cluster]
    mul ebx
    add eax, [fat_data_lba]
    mov [fat_current_lba], eax
    mov edi, SECTOR_BUFFER_ADDR
    xor eax, eax
    mov ecx, 512 / 4
    cld
    rep stosd
    movzx ecx, byte [fat_sectors_per_cluster]

.sector_loop:
    cmp ecx, 0
    je .ok
    push ecx
    mov eax, [fat_current_lba]
    mov esi, SECTOR_BUFFER_ADDR
    call block_selected_write_sector
    pop ecx
    jc .fail
    inc dword [fat_current_lba]
    dec ecx
    jmp .sector_loop

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fat_alloc_cluster:
    push ebx
    push ecx
    push edx
    push edi

    mov dword [fat_alloc_scan_refreshed], 0
    mov dword [fat_alloc_fail_stage], 0
    mov dword [fat_alloc_scan_cluster], 0
    mov dword [fat_alloc_found_cluster], 0
    mov dword [fat_alloc_last_entry], 0
    mov dword [fat_alloc_copy_retry_done], 0
    mov dword [fat_alloc_retry_copy_index], 0
    mov dword [fat_alloc_probe_first_free], 0
    mov dword [fat_alloc_probe_free_count], 0
    mov eax, [fat_last_data_cluster]
    mov [fat_alloc_last_data_snapshot], eax

.start_scan:
    mov dword [fat_alloc_debug_stage], 1
    mov dword [fat_alloc_fail_stage], 0
    mov ebx, [fat_next_free_hint]
    mov [fat_alloc_debug_hint], ebx
    cmp ebx, 2
    jae .hint_min_ok
    mov ebx, 2

.hint_min_ok:
    cmp ebx, [fat_last_data_cluster]
    jbe .hint_ready
    mov ebx, 2

.hint_ready:
    mov [fat_scan_start], ebx
    mov [fat_alloc_scan_start_snapshot], ebx

.scan_loop:
    cmp ebx, [fat_last_data_cluster]
    ja .wrap_scan
    mov [fat_alloc_scan_cluster], ebx
    mov eax, ebx
    call fat_next_cluster
    jc .fat_read_fail
    mov [fat_alloc_last_entry], eax
    cmp ax, 0
    je .fat_entry_free
    mov byte [fat_alloc_map + ebx], 1
    inc ebx
    jmp .scan_loop

.fat_entry_free:
    cmp byte [fat_alloc_map + ebx], 0
    je .found
    inc dword [fat_alloc_map_repairs]
    mov byte [fat_alloc_map + ebx], 0
    jmp .found

.fat_read_fail:
    mov dword [fat_alloc_fail_stage], 1
    jmp .fail

.scan_exhausted:
    mov dword [fat_alloc_fail_stage], 2
    jmp .retry_or_fail

.wrap_exhausted:
    mov dword [fat_alloc_fail_stage], 3
    jmp .retry_or_fail

.wrap_read_fail:
    mov dword [fat_alloc_fail_stage], 4
    jmp .fail

.write_fail:
    mov dword [fat_alloc_fail_stage], 5
    jmp .fail

.zero_fail:
    mov dword [fat_alloc_fail_stage], 6
    jmp .rollback_alloc

.rollback_write_fail:
    mov dword [fat_alloc_fail_stage], 7
    jmp .fail

.wrap_scan:
    mov ebx, 2
    cmp ebx, [fat_scan_start]
    jae .scan_exhausted

.wrap_loop:
    cmp ebx, [fat_scan_start]
    jae .wrap_exhausted
    mov [fat_alloc_scan_cluster], ebx
    mov eax, ebx
    call fat_next_cluster
    jc .wrap_read_fail
    mov [fat_alloc_last_entry], eax
    cmp ax, 0
    je .wrap_fat_entry_free
    mov byte [fat_alloc_map + ebx], 1
    inc ebx
    jmp .wrap_loop

.wrap_fat_entry_free:
    cmp byte [fat_alloc_map + ebx], 0
    je .found
    inc dword [fat_alloc_map_repairs]
    mov byte [fat_alloc_map + ebx], 0
    jmp .found

.found:
    mov dword [fat_alloc_debug_stage], 2
    mov [fat_alloc_debug_cluster], ebx
    mov eax, ebx
    mov [fat_alloc_found_cluster], ebx
    mov dx, 0xffff
    call fat_write_cluster_entry
    jc .write_fail
    mov eax, ebx
    cmp dword [fat_alloc_zero_policy], 0
    je .allocated
    call fat_zero_cluster
    jc .zero_fail

.allocated:
    mov byte [fat_alloc_map + ebx], 1
    mov dword [fat_alloc_debug_stage], 3
    mov edx, ebx
    inc edx
    cmp edx, [fat_last_data_cluster]
    jbe .store_hint
    mov edx, 2

.store_hint:
    mov [fat_next_free_hint], edx
    inc dword [fat_alloc_success_count]
    or dword [fat_generic_abi_mask], FAT_ABI_ALLOC_CLUSTER
    mov dword [fat_generic_last_op], FAT_ABI_ALLOC_CLUSTER
    mov eax, ebx
    clc
    jmp .done

.rollback_alloc:
    mov dword [fat_alloc_debug_stage], 0xe1
    mov eax, ebx
    xor edx, edx
    call fat_write_cluster_entry
    jc .rollback_write_fail
    mov byte [fat_alloc_map + ebx], 0
    inc dword [fat_alloc_failure_count]
    stc
    jmp .done

.retry_or_fail:
    call fat_probe_free_clusters
    cmp dword [fat_alloc_scan_refreshed], 0
    jne .try_fat_copy_1
    mov dword [fat_alloc_scan_refreshed], 1
    inc dword [fat_alloc_debug_refreshes]
    mov dword [fat_alloc_debug_stage], 0xd0
    call fat_cache_table
    jc .fail
    call fat_build_alloc_map
    jc .fail
    jmp .start_scan

.try_fat_copy_1:
    cmp dword [fat_alloc_copy_retry_done], 0
    jne .fail
    cmp dword [fat_count], 1
    jbe .fail
    mov dword [fat_alloc_copy_retry_done], 1
    mov dword [fat_alloc_retry_copy_index], 1
    inc dword [fat_alloc_debug_refreshes]
    mov dword [fat_alloc_debug_stage], 0xd1
    mov eax, 1
    call fat_cache_table_copy
    jc .fail
    call fat_build_alloc_map
    jc .fail
    mov dword [fat_next_free_hint], 2
    jmp .start_scan

.fail:
    inc dword [fat_alloc_failure_count]
    call fat_probe_free_clusters
    mov dword [fat_alloc_debug_stage], 0xe0
    stc

.done:
    pop edi
    pop edx
    pop ecx
    pop ebx
    ret

fat_free_chain:
    push eax
    push ebx
    push ecx
    push edx

    movzx ebx, ax
    cmp ax, 0
    je .ok
    cmp ebx, 2
    jb .fail
    mov [fat_current_cluster], ax
    mov ecx, [fat_last_data_cluster]

.validate_loop:
    cmp ebx, 0xfff8
    jae .validated
    cmp ebx, 2
    jb .fail
    cmp ebx, [fat_last_data_cluster]
    ja .fail
    cmp ecx, 0
    je .fail
    mov eax, ebx
    call fat_next_cluster
    jc .fail
    cmp ax, 0
    je .fail
    movzx ebx, ax
    dec ecx
    jmp .validate_loop

.validated:
    inc dword [fat_free_operation_count]
    mov dword [fat_next_free_hint], 2
    movzx ebx, word [fat_current_cluster]

.free_loop:
    cmp ebx, 0xfff8
    jae .ok
    cmp ebx, 2
    jb .fail
    cmp ebx, [fat_last_data_cluster]
    ja .fail
    mov eax, ebx
    call fat_next_cluster
    jc .fail
    mov [fat_free_next_cluster], ax
    mov eax, ebx
    xor edx, edx
    call fat_write_cluster_entry
    jc .fail
    mov byte [fat_alloc_map + ebx], 0
    inc dword [fat_free_cluster_count]
    movzx ebx, word [fat_free_next_cluster]
    jmp .free_loop

.ok:
    or dword [fat_generic_abi_mask], FAT_ABI_FREE_CHAIN
    mov dword [fat_generic_last_op], FAT_ABI_FREE_CHAIN
    clc
    jmp .done

.fail:
    stc

.done:
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fat_create_root_file:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [fat_search_name], edi
    xor ebx, ebx

.sector_loop:
    cmp ebx, [fat_root_sectors]
    jae .fail
    mov esi, ebx
    shl esi, 9
    add esi, fat_root_cache
    mov ecx, 16

.entry_loop:
    cmp byte [esi], 0
    je .create_here
    cmp byte [esi], 0xe5
    je .create_here
    add esi, 32
    loop .entry_loop
    inc ebx
    jmp .sector_loop

.create_here:
    push ecx
    push esi
    mov edi, esi
    xor eax, eax
    mov ecx, 32 / 4
    cld
    rep stosd
    pop esi
    mov edi, esi
    mov esi, [fat_search_name]
    mov ecx, 11
    cld
    rep movsb
    pop ecx
    mov byte [edi], 0x20
    mov eax, [fat_root_lba]
    add eax, ebx
    mov [fat_found_root_lba], eax
    mov eax, edi
    sub eax, 11
    sub eax, fat_root_cache
    and eax, 511
    mov [fat_found_root_offset], eax
    mov word [fat_found_first_cluster], 0
    mov dword [fat_found_size], 0
    mov byte [fat_found_attributes], FAT_ATTR_ARCHIVE
    mov eax, [fat_found_root_lba]
    mov esi, ebx
    shl esi, 9
    add esi, fat_root_cache
    ; FAT root creation goes through the selected block interface before low-level ATA.
    call block_selected_write_sector
    jc .fail
    inc dword [fat_dir_update_count]
    or dword [fat_generic_abi_mask], FAT_ABI_DIR_UPDATE
    mov dword [fat_generic_last_op], FAT_ABI_DIR_UPDATE
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

fat_load_file:
