.done:
    pop ebx
    pop eax
    ret

fd_reset_all:
    push ebx
    push ecx

    mov ecx, USER_FD_COUNT
    xor ebx, ebx

.loop:
    mov byte [fd_status + ebx], FD_STATUS_FREE
    mov byte [fd_kinds + ebx], FD_KIND_FREE
    mov dword [fd_indices + ebx * 4], 0
    mov dword [fd_offsets + ebx * 4], 0
    mov dword [fd_flags + ebx * 4], 0
    mov dword [fd_file_sizes + ebx * 4], 0
    mov dword [fd_owner_pids + ebx * 4], 0xffffffff
    mov dword [fd_inherit_flags + ebx * 4], 0
    mov dword [fd_description_roots + ebx * 4], 0
    mov dword [fd_refcounts + ebx * 4], 0
    inc ebx
    loop .loop

    call pipe_reset_all
    call eventfd_reset_all
    call epoll_reset_all
    call timerfd_reset_all

    pop ecx
    pop ebx
    ret

pipe_reset_all:
    push ebx
    push ecx

    mov ecx, PIPE_SLOT_COUNT
    xor ebx, ebx

.loop:
    mov byte [pipe_status + ebx], 0
    mov byte [pipe_read_open + ebx], 0
    mov byte [pipe_write_open + ebx], 0
    mov dword [pipe_lengths + ebx * 4], 0
    inc ebx
    loop .loop

    pop ecx
    pop ebx
    ret

eventfd_reset_all:
    push ebx
    push ecx

    mov ecx, EVENTFD_SLOT_COUNT
    xor ebx, ebx

.loop:
    mov byte [eventfd_status + ebx], 0
    mov dword [eventfd_counter_low + ebx * 4], 0
    mov dword [eventfd_counter_high + ebx * 4], 0
    inc ebx
    loop .loop

    pop ecx
    pop ebx
    ret

epoll_reset_all:
    push ebx
    push ecx

    mov ecx, EPOLL_SLOT_COUNT
    xor ebx, ebx

.slot_loop:
    mov byte [epoll_status + ebx], 0
    inc ebx
    loop .slot_loop

    mov ecx, EPOLL_ENTRY_COUNT
    xor ebx, ebx

.entry_loop:
    mov byte [epoll_entry_status + ebx], 0
    mov dword [epoll_entry_owner + ebx * 4], 0
    mov dword [epoll_entry_fd + ebx * 4], 0
    mov dword [epoll_entry_events + ebx * 4], 0
    mov dword [epoll_entry_data_low + ebx * 4], 0
    mov dword [epoll_entry_data_high + ebx * 4], 0
    inc ebx
    loop .entry_loop

    pop ecx
    pop ebx
    ret

timerfd_reset_all:
    push ebx
    push ecx

    mov ecx, TIMERFD_SLOT_COUNT
    xor ebx, ebx

.loop:
    mov byte [timerfd_status + ebx], 0
    mov dword [timerfd_clockid + ebx * 4], 0
    mov dword [timerfd_expirations_low + ebx * 4], 0
    mov dword [timerfd_expirations_high + ebx * 4], 0
    inc ebx
    loop .loop

    pop ecx
    pop ebx
    ret

pipe_close_root_fd:
    push eax
    push ebx

    cmp ebx, USER_FD_COUNT
    jae .done
    cmp byte [fd_kinds + ebx], FD_KIND_PIPE_READ
    je .close_read
    cmp byte [fd_kinds + ebx], FD_KIND_PIPE_WRITE
    jne .done
    mov eax, [fd_indices + ebx * 4]
    cmp eax, PIPE_SLOT_COUNT
    jae .done
    mov byte [pipe_write_open + eax], 0
    jmp .maybe_free

.close_read:
    mov eax, [fd_indices + ebx * 4]
    cmp eax, PIPE_SLOT_COUNT
    jae .done
    mov byte [pipe_read_open + eax], 0

.maybe_free:
    cmp byte [pipe_read_open + eax], 0
    jne .done
    cmp byte [pipe_write_open + eax], 0
    jne .done
    mov byte [pipe_status + eax], 0
    mov dword [pipe_lengths + eax * 4], 0

.done:
    pop ebx
    pop eax
    ret

fd_close_root_resources:
    push eax
    push ebx

    cmp ebx, USER_FD_COUNT
    jae .done
    cmp byte [fd_kinds + ebx], FD_KIND_PIPE_READ
    je .close_pipe
    cmp byte [fd_kinds + ebx], FD_KIND_PIPE_WRITE
    je .close_pipe
    cmp byte [fd_kinds + ebx], FD_KIND_EVENTFD
    je .close_eventfd
    cmp byte [fd_kinds + ebx], FD_KIND_EPOLL
    je .close_epoll
    cmp byte [fd_kinds + ebx], FD_KIND_TIMERFD
    jne .done

.close_timerfd:
    mov eax, [fd_indices + ebx * 4]
    cmp eax, TIMERFD_SLOT_COUNT
    jae .done
    mov byte [timerfd_status + eax], 0
    mov dword [timerfd_expirations_low + eax * 4], 0
    mov dword [timerfd_expirations_high + eax * 4], 0
    jmp .done

.close_eventfd:
    mov eax, [fd_indices + ebx * 4]
    cmp eax, EVENTFD_SLOT_COUNT
    jae .done
    mov byte [eventfd_status + eax], 0
    mov dword [eventfd_counter_low + eax * 4], 0
    mov dword [eventfd_counter_high + eax * 4], 0
    jmp .done

.close_epoll:
    mov eax, [fd_indices + ebx * 4]
    cmp eax, EPOLL_SLOT_COUNT
    jae .done
    push ecx
    push edx
    mov byte [epoll_status + eax], 0
    mov edx, eax
    mov ecx, EPOLL_ENTRY_COUNT
    xor eax, eax

.close_epoll_entry_loop:
    cmp [epoll_entry_owner + eax * 4], edx
    jne .close_epoll_next
    mov byte [epoll_entry_status + eax], 0
    mov dword [epoll_entry_fd + eax * 4], 0
    mov dword [epoll_entry_events + eax * 4], 0
    mov dword [epoll_entry_data_low + eax * 4], 0
    mov dword [epoll_entry_data_high + eax * 4], 0

.close_epoll_next:
    inc eax
    loop .close_epoll_entry_loop
    pop edx
    pop ecx
    jmp .done

.close_pipe:
    call pipe_close_root_fd

.done:
    pop ebx
    pop eax
    ret

fd_alloc:
    push ebx

    xor ebx, ebx

.loop:
    cmp ebx, USER_FD_COUNT
    jae .fail
    cmp byte [fd_status + ebx], FD_STATUS_FREE
    je .found
    inc ebx
    jmp .loop

.found:
    call fd_prepare_current_descriptor
    test dword [syscall_open_flags], O_CLOEXEC
    jnz .no_exec_inherit
    mov dword [fd_inherit_flags + ebx * 4], FD_INHERIT_EXEC
    jmp .inherit_done

.no_exec_inherit:
    mov dword [fd_inherit_flags + ebx * 4], 0

.inherit_done:
    mov eax, ebx
    clc
    jmp .done

.fail:
    stc

.done:
    pop ebx
    ret

fd_prepare_current_descriptor:
    push eax
    mov byte [fd_status + ebx], FD_STATUS_OPEN
    mov byte [fd_kinds + ebx], FD_KIND_FREE
    mov dword [fd_indices + ebx * 4], 0
    mov dword [fd_offsets + ebx * 4], 0
    mov dword [fd_flags + ebx * 4], 0
    mov dword [fd_file_sizes + ebx * 4], 0
    mov eax, [current_pid]
    mov [fd_owner_pids + ebx * 4], eax
    inc dword [fd_open_generations + ebx * 4]
    mov dword [fd_inherit_flags + ebx * 4], FD_INHERIT_EXEC
    mov [fd_description_roots + ebx * 4], ebx
    mov dword [fd_refcounts + ebx * 4], 1
    pop eax
    ret

fd_lookup_descriptor:
    mov eax, ebx
    sub eax, USER_FD_BASE
    cmp eax, USER_FD_COUNT
    jae .fail
    cmp byte [fd_status + eax], FD_STATUS_OPEN
    jne .fail
    push edx
    mov edx, [current_pid]
    cmp [fd_owner_pids + eax * 4], edx
    pop edx
    jne .fail
    clc
    ret

.fail:
    stc
    ret

fd_lookup:
    call fd_lookup_descriptor
    jc .fail
    push edx
    mov [file_io_user_fd_slot], eax
    mov edx, [fd_description_roots + eax * 4]
    cmp edx, USER_FD_COUNT
    jae .root_fail
    cmp byte [fd_status + edx], FD_STATUS_OPEN
    jne .root_fail
    cmp dword [fd_refcounts + edx * 4], 0
    je .root_fail
    mov eax, edx
    mov [file_io_fd_slot], eax
    pop edx
    clc
    ret

.root_fail:
    pop edx

.fail:
    stc
    ret

fd_clear_slot:
    mov byte [fd_status + ebx], FD_STATUS_FREE
    mov byte [fd_kinds + ebx], FD_KIND_FREE
    mov dword [fd_indices + ebx * 4], 0
    mov dword [fd_offsets + ebx * 4], 0
    mov dword [fd_flags + ebx * 4], 0
    mov dword [fd_file_sizes + ebx * 4], 0
    mov dword [fd_owner_pids + ebx * 4], 0xffffffff
    mov dword [fd_inherit_flags + ebx * 4], 0
    mov dword [fd_description_roots + ebx * 4], 0
    mov dword [fd_refcounts + ebx * 4], 0
    ret

fd_clone_descriptor:
    push eax
    mov [fd_description_roots + edi * 4], ebx
    mov dword [fd_refcounts + edi * 4], 0
    inc dword [fd_refcounts + ebx * 4]
    mov al, [fd_kinds + ebx]
    mov [fd_kinds + edi], al
    mov eax, [fd_indices + ebx * 4]
    mov [fd_indices + edi * 4], eax
    mov eax, [fd_offsets + ebx * 4]
    mov [fd_offsets + edi * 4], eax
    mov eax, [fd_flags + ebx * 4]
    mov [fd_flags + edi * 4], eax
    mov eax, [fd_file_sizes + ebx * 4]
    mov [fd_file_sizes + edi * 4], eax
    mov [fd_inherit_flags + edi * 4], edx
    inc dword [fd_dup_shared]
    pop eax
    ret

fd_close_slot:
    pushad
    mov esi, ebx
    cmp esi, USER_FD_COUNT
    jae .done
    cmp byte [fd_status + esi], FD_STATUS_OPEN
    jne .done
    mov edx, [fd_description_roots + esi * 4]
    cmp edx, USER_FD_COUNT
    jb .root_ready
    mov edx, esi

.root_ready:
    cmp dword [fd_refcounts + edx * 4], 0
    je .clear_descriptor
    cmp esi, edx
    je .close_root
    dec dword [fd_refcounts + edx * 4]
    mov ebx, esi
    call fd_clear_slot
    cmp dword [fd_refcounts + edx * 4], 0
    jne .done
    mov ebx, edx
    call fd_close_root_resources
    call fd_clear_slot
    jmp .done

.close_root:
    cmp dword [fd_refcounts + edx * 4], 1
    ja .promote_root
    mov ebx, edx
    call fd_close_root_resources
    call fd_clear_slot
    jmp .done

.promote_root:
    xor edi, edi

.find_alias:
    cmp edi, USER_FD_COUNT
    jae .clear_descriptor
    cmp edi, edx
    je .next_alias
    cmp byte [fd_status + edi], FD_STATUS_OPEN
    jne .next_alias
    cmp [fd_description_roots + edi * 4], edx
    je .alias_found

.next_alias:
    inc edi
    jmp .find_alias

.alias_found:
    mov al, [fd_kinds + edx]
    mov [fd_kinds + edi], al
    mov eax, [fd_indices + edx * 4]
    mov [fd_indices + edi * 4], eax
    mov eax, [fd_offsets + edx * 4]
    mov [fd_offsets + edi * 4], eax
    mov eax, [fd_flags + edx * 4]
    mov [fd_flags + edi * 4], eax
    mov eax, [fd_file_sizes + edx * 4]
    mov [fd_file_sizes + edi * 4], eax
    mov eax, [fd_refcounts + edx * 4]
    dec eax
    mov [fd_refcounts + edi * 4], eax
    mov [fd_description_roots + edi * 4], edi
    xor ebx, ebx

.retarget_next:
    cmp ebx, USER_FD_COUNT
    jae .clear_old_root
    cmp byte [fd_status + ebx], FD_STATUS_OPEN
    jne .retarget_advance
    cmp [fd_description_roots + ebx * 4], edx
    jne .retarget_advance
    mov [fd_description_roots + ebx * 4], edi

.retarget_advance:
    inc ebx
    jmp .retarget_next

.clear_old_root:
    mov ebx, edx
    call fd_clear_slot
    jmp .done

.clear_descriptor:
    mov ebx, esi
    call fd_clear_slot

.done:
    popad
    ret

fd_close_owned_by_pid:
    push ebx
    push ecx
    push edx

    mov edx, eax
    mov [fd_last_closed_owner_pid], edx
    mov ecx, USER_FD_COUNT
    xor ebx, ebx

.loop:
    cmp byte [fd_status + ebx], FD_STATUS_OPEN
    jne .next
    cmp [fd_owner_pids + ebx * 4], edx
    jne .next
    call fd_close_slot
    inc dword [fd_owner_closes]

.next:
    inc ebx
    loop .loop

    pop edx
    pop ecx
    pop ebx
    ret

fd_close_owned_by_process:
    push eax
    cmp esi, 0
    je .done
    cmp esi, process_kernel
    je .done
    mov eax, [esi + PROC_PID]
    call fd_close_owned_by_pid

.done:
    pop eax
    ret

fd_exec_handoff:
    push eax
    push ebx
    push ecx
    push edx
    push esi

    mov [fd_last_exec_from_pid], eax
    mov [fd_last_exec_to_pid], edx
    inc dword [fd_exec_handoffs]
    mov esi, eax
    mov ecx, USER_FD_COUNT
    xor ebx, ebx

.loop:
    cmp byte [fd_status + ebx], FD_STATUS_OPEN
    jne .next
    cmp [fd_owner_pids + ebx * 4], esi
    jne .next
    test dword [fd_inherit_flags + ebx * 4], FD_INHERIT_EXEC
    jz .close_on_exec
    mov [fd_owner_pids + ebx * 4], edx
    inc dword [fd_exec_inherited]
    jmp .next

.close_on_exec:
    call fd_close_slot
    inc dword [fd_exec_closed]

.next:
    inc ebx
    loop .loop

    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fd_find_free_slot:
    push ebx
    push ecx

    xor ebx, ebx
    mov ecx, USER_FD_COUNT

.scan_next:
    cmp ecx, 0
    je .fail
    cmp byte [fd_status + ebx], FD_STATUS_FREE
    je .found
    inc ebx
    dec ecx
    jmp .scan_next

.found:
    mov eax, ebx
    clc
    jmp .done

.fail:
    stc

.done:
    pop ecx
    pop ebx
    ret

fd_fork_clone_owned_by_pid:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [fd_fork_parent_pid], eax
    mov [fd_fork_child_pid], edx
    mov dword [fd_fork_clones_last], 0
    xor esi, esi

.source_next:
    cmp esi, USER_FD_COUNT
    jae .success
    cmp byte [fd_status + esi], FD_STATUS_OPEN
    jne .advance
    mov eax, [fd_fork_parent_pid]
    cmp [fd_owner_pids + esi * 4], eax
    jne .advance
    mov ebx, [fd_description_roots + esi * 4]
    cmp ebx, USER_FD_COUNT
    jae .fail
    cmp byte [fd_status + ebx], FD_STATUS_OPEN
    jne .fail
    cmp dword [fd_refcounts + ebx * 4], 0
    je .fail
    call fd_find_free_slot
    jc .fail
    mov edi, eax
    mov byte [fd_status + edi], FD_STATUS_OPEN
    mov eax, [fd_fork_child_pid]
    mov [fd_owner_pids + edi * 4], eax
    inc dword [fd_open_generations + edi * 4]
    mov edx, [fd_inherit_flags + esi * 4]
    call fd_clone_descriptor
    inc dword [fd_fork_clones_last]

.advance:
    inc esi
    jmp .source_next

.success:
    clc
    jmp .done

.fail:
    mov eax, [fd_fork_child_pid]
    call fd_close_owned_by_pid
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

writable_fd_index:
    call fd_lookup
    jc .fail
    cmp byte [fd_kinds + eax], FD_KIND_WRITABLE
    jne .fail
    mov ebx, [fd_indices + eax * 4]
    cmp ebx, WRITABLE_FILE_COUNT
    jae .fail
    cmp byte [writable_status + ebx], 1
    jne .fail
    mov [file_io_index], ebx
    clc
    ret

.fail:
    stc
    ret

readonly_fd_index:
    call fd_lookup
    jc .fail
    cmp byte [fd_kinds + eax], FD_KIND_READONLY_FILE
    jne .fail
    mov [file_io_index], eax
    clc
    ret

.fail:
    stc
    ret

readonly_fd_is_primary_asset_file:
    push eax
    push esi

    mov esi, [file_io_fd_slot]
    movzx eax, word [primary_asset_first_cluster]
    cmp [fd_indices + esi * 4], eax
    jne .fail
    mov eax, [primary_asset_size]
    cmp [fd_file_sizes + esi * 4], eax
    jne .fail
    clc
    jmp .done

.fail:
    stc

.done:
    pop esi
    pop eax
    ret

fat_file_lba_for_offset:
    push ecx
    push edx

    mov ebx, edx
    and ebx, 511
    shr edx, 9
    mov [fat_current_cluster], ax

.cluster_loop:
    movzx ecx, byte [fat_sectors_per_cluster]
    cmp edx, ecx
    jb .have_cluster
    sub edx, ecx
    movzx eax, word [fat_current_cluster]
    call fat_next_cluster
    jc .fail
    cmp eax, 2
    jb .fail
    cmp eax, 0xfff8
    jae .fail
    mov [fat_current_cluster], ax
    jmp .cluster_loop

.have_cluster:
    mov ecx, edx
    movzx eax, word [fat_current_cluster]
    cmp eax, 2
    jb .fail
    cmp eax, 0xfff8
    jae .fail
    sub eax, 2
    movzx edx, byte [fat_sectors_per_cluster]
    mul edx
    add eax, [fat_data_lba]
    add eax, ecx
    clc
    jmp .done

.fail:
    stc

.done:
    pop edx
    pop ecx
    ret

fat_file_lba_for_write:
    push ecx
    push edx
    push esi

    mov dword [fat_lba_fail_stage], 0
    mov dword [fat_file_lba_was_new_cluster], 0
    mov dword [fat_lba_logical_sectors], 0
    mov dword [fat_lba_tail_free_cluster], 0
    mov dword [fat_lba_tail_free_count], 0
    mov dword [fat_lba_walked_sectors], 0
    mov dword [fat_lba_next_boundary], 0
    mov dword [fat_lba_branch_code], 0
    mov dword [fat_lba_branch_cluster], 0
    mov dword [fat_lba_branch_next], 0
    mov esi, ebx
    mov ebx, edx
    and ebx, 511
    shr edx, 9
    mov [fat_lba_sector_index], edx
    mov eax, [writable_sizes + esi * 4]
    add eax, 511
    shr eax, 9
    mov [fat_lba_logical_sectors], eax
    mov ax, [writable_first_clusters + esi * 2]
    cmp ax, 2
    jae .have_first_cluster
    mov dword [fat_lba_fail_stage], 1
    call fat_alloc_cluster
    jc .fail
    mov [writable_first_clusters + esi * 2], ax
    mov dword [fat_file_lba_was_new_cluster], 1

.have_first_cluster:
    mov [fat_current_cluster], ax
    movzx eax, ax
    mov [fat_lba_current_cluster], eax

.cluster_loop:
    movzx ecx, byte [fat_sectors_per_cluster]
    cmp edx, ecx
    jb .have_cluster
    mov eax, [fat_lba_walked_sectors]
    add eax, ecx
    mov [fat_lba_next_boundary], eax
    cmp eax, [fat_lba_logical_sectors]
    jb .follow_existing_chain
    jmp .extend_after_current

.follow_existing_chain:
    mov dword [fat_lba_branch_code], 0x20
    sub edx, ecx
    add [fat_lba_walked_sectors], ecx
    movzx eax, word [fat_current_cluster]
    mov [fat_lba_current_cluster], eax
    mov [fat_lba_branch_cluster], eax
    mov dword [fat_lba_fail_stage], 2
    call fat_next_cluster
    jc .fail
    mov [fat_lba_next_cluster], eax
    mov [fat_lba_branch_next], eax
    cmp eax, 2
    jb .fail
    cmp eax, 0xfff8
    jb .next_exists
    jmp .fail

.extend_after_current:
    mov dword [fat_lba_branch_code], 0x30
    sub edx, ecx
    add [fat_lba_walked_sectors], ecx
    movzx eax, word [fat_current_cluster]
    mov [fat_lba_current_cluster], eax
    mov [fat_lba_branch_cluster], eax
    mov dword [fat_lba_fail_stage], 2
    call fat_next_cluster
    jc .fail
    mov [fat_lba_next_cluster], eax
    mov [fat_lba_branch_next], eax

.free_stale_tail_before_growth:
    cmp eax, 2
    jb .allocate_next_cluster
    cmp eax, 0xfff8
    jae .allocate_next_cluster
    mov [fat_lba_tail_free_cluster], eax
    mov dword [fat_lba_fail_stage], 9
    call fat_free_tail_after_current
    jc .fail

.allocate_next_cluster:
    mov dword [fat_lba_branch_code], 0x40
    mov dword [fat_lba_fail_stage], 3
    call fat_alloc_cluster
    jc .fail
    mov [fat_new_cluster], ax
    movzx eax, ax
    mov [fat_lba_new_cluster], eax
    mov dword [fat_file_lba_was_new_cluster], 1
    movzx eax, word [fat_current_cluster]
    push edx
    mov dx, [fat_new_cluster]
    mov dword [fat_lba_fail_stage], 4
    call fat_write_cluster_entry
    pop edx
    jnc .linked_new_cluster
    movzx eax, word [fat_new_cluster]
    push edx
    xor edx, edx
    call fat_write_cluster_entry
    pop edx
    jmp .fail

.linked_new_cluster:
    mov ax, [fat_new_cluster]

.next_exists:
    cmp dword [fat_lba_branch_code], 0x40
    je .next_exists_from_alloc
    mov dword [fat_lba_branch_code], 0x50

.next_exists_from_alloc:
    mov [fat_lba_next_cluster], eax
    mov dword [fat_lba_fail_stage], 5
    cmp eax, 2
    jb .fail
    mov dword [fat_lba_fail_stage], 6
    cmp eax, 0xfff8
    jae .fail
    mov [fat_current_cluster], ax
    jmp .cluster_loop

.have_cluster:
    mov dword [fat_lba_branch_code], 0x60
    mov ecx, edx
    movzx eax, word [fat_current_cluster]
    mov [fat_lba_current_cluster], eax
    mov dword [fat_lba_fail_stage], 7
    cmp eax, 2
    jb .fail
    mov dword [fat_lba_fail_stage], 8
    cmp eax, 0xfff8
    jae .fail
    sub eax, 2
    movzx edx, byte [fat_sectors_per_cluster]
    mul edx
    add eax, [fat_data_lba]
    add eax, ecx
    mov [fat_lba_result_lba], eax
    mov dword [fat_lba_fail_stage], 0
    clc
    jmp .done

.fail:
    stc
    jmp .done

.done:
    pop esi
    pop edx
    pop ecx
    ret

fat_update_writable_size:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov ebx, eax
    mov eax, [writable_root_lbas + ebx * 4]
    sub eax, [fat_root_lba]
    cmp eax, [fat_root_sectors]
    jae .load_directory_sector
    mov esi, eax
    shl esi, 9
    add esi, fat_root_cache
    jmp .update_entry

.load_directory_sector:
    mov eax, [writable_root_lbas + ebx * 4]
    mov edi, SECTOR_BUFFER_ADDR
    ; Non-cached directory updates use the selected block interface before low-level ATA.
    call block_selected_read_sector
    jc .fail
    mov esi, SECTOR_BUFFER_ADDR

.update_entry:
    mov edx, [writable_root_offsets + ebx * 4]
    mov ax, [esi + edx + 26]
    mov [fat_dir_update_old_first_cluster], ax
    mov ecx, [esi + edx + 28]
    mov [fat_dir_update_old_size], ecx
    mov ax, [writable_first_clusters + ebx * 2]
    mov [esi + edx + 26], ax
    mov ecx, [writable_sizes + ebx * 4]
    mov [esi + edx + 28], ecx
    mov eax, [writable_root_lbas + ebx * 4]
    ; Size updates use the selected block interface before low-level ATA.
    call block_selected_write_sector
    jc .fail_restore_entry
    inc dword [fat_dir_update_count]
    or dword [fat_generic_abi_mask], FAT_ABI_DIR_UPDATE
    mov dword [fat_generic_last_op], FAT_ABI_DIR_UPDATE
    clc
    jmp .done

.fail_restore_entry:
    mov edx, [writable_root_offsets + ebx * 4]
    mov ax, [fat_dir_update_old_first_cluster]
    mov [esi + edx + 26], ax
    mov ecx, [fat_dir_update_old_size]
    mov [esi + edx + 28], ecx

.fail:
    inc dword [fat_dir_update_failures]
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

fat_truncate_writable_file:
    push ebx

    mov ebx, eax
    mov ax, [writable_first_clusters + ebx * 2]
    mov [fat_truncate_old_first_cluster], ax
    mov eax, [writable_sizes + ebx * 4]
    mov [fat_truncate_old_size], eax
    mov eax, [writable_offsets + ebx * 4]
    mov [fat_truncate_old_offset], eax
    mov word [writable_first_clusters + ebx * 2], 0
    mov dword [writable_sizes + ebx * 4], 0
    mov dword [writable_offsets + ebx * 4], 0
    mov eax, ebx
    call fat_update_writable_size
    jc .rollback_root
    mov ax, [fat_truncate_old_first_cluster]
    cmp ax, 2
    jb .truncated
    call fat_free_chain
    jc .fail

.truncated:
    inc dword [fat_truncate_count]
    or dword [fat_generic_abi_mask], FAT_ABI_TRUNCATE_ZERO
    mov dword [fat_generic_last_op], FAT_ABI_TRUNCATE_ZERO
    clc
    jmp .done

.rollback_root:
    mov ax, [fat_truncate_old_first_cluster]
    mov [writable_first_clusters + ebx * 2], ax
    mov eax, [fat_truncate_old_size]
    mov [writable_sizes + ebx * 4], eax
    mov eax, [fat_truncate_old_offset]
    mov [writable_offsets + ebx * 4], eax
    stc
    jmp .done

.fail:
    stc

.done:
    pop ebx
    ret

fat_zero_writable_range:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [file_zero_index], eax
    mov [file_zero_offset], ecx
    mov [file_zero_end], edx
    cmp ecx, edx
    ja .fail
    je .ok
    mov ebx, eax
    cmp ebx, WRITABLE_FILE_COUNT
    jae .fail
    cmp byte [writable_status + ebx], 1
    jne .fail
    mov eax, [writable_capacity_table + ebx * 4]
    cmp [file_zero_end], eax
    ja .fail
    call fat_cache_table
    jc .fail
    call fat_build_alloc_map
    jc .fail

.loop:
    mov eax, [file_zero_offset]
    cmp eax, [file_zero_end]
    jae .ok
    mov ebx, [file_zero_index]
    mov edx, eax
    mov dword [fat_alloc_zero_policy], 1
    call fat_file_lba_for_write
    mov dword [fat_alloc_zero_policy], 1
    jc .fail
    mov [file_io_sector_lba], eax
    mov [file_io_sector_offset], ebx
    mov eax, 512
    sub eax, [file_io_sector_offset]
    mov edx, [file_zero_end]
    sub edx, [file_zero_offset]
    cmp eax, edx
    jbe .chunk_ready
    mov eax, edx

.chunk_ready:
    mov [file_zero_chunk], eax
    cmp dword [file_io_sector_offset], 0
    jne .prepare_partial_sector
    cmp dword [file_zero_chunk], 512
    jne .prepare_partial_sector
    call fat_zero_sector_buffer
    jmp .write_sector

.prepare_partial_sector:
    cmp dword [fat_file_lba_was_new_cluster], 1
    je .zero_sector_buffer
    mov eax, [file_io_sector_lba]
    mov edi, SECTOR_BUFFER_ADDR
    call block_selected_read_sector
    jc .fail
    jmp .zero_chunk

.zero_sector_buffer:
    call fat_zero_sector_buffer

.zero_chunk:
    mov edi, SECTOR_BUFFER_ADDR
    add edi, [file_io_sector_offset]
    xor eax, eax
    mov ecx, [file_zero_chunk]
    cld
    rep stosb

.write_sector:
    mov eax, [file_io_sector_lba]
    mov esi, SECTOR_BUFFER_ADDR
    call block_selected_write_sector
    jc .fail
    mov eax, [file_zero_chunk]
    add [file_zero_offset], eax
    mov ebx, [file_zero_index]
    mov eax, [file_zero_offset]
    cmp eax, [writable_sizes + ebx * 4]
    jbe .loop
    mov [writable_sizes + ebx * 4], eax
    jmp .loop

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fat_zero_sector_buffer:
    push eax
    push ecx
    push edi

    mov edi, SECTOR_BUFFER_ADDR
    xor eax, eax
    mov ecx, 512 / 4
    cld
    rep stosd

    pop edi
    pop ecx
    pop eax
    ret

fat_zero_writable_tail_after_size:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [file_zero_index], eax
    mov ebx, eax
    cmp ebx, WRITABLE_FILE_COUNT
    jae .fail
    cmp byte [writable_status + ebx], 1
    jne .fail
    mov ecx, [writable_sizes + ebx * 4]
    mov [file_zero_offset], ecx
    cmp ecx, 0
    je .ok
    mov ax, [writable_first_clusters + ebx * 2]
    cmp ax, 2
    jb .fail

    mov eax, ecx
    movzx ebx, byte [fat_sectors_per_cluster]
    shl ebx, 9
    xor edx, edx
    div ebx
    cmp edx, 0
    je .ok
    inc eax
    mul ebx
    mov [file_zero_end], eax

.loop:
    mov eax, [file_zero_offset]
    cmp eax, [file_zero_end]
    jae .ok
    mov ebx, [file_zero_index]
    mov ax, [writable_first_clusters + ebx * 2]
    mov edx, [file_zero_offset]
    call fat_file_lba_for_offset
    jc .fail
    mov [file_io_sector_lba], eax
    mov [file_io_sector_offset], ebx
    mov eax, 512
    sub eax, [file_io_sector_offset]
    mov edx, [file_zero_end]
    sub edx, [file_zero_offset]
    cmp eax, edx
    jbe .chunk_ready
    mov eax, edx

.chunk_ready:
    mov [file_zero_chunk], eax
    cmp dword [file_io_sector_offset], 0
    jne .prepare_partial_sector
    cmp dword [file_zero_chunk], 512
    jne .prepare_partial_sector
    call fat_zero_sector_buffer
    jmp .write_sector

.prepare_partial_sector:
    mov eax, [file_io_sector_lba]
    mov edi, SECTOR_BUFFER_ADDR
    call block_selected_read_sector
    jc .fail
    mov edi, SECTOR_BUFFER_ADDR
    add edi, [file_io_sector_offset]
    xor eax, eax
    mov ecx, [file_zero_chunk]
    cld
    rep stosb

.write_sector:
    mov eax, [file_io_sector_lba]
    mov esi, SECTOR_BUFFER_ADDR
    call block_selected_write_sector
    jc .fail
    mov eax, [file_zero_chunk]
    add [file_zero_offset], eax
    jmp .loop

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fat_resize_writable_file:
    push eax
    push ebx
    push ecx
    push edx

    mov [file_resize_index], eax
    mov [file_resize_new_size], ecx
    mov ebx, eax
    cmp ebx, WRITABLE_FILE_COUNT
    jae .fail
    cmp byte [writable_status + ebx], 1
    jne .fail
    mov eax, [writable_capacity_table + ebx * 4]
    cmp [file_resize_new_size], eax
    ja .fail
    mov eax, [writable_sizes + ebx * 4]
    mov [file_resize_old_size], eax
    cmp [file_resize_new_size], eax
    ja .grow
    jb .shrink
    clc
    jmp .done

.grow:
    mov eax, [file_resize_index]
    mov ecx, [file_resize_old_size]
    mov edx, [file_resize_new_size]
    call fat_zero_writable_range
    jc .rollback_grow_fail
    mov ebx, [file_resize_index]
    mov eax, [file_resize_new_size]
    mov [writable_sizes + ebx * 4], eax
    mov eax, ebx
    call fat_update_writable_size
    jc .rollback_grow_fail
    inc dword [fat_resize_grow_count]
    or dword [fat_generic_abi_mask], FAT_ABI_RESIZE_GROW
    mov dword [fat_generic_last_op], FAT_ABI_RESIZE_GROW
    clc
    jmp .done

.shrink:
    cmp dword [file_resize_new_size], 0
    je .truncate_zero
    mov ebx, [file_resize_index]
    mov eax, [file_resize_new_size]
    mov [writable_sizes + ebx * 4], eax
    mov eax, [file_resize_index]
    call fat_zero_writable_tail_after_size
    jc .rollback_size_only_fail
    mov eax, ebx
    call fat_update_writable_size
    jc .rollback_size_only_fail
    mov eax, [file_resize_index]
    call fat_clip_writable_chain_to_size
    jc .shrink_clip_fail
    inc dword [fat_resize_shrink_count]
    or dword [fat_generic_abi_mask], FAT_ABI_RESIZE_SHRINK
    mov dword [fat_generic_last_op], FAT_ABI_RESIZE_SHRINK
    clc
    jmp .done

.truncate_zero:
    mov eax, [file_resize_index]
    call fat_truncate_writable_file
    jc .done
    clc
    jmp .done

.rollback_size_only_fail:
    mov ebx, [file_resize_index]
    mov eax, [file_resize_old_size]
    mov [writable_sizes + ebx * 4], eax
    stc
    jmp .done

.rollback_grow_fail:
    mov ebx, [file_resize_index]
    mov eax, [file_resize_old_size]
    mov [writable_sizes + ebx * 4], eax
    mov eax, ebx
    call fat_clip_writable_chain_to_size
    mov eax, [file_resize_index]
    call fat_update_writable_size
    stc
    jmp .done

.shrink_clip_fail:
    stc
    jmp .done

.fail:
    stc

.done:
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fat_clip_writable_chain_to_size:
    push eax
    push ebx
    push ecx
    push edx
    push esi

    mov dword [fat_clip_debug_stage], 1
    mov dword [fat_clip_debug_index], eax
    mov dword [fat_clip_debug_size], 0
    mov dword [fat_clip_debug_first], 0
    mov dword [fat_clip_debug_needed], 0
    mov dword [fat_clip_debug_current], 0
    mov dword [fat_clip_debug_next], 0
    mov dword [fat_clip_debug_result], 0
    mov esi, eax
    cmp esi, WRITABLE_FILE_COUNT
    jae .fail
    mov ax, [writable_first_clusters + esi * 2]
    movzx eax, ax
    mov [fat_clip_debug_first], eax
    mov ebx, [writable_sizes + esi * 4]
    mov [fat_clip_debug_size], ebx
    cmp ebx, 0
    jne .nonempty
    mov dword [fat_clip_debug_stage], 2
    cmp ax, 2
    jb .ok
    call fat_free_chain
    jc .fail
    mov word [writable_first_clusters + esi * 2], 0
    jmp .ok

.nonempty:
    mov dword [fat_clip_debug_stage], 3
    cmp ax, 2
    jb .fail
    mov [fat_current_cluster], ax
    mov eax, ebx
    movzx ecx, byte [fat_sectors_per_cluster]
    shl ecx, 9
    add eax, ecx
    dec eax
    xor edx, edx
    div ecx
    mov ecx, eax
    mov [fat_clip_debug_needed], ecx
    cmp ecx, 0
    je .fail

.walk_needed:
    mov dword [fat_clip_debug_stage], 4
    cmp ecx, 1
    je .at_last_needed
    movzx eax, word [fat_current_cluster]
    mov [fat_clip_debug_current], eax
    call fat_next_cluster
    jc .fail
    cmp eax, 2
    jb .fail
    cmp eax, 0xfff8
    jae .fail
    mov [fat_current_cluster], ax
    dec ecx
    jmp .walk_needed

.at_last_needed:
    mov dword [fat_clip_debug_stage], 5
    movzx eax, word [fat_current_cluster]
    mov [fat_clip_debug_current], eax
    call fat_next_cluster
    jc .fail
    mov [fat_clip_debug_next], eax
    cmp eax, 2
    jb .ok
    cmp eax, 0xfff8
    jae .ok
    mov [fat_lba_tail_free_cluster], eax
    mov dword [fat_lba_fail_stage], 9
    mov dword [fat_clip_debug_stage], 6
    call fat_free_tail_after_current
    jc .fail

.ok:
    mov dword [fat_clip_debug_result], 0
    clc
    jmp .done

.fail:
    mov dword [fat_clip_debug_result], 0xffffffff
    stc

.done:
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fat_delete_found_file:
    push eax
    push edx
    push esi
    push edi

    mov ax, [fat_found_first_cluster]
    mov [fat_delete_old_first_cluster], ax

    mov eax, [fat_found_root_lba]
    sub eax, [fat_root_lba]
    cmp eax, [fat_root_sectors]
    jae .load_directory_sector
    mov esi, eax
    shl esi, 9
    add esi, fat_root_cache
    jmp .clear_entry

.load_directory_sector:
    mov eax, [fat_found_root_lba]
    mov edi, SECTOR_BUFFER_ADDR
    ; Non-cached delete uses the selected block interface before low-level ATA.
    call block_selected_read_sector
    jc .fail
    mov esi, SECTOR_BUFFER_ADDR

.clear_entry:
    mov edx, [fat_found_root_offset]
    mov byte [esi + edx], 0xe5
    mov word [esi + edx + 26], 0
    mov dword [esi + edx + 28], 0
    mov eax, [fat_found_root_lba]
    ; Delete updates use the selected block interface before low-level ATA.
    call block_selected_write_sector
    jc .fail
    inc dword [fat_dir_update_count]
    or dword [fat_generic_abi_mask], FAT_ABI_DIR_UPDATE
    mov dword [fat_generic_last_op], FAT_ABI_DIR_UPDATE
    mov ax, [fat_delete_old_first_cluster]
    cmp ax, 2
    jb .deleted
    call fat_free_chain
    jc .fail

.deleted:
    or dword [fat_generic_abi_mask], FAT_ABI_DELETE_FILE
    mov dword [fat_generic_last_op], FAT_ABI_DELETE_FILE
    clc
    jmp .done

.fail:
    inc dword [fat_dir_update_failures]
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop eax
    ret

stat_fill_user:
    push eax
    push ebx
    push ecx
    push edx
    push edi

    mov [stat_size_arg], eax
    mov [stat_mode_arg], edx
    mov eax, [syscall_stat_ptr]
    mov ebx, STAT_BYTES
    call user_range_validate
    jc .fail
    mov edi, [syscall_stat_ptr]
    xor eax, eax
    mov ecx, STAT_BYTES / 4
    cld
    rep stosd
    mov edi, [syscall_stat_ptr]
    mov eax, [stat_mode_arg]
    mov [edi + STAT_ST_MODE], eax
    mov dword [edi + STAT_ST_NLINK], 1
    mov eax, [stat_size_arg]
    mov [edi + STAT_ST_SIZE], eax
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fat_found_mode:
    push eax

    mov al, [fat_found_attributes]
    call fat_mode_from_attr_al

    pop eax
    ret

fat_mode_from_attr_al:
    test al, FAT_ATTR_DIRECTORY
    jnz .directory
    mov edx, STAT_MODE_WRITABLE_REG
    test al, FAT_ATTR_READ_ONLY
    jz .done
    mov edx, STAT_MODE_READONLY_REG
    jmp .done

.directory:
    mov edx, STAT_MODE_WRITABLE_DIR
    test al, FAT_ATTR_READ_ONLY
    jz .done
    mov edx, STAT_MODE_READONLY_DIR

.done:
    ret

fat_user_path_is_root:
    push eax
    push ebx
    push esi

    mov eax, [syscall_ptr_arg]
    cmp eax, 0
    je .fail
    mov ebx, 4
    call user_range_validate
    jc .fail
    mov esi, [syscall_ptr_arg]
    mov al, [esi]
    cmp al, 0
    je .ok
    cmp al, '.'
    je .dot
    cmp al, '/'
    je .slash
    cmp al, 0x5c
    je .slash
    jmp .fail

.dot:
    mov al, [esi + 1]
    cmp al, 0
    je .ok
    cmp al, '/'
    je .dot_slash
    cmp al, 0x5c
    je .dot_slash
    jmp .fail

.dot_slash:
    cmp byte [esi + 2], 0
    je .ok
    jmp .fail

.slash:
    cmp byte [esi + 1], 0
    je .ok
    jmp .fail

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop esi
    pop ebx
    pop eax
    ret

fat_fill_dirent_from_root_entry:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [fat_list_entry_ptr], esi
    mov [fat_list_output_ptr], edi
    xor eax, eax
    mov ecx, VIBE_DIRENT_BYTES / 4
    cld
    rep stosd
    mov esi, [fat_list_entry_ptr]
    mov edi, [fat_list_output_ptr]
    xor ebx, ebx
    mov ecx, 8

.base_loop:
    cmp ecx, 0
    je .base_done
    mov al, [esi]
    cmp al, ' '
    je .base_done
    mov [edi + ebx], al
    inc esi
    inc ebx
    dec ecx
    jmp .base_loop

.base_done:
    mov esi, [fat_list_entry_ptr]
    cmp byte [esi + 8], ' '
    je .metadata
    cmp ebx, 0
    je .metadata
    cmp ebx, 15
    jae .metadata
    mov byte [edi + ebx], '.'
    inc ebx
    add esi, 8
    mov ecx, 3

.ext_loop:
    cmp ecx, 0
    je .metadata
    cmp ebx, 15
    jae .metadata
    mov al, [esi]
    cmp al, ' '
    je .metadata
    mov [edi + ebx], al
    inc esi
    inc ebx
    dec ecx
    jmp .ext_loop

.metadata:
    mov esi, [fat_list_entry_ptr]
    mov edi, [fat_list_output_ptr]
    mov eax, [esi + 28]
    mov [edi + VIBE_DIRENT_SIZE], eax
    mov al, [esi + 11]
    call fat_mode_from_attr_al

.mode_ready:
    mov [edi + VIBE_DIRENT_MODE], edx
    movzx eax, word [esi + 26]
    mov [edi + VIBE_DIRENT_FIRST_CLUSTER], eax
    movzx eax, byte [esi + 11]
    mov [edi + VIBE_DIRENT_ATTRIBUTES], eax
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

fat_list_user_dir:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    call fat_user_path_is_root
    jnc .root
    call fat_parse_user_subdir_file83
    jc .try_root83
    mov edi, fat_subdir_name_buffer
    call fat_find_root_entry_any
    jc .fail_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jz .fail_enotdir
    mov ax, [fat_found_first_cluster]
    cmp ax, 2
    jb .fail_eio
    mov edi, fat_open_name_buffer
    call fat_find_subdir_entry
    jc .fail_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jz .fail_enotdir
    jmp .fail_inval

.try_root83:
    call fat_parse_user_root83
    jc .fail_inval
    mov edi, fat_open_name_buffer
    call fat_find_root_entry_any
    jc .fail_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jz .fail_enotdir
    mov ax, [fat_found_first_cluster]
    cmp ax, 2
    jb .fail_eio
    mov [fat_list_dir_cluster], ax
    mov eax, [syscall_dirent_max]
    cmp eax, FAT_ROOT_CACHE_SECTORS * 16
    ja .fail_inval
    mov [fat_list_max], eax
    mov eax, [syscall_dirent_ptr]
    mov [fat_list_user_ptr], eax
    mov dword [fat_list_copied], 0
    cmp eax, 0
    jne .validate_user_buffer
    cmp dword [syscall_dirent_max], 0
    jne .fail_inval
    jmp .ok

.validate_user_buffer:
    mov eax, [syscall_dirent_max]
    shl eax, 5
    mov ebx, eax
    mov eax, [fat_list_user_ptr]
    call user_range_validate
    jc .fail_inval
    call fat_list_subdir_cluster
    jc .done
    jmp .done

.root:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    call fat_list_root_dir
    ret

.ok:
    mov eax, [fat_list_copied]
    clc
    jmp .done

.fail_enoent:
    mov eax, -ERRNO_ENOENT
    stc
    jmp .done

.fail_eio:
    mov eax, -ERRNO_EIO
    stc
    jmp .done

.fail_enotdir:
    mov eax, -ERRNO_ENOTDIR
    stc
    jmp .done

.fail_inval:
    mov eax, -ERRNO_EINVAL
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

fat_list_subdir_cluster:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    movzx ebx, word [fat_list_dir_cluster]

.cluster_loop:
    cmp ebx, 2
    jb .ok
    cmp ebx, [fat_last_data_cluster]
    ja .fail_eio
    mov eax, ebx
    sub eax, 2
    movzx edx, byte [fat_sectors_per_cluster]
    mul edx
    add eax, [fat_data_lba]
    mov [fat_list_dir_lba], eax
    movzx eax, byte [fat_sectors_per_cluster]
    mov [fat_list_dir_sectors_left], eax

.sector_loop:
    cmp dword [fat_list_dir_sectors_left], 0
    je .next_cluster
    mov eax, [fat_list_dir_lba]
    mov edi, SECTOR_BUFFER_ADDR
    call block_selected_read_sector
    jc .fail_eio
    inc dword [fat_list_dir_lba]
    dec dword [fat_list_dir_sectors_left]
    mov esi, SECTOR_BUFFER_ADDR
    mov ecx, 16

.entry_loop:
    cmp byte [esi], 0
    je .ok
    cmp byte [esi], 0xe5
    je .next_entry
    cmp byte [esi], '.'
    je .next_entry
    mov al, [esi + 11]
    test al, FAT_ATTR_VOLUME_ID
    jnz .next_entry
    mov eax, [fat_list_copied]
    cmp eax, [fat_list_max]
    jae .ok
    push ebx
    push ecx
    push esi
    mov edi, [fat_list_user_ptr]
    mov ebx, eax
    shl ebx, 5
    add edi, ebx
    call fat_fill_dirent_from_root_entry
    pop esi
    pop ecx
    pop ebx
    inc dword [fat_list_copied]

.next_entry:
    add esi, 32
    loop .entry_loop
    jmp .sector_loop

.next_cluster:
    movzx eax, word [fat_list_dir_cluster]
    call fat_next_cluster
    jc .fail_eio
    cmp eax, 2
    jb .ok
    cmp eax, 0xfff8
    jae .ok
    cmp eax, [fat_last_data_cluster]
    ja .fail_eio
    mov [fat_list_dir_cluster], ax
    mov ebx, eax
    jmp .cluster_loop

.ok:
    mov eax, [fat_list_copied]
    clc
    jmp .done

.fail_eio:
    mov eax, -ERRNO_EIO
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

fat_list_root_dir:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    call fat_user_path_is_root
    jc .fail_inval
    mov eax, [syscall_dirent_max]
    cmp eax, FAT_ROOT_CACHE_SECTORS * 16
    ja .fail_inval
    mov [fat_list_max], eax
    mov eax, [syscall_dirent_ptr]
    mov [fat_list_user_ptr], eax
    mov dword [fat_list_copied], 0
    cmp eax, 0
    jne .validate_user_buffer
    cmp dword [syscall_dirent_max], 0
    jne .fail_inval
    jmp .ok

.validate_user_buffer:
    mov eax, [syscall_dirent_max]
    shl eax, 5
    mov ebx, eax
    mov eax, [fat_list_user_ptr]
    call user_range_validate
    jc .fail_inval
    xor ebx, ebx

.sector_loop:
    cmp ebx, [fat_root_sectors]
    jae .ok
    mov esi, ebx
    shl esi, 9
    add esi, fat_root_cache
    mov ecx, 16

.entry_loop:
    cmp byte [esi], 0
    je .ok
    cmp byte [esi], 0xe5
    je .next_entry
    mov al, [esi + 11]
    test al, 0x08
    jnz .next_entry
    mov eax, [fat_list_copied]
    cmp eax, [fat_list_max]
    jae .ok
    push ebx
    push ecx
    push esi
    mov edi, [fat_list_user_ptr]
    mov ebx, eax
    shl ebx, 5
    add edi, ebx
    call fat_fill_dirent_from_root_entry
    pop esi
    pop ecx
    pop ebx
    inc dword [fat_list_copied]

.next_entry:
    add esi, 32
    loop .entry_loop
    inc ebx
    jmp .sector_loop

.ok:
    mov eax, [fat_list_copied]
    clc
    jmp .done

.fail_inval:
    mov eax, -ERRNO_EINVAL
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

user_file_read:
    call writable_fd_index
    jc .fail_badfd
    mov esi, [file_io_fd_slot]
    mov eax, [fd_flags + esi * 4]
    and eax, O_ACCMODE
    cmp eax, O_WRONLY
    je .fail_badfd
    mov [file_io_user_ptr], ecx
    mov [file_io_remaining], edx
    mov dword [file_io_done], 0
    mov eax, ecx
    mov ebx, edx
    call user_range_validate
    jc .fail_inval
    mov ebx, [file_io_index]
    mov eax, [writable_sizes + ebx * 4]
    mov esi, [file_io_fd_slot]
    cmp [fd_offsets + esi * 4], eax
    jb .have_readable_bytes
    mov dword [file_io_remaining], 0
    jmp .loop

.have_readable_bytes:
    sub eax, [fd_offsets + esi * 4]
    cmp [file_io_remaining], eax
    jbe .loop
    mov [file_io_remaining], eax

.loop:
    cmp dword [file_io_remaining], 0
    je .ok
    mov ebx, [file_io_index]
    mov esi, [file_io_fd_slot]
    mov edx, [fd_offsets + esi * 4]
    mov ax, [writable_first_clusters + ebx * 2]
    call fat_file_lba_for_offset
    jc .fail_io
    mov [file_io_sector_offset], ebx
    mov edi, SECTOR_BUFFER_ADDR
    call block_selected_read_sector
    jc .fail_io
    mov eax, 512
    sub eax, [file_io_sector_offset]
    cmp eax, [file_io_remaining]
    jbe .chunk_ok
    mov eax, [file_io_remaining]

.chunk_ok:
    mov [file_io_chunk], eax
    mov esi, SECTOR_BUFFER_ADDR
    add esi, [file_io_sector_offset]
    mov edi, [file_io_user_ptr]
    add edi, [file_io_done]
    mov ecx, [file_io_chunk]
    cld
    rep movsb
    mov eax, [file_io_chunk]
    add [file_io_done], eax
    sub [file_io_remaining], eax
    mov esi, [file_io_fd_slot]
    add [fd_offsets + esi * 4], eax
    jmp .loop

.ok:
    mov eax, [file_io_done]
    clc
    ret

.fail_badfd:
    mov eax, -ERRNO_EBADF
    stc
    ret

.fail_inval:
    mov eax, -ERRNO_EINVAL
    stc
    ret

.fail_io:
    mov eax, -ERRNO_EIO
    stc
    ret

fat_rollback_file_write_no_progress:
    push eax
    push ebx
    push edx
    push esi

    mov ebx, [file_io_index]
    cmp ebx, WRITABLE_FILE_COUNT
    jae .fail
    cmp byte [writable_status + ebx], 1
    jne .fail
    mov ax, [file_write_old_first_cluster]
    cmp ax, 2
    jae .restore_old_chain
    mov ax, [writable_first_clusters + ebx * 2]
    cmp ax, 2
    jb .restore_empty_metadata
    call fat_free_chain
    jc .fail

.restore_empty_metadata:
    mov word [writable_first_clusters + ebx * 2], 0
    jmp .restore_size

.restore_old_chain:
    mov [writable_first_clusters + ebx * 2], ax

.restore_size:
    mov eax, [file_write_old_size]
    mov [writable_sizes + ebx * 4], eax
    mov eax, ebx
    call fat_clip_writable_chain_to_size
    jc .fail
    mov eax, ebx
    call fat_update_writable_size
    jc .fail
    mov esi, [file_io_fd_slot]
    cmp esi, USER_FD_COUNT
    jae .fail
    mov eax, [file_write_old_offset]
    mov [fd_offsets + esi * 4], eax
    clc
    jmp .done

.fail:
    stc

.done:
    pop esi
    pop edx
    pop ebx
    pop eax
    ret

user_file_write:
    mov dword [file_write_debug_stage], 1
    mov dword [file_write_debug_result], 0
    mov dword [file_write_debug_capacity], 0
    call writable_fd_index
    jc .fail_badfd
    mov esi, [file_io_fd_slot]
    mov eax, [fd_flags + esi * 4]
    and eax, O_ACCMODE
    cmp eax, O_WRONLY
    je .write_mode_ok
    cmp eax, O_RDWR
    jne .fail_badfd

.write_mode_ok:
    mov dword [file_write_debug_stage], 2
    test dword [fd_flags + esi * 4], O_APPEND
    jz .write_offset_ready
    mov ebx, [file_io_index]
    mov eax, [writable_sizes + ebx * 4]
    mov [fd_offsets + esi * 4], eax

.write_offset_ready:
    mov dword [file_write_debug_stage], 3
    mov ebx, [file_io_index]
    mov ax, [writable_first_clusters + ebx * 2]
    mov [file_write_old_first_cluster], ax
    mov eax, [writable_sizes + ebx * 4]
    mov [file_write_old_size], eax
    mov esi, [file_io_fd_slot]
    mov eax, [fd_offsets + esi * 4]
    mov [file_write_old_offset], eax
    mov [file_io_user_ptr], ecx
    mov [file_io_remaining], edx
    mov [file_write_requested], edx
    mov dword [file_io_done], 0
    mov dword [file_write_fail_stage], 0
    mov eax, ecx
    mov ebx, edx
    call user_range_validate
    jc .fail_inval_range
    mov dword [file_write_debug_stage], 4
    mov ebx, [file_io_index]
    mov esi, [file_io_fd_slot]
    mov eax, [writable_capacity_table + ebx * 4]
    mov [file_write_capacity], eax
    sub eax, [fd_offsets + esi * 4]
    mov [file_write_debug_capacity], eax
    cmp [file_io_remaining], eax
    jbe .write_span_ready
    cmp eax, 0
    je .fail_nospc
    mov [file_io_remaining], eax

.write_span_ready:
    cmp dword [file_io_remaining], 0
    je .loop
    mov ebx, [file_io_index]
    mov esi, [file_io_fd_slot]
    mov eax, [fd_offsets + esi * 4]
    cmp eax, [writable_sizes + ebx * 4]
    jbe .write_cache_ready
    mov ecx, [writable_sizes + ebx * 4]
    mov edx, eax
    mov eax, ebx
    call fat_zero_writable_range
    jc .fail_io

.write_cache_ready:
    mov dword [file_write_fail_stage], 9
    call fat_cache_table
    jc .fail_io
    call fat_build_alloc_map
    jc .fail_io
    mov dword [file_write_fail_stage], 0

.loop:
    cmp dword [file_io_remaining], 0
    je .ok
    mov ebx, [file_io_index]
    mov esi, [file_io_fd_slot]
    mov eax, ebx
    call fat_clip_writable_chain_to_size
    jc .fail_io
    mov edx, [fd_offsets + esi * 4]
    mov dword [fat_alloc_zero_policy], 1
    cmp edx, [writable_sizes + ebx * 4]
    ja .allocation_policy_ready
    mov eax, edx
    and eax, 511
    cmp eax, 0
    jne .allocation_policy_ready
    cmp dword [file_io_remaining], 512
    jb .allocation_policy_ready
    mov dword [fat_alloc_zero_policy], 0

.allocation_policy_ready:
    mov dword [file_write_debug_stage], 5
    mov dword [file_write_fail_stage], 4
    call fat_file_lba_for_write
    mov dword [fat_alloc_zero_policy], 1
    jc .fail_io
    mov [file_io_sector_lba], eax
    mov [file_io_sector_offset], ebx
    mov eax, 512
    sub eax, [file_io_sector_offset]
    cmp eax, [file_io_remaining]
    jbe .chunk_ok
    mov eax, [file_io_remaining]

.chunk_ok:
    mov [file_io_chunk], eax
    cmp dword [file_io_sector_offset], 0
    jne .prepare_partial_sector
    cmp dword [file_io_chunk], 512
    jne .prepare_partial_sector
    mov dword [file_write_debug_stage], 6
    mov eax, [file_io_sector_lba]
    mov esi, [file_io_user_ptr]
    add esi, [file_io_done]
    mov dword [file_write_fail_stage], 5
    call block_selected_write_sector
    jc .fail_io
    jmp .after_sector_write

.prepare_partial_sector:
    cmp dword [fat_file_lba_was_new_cluster], 1
    je .zero_sector_buffer
    mov dword [file_write_debug_stage], 7
    mov eax, [file_io_sector_lba]
    mov edi, SECTOR_BUFFER_ADDR
    mov dword [file_write_fail_stage], 6
    call block_selected_read_sector
    jc .fail_io
    jmp .copy_partial_sector

.zero_sector_buffer:
    mov edi, SECTOR_BUFFER_ADDR
    xor eax, eax
    mov ecx, 512 / 4
    cld
    rep stosd

.copy_partial_sector:
    mov esi, [file_io_user_ptr]
    add esi, [file_io_done]
    mov edi, SECTOR_BUFFER_ADDR
    add edi, [file_io_sector_offset]
    mov ecx, [file_io_chunk]
    cld
    rep movsb
    mov dword [file_write_debug_stage], 8
    mov eax, [file_io_sector_lba]
    mov esi, SECTOR_BUFFER_ADDR
    mov dword [file_write_fail_stage], 7
    call block_selected_write_sector
    jc .fail_io

.after_sector_write:
    mov dword [file_write_fail_stage], 0
    mov eax, [file_io_chunk]
    add [file_io_done], eax
    sub [file_io_remaining], eax
    mov esi, [file_io_fd_slot]
    add [fd_offsets + esi * 4], eax
    mov edx, [fd_offsets + esi * 4]
    mov ebx, [file_io_index]
    cmp edx, [writable_sizes + ebx * 4]
    jbe .loop
    mov [writable_sizes + ebx * 4], edx
    jmp .loop

.ok:
    mov dword [file_write_debug_stage], 9
    cmp dword [file_write_requested], 0
    je .update_size
    cmp dword [file_io_done], 0
    jne .update_size
    mov dword [file_write_fail_stage], 3

.update_size:
    mov eax, [file_io_index]
    call fat_clip_writable_chain_to_size
    jc .fail_io_no_progress
    mov eax, [file_io_index]
    cmp dword [file_write_fail_stage], 3
    je .skip_update_stage
    mov dword [file_write_fail_stage], 8

.skip_update_stage:
    call fat_update_writable_size
    jc .fail_io
    cmp dword [file_write_fail_stage], 3
    je .return_done
    mov dword [file_write_fail_stage], 0

.return_done:
    mov eax, [file_io_done]
    mov dword [file_write_debug_stage], 0x0a
    mov [file_write_debug_result], eax
    clc
    ret

.fail_badfd:
    mov dword [file_write_fail_stage], 1
    mov eax, -ERRNO_EBADF
    mov dword [file_write_debug_stage], 0xe1
    mov [file_write_debug_result], eax
    stc
    ret

.fail_inval_range:
    mov dword [file_write_fail_stage], 2

.fail_inval:
    mov eax, -ERRNO_EINVAL
    mov dword [file_write_debug_stage], 0xe2
    mov [file_write_debug_result], eax
    stc
    ret

.fail_nospc:
    mov dword [file_write_fail_stage], 0x0c
    mov eax, -ERRNO_ENOSPC
    mov dword [file_write_debug_stage], 0xe3
    mov [file_write_debug_result], eax
    stc
    ret

.fail_io:
    cmp dword [file_io_done], 0
    jne .partial_after_io_error

.fail_io_no_progress:
    call fat_rollback_file_write_no_progress
    mov eax, -ERRNO_EIO
    mov [file_write_debug_result], eax
    stc
    ret

.partial_after_io_error:
    mov eax, [file_io_index]
    call fat_clip_writable_chain_to_size
    jc .fail_io_no_progress
    mov eax, [file_io_index]
    call fat_update_writable_size
    jc .fail_io_no_progress
    mov eax, [file_io_done]
    mov dword [file_write_debug_stage], 0x0b
    mov [file_write_debug_result], eax
    clc
    ret

user_file_lseek:
    call writable_fd_index
    jc .fail_badfd
    mov ebx, [file_io_index]
    mov esi, [file_io_fd_slot]
    cmp edx, 0
    je .seek_set
    cmp edx, 1
    je .seek_cur
    cmp edx, 2
    je .seek_end
    jmp .fail_inval

.seek_set:
    mov eax, ecx
    test eax, 0x80000000
    jnz .fail_inval
    jmp .seek_validate

.seek_cur:
    mov eax, [fd_offsets + esi * 4]
    add eax, ecx
    jo .fail_inval
    test eax, 0x80000000
    jnz .fail_inval
    jmp .seek_validate

.seek_end:
    mov eax, [writable_sizes + ebx * 4]
    add eax, ecx
    jo .fail_inval
    test eax, 0x80000000
    jnz .fail_inval

.seek_validate:
    cmp eax, [writable_capacity_table + ebx * 4]
    ja .fail_inval
    mov [fd_offsets + esi * 4], eax
    clc
    ret

.fail_badfd:
    mov eax, -ERRNO_EBADF
    stc
    ret

.fail_inval:
    mov eax, -ERRNO_EINVAL
    stc
    ret

readonly_file_read:
    call readonly_fd_index
    jc .fail_badfd
    mov esi, [file_io_fd_slot]
    mov eax, [fd_offsets + esi * 4]
    mov [file_io_start_offset], eax
    mov [file_io_user_ptr], ecx
    mov [file_io_remaining], edx
    mov dword [file_io_done], 0
    mov eax, ecx
    mov ebx, edx
    call user_range_validate
    jc .fail_inval
    mov eax, [fd_file_sizes + esi * 4]
    cmp [fd_offsets + esi * 4], eax
    jb .have_readable_bytes
    mov dword [file_io_remaining], 0
    jmp .loop

.have_readable_bytes:
    sub eax, [fd_offsets + esi * 4]
    cmp [file_io_remaining], eax
    jbe .loop
    mov [file_io_remaining], eax

.loop:
    cmp dword [file_io_remaining], 0
    je .ok
    mov esi, [file_io_fd_slot]
    mov edx, [fd_offsets + esi * 4]
    mov ax, [fd_indices + esi * 4]
    call fat_file_lba_for_offset
    jc .fail_io
    mov [file_io_sector_offset], ebx
    mov edi, SECTOR_BUFFER_ADDR
    call block_selected_read_sector
    jc .fail_io
    mov eax, 512
    sub eax, [file_io_sector_offset]
    cmp eax, [file_io_remaining]
    jbe .chunk_ok
    mov eax, [file_io_remaining]

.chunk_ok:
    mov [file_io_chunk], eax
    mov esi, SECTOR_BUFFER_ADDR
    add esi, [file_io_sector_offset]
    mov edi, [file_io_user_ptr]
    add edi, [file_io_done]
    mov ecx, [file_io_chunk]
    cld
    rep movsb
    mov eax, [file_io_chunk]
    add [file_io_done], eax
    sub [file_io_remaining], eax
    mov esi, [file_io_fd_slot]
    add [fd_offsets + esi * 4], eax
    jmp .loop

.ok:
    cmp dword [file_io_done], 0
    je .return_done
    mov eax, user_io_read_count
    call user_io_increment_current
    cmp dword [file_io_start_offset], 0
    jne .readonly_maybe_primary_asset
    cmp dword [file_io_done], 4
    jb .readonly_maybe_primary_asset
    mov edi, [file_io_user_ptr]
    mov edx, [edi]
    cmp edx, 0x4b434150
    jne .readonly_maybe_primary_asset
    cmp dword [payload_secondary_package_magic_seen], 0
    jne .readonly_maybe_primary_asset
    mov [payload_secondary_package_magic_seen], edx

.readonly_maybe_primary_asset:
    call readonly_fd_is_primary_asset_file
    jc .return_done
    cmp dword [file_io_start_offset], 0
    jne .return_done
    cmp dword [file_io_done], 4
    jb .return_done
    mov edi, [file_io_user_ptr]
    mov edx, [edi]
    mov [user_primary_asset_magic_seen], edx
    cmp dword [payload_primary_asset_magic_seen], 0
    jne .return_done
    mov [payload_primary_asset_magic_seen], edx

.return_done:
    mov eax, [file_io_done]
    clc
    ret

.fail_badfd:
    mov eax, -ERRNO_EBADF
    stc
    ret

.fail_inval:
    mov eax, -ERRNO_EINVAL
    stc
    ret

.fail_io:
    mov eax, -ERRNO_EIO
    stc
    ret

readonly_file_lseek:
    call readonly_fd_index
    jc .fail_badfd
    mov esi, [file_io_fd_slot]
    cmp edx, 0
    je .seek_set
    cmp edx, 1
    je .seek_cur
    cmp edx, 2
    je .seek_end
    jmp .fail_inval

.seek_set:
    mov eax, ecx
    test eax, 0x80000000
    jnz .fail_inval
    jmp .seek_validate

.seek_cur:
    mov eax, [fd_offsets + esi * 4]
    add eax, ecx
    jo .fail_inval
    test eax, 0x80000000
    jnz .fail_inval
    jmp .seek_validate

.seek_end:
    mov eax, [fd_file_sizes + esi * 4]
    add eax, ecx
    jo .fail_inval
    test eax, 0x80000000
    jnz .fail_inval

.seek_validate:
    cmp eax, [fd_file_sizes + esi * 4]
    ja .fail_inval
    mov [fd_offsets + esi * 4], eax
    push eax
    mov eax, user_io_lseek_count
    call user_io_increment_current
    pop eax

.seek_ok:
    clc
    ret

.fail_badfd:
    mov eax, -ERRNO_EBADF
    stc
    ret

.fail_inval:
    mov eax, -ERRNO_EINVAL
    stc
    ret

primary_package_validate_range:
    push edx

    mov edx, eax
    add edx, ebx
    jc .fail
    cmp edx, [primary_asset_size]
    ja .fail
    clc
    jmp .done

.fail:
    stc

.done:
    pop edx
    ret

primary_package_find_member:
    push ecx
    push edx
    push esi
    push edi

    mov esi, PRIMARY_ASSET_LOAD_ADDR
    add esi, [primary_package_directory_offset]
    mov ecx, [primary_package_member_count]

.entry_loop:
    cmp ecx, 0
    je .fail
    push ecx
    push esi
    lea esi, [esi + 8]
    mov edi, edx
    mov ecx, 8
    repe cmpsb
    sete al
    pop esi
    pop ecx
    cmp al, 1
    je .found
    add esi, 16
    dec ecx
    jmp .entry_loop

.found:
    mov eax, [esi]
    mov ebx, [esi + 4]
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    ret

primary_package_parse:
    cmp dword [PRIMARY_ASSET_LOAD_ADDR], 0x44415749
    je .header_ok
    cmp dword [PRIMARY_ASSET_LOAD_ADDR], 0x44415750
    jne .fail

.header_ok:
    mov eax, [PRIMARY_ASSET_LOAD_ADDR + 4]
    cmp eax, 0
    je .fail
    cmp eax, 4096
    ja .fail
    mov [primary_package_member_count], eax

    mov ebx, [PRIMARY_ASSET_LOAD_ADDR + 8]
    mov [primary_package_directory_offset], ebx
    mov edx, eax
    shl edx, 4
    add edx, ebx
    jc .fail
    cmp edx, [primary_asset_size]
    ja .fail

    mov edx, primary_palette_member_name
    call primary_package_find_member
    jc .fail
    call primary_package_validate_range
    jc .fail
    mov [primary_palette_offset], eax
    mov [primary_palette_size], ebx

    mov edx, primary_colormap_member_name
    call primary_package_find_member
    jc .fail
    call primary_package_validate_range
    jc .fail
    mov [primary_colormap_offset], eax
    mov [primary_colormap_size], ebx

    mov byte [primary_package_parse_status], 1
    clc
    ret

.fail:
    mov byte [primary_package_parse_status], 2
    stc
    ret

