.master_irqs:
    call idt_set_gate
    loop .master_irqs

    mov eax, irq_audio
    call idt_set_gate

    mov eax, irq_ignore_master
    mov ecx, 2

.master_irqs_after_audio:
    call idt_set_gate
    loop .master_irqs_after_audio

    mov eax, irq_ignore_slave
    mov ecx, 8

.slave_irqs:
    call idt_set_gate
    loop .slave_irqs

    mov edi, idt_start + (44 * 8)
    mov eax, irq_mouse
    call idt_set_gate

    mov edi, idt_start + (46 * 8)
    mov eax, irq_ide_primary
    call idt_set_gate

    mov edi, idt_start + (48 * 8)
    mov eax, exception_halt
    mov ecx, 208

.remaining:
    call idt_set_gate
    loop .remaining

    mov edi, idt_start + (LAPIC_SPURIOUS_VECTOR * 8)
    mov eax, irq_lapic_spurious
    call idt_set_gate

    mov edi, idt_start + (0x80 * 8)
    mov eax, syscall_handler
    mov bl, IDT_TRAP_GATE_RING3
    call idt_set_gate_attr
    mov byte [cpu_idt_exception_attr], IDT_INTERRUPT_GATE_RING0
    mov byte [cpu_idt_breakpoint_attr], IDT_TRAP_GATE_RING3
    mov byte [cpu_idt_irq_attr], IDT_INTERRUPT_GATE_RING0
    mov byte [cpu_idt_syscall_attr], IDT_TRAP_GATE_RING3
    mov byte [cpu_idt_status], CPU_TABLE_STATUS_READY

    popad
    ret

idt_set_gate:
    push ebx
    mov bl, IDT_INTERRUPT_GATE_RING0
    call idt_set_gate_attr
    pop ebx
    ret

idt_set_gate_attr:
    push eax
    push edx

    add eax, [idt_gate_offset_bias]
    mov edx, eax
    mov [edi], dx
    mov word [edi + 2], CODE_SEG
    mov byte [edi + 4], 0
    mov byte [edi + 5], bl
    shr edx, 16
    mov [edi + 6], dx
    add edi, 8

    pop edx
    pop eax
    ret

