process_reset_user_probe:
    call process_reset_user_exec_target
    ret

process_reset_user_exec_target:
    call process_reset_accounting
    mov dword [esi + PROC_STATE], PROC_STATE_READY
    mov dword [esi + PROC_BRK], USER_HEAP_START
    mov dword [esi + PROC_ENTRY], 0
    ret

process_reset_preempt_probe:
    call process_reset_user_exec_target
    ret

process_seed_wait_reap_probe_child:
    push eax
    push esi
    mov esi, process_preempt_probe
    call process_reset_preempt_probe
    mov eax, [current_pid]
    mov [esi + PROC_PARENT_PID], eax
    mov dword [esi + PROC_EXIT_STATUS], WAIT_PROOF_EXIT_STATUS
    mov dword [esi + PROC_STATE], PROC_STATE_EXITED
    mov eax, [esi + PROC_PID]
    mov [process_wait_seeded_child_pid], eax
    inc dword [process_wait_seeded_children]
    pop esi
    pop eax
    ret

process_reset_payload:
    call process_reset_accounting
    mov dword [esi + PROC_KIND], USER_KIND_GENERIC
    mov dword [esi + PROC_STATE], PROC_STATE_READY
    mov dword [esi + PROC_BRK], PAYLOAD_USER_HEAP_START
    mov dword [esi + PROC_ENTRY], 0
    ret

process_reset_generic_unused:
    call process_reset_user_exec_target
    mov dword [esi + PROC_STATE], PROC_STATE_UNUSED
    ret

process_reset_accounting:
    push eax
    push ecx
    push edi
    call process_heap_clear_all
    mov dword [esi + PROC_TICKS], 0
    mov dword [esi + PROC_RUNS], 0
    mov dword [esi + PROC_QUANTUM_TICKS], 0
    mov dword [esi + PROC_SWITCHES], 0
    and dword [esi + PROC_VM_FLAGS], ~PROC_FLAGS_TRANSIENT_MASK
    mov dword [esi + PROC_PARENT_PID], 0xffffffff
    mov dword [esi + PROC_EXIT_STATUS], 0
    mov dword [esi + PROC_EXEC_COUNT], 0
    mov dword [esi + PROC_ARGC], 0
    mov dword [esi + PROC_ARGV], 0
    mov dword [esi + PROC_ENVP], 0
    mov dword [esi + PROC_ARGV0], 0
    lea edi, [esi + PROC_SAVED_EAX]
    xor eax, eax
    mov ecx, 16
    rep stosd
    mov dword [esi + PROC_LINUX_TLS_BASE], 0
    pop edi
    pop ecx
    pop eax
    ret

process_write_wait_status_for_parent:
    push eax
    push ebx
    push ecx
    push edx

    cmp edi, 0
    je .done
    cmp ecx, 0
    je .done
    cmp dword [edi + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .status_ready
    mov eax, ebx
    and eax, 0xff
    shl eax, 8
    mov ebx, eax

.status_ready:
    mov eax, cr3
    push eax
    mov eax, [edi + PROC_PAGE_DIR]
    test eax, eax
    jz .restore_cr3
    mov cr3, eax
    mov [ecx], ebx

.restore_cr3:
    pop eax
    mov cr3, eax

.done:
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

process_heap_clear_all:
    push eax
    push ecx
    push edi
    mov edi, [esi + PROC_HEAP_BITMAP]
    test edi, edi
    jz .done
    mov ecx, [esi + PROC_HEAP_PAGE_COUNT]
    add ecx, 7
    shr ecx, 3
    test ecx, ecx
    jz .done
    xor eax, eax
    cld
    rep stosb

.done:
    pop edi
    pop ecx
    pop eax
    ret

process_heap_mark_range:
    pushad
    cmp esi, 0
    je .done
    mov edi, [esi + PROC_HEAP_BITMAP]
    test edi, edi
    jz .done
    mov ebx, eax
    cmp ebx, [esi + PROC_HEAP_START]
    jae .base_ready
    mov ebx, [esi + PROC_HEAP_START]

.base_ready:
    mov ecx, edx
    cmp ecx, [esi + PROC_HEAP_END]
    jbe .end_ready
    mov ecx, [esi + PROC_HEAP_END]

.end_ready:
    cmp ebx, ecx
    jae .done
    sub ebx, [esi + PROC_HEAP_START]
    shr ebx, 12
    sub ecx, [esi + PROC_HEAP_START]
    add ecx, PAGE_SIZE - 1
    shr ecx, 12
    cmp ecx, [esi + PROC_HEAP_PAGE_COUNT]
    jbe .count_ready
    mov ecx, [esi + PROC_HEAP_PAGE_COUNT]

.count_ready:
    mov ebp, ecx
    cmp ebx, ebp
    jae .done

.mark_next:
    mov edx, ebx
    shr edx, 3
    mov al, 1
    mov ecx, ebx
    and ecx, 7
    shl al, cl
    or byte [edi + edx], al
    inc ebx
    cmp ebx, ebp
    jb .mark_next

.done:
    popad
    ret

process_heap_clear_range:
    pushad
    cmp esi, 0
    je .done
    mov edi, [esi + PROC_HEAP_BITMAP]
    test edi, edi
    jz .done
    mov ebx, eax
    cmp ebx, [esi + PROC_HEAP_START]
    jae .base_ready
    mov ebx, [esi + PROC_HEAP_START]

.base_ready:
    mov ecx, edx
    cmp ecx, [esi + PROC_HEAP_END]
    jbe .end_ready
    mov ecx, [esi + PROC_HEAP_END]

.end_ready:
    cmp ebx, ecx
    jae .done
    sub ebx, [esi + PROC_HEAP_START]
    shr ebx, 12
    sub ecx, [esi + PROC_HEAP_START]
    add ecx, PAGE_SIZE - 1
    shr ecx, 12
    cmp ecx, [esi + PROC_HEAP_PAGE_COUNT]
    jbe .count_ready
    mov ecx, [esi + PROC_HEAP_PAGE_COUNT]

.count_ready:
    mov ebp, ecx
    cmp ebx, ebp
    jae .done

.clear_next:
    mov edx, ebx
    shr edx, 3
    mov al, 1
    mov ecx, ebx
    and ecx, 7
    shl al, cl
    not al
    and byte [edi + edx], al
    inc ebx
    cmp ebx, ebp
    jb .clear_next

.done:
    popad
    ret

process_heap_range_is_mapped:
    push ebx
    push ecx
    push edx
    push edi
    cmp esi, 0
    je .fail
    mov edi, [esi + PROC_HEAP_BITMAP]
    test edi, edi
    jz .fail
    cmp eax, [esi + PROC_HEAP_START]
    jb .fail
    cmp edx, [esi + PROC_BRK]
    ja .fail
    mov ebx, eax
    sub ebx, [esi + PROC_HEAP_START]
    shr ebx, 12
    mov ecx, edx
    sub ecx, [esi + PROC_HEAP_START]
    add ecx, PAGE_SIZE - 1
    shr ecx, 12
    cmp ecx, [esi + PROC_HEAP_PAGE_COUNT]
    ja .fail
    mov edx, ecx
    cmp ebx, edx
    jae .ok

.check_next:
    mov ecx, ebx
    shr ecx, 3
    mov al, 1
    push ecx
    mov ecx, ebx
    and ecx, 7
    shl al, cl
    pop ecx
    test byte [edi + ecx], al
    jz .fail
    inc ebx
    cmp ebx, edx
    jb .check_next

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop edx
    pop ecx
    pop ebx
    ret

process_free_owned_user_page:
    push eax
    push ebx
    push ecx
    push edx
    push edi

    cmp esi, 0
    je .done
    cmp esi, process_kernel
    je .done
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .done
    call vmm_find_process_pte
    jc .done
    test edx, PTE_PRESENT
    jz .done
    test edx, PTE_USER
    jz .done
    mov ebx, edx
    and ebx, 0xfffff000
    mov ecx, eax
    and ecx, 0xfffff000
    cmp ebx, ecx
    jne .managed_check
    cmp ecx, PAGING_MAPPED_BYTES
    jb .done

.managed_check:
    cmp ebx, PMM_MANAGED_START
    jb .done
    cmp ebx, PMM_MANAGED_END
    jae .done
    mov eax, ebx
    call pmm_free_page
    inc dword [process_vm_owned_pages_freed]

.done:
    pop edi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

process_clear_user_range:
    push eax
    push edx

.next:
    cmp eax, edx
    jae .done
    call process_free_owned_user_page
    call vmm_clear_process_page
    jc .clear_heap_metadata
    inc dword [process_vm_pages_cleared]

.clear_heap_metadata:
    push edx
    mov edx, eax
    add edx, PAGE_SIZE
    call process_heap_clear_range
    pop edx
    add eax, PAGE_SIZE
    jmp .next

.done:
    pop edx
    pop eax
    ret

process_teardown_user_vm:
    pushad
    cmp esi, 0
    je .done
    cmp esi, process_kernel
    je .done
    test dword [esi + PROC_VM_FLAGS], PROC_FLAG_SHARED_VM
    jnz .reset_shared_metadata
    mov eax, [esi + PROC_PID]
    mov [process_last_teardown_pid], eax
    mov eax, [esi + PROC_BASE]
    mov [process_last_teardown_base], eax
    mov eax, [esi + PROC_END]
    mov [process_last_teardown_end], eax
    inc dword [process_vm_teardowns]
    mov ebx, [esi + PROC_PAGE_DIR]
    cmp ebx, 0
    je .reset_metadata
    mov edi, [esi + PROC_VM_REGIONS]
    mov ecx, [esi + PROC_VM_REGION_COUNT]

.region_next:
    cmp ecx, 0
    je .reset_metadata
    test dword [edi + VM_REGION_FLAGS], VM_REGION_USER
    jz .region_advance
    mov eax, [edi + VM_REGION_BASE]
    mov edx, [edi + VM_REGION_END]
    call process_clear_user_range

.region_advance:
    add edi, VM_REGION_BYTES
    dec ecx
    jmp .region_next

.reset_metadata:
    mov eax, [esi + PROC_HEAP_START]
    mov [esi + PROC_BRK], eax
    and dword [esi + PROC_VM_FLAGS], ~PROC_FLAGS_TRANSIENT_MASK
    jmp .done

.reset_shared_metadata:
    call process_restore_own_page_dir
    mov eax, [esi + PROC_HEAP_START]
    mov [esi + PROC_BRK], eax
    and dword [esi + PROC_VM_FLAGS], ~PROC_FLAGS_TRANSIENT_MASK

.done:
    popad
    ret

process_restore_own_page_dir:
    cmp esi, process_user_probe
    je .probe
    cmp esi, process_preempt_probe
    je .preempt
    cmp esi, process_payload
    je .payload
    cmp esi, process_generic0
    je .generic0
    cmp esi, process_generic1
    je .generic1
    cmp esi, process_generic2
    je .generic2
    ret

.probe:
    mov dword [esi + PROC_PAGE_DIR], PROC_PROBE_PAGE_DIR_ADDR
    ret

.preempt:
    mov dword [esi + PROC_PAGE_DIR], PROC_PREEMPT_PAGE_DIR_ADDR
    ret

.payload:
    mov dword [esi + PROC_PAGE_DIR], PROC_PAYLOAD_PAGE_DIR_ADDR
    ret

.generic0:
    mov dword [esi + PROC_PAGE_DIR], PROC_GENERIC0_PAGE_DIR_ADDR
    ret

.generic1:
    mov dword [esi + PROC_PAGE_DIR], PROC_GENERIC1_PAGE_DIR_ADDR
    ret

.generic2:
    mov dword [esi + PROC_PAGE_DIR], PROC_GENERIC2_PAGE_DIR_ADDR
    ret

process_restore_user_stack_vm:
    push eax
    push ebx
    push edx
    cmp esi, 0
    je .done
    cmp esi, process_kernel
    je .done
    mov ebx, [esi + PROC_PAGE_DIR]
    cmp ebx, 0
    je .done
    mov eax, [esi + PROC_STACK_BOTTOM]
    add eax, PAGE_SIZE
    mov edx, [esi + PROC_STACK_TOP]
    call vmm_mark_process_user_write_range

.done:
    pop edx
    pop ebx
    pop eax
    ret

process_restore_user_image_vm:
    push eax
    push ebx
    push edx
    cmp esi, 0
    je .done
    cmp esi, process_kernel
    je .done
    mov ebx, [esi + PROC_PAGE_DIR]
    cmp ebx, 0
    je .done
    mov eax, [esi + PROC_BASE]
    mov edx, [esi + PROC_HEAP_START]
    call vmm_mark_process_user_range

.done:
    pop edx
    pop ebx
    pop eax
    ret

process_reuse_exec_target_slot:
    push eax
    cmp esi, 0
    je .done
    cmp esi, process_kernel
    je .done
    call fd_close_owned_by_process
    call process_teardown_user_vm
    call process_restore_user_image_vm
    call process_restore_user_stack_vm
    inc dword [process_slot_reuses]
    mov [process_last_reused_slot], esi
    mov eax, [process_next_pid]
    mov [esi + PROC_PID], eax
    mov [process_last_reused_pid], eax
    inc eax
    cmp eax, 0
    jne .pid_ready
    mov eax, 4

.pid_ready:
    mov [process_next_pid], eax
    mov dword [esi + PROC_PARENT_PID], 0xffffffff
    mov dword [esi + PROC_EXIT_STATUS], 0
    mov dword [esi + PROC_EXEC_COUNT], 0
    mov dword [esi + PROC_ARGC], 0
    mov dword [esi + PROC_ARGV], 0
    mov dword [esi + PROC_ENVP], 0
    mov dword [esi + PROC_ARGV0], 0
    call process_fpu_reset_context
    inc dword [esi + PROC_SLOT_GENERATION]
    mov eax, [esi + PROC_SLOT_GENERATION]
    mov [process_last_slot_generation], eax
    mov dword [esi + PROC_STATE], PROC_STATE_UNUSED

.done:
    pop eax
    ret

process_is_user_exec_target:
    cmp eax, process_user_probe
    je .yes
    cmp eax, process_generic0
    je .yes
    cmp eax, process_generic1
    je .yes
    cmp eax, process_generic2
    je .yes
    stc
    ret

.yes:
    clc
    ret

user_kind_is_large_payload:
    cmp eax, USER_KIND_PAYLOAD_PRIMARY
    je .yes
    cmp eax, USER_KIND_PAYLOAD_SECONDARY
    je .yes
    stc
    ret

.yes:
    clc
    ret

payload_kind_to_fault_source:
    cmp eax, USER_KIND_PAYLOAD_PRIMARY
    je .primary_payload
    cmp eax, USER_KIND_PAYLOAD_SECONDARY
    je .secondary_payload
    mov eax, FAULT_SOURCE_USER
    ret

.primary_payload:
    mov eax, FAULT_SOURCE_PAYLOAD_PRIMARY
    ret

.secondary_payload:
    mov eax, FAULT_SOURCE_PAYLOAD_SECONDARY
    ret

process_alloc_generic_exec_slot:
    push eax
    push ecx
    push edi
    mov edi, process_generic_exec_slots
    mov ecx, PROCESS_GENERIC_SLOT_COUNT

.scan_next:
    cmp ecx, 0
    je .none
    mov esi, [edi]
    cmp dword [esi + PROC_STATE], PROC_STATE_UNUSED
    je .found
    cmp dword [esi + PROC_PARENT_PID], 0xffffffff
    jne .advance
    cmp dword [esi + PROC_STATE], PROC_STATE_EXITED
    je .found
    cmp dword [esi + PROC_STATE], PROC_STATE_FAULTED
    je .found

.advance:
    add edi, 4
    dec ecx
    jmp .scan_next

.found:
    mov [process_last_generic_slot], esi
    inc dword [process_generic_slot_allocations]
    clc
    jmp .done

.none:
    inc dword [process_generic_slot_failures]
    mov dword [process_exec_last_error], -ERRNO_ENOMEM
    stc

.done:
    pop edi
    pop ecx
    pop eax
    ret

process_retire_exec_slot:
    cmp esi, 0
    je .done
    cmp esi, process_kernel
    je .done
    call fd_close_owned_by_process
    call process_teardown_user_vm
    inc dword [process_exec_teardowns]
    mov dword [esi + PROC_STATE], PROC_STATE_EXITED
    and dword [esi + PROC_VM_FLAGS], ~PROC_FLAGS_TRANSIENT_MASK

.done:
    ret

process_retire_current_exit_slot:
    cmp esi, 0
    je .done
    cmp esi, process_kernel
    je .done
    call fd_close_owned_by_process
    call process_teardown_user_vm
    inc dword [process_exit_teardowns]
    mov dword [esi + PROC_STATE], PROC_STATE_EXITED
    and dword [esi + PROC_VM_FLAGS], ~PROC_FLAGS_TRANSIENT_MASK

.done:
    ret

process_mark_current_zombie_exited:
    push esi
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .done
    cmp esi, process_kernel
    je .done
    call fd_close_owned_by_process
    mov [esi + PROC_EXIT_STATUS], ebx
    mov dword [esi + PROC_STATE], PROC_STATE_EXITED
    and dword [esi + PROC_VM_FLAGS], 0xfffffffe
    inc dword [process_exit_zombies]

.done:
    pop esi
    ret

process_restore_syscall_context:
    push ebx
    push edx
    push edi

    mov edi, ebx
    mov edx, [esi + PROC_SAVED_EBP]
    mov [edi + SYSCALL_FRAME_EBP], edx
    mov edx, [esi + PROC_SAVED_EDI]
    mov [edi + SYSCALL_FRAME_EDI], edx
    mov edx, [esi + PROC_SAVED_ESI]
    mov [edi + SYSCALL_FRAME_ESI], edx
    mov edx, [esi + PROC_SAVED_EDX]
    mov [edi + SYSCALL_FRAME_EDX], edx
    mov edx, [esi + PROC_SAVED_ECX]
    mov [edi + SYSCALL_FRAME_ECX], edx
    mov edx, [esi + PROC_SAVED_EBX]
    mov [edi + SYSCALL_FRAME_EBX], edx
    mov edx, [esi + PROC_SAVED_EIP]
    mov [edi + SYSCALL_FRAME_EIP], edx
    mov edx, [esi + PROC_SAVED_CS]
    mov [edi + SYSCALL_FRAME_CS], edx
    mov edx, [esi + PROC_SAVED_EFLAGS]
    mov [edi + SYSCALL_FRAME_EFLAGS], edx
    mov edx, [esi + PROC_SAVED_ESP]
    mov [edi + SYSCALL_FRAME_ESP], edx
    mov edx, [esi + PROC_SAVED_SS]
    mov [edi + SYSCALL_FRAME_SS], edx
    mov eax, [esi + PROC_SAVED_EAX]

    pop edi
    pop edx
    pop ebx
    ret

process_exit_resume_parent:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov esi, [current_process_ptr]
    cmp esi, 0
    je .fail
    mov [process_exit_child_ptr], esi
    mov edx, [esi + PROC_PARENT_PID]
    mov [process_exit_parent_pid], edx
    cmp edx, 0xffffffff
    je .fail
    mov edi, process_table
    mov ecx, PROCESS_SLOT_COUNT
    xor ebx, ebx

.scan_next:
    cmp ecx, 0
    je .fail
    cmp edi, esi
    je .advance
    cmp [edi + PROC_PID], edx
    jne .advance
    cmp dword [edi + PROC_STATE], PROC_STATE_READY
    je .found
    cmp dword [edi + PROC_STATE], PROC_STATE_RUNNING
    je .found
    cmp dword [edi + PROC_STATE], PROC_STATE_BLOCKED
    je .check_blocked_parent
    jmp .fail

.advance:
    add edi, PROCESS_RECORD_BYTES
    inc ebx
    dec ecx
    jmp .scan_next

.check_blocked_parent:
    mov eax, [scheduler_sleep_reasons + ebx * 4]
    cmp eax, PROC_BLOCK_WAITPID
    jne .fail
    mov eax, [scheduler_block_objects + ebx * 4]
    cmp eax, 0xffffffff
    je .found_waitpid_block
    mov esi, [process_exit_child_ptr]
    cmp eax, [esi + PROC_PID]
    jne .fail

.found_waitpid_block:
    mov esi, [process_exit_child_ptr]
    mov eax, [esi + PROC_PID]
    mov [process_wait_last_reaped_pid], eax
    mov [edi + PROC_SAVED_EAX], eax
    mov eax, [scheduler_sleep_reasons + ebx * 4]
    mov [scheduler_block_last_wake_reason], eax
    mov edx, [edi + PROC_PID]
    mov [scheduler_block_last_woken_pid], edx
    mov edx, [scheduler_block_status_ptrs + ebx * 4]
    mov ebx, [esi + PROC_EXIT_STATUS]
    mov [process_wait_last_status], ebx
    mov ecx, edx
    call process_write_wait_status_for_parent
    inc dword [process_wait_reaps]
    inc dword [process_wait_block_wakeups]
    inc dword [scheduler_block_wakeups]
    mov dword [edi + PROC_STATE], PROC_STATE_READY
    mov ebx, edi
    sub ebx, process_table
    xor edx, edx
    mov eax, ebx
    mov ebx, PROCESS_RECORD_BYTES
    div ebx
    mov dword [scheduler_sleep_reasons + eax * 4], PROC_BLOCK_NONE
    mov dword [scheduler_sleep_wake_ticks + eax * 4], 0
    mov dword [scheduler_block_objects + eax * 4], 0
    mov dword [scheduler_block_status_ptrs + eax * 4], 0
    mov eax, [process_vm_pages_cleared]
    mov [process_wait_vm_pages_before], eax
    mov esi, [process_exit_child_ptr]
    call process_teardown_user_vm
    mov eax, [process_vm_pages_cleared]
    sub eax, [process_wait_vm_pages_before]
    mov [process_wait_last_vm_pages_reclaimed], eax
    add [process_wait_vm_pages_reclaimed], eax
    inc dword [process_wait_vm_reaps]
    mov dword [esi + PROC_STATE], PROC_STATE_UNUSED
    mov dword [esi + PROC_PARENT_PID], 0xffffffff
    and dword [esi + PROC_VM_FLAGS], ~PROC_FLAGS_TRANSIENT_MASK
    mov esi, edi
    call process_activate
    mov eax, [esi + PROC_PID]
    mov [process_exit_resumed_pid], eax
    mov ebx, [process_exit_frame_ptr]
    call process_restore_syscall_context
    clc
    jmp .done

.found:
    mov esi, edi
    call process_activate
    mov eax, [esi + PROC_PID]
    mov [process_exit_resumed_pid], eax
    mov ebx, [process_exit_frame_ptr]
    call process_restore_syscall_context
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

process_alloc_fork_child_slot:
    push eax
    push ecx
    push edi

    mov edi, process_generic_exec_slots
    mov ecx, PROCESS_GENERIC_SLOT_COUNT

.scan_next:
    cmp ecx, 0
    je .none
    mov esi, [edi]
    cmp esi, [current_process_ptr]
    je .advance
    cmp dword [esi + PROC_STATE], PROC_STATE_UNUSED
    je .found

.advance:
    add edi, 4
    dec ecx
    jmp .scan_next

.found:
    mov [process_fork_child_proc], esi
    inc dword [process_generic_slot_allocations]
    clc
    jmp .done

.none:
    stc

.done:
    pop edi
    pop ecx
    pop eax
    ret

process_fork_copy_metadata:
    push eax
    push ecx
    push esi
    push edi

    mov esi, [process_fork_parent_proc]
    mov edi, [process_fork_child_proc]
    mov eax, [esi + PROC_PID]
    mov [edi + PROC_PARENT_PID], eax
    mov eax, [esi + PROC_BASE]
    mov [edi + PROC_BASE], eax
    mov eax, [esi + PROC_END]
    mov [edi + PROC_END], eax
    mov eax, [esi + PROC_BRK]
    mov [edi + PROC_BRK], eax
    mov eax, [esi + PROC_HEAP_START]
    mov [edi + PROC_HEAP_START], eax
    mov eax, [esi + PROC_HEAP_END]
    mov [edi + PROC_HEAP_END], eax
    mov eax, [esi + PROC_STACK_BOTTOM]
    mov [edi + PROC_STACK_BOTTOM], eax
    mov eax, [esi + PROC_STACK_TOP]
    mov [edi + PROC_STACK_TOP], eax
    mov eax, [esi + PROC_ENTRY]
    mov [edi + PROC_ENTRY], eax
    mov eax, [esi + PROC_VM_REGIONS]
    mov [edi + PROC_VM_REGIONS], eax
    mov eax, [esi + PROC_VM_REGION_COUNT]
    mov [edi + PROC_VM_REGION_COUNT], eax
    mov eax, [esi + PROC_EXEC_COUNT]
    mov [edi + PROC_EXEC_COUNT], eax
    mov eax, [esi + PROC_ARGC]
    mov [edi + PROC_ARGC], eax
    mov eax, [esi + PROC_ARGV]
    mov [edi + PROC_ARGV], eax
    mov eax, [esi + PROC_ENVP]
    mov [edi + PROC_ENVP], eax
    mov eax, [esi + PROC_ARGV0]
    mov [edi + PROC_ARGV0], eax
    mov eax, [esi + PROC_PERSONALITY]
    mov [edi + PROC_PERSONALITY], eax
    mov eax, [esi + PROC_LINUX_TLS_BASE]
    mov [edi + PROC_LINUX_TLS_BASE], eax
    mov eax, [esi + PROC_LINUX_SET_TID_ADDR]
    mov [edi + PROC_LINUX_SET_TID_ADDR], eax
    mov eax, [esi + PROC_LINUX_ROBUST_LIST_HEAD]
    mov [edi + PROC_LINUX_ROBUST_LIST_HEAD], eax
    mov eax, [esi + PROC_LINUX_ROBUST_LIST_LEN]
    mov [edi + PROC_LINUX_ROBUST_LIST_LEN], eax
    mov eax, [esi + PROC_LINUX_SIGMASK_LO]
    mov [edi + PROC_LINUX_SIGMASK_LO], eax
    mov eax, [esi + PROC_LINUX_SIGMASK_HI]
    mov [edi + PROC_LINUX_SIGMASK_HI], eax
    mov eax, [esi + PROC_LINUX_SIGALTSTACK_SP]
    mov [edi + PROC_LINUX_SIGALTSTACK_SP], eax
    mov eax, [esi + PROC_LINUX_SIGALTSTACK_FLAGS]
    mov [edi + PROC_LINUX_SIGALTSTACK_FLAGS], eax
    mov eax, [esi + PROC_LINUX_SIGALTSTACK_SIZE]
    mov [edi + PROC_LINUX_SIGALTSTACK_SIZE], eax
    mov eax, [esi + PROC_LINUX_SIGACTION_SIGNUM]
    mov [edi + PROC_LINUX_SIGACTION_SIGNUM], eax
    mov eax, [esi + PROC_LINUX_SIGACTION_HANDLER]
    mov [edi + PROC_LINUX_SIGACTION_HANDLER], eax
    mov eax, [esi + PROC_LINUX_SIGACTION_FLAGS]
    mov [edi + PROC_LINUX_SIGACTION_FLAGS], eax
    mov eax, [esi + PROC_LINUX_SIGACTION_RESTORER]
    mov [edi + PROC_LINUX_SIGACTION_RESTORER], eax
    mov eax, [esi + PROC_LINUX_SIGACTION_MASK_LO]
    mov [edi + PROC_LINUX_SIGACTION_MASK_LO], eax
    mov eax, [esi + PROC_LINUX_SIGACTION_MASK_HI]
    mov [edi + PROC_LINUX_SIGACTION_MASK_HI], eax
    mov dword [edi + PROC_EXIT_STATUS], 0
    push esi
    push edi
    mov esi, [esi + PROC_HEAP_BITMAP]
    mov edi, [edi + PROC_HEAP_BITMAP]
    mov ecx, USER_HEAP_BITMAP_BYTES
    cld
    rep movsb
    pop edi
    pop esi

    pop edi
    pop esi
    pop ecx
    pop eax
    ret

process_clone_user_vm:
    pushad

    mov eax, cr3
    mov [process_fork_saved_cr3], eax
    mov eax, PAGING_DIR_ADDR
    mov cr3, eax
    mov dword [process_fork_pages_copied_last], 0
    mov dword [process_fork_parent_phys], 0
    mov dword [process_fork_copy_phys], 0
    call pmm_refresh_frame_counters
    mov esi, [process_fork_parent_proc]
    mov edi, [process_fork_child_proc]
    cmp esi, 0
    je .fail
    cmp edi, 0
    je .fail
    mov eax, [esi + PROC_PAGE_DIR]
    test eax, eax
    jz .fail
    mov [process_fork_parent_page_dir], eax
    mov eax, [edi + PROC_PAGE_DIR]
    test eax, eax
    jz .fail
    mov [process_fork_child_page_dir], eax
    mov eax, [esi + PROC_VM_REGIONS]
    mov [process_fork_region_ptr], eax
    mov eax, [esi + PROC_VM_REGION_COUNT]
    mov [process_fork_regions_left], eax

.region_next:
    cmp dword [process_fork_regions_left], 0
    je .large_elf_range
    mov edi, [process_fork_region_ptr]
    test dword [edi + VM_REGION_FLAGS], VM_REGION_USER
    jz .region_advance
    mov eax, [edi + VM_REGION_BASE]
    mov [process_fork_copy_vaddr], eax
    mov eax, [edi + VM_REGION_END]
    mov [process_fork_copy_end], eax
    call process_clone_present_user_range
    jc .fail

.region_advance:
    add dword [process_fork_region_ptr], VM_REGION_BYTES
    dec dword [process_fork_regions_left]
    jmp .region_next

.large_elf_range:
    mov esi, [process_fork_parent_proc]
    cmp esi, 0
    je .success
    cmp dword [esi + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .success
    cmp dword [large_elf_status], LARGE_ELF_STATUS_SPARSE_MAPPED
    jne .success
    mov eax, [large_elf_biased_low]
    and eax, 0xfffff000
    mov [process_fork_copy_vaddr], eax
    mov eax, [large_elf_biased_high]
    add eax, PAGE_SIZE - 1
    jc .fail
    and eax, 0xfffff000
    mov [process_fork_copy_end], eax
    mov eax, [process_fork_copy_vaddr]
    cmp eax, [process_fork_copy_end]
    jae .success
    call process_clone_present_user_range
    jc .fail

.success:
    clc
    jmp .done

.fail:
    stc

.done:
    mov eax, [process_fork_saved_cr3]
    mov cr3, eax
    popad
    ret

process_clone_present_user_range:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

.page_next:
    mov eax, [process_fork_copy_vaddr]
    cmp eax, [process_fork_copy_end]
    jae .success
    mov ebx, [process_fork_parent_page_dir]
    call vmm_find_process_pte
    jc .page_advance
    test edx, PTE_PRESENT
    jz .page_advance
    test edx, PTE_USER
    jz .page_advance
    mov eax, edx
    and eax, 0xfffff000
    mov [process_fork_parent_phys], eax
    mov eax, edx
    and eax, 0x00000fff
    mov [process_fork_copy_flags], eax
    call pmm_alloc_page
    test eax, eax
    jnz .copy_page_ready
    jmp .fail

.copy_page_ready:
    mov [process_fork_copy_phys], eax
    pushfd
    cli
    mov eax, FORK_COPY_SRC_ALIAS
    mov ebx, [process_fork_parent_phys]
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .copy_alias_fail
    mov eax, FORK_COPY_DST_ALIAS
    mov ebx, [process_fork_copy_phys]
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .copy_dst_alias_fail
    mov esi, FORK_COPY_SRC_ALIAS
    mov edi, FORK_COPY_DST_ALIAS
    mov ecx, PAGE_SIZE / 4
    cld
    rep movsd
    mov eax, FORK_COPY_DST_ALIAS
    call vmm_unmap_page
    mov eax, FORK_COPY_SRC_ALIAS
    call vmm_unmap_page
    popfd
    mov ecx, [process_fork_copy_phys]
    and ecx, 0xfffff000
    mov eax, [process_fork_copy_flags]
    and eax, 0x00000fff
    or ecx, eax
    or ecx, PTE_PRESENT
    mov eax, [process_fork_copy_vaddr]
    mov ebx, [process_fork_child_page_dir]
    call vmm_write_process_pte
    jnc .child_pte_ready
    mov eax, [process_fork_copy_phys]
    call pmm_free_page
    jmp .fail

.copy_dst_alias_fail:
    mov eax, FORK_COPY_SRC_ALIAS
    call vmm_unmap_page

.copy_alias_fail:
    popfd
    mov eax, [process_fork_copy_phys]
    call pmm_free_page
    jmp .fail

.child_pte_ready:
    inc dword [process_fork_pages_copied_last]

.page_advance:
    add dword [process_fork_copy_vaddr], PAGE_SIZE
    jmp .page_next

.success:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

process_fork_seed_child_context:
    push eax
    push ebx
    push esi
    push edi

    mov esi, [process_fork_child_proc]
    mov edi, [process_fork_frame_ptr]
    mov dword [esi + PROC_SAVED_EAX], 0
    mov eax, [edi + SYSCALL_FRAME_EBX]
    mov [esi + PROC_SAVED_EBX], eax
    mov eax, [edi + SYSCALL_FRAME_ECX]
    mov [esi + PROC_SAVED_ECX], eax
    mov eax, [edi + SYSCALL_FRAME_EDX]
    mov [esi + PROC_SAVED_EDX], eax
    mov eax, [edi + SYSCALL_FRAME_ESI]
    mov [esi + PROC_SAVED_ESI], eax
    mov eax, [edi + SYSCALL_FRAME_EDI]
    mov [esi + PROC_SAVED_EDI], eax
    mov eax, [edi + SYSCALL_FRAME_EBP]
    mov [esi + PROC_SAVED_EBP], eax
    mov eax, [edi + SYSCALL_FRAME_ESP]
    mov [esi + PROC_SAVED_ESP], eax
    mov eax, [edi + SYSCALL_FRAME_EIP]
    mov [esi + PROC_SAVED_EIP], eax
    mov eax, [edi + SYSCALL_FRAME_EFLAGS]
    mov [esi + PROC_SAVED_EFLAGS], eax
    mov eax, [edi + SYSCALL_FRAME_CS]
    mov [esi + PROC_SAVED_CS], eax
    mov eax, [edi + SYSCALL_FRAME_SS]
    mov [esi + PROC_SAVED_SS], eax
    mov dword [esi + PROC_SAVED_DS], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_ES], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_FS], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_GS], USER_DATA_SEG
    mov edi, [process_fork_parent_proc]
    cmp edi, 0
    je .segments_ready
    cmp dword [edi + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .segments_ready
    cmp dword [syscall_entry_gs_last], LINUX_TLS_SEG
    jne .segments_ready
    mov dword [esi + PROC_SAVED_GS], LINUX_TLS_SEG

.segments_ready:
    mov dword [esi + PROC_STATE], PROC_STATE_READY
    mov dword [esi + PROC_QUANTUM_TICKS], 0
    or dword [esi + PROC_VM_FLAGS], PROC_FLAG_IRQ_FRAME_VALID
    mov dword [process_fork_child_return], 0

    pop edi
    pop esi
    pop ebx
    pop eax
    ret

process_fork_rollback_child:
    push eax
    push esi

    mov esi, [process_fork_child_proc]
    cmp esi, 0
    je .done
    call fd_close_owned_by_process
    call process_teardown_user_vm
    mov dword [esi + PROC_STATE], PROC_STATE_UNUSED
    mov dword [esi + PROC_PARENT_PID], 0xffffffff
    and dword [esi + PROC_VM_FLAGS], ~PROC_FLAGS_TRANSIENT_MASK

.done:
    pop esi
    pop eax
    ret

process_fork_current:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov dword [process_fork_child_proc], 0
    mov dword [process_fork_child_pid], 0xffffffff
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .enosys
    cmp esi, process_kernel
    je .enosys
    mov eax, [esi + PROC_KIND]
    cmp eax, USER_KIND_PROBE
    je .kind_ok
    cmp eax, USER_KIND_GENERIC
    je .kind_ok
    jmp .enosys

.kind_ok:
    mov [process_fork_parent_proc], esi
    call process_alloc_fork_child_slot
    jc .enomem
    mov esi, [process_fork_child_proc]
    call process_reuse_exec_target_slot
    call process_fork_copy_metadata
    call process_clone_user_vm
    jc .rollback_enomem
    mov esi, [process_fork_parent_proc]
    mov eax, [esi + PROC_PID]
    mov edi, [process_fork_child_proc]
    mov edx, [edi + PROC_PID]
    call fd_fork_clone_owned_by_pid
    jc .rollback_enomem
    call process_fork_seed_child_context
    mov esi, [process_fork_parent_proc]
    mov eax, [esi + PROC_PID]
    mov [process_fork_parent_pid], eax
    mov edi, [process_fork_child_proc]
    mov eax, [edi + PROC_PID]
    mov [process_fork_child_pid], eax
    mov [process_fork_parent_return], eax
    inc dword [process_fork_successes]
    clc
    jmp .done

.rollback_enomem:
    call process_fork_rollback_child

.enomem:
    inc dword [process_fork_failures]
    mov eax, -ERRNO_ENOMEM
    stc
    jmp .done

.enosys:
    inc dword [process_fork_failures]
    mov eax, -ERRNO_ENOSYS
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

process_clone_shared_vm_current:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov dword [process_fork_child_proc], 0
    mov dword [process_fork_child_pid], 0xffffffff
    mov dword [process_fork_pages_copied_last], 0
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .enosys
    cmp esi, process_kernel
    je .enosys
    mov eax, [esi + PROC_KIND]
    cmp eax, USER_KIND_PROBE
    je .kind_ok
    cmp eax, USER_KIND_GENERIC
    je .kind_ok
    jmp .enosys

.kind_ok:
    mov [process_fork_parent_proc], esi
    call process_alloc_fork_child_slot
    jc .enomem
    mov esi, [process_fork_child_proc]
    call process_reuse_exec_target_slot
    call process_fork_copy_metadata
    mov esi, [process_fork_parent_proc]
    mov edi, [process_fork_child_proc]
    mov eax, [esi + PROC_PAGE_DIR]
    mov [edi + PROC_PAGE_DIR], eax
    or dword [edi + PROC_VM_FLAGS], PROC_FLAG_SHARED_VM
    mov eax, [esi + PROC_PID]
    mov edx, [edi + PROC_PID]
    call fd_fork_clone_owned_by_pid
    jc .rollback_enomem
    call process_fork_seed_child_context
    mov esi, [process_fork_parent_proc]
    mov eax, [esi + PROC_PID]
    mov [process_fork_parent_pid], eax
    mov edi, [process_fork_child_proc]
    mov eax, [edi + PROC_PID]
    mov [process_fork_child_pid], eax
    mov [process_fork_parent_return], eax
    inc dword [process_fork_successes]
    clc
    jmp .done

.rollback_enomem:
    call process_fork_rollback_child

.enomem:
    inc dword [process_fork_failures]
    mov eax, -ERRNO_ENOMEM
    stc
    jmp .done

.enosys:
    inc dword [process_fork_failures]
    mov eax, -ERRNO_ENOSYS
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

clear_fault_record:
    push eax
    push ecx
    push edi
    mov edi, fault_vector
    xor eax, eax
    mov ecx, (panic_status - fault_vector) / 4
    cld
    rep stosd
    pop edi
    pop ecx
    pop eax
    ret

process_seed_initial_user_context:
    push eax
    push ecx
    push edi
    lea edi, [esi + PROC_SAVED_EAX]
    xor eax, eax
    mov ecx, 16
    cld
    rep stosd
    mov eax, [esi + PROC_ENTRY]
    mov [esi + PROC_SAVED_EIP], eax
    mov eax, [esi + PROC_STACK_TOP]
    mov [esi + PROC_SAVED_ESP], eax
    mov dword [esi + PROC_SAVED_EFLAGS], 0x00000202
    mov dword [esi + PROC_SAVED_CS], USER_CODE_SEG
    mov dword [esi + PROC_SAVED_SS], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_DS], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_ES], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_FS], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_GS], USER_DATA_SEG
    mov dword [esi + PROC_STATE], PROC_STATE_READY
    mov dword [esi + PROC_QUANTUM_TICKS], 0
    or dword [esi + PROC_VM_FLAGS], PROC_FLAG_IRQ_FRAME_VALID
    mov dword [esi + PROC_PERSONALITY], PERSONALITY_NATIVE
    mov dword [esi + PROC_LINUX_TLS_BASE], 0
    call process_linux_clear_metadata
    call process_fpu_reset_context
    pop edi
    pop ecx
    pop eax
    ret

process_linux_clear_metadata:
    push eax
    push ecx
    push edi
    lea edi, [esi + PROC_LINUX_SET_TID_ADDR]
    xor eax, eax
    mov ecx, (PROCESS_RECORD_BYTES - PROC_LINUX_SET_TID_ADDR) / 4
    cld
    rep stosd
    pop edi
    pop ecx
    pop eax
    ret

process_fpu_context_for_ptr:
    cmp edx, process_kernel
    je .fail
    cmp edx, process_user_probe
    je .slot0
    cmp edx, process_preempt_probe
    je .slot1
    cmp edx, process_payload
    je .slot2
    cmp edx, process_generic0
    je .slot3
    cmp edx, process_generic1
    je .slot4
    cmp edx, process_generic2
    je .slot5
    jmp .fail

.slot0:
    mov edi, process_fpu_contexts + (FPU_CONTEXT_BYTES * 0)
    mov ebx, process_fpu_initialized + 0
    clc
    ret

.slot1:
    mov edi, process_fpu_contexts + (FPU_CONTEXT_BYTES * 1)
    mov ebx, process_fpu_initialized + 1
    clc
    ret

.slot2:
    mov edi, process_fpu_contexts + (FPU_CONTEXT_BYTES * 2)
    mov ebx, process_fpu_initialized + 2
    clc
    ret

.slot3:
    mov edi, process_fpu_contexts + (FPU_CONTEXT_BYTES * 3)
    mov ebx, process_fpu_initialized + 3
    clc
    ret

.slot4:
    mov edi, process_fpu_contexts + (FPU_CONTEXT_BYTES * 4)
    mov ebx, process_fpu_initialized + 4
    clc
    ret

.slot5:
    mov edi, process_fpu_contexts + (FPU_CONTEXT_BYTES * 5)
    mov ebx, process_fpu_initialized + 5
    clc
    ret

.fail:
    stc
    ret

process_fpu_reset_context:
    pushad
    mov edx, esi
    call process_fpu_context_for_ptr
    jc .done
    mov byte [ebx], 0
    xor eax, eax
    mov ecx, FPU_CONTEXT_BYTES / 4
    cld
    rep stosd

.done:
    popad
    ret

process_fpu_switch_context:
    pushad
    cmp byte [fpu_status], FPU_STATUS_READY
    jne .done
    cmp ebx, esi
    je .done

    mov edx, ebx
    cmp edx, 0
    je .restore_new
    cmp dword [edx + PROC_KIND], USER_KIND_NONE
    je .restore_new
    call process_fpu_context_for_ptr
    jc .restore_new
    cmp byte [ebx], 1
    jne .restore_new
    fxsave [edi]
    inc dword [fpu_context_save_count]

.restore_new:
    mov edx, esi
    cmp edx, 0
    je .done
    cmp dword [edx + PROC_KIND], USER_KIND_NONE
    je .done
    call process_fpu_context_for_ptr
    jc .done
    cmp byte [ebx], 1
    je .restore_saved
    fninit
    fnclex
    fnstcw [fpu_last_user_control_word]
    fnstsw [fpu_last_user_status_word]
    mov byte [ebx], 1
    inc dword [fpu_context_init_count]
    jmp .record_cr0

.restore_saved:
    fxrstor [edi]
    fnstcw [fpu_last_user_control_word]
    fnstsw [fpu_last_user_status_word]
    inc dword [fpu_context_restore_count]

.record_cr0:
    clts
    mov eax, cr0
    mov [fpu_cr0_after], eax

.done:
    popad
    ret

process_activate:
    push eax
    push ebx
    mov ebx, [current_process_ptr]
    cmp ebx, 0
    je .activate
    cmp dword [ebx + PROC_STATE], PROC_STATE_RUNNING
    jne .activate
    mov dword [ebx + PROC_STATE], PROC_STATE_READY

.activate:
    call process_fpu_switch_context
    mov [current_process_ptr], esi
    mov eax, [esi + PROC_PID]
    mov [current_pid], eax
    mov eax, [esi + PROC_PAGE_DIR]
    test eax, eax
    jnz .have_page_dir
    mov eax, PAGING_DIR_ADDR

.have_page_dir:
    mov cr3, eax
    mov eax, [esi + PROC_KERNEL_STACK_TOP]
    cmp byte [kernel_high_mainline_active], KERNEL_HIGH_MAINLINE_ACTIVE
    jne .kernel_stack_ready
    add eax, KERNEL_HIGHER_HALF_BASE

.kernel_stack_ready:
    mov [tss_esp0], eax
    mov [cpu_tss_esp0_last], eax
    mov word [tss_ss0], DATA_SEG
    mov word [cpu_tss_ss0_last], DATA_SEG
    mov dword [esi + PROC_STATE], PROC_STATE_RUNNING
    inc dword [esi + PROC_RUNS]
    inc dword [esi + PROC_SWITCHES]
    inc dword [scheduler_context_switches]
    mov eax, [esi + PROC_KIND]
    mov [current_user_kind], al
    mov eax, [esi + PROC_BASE]
    mov [current_user_base], eax
    mov eax, [esi + PROC_END]
    mov [current_user_end], eax
    mov eax, [esi + PROC_BRK]
    mov [current_user_brk], eax
    mov [user_brk_current], eax
    mov eax, [esi + PROC_HEAP_START]
    mov [current_user_heap_start], eax
    mov eax, [esi + PROC_HEAP_END]
    mov [current_user_heap_end], eax
    mov eax, [esi + PROC_STACK_TOP]
    mov [current_user_stack_top], eax
    mov eax, [esi + PROC_ENTRY]
    mov [current_user_entry], eax
    cmp dword [esi + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .tls_ready
    cmp dword [esi + PROC_SAVED_GS], LINUX_TLS_SEG
    jne .tls_ready
    mov eax, [esi + PROC_LINUX_TLS_BASE]
    call linux_tls_write_descriptor

.tls_ready:
    pop ebx
    pop eax
    ret

process_return_to_kernel:
    mov esi, process_kernel
    call process_activate
    ret

process_mark_current_exited:
    push esi
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .done
    call process_retire_current_exit_slot
    mov eax, [esi + PROC_PID]
    mov [process_exit_last_pid], eax
    mov [esi + PROC_EXIT_STATUS], ebx
    mov [process_exit_last_status], ebx
    mov dword [process_exit_last_state], PROC_STATE_EXITED

.done:
    pop esi
    ret

process_mark_current_faulted:
    push esi
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .done
    call fd_close_owned_by_process
    call process_teardown_user_vm
    mov eax, [esi + PROC_PID]
    mov [process_fault_last_pid], eax
    mov eax, [fault_vector]
    and eax, 0xff
    or eax, PROCESS_FAULT_EXIT_STATUS_BASE
    mov [esi + PROC_EXIT_STATUS], eax
    mov [process_fault_last_status], eax
    mov dword [esi + PROC_STATE], PROC_STATE_FAULTED
    mov dword [process_fault_last_state], PROC_STATE_FAULTED

.done:
    pop esi
    ret

process_waitpid_current:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [process_wait_last_pid_arg], ebx
    mov [process_wait_last_status_ptr], ecx
    mov [process_wait_last_options], edx
    inc dword [process_wait_attempts]
    mov eax, edx
    and eax, 0xfffffffe
    jne .einval
    cmp ebx, 0xffffffff
    je .pid_ok
    cmp ebx, 0
    jg .pid_ok
    jmp .echild

.pid_ok:
    cmp ecx, 0
    je .scan
    mov eax, ecx
    mov ebx, 4
    call user_range_validate
    jc .einval

.scan:
    mov dword [process_wait_seen_live_child], 0
    mov esi, process_table
    mov edi, PROCESS_SLOT_COUNT

.scan_next:
    cmp edi, 0
    je .scan_done
    cmp esi, process_kernel
    je .advance
    mov eax, [current_process_ptr]
    cmp esi, eax
    je .advance
    mov eax, [esi + PROC_PARENT_PID]
    cmp eax, [current_pid]
    jne .advance
    mov eax, [process_wait_last_pid_arg]
    cmp eax, 0xffffffff
    je .child_matches
    cmp eax, [esi + PROC_PID]
    jne .advance

.child_matches:
    mov eax, [esi + PROC_STATE]
    cmp eax, PROC_STATE_EXITED
    je .reap
    cmp eax, PROC_STATE_FAULTED
    je .reap
    mov dword [process_wait_seen_live_child], 1
    jmp .advance

.advance:
    add esi, PROCESS_RECORD_BYTES
    dec edi
    jmp .scan_next

.scan_done:
    cmp dword [process_wait_seen_live_child], 0
    jne .live_child
    jmp .echild

.live_child:
    test dword [process_wait_last_options], WAIT_OPTION_WNOHANG
    jnz .nohang
    mov eax, WAITPID_BLOCK_SENTINEL
    clc
    jmp .done

.nohang:
    inc dword [process_wait_nohang_returns]
    xor eax, eax
    clc
    jmp .done

.reap:
    mov eax, [esi + PROC_PID]
    mov [process_wait_last_reaped_pid], eax
    mov ebx, [esi + PROC_EXIT_STATUS]
    mov [process_wait_last_status], ebx
    mov ecx, [process_wait_last_status_ptr]
    cmp ecx, 0
    je .reap_without_status
    push eax
    mov eax, [current_process_ptr]
    cmp eax, 0
    je .status_ready
    cmp dword [eax + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .status_ready
    mov eax, ebx
    and eax, 0xff
    shl eax, 8
    mov ebx, eax

.status_ready:
    pop eax
    mov [ecx], ebx

.reap_without_status:
    inc dword [process_wait_reaps]
    call fd_close_owned_by_process
    mov eax, [process_vm_pages_cleared]
    mov [process_wait_vm_pages_before], eax
    call process_teardown_user_vm
    mov eax, [process_vm_pages_cleared]
    sub eax, [process_wait_vm_pages_before]
    mov [process_wait_last_vm_pages_reclaimed], eax
    add [process_wait_vm_pages_reclaimed], eax
    inc dword [process_wait_vm_reaps]
    mov dword [esi + PROC_STATE], PROC_STATE_UNUSED
    mov dword [esi + PROC_PARENT_PID], 0xffffffff
    and dword [esi + PROC_VM_FLAGS], ~PROC_FLAGS_TRANSIENT_MASK
    mov eax, [process_wait_last_reaped_pid]
    clc
    jmp .done

.einval:
    inc dword [process_wait_failures]
    mov eax, -ERRNO_EINVAL
    stc
    jmp .done

.enosys:
    inc dword [process_wait_failures]
    mov eax, -ERRNO_ENOSYS
    stc
    jmp .done

.echild:
    inc dword [process_wait_failures]
    mov eax, -ERRNO_ECHILD
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

process_status_current:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [process_status_last_pid_arg], ebx
    inc dword [process_status_attempts]
    cmp ecx, 0
    je .einval
    cmp edx, VIBE_PROCESS_STATUS_BYTES
    jb .einval
    mov [syscall_ptr_arg], ecx
    mov eax, ecx
    mov ebx, VIBE_PROCESS_STATUS_BYTES
    call user_range_validate
    jc .einval
    mov eax, [process_status_last_pid_arg]
    cmp eax, 0
    je .current
    test eax, 0x80000000
    jnz .einval
    mov esi, process_table
    mov edi, PROCESS_SLOT_COUNT

.scan_next:
    cmp edi, 0
    je .einval
    cmp dword [esi + PROC_STATE], PROC_STATE_UNUSED
    je .advance
    cmp eax, [esi + PROC_PID]
    je .found

.advance:
    add esi, PROCESS_RECORD_BYTES
    dec edi
    jmp .scan_next

.current:
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .einval

.found:
    mov edi, [syscall_ptr_arg]
    xor eax, eax
    mov ecx, VIBE_PROCESS_STATUS_BYTES / 4
    cld
    rep stosd
    mov edi, [syscall_ptr_arg]
    mov dword [edi + PROCESS_STATUS_ABI_VERSION], VIBE_PROCESS_STATUS_ABI_VERSION
    mov dword [edi + PROCESS_STATUS_BYTES], VIBE_PROCESS_STATUS_BYTES
    mov eax, [esi + PROC_PID]
    mov [edi + PROCESS_STATUS_PID], eax
    mov [process_status_last_pid], eax
    mov eax, [esi + PROC_PARENT_PID]
    mov [edi + PROCESS_STATUS_PARENT_PID], eax
    mov [process_status_last_parent_pid], eax
    mov eax, [esi + PROC_STATE]
    mov [edi + PROCESS_STATUS_STATE], eax
    mov [process_status_last_state], eax
    mov eax, [esi + PROC_KIND]
    mov [edi + PROCESS_STATUS_KIND], eax
    mov eax, [esi + PROC_EXIT_STATUS]
    mov [edi + PROCESS_STATUS_EXIT_STATUS], eax
    mov eax, [esi + PROC_TICKS]
    mov [edi + PROCESS_STATUS_TICKS], eax
    mov [process_status_last_ticks], eax
    mov eax, [esi + PROC_RUNS]
    mov [edi + PROCESS_STATUS_RUNS], eax
    mov eax, [esi + PROC_SWITCHES]
    mov [edi + PROCESS_STATUS_SWITCHES], eax
    mov eax, [esi + PROC_QUANTUM_TICKS]
    mov [edi + PROCESS_STATUS_QUANTUM_TICKS], eax
    mov eax, [esi + PROC_ENTRY]
    mov [edi + PROCESS_STATUS_ENTRY], eax
    mov eax, [esi + PROC_STACK_TOP]
    mov [edi + PROCESS_STATUS_STACK_TOP], eax
    mov eax, [esi + PROC_BRK]
    mov [edi + PROCESS_STATUS_BRK], eax
    mov eax, [scheduler_tick_count]
    mov [edi + PROCESS_STATUS_SCHEDULER_TICKS], eax
    mov eax, [scheduler_round_count]
    mov [edi + PROCESS_STATUS_SCHEDULER_ROUNDS], eax
    inc dword [process_status_successes]
    xor eax, eax
    clc
    jmp .done

.einval:
    inc dword [process_status_failures]
    mov eax, -ERRNO_EINVAL
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

scheduler_prepare_live_preempt_probe:
    push eax
    push esi
    mov esi, process_preempt_probe
    call process_reset_preempt_probe
    call process_restore_user_image_vm
    call process_restore_user_stack_vm
    mov dword [esi + PROC_ENTRY], USER_CODE_ADDR
    call process_seed_initial_user_context
    mov dword [esi + PROC_SAVED_EAX], PREEMPT_PROBE_MAGIC
    mov dword [USER_STACK_TOP - 4], PREEMPT_PROBE_MAGIC
    mov dword [scheduler_preempt_probe_ready], 1
    mov dword [scheduler_preempt_spin_value], PREEMPT_PROBE_MAGIC
    pop esi
    pop eax
    ret

scheduler_capture_preempt_spin:
    push eax
    cmp dword [scheduler_preempt_probe_ready], 0
    je .done
    cmp dword [current_process_ptr], process_preempt_probe
    jne .done
    mov eax, [USER_STACK_TOP - 4]
    mov [scheduler_preempt_spin_value], eax
    or dword [scheduler_preempt_abi_mask], PREEMPT_ABI_CAPTURE_SPIN
    mov dword [scheduler_preempt_abi_last_op], PREEMPT_ABI_CAPTURE_SPIN

.done:
    pop eax
    ret

scheduler_block_current:
    push eax
    push ebx
    push ecx
    push edx
    push edi
    push ebp

    inc dword [scheduler_block_attempts]
    mov [scheduler_block_pending_reason], eax
    mov [scheduler_block_pending_object], ebx
    mov [scheduler_block_pending_deadline], ecx
    mov [scheduler_block_pending_status_ptr], edx
    cmp esi, 0
    je .fail
    cmp esi, process_kernel
    je .fail
    mov edi, process_table
    xor ebp, ebp

.find_slot:
    cmp ebp, PROCESS_SLOT_COUNT
    jae .fail
    cmp edi, esi
    je .slot_found
    add edi, PROCESS_RECORD_BYTES
    inc ebp
    jmp .find_slot

.slot_found:
    mov eax, [scheduler_block_pending_deadline]
    mov [scheduler_sleep_wake_ticks + ebp * 4], eax
    mov eax, [scheduler_block_pending_reason]
    mov [scheduler_sleep_reasons + ebp * 4], eax
    mov [scheduler_block_last_reason], eax
    mov eax, [scheduler_block_pending_object]
    mov [scheduler_block_objects + ebp * 4], eax
    mov [scheduler_block_last_object], eax
    mov eax, [scheduler_block_pending_status_ptr]
    mov [scheduler_block_status_ptrs + ebp * 4], eax
    mov dword [esi + PROC_STATE], PROC_STATE_BLOCKED
    mov eax, [esi + PROC_PID]
    mov [scheduler_block_last_pid], eax
    inc dword [scheduler_block_transitions]
    clc
    jmp .done

.fail:
    inc dword [scheduler_block_failures]
    stc

.done:
    pop ebp
    pop edi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

scheduler_wake_sleepers:
    push eax
    push ecx
    push edx
    push edi

    mov edi, process_table
    xor edx, edx
    mov ecx, PROCESS_SLOT_COUNT

.next:
    cmp ecx, 0
    je .done
    cmp dword [edi + PROC_STATE], PROC_STATE_BLOCKED
    jne .advance
    cmp dword [scheduler_sleep_reasons + edx * 4], PROC_BLOCK_SLEEP_TICKS
    jne .advance
    mov eax, [timer_ticks]
    sub eax, [scheduler_sleep_wake_ticks + edx * 4]
    js .advance
    mov dword [edi + PROC_STATE], PROC_STATE_READY
    mov dword [scheduler_sleep_reasons + edx * 4], PROC_BLOCK_NONE
    mov dword [scheduler_sleep_wake_ticks + edx * 4], 0
    mov dword [scheduler_block_objects + edx * 4], 0
    mov dword [scheduler_block_status_ptrs + edx * 4], 0
    inc dword [scheduler_sleep_wakeups]
    inc dword [scheduler_block_wakeups]
    mov eax, [edi + PROC_PID]
    mov [scheduler_sleep_last_woken_pid], eax
    mov [scheduler_block_last_woken_pid], eax
    mov dword [scheduler_block_last_wake_reason], PROC_BLOCK_SLEEP_TICKS

.advance:
    add edi, PROCESS_RECORD_BYTES
    inc edx
    dec ecx
    jmp .next

.done:
    pop edi
    pop edx
    pop ecx
    pop eax
    ret

scheduler_tick:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi
    inc dword [scheduler_tick_count]
    call scheduler_wake_sleepers
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .done
    call scheduler_capture_preempt_spin
    mov eax, [ebx + IRQ_FRAME_CS]
    test eax, 3
    jz .kernel_irq_frame
    inc dword [scheduler_user_irq_ticks]
    or dword [scheduler_preempt_abi_mask], PREEMPT_ABI_USER_IRQ_FRAME
    mov dword [scheduler_preempt_abi_last_op], PREEMPT_ABI_USER_IRQ_FRAME
    mov eax, [ebx + IRQ_FRAME_EIP]
    mov [scheduler_last_irq_frame_eip], eax
    mov eax, [ebx + IRQ_FRAME_CS]
    mov [scheduler_last_irq_frame_cs], eax
    mov eax, [ebx + IRQ_FRAME_ESP]
    mov [scheduler_last_irq_frame_esp], eax
    mov eax, [ebx + IRQ_FRAME_SS]
    mov [scheduler_last_irq_frame_ss], eax
    mov eax, [ebx + IRQ_FRAME_DS]
    mov [scheduler_last_irq_frame_ds], eax
    mov eax, [ebx + IRQ_FRAME_ES]
    mov [scheduler_last_irq_frame_es], eax
    mov eax, [ebx + IRQ_FRAME_FS]
    mov [scheduler_last_irq_frame_fs], eax
    mov eax, [ebx + IRQ_FRAME_GS]
    mov [scheduler_last_irq_frame_gs], eax
    mov eax, [ebx + IRQ_FRAME_EFLAGS]
    mov [scheduler_last_irq_frame_eflags], eax
    call scheduler_validate_irq_user_frame
    jc .invalid_user_irq_frame

.account_current:
    inc dword [esi + PROC_TICKS]
    inc dword [esi + PROC_QUANTUM_TICKS]
    call process_save_irq_context
    or dword [scheduler_preempt_abi_mask], PREEMPT_ABI_SAVE_CONTEXT
    mov dword [scheduler_preempt_abi_last_op], PREEMPT_ABI_SAVE_CONTEXT
    mov eax, [esi + PROC_QUANTUM_TICKS]
    cmp eax, SCHEDULER_QUANTUM_TICKS
    jb .done
    mov dword [esi + PROC_QUANTUM_TICKS], 0
    inc dword [scheduler_round_count]
    mov eax, [ebx + IRQ_FRAME_CS]
    test eax, 3
    jz .skip_preempt
    inc dword [scheduler_preempt_attempts]
    or dword [scheduler_preempt_abi_mask], PREEMPT_ABI_TIMER_ATTEMPT
    mov dword [scheduler_preempt_abi_last_op], PREEMPT_ABI_TIMER_ATTEMPT
    mov eax, [esi + PROC_PID]
    mov [scheduler_last_preempt_from_pid], eax
    mov eax, [esi + PROC_KIND]
    mov [scheduler_last_preempt_from_kind], eax
    mov eax, [esi + PROC_SAVED_EIP]
    mov [scheduler_last_preempt_from_eip], eax
    mov eax, [esi + PROC_SAVED_EFLAGS]
    mov [scheduler_last_preempt_from_eflags], eax
    mov eax, [esi + PROC_PAGE_DIR]
    mov [scheduler_last_preempt_from_cr3], eax
    mov eax, [esi + PROC_KERNEL_STACK_TOP]
    mov [scheduler_last_preempt_from_kstack], eax
    mov dword [scheduler_last_preempt_to_pid], 0xffffffff
    mov dword [scheduler_last_preempt_to_kind], 0
    mov dword [scheduler_last_preempt_to_eip], 0
    mov dword [scheduler_last_preempt_to_eflags], 0
    mov dword [scheduler_last_preempt_to_cr3], 0
    mov dword [scheduler_last_preempt_to_kstack], 0
    call scheduler_select_next_ready
    mov esi, [scheduler_next_process_ptr]
    cmp esi, 0
    je .no_preempt_target
    or dword [scheduler_preempt_abi_mask], PREEMPT_ABI_SELECT_TARGET
    mov dword [scheduler_preempt_abi_last_op], PREEMPT_ABI_SELECT_TARGET
    mov eax, [esi + PROC_PID]
    mov [scheduler_last_preempt_to_pid], eax
    mov eax, [esi + PROC_KIND]
    mov [scheduler_last_preempt_to_kind], eax
    mov eax, [esi + PROC_SAVED_EIP]
    mov [scheduler_last_preempt_to_eip], eax
    mov eax, [esi + PROC_SAVED_EFLAGS]
    call process_sanitize_irq_user_eflags
    mov [esi + PROC_SAVED_EFLAGS], eax
    mov [scheduler_last_preempt_to_eflags], eax
    mov eax, [esi + PROC_PAGE_DIR]
    mov [scheduler_last_preempt_to_cr3], eax
    mov eax, [esi + PROC_KERNEL_STACK_TOP]
    mov [scheduler_last_preempt_to_kstack], eax
    mov eax, [scheduler_last_preempt_from_kind]
    call user_kind_is_large_payload
    jc .check_preempt_probe_to_payload

.check_payload_to_preempt_probe:
    cmp dword [scheduler_last_preempt_to_kind], USER_KIND_PREEMPT_PROBE
    jne .pair_mask_done
    or dword [scheduler_preempt_pair_mask], 0x1
    jmp .pair_mask_done

.check_preempt_probe_to_payload:
    cmp eax, USER_KIND_PREEMPT_PROBE
    jne .pair_mask_done
    mov eax, [scheduler_last_preempt_to_kind]
    call user_kind_is_large_payload
    jc .pair_mask_done

.preempt_probe_to_payload:
    or dword [scheduler_preempt_pair_mask], 0x2

.pair_mask_done:
    call process_activate
    or dword [scheduler_preempt_abi_mask], PREEMPT_ABI_ACTIVATE_TARGET
    mov dword [scheduler_preempt_abi_last_op], PREEMPT_ABI_ACTIVATE_TARGET
    call process_restore_irq_context
    or dword [scheduler_preempt_abi_mask], PREEMPT_ABI_RESTORE_FRAME
    mov dword [scheduler_preempt_abi_last_op], PREEMPT_ABI_RESTORE_FRAME
    inc dword [scheduler_irq_frame_rewrites]
    or dword [scheduler_preempt_abi_mask], PREEMPT_ABI_REWRITE_IRQ_FRAME
    mov dword [scheduler_preempt_abi_last_op], PREEMPT_ABI_REWRITE_IRQ_FRAME
    mov eax, [ebx + IRQ_FRAME_EIP]
    mov [scheduler_last_irq_frame_eip], eax
    mov eax, [ebx + IRQ_FRAME_CS]
    mov [scheduler_last_irq_frame_cs], eax
    mov eax, [ebx + IRQ_FRAME_ESP]
    mov [scheduler_last_irq_frame_esp], eax
    mov eax, [ebx + IRQ_FRAME_SS]
    mov [scheduler_last_irq_frame_ss], eax
    mov eax, [ebx + IRQ_FRAME_DS]
    mov [scheduler_last_irq_frame_ds], eax
    mov eax, [ebx + IRQ_FRAME_ES]
    mov [scheduler_last_irq_frame_es], eax
    mov eax, [ebx + IRQ_FRAME_FS]
    mov [scheduler_last_irq_frame_fs], eax
    mov eax, [ebx + IRQ_FRAME_GS]
    mov [scheduler_last_irq_frame_gs], eax
    mov eax, [ebx + IRQ_FRAME_EFLAGS]
    mov [scheduler_last_irq_frame_eflags], eax
    inc dword [scheduler_preempt_switches]
    inc dword [scheduler_irq_context_switches]
    or dword [scheduler_preempt_abi_mask], PREEMPT_ABI_ACCOUNT_SWITCH
    mov dword [scheduler_preempt_abi_last_op], PREEMPT_ABI_ACCOUNT_SWITCH
    jmp .done

.skip_preempt:
    inc dword [scheduler_preempt_skips]
    jmp .done

.no_preempt_target:
    inc dword [scheduler_preempt_no_peer]
    jmp .done

.invalid_user_irq_frame:
    inc dword [scheduler_irq_frame_invalid]
    inc dword [esi + PROC_TICKS]
    inc dword [esi + PROC_QUANTUM_TICKS]
    and dword [esi + PROC_VM_FLAGS], 0xfffffffe
    jmp .done

.kernel_irq_frame:
    inc dword [esi + PROC_TICKS]
    inc dword [esi + PROC_QUANTUM_TICKS]

.done:
    call scheduler_capture_preempt_spin

.restore_regs:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

process_save_irq_context:
    mov eax, [ebx + IRQ_FRAME_EAX]
    mov [esi + PROC_SAVED_EAX], eax
    mov eax, [ebx + IRQ_FRAME_EBX]
    mov [esi + PROC_SAVED_EBX], eax
    mov eax, [ebx + IRQ_FRAME_ECX]
    mov [esi + PROC_SAVED_ECX], eax
    mov eax, [ebx + IRQ_FRAME_EDX]
    mov [esi + PROC_SAVED_EDX], eax
    mov eax, [ebx + IRQ_FRAME_ESI]
    mov [esi + PROC_SAVED_ESI], eax
    mov eax, [ebx + IRQ_FRAME_EDI]
    mov [esi + PROC_SAVED_EDI], eax
    mov eax, [ebx + IRQ_FRAME_EBP]
    mov [esi + PROC_SAVED_EBP], eax
    mov eax, [ebx + IRQ_FRAME_EIP]
    mov [esi + PROC_SAVED_EIP], eax
    mov eax, [ebx + IRQ_FRAME_EFLAGS]
    call process_sanitize_irq_user_eflags
    mov [esi + PROC_SAVED_EFLAGS], eax
    mov eax, [ebx + IRQ_FRAME_CS]
    mov [esi + PROC_SAVED_CS], eax
    mov eax, [ebx + IRQ_FRAME_DS]
    mov [esi + PROC_SAVED_DS], eax
    mov eax, [ebx + IRQ_FRAME_ES]
    mov [esi + PROC_SAVED_ES], eax
    mov eax, [ebx + IRQ_FRAME_FS]
    mov [esi + PROC_SAVED_FS], eax
    mov eax, [ebx + IRQ_FRAME_GS]
    mov [esi + PROC_SAVED_GS], eax
    mov eax, [esi + PROC_SAVED_CS]
    test eax, 3
    jz .kernel_frame
    mov eax, [ebx + IRQ_FRAME_ESP]
    mov [esi + PROC_SAVED_ESP], eax
    mov eax, [ebx + IRQ_FRAME_SS]
    mov [esi + PROC_SAVED_SS], eax
    or dword [esi + PROC_VM_FLAGS], PROC_FLAG_IRQ_FRAME_VALID
    ret

.kernel_frame:
    mov eax, [ebx + IRQ_FRAME_PUSHAD_ESP]
    mov [esi + PROC_SAVED_ESP], eax
    mov dword [esi + PROC_SAVED_SS], DATA_SEG
    and dword [esi + PROC_VM_FLAGS], 0xfffffffe
    ret

process_restore_irq_context:
    mov eax, [esi + PROC_SAVED_EDI]
    mov [ebx + IRQ_FRAME_EDI], eax
    mov eax, [esi + PROC_SAVED_ESI]
    mov [ebx + IRQ_FRAME_ESI], eax
    mov eax, [esi + PROC_SAVED_EBP]
    mov [ebx + IRQ_FRAME_EBP], eax
    mov eax, [esi + PROC_SAVED_ESP]
    mov [ebx + IRQ_FRAME_PUSHAD_ESP], eax
    mov eax, [esi + PROC_SAVED_EBX]
    mov [ebx + IRQ_FRAME_EBX], eax
    mov eax, [esi + PROC_SAVED_EDX]
    mov [ebx + IRQ_FRAME_EDX], eax
    mov eax, [esi + PROC_SAVED_ECX]
    mov [ebx + IRQ_FRAME_ECX], eax
    mov eax, [esi + PROC_SAVED_EAX]
    mov [ebx + IRQ_FRAME_EAX], eax
    mov eax, [esi + PROC_SAVED_EIP]
    mov [ebx + IRQ_FRAME_EIP], eax
    mov eax, [esi + PROC_SAVED_CS]
    mov [ebx + IRQ_FRAME_CS], eax
    mov eax, [esi + PROC_SAVED_EFLAGS]
    call process_sanitize_irq_user_eflags
    mov [esi + PROC_SAVED_EFLAGS], eax
    mov [ebx + IRQ_FRAME_EFLAGS], eax
    mov eax, [esi + PROC_SAVED_ESP]
    mov [ebx + IRQ_FRAME_ESP], eax
    mov eax, [esi + PROC_SAVED_SS]
    mov [ebx + IRQ_FRAME_SS], eax
    mov eax, [esi + PROC_SAVED_DS]
    mov [ebx + IRQ_FRAME_DS], eax
    mov eax, [esi + PROC_SAVED_ES]
    mov [ebx + IRQ_FRAME_ES], eax
    mov eax, [esi + PROC_SAVED_FS]
    mov [ebx + IRQ_FRAME_FS], eax
    mov eax, [esi + PROC_SAVED_GS]
    mov [ebx + IRQ_FRAME_GS], eax
    ret

scheduler_validate_irq_user_frame:
    push eax
    push edx
    cmp dword [ebx + IRQ_FRAME_CS], USER_CODE_SEG
    jne .fail
    cmp dword [ebx + IRQ_FRAME_SS], USER_DATA_SEG
    jne .fail
    cmp dword [ebx + IRQ_FRAME_DS], USER_DATA_SEG
    jne .fail
    cmp dword [ebx + IRQ_FRAME_ES], USER_DATA_SEG
    jne .fail
    cmp dword [ebx + IRQ_FRAME_FS], USER_DATA_SEG
    jne .fail
    mov eax, [ebx + IRQ_FRAME_GS]
    cmp eax, USER_DATA_SEG
    je .segments_ok
    cmp dword [esi + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .fail
    cmp eax, LINUX_TLS_SEG
    jne .fail

.segments_ok:
    mov eax, [ebx + IRQ_FRAME_EFLAGS]
    mov edx, eax
    and eax, SYSCALL_RETURN_EFLAGS_KEEP_MASK
    or eax, SYSCALL_RETURN_EFLAGS_SET
    cmp eax, edx
    je .eflags_ok
    xor edx, eax
    cmp edx, USER_EFLAGS_RF
    jne .fail_eflags
    mov [ebx + IRQ_FRAME_EFLAGS], eax
    inc dword [scheduler_irq_eflags_sanitize_count]

.eflags_ok:
    mov eax, [ebx + IRQ_FRAME_EIP]
    cmp eax, [esi + PROC_BASE]
    jb .fail
    cmp eax, [esi + PROC_END]
    jae .fail
    mov eax, [ebx + IRQ_FRAME_ESP]
    test eax, eax
    jz .fail
    cmp eax, [esi + PROC_STACK_BOTTOM]
    jbe .fail
    cmp eax, [esi + PROC_STACK_TOP]
    ja .fail
    clc
    jmp .done

.fail:
    stc
    jmp .done

.fail_eflags:
    inc dword [scheduler_irq_eflags_invalid]
    stc

.done:
    pop edx
    pop eax
    ret

process_save_syscall_return_context:
    push eax
    push esi
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .done
    mov eax, [syscall_return_value]
    mov [esi + PROC_SAVED_EAX], eax
    mov eax, [esp + 32]
    mov [esi + PROC_SAVED_EBX], eax
    mov eax, [esp + 28]
    mov [esi + PROC_SAVED_ECX], eax
    mov eax, [esp + 24]
    mov [esi + PROC_SAVED_EDX], eax
    mov eax, [esp + 20]
    mov [esi + PROC_SAVED_ESI], eax
    mov eax, [esp + 16]
    mov [esi + PROC_SAVED_EDI], eax
    mov eax, [esp + 12]
    mov [esi + PROC_SAVED_EBP], eax
    mov eax, [esp + 36]
    mov [esi + PROC_SAVED_EIP], eax
    mov eax, [esp + 44]
    mov [esi + PROC_SAVED_EFLAGS], eax
    mov eax, [esp + 40]
    mov [esi + PROC_SAVED_CS], eax
    mov eax, [esp + 48]
    mov [esi + PROC_SAVED_ESP], eax
    mov eax, [esp + 52]
    mov [esi + PROC_SAVED_SS], eax
    mov dword [esi + PROC_SAVED_DS], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_ES], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_FS], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_GS], USER_DATA_SEG
    cmp dword [esi + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .saved_segments_ready
    mov eax, [syscall_entry_gs_last]
    cmp eax, LINUX_TLS_SEG
    jne .saved_segments_ready
    mov [esi + PROC_SAVED_GS], eax

.saved_segments_ready:
    or dword [esi + PROC_VM_FLAGS], PROC_FLAG_IRQ_FRAME_VALID

.done:
    pop esi
    pop eax
    ret

scheduler_select_next_ready:
    push eax
    push ecx
    push edx
    push edi
    mov dword [scheduler_next_process_ptr], 0
    mov eax, [scheduler_rr_cursor]
    mov ecx, PROCESS_SLOT_COUNT

.next:
    inc eax
    cmp eax, PROCESS_SLOT_COUNT
    jb .index_ok
    xor eax, eax

.index_ok:
    mov edi, eax
    imul edi, PROCESS_RECORD_BYTES
    add edi, process_table
    cmp dword [edi + PROC_STATE], PROC_STATE_READY
    jne .advance
    test dword [edi + PROC_VM_FLAGS], PROC_FLAG_IRQ_FRAME_VALID
    jz .advance
    test dword [edi + PROC_SAVED_CS], 3
    jz .advance
    cmp dword [edi + PROC_SAVED_CS], USER_CODE_SEG
    jne .advance
    cmp dword [edi + PROC_SAVED_SS], USER_DATA_SEG
    jne .advance
    cmp dword [edi + PROC_SAVED_DS], USER_DATA_SEG
    jne .advance
    cmp dword [edi + PROC_SAVED_ES], USER_DATA_SEG
    jne .advance
    cmp dword [edi + PROC_SAVED_FS], USER_DATA_SEG
    jne .advance
    mov eax, [edi + PROC_SAVED_GS]
    cmp eax, USER_DATA_SEG
    je .saved_segments_ok
    cmp dword [edi + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .advance
    cmp eax, LINUX_TLS_SEG
    jne .advance

.saved_segments_ok:
    cmp dword [edi + PROC_SAVED_EIP], 0
    je .advance
    call process_saved_frame_user_bounds_ok
    jc .advance
    jmp .found

.advance:
    loop .next
    mov dword [scheduler_next_pid], 0xffffffff
    jmp .done

.found:
    mov [scheduler_rr_cursor], eax
    mov [scheduler_next_process_ptr], edi
    mov edx, [edi + PROC_PID]
    mov [scheduler_next_pid], edx

.done:
    pop edi
    pop edx
    pop ecx
    pop eax
    ret

process_saved_frame_user_bounds_ok:
    push eax
    mov eax, [edi + PROC_SAVED_EIP]
    cmp eax, [edi + PROC_BASE]
    jb .fail
    cmp eax, [edi + PROC_END]
    jae .fail
    mov eax, [edi + PROC_SAVED_ESP]
    test eax, eax
    jz .fail
    cmp eax, [edi + PROC_STACK_BOTTOM]
    jbe .fail
    cmp eax, [edi + PROC_STACK_TOP]
    ja .fail
    clc
    jmp .done

.fail:
    stc

.done:
    pop eax
    ret

process_sanitize_irq_user_eflags:
    push edx
    mov edx, eax
    and eax, SYSCALL_RETURN_EFLAGS_KEEP_MASK
    or eax, SYSCALL_RETURN_EFLAGS_SET
    cmp eax, edx
    je .done
    inc dword [scheduler_irq_eflags_sanitize_count]

.done:
    pop edx
    ret

scheduler_preempt_self_test:
    pushad
    mov byte [scheduler_preempt_selftest_status], 0

    mov esi, process_user_probe
    mov dword [esi + PROC_STATE], PROC_STATE_READY
    mov dword [esi + PROC_SAVED_EAX], 0x11111111
    mov dword [esi + PROC_SAVED_EBX], 0x22222222
    mov dword [esi + PROC_SAVED_ECX], 0x33333333
    mov dword [esi + PROC_SAVED_EDX], 0x44444444
    mov dword [esi + PROC_SAVED_ESI], 0x55555555
    mov dword [esi + PROC_SAVED_EDI], 0x66666666
    mov dword [esi + PROC_SAVED_EBP], 0x77777777
    mov dword [esi + PROC_SAVED_ESP], USER_STACK_TOP - 16
    mov dword [esi + PROC_SAVED_EIP], USER_CODE_ADDR
    mov dword [esi + PROC_SAVED_EFLAGS], 0x00000202
    mov dword [esi + PROC_SAVED_CS], USER_CODE_SEG
    mov dword [esi + PROC_SAVED_SS], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_DS], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_ES], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_FS], USER_DATA_SEG
    mov dword [esi + PROC_SAVED_GS], USER_DATA_SEG
    or dword [esi + PROC_VM_FLAGS], PROC_FLAG_IRQ_FRAME_VALID

    mov esi, process_preempt_probe
    mov dword [esi + PROC_ENTRY], USER_CODE_ADDR
    call process_seed_initial_user_context
    mov dword [esi + PROC_SAVED_EAX], PREEMPT_PROBE_MAGIC
    mov dword [esi + PROC_SAVED_EFLAGS], 0x00003202

    mov edi, scheduler_preempt_selftest_frame
    xor eax, eax
    mov ecx, IRQ_FRAME_DWORDS
    cld
    rep stosd

    mov esi, process_user_probe
    mov ebx, scheduler_preempt_selftest_frame
    call process_restore_irq_context

    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EAX], 0x11111111
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EBX], 0x22222222
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EIP], USER_CODE_ADDR
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_CS], USER_CODE_SEG
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EFLAGS], 0x00000202
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_ESP], USER_STACK_TOP - 16
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_SS], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_DS], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_ES], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_FS], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_GS], USER_DATA_SEG
    jne .done

    mov dword [scheduler_rr_cursor], 0
    call scheduler_select_next_ready
    cmp dword [scheduler_next_pid], 1
    jne .done
    cmp dword [scheduler_next_process_ptr], process_user_probe
    jne .done
    mov dword [scheduler_rr_cursor], 1
    call scheduler_select_next_ready
    cmp dword [scheduler_next_pid], 3
    jne .done
    cmp dword [scheduler_next_process_ptr], process_preempt_probe
    jne .done

    mov esi, process_user_probe
    mov dword [current_process_ptr], esi
    mov dword [current_pid], 1
    mov dword [esi + PROC_STATE], PROC_STATE_RUNNING
    mov dword [esi + PROC_QUANTUM_TICKS], SCHEDULER_QUANTUM_TICKS
    mov dword [scheduler_rr_cursor], 1
    mov edi, scheduler_preempt_selftest_frame
    xor eax, eax
    mov ecx, IRQ_FRAME_DWORDS
    cld
    rep stosd
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EAX], 0xaaaaaaaa
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EBX], 0xbbbbbbbb
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_ECX], 0xcccccccc
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EDX], 0xdddddddd
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_ESI], 0xeeeeeeee
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EDI], 0xf0f0f0f0
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EBP], 0x77777777
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EIP], USER_CODE_ADDR + 0x20
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_CS], USER_CODE_SEG
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EFLAGS], 0x00000202
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_ESP], USER_STACK_TOP - 32
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_SS], USER_DATA_SEG
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_DS], USER_DATA_SEG
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_ES], USER_DATA_SEG
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_FS], USER_DATA_SEG
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_GS], USER_DATA_SEG
    mov ebx, scheduler_preempt_selftest_frame
    call scheduler_tick

    mov esi, process_user_probe
    test dword [esi + PROC_VM_FLAGS], PROC_FLAG_IRQ_FRAME_VALID
    jz .done
    cmp dword [esi + PROC_SAVED_EAX], 0xaaaaaaaa
    jne .done
    cmp dword [esi + PROC_SAVED_EBX], 0xbbbbbbbb
    jne .done
    cmp dword [esi + PROC_SAVED_ECX], 0xcccccccc
    jne .done
    cmp dword [esi + PROC_SAVED_EDX], 0xdddddddd
    jne .done
    cmp dword [esi + PROC_SAVED_ESI], 0xeeeeeeee
    jne .done
    cmp dword [esi + PROC_SAVED_EDI], 0xf0f0f0f0
    jne .done
    cmp dword [esi + PROC_SAVED_EBP], 0x77777777
    jne .done
    cmp dword [esi + PROC_SAVED_EIP], USER_CODE_ADDR + 0x20
    jne .done
    cmp dword [esi + PROC_SAVED_CS], USER_CODE_SEG
    jne .done
    cmp dword [esi + PROC_SAVED_ESP], USER_STACK_TOP - 32
    jne .done
    cmp dword [esi + PROC_SAVED_SS], USER_DATA_SEG
    jne .done
    cmp dword [esi + PROC_SAVED_DS], USER_DATA_SEG
    jne .done
    cmp dword [esi + PROC_SAVED_ES], USER_DATA_SEG
    jne .done
    cmp dword [esi + PROC_SAVED_FS], USER_DATA_SEG
    jne .done
    cmp dword [esi + PROC_SAVED_GS], USER_DATA_SEG
    jne .done
    cmp dword [current_process_ptr], process_preempt_probe
    jne .done
    cmp dword [current_pid], 3
    jne .done
    cmp dword [scheduler_preempt_attempts], 1
    jne .done
    cmp dword [scheduler_preempt_switches], 1
    jne .done
    cmp dword [scheduler_irq_context_switches], 1
    jne .done
    cmp dword [scheduler_irq_frame_rewrites], 1
    jne .done
    cmp dword [scheduler_last_preempt_from_pid], 1
    jne .done
    cmp dword [scheduler_last_preempt_to_pid], 3
    jne .done
    cmp dword [scheduler_last_preempt_from_cr3], PROC_PROBE_PAGE_DIR_ADDR
    jne .done
    cmp dword [scheduler_last_preempt_to_cr3], PROC_PREEMPT_PAGE_DIR_ADDR
    jne .done
    cmp dword [scheduler_last_preempt_from_kstack], PROC_USER_PROBE_KERNEL_STACK_TOP
    jne .done
    cmp dword [scheduler_last_preempt_to_kstack], PROC_PREEMPT_PROBE_KERNEL_STACK_TOP
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EAX], PREEMPT_PROBE_MAGIC
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EIP], USER_CODE_ADDR
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_CS], USER_CODE_SEG
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EFLAGS], 0x00000202
    jne .done
    cmp dword [scheduler_last_preempt_to_eflags], 0x00000202
    jne .done
    cmp dword [scheduler_last_irq_frame_eflags], 0x00000202
    jne .done
    cmp dword [scheduler_irq_eflags_sanitize_count], 1
    jne .done
    mov eax, [scheduler_irq_eflags_sanitize_count]
    mov [scheduler_preempt_selftest_eflags_sanitize_count], eax
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_ESP], USER_STACK_TOP
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_SS], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_DS], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_ES], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_FS], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_preempt_selftest_frame + IRQ_FRAME_GS], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_last_irq_frame_eip], USER_CODE_ADDR
    jne .done
    cmp dword [scheduler_last_irq_frame_cs], USER_CODE_SEG
    jne .done
    cmp dword [scheduler_last_irq_frame_esp], USER_STACK_TOP
    jne .done
    cmp dword [scheduler_last_irq_frame_ss], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_last_irq_frame_ds], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_last_irq_frame_es], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_last_irq_frame_fs], USER_DATA_SEG
    jne .done
    cmp dword [scheduler_last_irq_frame_gs], USER_DATA_SEG
    jne .done

    mov esi, process_user_probe
    mov dword [current_process_ptr], esi
    mov dword [current_pid], 1
    mov dword [esi + PROC_STATE], PROC_STATE_RUNNING
    mov dword [esi + PROC_QUANTUM_TICKS], 0
    or dword [esi + PROC_VM_FLAGS], PROC_FLAG_IRQ_FRAME_VALID
    mov edi, scheduler_preempt_selftest_frame
    xor eax, eax
    mov ecx, IRQ_FRAME_DWORDS
    cld
    rep stosd
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EAX], 0x10101010
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EIP], USER_CODE_ADDR + 0x24
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_CS], USER_CODE_SEG
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_EFLAGS], 0x00003202
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_ESP], USER_STACK_TOP - 64
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_SS], USER_DATA_SEG
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_DS], USER_DATA_SEG
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_ES], USER_DATA_SEG
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_FS], USER_DATA_SEG
    mov dword [scheduler_preempt_selftest_frame + IRQ_FRAME_GS], USER_DATA_SEG
    mov ebx, scheduler_preempt_selftest_frame
    call scheduler_tick

    cmp dword [scheduler_irq_frame_invalid], 1
    jne .done
    cmp dword [scheduler_irq_eflags_invalid], 1
    jne .done
    test dword [process_user_probe + PROC_VM_FLAGS], PROC_FLAG_IRQ_FRAME_VALID
    jnz .done
    cmp dword [current_process_ptr], process_user_probe
    jne .done
    cmp dword [scheduler_preempt_switches], 1
    jne .done
    cmp dword [scheduler_irq_context_switches], 1
    jne .done
    mov eax, [scheduler_irq_frame_invalid]
    mov [scheduler_preempt_selftest_invalid_count], eax
    mov eax, [scheduler_irq_eflags_invalid]
    mov [scheduler_preempt_selftest_eflags_invalid_count], eax

    mov byte [scheduler_preempt_selftest_status], 1

.done:
    mov eax, PAGING_DIR_ADDR
    mov cr3, eax
    mov dword [current_process_ptr], process_kernel
    mov dword [current_pid], 0
    mov byte [current_user_kind], USER_KIND_NONE
    mov eax, KERNEL_STACK_TOP
    cmp byte [kernel_high_mainline_active], KERNEL_HIGH_MAINLINE_ACTIVE
    jne .restore_kernel_tss
    add eax, KERNEL_HIGHER_HALF_BASE

.restore_kernel_tss:
    mov [tss_esp0], eax
    mov [cpu_tss_esp0_last], eax
    mov word [tss_ss0], DATA_SEG
    mov word [cpu_tss_ss0_last], DATA_SEG
    mov dword [process_kernel + PROC_STATE], PROC_STATE_RUNNING
    mov dword [scheduler_tick_count], 0
    mov dword [scheduler_round_count], 0
    mov dword [scheduler_context_switches], 0
    mov dword [scheduler_rr_cursor], 0
    mov dword [scheduler_next_pid], 0xffffffff
    mov dword [scheduler_next_process_ptr], 0
    mov dword [scheduler_preempt_attempts], 0
    mov dword [scheduler_preempt_switches], 0
    mov dword [scheduler_irq_context_switches], 0
    mov dword [scheduler_preempt_skips], 0
    mov dword [scheduler_preempt_no_peer], 0
    mov dword [scheduler_irq_frame_invalid], 0
    mov dword [scheduler_irq_eflags_invalid], 0
    mov dword [scheduler_user_irq_ticks], 0
    mov dword [scheduler_last_preempt_from_pid], 0xffffffff
    mov dword [scheduler_last_preempt_to_pid], 0xffffffff
    mov dword [scheduler_last_preempt_from_kind], 0
    mov dword [scheduler_last_preempt_to_kind], 0
    mov dword [scheduler_last_preempt_from_eip], 0
    mov dword [scheduler_last_preempt_to_eip], 0
    mov dword [scheduler_last_preempt_from_eflags], 0
    mov dword [scheduler_last_preempt_to_eflags], 0
    mov dword [scheduler_last_preempt_from_cr3], 0
    mov dword [scheduler_last_preempt_to_cr3], 0
    mov dword [scheduler_last_preempt_from_kstack], 0
    mov dword [scheduler_last_preempt_to_kstack], 0
    mov dword [scheduler_irq_frame_rewrites], 0
    mov dword [scheduler_last_irq_frame_eip], 0
    mov dword [scheduler_last_irq_frame_cs], 0
    mov dword [scheduler_last_irq_frame_esp], 0
    mov dword [scheduler_last_irq_frame_ss], 0
    mov dword [scheduler_last_irq_frame_ds], 0
    mov dword [scheduler_last_irq_frame_es], 0
    mov dword [scheduler_last_irq_frame_fs], 0
    mov dword [scheduler_last_irq_frame_gs], 0
    mov dword [scheduler_last_irq_frame_eflags], 0
    mov dword [scheduler_irq_eflags_sanitize_count], 0
    mov dword [scheduler_preempt_pair_mask], 0
    mov dword [scheduler_preempt_probe_ready], 0
    mov dword [scheduler_preempt_spin_value], 0
    mov dword [scheduler_preempt_abi_mask], 0
    mov dword [scheduler_preempt_abi_last_op], 0
    mov esi, process_user_probe
    call process_reset_user_probe
    mov esi, process_preempt_probe
    call process_reset_preempt_probe
    mov esi, process_payload
    call process_reset_payload
    popad
    ret

process_boot_launch_payload:
    cmp dword [sys_exec_successes], 0
    jne .done
    mov dword [payload_lifecycle_run_status + USER_KIND_PAYLOAD_PRIMARY * 4], 4

.done:
    ret

process_exec_path:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov byte [process_exec_status], 0
    mov dword [process_exec_last_error], 0
    mov dword [process_exec_entry], 0
    mov dword [process_exec_last_resolve_mode], SYS_EXEC_RESOLVE_NONE
    mov dword [process_exec_load_old_cr3], 0
    mov dword [process_exec_load_target_cr3], 0
    mov dword [process_exec_path_ptr], esi
    mov dword [process_exec_target], edi
    mov dword [process_exec_target_kind], USER_KIND_NONE
    mov dword [process_exec_target_personality], PERSONALITY_NATIVE
    mov byte [process_exec_lookup_depth], 0
    call process_exec_resolve_path
    jnc .resolved
    cmp dword [process_exec_last_error], 0
    jne .fail
    mov dword [process_exec_last_error], -ERRNO_ENOENT
    jmp .fail

.resolved:
    cmp byte [process_exec_reject_active_target], 1
    jne .target_safe
    mov eax, [current_process_ptr]
    cmp eax, [process_exec_target]
    jne .target_safe
    mov dword [process_exec_last_error], -ERRNO_EACCES
    jmp .fail

.target_safe:
    mov esi, [process_exec_target]
    call process_reuse_exec_target_slot

    call process_exec_find_file
    jnc .fat_found
    mov dword [process_exec_last_error], -ERRNO_ENOENT
    jmp .fail

.fat_found:

    mov ax, [fat_found_first_cluster]
    mov [process_exec_first_cluster], ax
    mov eax, [fat_found_size]
    mov [process_exec_size], eax

    cmp dword [process_exec_target], process_payload
    je near .bind_large_payload_artifact
    mov eax, [process_exec_target]
    call process_is_user_exec_target
    jnc near .bind_user_artifact
    jmp near .reserve

.bind_large_payload_artifact:
    mov ax, [process_exec_first_cluster]
    mov [payload_elf_first_cluster], ax
    mov eax, [process_exec_size]
    mov [payload_elf_size], eax
    mov byte [payload_elf_status], 1
    mov byte [payload_elf_load_status], 0
    mov byte [payload_elf_parse_status], 0
    mov ax, [process_exec_first_cluster]
    movzx edx, ax
    mov eax, payload_exec_first_cluster
    call payload_exec_store_target
    mov eax, [process_exec_size]
    mov edx, eax
    mov eax, payload_exec_size
    call payload_exec_store_target
    mov edx, 1
    mov eax, payload_exec_status
    call payload_exec_store_target
    xor edx, edx
    mov eax, payload_exec_load_status
    call payload_exec_store_target
    mov eax, payload_exec_parse_status
    call payload_exec_store_target
    jmp near .reserve

.bind_user_artifact:
    mov ax, [process_exec_first_cluster]
    mov [user_elf_first_cluster], ax
    mov eax, [process_exec_size]
    mov [user_elf_size], eax
    mov byte [user_elf_status], 1

.reserve:
    mov eax, [process_exec_size]
    cmp eax, [process_exec_max_bytes]
    jbe .reserve_size_ok
    cmp dword [process_exec_target_personality], PERSONALITY_LINUX
    jne .too_big
    call process_exec_large_linux_preflight
    jc .fail
    jmp .prepared

.too_big:
    mov dword [process_exec_last_error], -ERRNO_E2BIG
    jmp .fail

.reserve_size_ok:
    mov eax, [process_exec_size]
    add eax, PAGE_SIZE - 1
    shr eax, 12
    mov ecx, eax
    mov eax, [process_exec_load_addr]
    call pmm_reserve_pages

    pushfd
    cli
    mov eax, cr3
    push eax
    mov [process_exec_load_old_cr3], eax
    mov [process_exec_load_target_cr3], eax
    mov ebx, [process_exec_target]
    cmp ebx, 0
    je .load_address_space_ready
    mov eax, [ebx + PROC_PAGE_DIR]
    test eax, eax
    jz .load_address_space_ready
    mov [process_exec_load_target_cr3], eax
    mov cr3, eax

.load_address_space_ready:
    movzx eax, word [process_exec_first_cluster]
    mov ebx, [process_exec_size]
    mov ecx, [process_exec_max_bytes]
    mov edi, [process_exec_load_addr]
    call fat_load_file
    jc .load_fail_restore_cr3

    mov eax, [fat_load_sectors_read]
    mov [process_exec_sectors_read], eax
    mov esi, [process_exec_load_addr]
    cmp dword [esi], ELF_MAGIC
    jne .load_fail_restore_cr3

    cmp dword [process_exec_target], process_payload
    je .loaded_payload
    mov eax, [process_exec_target]
    call process_is_user_exec_target
    jnc .loaded_user_probe
    jmp .unsupported_restore_cr3

.loaded_payload:
    mov eax, [process_exec_sectors_read]
    mov [payload_elf_sectors_read], eax
    mov byte [payload_elf_load_status], 1
    mov edx, eax
    mov eax, payload_exec_sectors_read
    call payload_exec_store_target
    mov edx, 1
    mov eax, payload_exec_load_status
    call payload_exec_store_target
    jmp .prepare

.loaded_user_probe:
    mov eax, [process_exec_sectors_read]
    mov [user_elf_sectors_read], eax
    mov byte [user_elf_status], 1

.prepare:
    call process_exec_prepare_elf_image
    jnc .prepared_restore_cr3

.prepare_fail_restore_cr3:
    pop eax
    mov cr3, eax
    popfd
    mov dword [process_exec_last_error], -ERRNO_EIO
    jmp .fail

.load_fail_restore_cr3:
    pop eax
    mov cr3, eax
    popfd
    jmp .load_fail

.unsupported_restore_cr3:
    pop eax
    mov cr3, eax
    popfd
    jmp .unsupported

.prepared_restore_cr3:
    pop eax
    mov cr3, eax
    popfd

.prepared:
    mov esi, [process_exec_target]
    mov eax, [process_exec_entry]
    mov [esi + PROC_ENTRY], eax
    mov eax, [process_exec_last_resolve_mode]
    mov [process_exec_last_success_mode], eax
    cmp eax, SYS_EXEC_RESOLVE_GENERIC_ROOT83
    je .generic_success
    cmp eax, SYS_EXEC_RESOLVE_APP_PATH
