.generic_success:
    inc dword [process_exec_generic_successes]
    mov eax, [esi + PROC_PID]
    mov [process_exec_last_generic_pid], eax
    mov eax, [process_exec_entry]
    mov [process_exec_last_generic_entry], eax

.status_success:
    mov byte [process_exec_status], 1
    clc
    jmp .done

.unsupported:
    mov dword [process_exec_last_error], -ERRNO_EINVAL
    stc
    jmp .fail

.load_fail:
    mov dword [process_exec_last_error], -ERRNO_EIO
    cmp dword [process_exec_target], process_payload
    je .load_fail_payload
    mov eax, [process_exec_target]
    call process_is_user_exec_target
    jc .fail
    mov byte [user_elf_status], 2
    jmp .fail

.load_fail_payload:
    mov byte [payload_elf_load_status], 2
    mov edx, 2
    mov eax, payload_exec_load_status
    call payload_exec_store_target

.fail:
    mov esi, [process_exec_target]
    cmp esi, 0
    je .status_fail
    cmp esi, [current_process_ptr]
    je .status_fail
    call process_retire_exec_slot

.status_fail:
    mov byte [process_exec_status], 2
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

