    inc dword [process_exec_table_resolves]
    mov dword [process_exec_last_resolve_mode], SYS_EXEC_RESOLVE_TABLE
    mov eax, [ebx + PROCESS_EXEC_NAME83]
    mov [process_exec_name83], eax
