process_exec_resolve_generic_root83:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov edi, process_exec_name83_buffer
    mov al, ' '
    mov ecx, 11
    cld
    rep stosb
    mov esi, [process_exec_path_ptr]
    cmp esi, 0
    je .fail
    xor eax, eax
    mov [process_exec_base_len], al
    mov [process_exec_ext_len], al
    mov [process_exec_dot_seen], al
    mov ecx, SYS_EXEC_PATH_MAX - 1

.skip_prefix:
    cmp ecx, 0
    je .fail
    mov al, [esi]
    cmp al, '/'
    je .skip_one_prefix_char
    cmp al, 0x5c
    je .skip_one_prefix_char
    cmp al, '.'
    jne .char_loop
    mov al, [esi + 1]
    cmp al, '/'
    je .skip_dot_prefix
    cmp al, 0x5c
    je .skip_dot_prefix
    jmp .char_loop

.skip_one_prefix_char:
    inc esi
    dec ecx
    jmp .skip_prefix

.skip_dot_prefix:
    add esi, 2
    sub ecx, 2
    js .fail
    jmp .skip_prefix

.char_loop:
    cmp ecx, 0
    je .fail
    lodsb
    test al, al
    jz .finish
    dec ecx
    cmp al, '/'
    je .fail
    cmp al, 0x5c
    je .fail
    cmp al, '.'
    je .dot
    cmp al, 'a'
    jb .validate_char
    cmp al, 'z'
    ja .validate_char
    sub al, 32

.validate_char:
    cmp al, 'A'
    jb .check_digit
    cmp al, 'Z'
    jbe .store_char

.check_digit:
    cmp al, '0'
    jb .check_extra
    cmp al, '9'
    jbe .store_char

.check_extra:
    cmp al, '_'
    je .store_char
    cmp al, '-'
    je .store_char
    jmp .fail

.dot:
    cmp byte [process_exec_base_len], 0
    je .fail
    cmp byte [process_exec_dot_seen], 0
    jne .fail
    mov byte [process_exec_dot_seen], 1
    jmp .char_loop

.store_char:
    cmp byte [process_exec_dot_seen], 0
    jne .store_ext
    movzx edx, byte [process_exec_base_len]
    cmp edx, 8
    jae .fail
    mov [process_exec_name83_buffer + edx], al
    inc byte [process_exec_base_len]
    jmp .char_loop

.store_ext:
    movzx edx, byte [process_exec_ext_len]
    cmp edx, 3
    jae .fail
    mov [process_exec_name83_buffer + 8 + edx], al
    inc byte [process_exec_ext_len]
    jmp .char_loop

.finish:
    cmp byte [process_exec_base_len], 0
    je .fail
    cmp byte [process_exec_dot_seen], 0
    je .fail
    cmp byte [process_exec_ext_len], 0
    je .fail
    cmp byte [process_exec_name83_buffer + 8], 'E'
    jne .fail
    cmp byte [process_exec_name83_buffer + 9], 'L'
    jne .fail
    cmp byte [process_exec_name83_buffer + 10], 'F'
    jne .fail
    call process_exec_resolve_large_payload_label
    jnc .done
    call process_alloc_generic_exec_slot
    jc .fail
    inc dword [process_exec_generic_resolves]
    mov dword [process_exec_last_resolve_mode], SYS_EXEC_RESOLVE_GENERIC_ROOT83
    mov dword [process_exec_name83], process_exec_name83_buffer
    mov dword [process_exec_load_addr], USER_ELF_LOAD_ADDR
    mov dword [process_exec_max_bytes], USER_ELF_MAX_BYTES
    mov [process_exec_target], esi
    mov dword [process_exec_target_kind], USER_KIND_GENERIC
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

process_exec_resolve_large_payload_label:
    push eax
    push ebx
    push ecx
    push esi
    push edi

    mov ebx, large_payload_proof_label_table
    mov ecx, LARGE_PAYLOAD_PROOF_LABEL_COUNT

.scan_next:
    cmp ecx, 0
    je .not_found
    push ecx
    mov esi, process_exec_name83_buffer
    mov edi, [ebx + LARGE_PAYLOAD_PROOF_LABEL_NAME83]
    cld
    call fat_name_match
    pop ecx
    cmp al, 1
    je .found
    add ebx, LARGE_PAYLOAD_PROOF_LABEL_ENTRY_BYTES
    dec ecx
    jmp .scan_next

.found:
    inc dword [process_exec_generic_resolves]
    mov dword [process_exec_last_resolve_mode], SYS_EXEC_RESOLVE_GENERIC_ROOT83
    mov dword [process_exec_name83], process_exec_name83_buffer
    mov dword [process_exec_load_addr], PAYLOAD_ELF_LOAD_ADDR
    mov dword [process_exec_max_bytes], PAYLOAD_ELF_MAX_BYTES
    mov dword [process_exec_target], process_payload
    mov eax, [ebx + LARGE_PAYLOAD_PROOF_LABEL_KIND]
    mov [process_exec_target_kind], eax
    clc
    jmp .done

.not_found:
    stc

.done:
    pop edi
    pop esi
    pop ecx
    pop ebx
    pop eax
    ret

process_exec_large_linux_preflight:
    pushad

    mov dword [large_elf_status], LARGE_ELF_STATUS_NONE
    mov dword [large_elf_type], 0
    mov dword [large_elf_entry], 0
    mov dword [large_elf_phoff], 0
    mov dword [large_elf_phnum], 0
    mov dword [large_elf_load_count], 0
    mov dword [large_elf_interp_status], 0
    mov dword [large_elf_interp_match], 0
    mov dword [large_elf_image_low], 0xffffffff
    mov dword [large_elf_image_high], 0
    mov dword [large_elf_file_end], 0
    mov dword [large_elf_sectors_read], 0
    mov dword [large_elf_load_bias], 0
    mov dword [large_elf_biased_low], 0
    mov dword [large_elf_biased_high], 0
    mov dword [large_elf_image_limit], 0
    mov dword [large_elf_last_error], 0
    mov dword [large_elf_mapped_pages], 0
    mov dword [large_elf_last_map_vaddr], 0
    mov dword [large_elf_last_map_offset], 0
    mov dword [large_elf_last_map_phys], 0
    mov dword [large_elf_last_map_flags], 0
    mov dword [large_elf_map_fail_stage], 0
    mov dword [large_elf_map_bytes_done], 0
    mov dword [large_elf_map_copy_start], 0
    mov dword [large_elf_map_copy_len], 0
    mov dword [large_elf_map_copy_done], 0
    mov dword [large_elf_map_sector_offset], 0
    mov dword [large_elf_demand_attempts], 0
    mov dword [large_elf_demand_pages], 0
    mov dword [large_elf_demand_failures], 0
    mov dword [large_elf_demand_status], 0
    mov dword [large_elf_demand_sequence], 0
    mov dword [large_elf_demand_handled_sequence], 0
    mov dword [large_elf_demand_refaults], 0
    mov dword [large_elf_demand_last_addr], 0
    mov dword [large_elf_demand_last_page], 0
    mov dword [large_elf_demand_last_segment], 0
    mov dword [large_elf_demand_last_offset], 0
    mov dword [large_elf_demand_last_copy_len], 0
    mov dword [large_elf_demand_last_eip], 0
    mov dword [large_elf_demand_last_esp], 0
    mov dword [large_elf_demand_last_eflags], 0
    mov dword [large_elf_demand_last_eax], 0
    mov dword [large_elf_demand_last_ebx], 0
    mov dword [large_elf_demand_last_ecx], 0
    mov dword [large_elf_demand_last_edx], 0
    mov dword [large_elf_demand_last_esi], 0
    mov dword [large_elf_demand_last_edi], 0
    mov dword [large_elf_demand_last_ebp], 0
    mov dword [large_elf_demand_stack_offset], 0
    mov dword [large_elf_demand_stack0], 0
    mov dword [large_elf_demand_stack1], 0
    mov dword [large_elf_demand_stack2], 0
    mov dword [large_elf_demand_stack3], 0
    mov dword [linux_syscall_after_demand_sequence], 0
    mov dword [linux_syscall_after_demand_count], 0
    mov dword [linux_syscall_after_demand_nr], 0
    mov dword [linux_syscall_after_demand_eip], 0
    mov dword [linux_mprotect_last_start], 0
    mov dword [linux_mprotect_last_end], 0
    mov dword [linux_mprotect_last_prot], 0

    mov ebx, [process_exec_size]
    cmp ebx, LARGE_ELF_PREFLIGHT_BYTES
    jbe .read_len_ready
    mov ebx, LARGE_ELF_PREFLIGHT_BYTES

.read_len_ready:
    movzx eax, word [process_exec_first_cluster]
    mov ecx, LARGE_ELF_PREFLIGHT_BYTES
    mov edi, LARGE_ELF_PREFLIGHT_ADDR
    call fat_load_file
    jc .read_fail
    mov eax, [fat_load_sectors_read]
    mov [large_elf_sectors_read], eax
    mov [process_exec_sectors_read], eax

    mov esi, LARGE_ELF_PREFLIGHT_ADDR
    cmp dword [esi], ELF_MAGIC
    jne .parse_fail
    cmp byte [esi + 4], ELFCLASS32
    jne .parse_fail
    cmp byte [esi + 5], ELFDATA2LSB
    jne .parse_fail

    movzx eax, word [esi + ELF_E_TYPE]
    mov [large_elf_type], eax
    cmp ax, ET_EXEC
    je .type_ok
    cmp ax, ET_DYN
    je .type_ok
    jmp .unsupported_type

.type_ok:
    cmp word [esi + ELF_E_MACHINE], EM_386
    jne .parse_fail
    cmp dword [esi + ELF_E_VERSION], 1
    jne .parse_fail
    cmp word [esi + ELF_E_PHENTSIZE], ELF_PHDR_SIZE
    jne .parse_fail

    mov eax, [esi + ELF_E_ENTRY]
    mov [large_elf_entry], eax
    mov eax, [esi + ELF_E_PHOFF]
    mov [large_elf_phoff], eax
    movzx ecx, word [esi + ELF_E_PHNUM]
    cmp ecx, 0
    je .parse_fail
    cmp ecx, ELF_MAX_PHDRS
    ja .parse_fail
    mov [large_elf_phnum], ecx

    mov eax, [large_elf_phoff]
    mov ebx, ecx
    shl ebx, 5
    add ebx, eax
    jc .parse_fail
    cmp ebx, [process_exec_size]
    ja .parse_fail
    cmp ebx, LARGE_ELF_PREFLIGHT_BYTES
    ja .parse_fail

    push ecx
    mov eax, [large_elf_phoff]
    add eax, LARGE_ELF_PREFLIGHT_ADDR
    jc .parse_fail_pop_ecx
    mov esi, eax
    mov edi, elf_phdr_scratch
    mov ecx, [esp]
    shl ecx, 5
    cld
    rep movsb
    pop ecx

    mov dword [user_phdr_ptr], elf_phdr_scratch
    mov [user_phdr_remaining], ecx

.phdr_loop:
    cmp dword [user_phdr_remaining], 0
    je .segments_done
    mov esi, [user_phdr_ptr]
    cmp dword [esi + ELF_PH_TYPE], PT_INTERP
    je .interp_phdr
    cmp dword [esi + ELF_PH_TYPE], PT_LOAD
    jne .next_phdr

    mov eax, [esi + ELF_PH_FILESZ]
    cmp eax, [esi + ELF_PH_MEMSZ]
    ja .parse_fail
    mov edx, eax
    test edx, edx
    jz .load_file_span_ok
    mov eax, [esi + ELF_PH_OFFSET]
    add eax, edx
    jc .parse_fail
    cmp eax, [process_exec_size]
    ja .parse_fail
    cmp eax, [large_elf_file_end]
    jbe .load_file_span_ok
    mov [large_elf_file_end], eax

.load_file_span_ok:
    mov eax, [esi + ELF_PH_VADDR]
    cmp eax, [large_elf_image_low]
    jae .image_low_ready
    mov [large_elf_image_low], eax

.image_low_ready:
    mov ebx, [esi + ELF_PH_VADDR]
    add ebx, [esi + ELF_PH_MEMSZ]
    jc .parse_fail
    cmp ebx, [large_elf_image_high]
    jbe .image_high_ready
    mov [large_elf_image_high], ebx

.image_high_ready:
    inc dword [large_elf_load_count]
    jmp .next_phdr

.interp_phdr:
    cmp dword [large_elf_interp_status], 0
    jne .parse_fail
    mov edx, [esi + ELF_PH_FILESZ]
    test edx, edx
    jz .parse_fail
    mov eax, [esi + ELF_PH_OFFSET]
    add eax, edx
    jc .parse_fail
    cmp eax, [process_exec_size]
    ja .parse_fail
    mov dword [large_elf_interp_status], 1
    cmp eax, LARGE_ELF_PREFLIGHT_BYTES
    ja .next_phdr
    cmp edx, linux_interp_ld_path_end - linux_interp_ld_path
    jne .next_phdr
    mov eax, [esi + ELF_PH_OFFSET]
    add eax, LARGE_ELF_PREFLIGHT_ADDR
    jc .parse_fail
    mov esi, eax
    mov edi, linux_interp_ld_path
    call kernel_streq
    cmp al, 1
    jne .next_phdr
    mov dword [large_elf_interp_match], 1

.next_phdr:
    add dword [user_phdr_ptr], ELF_PHDR_SIZE
    dec dword [user_phdr_remaining]
    jmp .phdr_loop

.segments_done:
    cmp dword [large_elf_load_count], 0
    je .parse_fail
    cmp dword [large_elf_image_low], 0xffffffff
    jne .metadata_ok
    mov dword [large_elf_image_low], 0

.metadata_ok:
    mov dword [large_elf_status], LARGE_ELF_STATUS_METADATA_OK
    mov dword [large_elf_load_bias], 0
    cmp dword [large_elf_type], ET_DYN
    jne .bias_ready
    mov dword [large_elf_load_bias], LINUX_LARGE_ET_DYN_BASE

.bias_ready:
    mov eax, [large_elf_image_low]
    add eax, [large_elf_load_bias]
    jc .vma_too_large
    mov [large_elf_biased_low], eax
    mov eax, [large_elf_image_high]
    add eax, [large_elf_load_bias]
    jc .vma_too_large
    mov [large_elf_biased_high], eax
    mov dword [large_elf_image_limit], LINUX_LARGE_IMAGE_LIMIT
    cmp eax, LINUX_LARGE_IMAGE_LIMIT
    ja .vma_too_large
    call process_exec_large_linux_sparse_prepare
    jmp .done

.vma_too_large:
    mov dword [large_elf_status], LARGE_ELF_STATUS_VMA_TOO_LARGE
    mov dword [process_exec_last_error], -ERRNO_ENOMEM
    mov dword [large_elf_last_error], -ERRNO_ENOMEM
    stc
    jmp .done

.parse_fail_pop_ecx:
    pop ecx

.parse_fail:
    mov dword [large_elf_status], LARGE_ELF_STATUS_PARSE_FAIL
    mov dword [process_exec_last_error], -ERRNO_ENOEXEC
    mov dword [large_elf_last_error], -ERRNO_ENOEXEC
    stc
    jmp .done

.unsupported_type:
    mov dword [large_elf_status], LARGE_ELF_STATUS_UNSUPPORTED_TYPE
    mov dword [process_exec_last_error], -ERRNO_ENOEXEC
    mov dword [large_elf_last_error], -ERRNO_ENOEXEC
    stc
    jmp .done

.read_fail:
    mov dword [large_elf_status], LARGE_ELF_STATUS_PARSE_FAIL
    mov dword [process_exec_last_error], -ERRNO_EIO
    mov dword [large_elf_last_error], -ERRNO_EIO
    stc

.done:
    popad
    ret

process_exec_large_linux_sparse_prepare:
    pushad

    mov byte [user_elf_parse_status], 0
    mov byte [user_load_segment_count], 0
    mov dword [user_entry_addr], 0
    mov dword [user_phdr_count], 0
    mov dword [user_phdr_addr], 0
    mov dword [user_interp_status], 0
    mov dword [user_interp_path_match], 0
    mov dword [user_interp_load_status], 0
    mov dword [user_interp_base], 0
    mov dword [user_program_image_end], 0
    mov dword [process_exec_entry], 0
    mov dword [large_elf_mapped_pages], 0
    mov dword [large_elf_map_fail_stage], 0
    mov dword [large_elf_map_bytes_done], 0

    mov eax, [large_elf_entry]
    add eax, [large_elf_load_bias]
    jc .map_fail
    mov [user_entry_addr], eax
    mov eax, [large_elf_phoff]
    add eax, [large_elf_load_bias]
    jc .map_fail
    mov [user_phdr_addr], eax
    mov eax, [large_elf_phnum]
    mov [user_phdr_count], eax
    mov eax, [large_elf_interp_status]
    mov [user_interp_status], eax
    mov eax, [large_elf_interp_match]
    mov [user_interp_path_match], eax

    cmp dword [user_interp_status], 1
    jne .interp_staging_reserved
    mov eax, USER_ELF_LOAD_ADDR
    mov ecx, USER_ELF_MAX_BYTES / PAGE_SIZE
    call pmm_reserve_pages

.interp_staging_reserved:
    mov dword [user_phdr_ptr], elf_phdr_scratch
    mov eax, [large_elf_phnum]
    mov [user_phdr_remaining], eax

.phdr_loop:
    cmp dword [user_phdr_remaining], 0
    je .segments_done
    mov esi, [user_phdr_ptr]
    cmp dword [esi + ELF_PH_TYPE], PT_LOAD
    jne .next_phdr

    mov eax, [esi + ELF_PH_FILESZ]
    cmp eax, [esi + ELF_PH_MEMSZ]
    ja .map_fail

    mov eax, [esi + ELF_PH_VADDR]
    add eax, [large_elf_load_bias]
    jc .map_fail
    mov ebx, eax
    and eax, 0xfffff000
    mov [large_elf_last_map_vaddr], eax
    and ebx, 0x00000fff
    mov [large_elf_map_copy_start], ebx

    mov eax, [esi + ELF_PH_OFFSET]
    mov [large_elf_last_map_offset], eax
    mov eax, [esi + ELF_PH_FLAGS]
    mov [large_elf_last_map_flags], eax

    mov ebx, PAGE_SIZE
    sub ebx, [large_elf_map_copy_start]
    mov eax, [esi + ELF_PH_FILESZ]
    cmp eax, ebx
    jbe .copy_len_ready
    mov eax, ebx

.copy_len_ready:
    mov [large_elf_map_copy_len], eax
    call process_exec_large_linux_map_file_page
    jc .map_fail_from_child
    inc dword [large_elf_mapped_pages]
    inc byte [user_load_segment_count]

.next_phdr:
    add dword [user_phdr_ptr], ELF_PHDR_SIZE
    dec dword [user_phdr_remaining]
    jmp .phdr_loop

.segments_done:
    cmp byte [user_load_segment_count], 0
    je .map_fail
    call process_exec_large_linux_premap_dynamic
    jc .map_fail_from_child
    cmp dword [user_interp_status], 1
    jne .no_interp
    cmp dword [user_interp_path_match], 1
    jne .interp_fail
    call user_interp_prepare
    jc .interp_fail
    jmp .success

.no_interp:
    mov eax, [user_entry_addr]
    mov [process_exec_entry], eax

.success:
    mov byte [user_elf_parse_status], 1
    mov dword [large_elf_status], LARGE_ELF_STATUS_SPARSE_MAPPED
    mov dword [process_exec_last_error], 0
    mov dword [large_elf_last_error], 0
    clc
    jmp .done

.interp_fail:
    mov dword [large_elf_status], LARGE_ELF_STATUS_INTERP_FAIL
    mov dword [process_exec_last_error], -ERRNO_ENOENT
    mov dword [large_elf_last_error], -ERRNO_ENOENT
    stc
    jmp .done

.map_fail:
    cmp dword [large_elf_last_error], 0
    jne .map_fail_from_child
    mov dword [large_elf_last_error], -ERRNO_EIO
    mov dword [process_exec_last_error], -ERRNO_EIO

.map_fail_from_child:
    mov dword [large_elf_status], LARGE_ELF_STATUS_MAP_FAIL
    stc

.done:
    popad
    ret

process_exec_large_linux_premap_dynamic:
    pushad

    mov dword [user_phdr_ptr], elf_phdr_scratch
    mov eax, [large_elf_phnum]
    mov [user_phdr_remaining], eax

.dynamic_loop:
    cmp dword [user_phdr_remaining], 0
    je .success
    mov esi, [user_phdr_ptr]
    cmp dword [esi + ELF_PH_TYPE], PT_DYNAMIC
    jne .next_dynamic

    mov eax, [esi + ELF_PH_VADDR]
    add eax, [large_elf_load_bias]
    jc .map_fail
    mov ebx, eax
    and eax, 0xfffff000
    mov [large_elf_last_map_vaddr], eax

    mov edi, [process_exec_target]
    cmp edi, 0
    je .map_fail
    mov ebx, [edi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .map_fail
    mov eax, [large_elf_last_map_vaddr]
    call vmm_find_process_pte
    jc .map_dynamic_page
    test edx, PTE_PRESENT
    jz .map_dynamic_page
    test edx, PTE_USER
    jnz .next_dynamic

.map_dynamic_page:
    mov edi, elf_phdr_scratch
    mov edx, [large_elf_phnum]

.load_loop:
    cmp edx, 0
    je .map_fail
    cmp dword [edi + ELF_PH_TYPE], PT_LOAD
    jne .next_load

    mov eax, [edi + ELF_PH_VADDR]
    add eax, [large_elf_load_bias]
    jc .next_load
    mov ebp, eax
    mov ebx, eax
    add ebx, [edi + ELF_PH_MEMSZ]
    jc .next_load
    mov eax, [esi + ELF_PH_VADDR]
    add eax, [large_elf_load_bias]
    jc .map_fail
    cmp eax, ebp
    jb .next_load
    cmp eax, ebx
    jb .load_found

.next_load:
    add edi, ELF_PHDR_SIZE
    dec edx
    jmp .load_loop

.load_found:
    mov eax, [edi + ELF_PH_FLAGS]
    mov [large_elf_last_map_flags], eax

    mov edx, [large_elf_last_map_vaddr]
    xor ecx, ecx
    cmp edx, ebp
    jae .copy_begin_ready
    mov ecx, ebp
    sub ecx, edx
    mov edx, ebp

.copy_begin_ready:
    mov [large_elf_map_copy_start], ecx
    mov eax, ebp
    add eax, [edi + ELF_PH_FILESZ]
    jc .map_fail
    cmp edx, eax
    jae .zero_fill_page
    mov ebx, [large_elf_last_map_vaddr]
    add ebx, PAGE_SIZE
    jc .map_fail
    cmp ebx, eax
    jbe .copy_end_ready
    mov ebx, eax

.copy_end_ready:
    mov ecx, ebx
    sub ecx, edx
    mov [large_elf_map_copy_len], ecx
    mov eax, edx
    sub eax, ebp
    add eax, [edi + ELF_PH_OFFSET]
    jc .map_fail
    mov [large_elf_last_map_offset], eax
    jmp .map_page

.zero_fill_page:
    mov dword [large_elf_map_copy_len], 0
    mov eax, [edi + ELF_PH_OFFSET]
    add eax, [edi + ELF_PH_FILESZ]
    jc .map_fail
    mov [large_elf_last_map_offset], eax

.map_page:
    call process_exec_large_linux_map_file_page
    jc .map_fail_from_child
    inc dword [large_elf_mapped_pages]

.next_dynamic:
    add dword [user_phdr_ptr], ELF_PHDR_SIZE
    dec dword [user_phdr_remaining]
    jmp .dynamic_loop

.success:
    clc
    jmp .done

.map_fail:
    cmp dword [large_elf_last_error], 0
    jne .map_fail_from_child
    mov dword [large_elf_last_error], -ERRNO_EIO
    mov dword [process_exec_last_error], -ERRNO_EIO

.map_fail_from_child:
    stc

.done:
    popad
    ret

process_exec_large_linux_map_file_page:
    pushad

    mov dword [large_elf_map_copy_done], 0
    mov dword [large_elf_map_fail_stage], 0
    call pmm_alloc_page
    test eax, eax
    jnz .phys_ready
    mov dword [large_elf_map_fail_stage], 1
    mov dword [large_elf_last_error], -ERRNO_ENOMEM
    mov dword [process_exec_last_error], -ERRNO_ENOMEM
    stc
    jmp .done

.phys_ready:
    mov [large_elf_last_map_phys], eax

    pushfd
    cli
    mov eax, FORK_COPY_DST_ALIAS
    mov ebx, [large_elf_last_map_phys]
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .alias_fail

    mov edi, FORK_COPY_DST_ALIAS
    xor eax, eax
    mov ecx, PAGE_SIZE / 4
    cld
    rep stosd

.copy_loop:
    mov eax, [large_elf_map_copy_done]
    cmp eax, [large_elf_map_copy_len]
    jae .copy_done
    mov ax, [process_exec_first_cluster]
    mov edx, [large_elf_last_map_offset]
    add edx, [large_elf_map_copy_done]
    jc .read_fail_unmap
    call fat_file_lba_for_offset
    jc .read_fail_unmap
    mov [large_elf_map_sector_offset], ebx
    mov edi, SECTOR_BUFFER_ADDR
    call block_selected_read_sector
    jc .read_fail_unmap
    inc dword [large_elf_sectors_read]
    inc dword [process_exec_sectors_read]

    mov esi, SECTOR_BUFFER_ADDR
    add esi, [large_elf_map_sector_offset]
    mov edi, FORK_COPY_DST_ALIAS
    add edi, [large_elf_map_copy_start]
    add edi, [large_elf_map_copy_done]
    mov ecx, 512
    sub ecx, [large_elf_map_sector_offset]
    mov eax, [large_elf_map_copy_len]
    sub eax, [large_elf_map_copy_done]
    cmp ecx, eax
    jbe .sector_len_ready
    mov ecx, eax

.sector_len_ready:
    mov ebx, ecx
    cld
    rep movsb
    add [large_elf_map_copy_done], ebx
    add [large_elf_map_bytes_done], ebx
    jmp .copy_loop

.copy_done:
    mov eax, FORK_COPY_DST_ALIAS
    call vmm_unmap_page
    popfd

    mov esi, [process_exec_target]
    cmp esi, 0
    je .target_fail
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .target_fail
    mov ecx, [large_elf_last_map_phys]
    and ecx, 0xfffff000
    test dword [large_elf_last_map_flags], ELF_PF_W
    jz .read_only_pte
    or ecx, PTE_USER_WRITE_FLAGS
    jmp .mprotect_check

.read_only_pte:
    or ecx, PTE_USER_READ_FLAGS

.mprotect_check:
    mov eax, [large_elf_last_map_vaddr]
    cmp eax, [linux_mprotect_last_start]
    jb .pte_ready
    cmp eax, [linux_mprotect_last_end]
    jae .pte_ready
    test dword [linux_mprotect_last_prot], MMAP_PROT_WRITE
    jz .pte_ready
    and ecx, 0xfffff000
    or ecx, PTE_USER_WRITE_FLAGS

.pte_ready:
    mov eax, [large_elf_last_map_vaddr]
    call vmm_write_process_pte
    jc .pte_fail
    clc
    jmp .done

.read_fail_unmap:
    mov dword [large_elf_map_fail_stage], 3
    mov dword [large_elf_last_error], -ERRNO_EIO
    mov dword [process_exec_last_error], -ERRNO_EIO
    mov eax, FORK_COPY_DST_ALIAS
    call vmm_unmap_page

.alias_fail:
    popfd
    cmp dword [large_elf_map_fail_stage], 0
    jne .free_fail
    mov dword [large_elf_map_fail_stage], 2
    mov dword [large_elf_last_error], -ERRNO_EIO
    mov dword [process_exec_last_error], -ERRNO_EIO
    jmp .free_fail

.target_fail:
    mov dword [large_elf_map_fail_stage], 5
    mov dword [large_elf_last_error], -ERRNO_EINVAL
    mov dword [process_exec_last_error], -ERRNO_EINVAL
    jmp .free_fail

.pte_fail:
    mov dword [large_elf_map_fail_stage], 4
    mov dword [large_elf_last_error], -ERRNO_ENOMEM
    mov dword [process_exec_last_error], -ERRNO_ENOMEM

.free_fail:
    mov eax, [large_elf_last_map_phys]
    call pmm_free_page
    stc

.done:
    popad
    ret

large_elf_demand_page_fault:
    pushad

    cmp dword [fault_vector], 14
    jne .reject
    cmp dword [large_elf_status], LARGE_ELF_STATUS_SPARSE_MAPPED
    jne .reject
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .reject
    cmp esi, process_kernel
    je .reject
    cmp dword [esi + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .reject
    test dword [fault_error], 1
    jz .fault_demandable
    mov eax, [fault_cr2]
    mov ebx, [esi + PROC_PAGE_DIR]
    call vmm_find_process_pte
    jc .reject
    test edx, PTE_PRESENT
    jz .reject
    test edx, PTE_USER
    jnz .reject

.fault_demandable:
    mov [process_exec_target], esi

    inc dword [large_elf_demand_attempts]
    inc dword [large_elf_demand_sequence]
    mov dword [large_elf_demand_status], 1
    mov eax, [fault_cr2]
    cmp eax, [large_elf_demand_last_addr]
    je .same_fault_addr
    mov dword [large_elf_demand_refaults], 0
    jmp .fault_addr_ready

.same_fault_addr:
    inc dword [large_elf_demand_refaults]

.fault_addr_ready:
    mov [large_elf_demand_last_addr], eax
    and eax, 0xfffff000
    mov [large_elf_demand_last_page], eax
    mov dword [large_elf_demand_last_segment], 0
    mov dword [large_elf_demand_last_offset], 0
    mov dword [large_elf_demand_last_copy_len], 0
    mov eax, [fault_eip]
    mov [large_elf_demand_last_eip], eax
    mov eax, [fault_esp]
    mov [large_elf_demand_last_esp], eax
    mov eax, [fault_eflags]
    mov [large_elf_demand_last_eflags], eax
    mov eax, [fault_eax]
    mov [large_elf_demand_last_eax], eax
    mov eax, [fault_ebx]
    mov [large_elf_demand_last_ebx], eax
    mov eax, [fault_ecx]
    mov [large_elf_demand_last_ecx], eax
    mov eax, [fault_edx]
    mov [large_elf_demand_last_edx], eax
    mov eax, [fault_esi]
    mov [large_elf_demand_last_esi], eax
    mov eax, [fault_edi]
    mov [large_elf_demand_last_edi], eax
    mov eax, [fault_ebp]
    mov [large_elf_demand_last_ebp], eax
    call large_elf_capture_demand_stack

    mov dword [user_phdr_ptr], elf_phdr_scratch
    mov ecx, [large_elf_phnum]

.scan_next:
    cmp ecx, 0
    je .not_found
    mov esi, [user_phdr_ptr]
    cmp dword [esi + ELF_PH_TYPE], PT_LOAD
    jne .advance

    mov eax, [esi + ELF_PH_VADDR]
    add eax, [large_elf_load_bias]
    jc .advance
    mov [large_elf_demand_last_segment], eax
    mov ebx, eax
    add ebx, [esi + ELF_PH_MEMSZ]
    jc .advance
    mov edx, [fault_cr2]
    cmp edx, eax
    jb .advance
    cmp edx, ebx
    jb .found

.advance:
    add dword [user_phdr_ptr], ELF_PHDR_SIZE
    dec ecx
    jmp .scan_next

.found:
    mov eax, [large_elf_demand_last_page]
    mov [large_elf_last_map_vaddr], eax
    mov eax, [esi + ELF_PH_FLAGS]
    mov [large_elf_last_map_flags], eax

    mov edx, [large_elf_demand_last_page]
    xor ecx, ecx
    mov eax, [large_elf_demand_last_segment]
    cmp edx, eax
    jae .copy_begin_ready
    mov ecx, eax
    sub ecx, edx
    mov edx, eax

.copy_begin_ready:
    mov [large_elf_map_copy_start], ecx
    mov eax, [large_elf_demand_last_segment]
    add eax, [esi + ELF_PH_FILESZ]
    jc .map_fail
    cmp edx, eax
    jae .zero_fill_page
    mov ebx, [large_elf_demand_last_page]
    add ebx, PAGE_SIZE
    jc .map_fail
    cmp ebx, eax
    jbe .copy_end_ready
    mov ebx, eax

.copy_end_ready:
    mov ecx, ebx
    sub ecx, edx
    mov [large_elf_map_copy_len], ecx
    mov [large_elf_demand_last_copy_len], ecx
    mov eax, edx
    sub eax, [large_elf_demand_last_segment]
    add eax, [esi + ELF_PH_OFFSET]
    jc .map_fail
    mov [large_elf_last_map_offset], eax
    mov [large_elf_demand_last_offset], eax
    jmp .map_page

.zero_fill_page:
    mov dword [large_elf_map_copy_len], 0
    mov dword [large_elf_demand_last_copy_len], 0
    mov eax, [esi + ELF_PH_OFFSET]
    add eax, [esi + ELF_PH_FILESZ]
    jc .map_fail
    mov [large_elf_last_map_offset], eax
    mov [large_elf_demand_last_offset], eax

.map_page:
    call process_exec_large_linux_map_file_page
    jc .map_fail_from_child
    inc dword [large_elf_mapped_pages]
    inc dword [large_elf_demand_pages]
    mov eax, [large_elf_demand_last_page]
    invlpg [eax]
    mov dword [large_elf_demand_status], 2
    mov eax, [large_elf_demand_sequence]
    mov [large_elf_demand_handled_sequence], eax
    mov dword [linux_syscall_after_demand_sequence], 0
    mov dword [linux_syscall_after_demand_count], 0
    mov dword [linux_syscall_after_demand_nr], 0
    mov dword [linux_syscall_after_demand_eip], 0
    call linux_m1_smoke_maybe_write_runtime_status
    clc
    jmp .done

.not_found:
    mov dword [large_elf_demand_status], 3
    inc dword [large_elf_demand_failures]
    stc
    jmp .done

.map_fail:
    cmp dword [large_elf_last_error], 0
    jne .map_fail_from_child
    mov dword [large_elf_last_error], -ERRNO_EIO

.map_fail_from_child:
    mov dword [large_elf_demand_status], 4
    inc dword [large_elf_demand_failures]
    stc
    jmp .done

.reject:
    stc

.done:
    popad
    ret

large_elf_capture_demand_stack:
    pushad

    mov dword [large_elf_demand_stack_offset], 0
    mov dword [large_elf_demand_stack0], 0
    mov dword [large_elf_demand_stack1], 0
    mov dword [large_elf_demand_stack2], 0
    mov dword [large_elf_demand_stack3], 0

    mov esi, [current_process_ptr]
    cmp esi, 0
    je .done
    cmp esi, process_kernel
    je .done
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .done

    mov eax, [fault_esp]
    call vmm_find_process_pte
    jc .done
    test edx, PTE_PRESENT
    jz .done
    test edx, PTE_USER
    jz .done

    mov eax, [fault_esp]
    and eax, 0x00000fff
    cmp eax, PAGE_SIZE - 16
    ja .done
    mov [large_elf_demand_stack_offset], eax

    mov ebx, edx
    and ebx, 0xfffff000
    pushfd
    cli
    mov eax, FORK_COPY_SRC_ALIAS
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .alias_fail

    mov esi, FORK_COPY_SRC_ALIAS
    add esi, [large_elf_demand_stack_offset]
    mov eax, [esi]
    mov [large_elf_demand_stack0], eax
    mov eax, [esi + 4]
    mov [large_elf_demand_stack1], eax
    mov eax, [esi + 8]
    mov [large_elf_demand_stack2], eax
    mov eax, [esi + 12]
    mov [large_elf_demand_stack3], eax

    mov eax, FORK_COPY_SRC_ALIAS
    call vmm_unmap_page
    popfd
    jmp .done

.alias_fail:
    popfd

.done:
    popad
    ret

process_exec_prepare_elf_image:
    cmp dword [process_exec_target], process_payload
    je .prepare_payload
    mov eax, [process_exec_target]
    call process_is_user_exec_target
    jnc .prepare_user_probe
    jmp .fail

.prepare_payload:
    xor edx, edx
    mov eax, payload_exec_parse_status
    call payload_exec_store_target
    call payload_elf_prepare
    jc .fail
    mov eax, [payload_entry_addr]
    mov edx, eax
    mov eax, payload_exec_entry
    call payload_exec_store_target
    mov eax, [payload_segment_memsz]
    mov edx, eax
    mov eax, payload_exec_segment_memsz
    call payload_exec_store_target
    mov eax, [payload_segment_end]
    mov edx, eax
    mov eax, payload_exec_segment_end
    call payload_exec_store_target
    mov edx, 1
    mov eax, payload_exec_parse_status
    call payload_exec_store_target

.prepare_payload_entry:
    mov eax, [payload_entry_addr]
    mov [process_exec_entry], eax
    clc
    ret

.prepare_user_probe:
    call user_elf_prepare
    jc .fail
    cmp dword [user_interp_status], 1
    jne .prepare_user_entry
    cmp dword [user_interp_path_match], 1
    jne .fail
    call user_interp_prepare
    jc .fail
    clc
    ret

.prepare_user_entry:
    mov eax, [user_entry_addr]
    mov [process_exec_entry], eax
    clc
    ret

.fail:
    cmp dword [process_exec_target], process_payload
    jne .fail_status_ready
    mov edx, 2
    mov eax, payload_exec_parse_status
    call payload_exec_store_target

.fail_status_ready:
    stc
    ret

process_exec_handoff_current:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov esi, [process_exec_target]
    cmp esi, 0
    je .einval
    mov edi, [current_process_ptr]
    cmp edi, 0
    je .einval
    cmp edi, esi
    je .eacces
    cmp dword [process_exec_entry], 0
    je .eio

    cmp esi, process_payload
    je .reset_payload_target
    mov eax, esi
    call process_is_user_exec_target
    jnc .reset_user_probe_target
    jmp .einval

.reset_payload_target:
    call process_reset_payload
    mov eax, [process_exec_target_kind]
    cmp eax, USER_KIND_NONE
    jne .reset_large_kind_ready
    mov eax, USER_KIND_GENERIC

.reset_large_kind_ready:
    mov [esi + PROC_KIND], eax
    mov eax, [process_exec_entry]
    mov [esi + PROC_ENTRY], eax
    cmp dword [process_exec_target_kind], USER_KIND_PAYLOAD_PRIMARY
    je .reset_primary_payload_status
    cmp dword [process_exec_target_kind], USER_KIND_PAYLOAD_SECONDARY
    je .reset_secondary_payload_status
    mov eax, USER_KIND_GENERIC
    call payload_lifecycle_start_kind
    call clear_fault_record
    mov eax, USER_KIND_GENERIC
    call user_io_reset_kind
    jmp .seed_context

.reset_primary_payload_status:
    mov eax, USER_KIND_PAYLOAD_PRIMARY
    call payload_lifecycle_start_kind
    call clear_fault_record
    mov eax, USER_KIND_PAYLOAD_PRIMARY
    call user_io_reset_kind
    mov dword [payload_primary_stdout_log_len], 0
    mov byte [payload_primary_stdout_log_buffer], 0
    jmp .seed_context

.reset_secondary_payload_status:
    mov eax, USER_KIND_PAYLOAD_SECONDARY
    call payload_lifecycle_start_kind
    mov eax, USER_KIND_PAYLOAD_SECONDARY
    call payload_telemetry_reset_kind
    call clear_fault_record
    mov eax, USER_KIND_PAYLOAD_SECONDARY
    call user_io_reset_kind
    mov dword [payload_secondary_package_magic_seen], 0
    mov dword [payload_secondary_frame_report_count], 0
    mov dword [payload_secondary_frame_count], 0
    mov dword [payload_secondary_server_active], 0
    mov dword [payload_secondary_gameplay_status], 0
    mov dword [payload_secondary_input_events], 0
    mov dword [payload_secondary_input_buttons], 0
    mov dword [payload_secondary_audio_writes], 0
    mov dword [payload_secondary_audio_handle], 0
    jmp .seed_context

.reset_user_probe_target:
    call process_reset_user_exec_target
    mov eax, [process_exec_entry]
    mov [esi + PROC_ENTRY], eax
    cmp esi, process_user_probe
    jne .seed_context
    mov byte [user_probe_status], 0
    mov byte [user_fault_expected], 0
    mov byte [user_fault_status], 0
    mov dword [user_probe_magic_seen], 0
    mov dword [user_probe_flags_seen], 0
    mov byte [abi_probe_status], 0
    mov byte [abi_probe_exec_status], 0
    mov dword [abi_probe_magic_seen], 0
    mov dword [abi_probe_flags_seen], 0
    mov dword [abi_probe_exec_pid], 0xffffffff
    mov dword [abi_probe_exec_parent_pid], 0xffffffff
    mov dword [abi_probe_exec_entry], 0
    mov dword [abi_probe_exec_argc], 0
    mov dword [abi_probe_exec_argv_source], 0
    mov dword [user_fault_addr], 0
    mov dword [user_fault_recovery], 0

.seed_context:
    mov eax, [edi + PROC_KIND]
    mov [process_exec_last_caller_kind], eax
    mov eax, [esi + PROC_KIND]
    mov [process_exec_last_target_kind], eax
    mov eax, [edi + PROC_PID]
    mov edx, [esi + PROC_PID]
    call fd_exec_handoff
    call input_reset_queue
    call keyboard_reset_queue
    call mouse_reset_queue
    call process_seed_initial_user_context
    call process_exec_restore_target_personality
    cmp esi, process_payload
    jne .activate_target
    call scheduler_prepare_live_preempt_probe

.activate_target:
    mov eax, [edi + PROC_PID]
    mov [esi + PROC_PARENT_PID], eax
    call process_activate
    call process_exec_seed_argv_stack
    jc .eio_after_activate
    call irq_unmask_timer_keyboard

    mov eax, [edi + PROC_PID]
    mov [sys_exec_last_caller_pid], eax
    mov eax, [esi + PROC_PARENT_PID]
    mov [sys_exec_last_parent_pid], eax
    mov eax, [esi + PROC_PID]
    mov [sys_exec_last_target_pid], eax
    mov eax, [esi + PROC_ENTRY]
    mov [sys_exec_last_target_entry], eax
    mov eax, [esi + PROC_SAVED_ESP]
    mov [sys_exec_last_target_stack], eax
    call process_record_abi_exec_success
    inc dword [esi + PROC_EXEC_COUNT]
    call process_exec_patch_syscall_frame
    jc .eio_after_activate
    push esi
    mov esi, edi
    call process_retire_exec_slot
    pop esi

    mov eax, [esi + PROC_PID]
    mov [scheduler_next_pid], eax
    mov [scheduler_next_process_ptr], esi
    inc dword [sys_exec_scheduled]
    inc dword [sys_exec_handoffs]
    clc
    jmp .done

.eacces:
    mov dword [process_exec_last_error], -ERRNO_EACCES
    stc
    jmp .done

.einval:
    mov dword [process_exec_last_error], -ERRNO_EINVAL
    stc
    jmp .done

.eio_after_activate:
    push esi
    mov esi, edi
    call process_activate
    pop esi
    call process_retire_exec_slot
    jmp .eio

.eio:
    mov dword [process_exec_last_error], -ERRNO_EIO
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

process_exec_restore_target_personality:
    push eax
    cmp esi, 0
    je .done
    mov eax, [process_exec_target_personality]
    mov [esi + PROC_PERSONALITY], eax

.done:
    pop eax
    ret

process_exec_seed_argv_stack:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov edx, esi
    cmp dword [sys_exec_argc], 0
    je .fail
    cmp dword [sys_exec_argc], SYS_EXEC_ARG_MAX
    ja .fail
    cmp dword [sys_exec_envc], SYS_EXEC_ENV_MAX
    ja .fail

    mov eax, [edx + PROC_STACK_BOTTOM]
    add eax, PAGE_SIZE
    jc .fail
    cmp eax, [edx + PROC_STACK_TOP]
    ja .fail
    mov [sys_exec_stack_low], eax
    mov edi, eax
    mov ecx, [edx + PROC_STACK_TOP]
    sub ecx, edi
    jc .fail
    shr ecx, 2
    xor eax, eax
    cld
    rep stosd

    mov eax, [edx + PROC_STACK_TOP]
    mov [sys_exec_stack_cursor], eax
    mov ecx, [sys_exec_argc]

.copy_arg_string_loop:
    cmp ecx, 0
    je .arg_strings_done
    dec ecx
    mov esi, [sys_exec_arg_target_ptrs]
    mov esi, [esi + ecx * 4]
    cmp esi, 0
    je .fail
    xor ebx, ebx

.measure_arg_string:
    cmp ebx, SYS_EXEC_ARG_STR_MAX
    jae .fail
    cmp byte [esi + ebx], 0
    je .arg_string_measured
    inc ebx
    jmp .measure_arg_string

.arg_string_measured:
    inc ebx
    mov eax, [sys_exec_stack_cursor]
    sub eax, ebx
    jc .fail
    and eax, 0xfffffffc
    cmp eax, [sys_exec_stack_low]
    jb .fail
    mov [sys_exec_stack_cursor], eax
    mov edi, eax
    push ecx
    mov ecx, ebx
    cld
    rep movsb
    pop ecx
    mov edi, [sys_exec_arg_target_ptrs]
    mov [edi + ecx * 4], eax
    jmp .copy_arg_string_loop

.arg_strings_done:
    mov ecx, [sys_exec_envc]

.copy_env_string_loop:
    cmp ecx, 0
    je .strings_done
    dec ecx
    mov esi, [sys_exec_env_target_ptrs]
    mov esi, [esi + ecx * 4]
    cmp esi, 0
    je .fail
    xor ebx, ebx

.measure_env_string:
    cmp ebx, SYS_EXEC_ENV_STR_MAX
    jae .fail
    cmp byte [esi + ebx], 0
    je .env_string_measured
    inc ebx
    jmp .measure_env_string

.env_string_measured:
    inc ebx
    mov eax, [sys_exec_stack_cursor]
    sub eax, ebx
    jc .fail
    and eax, 0xfffffffc
    cmp eax, [sys_exec_stack_low]
    jb .fail
    mov [sys_exec_stack_cursor], eax
    mov edi, eax
    push ecx
    mov ecx, ebx
    cld
    rep movsb
    pop ecx
    mov edi, [sys_exec_env_target_ptrs]
    mov [edi + ecx * 4], eax
    jmp .copy_env_string_loop

.strings_done:
    mov ecx, [sys_exec_argc]
    mov ebx, ecx
    shl ebx, 2
    mov eax, [sys_exec_envc]
    shl eax, 2
    add ebx, eax
    add ebx, SYS_EXEC_ARG_FRAME_BASE_BYTES
    cmp dword [edx + PROC_PERSONALITY], PERSONALITY_LINUX
    je .linux_frame_size
    add ebx, SYS_EXEC_AUXV_BYTES
    jc .fail
    jmp .frame_size_ready

.linux_frame_size:
    add ebx, SYS_EXEC_LINUX_AUXV_BYTES + SYS_EXEC_LINUX_RANDOM_BYTES
    jc .fail

.frame_size_ready:
    mov eax, [sys_exec_stack_cursor]
    sub eax, ebx
    jc .fail
    and eax, 0xfffffff0
    cmp eax, [sys_exec_stack_low]
    jb .fail
    mov [sys_exec_user_stack_ptr], eax
    mov edi, eax
    mov [edi], ecx
    lea ebx, [edi + 4]
    xor esi, esi

.copy_argv_ptr_loop:
    cmp esi, ecx
    jae .argv_ptrs_done
    mov edi, [sys_exec_arg_target_ptrs]
    mov eax, [edi + esi * 4]
    mov [ebx + esi * 4], eax
    inc esi
    jmp .copy_argv_ptr_loop

.argv_ptrs_done:
    mov dword [ebx + ecx * 4], 0
    lea edi, [ebx + ecx * 4 + 4]
    mov eax, edi
    mov [sys_exec_last_envp], eax
    mov [edx + PROC_ENVP], eax
    mov ecx, [sys_exec_envc]
    xor esi, esi

.copy_env_ptr_loop:
    cmp esi, ecx
    jae .env_ptrs_done
    push ebx
    mov ebx, [sys_exec_env_target_ptrs]
    mov eax, [ebx + esi * 4]
    pop ebx
    mov [edi + esi * 4], eax
    inc esi
    jmp .copy_env_ptr_loop

.env_ptrs_done:
    mov dword [edi + ecx * 4], 0
    mov eax, [edi]
    mov [sys_exec_last_envp0], eax
    lea eax, [edi + ecx * 4 + 4]
    mov [sys_exec_last_auxv], eax
    mov dword [sys_exec_last_stack_abi], SYS_EXEC_STACK_ABI_VERSION
    mov dword [sys_exec_last_stack_align], SYS_EXEC_STACK_ALIGN
    cmp dword [edx + PROC_PERSONALITY], PERSONALITY_LINUX
    je .write_linux_auxv

.write_native_auxv:
    mov dword [sys_exec_last_auxv_pairs], SYS_EXEC_AUXV_PAIR_COUNT
    mov dword [eax], SYS_EXEC_AUX_AT_PAGESZ
    mov dword [eax + 4], PAGE_SIZE
    mov dword [eax + 8], SYS_EXEC_AUX_AT_ENTRY
    mov esi, [edx + PROC_ENTRY]
    mov [eax + 12], esi
    mov dword [eax + 16], SYS_EXEC_AUX_AT_NULL
    mov dword [eax + 20], 0
    mov dword [sys_exec_last_aux_phdr], 0
    mov dword [sys_exec_last_aux_phnum], 0
    mov dword [sys_exec_last_aux_base], 0
    mov [sys_exec_last_aux_entry], esi
    jmp .auxv_done

.write_linux_auxv:
    mov dword [sys_exec_last_auxv_pairs], SYS_EXEC_LINUX_AUXV_PAIR_COUNT
    mov edi, eax
    mov esi, linux_auxv_type_table
    mov ecx, SYS_EXEC_LINUX_AUXV_PAIR_COUNT
    cld
    xor eax, eax
.linux_auxv_type_loop:
    lodsb
    stosd
    xor eax, eax
    stosd
    loop .linux_auxv_type_loop

    mov eax, [sys_exec_last_auxv]
    mov dword [eax + SYS_EXEC_LINUX_AUX_PHENT_VALUE_OFF], ELF_PHDR_SIZE
    mov dword [eax + SYS_EXEC_LINUX_AUX_PAGESZ_VALUE_OFF], PAGE_SIZE
    mov dword [eax + SYS_EXEC_LINUX_AUX_HWCAP_VALUE_OFF], SYS_EXEC_LINUX_HWCAP_I386_FPU
    mov dword [eax + SYS_EXEC_LINUX_AUX_CLKTCK_VALUE_OFF], SYS_EXEC_LINUX_CLKTCK
    mov esi, eax
    add esi, SYS_EXEC_LINUX_AUXV_BYTES
    mov [eax + SYS_EXEC_LINUX_AUX_RANDOM_VALUE_OFF], esi
    cmp edx, process_payload
    je .write_linux_payload_auxv_values
    mov esi, [user_phdr_addr]
    mov [eax + SYS_EXEC_LINUX_AUX_PHDR_VALUE_OFF], esi
    mov [sys_exec_last_aux_phdr], esi
    mov esi, [user_phdr_count]
    mov [eax + SYS_EXEC_LINUX_AUX_PHNUM_VALUE_OFF], esi
    mov [sys_exec_last_aux_phnum], esi
    mov esi, [user_interp_base]
    mov [eax + SYS_EXEC_LINUX_AUX_BASE_VALUE_OFF], esi
    mov [sys_exec_last_aux_base], esi
    mov esi, [user_entry_addr]
    mov [eax + SYS_EXEC_LINUX_AUX_ENTRY_VALUE_OFF], esi
    mov [sys_exec_last_aux_entry], esi
    jmp .write_linux_execfn

.write_linux_payload_auxv_values:
    mov esi, [payload_phdr_addr]
    mov [eax + SYS_EXEC_LINUX_AUX_PHDR_VALUE_OFF], esi
    mov [sys_exec_last_aux_phdr], esi
    mov esi, [payload_phdr_count]
    mov [eax + SYS_EXEC_LINUX_AUX_PHNUM_VALUE_OFF], esi
    mov [sys_exec_last_aux_phnum], esi
    mov dword [eax + SYS_EXEC_LINUX_AUX_BASE_VALUE_OFF], 0
    mov dword [sys_exec_last_aux_base], 0
    mov esi, [payload_entry_addr]
    mov [eax + SYS_EXEC_LINUX_AUX_ENTRY_VALUE_OFF], esi
    mov [sys_exec_last_aux_entry], esi

.write_linux_execfn:
    mov esi, [sys_exec_arg_target_ptrs]
    mov esi, [esi]
    mov [eax + SYS_EXEC_LINUX_AUX_EXECFN_VALUE_OFF], esi

    mov edi, [eax + SYS_EXEC_LINUX_AUX_RANDOM_VALUE_OFF]
    push eax
    mov eax, [timer_ticks]
    xor eax, [clock_milliseconds]
    xor eax, 0x56584231
    stosd
    xor eax, [current_pid]
    stosd
    xor eax, [process_exec_size]
    stosd
    xor eax, [sys_exec_user_stack_ptr]
    stosd

    pop eax

.auxv_done:
    mov eax, [sys_exec_argc]
    mov [sys_exec_last_argc], eax
    mov [edx + PROC_ARGC], eax
    mov eax, ebx
    mov [sys_exec_last_argv], eax
    mov [edx + PROC_ARGV], eax
    mov eax, [sys_exec_envc]
    mov [sys_exec_last_envc], eax
    mov eax, [sys_exec_arg_target_ptrs]
    mov eax, [eax]
    mov [sys_exec_argv0_ptr], eax
    mov [sys_exec_last_argv0], eax
    mov [edx + PROC_ARGV0], eax
    mov eax, [sys_exec_user_stack_ptr]
    mov [edx + PROC_SAVED_ESP], eax
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

process_exec_patch_syscall_frame:
    push eax
    push ebx

    mov ebx, [sys_exec_frame_ptr]
    cmp ebx, 0
    je .fail
    mov dword [ebx + SYSCALL_FRAME_EBP], 0
    mov dword [ebx + SYSCALL_FRAME_EDI], 0
    mov dword [ebx + SYSCALL_FRAME_ESI], 0
    mov dword [ebx + SYSCALL_FRAME_EDX], 0
    mov dword [ebx + SYSCALL_FRAME_ECX], 0
    mov dword [ebx + SYSCALL_FRAME_EBX], 0
    mov eax, [esi + PROC_SAVED_EIP]
    mov [ebx + SYSCALL_FRAME_EIP], eax
    mov eax, [esi + PROC_SAVED_CS]
    mov [ebx + SYSCALL_FRAME_CS], eax
    mov eax, [esi + PROC_SAVED_EFLAGS]
    mov [ebx + SYSCALL_FRAME_EFLAGS], eax
    mov eax, [esi + PROC_SAVED_ESP]
    mov [ebx + SYSCALL_FRAME_ESP], eax
    mov eax, [esi + PROC_SAVED_SS]
    mov [ebx + SYSCALL_FRAME_SS], eax
    clc
    jmp .done

.fail:
    stc

.done:
    pop ebx
    pop eax
    ret

process_record_abi_exec_success:
    push eax
    push ebx
    push esi
    push edi

    mov esi, [process_exec_path_ptr]
    cmp esi, 0
    je .done
    mov edi, exec_path_abi_probe
    call kernel_streq
    cmp al, 1
    jne .done
    mov ebx, [process_exec_target]
    cmp ebx, 0
    je .done
    mov byte [abi_probe_exec_status], 1
    mov eax, [ebx + PROC_PID]
    mov [abi_probe_exec_pid], eax
    mov eax, [ebx + PROC_PARENT_PID]
    mov [abi_probe_exec_parent_pid], eax
    mov eax, [ebx + PROC_ENTRY]
    mov [abi_probe_exec_entry], eax
    mov eax, [sys_exec_last_argc]
    mov [abi_probe_exec_argc], eax
    mov eax, [sys_exec_last_argv_source]
    mov [abi_probe_exec_argv_source], eax

.done:
    pop edi
    pop esi
    pop ebx
    pop eax
    ret

kernel_streq:
    push esi
    push edi

.next:
    mov al, [esi]
    cmp al, [edi]
    jne .no
    test al, al
    jz .yes
    inc esi
    inc edi
    jmp .next

.yes:
    mov al, 1
    jmp .done

.no:
    xor al, al

.done:
    pop edi
    pop esi
    ret

user_probe_run:
    mov byte [boot_user_exec_status], 0
    mov dword [boot_user_exec_pid], 0xffffffff
    mov dword [boot_user_exec_entry], 0
    mov byte [user_probe_status], 0
