    mov word [user_probe_cs], 0
    mov word [user_probe_ss], 0

    mov esi, exec_path_boot_user
    mov [boot_user_exec_path_ptr], esi
    xor edi, edi
    call process_exec_path
    jnc .boot_exec_ready

.use_probe_boot_path:
    mov esi, exec_path_user_probe
    mov [boot_user_exec_path_ptr], esi
    xor edi, edi
    call process_exec_path
    jc .fail

.boot_exec_ready:
    mov byte [boot_user_exec_status], 1
    mov eax, [process_user_probe + PROC_PID]
    mov [boot_user_exec_pid], eax
    mov eax, [process_exec_entry]
    mov [boot_user_exec_entry], eax
    mov dword [process_user_probe + PROC_PARENT_PID], 0
    mov esi, process_user_probe
    call process_activate
    call process_seed_wait_reap_probe_child
    mov eax, [process_user_probe + PROC_ENTRY]
    mov [current_user_entry], eax

    mov edi, USER_STACK_BOTTOM
    xor eax, eax
    mov ecx, PAGE_SIZE / 4
    rep stosd
    mov esi, [boot_user_exec_path_ptr]
    cmp esi, 0
    jne .stage_boot_arg
    mov esi, exec_path_user_probe

.stage_boot_arg:
    call sys_exec_stage_kernel_arg
    jc .fail
    mov esi, process_user_probe
    call process_seed_initial_user_context
    call process_activate
    call process_exec_seed_argv_stack
    jc .fail
    inc dword [process_user_probe + PROC_EXEC_COUNT]

    cli
    mov ax, USER_DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax

    push dword [process_user_probe + PROC_SAVED_SS]
    push dword [process_user_probe + PROC_SAVED_ESP]
    push dword 0x00000202
    push dword [process_user_probe + PROC_SAVED_CS]
    push dword [process_user_probe + PROC_SAVED_EIP]
    xor eax, eax
    xor ebx, ebx
    xor ecx, ecx
    xor edx, edx
    xor esi, esi
    xor edi, edi
    xor ebp, ebp
    iretd

.fail:
    mov byte [boot_user_exec_status], 2
    mov byte [user_probe_status], 2
    cmp dword [current_process_ptr], process_user_probe
    jne .fail_done
    call process_mark_current_faulted

.fail_done:
    ret

