    cmp byte [user_elf_status], 1
    jne .fail
    cmp dword [user_elf_size], 52
    jb .fail

    mov esi, USER_ELF_LOAD_ADDR
    cmp dword [esi], ELF_MAGIC
    jne .fail
    cmp byte [esi + 4], ELFCLASS32
    jne .fail
    cmp byte [esi + 5], ELFDATA2LSB
    jne .fail
    cmp word [esi + 16], ET_EXEC
    jne .fail
    cmp word [esi + 18], EM_386
    jne .fail
    cmp dword [esi + 20], 1
    jne .fail
