; linux_syscall_unimpl: default handler for unimplemented Linux syscalls.
; Records the number for guest-status proof and returns -ENOSYS in EAX
; (vibe-os negative-errno convention).
linux_syscall_unimpl:
    mov [linux_last_unimpl_nr], eax
    mov eax, -LINUX_ENOSYS
    ret

linux_syscall_note_enter:
    pushad
    inc dword [linux_syscall_count]
    mov eax, [current_syscall_number]
    mov [linux_sys_last_nr], eax
    mov eax, [syscall_entry_eip_last]
    mov [linux_sys_last_eip], eax
    mov [linux_sys_last_arg0], ebx
    mov [linux_sys_last_arg1], ecx
    mov [linux_sys_last_arg2], edx
    mov [linux_sys_last_arg3], esi
    mov [linux_sys_last_arg4], edi
    mov [linux_sys_last_arg5], ebp
    cmp dword [large_elf_demand_handled_sequence], 0
    je .done
    inc dword [linux_syscall_after_demand_count]
    cmp dword [linux_syscall_after_demand_sequence], 0
    jne .done
    mov eax, [linux_syscall_count]
    mov [linux_syscall_after_demand_sequence], eax
    mov eax, [current_syscall_number]
    mov [linux_syscall_after_demand_nr], eax
    mov eax, [syscall_entry_eip_last]
    mov [linux_syscall_after_demand_eip], eax

.done:
    popad
    ret

linux_syscall_note_return:
    pushfd
    push ebx
    push ecx
    push edx
    push esi
    push edi
    mov [linux_sys_last_ret], eax
    mov ebx, [current_syscall_number]
    cmp ebx, [linux_path_last_nr]
    jne .check_error
    mov [linux_path_last_ret], eax

.check_error:
    cmp eax, 0xfffff000
    jbe .done
    inc dword [linux_sys_error_count]
    mov [linux_sys_last_error_nr], ebx
    mov [linux_sys_last_error_ret], eax
    mov ecx, [linux_sys_last_arg0]
    mov [linux_sys_last_error_arg0], ecx
    mov ecx, [linux_sys_last_arg1]
    mov [linux_sys_last_error_arg1], ecx
    mov ecx, [linux_sys_last_arg2]
    mov [linux_sys_last_error_arg2], ecx
    mov ecx, [linux_sys_last_arg3]
    mov [linux_sys_last_error_arg3], ecx
    cmp ebx, [linux_path_last_nr]
    jne .done
    mov [linux_error_path_nr], ebx
    mov edx, [linux_sys_last_error_ret]
    mov [linux_error_path_ret], edx
    mov edx, [linux_path_last_ptr]
    mov [linux_error_path_ptr], edx
    mov edx, [linux_path_last_valid]
    mov [linux_error_path_valid], edx
    mov esi, linux_path_last_bytes
    mov edi, linux_error_path_bytes
    mov ecx, LINUX_PATH_SNAPSHOT_BYTES / 4
    cld
    rep movsd

.done:
    call linux_m1_smoke_maybe_write_runtime_status
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    popfd
    ret

linux_m1_smoke_maybe_write_runtime_status:
%ifdef LINUX_M1_SMOKE
    pushfd
    pushad
    cmp dword [linux_m1_smoke_status], 1
    jne .restore
    cmp dword [linux_m1_smoke_runtime_status_writes], LINUX_M1_STATUS_WRITE_LIMIT
    jae .restore

    mov eax, [linux_last_unimpl_nr]
    test eax, eax
    jz .check_demand
    cmp eax, [linux_m1_smoke_status_last_unimpl_nr]
    jne .write

.check_demand:
    mov eax, [large_elf_demand_sequence]
    cmp eax, [linux_m1_smoke_status_last_demand_sequence]
    je .check_syscall
    mov edx, eax
    and edx, LINUX_M1_STATUS_DEMAND_STRIDE - 1
    jz .write
    cmp dword [large_elf_demand_failures], 0
    jne .write

.check_syscall:
    mov eax, [linux_syscall_count]
    cmp eax, [linux_m1_smoke_status_last_syscall_count]
    je .restore
    mov edx, eax
    and edx, LINUX_M1_STATUS_SYSCALL_STRIDE - 1
    jnz .restore

.write:
    mov eax, [linux_syscall_count]
    mov [linux_m1_smoke_status_last_syscall_count], eax
    mov eax, [large_elf_demand_sequence]
    mov [linux_m1_smoke_status_last_demand_sequence], eax
    mov eax, [linux_last_unimpl_nr]
    mov [linux_m1_smoke_status_last_unimpl_nr], eax
    inc dword [linux_m1_smoke_runtime_status_writes]
    call write_smoke_status
.restore:
    popad
    popfd
%endif
    ret

linux_record_path_arg:
    pushad
    mov dword [linux_relative_synthetic_dir_arg], 0
    mov [linux_path_last_ptr], ebx
    mov eax, [current_syscall_number]
    mov [linux_path_last_nr], eax
    mov dword [linux_path_last_ret], 0
    mov dword [linux_path_last_valid], 0
    mov edi, linux_path_last_bytes
    xor eax, eax
    mov ecx, LINUX_PATH_SNAPSHOT_BYTES / 4
    rep stosd
    mov esi, ebx
    cmp esi, 0
    je .done
    xor ecx, ecx

.copy:
    cmp ecx, LINUX_PATH_SNAPSHOT_BYTES
    jae .valid
    lea eax, [esi + ecx]
    mov ebx, 1
    call user_range_validate
    jc .done
    mov dl, [esi + ecx]
    mov [linux_path_last_bytes + ecx], dl
    cmp dl, 0
    je .valid
    inc ecx
    jmp .copy

.valid:
    mov dword [linux_path_last_valid], 1

.done:
	    popad
	    ret

linux_path_has_prefix_child:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov esi, eax
    mov edx, ebx
    inc ebx
    call user_range_validate
    jc .fail
    mov ecx, edx
    repe cmpsb
    jne .fail
    cmp byte [esi], 0
    je .fail
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

linux_path_is_relative_child:
    push eax
    push ebx

    mov eax, [syscall_ptr_arg]
    cmp eax, 0
    je .fail
    mov ebx, 1
    call user_range_validate
    jc .fail
    cmp byte [eax], 0
    je .fail
    cmp byte [eax], '/'
    je .fail
    clc
    jmp .done

.fail:
    stc

.done:
    pop ebx
    pop eax
    ret

linux_path_is_synthetic_lib_dir:
    push eax
    push ebx
    push edi

    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_lib_end - linux_path_lib
    mov edi, linux_path_lib
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_lib_slash_end - linux_path_lib_slash
    mov edi, linux_path_lib_slash
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_usr_end - linux_path_usr
    mov edi, linux_path_usr
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_usr_slash_end - linux_path_usr_slash
    mov edi, linux_path_usr_slash
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_usr_lib_end - linux_path_usr_lib
    mov edi, linux_path_usr_lib
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_usr_lib_slash_end - linux_path_usr_lib_slash
    mov edi, linux_path_usr_lib_slash
    call user_path_equals
    jnc .ok
%ifdef LINUX_M1_CHROMIUM_SMOKE
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_usr_lib_chromium_end - linux_path_usr_lib_chromium
    mov edi, linux_path_usr_lib_chromium
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_usr_lib_chromium_slash_end - linux_path_usr_lib_chromium_slash
    mov edi, linux_path_usr_lib_chromium_slash
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_usr_lib_chromium_locales_end - linux_path_usr_lib_chromium_locales
    mov edi, linux_path_usr_lib_chromium_locales
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_usr_lib_chromium_locales_slash_end - linux_path_usr_lib_chromium_locales_slash
    mov edi, linux_path_usr_lib_chromium_locales_slash
    call user_path_equals
    jnc .ok
%endif
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_lib_i386_end - linux_path_lib_i386
    mov edi, linux_path_lib_i386
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_lib_i386_slash_end - linux_path_lib_i386_slash
    mov edi, linux_path_lib_i386_slash
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_usr_lib_i386_end - linux_path_usr_lib_i386
    mov edi, linux_path_usr_lib_i386
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_usr_lib_i386_slash_end - linux_path_usr_lib_i386_slash
    mov edi, linux_path_usr_lib_i386_slash
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_tmp_end - linux_path_tmp
    mov edi, linux_path_tmp
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_tmp_slash_end - linux_path_tmp_slash
    mov edi, linux_path_tmp_slash
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_tmp_chromium_profile_end - linux_path_tmp_chromium_profile
    mov edi, linux_path_tmp_chromium_profile
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_tmp_chromium_profile_slash_end - linux_path_tmp_chromium_profile_slash
    mov edi, linux_path_tmp_chromium_profile_slash
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_tmp_chromium_profile_slash_end - linux_path_tmp_chromium_profile_slash - 1
    mov edi, linux_path_tmp_chromium_profile_slash
    call linux_path_has_prefix_child
    jnc .ok
    cmp dword [linux_relative_synthetic_dir_arg], 1
    jne .check_proc_dirs
    call linux_path_is_relative_child
    jnc .ok

.check_proc_dirs:
%ifdef LINUX_M1_CHROMIUM_SMOKE
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_proc_end - linux_path_proc
    mov edi, linux_path_proc
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_proc_slash_end - linux_path_proc_slash
    mov edi, linux_path_proc_slash
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_proc_self_end - linux_path_proc_self
    mov edi, linux_path_proc_self
    call user_path_equals
    jnc .ok
    mov eax, [syscall_ptr_arg]
    mov ebx, linux_path_proc_self_slash_end - linux_path_proc_self_slash
