    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

linux_sys_fcntl:
    cmp ecx, F_DUPFD
    je .dupfd
    cmp ecx, F_DUPFD_CLOEXEC
    je .dupfd_cloexec
    cmp ecx, F_GETFD
    je .getfd
    cmp ecx, F_SETFD
    je .setfd
    cmp ecx, F_GETFL
    je .getfl
    cmp ecx, F_SETFL
    je .setfl
    mov eax, -ERRNO_EINVAL
    ret

.dupfd:
    mov dword [fd_dup_flags_arg], FD_INHERIT_EXEC
    call linux_fcntl_dupfd
    ret

.dupfd_cloexec:
    mov dword [fd_dup_flags_arg], 0
    call linux_fcntl_dupfd
    ret

.getfd:
    call fd_lookup_descriptor
    jc .ebadf
    mov esi, eax
    mov eax, [fd_inherit_flags + esi * 4]
    test eax, FD_INHERIT_EXEC
    jz .getfd_cloexec
    xor eax, eax
    ret

.getfd_cloexec:
    mov eax, FD_CLOEXEC
    ret

.setfd:
    call fd_lookup_descriptor
    jc .ebadf
    mov esi, eax
    mov eax, edx
    and eax, 0xfffffffe
    jnz .einval
    test edx, FD_CLOEXEC
    jz .setfd_inherit
    mov dword [fd_inherit_flags + esi * 4], 0
    xor eax, eax
    ret

.setfd_inherit:
    mov dword [fd_inherit_flags + esi * 4], FD_INHERIT_EXEC
    xor eax, eax
    ret

.getfl:
    call fd_lookup
    jc .ebadf
    mov esi, eax
    mov edx, [fd_flags + esi * 4]
    mov eax, edx
    and eax, O_ACCMODE
    test edx, O_APPEND
    jz .getfl_check_nonblock
    or eax, LINUX_O_APPEND

.getfl_check_nonblock:
    test edx, O_NONBLOCK
    jz .getfl_done
    or eax, LINUX_O_NONBLOCK

.getfl_done:
    ret

.setfl:
    mov [linux_fcntl_flags_arg], edx
    call fd_lookup
    jc .ebadf
    mov esi, eax
    mov eax, [fd_flags + esi * 4]
    and eax, 0xffffebff
    test dword [linux_fcntl_flags_arg], LINUX_O_APPEND
    jz .setfl_check_nonblock
    or eax, O_APPEND

.setfl_check_nonblock:
    test dword [linux_fcntl_flags_arg], LINUX_O_NONBLOCK
    jz .setfl_store
    or eax, O_NONBLOCK

.setfl_store:
    mov [fd_flags + esi * 4], eax
    xor eax, eax
    ret

.ebadf:
    mov eax, -ERRNO_EBADF
    ret

.einval:
    mov eax, -ERRNO_EINVAL
    ret

linux_fcntl_dupfd:
    mov [linux_fcntl_fd_arg], ebx
    mov [linux_fcntl_min_fd_arg], edx
