.ebadf:
    mov eax, -ERRNO_EBADF
    ret

.emfile:
    mov eax, -ERRNO_EMFILE
    ret

.einval:
    mov eax, -ERRNO_EINVAL
    ret

linux_sys_pipe:
    xor ecx, ecx
    call linux_sys_pipe_common
    ret

linux_sys_pipe2:
    call linux_sys_pipe_common
    ret

linux_sys_pipe_common:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [pipe_user_ptr_arg], ebx
    mov [pipe_flags_arg], ecx
    mov eax, ecx
    and eax, LINUX_PIPE2_KNOWN_MASK
    cmp eax, ecx
    jne .einval
    mov eax, [pipe_user_ptr_arg]
    mov ebx, 8
    call user_range_validate
    jc .einval

    xor ebx, ebx

.find_pipe:
    cmp ebx, PIPE_SLOT_COUNT
    jae .emfile
    cmp byte [pipe_status + ebx], 0
    je .pipe_found
    inc ebx
    jmp .find_pipe

.pipe_found:
    mov [pipe_alloc_slot], ebx
    mov dword [syscall_open_flags], 0
    test dword [pipe_flags_arg], LINUX_O_CLOEXEC
    jz .alloc_read_fd
    mov dword [syscall_open_flags], O_CLOEXEC

.alloc_read_fd:
    call fd_alloc
    jc .emfile
    mov [pipe_read_fd_slot], eax
    call fd_alloc
    jc .rollback_read_fd
    mov [pipe_write_fd_slot], eax

    mov ebx, [pipe_alloc_slot]
    mov byte [pipe_status + ebx], 1
    mov byte [pipe_read_open + ebx], 1
    mov byte [pipe_write_open + ebx], 1
    mov dword [pipe_lengths + ebx * 4], 0

    xor edx, edx
    test dword [pipe_flags_arg], LINUX_O_NONBLOCK
    jz .read_flags_ready
    or edx, O_NONBLOCK

.read_flags_ready:
    mov esi, [pipe_read_fd_slot]
    mov byte [fd_kinds + esi], FD_KIND_PIPE_READ
    mov [fd_indices + esi * 4], ebx
    mov dword [fd_offsets + esi * 4], 0
    mov [fd_flags + esi * 4], edx
    mov dword [fd_file_sizes + esi * 4], 0

    mov edx, O_WRONLY
    test dword [pipe_flags_arg], LINUX_O_NONBLOCK
    jz .write_flags_ready
    or edx, O_NONBLOCK

.write_flags_ready:
    mov esi, [pipe_write_fd_slot]
    mov byte [fd_kinds + esi], FD_KIND_PIPE_WRITE
    mov [fd_indices + esi * 4], ebx
    mov dword [fd_offsets + esi * 4], 0
    mov [fd_flags + esi * 4], edx
    mov dword [fd_file_sizes + esi * 4], 0

    mov edi, [pipe_user_ptr_arg]
    mov eax, [pipe_read_fd_slot]
    add eax, USER_FD_BASE
    mov [edi], eax
    mov eax, [pipe_write_fd_slot]
    add eax, USER_FD_BASE
    mov [edi + 4], eax
    xor eax, eax
    jmp .done

.rollback_read_fd:
    mov ebx, [pipe_read_fd_slot]
    call fd_clear_slot

.emfile:
    mov eax, -ERRNO_EMFILE
    jmp .done

.einval:
    mov eax, -ERRNO_EINVAL

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

linux_sys_poll:
    call linux_sys_poll_common
    ret

linux_sys_ppoll:
    cmp edx, 0
    je .sigmask
    mov eax, edx
    mov ebx, LINUX_TIMESPEC_BYTES
    call user_range_validate
    jc .efault

.sigmask:
    cmp esi, 0
    je .poll
    mov eax, esi
    mov ebx, edi
    call user_range_validate
    jc .efault

.poll:
    call linux_sys_poll_common
    ret

.efault:
    mov eax, -ERRNO_EFAULT
    ret

linux_sys_poll_common:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [linux_pollfds_arg], ebx
    mov [linux_poll_nfds_arg], ecx
    cmp ecx, LINUX_POLL_MAX_NFDS
    ja .einval
    cmp ecx, 0
    je .zero
    mov eax, ecx
    shl eax, 3
    mov ebx, eax
    mov eax, [linux_pollfds_arg]
    call user_range_validate
    jc .efault

    mov dword [linux_poll_ready_count], 0
    mov dword [linux_poll_index], 0

.loop:
    mov eax, [linux_poll_index]
    cmp eax, [linux_poll_nfds_arg]
    jae .done_count
    mov edi, [linux_pollfds_arg]
    mov edx, eax
    shl edx, 3
    add edi, edx
    mov word [edi + 6], 0
    mov ebx, [edi]
    test ebx, ebx
    js .next
    movzx ecx, word [edi + 4]
    call linux_pollfd_revents
    mov [edi + 6], ax
    test ax, ax
    jz .next
    inc dword [linux_poll_ready_count]

.next:
    inc dword [linux_poll_index]
    jmp .loop

.done_count:
    mov eax, [linux_poll_ready_count]
    jmp .done

.zero:
    xor eax, eax
    jmp .done

.efault:
    mov eax, -ERRNO_EFAULT
    jmp .done

.einval:
    mov eax, -ERRNO_EINVAL

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

