.common:
    call linux_sys_select_common
    ret

.efault:
    mov eax, -ERRNO_EFAULT
    ret

linux_sys_pselect6:
    cmp edi, 0
    je .sigmask
    mov eax, edi
    mov ebx, LINUX_TIMESPEC_BYTES
    call user_range_validate
    jc .efault

.sigmask:
