    call linux_fd_read_ready
    jc .nval
    test eax, eax
    jz .write
    or edx, LINUX_POLLIN

.write:
    test ecx, LINUX_POLLOUT
    jz .done
    call linux_fd_write_ready
    jc .nval
    test eax, eax
    jz .done
    or edx, LINUX_POLLOUT
    jmp .done

.nval:
    mov edx, LINUX_POLLNVAL

.done:
    mov eax, edx
    pop edx
    pop ecx
    pop ebx
    ret

