linux_fd_root_read_ready:
    cmp byte [fd_kinds + esi], FD_KIND_PRIMARY_ASSET
    je .ready
    cmp byte [fd_kinds + esi], FD_KIND_READONLY_FILE
    je .ready
    cmp byte [fd_kinds + esi], FD_KIND_DIRECTORY
    je .ready
    cmp byte [fd_kinds + esi], FD_KIND_DEV_NULL
    je .dev_null
    cmp byte [fd_kinds + esi], FD_KIND_WRITABLE
    je .writable_file
    cmp byte [fd_kinds + esi], FD_KIND_PIPE_READ
    je .pipe_read
    xor eax, eax
    ret

.dev_null:
    mov eax, [fd_flags + esi * 4]
    and eax, O_ACCMODE
    cmp eax, O_WRONLY
    je .not_ready
    jmp .ready

.writable_file:
    mov eax, [fd_flags + esi * 4]
    and eax, O_ACCMODE
    cmp eax, O_WRONLY
    je .not_ready
    jmp .ready

.pipe_read:
    mov edx, [fd_indices + esi * 4]
    cmp edx, PIPE_SLOT_COUNT
    jae .not_ready
    cmp byte [pipe_status + edx], 1
    jne .not_ready
    cmp byte [pipe_read_open + edx], 1
    jne .not_ready
    cmp dword [pipe_lengths + edx * 4], 0
    jne .ready
    cmp byte [pipe_write_open + edx], 0
    je .ready
    jmp .not_ready

.ready:
    mov eax, 1
    ret

.not_ready:
    xor eax, eax
    ret

linux_fd_root_write_ready:
    cmp byte [fd_kinds + esi], FD_KIND_WRITABLE
    je .writable_file
    cmp byte [fd_kinds + esi], FD_KIND_DEV_NULL
    je .dev_null
    cmp byte [fd_kinds + esi], FD_KIND_PIPE_WRITE
    je .pipe_write
    xor eax, eax
    ret

.dev_null:
    mov eax, [fd_flags + esi * 4]
    and eax, O_ACCMODE
    cmp eax, O_WRONLY
    je .ready
    cmp eax, O_RDWR
    je .ready
    jmp .not_ready

.writable_file:
    mov eax, [fd_flags + esi * 4]
    and eax, O_ACCMODE
    cmp eax, O_WRONLY
    je .ready
    cmp eax, O_RDWR
    je .ready
    jmp .not_ready

.pipe_write:
    mov edx, [fd_indices + esi * 4]
    cmp edx, PIPE_SLOT_COUNT
    jae .not_ready
    cmp byte [pipe_status + edx], 1
    jne .not_ready
    cmp byte [pipe_write_open + edx], 1
    jne .not_ready
    cmp byte [pipe_read_open + edx], 1
    jne .not_ready
    mov eax, [pipe_lengths + edx * 4]
    cmp eax, PIPE_BUFFER_BYTES
    jae .not_ready

.ready:
    mov eax, 1
    ret

.not_ready:
    xor eax, eax
    ret

