    jae .einval
    cmp byte [timerfd_status + eax], 1
    jne .einval
    mov eax, [timerfd_old_ptr_arg]
    mov ebx, LINUX_ITIMERSPEC_BYTES
    call user_range_validate
    jc .einval
    mov edi, eax
    mov ecx, LINUX_ITIMERSPEC_BYTES / 4
    xor eax, eax
    cld
    rep stosd
    xor eax, eax
    jmp .done

.ebadf:
    mov eax, -ERRNO_EBADF
    jmp .done

.einval:
    mov eax, -ERRNO_EINVAL

.done:
    pop edi
    pop ecx
    pop ebx
    ret

linux_sys_gettid:
    mov eax, [current_pid]
