    cmp eax, 0xffffffff
    jne .done

.zero:
    xor eax, eax

.done:
    ret

linux_sys_get_identity_zero:
    xor eax, eax
    ret

linux_sys_getpgid:
    cmp ebx, 0
    je .current
    cmp ebx, [current_pid]
    jne .esrch

.current:
    mov eax, [current_pid]
    ret

.esrch:
    mov eax, -ERRNO_ESRCH
    ret

linux_sys_setpgid:
