    je .ok
    cmp ecx, [current_pid]
    jne .eperm

.ok:
    xor eax, eax
    ret

.esrch:
    mov eax, -ERRNO_ESRCH
    ret

.eperm:
    mov eax, -ERRNO_EPERM
    ret

linux_sys_setsid:
    mov eax, [current_pid]
    ret

linux_sys_getsid:
    cmp ebx, 0
    je .current
    cmp ebx, [current_pid]
    jne .esrch

.current:
    mov eax, [current_pid]
    ret

.esrch:
    mov eax, -ERRNO_ESRCH
    ret

linux_sys_socketcall:
    mov dword [linux_socket_last_call], LINUX_SYS_SOCKETCALL
    mov [linux_socket_last_subcall], ebx
    cmp ebx, LINUX_SOCKETCALL_SOCKETPAIR
    je .socketpair
    cmp ebx, LINUX_SOCKETCALL_SETSOCKOPT
    je .setsockopt
    jmp .enosys

.socketpair:
