    mov eax, esi
    mov ebx, edi
    call user_range_validate
    jc .efault_set
    inc dword [linux_socket_setsockopt_successes]
    xor eax, eax
    mov [linux_socket_last_result], eax
    ret

.badfd:
    mov eax, -ERRNO_EBADF
    jmp .fail

.notsock:
    mov eax, -ERRNO_ENOTSOCK
    jmp .fail

.noprotoopt:
    mov eax, -ERRNO_ENOPROTOOPT
    jmp .fail

.efault_set:
    mov eax, -ERRNO_EFAULT
    jmp .fail

.einval_set:
    mov eax, -ERRNO_EINVAL

.fail:
    inc dword [linux_socket_setsockopt_failures]
    mov [linux_socket_last_result], eax
    ret

pipe_read:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [pipe_io_fd_slot], eax
    mov [pipe_io_user_ptr], ecx
    mov [pipe_io_len], edx
    cmp edx, 0
    je .zero
    mov eax, ecx
    mov ebx, edx
    call user_range_validate
    jc .fail_inval

    mov esi, [pipe_io_fd_slot]
    mov ebx, [fd_indices + esi * 4]
    cmp ebx, PIPE_SLOT_COUNT
    jae .fail_badfd
    cmp byte [pipe_status + ebx], 1
    jne .fail_badfd
    cmp byte [pipe_read_open + ebx], 1
    jne .fail_badfd
    mov eax, [pipe_lengths + ebx * 4]
    cmp eax, 0
    je .zero
    cmp [pipe_io_len], eax
    jbe .copy_ready
    mov [pipe_io_len], eax

.copy_ready:
    mov esi, pipe_buffers
    mov edx, ebx
    shl edx, 8
    add esi, edx
    mov edi, [pipe_io_user_ptr]
    mov ecx, [pipe_io_len]
    cld
    rep movsb

    mov eax, [pipe_io_len]
    mov edx, [pipe_lengths + ebx * 4]
    sub edx, eax
    mov [pipe_io_remaining], edx
    cmp edx, 0
    je .store_remaining
    mov esi, pipe_buffers
    mov edi, pipe_buffers
    mov ecx, ebx
    shl ecx, 8
    add esi, ecx
    add edi, ecx
    add esi, eax
    mov ecx, [pipe_io_remaining]
    cld
    rep movsb

.store_remaining:
    mov eax, [pipe_io_remaining]
    mov [pipe_lengths + ebx * 4], eax
    mov eax, [pipe_io_len]
