pipe_write:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov [pipe_io_fd_slot], eax
    mov [pipe_io_user_ptr], ecx
    mov [pipe_io_len], edx
    cmp edx, 0
    je .zero
    mov eax, ecx
