    shl esi, 8
    add edi, esi
    add edi, [pipe_lengths + ebx * 4]
    mov esi, [pipe_io_user_ptr]
    mov ecx, [pipe_io_len]
    cld
    rep movsb
    mov eax, [pipe_io_len]
    add [pipe_lengths + ebx * 4], eax
    clc
    jmp .done

.zero:
    xor eax, eax
    clc
    jmp .done

.fail_again:
