    ret

linux_fstat64_common:
    mov [syscall_stat_ptr], ecx
    mov dword [stat_inode_arg], 1
    cmp ebx, 2
    ja .lookup_file
    mov eax, ebx
    inc eax
    mov [stat_inode_arg], eax
    xor eax, eax
    mov edx, STAT_MODE_STDIO_CHR
    jmp .fill

.lookup_file:
    call fd_lookup
    jc .ebadf
    cmp byte [fd_kinds + eax], FD_KIND_DEV_NULL
    je .dev_null
    cmp byte [fd_kinds + eax], FD_KIND_DEV_ZERO
    je .dev_zero
    cmp byte [fd_kinds + eax], FD_KIND_DEV_URANDOM
    je .dev_urandom
    cmp byte [fd_kinds + eax], FD_KIND_PIPE_READ
    je .pipe
    cmp byte [fd_kinds + eax], FD_KIND_PIPE_WRITE
    je .pipe
%ifdef LINUX_M1_CHROMIUM_SMOKE
    cmp byte [fd_kinds + eax], FD_KIND_SYNTHETIC_FILE
    je .synthetic_file
%endif
    cmp byte [fd_kinds + eax], FD_KIND_READONLY_FILE
    je .readonly_file
    cmp byte [fd_kinds + eax], FD_KIND_DIRECTORY
    jne .ebadf
    mov edx, [fd_indices + eax * 4]
    cmp edx, LINUX_SYNTHETIC_DIR_CLUSTER
    jne .directory_inode_ready
    mov edx, 3

.directory_inode_ready:
    mov [stat_inode_arg], edx
    xor eax, eax
    mov edx, STAT_MODE_READONLY_DIR
    jmp .fill

.readonly_file:
    mov edx, [fd_indices + eax * 4]
    mov [stat_inode_arg], edx
    mov eax, [fd_file_sizes + eax * 4]
    mov edx, STAT_MODE_READONLY_REG
    jmp .fill

%ifdef LINUX_M1_CHROMIUM_SMOKE
.synthetic_file:
    mov edx, [fd_indices + eax * 4]
    mov [stat_inode_arg], edx
    push eax
    mov eax, edx
    call linux_synthetic_file_info
    pop eax
    jc .ebadf
    mov eax, ecx
    mov edx, STAT_MODE_READONLY_REG
    jmp .fill
%endif

.dev_null:
    mov dword [stat_inode_arg], 4
    xor eax, eax
    mov edx, STAT_MODE_STDIO_CHR
    jmp .fill

.dev_zero:
    mov dword [stat_inode_arg], 5
    xor eax, eax
    mov edx, STAT_MODE_STDIO_CHR
    jmp .fill

.dev_urandom:
    mov dword [stat_inode_arg], 6
    xor eax, eax
    mov edx, STAT_MODE_STDIO_CHR
    jmp .fill

.pipe:
    mov edx, [fd_indices + eax * 4]
    add edx, 5
    mov [stat_inode_arg], edx
    xor eax, eax
    mov edx, STAT_MODE_PIPE_FIFO

.fill:
    cmp dword [linux_stat_format], LINUX_STAT_FORMAT_STATX
    je .fill_statx
    call linux_stat64_fill_user
    jc .einval
    xor eax, eax
    ret

.fill_statx:
    call linux_statx_fill_user
    jc .einval
    xor eax, eax
    ret

.ebadf:
    mov eax, -ERRNO_EBADF
    ret

.einval:
    mov eax, -ERRNO_EINVAL
    ret

linux_sys_llseek:
    cmp ecx, 0
    jne .einval
    mov [syscall_ptr_arg], esi
    mov eax, esi
    mov ebx, 8
    call user_range_validate
    jc .einval
    push esi
    mov ecx, edx
    mov edx, edi
    call fd_lookup
    jc .ebadf_pop
    cmp byte [fd_kinds + eax], FD_KIND_READONLY_FILE
    je .readonly_file
%ifdef LINUX_M1_CHROMIUM_SMOKE
    cmp byte [fd_kinds + eax], FD_KIND_SYNTHETIC_FILE
    je .synthetic_file
%endif
    call user_file_lseek
    jc .from_eax
    jmp .store_result

.readonly_file:
    call readonly_file_lseek
    jc .from_eax
    jmp .store_result

%ifdef LINUX_M1_CHROMIUM_SMOKE
.synthetic_file:
    pop edi
    push edi
    cmp edi, 0
    je .einval_pop
    mov eax, [file_io_fd_slot]
    mov eax, [fd_file_sizes + eax * 4]
    cmp edx, 0
    je .synthetic_seek_set
    cmp edx, 1
    je .synthetic_seek_cur
    cmp edx, 2
    je .synthetic_seek_end
    jmp .einval_pop

.synthetic_seek_set:
    mov eax, ecx
    test eax, 0x80000000
    jnz .einval_pop
    jmp .synthetic_seek_validate

.synthetic_seek_cur:
    mov eax, [file_io_fd_slot]
    mov eax, [fd_offsets + eax * 4]
    add eax, ecx
    jo .einval_pop
    test eax, 0x80000000
    jnz .einval_pop
    jmp .synthetic_seek_validate

.synthetic_seek_end:
    mov eax, [file_io_fd_slot]
    mov eax, [fd_file_sizes + eax * 4]
    add eax, ecx
    jo .einval_pop
    test eax, 0x80000000
    jnz .einval_pop

.synthetic_seek_validate:
    mov ebx, [file_io_fd_slot]
    cmp eax, [fd_file_sizes + ebx * 4]
    ja .einval_pop
    mov [fd_offsets + ebx * 4], eax
    jmp .store_result
%endif

.store_result:
    pop edi
    mov [edi], eax
    mov dword [edi + 4], 0
    xor eax, eax
    ret

.from_eax:
    pop esi
    ret

.ebadf_pop:
    pop esi
    mov eax, -ERRNO_EBADF
    ret

.einval_pop:
    pop esi

.einval:
    mov eax, -ERRNO_EINVAL
    ret

linux_sys_pread64:
    cmp edi, 0
    jne .einval
    call fd_lookup
    jc .ebadf
    push dword [fd_offsets + eax * 4]
    mov [fd_offsets + eax * 4], esi
    cmp byte [fd_kinds + eax], FD_KIND_READONLY_FILE
    je .readonly_file
%ifdef LINUX_M1_CHROMIUM_SMOKE
    cmp byte [fd_kinds + eax], FD_KIND_SYNTHETIC_FILE
    je .synthetic_file
%endif
    call user_file_read
    jmp .restore

.readonly_file:
    call readonly_file_read
    jmp .restore

%ifdef LINUX_M1_CHROMIUM_SMOKE
.synthetic_file:
    call linux_synthetic_file_read
    jmp .restore
%endif

.restore:
    mov ebx, [file_io_fd_slot]
    pop dword [fd_offsets + ebx * 4]
    jc .from_eax
    ret

.from_eax:
    ret

.ebadf:
    mov eax, -ERRNO_EBADF
    ret

.einval:
    mov eax, -ERRNO_EINVAL
    ret

linux_sys_mmap2_file:
    inc dword [process_mmap_attempts]
    mov dword [process_mmap_last_result], 0
    mov dword [process_mmap_last_error], 0
    cmp ecx, 0
    je .einval
    mov eax, esi
    and eax, MMAP_MAP_SHARED | MMAP_MAP_PRIVATE
    jz .einval
    mov [mmap_addr_arg], ebx
    mov [mmap_len_arg], ecx
    mov eax, edx
    and eax, MMAP_PROT_MASK
    mov [mmap_prot_arg], eax
    mov [mmap_flags_arg], esi
    mov [syscall_open_flags], edi
    mov eax, ebp
    shl eax, 12
    jc .einval
    mov [file_io_start_offset], eax
    mov [mmap_file_offset_arg], eax
    mov eax, [mmap_len_arg]
    add eax, PAGE_SIZE - 1
    jc .enomem
    and eax, 0xfffff000
    mov [mmap_len_arg], eax
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .enomem
    mov eax, [mmap_addr_arg]
    test dword [mmap_flags_arg], MMAP_MAP_FIXED
    jnz .have_base
    mov eax, [esi + PROC_BRK]
    add eax, PAGE_SIZE - 1
    jc .enomem
    and eax, 0xfffff000

.have_base:
    test eax, PAGE_SIZE - 1
    jnz .einval
    cmp eax, [esi + PROC_HEAP_START]
    jb .enomem
    mov [mmap_base_arg], eax
    mov edx, eax
    add edx, [mmap_len_arg]
    jc .enomem
    cmp edx, [esi + PROC_HEAP_END]
    ja .enomem
    mov [mmap_end_arg], edx
    cmp edx, [esi + PROC_BRK]
    jbe .brk_ready
    mov [esi + PROC_BRK], edx
    mov [current_user_brk], edx
    mov [user_brk_current], edx

.brk_ready:
    mov ebx, [syscall_open_flags]
    call fd_lookup
    jc .ebadf
    cmp byte [fd_kinds + eax], FD_KIND_READONLY_FILE
    jne .ebadf
    mov eax, [mmap_end_arg]
    cmp eax, PAGING_MAPPED_BYTES
    ja .high_file_map

.low_file_map:
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jnz .have_page_dir
    mov ebx, PAGING_DIR_ADDR

.have_page_dir:
    mov eax, [mmap_base_arg]
    mov edx, [mmap_end_arg]
    call vmm_mark_process_user_write_range
    jmp .flush

.flush:
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .heap_mark
    mov cr3, ebx

.heap_mark:
    mov eax, [mmap_base_arg]
    mov edx, [mmap_end_arg]
    call process_heap_mark_range
    mov ebx, [file_io_fd_slot]
    push dword [fd_offsets + ebx * 4]
    mov edx, [file_io_start_offset]
    mov [fd_offsets + ebx * 4], edx
    mov edx, [mmap_len_arg]
    mov ecx, [mmap_base_arg]
    mov ebx, [syscall_open_flags]
    call readonly_file_read
    push eax
    mov ebx, [file_io_fd_slot]
    pop eax
    pop dword [fd_offsets + ebx * 4]
    jc .from_eax
    mov edx, [mmap_len_arg]
    cmp eax, edx
    jae .record
    mov edi, [mmap_base_arg]
    add edi, eax
    mov ecx, edx
    sub ecx, eax
    xor eax, eax
    cld
    rep stosb
    jmp .record

.high_file_map:
    mov eax, [mmap_base_arg]
    mov edx, [mmap_end_arg]
    call process_heap_mark_range
    mov ebx, [file_io_fd_slot]
    mov eax, [fd_offsets + ebx * 4]
    mov [mmap_saved_fd_offset], eax
    mov eax, [mmap_base_arg]
    mov [mmap_page_vaddr], eax

.high_page_next:
    mov eax, [mmap_page_vaddr]
    cmp eax, [mmap_end_arg]
    jae .high_done
    call pmm_alloc_page
    test eax, eax
    jz .high_enomem_restore
    mov [mmap_page_phys], eax

    pushfd
    cli
    mov eax, FORK_COPY_DST_ALIAS
    mov ebx, [mmap_page_phys]
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .high_alias_fail
    mov edi, FORK_COPY_DST_ALIAS
    xor eax, eax
    mov ecx, PAGE_SIZE / 4
    cld
    rep stosd
    mov eax, FORK_COPY_DST_ALIAS
    call vmm_unmap_page
    popfd

    mov esi, [current_process_ptr]
    cmp esi, 0
    je .high_pte_fail
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jnz .high_have_page_dir
    mov ebx, PAGING_DIR_ADDR

.high_have_page_dir:
    mov ecx, [mmap_page_phys]
    and ecx, 0xfffff000
    or ecx, PTE_USER_WRITE_FLAGS
    mov eax, [mmap_page_vaddr]
    call vmm_write_process_pte
    jc .high_pte_fail

    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .high_cr3_ready
    mov cr3, ebx

.high_cr3_ready:
    mov eax, [mmap_page_vaddr]
    invlpg [eax]

    mov ebx, [file_io_fd_slot]
    mov eax, [mmap_file_offset_arg]
    mov edi, [mmap_page_vaddr]
    sub edi, [mmap_base_arg]
    add eax, edi
    jc .high_einval_restore
    mov [fd_offsets + ebx * 4], eax
    mov edx, [mmap_end_arg]
    sub edx, [mmap_page_vaddr]
    cmp edx, PAGE_SIZE
    jbe .high_copy_len_ready
    mov edx, PAGE_SIZE

.high_copy_len_ready:
    mov ecx, [mmap_page_vaddr]
    mov ebx, [syscall_open_flags]
    call readonly_file_read
    jc .high_from_eax_restore
    add dword [mmap_page_vaddr], PAGE_SIZE
    jmp .high_page_next

.high_done:
    mov ebx, [file_io_fd_slot]
    mov eax, [mmap_saved_fd_offset]
    mov [fd_offsets + ebx * 4], eax
    jmp .record

.high_alias_fail:
    popfd
    mov eax, [mmap_page_phys]
    call pmm_free_page
    jmp .high_enomem_restore

.high_pte_fail:
    mov eax, [mmap_page_phys]
    call pmm_free_page
    jmp .high_enomem_restore

.high_einval_restore:
    mov ebx, [file_io_fd_slot]
    mov eax, [mmap_saved_fd_offset]
    mov [fd_offsets + ebx * 4], eax
    jmp .einval

.high_enomem_restore:
    mov ebx, [file_io_fd_slot]
    mov eax, [mmap_saved_fd_offset]
    mov [fd_offsets + ebx * 4], eax
    jmp .enomem

.high_from_eax_restore:
    push eax
    mov ebx, [file_io_fd_slot]
    mov eax, [mmap_saved_fd_offset]
    mov [fd_offsets + ebx * 4], eax
    pop eax
    jmp .from_eax

.record:
    mov eax, [mmap_base_arg]
    mov [process_mmap_last_result], eax
    mov dword [process_mmap_last_error], 0
    inc dword [process_mmap_successes]
    ret

.from_eax:
    mov [process_mmap_last_result], eax
    mov [process_mmap_last_error], eax
    inc dword [process_mmap_failures]
    ret

.ebadf:
    mov dword [process_mmap_last_result], -ERRNO_EBADF
    mov dword [process_mmap_last_error], -ERRNO_EBADF
    inc dword [process_mmap_failures]
    mov eax, -ERRNO_EBADF
    ret

.enomem:
    mov dword [process_mmap_last_result], -ERRNO_ENOMEM
    mov dword [process_mmap_last_error], -ERRNO_ENOMEM
    inc dword [process_mmap_failures]
    mov eax, -ERRNO_ENOMEM
    ret

.einval:
    mov dword [process_mmap_last_result], -ERRNO_EINVAL
    mov dword [process_mmap_last_error], -ERRNO_EINVAL
    inc dword [process_mmap_failures]
    mov eax, -ERRNO_EINVAL
    ret

linux_sys_writev:
    test edx, edx
    js .einval
    cmp edx, LINUX_IOV_MAX_M1
    ja .einval
    mov [syscall_ptr_arg], ecx
    mov [syscall_len_arg], edx
    mov dword [file_io_index], 0
    cmp ebx, 1
    je .fd_ok
    cmp ebx, 2
    je .fd_ok
    call fd_lookup
    jc .ebadf
    cmp byte [fd_kinds + eax], FD_KIND_PIPE_WRITE
    je .pipe_fd
    cmp byte [fd_kinds + eax], FD_KIND_DEV_NULL
    jne .ebadf
    mov esi, [file_io_fd_slot]
    mov eax, [fd_flags + esi * 4]
    and eax, O_ACCMODE
    cmp eax, O_WRONLY
    je .dev_null_fd
    cmp eax, O_RDWR
    jne .ebadf

.dev_null_fd:
    mov dword [file_io_index], 2
    jmp .fd_ok

.pipe_fd:
    mov dword [file_io_index], 1

.fd_ok:
    cmp dword [syscall_len_arg], 0
    je .zero
    mov eax, ecx
    mov ebx, edx
    shl ebx, 3
    call user_range_validate
    jc .einval
    mov esi, [syscall_ptr_arg]
    mov ebp, [syscall_len_arg]
    xor edi, edi

.iov_next:
    cmp ebp, 0
    je .done
    mov eax, [esi]
    mov ecx, [esi + 4]
    add esi, 8
    cmp ecx, 0
    je .iov_advance
    push esi
    push ebp
    push edi
    mov [syscall_ptr_arg], eax
    mov [syscall_len_arg], ecx
    mov ebx, ecx
    call user_range_validate
    jc .range_fail
    cmp dword [file_io_index], 0
    je .write_stdout
    cmp dword [file_io_index], 1
    je .write_pipe
    jmp .write_dev_null

.write_stdout:
    mov esi, [syscall_ptr_arg]
    mov ecx, [syscall_len_arg]

.write_next:
    cmp ecx, 0
    je .write_done
    lodsb
    call put_char
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_PRIMARY
    jne .write_skip_capture
    call payload_primary_stdout_log_char

.write_skip_capture:
    dec ecx
    jmp .write_next

.write_done:
    pop edi
    mov eax, [syscall_len_arg]
    add edi, eax
    pop ebp
    pop esi
    jmp .iov_advance

.write_pipe:
    mov eax, [file_io_fd_slot]
    mov ecx, [syscall_ptr_arg]
    mov edx, [syscall_len_arg]
    call pipe_write
    jc .pipe_fail
    pop edi
    add edi, eax
    mov ecx, [syscall_len_arg]
    cmp eax, ecx
    pop ebp
    pop esi
    jb .done
    jmp .iov_advance

.write_dev_null:
    pop edi
    mov eax, [syscall_len_arg]
    add edi, eax
    pop ebp
    pop esi

.iov_advance:
    dec ebp
    jmp .iov_next

.done:
    mov eax, user_io_write_count
    call user_io_increment_current
    mov eax, edi
    ret

.zero:
    xor edi, edi
    jmp .done

.range_fail:
    pop edi
    pop ebp
    pop esi

.einval:
    mov eax, -ERRNO_EINVAL
    ret

.pipe_fail:
    mov edx, eax
    pop edi
    pop ebp
    pop esi
    cmp edi, 0
    jne .done
    mov eax, edx
    ret

.ebadf:
    mov eax, -ERRNO_EBADF
    ret

syscall_handler:
    push eax
    xor eax, eax
    mov ax, ds
    push eax
    mov ax, es
    push eax
    mov ax, fs
    push eax
    mov ax, gs
    push eax
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    pop eax
    mov [syscall_entry_gs_last], eax
    pop eax
    mov [syscall_entry_fs_last], eax
    pop eax
    mov [syscall_entry_es_last], eax
    pop eax
    mov [syscall_entry_ds_last], eax
    pop eax
    push ebx
    push ecx
    push edx
    push esi
    push edi
    push ebp

    cld
    inc dword [syscall_trap_entry_count]
    mov dword [syscall_abi_version_seen], VIBE_USER_ABI_VERSION
    mov dword [syscall_trap_vector_seen], SYSCALL_TRAP_VECTOR
    mov dword [syscall_max_args_seen], SYSCALL_MAX_ARGS
    mov dword [syscall_result_convention_seen], SYSCALL_RESULT_NEGATIVE_ERRNO
    mov dword [syscall_saved_reg_mask_seen], SYSCALL_SAVED_REG_MASK
    mov dword [syscall_frame_bytes_seen], SYSCALL_FRAME_BYTES
    mov [syscall_entry_kernel_esp_last], esp
    push eax
    mov eax, [esp + 4 + SYSCALL_FRAME_EIP]
    mov [syscall_entry_eip_last], eax
    mov eax, [esp + 4 + SYSCALL_FRAME_CS]
    mov [syscall_entry_cs_last], eax
    mov eax, [esp + 4 + SYSCALL_FRAME_EFLAGS]
    mov [syscall_entry_eflags_last], eax
    mov eax, [esp + 4 + SYSCALL_FRAME_ESP]
    mov [syscall_entry_esp_last], eax
    mov eax, [esp + 4 + SYSCALL_FRAME_SS]
    mov [syscall_entry_ss_last], eax
    mov eax, [tss_esp0]
    mov [syscall_entry_tss_esp0_last], eax
    pop eax

    mov [current_syscall_number], eax
    push edx
    mov edx, eax
    mov eax, user_io_last_syscall
    call user_io_store_current
    pop edx
    mov eax, [current_syscall_number]

.dispatch:
    ; Linux personality branch: route LINUX processes to the parallel
    ; Linux i386 syscall path; native processes fall through unchanged.
    push ebx
    mov ebx, [current_process_ptr]
    cmp dword [ebx + PROC_PERSONALITY], PERSONALITY_LINUX
    pop ebx
    je .linux_dispatch
    cmp eax, SYS_USER_PROBE
    je .user_probe
    cmp eax, SYS_EXIT
    je .exit
    cmp eax, SYS_EXPECT_FAULT
    je .expect_fault
    cmp eax, SYS_WRITE
    je .write
    cmp eax, SYS_SBRK
    je .sbrk
    cmp eax, SYS_OPEN
    je .open
    cmp eax, SYS_READ
    je .read
    cmp eax, SYS_LSEEK
    je .lseek
    cmp eax, SYS_TIME
    je .time
    cmp eax, SYS_PRESENT
    je .present
    cmp eax, SYS_POLL_KEY
    je .poll_key
    cmp eax, SYS_CLOSE
    je .close
    cmp eax, SYS_AUDIO
    je .audio
    cmp eax, SYS_POLL_MOUSE
    je .poll_mouse
    cmp eax, SYS_GAMEPLAY_STATUS
    je .gameplay_status
    cmp eax, SYS_EXEC
    je .exec
    cmp eax, SYS_UNLINK
    je .unlink
    cmp eax, SYS_STAT
    je .stat
    cmp eax, SYS_FSTAT
    je .fstat
    cmp eax, SYS_MMAP
    je .mmap
    cmp eax, SYS_MUNMAP
    je .munmap
    cmp eax, SYS_IOCTL
    je .ioctl
    cmp eax, SYS_FORK
    je .fork
    cmp eax, SYS_WAITPID
    je .waitpid
    cmp eax, SYS_GETPID
    je .getpid
    cmp eax, SYS_PLAYER_DETAIL_STATUS
    je .player_detail_status
    cmp eax, SYS_FTRUNCATE
    je .ftruncate
    cmp eax, SYS_POLL_INPUT
    je .poll_input
    cmp eax, SYS_CLOCK_GETTIME
    je .clock_gettime
    cmp eax, SYS_LISTDIR
    je .listdir
    cmp eax, SYS_INPUT_STATUS
    je .input_status
    cmp eax, SYS_INPUT_DEVICE_STATUS
    je .input_device_status
    cmp eax, SYS_DUP
    je .dup
    cmp eax, SYS_DUP2
    je .dup2
    cmp eax, SYS_DUP3
    je .dup3
    cmp eax, SYS_FCNTL
    je .fcntl
    cmp eax, SYS_PROCESS_STATUS
    je .process_status
    cmp eax, SYS_YIELD
    je .yield
    cmp eax, SYS_SLEEP_TICKS
    je .sleep_ticks
    cmp eax, SYS_GETPPID
    je .getppid
    jmp .bad_syscall_enosys

.user_probe:
    cmp byte [current_user_kind], USER_KIND_PREEMPT_PROBE
    je .user_probe_skip
    cmp ebx, ABI_PROBE_MAGIC
    je .abi_probe
    mov [user_probe_magic_seen], ebx
    mov [user_probe_flags_seen], ecx
    movzx edx, word [esp + 28]
    mov [user_probe_cs], dx
    movzx edx, word [esp + 40]
    mov [user_probe_ss], dx
    mov byte [user_probe_status], 1
    xor eax, eax
    jmp .return

.abi_probe:
    mov [abi_probe_magic_seen], ebx
    mov [abi_probe_flags_seen], ecx
    cmp ecx, ABI_PROBE_EXPECTED_FLAGS
    jne .abi_probe_fail
    mov byte [abi_probe_status], 1
    xor eax, eax
    jmp .return

.abi_probe_fail:
    mov byte [abi_probe_status], 2
    xor eax, eax
    jmp .return

.user_probe_skip:
    xor eax, eax
    jmp .return

.expect_fault:
    mov [syscall_ptr_arg], ebx
    cmp ebx, 0
    je .expect_fault_arm
    mov eax, ebx
    mov ebx, 1
    call user_range_validate
    jc .bad_syscall_einval
    mov ebx, [syscall_ptr_arg]

.expect_fault_arm:
    mov byte [user_fault_expected], 1
    mov [user_fault_recovery], ebx
    xor eax, eax
    jmp .return

.write:
    cmp ebx, 1
    je .write_fd_ok
    cmp ebx, 2
    je .write_fd_ok
    mov eax, vfs_write_count
    call .vfs_count_generic
    call fd_lookup
    jc .bad_syscall_ebadf
    cmp byte [fd_kinds + eax], FD_KIND_PIPE_WRITE
    je .write_pipe
    cmp byte [fd_kinds + eax], FD_KIND_DEV_NULL
    je .write_dev_null
    cmp byte [fd_kinds + eax], FD_KIND_DEV_ZERO
    je .write_dev_null
    cmp byte [fd_kinds + eax], FD_KIND_DEV_URANDOM
    je .write_dev_null
    cmp byte [fd_kinds + eax], FD_KIND_EVENTFD
    je .write_eventfd
    call user_file_write
    jc .bad_syscall_from_eax
    jmp .return

.write_eventfd:
    call eventfd_write
    jc .bad_syscall_from_eax
    jmp .return

.write_dev_null:
    mov esi, [file_io_fd_slot]
    mov eax, [fd_flags + esi * 4]
    and eax, O_ACCMODE
    cmp eax, O_WRONLY
    je .write_dev_null_mode_ok
    cmp eax, O_RDWR
    jne .bad_syscall_ebadf

.write_dev_null_mode_ok:
    mov [syscall_ptr_arg], ecx
    mov [syscall_len_arg], edx
    cmp edx, 0
    je .write_dev_null_done
    mov eax, ecx
    mov ebx, edx
    call user_range_validate
    jc .bad_syscall_einval

.write_dev_null_done:
    mov eax, user_io_write_count
    call user_io_increment_current
    mov eax, [syscall_len_arg]
    jmp .return

.write_pipe:
    call pipe_write
    jc .bad_syscall_from_eax
    jmp .return

.write_fd_ok:
    mov [syscall_ptr_arg], ecx
    mov [syscall_len_arg], edx
    mov eax, ecx
    mov ebx, edx
    call user_range_validate
    jc .bad_syscall_einval
    mov esi, [syscall_ptr_arg]
    mov ecx, [syscall_len_arg]

.write_next:
    cmp ecx, 0
    je .write_done
    lodsb
    call put_char
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_PRIMARY
    jne .write_skip_capture
    call payload_primary_stdout_log_char

.write_skip_capture:
    dec ecx
    jmp .write_next

.write_done:
    mov eax, user_io_write_count
    call user_io_increment_current
    mov eax, [syscall_len_arg]
    jmp .return

.sbrk:
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .bad_syscall_enomem
    mov eax, [esi + PROC_BRK]
    mov edx, eax
    test ebx, 0x80000000
    jnz .sbrk_shrink
    add edx, ebx
    jc .bad_syscall_enomem
    cmp edx, [esi + PROC_HEAP_END]
    ja .bad_syscall_enomem
    mov [sbrk_old_brk], eax
    mov [sbrk_new_brk], edx
    push eax
    push edx
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jnz .sbrk_have_page_dir
    mov ebx, PAGING_DIR_ADDR

.sbrk_have_page_dir:
    call vmm_mark_process_user_range
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .sbrk_restore_brk
    mov cr3, ebx

.sbrk_restore_brk:
    pop edx
    pop eax
    mov edi, [sbrk_old_brk]
    mov ecx, [sbrk_new_brk]
    sub ecx, edi
    xor eax, eax
    cld
    rep stosb
    mov eax, [sbrk_old_brk]
    mov edx, [sbrk_new_brk]
    call process_heap_mark_range
    mov [esi + PROC_BRK], edx
    mov [current_user_brk], edx
    mov [user_brk_current], edx
    mov eax, user_io_sbrk_count
    call user_io_increment_current
    mov eax, [sbrk_old_brk]
    jmp .return

.sbrk_shrink:
    add edx, ebx
    cmp edx, eax
    ja .bad_syscall_enomem
    cmp edx, [esi + PROC_HEAP_START]
    jb .bad_syscall_enomem
    mov [sbrk_old_brk], eax
    mov [sbrk_new_brk], edx
    mov ecx, edx
    add ecx, PAGE_SIZE - 1
    jc .bad_syscall_enomem
    and ecx, 0xfffff000
    mov edi, eax
    add edi, PAGE_SIZE - 1
    and edi, 0xfffff000
    cmp ecx, edi
    jae .sbrk_shrink_update
    push ecx
    push edi
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jnz .sbrk_shrink_have_page_dir
    mov ebx, PAGING_DIR_ADDR

.sbrk_shrink_have_page_dir:
    mov eax, ecx
    mov edx, edi
    call process_clear_user_range
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .sbrk_shrink_count_pages
    mov cr3, ebx

.sbrk_shrink_count_pages:
    pop edi
    pop ecx
    mov eax, edi
    sub eax, ecx
    shr eax, 12
    add [process_sbrk_pages_released], eax

.sbrk_shrink_update:
    mov edx, [sbrk_new_brk]
    mov [esi + PROC_BRK], edx
    mov [current_user_brk], edx
    mov [user_brk_current], edx
    inc dword [process_sbrk_shrink_calls]
    mov eax, [sbrk_old_brk]
    jmp .return

.vfs_count_generic:
    push eax
    push edx
    inc dword [eax]
    xor edx, edx
    cmp eax, vfs_open_count
    jne .vfs_count_read
    mov edx, VFS_ABI_OPEN
    jmp .vfs_count_record

.vfs_count_read:
    cmp eax, vfs_read_count
    jne .vfs_count_write
    mov edx, VFS_ABI_READ
    jmp .vfs_count_record

.vfs_count_write:
    cmp eax, vfs_write_count
    jne .vfs_count_lseek
    mov edx, VFS_ABI_WRITE
    jmp .vfs_count_record

.vfs_count_lseek:
    cmp eax, vfs_lseek_count
    jne .vfs_count_stat
    mov edx, VFS_ABI_LSEEK
    jmp .vfs_count_record

.vfs_count_stat:
    cmp eax, vfs_stat_count
    jne .vfs_count_fstat
    mov edx, VFS_ABI_STAT
    jmp .vfs_count_record

.vfs_count_fstat:
    cmp eax, vfs_fstat_count
    jne .vfs_count_listdir
    mov edx, VFS_ABI_FSTAT
    jmp .vfs_count_record

.vfs_count_listdir:
    cmp eax, vfs_listdir_count
    jne .vfs_count_unlink
    mov edx, VFS_ABI_LISTDIR
    jmp .vfs_count_record

.vfs_count_unlink:
    cmp eax, vfs_unlink_count
    jne .vfs_count_ftruncate
    mov edx, VFS_ABI_UNLINK
    jmp .vfs_count_record

.vfs_count_ftruncate:
    cmp eax, vfs_ftruncate_count
    jne .vfs_count_close
    mov edx, VFS_ABI_FTRUNCATE
    jmp .vfs_count_record

.vfs_count_close:
    cmp eax, vfs_close_count
    jne .vfs_count_done
    mov edx, VFS_ABI_CLOSE

.vfs_count_record:
    or [vfs_generic_abi_mask], edx
    mov [vfs_generic_last_op], edx

.vfs_count_done:
    pop edx
    pop eax
    ret

.open:
    mov [syscall_ptr_arg], ebx
    mov [syscall_open_flags], ecx
    push edx
    mov edx, ecx
    mov eax, user_io_last_open_flags
    call user_io_store_current
    pop edx
    mov eax, user_io_last_open_mode
    call user_io_store_current
    mov eax, vfs_open_count
    call .vfs_count_generic
    mov eax, [syscall_open_flags]
    and eax, O_KNOWN_MASK
    cmp eax, [syscall_open_flags]
    jne .bad_syscall_einval
    mov eax, [syscall_open_flags]
    and eax, O_ACCMODE
    cmp eax, O_ACCMODE
    je .bad_syscall_einval
    test dword [syscall_open_flags], O_TRUNC | O_APPEND
    jz .open_flags_ok
    cmp eax, O_WRONLY
    je .open_flags_ok
    cmp eax, O_RDWR
    jne .bad_syscall_einval

.open_flags_ok:
    push ebx
    mov ebx, [current_process_ptr]
    cmp ebx, 0
    je .open_synthetic_dir_skip
    cmp dword [ebx + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .open_synthetic_dir_skip
    call linux_path_is_dev_null
    jnc .open_dev_null_pop_bind
    call linux_path_is_dev_zero
    jnc .open_dev_zero_pop_bind
    call linux_path_is_dev_urandom
    jnc .open_dev_urandom_pop_bind
    call linux_path_is_proc_self_exe
    jnc .open_proc_self_exe_pop_lookup
%ifdef LINUX_M1_CHROMIUM_SMOKE
    call linux_path_get_synthetic_file
    jnc .open_synthetic_file_pop_bind
%endif
    mov eax, [syscall_open_flags]
    test eax, O_WRONLY | O_RDWR | O_CREAT | O_TRUNC | O_APPEND
    jnz .open_synthetic_dir_skip
    call linux_path_is_synthetic_lib_dir
    jnc .open_synthetic_dir_pop_bind
%ifdef LINUX_M1_CHROMIUM_SMOKE
    call linux_find_chromium_resource_alias
    jnc .open_chromium_resource_pop_lookup
%endif
    call linux_find_library_alias
    jnc .open_library_alias_pop_lookup

.open_synthetic_dir_skip:
    pop ebx
    mov eax, ebx
    mov ebx, user_path_primary_asset_end - user_path_primary_asset
    mov edi, user_path_primary_asset
    call user_path_equals
    jc .open_writable
    ; The primary readonly asset is protected; user reads go through the
    ; same readonly descriptor path as other root files.
    jmp .open_generic_parse_root83

.open_synthetic_dir_pop_bind:
    pop ebx
    call fd_alloc
    jc .bad_syscall_emfile
    mov byte [fd_kinds + eax], FD_KIND_DIRECTORY
    mov dword [fd_indices + eax * 4], LINUX_SYNTHETIC_DIR_CLUSTER
    mov dword [fd_offsets + eax * 4], 0
    mov dword [fd_file_sizes + eax * 4], 0
    mov edx, [syscall_open_flags]
    mov [fd_flags + eax * 4], edx
    push eax
    mov eax, user_io_open_count
    call user_io_increment_current
    pop eax
    add eax, USER_FD_BASE
    jmp .return

.open_library_alias_pop_lookup:
    pop ebx
    call linux_find_library_alias_entry
    jc .bad_syscall_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jnz .bad_syscall_eisdir
    jmp .open_generic_bind_readonly

.open_proc_self_exe_pop_lookup:
    pop ebx
    mov eax, [syscall_open_flags]
    test eax, O_WRONLY | O_RDWR | O_CREAT | O_TRUNC | O_APPEND
    jnz .bad_syscall_eacces
    call linux_find_proc_self_exe_entry
    jc .bad_syscall_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jnz .bad_syscall_eisdir
    jmp .open_generic_bind_readonly

%ifdef LINUX_M1_CHROMIUM_SMOKE
.open_synthetic_file_pop_bind:
    pop ebx
    mov [linux_synthetic_file_id_arg], eax
    mov eax, [syscall_open_flags]
    test eax, O_WRONLY | O_RDWR | O_CREAT | O_TRUNC | O_APPEND
    jnz .bad_syscall_eacces
    mov eax, [linux_synthetic_file_id_arg]
    call linux_synthetic_file_info
    jc .bad_syscall_enoent
    call fd_alloc
    jc .bad_syscall_emfile
    mov byte [fd_kinds + eax], FD_KIND_SYNTHETIC_FILE
    mov edx, [linux_synthetic_file_id_arg]
    mov [fd_indices + eax * 4], edx
    mov dword [fd_offsets + eax * 4], 0
    mov [fd_file_sizes + eax * 4], ecx
    mov edx, [syscall_open_flags]
    mov [fd_flags + eax * 4], edx
    push eax
    mov eax, user_io_open_count
    call user_io_increment_current
    pop eax
    add eax, USER_FD_BASE
    jmp .return
%endif

%ifdef LINUX_M1_CHROMIUM_SMOKE
.open_chromium_resource_pop_lookup:
    pop ebx
    call linux_find_chromium_resource_alias_entry
    jc .bad_syscall_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jnz .bad_syscall_eisdir
    jmp .open_generic_bind_readonly
%endif

.open_dev_null_pop_bind:
    pop ebx
    call fd_alloc
    jc .bad_syscall_emfile
    mov byte [fd_kinds + eax], FD_KIND_DEV_NULL
    mov dword [fd_indices + eax * 4], 0
    mov dword [fd_offsets + eax * 4], 0
    mov dword [fd_file_sizes + eax * 4], 0
    mov edx, [syscall_open_flags]
    mov [fd_flags + eax * 4], edx
    push eax
    mov eax, user_io_open_count
    call user_io_increment_current
    pop eax
    add eax, USER_FD_BASE
    jmp .return

.open_dev_zero_pop_bind:
    pop ebx
    call fd_alloc
    jc .bad_syscall_emfile
    mov byte [fd_kinds + eax], FD_KIND_DEV_ZERO
    mov dword [fd_indices + eax * 4], 0
    mov dword [fd_offsets + eax * 4], 0
    mov dword [fd_file_sizes + eax * 4], 0
    mov edx, [syscall_open_flags]
    mov [fd_flags + eax * 4], edx
    push eax
    mov eax, user_io_open_count
    call user_io_increment_current
    pop eax
    add eax, USER_FD_BASE
    jmp .return

.open_dev_urandom_pop_bind:
    pop ebx
    call fd_alloc
    jc .bad_syscall_emfile
    mov byte [fd_kinds + eax], FD_KIND_DEV_URANDOM
    mov dword [fd_indices + eax * 4], 0
    mov dword [fd_offsets + eax * 4], 0
    mov dword [fd_file_sizes + eax * 4], 0
    mov edx, [syscall_open_flags]
    mov [fd_flags + eax * 4], edx
    push eax
    mov eax, user_io_open_count
    call user_io_increment_current
    pop eax
    add eax, USER_FD_BASE
    jmp .return

.open_writable:
    xor edx, edx

.open_writable_loop:
    cmp edx, WRITABLE_KNOWN_FILE_COUNT
    jae .open_generic_root83
    mov eax, [syscall_ptr_arg]
    mov ebx, [writable_path_len_table + edx * 4]
    mov edi, [writable_path_table + edx * 4]
    push edx
    call user_path_equals
    pop edx
    jnc .open_writable_found
    inc edx
    jmp .open_writable_loop

.open_writable_found:
    cmp byte [writable_status + edx], 1
    je .open_writable_ready
    test dword [syscall_open_flags], O_CREAT
    jz .bad_syscall_enoent
    mov edi, [writable_name_table + edx * 4]
    push edx
    call fat_find_file
    pop edx
    jnc .open_writable_bind_known
    mov edi, [writable_name_table + edx * 4]
    push edx
    call fat_create_root_file
    pop edx
    jc .bad_syscall_enomem

.open_writable_bind_known:
    mov ebx, edx
    call fat_bind_found_to_writable_slot
    jc .bad_syscall_enomem

.open_writable_ready:
    mov [fat_open_slot], edx
    call fd_alloc
    jc .bad_syscall_emfile
    mov [file_io_fd_slot], eax
    test dword [syscall_open_flags], O_TRUNC
    jz .open_writable_bind_reserved
    mov eax, [fat_open_slot]
    cmp eax, WRITABLE_KNOWN_FILE_COUNT
    jae .open_writable_refresh_generic
    call fat_refresh_known_writable_slot
    jc .open_writable_reserved_eio
    jmp .open_writable_truncate

.open_writable_refresh_generic:
    call fat_cache_table
    jc .open_writable_reserved_eio

.open_writable_truncate:
    mov eax, [fat_open_slot]
    call fat_truncate_writable_file
    jc .open_writable_reserved_eio

.open_writable_bind_reserved:
    mov eax, [file_io_fd_slot]
    mov byte [fd_kinds + eax], FD_KIND_WRITABLE
    mov edx, [fat_open_slot]
    mov [fd_indices + eax * 4], edx
    mov dword [fd_offsets + eax * 4], 0
    test dword [syscall_open_flags], O_APPEND
    jz .open_writable_bind_flags
    mov ecx, [writable_sizes + edx * 4]
    mov [fd_offsets + eax * 4], ecx

.open_writable_bind_flags:
    mov ecx, [syscall_open_flags]
    mov [fd_flags + eax * 4], ecx
    add eax, USER_FD_BASE
    jmp .return

.open_writable_reserved_eio:
    mov ebx, [file_io_fd_slot]
    call fd_clear_slot
    jmp .bad_syscall_eio

.open_generic_root83:
    test dword [syscall_open_flags], O_WRONLY | O_RDWR | O_CREAT | O_TRUNC | O_APPEND
    jz .open_generic_try_subdir_readonly
    call fat_parse_user_subdir_file83
    jnc .open_generic_subdir_writable
    jmp .open_generic_parse_root83

.open_generic_subdir_writable:
    mov edi, fat_subdir_name_buffer
    call fat_find_root_entry_any
    jc .bad_syscall_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jz .bad_syscall_enotdir
    test byte [fat_found_attributes], FAT_ATTR_READ_ONLY
    jnz .bad_syscall_eacces
    mov ax, [fat_found_first_cluster]
    cmp ax, 2
    jb .bad_syscall_eio
    mov [fat_parent_dir_cluster], ax
    mov edi, fat_open_name_buffer
    call fat_find_subdir_entry
    jnc .open_generic_subdir_found
    test dword [syscall_open_flags], O_CREAT
    jz .bad_syscall_enoent
    mov ax, [fat_parent_dir_cluster]
    mov edi, fat_open_name_buffer
    call fat_create_subdir_file
    jc .bad_syscall_enomem

.open_generic_subdir_found:
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jnz .bad_syscall_eisdir
    test byte [fat_found_attributes], FAT_ATTR_READ_ONLY
    jnz .bad_syscall_eacces
    call fat_bind_found_writable_slot
    jc .bad_syscall_enomem
    mov edx, [fat_open_slot]
    jmp .open_writable_ready

.open_generic_try_subdir_readonly:
    call fat_parse_user_subdir_file83
    jc .open_generic_parse_root83
    mov edi, fat_subdir_name_buffer
    call fat_find_root_entry_any
    jc .bad_syscall_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jz .bad_syscall_enotdir
    mov ax, [fat_found_first_cluster]
    cmp ax, 2
    jb .bad_syscall_eio
    mov edi, fat_open_name_buffer
    call fat_find_subdir_entry
    jc .bad_syscall_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jnz .bad_syscall_eisdir
    test byte [fat_found_attributes], FAT_ATTR_READ_ONLY
    jz .open_generic_found_writable
    jmp .open_generic_bind_readonly

.open_generic_bind_readonly:
    call fd_alloc
    jc .bad_syscall_emfile
    mov byte [fd_kinds + eax], FD_KIND_READONLY_FILE
    movzx edx, word [fat_found_first_cluster]
    mov [fd_indices + eax * 4], edx
    mov dword [fd_offsets + eax * 4], 0
    mov edx, [syscall_open_flags]
    mov [fd_flags + eax * 4], edx
    mov edx, [fat_found_size]
    mov [fd_file_sizes + eax * 4], edx
    push eax
    mov eax, user_io_open_count
    call user_io_increment_current
    movzx ecx, word [fat_found_first_cluster]
    mov edx, ecx
    mov eax, user_io_last_open_cluster
    call user_io_store_current
    mov edx, [fat_found_size]
    mov eax, user_io_last_open_size
    call user_io_store_current
    pop eax
    add eax, USER_FD_BASE
    jmp .return

.open_generic_parse_root83:
    call fat_parse_user_root83
    jc .open_generic_parse_root83_failed
    mov edi, fat_open_name_buffer
    call fat_find_root_entry_any
    jnc .open_generic_found
    test dword [syscall_open_flags], O_CREAT
    jz .bad_syscall_enoent
    call fat_open_name_is_protected
    jc .bad_syscall_eacces
    mov edi, fat_open_name_buffer
    call fat_create_root_file
    jc .bad_syscall_enomem

.open_generic_found:
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jnz .bad_syscall_eisdir
    call fat_open_name_is_protected
    jc .open_generic_found_protected
    test byte [fat_found_attributes], FAT_ATTR_READ_ONLY
    jz .open_generic_found_writable
    test dword [syscall_open_flags], O_WRONLY | O_RDWR | O_CREAT | O_TRUNC | O_APPEND
    jnz .bad_syscall_eacces
    jmp .open_generic_bind_readonly

.open_generic_found_protected:
    test dword [syscall_open_flags], O_WRONLY | O_RDWR | O_CREAT | O_TRUNC | O_APPEND
    jnz .bad_syscall_eacces
    jmp .open_generic_bind_readonly

.open_generic_parse_root83_failed:
    mov eax, [current_process_ptr]
    cmp eax, 0
    je .bad_syscall_einval
    cmp dword [eax + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .bad_syscall_einval
    mov eax, [syscall_ptr_arg]
    mov ebx, 1
    call user_range_validate
    jc .bad_syscall_einval
    cmp byte [eax], '/'
    je .bad_syscall_enoent
    jmp .bad_syscall_einval

.open_generic_found_writable:
    call fat_bind_found_writable_slot
    jc .bad_syscall_enomem
    mov edx, [fat_open_slot]
    jmp .open_writable_ready

.read:
    mov eax, vfs_read_count
    call .vfs_count_generic
    call fd_lookup
    jc .bad_syscall_ebadf
    cmp byte [fd_kinds + eax], FD_KIND_PRIMARY_ASSET
    je .read_primary_asset
    cmp byte [fd_kinds + eax], FD_KIND_READONLY_FILE
    je .read_readonly_file
    cmp byte [fd_kinds + eax], FD_KIND_PIPE_READ
    je .read_pipe
    cmp byte [fd_kinds + eax], FD_KIND_DEV_NULL
    je .read_dev_null
    cmp byte [fd_kinds + eax], FD_KIND_DEV_ZERO
    je .read_dev_zero
    cmp byte [fd_kinds + eax], FD_KIND_DEV_URANDOM
    je .read_dev_urandom
%ifdef LINUX_M1_CHROMIUM_SMOKE
    cmp byte [fd_kinds + eax], FD_KIND_SYNTHETIC_FILE
    je .read_synthetic_file
%endif
    cmp byte [fd_kinds + eax], FD_KIND_EVENTFD
    je .read_eventfd
    cmp byte [fd_kinds + eax], FD_KIND_TIMERFD
    je .read_timerfd
    call user_file_read
    jc .bad_syscall_from_eax
    jmp .return

.read_eventfd:
    call eventfd_read
    jc .bad_syscall_from_eax
    jmp .return

.read_timerfd:
    call timerfd_read
    jc .bad_syscall_from_eax
    jmp .return

.read_dev_zero:
    call linux_dev_zero_read
    jmp .return

.read_dev_urandom:
    call linux_dev_urandom_read
    jmp .return

%ifdef LINUX_M1_CHROMIUM_SMOKE
.read_synthetic_file:
    call linux_synthetic_file_read
    jmp .return
%endif

.read_dev_null:
    mov esi, [file_io_fd_slot]
    mov eax, [fd_flags + esi * 4]
    and eax, O_ACCMODE
    cmp eax, O_WRONLY
    je .bad_syscall_ebadf
    xor eax, eax
    jmp .return

.read_pipe:
    call pipe_read
    jc .bad_syscall_from_eax
    jmp .return

.read_readonly_file:
    call readonly_file_read
    jc .bad_syscall_from_eax
    jmp .return

.read_primary_asset:
    mov [syscall_ptr_arg], ecx
    mov [syscall_len_arg], edx
    mov eax, ecx
    mov ebx, edx
    call user_range_validate
    jc .bad_syscall_einval
    mov eax, [primary_asset_size]
    mov esi, [file_io_fd_slot]
    mov ecx, [fd_offsets + esi * 4]
    mov [file_io_start_offset], ecx
    sub eax, [fd_offsets + esi * 4]
    cmp edx, eax
    jbe .read_len_ok
    mov edx, eax
    mov [syscall_len_arg], edx

.read_len_ok:
    mov esi, PRIMARY_ASSET_LOAD_ADDR
    mov eax, [file_io_fd_slot]
    add esi, [fd_offsets + eax * 4]
    mov edi, [syscall_ptr_arg]
    mov ecx, [syscall_len_arg]
    cld
    rep movsb
    mov eax, [syscall_len_arg]
    mov esi, [file_io_fd_slot]
    add [fd_offsets + esi * 4], eax
    cmp dword [file_io_start_offset], 0
    jne .read_done
    cmp eax, 4
    jb .read_done
    mov edi, [syscall_ptr_arg]
    mov edx, [edi]
    mov [user_primary_asset_magic_seen], edx
    cmp dword [payload_primary_asset_magic_seen], 0
    jne .read_done
    mov [payload_primary_asset_magic_seen], edx

.read_done:
    cmp eax, 0
    je .read_return
    push eax
    mov eax, user_io_read_count
    call user_io_increment_current
    pop eax

.read_return:
    jmp .return

.lseek:
    mov eax, vfs_lseek_count
    call .vfs_count_generic
    call fd_lookup
    jc .bad_syscall_ebadf
    cmp byte [fd_kinds + eax], FD_KIND_PRIMARY_ASSET
    je .lseek_primary_asset
    cmp byte [fd_kinds + eax], FD_KIND_READONLY_FILE
    je .lseek_readonly_file
%ifdef LINUX_M1_CHROMIUM_SMOKE
    cmp byte [fd_kinds + eax], FD_KIND_SYNTHETIC_FILE
    je .lseek_synthetic_file
%endif
    call user_file_lseek
    jc .bad_syscall_from_eax
    jmp .return

%ifdef LINUX_M1_CHROMIUM_SMOKE
.lseek_synthetic_file:
    cmp edx, 0
    je .seek_set_synthetic
    cmp edx, 1
    je .seek_cur_synthetic
    cmp edx, 2
    je .seek_end_synthetic
    jmp .bad_syscall_einval

.seek_set_synthetic:
    mov eax, ecx
    test eax, 0x80000000
    jnz .bad_syscall_einval
    jmp .seek_validate_synthetic

.seek_cur_synthetic:
    mov esi, [file_io_fd_slot]
    mov eax, [fd_offsets + esi * 4]
    add eax, ecx
    jo .bad_syscall_einval
    test eax, 0x80000000
    jnz .bad_syscall_einval
    jmp .seek_validate_synthetic

.seek_end_synthetic:
    mov esi, [file_io_fd_slot]
    mov eax, [fd_file_sizes + esi * 4]
    add eax, ecx
    jo .bad_syscall_einval
    test eax, 0x80000000
    jnz .bad_syscall_einval
    jmp .seek_validate_synthetic

.seek_validate_synthetic:
    mov esi, [file_io_fd_slot]
    cmp eax, [fd_file_sizes + esi * 4]
    ja .bad_syscall_einval
    mov [fd_offsets + esi * 4], eax
    push eax
    mov eax, user_io_lseek_count
    call user_io_increment_current
    pop eax
    jmp .return
%endif

.lseek_readonly_file:
    call readonly_file_lseek
    jc .bad_syscall_from_eax
    jmp .return

.lseek_primary_asset:
    cmp edx, 0
    je .seek_set
    cmp edx, 1
    je .seek_cur
    cmp edx, 2
    je .seek_end
    jmp .bad_syscall_einval

.seek_set:
    mov eax, ecx
    test eax, 0x80000000
    jnz .bad_syscall_einval
    jmp .seek_validate

.seek_cur:
    mov esi, [file_io_fd_slot]
    mov eax, [fd_offsets + esi * 4]
    add eax, ecx
    jo .bad_syscall_einval
    test eax, 0x80000000
    jnz .bad_syscall_einval
    jmp .seek_validate

.seek_end:
    mov eax, [primary_asset_size]
    add eax, ecx
    jo .bad_syscall_einval
    test eax, 0x80000000
    jnz .bad_syscall_einval

.seek_validate:
    cmp eax, [primary_asset_size]
    ja .bad_syscall_einval
    mov esi, [file_io_fd_slot]
    mov [fd_offsets + esi * 4], eax
    push eax
    mov eax, user_io_lseek_count
    call user_io_increment_current
    pop eax

.seek_return:
    jmp .return

.time:
    mov eax, [clock_compat35_ticks]
    jmp .return

.clock_gettime:
    cmp ebx, CLOCK_MONOTONIC_ID
    jne .bad_syscall_einval
    cmp edx, CLOCK_TIME_BYTES
    jb .bad_syscall_einval
    mov [syscall_ptr_arg], ecx
    mov eax, ecx
    mov ebx, CLOCK_TIME_BYTES
    call user_range_validate
    jc .bad_syscall_einval
    mov edi, [syscall_ptr_arg]
    call clock_write_monotonic_time
    xor eax, eax
    jmp .return

.present:
    mov [present_frame_arg], ebx
    mov [present_palette_arg], ecx
    mov dword [present_width_arg], FB_PRESENT_WIDTH
    mov dword [present_height_arg], FB_PRESENT_HEIGHT
    mov dword [present_frame_bytes_arg], FB_PRESENT_FRAME_BYTES
    mov eax, ebx
    mov ebx, FB_PRESENT_FRAME_BYTES
    call user_range_validate
    jnc .present_frame_valid
    inc dword [framebuffer_present_bad_range_count]
    jmp .bad_syscall_einval

.present_frame_valid:
    mov eax, [present_palette_arg]
    mov ebx, FB_PRESENT_PALETTE_BYTES
    call user_range_validate
    jnc .present_palette_valid
    inc dword [framebuffer_present_bad_range_count]
    jmp .bad_syscall_einval

.present_palette_valid:
    call present_indexed_frame
    jnc .present_success
    inc dword [framebuffer_present_failure_count]
    jmp .bad_syscall_eio

.present_success:
    mov eax, FRAMEBUFFER_PRESENT_SOURCE_SYS
    call framebuffer_record_present_success
    mov eax, payload_telemetry_present_count
    call payload_telemetry_increment_current
    xor eax, eax
    jmp .return

.poll_key:
    pushfd
    cli
    mov ebx, [key_event_tail]
    cmp ebx, [key_event_head]
    je .poll_key_empty_locked
    mov edi, key_event_queue
    mov eax, [edi + ebx * 4]
    inc ebx
    and ebx, KEY_QUEUE_MASK
    mov [key_event_tail], ebx
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_PRIMARY
    jne .poll_key_return
    call payload_primary_record_key_event
    inc dword [payload_primary_key_event_count]

.poll_key_return:
    popfd
    jmp .return

.poll_key_empty_locked:
    popfd
    xor eax, eax
    jmp .return

.poll_mouse:
    pushfd
    cli
    mov ebx, [mouse_event_tail]
    cmp ebx, [mouse_event_head]
    je .poll_mouse_empty_locked
    mov edi, mouse_event_queue
    mov eax, [edi + ebx * 4]
    inc ebx
    and ebx, MOUSE_QUEUE_MASK
    mov [mouse_event_tail], ebx
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_PRIMARY
    jne .poll_mouse_return
    call payload_primary_record_mouse_event
    inc dword [payload_primary_mouse_event_count]

.poll_mouse_return:
    popfd
    jmp .return

.poll_mouse_empty_locked:
    popfd
    xor eax, eax
    jmp .return

.poll_input:
    mov [syscall_ptr_arg], ebx
    cmp ecx, VIBE_INPUT_EVENT_BYTES
    jb .bad_syscall_einval
    mov eax, ebx
    mov ebx, VIBE_INPUT_EVENT_BYTES
    call user_range_validate
    jc .bad_syscall_einval
    pushfd
    cli
    mov ebx, [input_event_tail]
    cmp ebx, [input_event_head]
    je .poll_input_empty_locked
    mov esi, input_event_queue
    mov edx, ebx
    imul edx, VIBE_INPUT_EVENT_BYTES
    add esi, edx
    push esi
    mov edi, [syscall_ptr_arg]
    mov ecx, VIBE_INPUT_EVENT_DWORDS
    cld
    rep movsd
    pop esi
    inc ebx
    and ebx, INPUT_EVENT_QUEUE_MASK
    mov [input_event_tail], ebx
    inc dword [input_event_poll_count]
    mov edx, [esi + VIBE_INPUT_EVENT_DEVICE_ID]
    cmp edx, VIBE_INPUT_DEVICE_KEYBOARD
    je .poll_input_count_keyboard
    cmp edx, VIBE_INPUT_DEVICE_MOUSE
    je .poll_input_count_mouse
    jmp .poll_input_count_done

    .poll_input_count_keyboard:
    inc dword [input_keyboard_poll_count]
    jmp .poll_input_count_done

    .poll_input_count_mouse:
    inc dword [input_mouse_poll_count]

.poll_input_count_done:
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_PRIMARY
    jne .poll_input_return_one
    call payload_primary_record_input_event

.poll_input_return_one:
    mov eax, INPUT_ABI_POLL_EVENT
    mov ecx, 1
    call input_record_generic_abi
    mov eax, 1
    popfd
    jmp .return

.poll_input_empty_locked:
    popfd
    mov eax, INPUT_ABI_POLL_EVENT
    xor ecx, ecx
    call input_record_generic_abi
    xor eax, eax
    jmp .return

.input_status:
    mov [syscall_ptr_arg], ebx
    cmp ecx, VIBE_INPUT_STATUS_BYTES
    jb .bad_syscall_einval
    mov eax, ebx
    mov ebx, VIBE_INPUT_STATUS_BYTES
    call user_range_validate
    jc .bad_syscall_einval
    pushfd
    cli
    mov edi, [syscall_ptr_arg]
    mov dword [edi + VIBE_INPUT_STATUS_ABI_VERSION], VIBE_INPUT_ABI_VERSION
    mov dword [edi + VIBE_INPUT_STATUS_EVENT_BYTES], VIBE_INPUT_EVENT_BYTES
    mov dword [edi + VIBE_INPUT_STATUS_QUEUE_CAPACITY], INPUT_EVENT_QUEUE_SIZE
    mov eax, [input_event_head]
    sub eax, [input_event_tail]
    and eax, INPUT_EVENT_QUEUE_MASK
    mov [edi + VIBE_INPUT_STATUS_QUEUED_EVENTS], eax
    mov eax, [input_event_count]
    mov [edi + VIBE_INPUT_STATUS_TOTAL_EVENTS], eax
    mov eax, [input_event_poll_count]
    mov [edi + VIBE_INPUT_STATUS_POLLED_EVENTS], eax
    mov eax, [input_event_drop_count]
    mov [edi + VIBE_INPUT_STATUS_DROPPED_EVENTS], eax
    mov eax, VIBE_INPUT_CAP_POLL_EVENT | VIBE_INPUT_CAP_STATUS | VIBE_INPUT_CAP_DEVICE_STATUS
    cmp byte [keyboard_status], INPUT_DEVICE_STATUS_READY
    jne .input_status_keyboard_cap_done
    or eax, VIBE_INPUT_CAP_KEYBOARD

.input_status_keyboard_cap_done:
    cmp byte [mouse_status], INPUT_DEVICE_STATUS_READY
    jne .input_status_caps_done
    or eax, VIBE_INPUT_CAP_MOUSE

.input_status_caps_done:
    mov [edi + VIBE_INPUT_STATUS_CAPABILITIES], eax
    mov eax, [keyboard_irq_count]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_IRQ_COUNT], eax
    mov eax, [keyboard_event_count]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_EVENT_COUNT], eax
    mov eax, [input_keyboard_down_count]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_DOWN_COUNT], eax
    mov eax, [input_keyboard_last_code]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_LAST_CODE], eax
    mov eax, [input_keyboard_state + 0]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_STATE + 0], eax
    mov eax, [input_keyboard_state + 4]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_STATE + 4], eax
    mov eax, [input_keyboard_state + 8]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_STATE + 8], eax
    mov eax, [input_keyboard_state + 12]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_STATE + 12], eax
    mov eax, [input_keyboard_state + 16]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_STATE + 16], eax
    mov eax, [input_keyboard_state + 20]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_STATE + 20], eax
    mov eax, [input_keyboard_state + 24]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_STATE + 24], eax
    mov eax, [input_keyboard_state + 28]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_STATE + 28], eax
    mov eax, [mouse_irq_count]
    mov [edi + VIBE_INPUT_STATUS_MOUSE_IRQ_COUNT], eax
    mov eax, [mouse_packet_count]
    mov [edi + VIBE_INPUT_STATUS_MOUSE_PACKET_COUNT], eax
    mov eax, [mouse_sync_loss_count]
    mov [edi + VIBE_INPUT_STATUS_MOUSE_SYNC_LOSS_COUNT], eax
    mov eax, [input_mouse_buttons]
    mov [edi + VIBE_INPUT_STATUS_MOUSE_BUTTONS], eax
    mov eax, [input_mouse_delta_x_total]
    mov [edi + VIBE_INPUT_STATUS_MOUSE_DELTA_X_TOTAL], eax
    mov eax, [input_mouse_delta_y_total]
    mov [edi + VIBE_INPUT_STATUS_MOUSE_DELTA_Y_TOTAL], eax
    mov eax, [input_last_event_device]
    mov [edi + VIBE_INPUT_STATUS_LAST_EVENT_DEVICE_ID], eax
    mov eax, [input_last_event_type]
    mov [edi + VIBE_INPUT_STATUS_LAST_EVENT_TYPE], eax
    mov dword [edi + VIBE_INPUT_STATUS_STATUS_BYTES], VIBE_INPUT_STATUS_BYTES
    mov dword [edi + VIBE_INPUT_STATUS_QUEUE_USABLE_CAPACITY], VIBE_INPUT_EVENT_QUEUE_USABLE_CAPACITY
    mov dword [edi + VIBE_INPUT_STATUS_OVERFLOW_POLICY], VIBE_INPUT_QUEUE_OVERFLOW_DROP_OLDEST
    movzx eax, byte [keyboard_status]
    mov [edi + VIBE_INPUT_STATUS_KEYBOARD_STATUS], eax
    movzx eax, byte [mouse_status]
    mov [edi + VIBE_INPUT_STATUS_MOUSE_STATUS], eax
    mov eax, INPUT_ABI_STATUS
    xor ecx, ecx
    call input_record_generic_abi
    xor eax, eax
    popfd
    jmp .return

    .input_device_status:
    mov [input_device_status_arg], ebx
    mov [syscall_ptr_arg], ecx
    cmp edx, VIBE_INPUT_DEVICE_STATUS_BYTES
    jb .bad_syscall_einval
    mov eax, ecx
    mov ebx, VIBE_INPUT_DEVICE_STATUS_BYTES
    call user_range_validate
    jc .bad_syscall_einval
    mov edi, [syscall_ptr_arg]
    mov eax, [input_device_status_arg]
    cmp eax, VIBE_INPUT_DEVICE_KEYBOARD
    je .input_device_status_lock
    cmp eax, VIBE_INPUT_DEVICE_MOUSE
    je .input_device_status_lock
    jmp .bad_syscall_einval

    .input_device_status_lock:
    pushfd
    cli
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_ABI_VERSION], VIBE_INPUT_ABI_VERSION
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_STATUS_BYTES], VIBE_INPUT_DEVICE_STATUS_BYTES
    cmp eax, VIBE_INPUT_DEVICE_KEYBOARD
    je .input_device_status_keyboard
    jmp .input_device_status_mouse

    .input_device_status_keyboard:
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_DEVICE_ID], VIBE_INPUT_DEVICE_KEYBOARD
    movzx eax, byte [keyboard_status]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_STATUS], eax
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_CAPABILITIES], VIBE_INPUT_DEVICE_CAP_KEYS | VIBE_INPUT_DEVICE_CAP_STATE_SNAPSHOT
    mov eax, [keyboard_irq_count]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_IRQ_COUNT], eax
    mov eax, [keyboard_event_count]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_EVENT_COUNT], eax
    mov eax, [input_keyboard_poll_count]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_POLLED_EVENTS], eax
    mov eax, [input_keyboard_drop_count]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_DROPPED_EVENTS], eax
    mov eax, [input_keyboard_last_timestamp]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_LAST_TIMESTAMP], eax
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_LAST_EVENT_TYPE], VIBE_INPUT_EVENT_KEY
    mov eax, [input_keyboard_last_code]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_LAST_CODE], eax
    mov eax, [input_keyboard_modifiers]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_ACTIVE_STATE], eax
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_AXIS_X_TOTAL], 0
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_AXIS_Y_TOTAL], 0
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_RESERVED0], 0
    mov eax, INPUT_ABI_KEYBOARD_STATUS
    xor ecx, ecx
    call input_record_generic_abi
    xor eax, eax
    popfd
    jmp .return

    .input_device_status_mouse:
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_DEVICE_ID], VIBE_INPUT_DEVICE_MOUSE
    movzx eax, byte [mouse_status]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_STATUS], eax
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_CAPABILITIES], VIBE_INPUT_DEVICE_CAP_RELATIVE_POINTER | VIBE_INPUT_DEVICE_CAP_BUTTONS | VIBE_INPUT_DEVICE_CAP_STATE_SNAPSHOT
    mov eax, [mouse_irq_count]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_IRQ_COUNT], eax
    mov eax, [input_mouse_event_count]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_EVENT_COUNT], eax
    mov eax, [input_mouse_poll_count]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_POLLED_EVENTS], eax
    mov eax, [input_mouse_drop_count]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_DROPPED_EVENTS], eax
    mov eax, [input_mouse_last_timestamp]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_LAST_TIMESTAMP], eax
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_LAST_EVENT_TYPE], VIBE_INPUT_EVENT_MOUSE_PACKET
    mov eax, [input_mouse_buttons]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_LAST_CODE], eax
    mov [edi + VIBE_INPUT_DEVICE_STATUS_ACTIVE_STATE], eax
    mov eax, [input_mouse_delta_x_total]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_AXIS_X_TOTAL], eax
    mov eax, [input_mouse_delta_y_total]
    mov [edi + VIBE_INPUT_DEVICE_STATUS_AXIS_Y_TOTAL], eax
    mov dword [edi + VIBE_INPUT_DEVICE_STATUS_RESERVED0], 0
    mov eax, INPUT_ABI_MOUSE_STATUS
    xor ecx, ecx
    call input_record_generic_abi
    xor eax, eax
    popfd
    jmp .return

    .close:
    mov eax, vfs_close_count
    call .vfs_count_generic
    call fd_lookup_descriptor
    jc .bad_syscall_ebadf
    mov ebx, eax
    call fd_close_slot

.close_ok:
    mov eax, user_io_close_count
    call user_io_increment_current
    xor eax, eax
    jmp .return

.dup:
    inc dword [fd_dup_calls]
    call fd_lookup_descriptor
    jc .bad_syscall_ebadf
    mov esi, eax
    mov ebx, [fd_description_roots + esi * 4]
    cmp ebx, USER_FD_COUNT
    jae .bad_syscall_ebadf
    cmp byte [fd_status + ebx], FD_STATUS_OPEN
    jne .bad_syscall_ebadf
    cmp dword [fd_refcounts + ebx * 4], 0
    je .bad_syscall_ebadf
    mov [fd_dup_root_slot], ebx
    call fd_alloc
    jc .bad_syscall_emfile
    mov edi, eax
    mov ebx, [fd_dup_root_slot]
    mov edx, FD_INHERIT_EXEC
    call fd_clone_descriptor
    mov eax, esi
    add eax, USER_FD_BASE
    mov [fd_last_dup_source], eax
    mov eax, edi
    add eax, USER_FD_BASE
    mov [fd_last_dup_target], eax
    jmp .return

.dup2:
    inc dword [fd_dup2_calls]
    mov dword [fd_dup_flags_arg], FD_INHERIT_EXEC
    jmp .dup_to_fd

.dup3:
    inc dword [fd_dup3_calls]
    mov eax, edx
    and eax, 0xfffff7ff
    jnz .bad_syscall_einval
    cmp ebx, ecx
    je .bad_syscall_einval
    mov dword [fd_dup_flags_arg], FD_INHERIT_EXEC
    test edx, O_CLOEXEC
    jz .dup_to_fd
    mov dword [fd_dup_flags_arg], 0

.dup_to_fd:
    call fd_lookup_descriptor
    jc .bad_syscall_ebadf
    mov esi, eax
    mov eax, ecx
    sub eax, USER_FD_BASE
    cmp eax, USER_FD_COUNT
    jae .bad_syscall_ebadf
    mov edi, eax
    cmp edi, esi
    je .dup_same_fd
    cmp byte [fd_status + edi], FD_STATUS_FREE
    je .dup_target_ready
    cmp byte [fd_status + edi], FD_STATUS_OPEN
    jne .bad_syscall_ebadf
    mov eax, [current_pid]
    cmp [fd_owner_pids + edi * 4], eax
    jne .bad_syscall_ebadf
    mov ebx, edi
    call fd_close_slot

.dup_target_ready:
    cmp byte [fd_status + esi], FD_STATUS_OPEN
    jne .bad_syscall_ebadf
    mov eax, [current_pid]
    cmp [fd_owner_pids + esi * 4], eax
    jne .bad_syscall_ebadf
    mov ebx, [fd_description_roots + esi * 4]
    cmp ebx, USER_FD_COUNT
    jae .bad_syscall_ebadf
    cmp byte [fd_status + ebx], FD_STATUS_OPEN
    jne .bad_syscall_ebadf
    cmp dword [fd_refcounts + ebx * 4], 0
    je .bad_syscall_ebadf
    mov [fd_dup_root_slot], ebx
    mov ebx, edi
    call fd_prepare_current_descriptor
    mov ebx, [fd_dup_root_slot]
    mov edx, [fd_dup_flags_arg]
    call fd_clone_descriptor
    cmp dword [fd_dup_flags_arg], 0
    jne .dup_record_result
    inc dword [fd_dup_cloexec]

.dup_record_result:
    mov eax, esi
    add eax, USER_FD_BASE
    mov [fd_last_dup_source], eax
    mov eax, edi
    add eax, USER_FD_BASE
    mov [fd_last_dup_target], eax
    jmp .return

.dup_same_fd:
    mov eax, ecx
    jmp .return

.fcntl:
    call fd_lookup_descriptor
    jc .bad_syscall_ebadf
    mov esi, eax
    cmp ecx, F_GETFD
    je .fcntl_getfd
    cmp ecx, F_SETFD
    je .fcntl_setfd
    jmp .bad_syscall_einval

.fcntl_getfd:
    mov eax, [fd_inherit_flags + esi * 4]
    test eax, FD_INHERIT_EXEC
    jz .fcntl_getfd_cloexec
    xor eax, eax
    jmp .return

.fcntl_getfd_cloexec:
    mov eax, FD_CLOEXEC
    jmp .return

.fcntl_setfd:
    mov eax, edx
    and eax, 0xfffffffe
    jnz .bad_syscall_einval
    test edx, FD_CLOEXEC
    jz .fcntl_setfd_inherit
    mov dword [fd_inherit_flags + esi * 4], 0
    xor eax, eax
    jmp .return

.fcntl_setfd_inherit:
    mov dword [fd_inherit_flags + esi * 4], FD_INHERIT_EXEC
    xor eax, eax
    jmp .return

.process_status:
    call process_status_current
    jc .bad_syscall_from_eax
    jmp .return

.yield:
    inc dword [scheduler_yield_attempts]
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .yield_noop
    cmp esi, process_kernel
    je .yield_noop
    mov eax, [esi + PROC_PID]
    mov [scheduler_yield_last_from_pid], eax
    mov dword [scheduler_yield_last_to_pid], 0xffffffff
    mov dword [syscall_return_value], 0
    mov dword [esi + PROC_QUANTUM_TICKS], 0
    call process_save_syscall_return_context
    call scheduler_select_next_ready
    mov esi, [scheduler_next_process_ptr]
    cmp esi, 0
    je .yield_noop_after_save
    mov eax, [esi + PROC_PID]
    mov [scheduler_yield_last_to_pid], eax
    call process_activate
    inc dword [scheduler_yield_switches]
    mov ebx, esp
    call process_restore_syscall_context
    jmp .context_handoff_return

.yield_noop_after_save:
    inc dword [scheduler_yield_noops]
    xor eax, eax
    jmp .return

.yield_noop:
    inc dword [scheduler_yield_noops]
    xor eax, eax
    jmp .return

.sleep_ticks:
    inc dword [scheduler_sleep_attempts]
    cmp ebx, 0
    jne .sleep_nonzero
    inc dword [scheduler_sleep_noops]
    xor eax, eax
    jmp .return

.sleep_nonzero:
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .sleep_enosys
    cmp esi, process_kernel
    je .sleep_enosys
    mov eax, [timer_ticks]
    add eax, ebx
    jc .sleep_einval
    mov [scheduler_sleep_last_until], eax
    mov [scheduler_sleep_last_ticks], ebx
    mov edx, [esi + PROC_PID]
    mov [scheduler_sleep_last_pid], edx
    mov dword [syscall_return_value], 0
    mov dword [esi + PROC_QUANTUM_TICKS], 0
    call process_save_syscall_return_context
    mov edi, process_table
    xor edx, edx

.sleep_find_slot:
    cmp edx, PROCESS_SLOT_COUNT
    jae .sleep_einval
    cmp edi, esi
    je .sleep_slot_found
    add edi, PROCESS_RECORD_BYTES
    inc edx
    jmp .sleep_find_slot

.sleep_slot_found:
    mov eax, PROC_BLOCK_SLEEP_TICKS
    xor ebx, ebx
    mov ecx, [scheduler_sleep_last_until]
    xor edx, edx
    call scheduler_block_current
    jc .sleep_einval
    inc dword [scheduler_sleep_blocks]
    call scheduler_select_next_ready
    mov esi, [scheduler_next_process_ptr]
    cmp esi, 0
    je .sleep_idle_wait
    call process_activate
    mov ebx, esp
    call process_restore_syscall_context
    jmp .context_handoff_return

.sleep_idle_wait:
    sti
    hlt
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .sleep_idle_wait
    cmp dword [esi + PROC_STATE], PROC_STATE_READY
    jne .sleep_idle_wait
    call process_activate
    mov ebx, esp
    call process_restore_syscall_context
    jmp .context_handoff_return

.sleep_einval:
    inc dword [scheduler_sleep_failures]
    mov eax, -ERRNO_EINVAL
    jmp .return

.sleep_enosys:
    inc dword [scheduler_sleep_failures]
    mov eax, -ERRNO_ENOSYS
    jmp .return

.audio:
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_PRIMARY
    jne .audio_dispatch
    inc dword [payload_primary_audio_call_count]
    mov [payload_primary_audio_last_command], ebx
    mov [payload_primary_audio_last_handle], ecx
    mov [payload_primary_audio_last_packed], edx

.audio_dispatch:
    call .audio_note_generic_abi
    cmp ebx, AUDIO_CMD_INIT
    je .audio_init_cmd
    cmp ebx, AUDIO_CMD_START_SFX
    je .audio_start_sfx
    cmp ebx, AUDIO_CMD_STOP_SFX
    je .audio_stop_sfx
    cmp ebx, AUDIO_CMD_UPDATE_SFX
    je .audio_update_sfx
    cmp ebx, AUDIO_CMD_SHUTDOWN
    je .audio_shutdown_cmd
    cmp ebx, AUDIO_CMD_IS_PLAYING
    je .audio_is_playing
    cmp ebx, AUDIO_CMD_BUFFERED_BYTES
    je .audio_buffered_bytes
    cmp ebx, AUDIO_CMD_MUSIC_PULL_STATE
    je .audio_music_pull_state
    cmp ebx, AUDIO_CMD_DEVICE_INFO
    je .audio_device_info
    cmp ebx, AUDIO_CMD_PCM_RING_INFO
    je .audio_pcm_ring_info
    cmp ebx, AUDIO_CMD_STREAM_INFO
    je .audio_stream_info
    cmp ebx, AUDIO_CMD_PCM_WRITE
    je .audio_pcm_write
    cmp ebx, AUDIO_CMD_PCM_WRITE_DESC
    je .audio_pcm_write_desc
    cmp ebx, AUDIO_CMD_PCM_OPEN
    je .audio_pcm_open
    cmp ebx, AUDIO_CMD_PCM_DRAIN
    je .audio_pcm_drain
    cmp ebx, AUDIO_CMD_PCM_CLOSE
    je .audio_pcm_close
    jmp .audio_status

.audio_init_cmd:
    call sb16_start_playback
    jmp .audio_status

.audio_start_sfx:
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_PRIMARY
    jne .audio_start_counted
    inc dword [payload_primary_audio_start_count]

.audio_start_counted:
    mov [audio_sfx_handle_arg], ecx
    mov [audio_sfx_desc_arg], edx
    call sb16_start_playback
    call audio_register_sfx_voice
    jmp .audio_status

.audio_stop_sfx:
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_PRIMARY
    jne .audio_stop_counted
    inc dword [payload_primary_audio_stop_count]

.audio_stop_counted:
    mov [audio_sfx_handle_arg], ecx
    call audio_stop_sfx_voice
    jmp .audio_status

.audio_update_sfx:
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_PRIMARY
    jne .audio_update_counted
    inc dword [payload_primary_audio_update_count]

.audio_update_counted:
    mov [audio_sfx_handle_arg], ecx
    mov [audio_sfx_desc_arg], edx
    call audio_update_sfx_voice
    jmp .audio_status

.audio_pcm_write:
    mov [audio_sfx_handle_arg], ecx
    mov [audio_sfx_desc_arg], edx
    cmp byte [audio_status], 1
    jne .audio_pcm_write_eio
    cmp dword [audio_pcm_queue_buffer], 0
    je .audio_pcm_write_eio
    cmp dword [audio_pcm_queue_capacity], AUDIO_PCM_QUEUE_BYTES
    jne .audio_pcm_write_eio
    call sb16_start_playback
    jc .audio_pcm_write_eio
    call audio_pcm_stream_write

.audio_pcm_write_finish:
    jc .bad_syscall_einval
    mov eax, [audio_pcm_stream_last_write_bytes]
    jmp .return

.audio_pcm_write_eio:
    jmp .bad_syscall_eio

.audio_pcm_write_desc:
    mov [audio_sfx_handle_arg], ecx
    mov [audio_sfx_desc_arg], edx
    cmp byte [audio_status], 1
    jne .audio_pcm_write_eio
    cmp dword [audio_pcm_queue_buffer], 0
    je .audio_pcm_write_eio
    cmp dword [audio_pcm_queue_capacity], AUDIO_PCM_QUEUE_BYTES
    jne .audio_pcm_write_eio
    call sb16_start_playback
    jc .audio_pcm_write_eio
    call audio_pcm_desc_stream_write
    jmp .audio_pcm_write_finish

.audio_pcm_open:
    cmp byte [audio_status], 1
    jne .audio_pcm_write_eio
    cmp dword [audio_pcm_queue_buffer], 0
    je .audio_pcm_write_eio
    cmp dword [audio_pcm_queue_capacity], AUDIO_PCM_QUEUE_BYTES
    jne .audio_pcm_write_eio
    call sb16_start_playback
    jc .audio_pcm_write_eio
    call audio_pcm_open_stream
    jc .bad_syscall_einval
    jmp .return

.audio_pcm_drain:
    call audio_pcm_drain_stream
    jc .bad_syscall_einval
    jmp .return

.audio_pcm_close:
    call audio_pcm_close_stream
    jc .bad_syscall_einval
    jmp .return

.audio_shutdown_cmd:
    call sb16_stop_playback
    jmp .audio_status

.audio_is_playing:
    mov [audio_sfx_handle_arg], ecx
    call sb16_find_voice_by_handle
    jc .audio_check_pcm_stream_playing
    mov eax, 1
    jmp .return

.audio_check_pcm_stream_playing:
    call audio_sync_pcm_stream_state
    mov eax, [audio_pcm_stream_handle]
    cmp eax, ecx
    jne .audio_not_playing
    cmp dword [audio_pcm_stream_mode], AUDIO_STREAM_NONE
    je .audio_not_playing
    cmp dword [audio_pcm_stream_active_count], 0
    je .audio_not_playing
    mov eax, 1
    jmp .return

.audio_not_playing:
    xor eax, eax
    jmp .return

.audio_buffered_bytes:
    mov [audio_sfx_handle_arg], ecx
    call sb16_find_voice_by_handle
    jc .audio_pcm_buffered_bytes
    mov ebx, eax
    mov edx, [sb16_voice_positions + ebx * 4]
    shr edx, 16
    mov eax, [sb16_voice_lengths + ebx * 4]
    cmp eax, edx
    jbe .audio_pending_only
    sub eax, edx
    jmp .audio_add_pending

.audio_pending_only:
    xor eax, eax

.audio_add_pending:
    add eax, [sb16_voice_pending_lengths + ebx * 4]
    jmp .return

.audio_pcm_buffered_bytes:
    call audio_sync_pcm_stream_state
    mov eax, [audio_pcm_stream_handle]
    cmp eax, ecx
    jne .audio_not_playing
    mov eax, [audio_pcm_stream_queued_bytes]
    jmp .return

.audio_music_pull_state:
    mov [audio_sfx_handle_arg], ecx
    call sb16_find_voice_by_handle
    jc .audio_pcm_pull_state
    mov ebx, eax
    test dword [sb16_voice_flags + ebx * 4], AUDIO_FLAG_MUSIC
    jz .audio_pcm_pull_state
    mov eax, [sb16_music_pull_request_count]
    jmp .return

.audio_pcm_pull_state:
    call audio_sync_pcm_stream_state
    mov eax, [audio_pcm_stream_handle]
    cmp eax, ecx
    jne .audio_no_pull_state
    mov eax, [audio_pcm_stream_pull_request_count]
    jmp .return

.audio_no_pull_state:
    xor eax, eax
    jmp .return

.audio_device_info:
    call audio_write_device_info
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.audio_pcm_ring_info:
    call audio_write_pcm_ring_info
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.audio_stream_info:
    call audio_write_stream_info
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.audio_status:
    movzx eax, byte [audio_status]
    jmp .return

.audio_note_generic_abi:
    push eax
    push edx
    xor eax, eax
    cmp ebx, AUDIO_CMD_DEVICE_START
    jne .audio_note_device_info
    mov eax, AUDIO_ABI_DEVICE_START
    jmp .audio_note_record

.audio_note_device_info:
    cmp ebx, AUDIO_CMD_DEVICE_INFO
    jne .audio_note_ring_info
    mov eax, AUDIO_ABI_DEVICE_INFO
    jmp .audio_note_record

.audio_note_ring_info:
    cmp ebx, AUDIO_CMD_PCM_RING_INFO
    jne .audio_note_stream_info
    mov eax, AUDIO_ABI_PCM_RING_INFO
    jmp .audio_note_record

.audio_note_stream_info:
    cmp ebx, AUDIO_CMD_STREAM_INFO
    jne .audio_note_open
    mov eax, AUDIO_ABI_STREAM_INFO
    jmp .audio_note_record

.audio_note_open:
    cmp ebx, AUDIO_CMD_PCM_OPEN
    jne .audio_note_write
    mov eax, AUDIO_ABI_PCM_OPEN
    jmp .audio_note_record

.audio_note_write:
    cmp ebx, AUDIO_CMD_PCM_WRITE
    je .audio_note_write_match
    cmp ebx, AUDIO_CMD_PCM_WRITE_DESC
    jne .audio_note_buffered

.audio_note_write_match:
    mov eax, AUDIO_ABI_PCM_WRITE
    jmp .audio_note_record

.audio_note_buffered:
    cmp ebx, AUDIO_CMD_PCM_BUFFERED_BYTES
    jne .audio_note_drain
    mov eax, AUDIO_ABI_PCM_BUFFERED_BYTES
    jmp .audio_note_record

.audio_note_drain:
    cmp ebx, AUDIO_CMD_PCM_DRAIN
    jne .audio_note_close
    mov eax, AUDIO_ABI_PCM_DRAIN
    jmp .audio_note_record

.audio_note_close:
    cmp ebx, AUDIO_CMD_PCM_CLOSE
    jne .audio_note_done
    mov eax, AUDIO_ABI_PCM_CLOSE

.audio_note_record:
    or [audio_generic_abi_mask], eax
    mov [audio_generic_last_op], eax
    mov [audio_generic_last_cmd], ebx

.audio_note_done:
    pop edx
    pop eax
    ret

.gameplay_status:
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_SECONDARY
    je .payload_secondary_gameplay_status
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_PRIMARY
    jne .gameplay_return
    test ebx, PAYLOAD_INIT_STATUS_FLAG
    jnz .payload_init_status
    test ebx, SAVELOAD_STATUS_FLAG
    jnz .save_slot_io_status
    test ebx, SAVEACTION_STATUS_FLAG
    jnz .save_action_status
    test ebx, PLAYABLE_STATUS_FLAG
    jnz .playable_status
    inc dword [payload_primary_gameplay_report_count]
    mov [payload_primary_game_state_packed], ebx
    mov eax, ebx
    and eax, 0xff
    mov [payload_primary_game_state], eax
    mov eax, ebx
    shr eax, 8
    and eax, 0xff
    mov [payload_primary_game_episode], eax
    mov eax, ebx
    shr eax, 16
    and eax, 0xff
    mov [payload_primary_game_map], eax
    mov eax, ebx
    shr eax, 24
    mov [payload_primary_game_flags], eax
    mov eax, [payload_primary_game_episode]
    shl eax, 8
    or eax, [payload_primary_game_map]
    mov [payload_primary_game_map_pair], eax
    mov [payload_primary_game_tic], ecx
    mov [payload_primary_level_time], edx
    cmp dword [payload_primary_game_state], 0
    jne .gameplay_return
    cmp dword [payload_primary_game_episode], 0
    je .gameplay_return
    cmp dword [payload_primary_game_map], 0
    je .gameplay_return
    cmp ecx, 0
    je .gameplay_return
    cmp edx, 0
    je .gameplay_return
    mov byte [payload_primary_gameplay_status], 1
    jmp .gameplay_return

.payload_init_status:
    mov eax, ebx
    and eax, 0x0000ffff
    or [payload_telemetry_init_flags + USER_KIND_PAYLOAD_PRIMARY * 4], eax
    inc dword [payload_telemetry_init_report_count + USER_KIND_PAYLOAD_PRIMARY * 4]
    jmp .gameplay_return

.save_slot_io_status:
    mov esi, ebx
    and esi, 0x0000ffff
    or [save_slot_io_flags], esi
    mov eax, ebx
    shr eax, SAVELOAD_SLOT_SHIFT
    and eax, 0xff
    mov [save_slot_io_slot], eax
    test esi, SAVELOAD_EVENT_OPEN
    jz .save_slot_io_read
    inc dword [save_slot_io_open_count]
    mov [save_slot_io_last_open_flags], ecx
    mov [save_slot_io_last_open_mode], edx

.save_slot_io_read:
    test esi, SAVELOAD_EVENT_READ
    jz .save_slot_io_write
    inc dword [save_slot_io_read_count]
    add [save_slot_io_read_bytes], ecx

.save_slot_io_write:
    test esi, SAVELOAD_EVENT_WRITE
    jz .save_slot_io_close
    inc dword [save_slot_io_write_count]
    add [save_slot_io_write_bytes], ecx

.save_slot_io_close:
    test esi, SAVELOAD_EVENT_CLOSE
    jz .gameplay_return
    inc dword [save_slot_io_close_count]
    jmp .gameplay_return

.save_action_status:
    mov esi, ebx
    and esi, 0x0000ffff
    test esi, SAVEACTION_STREAM_EVENT
    jnz .save_stream_status
    inc dword [save_action_report_count]
    mov eax, ebx
    and eax, 0x000000ff
    mov [save_action_flags], eax
    mov eax, ebx
    shr eax, SAVEACTION_GAMEACTION_SHIFT
    and eax, 0x000000ff
    mov [save_action_gameaction], eax
    mov eax, ebx
    shr eax, SAVEACTION_SLOT_SHIFT
    and eax, 0x000000ff
    mov [save_action_slot], eax
    mov [save_action_desc_hash], ecx
    mov [save_action_desc_len], edx
    jmp .gameplay_return

.save_stream_status:
    inc dword [save_stream_report_count]
    mov eax, ebx
    shr eax, SAVEACTION_GAMEACTION_SHIFT
    and eax, 0x000000ff
    mov [save_stream_stage], eax
    mov eax, ebx
    shr eax, SAVEACTION_SLOT_SHIFT
    and eax, 0x000000ff
    mov [save_stream_slot], eax
    mov [save_stream_offset], ecx
    mov [save_stream_value], edx
    cmp dword [save_stream_stage], 0x05
    je .save_stream_archive_thinker
    cmp dword [save_stream_stage], 0x15
    je .save_stream_unarchive_thinker
    cmp dword [save_stream_stage], 0x1a
    je .save_stream_unarchive_thinker
    jmp .gameplay_return

.save_stream_archive_thinker:
    mov [save_stream_thinker_archive_offset], ecx
    mov [save_stream_thinker_archive_value], edx
    jmp .gameplay_return

.save_stream_unarchive_thinker:
    mov [save_stream_thinker_unarchive_offset], ecx
    mov [save_stream_thinker_unarchive_value], edx
    jmp .gameplay_return

.playable_status:
    mov eax, ebx
    and eax, 0x0000ffff
    mov [payload_primary_player_flags], eax
    mov eax, ebx
    shr eax, 16
    and eax, 0xff
    mov [payload_primary_player_buttons], eax
    mov eax, ebx
    shr eax, 24
    and eax, 0x7f
    mov [payload_primary_game_action], eax
    mov [payload_primary_player_x], ecx
    mov [payload_primary_player_y], edx
    cmp dword [payload_primary_player_origin_set], 0
    jne .playable_delta
    mov dword [payload_primary_player_origin_set], 1
    mov [payload_primary_player_origin_x], ecx
    mov [payload_primary_player_origin_y], edx

.playable_delta:
    mov eax, ecx
    sub eax, [payload_primary_player_origin_x]
    jns .playable_dx_ok
    neg eax

.playable_dx_ok:
    mov esi, eax
    mov eax, edx
    sub eax, [payload_primary_player_origin_y]
    jns .playable_dy_ok
    neg eax

.playable_dy_ok:
    add eax, esi
    cmp eax, [payload_primary_player_delta]
    jbe .gameplay_return
    mov [payload_primary_player_delta], eax
    jmp .gameplay_return

.player_detail_status:
    cmp byte [current_user_kind], USER_KIND_PAYLOAD_PRIMARY
    jne .gameplay_return
    mov [payload_primary_player_cmd], ebx
    mov [payload_primary_player_angle], ecx
    mov eax, edx
    and eax, 0x0000ffff
    mov [payload_primary_player_ammo], eax
    mov eax, edx
    shr eax, 16
    and eax, 0xff
    mov [payload_primary_player_refire], eax
    mov eax, edx
    shr eax, 24
    and eax, 0xff
    mov [payload_primary_player_weapon], eax
    cmp dword [payload_primary_player_angle_origin_set], 0
    jne .player_angle_delta
    mov dword [payload_primary_player_angle_origin_set], 1
    mov [payload_primary_player_origin_angle], ecx

.player_angle_delta:
    mov eax, ecx
    xor eax, [payload_primary_player_origin_angle]
    or [payload_primary_player_angle_delta], eax
    jmp .gameplay_return

.payload_secondary_gameplay_status:
    mov eax, ebx
    and eax, PAYLOAD_SECONDARY_STATUS_KIND_MASK
    cmp eax, PAYLOAD_SECONDARY_STATUS_INIT
    je .secondary_payload_init_status
    cmp eax, PAYLOAD_SECONDARY_STATUS_FRAME
    je .secondary_payload_frame_status
    cmp eax, PAYLOAD_SECONDARY_STATUS_INPUT
    je .secondary_payload_input_status
    cmp eax, PAYLOAD_SECONDARY_STATUS_AUDIO
    je .secondary_payload_audio_status
    jmp .gameplay_return

.secondary_payload_init_status:
    mov eax, ebx
    and eax, 0x0000ffff
    or [payload_telemetry_init_flags + USER_KIND_PAYLOAD_SECONDARY * 4], eax
    inc dword [payload_telemetry_init_report_count + USER_KIND_PAYLOAD_SECONDARY * 4]
    jmp .gameplay_return

.secondary_payload_frame_status:
    inc dword [payload_secondary_frame_report_count]
    mov [payload_secondary_frame_count], ecx
    mov eax, ebx
    shr eax, 8
    and eax, 0x000000ff
    mov [payload_secondary_server_active], eax
    cmp ecx, 0
    je .gameplay_return
    cmp eax, 0
    je .gameplay_return
    mov dword [payload_secondary_gameplay_status], 1
    jmp .gameplay_return

.secondary_payload_input_status:
    mov [payload_secondary_input_events], ecx
    mov [payload_secondary_input_buttons], edx
    jmp .gameplay_return

.secondary_payload_audio_status:
    mov [payload_secondary_audio_writes], ecx
    mov [payload_secondary_audio_handle], edx
    jmp .gameplay_return

.gameplay_return:
    xor eax, eax
    jmp .return

.unlink:
    mov eax, vfs_unlink_count
    call .vfs_count_generic
    mov [syscall_ptr_arg], ebx
    call fat_parse_user_subdir_file83
    jnc .unlink_subdir
    call fat_parse_user_root83
    jc .bad_syscall_einval
    call fat_open_name_is_protected
    jc .bad_syscall_eacces
    mov edi, fat_open_name_buffer
    call fat_find_root_entry_any
    jc .bad_syscall_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jnz .bad_syscall_eisdir
    test byte [fat_found_attributes], FAT_ATTR_READ_ONLY
    jnz .bad_syscall_eacces
    mov dword [fat_unlink_slot], 0xffffffff
    call fat_find_writable_slot_for_found
    jc .unlink_delete
    mov [fat_unlink_slot], eax

.unlink_delete:
    call fat_delete_found_file
    jc .bad_syscall_eio
    mov eax, [fat_unlink_slot]
    cmp eax, 0xffffffff
    je .unlink_ok
    call fat_close_writable_fds_for_slot
    mov eax, [fat_unlink_slot]
    call fat_clear_writable_slot

.unlink_ok:
    xor eax, eax
    jmp .return

.unlink_subdir:
    mov edi, fat_subdir_name_buffer
    call fat_find_root_entry_any
    jc .bad_syscall_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jz .bad_syscall_enotdir
    test byte [fat_found_attributes], FAT_ATTR_READ_ONLY
    jnz .bad_syscall_eacces
    mov ax, [fat_found_first_cluster]
    cmp ax, 2
    jb .bad_syscall_eio
    mov edi, fat_open_name_buffer
    call fat_find_subdir_entry
    jc .bad_syscall_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jnz .bad_syscall_eisdir
    test byte [fat_found_attributes], FAT_ATTR_READ_ONLY
    jnz .bad_syscall_eacces
    mov dword [fat_unlink_slot], 0xffffffff
    call fat_find_writable_slot_for_found
    jc .unlink_subdir_delete
    mov [fat_unlink_slot], eax

.unlink_subdir_delete:
    call fat_delete_found_file
    jc .bad_syscall_eio
    mov eax, [fat_unlink_slot]
    cmp eax, 0xffffffff
    je .unlink_ok
    call fat_close_writable_fds_for_slot
    mov eax, [fat_unlink_slot]
    call fat_clear_writable_slot
    xor eax, eax
    jmp .return

.stat:
    mov eax, vfs_stat_count
    call .vfs_count_generic
    mov [syscall_ptr_arg], ebx
    mov [syscall_stat_ptr], ecx
    call fat_user_path_is_root
    jnc .stat_root
    mov eax, ebx
    mov ebx, user_path_primary_asset_end - user_path_primary_asset
    mov edi, user_path_primary_asset
    call user_path_equals
    jnc .stat_primary_asset
    call fat_parse_user_subdir_file83
    jc .stat_parse_root83
    mov edi, fat_subdir_name_buffer
    call fat_find_root_entry_any
    jc .bad_syscall_enoent
    test byte [fat_found_attributes], FAT_ATTR_DIRECTORY
    jz .bad_syscall_enotdir
    mov ax, [fat_found_first_cluster]
    cmp ax, 2
    jb .bad_syscall_eio
    mov edi, fat_open_name_buffer
    call fat_find_subdir_entry
    jc .bad_syscall_enoent
    mov eax, [fat_found_size]
    call fat_found_mode
    jmp .stat_found_entry

.stat_parse_root83:
    call fat_parse_user_root83
    jc .bad_syscall_einval
    mov esi, fat_open_name_buffer
    mov edi, primary_asset_name_83
    call fat_name_match
    cmp al, 1
    je .stat_primary_asset
    mov esi, fat_open_name_buffer
    mov edi, user_elf_name_83
    call fat_name_match
    cmp al, 1
    je .stat_user_elf
    call fat_open_name_marker_index
    jnc .stat_persistence_marker
    mov edi, fat_open_name_buffer
    call fat_find_root_entry_any
    jc .bad_syscall_enoent
    mov eax, [fat_found_size]
    call fat_found_mode

.stat_found_entry:
    call stat_fill_user
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.stat_root:
    mov eax, [fat_root_entries]
    shl eax, 5
    mov edx, STAT_MODE_READONLY_DIR
    call stat_fill_user
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.stat_primary_asset:
    mov edi, primary_asset_name_83
    call fat_find_file
    jc .bad_syscall_enoent
    mov eax, [fat_found_size]
    mov edx, STAT_MODE_READONLY_REG
    call stat_fill_user
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.stat_user_elf:
    mov edi, user_elf_name_83
    call fat_find_file
    jc .bad_syscall_enoent
    mov eax, [fat_found_size]
    mov edx, STAT_MODE_READONLY_REG
    call stat_fill_user
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.stat_persistence_marker:
    cmp byte [persistence_marker_status + eax], 1
    jne .bad_syscall_enoent
    mov eax, [persistence_marker_sizes + eax * 4]
    mov edx, STAT_MODE_READONLY_REG
    call stat_fill_user
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.fstat:
    mov eax, vfs_fstat_count
    call .vfs_count_generic
    mov [syscall_stat_ptr], ecx
    call fd_lookup
    jc .bad_syscall_ebadf
    cmp byte [fd_kinds + eax], FD_KIND_PRIMARY_ASSET
    je .fstat_primary_asset
    cmp byte [fd_kinds + eax], FD_KIND_READONLY_FILE
    je .fstat_readonly_file
    cmp byte [fd_kinds + eax], FD_KIND_WRITABLE
    jne .bad_syscall_ebadf
    mov ebx, [fd_indices + eax * 4]
    cmp ebx, WRITABLE_FILE_COUNT
    jae .bad_syscall_ebadf
    cmp byte [writable_status + ebx], 1
    jne .bad_syscall_ebadf
    mov eax, [writable_sizes + ebx * 4]
    mov edx, STAT_MODE_WRITABLE_REG
    call stat_fill_user
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.fstat_readonly_file:
    mov eax, [fd_file_sizes + eax * 4]
    mov edx, STAT_MODE_READONLY_REG
    call stat_fill_user
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.fstat_primary_asset:
    mov eax, [primary_asset_size]
    mov edx, STAT_MODE_READONLY_REG
    call stat_fill_user
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.listdir:
    mov eax, vfs_listdir_count
    call .vfs_count_generic
    mov [syscall_ptr_arg], ebx
    mov [syscall_dirent_ptr], ecx
    mov [syscall_dirent_max], edx
    call fat_list_user_dir
    jc .bad_syscall_from_eax
    jmp .return

.ftruncate:
    mov eax, vfs_ftruncate_count
    call .vfs_count_generic
    test ecx, 0x80000000
    jnz .bad_syscall_einval
    call fd_lookup
    jc .bad_syscall_ebadf
    cmp byte [fd_kinds + eax], FD_KIND_WRITABLE
    jne .bad_syscall_ebadf
    mov edx, [fd_flags + eax * 4]
    and edx, O_ACCMODE
    cmp edx, O_WRONLY
    je .ftruncate_mode_ok
    cmp edx, O_RDWR
    jne .bad_syscall_ebadf

.ftruncate_mode_ok:
    mov ebx, [fd_indices + eax * 4]
    cmp ebx, WRITABLE_FILE_COUNT
    jae .bad_syscall_ebadf
    cmp byte [writable_status + ebx], 1
    jne .bad_syscall_ebadf
    cmp ecx, [writable_capacity_table + ebx * 4]
    ja .bad_syscall_enospc
    mov eax, ebx
    call fat_resize_writable_file
    jc .bad_syscall_eio
    xor eax, eax
    jmp .return

.mmap:
    inc dword [process_mmap_attempts]
    mov dword [process_mmap_last_result], 0
    mov dword [process_mmap_last_error], 0
    mov [mmap_addr_arg], ebx
    mov [mmap_len_arg], ecx
    mov eax, edx
    and eax, MMAP_PROT_MASK
    mov [mmap_prot_arg], eax
    mov eax, edx
    shr eax, MMAP_FLAGS_SHIFT
    mov [mmap_flags_arg], eax
    cmp dword [mmap_len_arg], 0
    je .mmap_einval
    mov eax, [mmap_prot_arg]
    and eax, 0xfffffff8
    jnz .mmap_einval
    test dword [mmap_flags_arg], MMAP_MAP_FIXED
    jz .mmap_addr_ok
    mov eax, [mmap_addr_arg]
    test eax, PAGE_SIZE - 1
    jnz .mmap_einval
    jmp .mmap_flags_ok

.mmap_addr_ok:
    ; Linux permits a nonzero address without MAP_FIXED as a placement hint.
    ; The seed allocator ignores the hint and chooses the process mmap cursor.

.mmap_flags_ok:
    test dword [mmap_flags_arg], MMAP_MAP_ANONYMOUS
    jz .mmap_einval
    mov eax, [mmap_flags_arg]
    and eax, MMAP_MAP_SHARED | MMAP_MAP_PRIVATE
    jz .mmap_einval
    mov eax, [mmap_flags_arg]
    and eax, ~MMAP_SUPPORTED_FLAGS
    jnz .mmap_einval
    mov eax, [mmap_len_arg]
    add eax, PAGE_SIZE - 1
    jc .mmap_enomem
    and eax, 0xfffff000
    mov [mmap_len_arg], eax
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .mmap_enomem
    test dword [mmap_flags_arg], MMAP_MAP_FIXED
    jz .mmap_choose_base
    mov eax, [mmap_addr_arg]
    cmp eax, [esi + PROC_HEAP_START]
    jb .mmap_enomem
    jmp .mmap_base_ready

.mmap_choose_base:
    mov eax, [esi + PROC_BRK]
    add eax, PAGE_SIZE - 1
    jc .bad_syscall_enomem
    and eax, 0xfffff000

.mmap_base_ready:
    mov [mmap_base_arg], eax
    mov edx, eax
    add edx, [mmap_len_arg]
    jc .mmap_enomem
    cmp edx, [esi + PROC_HEAP_END]
    ja .mmap_enomem
    mov [mmap_end_arg], edx
    cmp edx, PAGING_MAPPED_BYTES
    ja .mmap_high_anon
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jnz .mmap_have_page_dir
    mov ebx, PAGING_DIR_ADDR

.mmap_have_page_dir:
    call vmm_mark_process_user_write_range
    jmp .mmap_flush

.mmap_readonly:
    call vmm_mark_process_user_read_range

.mmap_flush:
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .mmap_zero
    mov cr3, ebx

.mmap_zero:
    mov edi, [mmap_base_arg]
    mov ecx, [mmap_len_arg]
    shr ecx, 2
    xor eax, eax
    cld
    rep stosd
    jmp .mmap_mark_and_update

.mmap_high_anon:
    mov eax, [mmap_base_arg]
    mov [mmap_page_vaddr], eax

.mmap_high_anon_next:
    mov eax, [mmap_page_vaddr]
    cmp eax, [mmap_end_arg]
    jae .mmap_mark_and_update
    call pmm_alloc_page
    test eax, eax
    jz .mmap_enomem
    mov [mmap_page_phys], eax

    pushfd
    cli
    mov eax, FORK_COPY_DST_ALIAS
    mov ebx, [mmap_page_phys]
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .mmap_high_alias_fail
    mov edi, FORK_COPY_DST_ALIAS
    xor eax, eax
    mov ecx, PAGE_SIZE / 4
    cld
    rep stosd
    mov eax, FORK_COPY_DST_ALIAS
    call vmm_unmap_page
    popfd

    mov esi, [current_process_ptr]
    cmp esi, 0
    je .mmap_high_pte_fail
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jnz .mmap_high_have_page_dir
    mov ebx, PAGING_DIR_ADDR

.mmap_high_have_page_dir:
    mov ecx, [mmap_page_phys]
    and ecx, 0xfffff000
    or ecx, PTE_USER_WRITE_FLAGS
    mov eax, [mmap_page_vaddr]
    call vmm_write_process_pte
    jc .mmap_high_pte_fail

    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .mmap_high_cr3_ready
    mov cr3, ebx

.mmap_high_cr3_ready:
    mov eax, [mmap_page_vaddr]
    invlpg [eax]
    add dword [mmap_page_vaddr], PAGE_SIZE
    jmp .mmap_high_anon_next

.mmap_high_alias_fail:
    popfd
    mov eax, [mmap_page_phys]
    call pmm_free_page
    jmp .mmap_enomem

.mmap_high_pte_fail:
    mov eax, [mmap_page_phys]
    call pmm_free_page
    jmp .mmap_enomem

.mmap_mark_and_update:
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .mmap_enomem
    mov eax, [mmap_base_arg]
    mov edx, [mmap_end_arg]
    call process_heap_mark_range
    mov edx, [mmap_end_arg]
    cmp edx, [esi + PROC_BRK]
    jbe .mmap_brk_ready
    mov [esi + PROC_BRK], edx
    mov [current_user_brk], edx
    mov [user_brk_current], edx

.mmap_brk_ready:
    mov eax, user_io_sbrk_count
    call user_io_increment_current
    mov eax, [mmap_base_arg]
    mov [process_mmap_last_result], eax
    mov dword [process_mmap_last_error], 0
    inc dword [process_mmap_successes]
    jmp .return

.mmap_enomem:
    mov dword [process_mmap_last_result], -ERRNO_ENOMEM
    mov dword [process_mmap_last_error], -ERRNO_ENOMEM
    inc dword [process_mmap_failures]
    jmp .bad_syscall_enomem

.mmap_einval:
    mov dword [process_mmap_last_result], -ERRNO_EINVAL
    mov dword [process_mmap_last_error], -ERRNO_EINVAL
    inc dword [process_mmap_failures]
    jmp .bad_syscall_einval

.munmap:
    inc dword [process_munmap_attempts]
    cmp ebx, 0
    je .bad_syscall_einval
    cmp ecx, 0
    je .bad_syscall_einval
    mov eax, ebx
    and eax, PAGE_SIZE - 1
    jnz .bad_syscall_einval
    mov [mmap_base_arg], ebx
    mov eax, ecx
    add eax, PAGE_SIZE - 1
    jc .bad_syscall_einval
    and eax, 0xfffff000
    mov [mmap_len_arg], eax
    mov eax, ebx
    add eax, [mmap_len_arg]
    jc .bad_syscall_einval
    mov [mmap_end_arg], eax
    mov eax, [mmap_base_arg]
    mov ebx, [mmap_len_arg]
    call user_range_validate
    jc .bad_syscall_einval
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .bad_syscall_einval
    mov eax, [mmap_base_arg]
    mov [process_last_munmap_base], eax
    mov eax, [mmap_end_arg]
    mov [process_last_munmap_end], eax
    cmp eax, [esi + PROC_BRK]
    jne .munmap_keep_non_tail
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jnz .munmap_have_page_dir
    mov ebx, PAGING_DIR_ADDR

.munmap_have_page_dir:
    mov eax, [mmap_base_arg]
    mov edx, [mmap_end_arg]
    call process_clear_user_range
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .munmap_update_brk
    mov cr3, ebx

.munmap_update_brk:
    mov eax, [mmap_base_arg]
    mov [esi + PROC_BRK], eax
    mov [current_user_brk], eax
    mov [user_brk_current], eax
    mov eax, [mmap_len_arg]
    shr eax, 12
    add [process_munmap_pages_released], eax
    xor eax, eax
    jmp .return

.munmap_keep_non_tail:
    inc dword [process_munmap_non_tail_kept]
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jnz .munmap_non_tail_have_page_dir
    mov ebx, PAGING_DIR_ADDR

.munmap_non_tail_have_page_dir:
    mov eax, [mmap_base_arg]
    mov edx, [mmap_end_arg]
    call process_clear_user_range
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .munmap_non_tail_account
    mov cr3, ebx

.munmap_non_tail_account:
    inc dword [process_munmap_holes_punched]
    mov eax, [mmap_len_arg]
    shr eax, 12
    add [process_munmap_pages_unmapped], eax
    xor eax, eax
    jmp .return

.ioctl:
    cmp ebx, IOCTL_DISPLAY_FD
    je .ioctl_display
    cmp ebx, IOCTL_AUDIO_FD
    je .ioctl_audio
    jmp .bad_syscall_enotty

.ioctl_display:
    cmp ecx, VIBE_IOCTL_FBINFO
    je .ioctl_fbinfo
    cmp ecx, VIBE_IOCTL_PRESENT_INDEXED
    je .ioctl_present_indexed
    jmp .bad_syscall_enotty

.ioctl_fbinfo:
    mov [syscall_ptr_arg], edx
    mov eax, edx
    mov ebx, VIBE_FB_INFO_BYTES
    call user_range_validate
    jnc .ioctl_fbinfo_range_valid
    inc dword [framebuffer_present_bad_range_count]
    jmp .bad_syscall_einval

.ioctl_fbinfo_range_valid:
    call framebuffer_record_info_query
    mov edi, [syscall_ptr_arg]
    mov eax, [framebuffer_width]
    mov [edi + VIBE_FB_INFO_WIDTH], eax
    mov eax, [framebuffer_height]
    mov [edi + VIBE_FB_INFO_HEIGHT], eax
    mov eax, [framebuffer_pitch]
    mov [edi + VIBE_FB_INFO_PITCH], eax
    movzx eax, byte [video_backend]
    mov [edi + VIBE_FB_INFO_BACKEND], eax
    mov eax, [present_frame_bytes_arg]
    mov [edi + VIBE_FB_INFO_FRAME_BYTES], eax
    mov eax, [framebuffer_source_palette_bytes]
    mov [edi + VIBE_FB_INFO_PALETTE_BYTES], eax
    mov eax, [present_lfb_scale]
    mov [edi + VIBE_FB_INFO_SCALE], eax
    mov eax, [present_lfb_view_x]
    mov [edi + VIBE_FB_INFO_VIEW_X], eax
    mov eax, [present_lfb_view_y]
    mov [edi + VIBE_FB_INFO_VIEW_Y], eax
    mov eax, [present_lfb_view_width]
    mov [edi + VIBE_FB_INFO_VIEW_WIDTH], eax
    mov eax, [present_lfb_view_height]
    mov [edi + VIBE_FB_INFO_VIEW_HEIGHT], eax
    mov eax, [present_lfb_policy]
    mov [edi + VIBE_FB_INFO_POLICY], eax
    mov eax, [present_dirty_x]
    mov [edi + VIBE_FB_INFO_DIRTY_X], eax
    mov eax, [present_dirty_y]
    mov [edi + VIBE_FB_INFO_DIRTY_Y], eax
    mov eax, [present_dirty_width]
    mov [edi + VIBE_FB_INFO_DIRTY_WIDTH], eax
    mov eax, [present_dirty_height]
    mov [edi + VIBE_FB_INFO_DIRTY_HEIGHT], eax
    mov eax, [present_dirty_count]
    mov [edi + VIBE_FB_INFO_DIRTY_COUNT], eax
    mov eax, [framebuffer_capabilities]
    mov [edi + VIBE_FB_INFO_CAPABILITIES], eax
    mov eax, [framebuffer_source_format]
    mov [edi + VIBE_FB_INFO_PRESENT_FORMAT], eax
    mov eax, [framebuffer_source_width]
    mov [edi + VIBE_FB_INFO_MAX_PRESENT_WIDTH], eax
    mov eax, [framebuffer_source_height]
    mov [edi + VIBE_FB_INFO_MAX_PRESENT_HEIGHT], eax
    xor eax, eax
    jmp .return

.ioctl_present_indexed:
    mov [syscall_ptr_arg], edx
    mov eax, edx
    mov ebx, VIBE_PRESENT_DESC_BYTES
    call user_range_validate
    jnc .ioctl_present_desc_valid
    inc dword [framebuffer_present_bad_desc_count]
    jmp .bad_syscall_einval

.ioctl_present_desc_valid:
    mov esi, [syscall_ptr_arg]
    mov eax, [esi + VIBE_PRESENT_DESC_WIDTH]
    mov [present_width_arg], eax
    test eax, eax
    jz .ioctl_present_bad_size
    cmp byte [video_backend], VIDEO_BACKEND_LFB_XRGB8888
    je .ioctl_present_lfb_width
    cmp eax, FB_PRESENT_WIDTH
    je .ioctl_present_width_valid
.ioctl_present_bad_size:
    inc dword [framebuffer_present_bad_size_count]
    jmp .bad_syscall_einval

.ioctl_present_lfb_width:
    cmp eax, [framebuffer_source_width]
    jbe .ioctl_present_width_valid
    jmp .ioctl_present_bad_size

.ioctl_present_width_valid:
    mov eax, [esi + VIBE_PRESENT_DESC_HEIGHT]
    mov [present_height_arg], eax
    test eax, eax
    jz .ioctl_present_bad_size
    cmp byte [video_backend], VIDEO_BACKEND_LFB_XRGB8888
    je .ioctl_present_lfb_height
    cmp eax, FB_PRESENT_HEIGHT
    jne .ioctl_present_bad_size
    jmp .ioctl_present_height_valid

.ioctl_present_lfb_height:
    cmp eax, [framebuffer_source_height]
    ja .ioctl_present_bad_size

.ioctl_present_height_valid:
    mov eax, [present_width_arg]
    mul dword [present_height_arg]
    jc .ioctl_present_bad_size
    test eax, eax
    jz .ioctl_present_bad_size
    mov [present_frame_bytes_arg], eax
    mov eax, [esi + VIBE_PRESENT_DESC_FRAME]
    mov [present_frame_arg], eax
    mov eax, [esi + VIBE_PRESENT_DESC_PALETTE]
    mov [present_palette_arg], eax
    mov eax, [present_frame_arg]
    mov ebx, [present_frame_bytes_arg]
    call user_range_validate
    jnc .ioctl_present_frame_valid
    inc dword [framebuffer_present_bad_range_count]
    jmp .bad_syscall_einval

.ioctl_present_frame_valid:
    mov eax, [present_palette_arg]
    mov ebx, [framebuffer_source_palette_bytes]
    call user_range_validate
    jnc .ioctl_present_palette_valid
    inc dword [framebuffer_present_bad_range_count]
    jmp .bad_syscall_einval

.ioctl_present_palette_valid:
    call present_indexed_frame
    jnc .ioctl_present_success
    inc dword [framebuffer_present_failure_count]
    jmp .bad_syscall_eio

.ioctl_present_success:
    mov eax, FRAMEBUFFER_PRESENT_SOURCE_IOCTL
    call framebuffer_record_present_success
    mov eax, payload_telemetry_present_count
    call payload_telemetry_increment_current
    xor eax, eax
    jmp .return

.ioctl_audio:
    cmp ecx, VIBE_IOCTL_AUDIO_DEVICE_INFO
    je .ioctl_audio_device_info
    cmp ecx, VIBE_IOCTL_AUDIO_PCM_RING_INFO
    je .ioctl_audio_pcm_ring_info
    cmp ecx, VIBE_IOCTL_AUDIO_STREAM_INFO
    je .ioctl_audio_stream_info
    jmp .bad_syscall_enotty

.ioctl_audio_device_info:
    mov ecx, edx
    call audio_write_device_info
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.ioctl_audio_pcm_ring_info:
    mov ecx, edx
    call audio_write_pcm_ring_info
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.ioctl_audio_stream_info:
    mov [syscall_ptr_arg], edx
    mov eax, edx
    mov ebx, AUDIO_STREAM_INFO_BYTES
    call user_range_validate
    jc .bad_syscall_einval
    mov edi, [syscall_ptr_arg]
    mov ecx, [edi + AUDIO_STREAM_INFO_HANDLE]
    mov edx, [syscall_ptr_arg]
    call audio_write_stream_info
    jc .bad_syscall_einval
    xor eax, eax
    jmp .return

.fork:
    mov [process_fork_frame_ptr], esp
    call process_fork_current
    jc .bad_syscall_from_eax
    jmp .return

.waitpid:
    call process_waitpid_current
    jc .bad_syscall_from_eax
    cmp eax, WAITPID_BLOCK_SENTINEL
    je .waitpid_block
    jmp .return

.waitpid_block:
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .bad_syscall_enosys
    cmp esi, process_kernel
    je .bad_syscall_enosys
    mov dword [syscall_return_value], 0
    mov dword [esi + PROC_QUANTUM_TICKS], 0
    call process_save_syscall_return_context
    mov eax, PROC_BLOCK_WAITPID
    mov ebx, [process_wait_last_pid_arg]
    xor ecx, ecx
    mov edx, [process_wait_last_status_ptr]
    call scheduler_block_current
    jc .waitpid_block_fail
    inc dword [process_wait_blocks]
    call scheduler_select_next_ready
    mov esi, [scheduler_next_process_ptr]
    cmp esi, 0
    je .waitpid_idle_wait
    call process_activate
    mov ebx, esp
    call process_restore_syscall_context
    jmp .context_handoff_return

.waitpid_idle_wait:
    sti
    hlt
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .waitpid_idle_wait
    cmp dword [esi + PROC_STATE], PROC_STATE_READY
    jne .waitpid_idle_wait
    call process_activate
    mov ebx, esp
    call process_restore_syscall_context
    jmp .context_handoff_return

.waitpid_block_fail:
    inc dword [process_wait_failures]
    jmp .bad_syscall_einval

.getpid:
    mov eax, [current_pid]
    jmp .return

.getppid:
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .bad_syscall_enosys
    mov eax, [esi + PROC_PARENT_PID]
    jmp .return

.exec:
    mov [syscall_ptr_arg], ebx
    mov [sys_exec_user_argv_arg], ecx
    mov [sys_exec_user_envp_arg], edx
    mov [sys_exec_frame_ptr], esp
    mov dword [process_exec_path_ptr], 0
    mov dword [process_exec_target], 0
    mov dword [process_exec_target_kind], USER_KIND_NONE
    mov dword [process_exec_entry], 0
    mov dword [process_exec_last_error], 0
    mov dword [sys_exec_last_parent_pid], 0xffffffff
    mov dword [sys_exec_last_target_pid], 0xffffffff
    mov dword [sys_exec_last_target_entry], 0
    mov dword [sys_exec_last_target_stack], 0
    mov dword [sys_exec_last_argc], 0
    mov dword [sys_exec_last_envc], 0
    mov dword [sys_exec_last_argv], 0
    mov dword [sys_exec_last_envp], 0
    mov dword [sys_exec_last_argv0], 0
    mov dword [sys_exec_last_envp0], 0
    mov dword [sys_exec_last_auxv], 0
    mov dword [sys_exec_last_stack_abi], 0
    mov dword [sys_exec_last_stack_align], 0
    mov dword [sys_exec_last_auxv_pairs], 0
    mov dword [sys_exec_last_aux_phdr], 0
    mov dword [sys_exec_last_aux_phnum], 0
    mov dword [sys_exec_last_aux_base], 0
    mov dword [sys_exec_last_aux_entry], 0
    mov dword [sys_exec_last_argv_source], 0
    mov dword [sys_exec_last_envp_source], 0
    inc dword [sys_exec_attempts]
    call sys_exec_copy_user_path
    jc .exec_einval
    call sys_exec_copy_argv
    jc .exec_einval
    call sys_exec_copy_envp
    jc .exec_einval
    mov esi, [sys_exec_path_buffer_ptr]
    xor edi, edi
    mov byte [process_exec_reject_active_target], 1
    call process_exec_path
    mov byte [process_exec_reject_active_target], 0
    jc .exec_path_failed
    call process_exec_handoff_current
    jc .exec_path_failed
    inc dword [sys_exec_successes]
    xor eax, eax
    mov [sys_exec_last_result], eax
    jmp .exec_handoff_return

.exec_einval:
    mov dword [process_exec_last_error], -ERRNO_EINVAL
    mov eax, -ERRNO_EINVAL
    jmp .exec_fail

.exec_path_failed:
    mov byte [process_exec_reject_active_target], 0
    mov eax, [process_exec_last_error]
    cmp eax, 0
    jne .exec_fail
    mov eax, -ERRNO_ENOENT

.exec_fail:
    inc dword [sys_exec_failures]
    inc dword [sys_exec_rollbacks]
    mov [sys_exec_last_result], eax
    jmp .bad_syscall_return

.context_handoff_return:
    call syscall_sanitize_return_frame
    call syscall_restore_user_segments
    pop ebp
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    iretd

.exec_handoff_return:
    xor eax, eax
    jmp .context_handoff_return

.bad_syscall:
    mov eax, 0xffffffff
    jmp .bad_syscall_return

.bad_syscall_from_eax:
    jmp .bad_syscall_return

.bad_syscall_enoent:
    mov eax, -ERRNO_ENOENT
    jmp .bad_syscall_return

.bad_syscall_eio:
    mov eax, -ERRNO_EIO
    jmp .bad_syscall_return

.bad_syscall_ebadf:
    mov eax, -ERRNO_EBADF
    jmp .bad_syscall_return

.bad_syscall_enomem:
    mov eax, -ERRNO_ENOMEM
    jmp .bad_syscall_return

.bad_syscall_eacces:
    mov eax, -ERRNO_EACCES
    jmp .bad_syscall_return

.bad_syscall_enotdir:
    mov eax, -ERRNO_ENOTDIR
    jmp .bad_syscall_return

.bad_syscall_eisdir:
    mov eax, -ERRNO_EISDIR
    jmp .bad_syscall_return

.bad_syscall_einval:
    mov eax, -ERRNO_EINVAL
    jmp .bad_syscall_return

.bad_syscall_emfile:
    mov eax, -ERRNO_EMFILE
    jmp .bad_syscall_return

.bad_syscall_enotty:
    mov eax, -ERRNO_ENOTTY
    jmp .bad_syscall_return

.bad_syscall_enospc:
    mov eax, -ERRNO_ENOSPC
    jmp .bad_syscall_return

.bad_syscall_echild:
    mov eax, -ERRNO_ECHILD
    jmp .bad_syscall_return

.bad_syscall_enosys:
    mov eax, -ERRNO_ENOSYS
    jmp .bad_syscall_return

.bad_syscall_return:
    push eax
    mov eax, user_io_error_count
    call user_io_increment_current
    pop eax
    mov edx, eax
    mov eax, user_io_last_error
    call user_io_store_current
    mov eax, edx
    jmp .return

; Linux i386 syscall path. EAX=nr, EBX/ECX/EDX/ESI/EDI/EBP=args 1..6.
; M-1 keeps the dispatch tiny: implemented Linux calls reuse the native safe
; syscall bodies; every other Linux syscall remains traced and returns -ENOSYS.
.linux_dispatch:
    call linux_syscall_note_enter
    cmp eax, LINUX_SYS_READ
    je .read
    cmp eax, LINUX_SYS_FORK
    je .fork
    cmp eax, LINUX_SYS_WRITE
    je .write
    cmp eax, LINUX_SYS_OPEN
    je .linux_open
    cmp eax, LINUX_SYS_CLOSE
    je .close
    cmp eax, LINUX_SYS_WAITPID
    je .waitpid
    cmp eax, LINUX_SYS_EXIT
    je .exit
    cmp eax, LINUX_SYS_LSEEK
    je .lseek
    cmp eax, LINUX_SYS_GETPID
    je .getpid
    cmp eax, LINUX_SYS_GETUID
    je .linux_get_identity_zero
    cmp eax, LINUX_SYS_ACCESS
    je .linux_access
    cmp eax, LINUX_SYS_DUP
    je .dup
    cmp eax, LINUX_SYS_PIPE
    je .linux_pipe
    cmp eax, LINUX_SYS_BRK
