.linux_open_file:
    mov [syscall_ptr_arg], ebx
    call linux_path_is_synthetic_lib_dir
    jnc .linux_open_synthetic_dir
    call linux_translate_open_flags
    jc .bad_syscall_einval
    jmp .open

