    jmp .return

.linux_sigaltstack:
    call linux_sys_sigaltstack
    jmp .return

.linux_getrandom:
    call linux_sys_getrandom
    jmp .return

.linux_rseq:
    call linux_sys_rseq
    jmp .return

.linux_readlink:
    call linux_record_path_arg
    call linux_sys_readlink
    jmp .return

.linux_readlinkat:
    push ebx
    mov ebx, ecx
    call linux_record_path_arg
    pop ebx
    cmp ebx, LINUX_AT_FDCWD
    je .linux_readlinkat_args
    mov eax, ecx
    mov ebx, 1
    call user_range_validate
    jc .bad_syscall_einval
    cmp byte [eax], '/'
    jne .bad_syscall_enoent

.linux_readlinkat_args:
    mov ebx, ecx
    mov ecx, edx
    mov edx, esi
    call linux_sys_readlink
    jmp .return

.exit:
    movzx eax, byte [current_user_kind]
    call user_kind_is_large_payload
    jnc .payload_exit
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .user_exit_to_kernel
    cmp esi, process_user_probe
    je .user_exit_to_kernel
    cmp dword [esi + PROC_PARENT_PID], 0xffffffff
    je .user_exit_to_kernel
    mov [process_exit_frame_ptr], esp
    call process_mark_current_zombie_exited
    call process_exit_resume_parent
    jc .user_exit_after_zombie
    jmp .context_handoff_return

.user_exit_to_kernel:
    mov byte [user_probe_status], 2
    call process_mark_current_exited

.user_exit_after_zombie:
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    mov ss, ax
    call kernel_switch_main_stack_and_return
    jmp user_probe_finished

.payload_exit:
    mov edx, ebx
    call payload_lifecycle_exit_kind
    call process_mark_current_exited
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    mov ss, ax
    call kernel_switch_main_stack_and_return
    jmp payload_user_finished

.return:
    push eax
    mov eax, [current_process_ptr]
    cmp eax, 0
    je .return_note_done
    cmp dword [eax + PROC_PERSONALITY], PERSONALITY_LINUX
    pop eax
    jne .return_note_skipped
    call linux_syscall_note_return
    jmp .return_note_skipped

.return_note_done:
    pop eax

.return_note_skipped:
    call syscall_sanitize_return_frame
    mov [syscall_return_value], eax
    call process_save_syscall_return_context
    mov eax, [syscall_return_value]
    call syscall_restore_user_segments
    pop ebp
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    iretd

syscall_sanitize_return_frame:
    push eax
    mov eax, [esp + SYSCALL_SANITIZE_EFLAGS_OFFSET]
    mov [syscall_return_eflags_last_before], eax
    and eax, SYSCALL_RETURN_EFLAGS_KEEP_MASK
    or eax, SYSCALL_RETURN_EFLAGS_SET
    mov [syscall_return_eflags_last_after], eax
    cmp eax, [syscall_return_eflags_last_before]
    je .store
    inc dword [syscall_return_eflags_sanitize_count]

.store:
    mov [esp + SYSCALL_SANITIZE_EFLAGS_OFFSET], eax
    pop eax
    ret

syscall_restore_user_segments:
    mov si, USER_DATA_SEG
    mov ds, si
    mov es, si
    mov fs, si
    mov edx, [current_process_ptr]
    cmp edx, 0
    je .restore_gs
    cmp dword [edx + PROC_PERSONALITY], PERSONALITY_LINUX
    jne .restore_gs
    mov si, [edx + PROC_SAVED_GS]

.restore_gs:
    mov gs, si
    ret

sys_exec_ensure_staging:
    push eax
    push ebx

    cmp dword [sys_exec_stage_base], 0
    jne .ok
    mov eax, SYS_EXEC_STAGE_BYTES
    call kalloc
    test eax, eax
    jz .fail
    mov [sys_exec_stage_base], eax
    mov dword [sys_exec_stage_bytes], SYS_EXEC_STAGE_BYTES
    mov dword [sys_exec_stage_alloc_status], 1
    lea ebx, [eax + SYS_EXEC_STAGE_PATH_OFF]
    mov [sys_exec_path_buffer_ptr], ebx
    lea ebx, [eax + SYS_EXEC_STAGE_ARG_PTR_OFF]
    mov [sys_exec_arg_target_ptrs], ebx
    lea ebx, [eax + SYS_EXEC_STAGE_ENV_PTR_OFF]
    mov [sys_exec_env_target_ptrs], ebx
    lea ebx, [eax + SYS_EXEC_STAGE_POOL_OFF]
    mov [sys_exec_string_pool_ptr], ebx
    mov [sys_exec_string_pool_cursor], ebx
    add ebx, SYS_EXEC_STRING_POOL_BYTES
    mov [sys_exec_string_pool_end], ebx

.ok:
    clc
    jmp .done

.fail:
    mov dword [sys_exec_stage_alloc_status], 2
    stc

.done:
    pop ebx
    pop eax
    ret

sys_exec_reset_string_pool:
    push eax
    mov eax, [sys_exec_string_pool_ptr]
    mov [sys_exec_string_pool_cursor], eax
    mov dword [sys_exec_string_pool_used], 0
    pop eax
    ret

sys_exec_copy_user_path:
    push eax
    push ebx
    push ecx
    push esi
    push edi

    call sys_exec_ensure_staging
    jc .fail
    mov edi, [sys_exec_path_buffer_ptr]
    xor eax, eax
    mov ecx, SYS_EXEC_PATH_MAX
    cld
    rep stosb

    mov esi, [syscall_ptr_arg]
    cmp esi, 0
    je .fail
    mov edi, [sys_exec_path_buffer_ptr]
    xor ecx, ecx

.next:
    mov eax, esi
    add eax, ecx
    jc .fail
    mov ebx, 1
    call user_range_validate
    jc .fail
    mov al, [esi + ecx]
    mov [edi + ecx], al
    test al, al
    jz .ok
    inc ecx
    cmp ecx, SYS_EXEC_PATH_MAX - 1
    jb .next
    mov byte [edi + SYS_EXEC_PATH_MAX - 1], 0

.fail:
    stc
    jmp .done

.ok:
    clc

.done:
    pop edi
    pop esi
    pop ecx
    pop ebx
    pop eax
    ret

sys_exec_clear_args:
    push eax
    push ecx
    push edi

    call sys_exec_ensure_staging
    jc .fail
    mov dword [sys_exec_argc], 0
    mov dword [sys_exec_arg_copy_index], 0
    mov dword [sys_exec_stack_cursor], 0
    mov dword [sys_exec_user_stack_ptr], 0
    mov dword [sys_exec_argv0_ptr], 0
    mov dword [sys_exec_last_auxv], 0
    mov dword [sys_exec_last_aux_phdr], 0
    mov dword [sys_exec_last_aux_phnum], 0
    mov dword [sys_exec_last_aux_base], 0
    mov dword [sys_exec_last_aux_entry], 0
    mov dword [sys_exec_last_argv_source], 0
    mov dword [sys_exec_last_envp_source], SYS_EXEC_ENVP_SOURCE_EMPTY
    mov dword [sys_exec_envc], 0
    mov dword [sys_exec_env_copy_index], 0
    call sys_exec_reset_string_pool
    mov edi, [sys_exec_arg_target_ptrs]
    xor eax, eax
    mov ecx, SYS_EXEC_ARG_MAX
    cld
    rep stosd
    mov edi, [sys_exec_env_target_ptrs]
    mov ecx, SYS_EXEC_ENV_MAX
    rep stosd
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop ecx
    pop eax
    ret

sys_exec_stage_kernel_arg:
    push eax
    push edx
    push esi
    push edi

    call sys_exec_clear_args
    jc .done
    mov edx, SYS_EXEC_ARG_STR_MAX
    call sys_exec_stage_kernel_string
    jc .done
    mov edi, [sys_exec_arg_target_ptrs]
    mov [edi], eax
    mov dword [sys_exec_argc], SYS_EXEC_ARGC_DEFAULT
    mov dword [sys_exec_last_argv_source], SYS_EXEC_ARGV_SOURCE_DEFAULT
    clc

.done:
    pop edi
    pop esi
    pop edx
    pop eax
    ret

sys_exec_stage_kernel_arg_append:
    push ecx
    push edx
    push edi

    mov ecx, [sys_exec_argc]
    cmp ecx, SYS_EXEC_ARG_MAX
    jae .fail
    mov edx, SYS_EXEC_ARG_STR_MAX
    call sys_exec_stage_kernel_string
    jc .done
    mov edi, [sys_exec_arg_target_ptrs]
    mov [edi + ecx * 4], eax
    inc dword [sys_exec_argc]
    mov dword [sys_exec_last_argv_source], SYS_EXEC_ARGV_SOURCE_USER
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop edx
    pop ecx
    ret

sys_exec_stage_kernel_env_append:
    push ecx
    push edx
    push edi

    mov ecx, [sys_exec_envc]
    cmp ecx, SYS_EXEC_ENV_MAX
    jae .fail
    mov edx, SYS_EXEC_ENV_STR_MAX
    call sys_exec_stage_kernel_string
    jc .done
    mov edi, [sys_exec_env_target_ptrs]
    mov [edi + ecx * 4], eax
    inc dword [sys_exec_envc]
    mov dword [sys_exec_last_envp_source], SYS_EXEC_ENVP_SOURCE_USER
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop edx
    pop ecx
    ret

sys_exec_copy_argv:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    call sys_exec_clear_args
    jc .fail
    cmp dword [sys_exec_user_argv_arg], 0
    jne .copy_user_argv

    mov esi, [sys_exec_path_buffer_ptr]
    mov edi, [sys_exec_arg_target_ptrs]
    mov [edi], esi
    mov dword [sys_exec_argc], SYS_EXEC_ARGC_DEFAULT
    mov dword [sys_exec_last_argv_source], SYS_EXEC_ARGV_SOURCE_DEFAULT
    clc
    jmp .done

.copy_user_argv:
    mov dword [sys_exec_arg_copy_index], 0

.argv_loop:
    mov ecx, [sys_exec_arg_copy_index]
    mov eax, [sys_exec_user_argv_arg]
    mov edx, ecx
    shl edx, 2
    add eax, edx
    jc .fail
    mov ebx, 4
    call user_range_validate
    jc .fail
    mov esi, [eax]
    cmp esi, 0
    je .argv_done
    cmp ecx, SYS_EXEC_ARG_MAX
    jae .fail
    call sys_exec_copy_user_arg_string
    jc .fail
    mov edi, [sys_exec_arg_target_ptrs]
    mov [edi + ecx * 4], eax
    inc dword [sys_exec_arg_copy_index]
    jmp .argv_loop

.argv_done:
    cmp dword [sys_exec_arg_copy_index], 0
    je .fail
    mov eax, [sys_exec_arg_copy_index]
    mov [sys_exec_argc], eax
    mov dword [sys_exec_last_argv_source], SYS_EXEC_ARGV_SOURCE_USER
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

sys_exec_copy_envp:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    call sys_exec_ensure_staging
    jc .fail
    cmp dword [sys_exec_user_envp_arg], 0
    jne .copy_user_envp
    mov dword [sys_exec_envc], 0
    mov dword [sys_exec_last_envp_source], SYS_EXEC_ENVP_SOURCE_EMPTY
    clc
    jmp .done

.copy_user_envp:
    mov dword [sys_exec_env_copy_index], 0

.env_loop:
    mov ecx, [sys_exec_env_copy_index]
    mov eax, [sys_exec_user_envp_arg]
    mov edx, ecx
    shl edx, 2
    add eax, edx
    jc .fail
    mov ebx, 4
    call user_range_validate
    jc .fail
    mov esi, [eax]
    cmp esi, 0
    je .env_done
    cmp ecx, SYS_EXEC_ENV_MAX
    jae .fail
    call sys_exec_copy_user_env_string
    jc .fail
    mov edi, [sys_exec_env_target_ptrs]
    mov [edi + ecx * 4], eax
    inc dword [sys_exec_env_copy_index]
    jmp .env_loop

.env_done:
    mov eax, [sys_exec_env_copy_index]
    mov [sys_exec_envc], eax
    mov dword [sys_exec_last_envp_source], SYS_EXEC_ENVP_SOURCE_EMPTY
    cmp eax, 0
    je .ok
    mov dword [sys_exec_last_envp_source], SYS_EXEC_ENVP_SOURCE_USER

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

sys_exec_copy_user_arg_string:
    mov edx, SYS_EXEC_ARG_STR_MAX
    jmp sys_exec_stage_user_string

sys_exec_copy_user_env_string:
    mov edx, SYS_EXEC_ENV_STR_MAX
    jmp sys_exec_stage_user_string

sys_exec_stage_user_string:
    push ebx
    push ecx
    push edx
    push esi
    push edi
    push ebp

    mov edi, [sys_exec_string_pool_cursor]
    mov ebp, edi
    xor ecx, ecx

.next:
    cmp ecx, edx
    jae .fail
    mov ebx, edi
    add ebx, ecx
    jc .fail
    inc ebx
    jc .fail
    cmp ebx, [sys_exec_string_pool_end]
    ja .fail
    mov eax, esi
    add eax, ecx
    jc .fail
    mov ebx, 1
    call user_range_validate
    jc .fail
    mov al, [esi + ecx]
    mov [edi + ecx], al
    test al, al
    jz .ok
    inc ecx
    jmp .next

.ok:
    mov ebx, edi
    add ebx, ecx
    jc .fail
    inc ebx
    jc .fail
    add ebx, 3
    jc .fail
    and ebx, 0xfffffffc
    cmp ebx, [sys_exec_string_pool_end]
    ja .fail
    mov [sys_exec_string_pool_cursor], ebx
    mov eax, ebx
    sub eax, [sys_exec_string_pool_ptr]
    mov [sys_exec_string_pool_used], eax
    mov eax, ebp
    clc
    jmp .done

.fail:
    stc

.done:
    pop ebp
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

sys_exec_stage_kernel_string:
    push ebx
    push ecx
    push edx
    push esi
    push edi
    push ebp

    mov edi, [sys_exec_string_pool_cursor]
    mov ebp, edi
    xor ecx, ecx

.next:
    cmp ecx, edx
    jae .fail
    mov ebx, edi
    add ebx, ecx
    jc .fail
    inc ebx
    jc .fail
    cmp ebx, [sys_exec_string_pool_end]
    ja .fail
    mov al, [esi + ecx]
    mov [edi + ecx], al
    test al, al
    jz .ok
    inc ecx
    jmp .next

.ok:
    mov ebx, edi
    add ebx, ecx
    jc .fail
    inc ebx
    jc .fail
    add ebx, 3
    jc .fail
    and ebx, 0xfffffffc
    cmp ebx, [sys_exec_string_pool_end]
    ja .fail
    mov [sys_exec_string_pool_cursor], ebx
    mov eax, ebx
    sub eax, [sys_exec_string_pool_ptr]
    mov [sys_exec_string_pool_used], eax
    mov eax, ebp
    clc
    jmp .done

.fail:
    stc

.done:
    pop ebp
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

user_range_validate:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .fail
    cmp ebx, 0
    je .ok
    mov edx, eax
    add edx, ebx
    jc .fail
    mov edi, [esi + PROC_VM_REGIONS]
    mov ecx, [esi + PROC_VM_REGION_COUNT]

.region_next:
    cmp ecx, 0
    je .fail
    cmp eax, [edi + VM_REGION_BASE]
    jb .region_advance
    mov ebx, [edi + VM_REGION_END]
    test dword [edi + VM_REGION_FLAGS], VM_REGION_HEAP
    jz .region_end_ready
    mov ebx, [esi + PROC_BRK]

.region_end_ready:
    cmp edx, ebx
    ja .region_advance
    test dword [edi + VM_REGION_FLAGS], VM_REGION_HEAP
    jz .check_present_pages
    push eax
    call process_heap_range_is_mapped
    pop eax
    jc .fail

.check_present_pages:
    call user_range_pages_present
    jc .fail
    jmp .ok

.region_advance:
    add edi, VM_REGION_BYTES
    dec ecx
    jmp .region_next

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

user_range_pages_present:
    pushad
    cmp esi, 0
    je .fail
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .fail
    cmp edx, eax
    jb .fail
    je .ok

    mov ebp, eax
    and ebp, 0xfffff000
    mov ecx, edx
    dec ecx
    and ecx, 0xfffff000

.page_next:
    mov eax, ebp
    call vmm_find_process_pte
    jc .fail
    test edx, PTE_PRESENT
    jz .fail
    test edx, PTE_USER
    jz .fail
    cmp ebp, ecx
    jae .ok
    add ebp, PAGE_SIZE
    jc .fail
    jmp .page_next

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    popad
    ret

payload_primary_stdout_log_char:
    push eax
    push ebx
    push ecx
    push esi
    push edi

    cmp al, 13
    je .space
    cmp al, 10
    je .space
    cmp al, 9
    je .space
    cmp al, 32
    jb .space
    cmp al, 126
    jbe .have_char

.space:
    mov al, ' '

.have_char:
    mov bl, al
    mov eax, [payload_primary_stdout_log_len]
    cmp eax, PAYLOAD_PRIMARY_STDOUT_LOG_BYTES - 1
    jb .append

    mov esi, payload_primary_stdout_log_buffer + 1
    mov edi, payload_primary_stdout_log_buffer
    mov ecx, PAYLOAD_PRIMARY_STDOUT_LOG_BYTES - 2
    cld
    rep movsb
    mov byte [payload_primary_stdout_log_buffer + PAYLOAD_PRIMARY_STDOUT_LOG_BYTES - 2], bl
    mov byte [payload_primary_stdout_log_buffer + PAYLOAD_PRIMARY_STDOUT_LOG_BYTES - 1], 0
    jmp .done

.append:
    mov edi, payload_primary_stdout_log_buffer
    add edi, eax
    mov [edi], bl
    inc eax
    mov [payload_primary_stdout_log_len], eax
    mov byte [edi + 1], 0

.done:
    pop edi
    pop esi
    pop ecx
    pop ebx
    pop eax
    ret

framebuffer_record_info_query:
    push eax
    inc dword [framebuffer_info_query_count]
    movzx eax, byte [current_user_kind]
    mov [framebuffer_last_info_kind], eax
    mov eax, [current_pid]
    mov [framebuffer_last_info_pid], eax
    or dword [framebuffer_generic_abi_mask], FB_ABI_INFO
    mov dword [framebuffer_generic_last_op], FB_ABI_INFO
    mov dword [framebuffer_generic_last_source], 0
    movzx eax, byte [current_user_kind]
    mov [framebuffer_generic_last_kind], eax

.done:
    pop eax
    ret

framebuffer_record_present_success:
    push eax
    push ebx

    inc dword [framebuffer_present_count]
    cmp eax, FRAMEBUFFER_PRESENT_SOURCE_SYS
    jne .check_ioctl
    inc dword [framebuffer_present_syscall_count]
    jmp .source_counted

.check_ioctl:
    cmp eax, FRAMEBUFFER_PRESENT_SOURCE_IOCTL
    jne .source_counted
    inc dword [framebuffer_present_ioctl_count]

.source_counted:
    mov [framebuffer_last_present_source], eax
    movzx ebx, byte [current_user_kind]
    mov [framebuffer_last_present_kind], ebx
    mov ebx, [current_pid]
    mov [framebuffer_last_present_pid], ebx
    mov ebx, [present_width_arg]
    mov [framebuffer_last_present_width], ebx
    mov ebx, [present_height_arg]
    mov [framebuffer_last_present_height], ebx
    mov ebx, FB_ABI_PRESENT
    cmp eax, FRAMEBUFFER_PRESENT_SOURCE_IOCTL
    jne .generic_source_ready
    or ebx, FB_ABI_IOCTL_PRESENT

.generic_source_ready:
    cmp dword [present_dirty_count], 0
    je .generic_dirty_ready
    or ebx, FB_ABI_DIRTY

.generic_dirty_ready:
    or [framebuffer_generic_abi_mask], ebx
    mov [framebuffer_generic_last_op], ebx
    mov [framebuffer_generic_last_source], eax
    movzx ebx, byte [current_user_kind]
    mov [framebuffer_generic_last_kind], ebx

.generic_done:

    pop ebx
    pop eax
    ret

present_indexed_frame:
    push ebx
    push ecx
    push edx
    push esi
    push edi

    cmp byte [video_backend], VIDEO_BACKEND_LFB_XRGB8888
    je .lfb_present

    mov dx, VGA_DAC_WRITE_INDEX
    xor al, al
    out dx, al
    mov dx, VGA_DAC_DATA
    mov esi, [present_palette_arg]
    mov ecx, FB_PRESENT_PALETTE_BYTES

.palette_next:
    lodsb
    shr al, 2
    out dx, al
    loop .palette_next

.mode13_present:
    call present_set_mode13_geometry
    call present_update_dirty_rect
    call present_copy_indexed_shadow
    call present_update_visual_proof
    jmp .success

.lfb_present:
    call present_select_lfb_geometry
    jc .fail
    call present_update_dirty_rect
    call present_update_visual_proof
    call present_clear_lfb_if_geometry_changed
    call present_lfb_xrgb8888
    jc .fail

.success:
    mov byte [present_status], 1
    clc
    jmp .done

.fail:
    stc

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    ret

present_reset_status_fields:
    mov byte [present_status], 0
    mov dword [present_width_arg], FB_PRESENT_WIDTH
    mov dword [present_height_arg], FB_PRESENT_HEIGHT
    mov dword [present_visual_height_arg], FB_PRESENT_ASPECT_HEIGHT
    mov dword [present_frame_bytes_arg], FB_PRESENT_FRAME_BYTES
    mov dword [present_sample_first], 0
    mov dword [present_sample_mid], 0
    mov dword [present_sample_last], 0
    mov dword [present_palette_hash], 0
    mov dword [present_frame_hash], 0
    mov dword [present_nonzero_count], 0
    mov dword [present_color_transition_count], 0
    mov byte [present_previous_index], 0
    mov dword [present_dirty_x], 0
    mov dword [present_dirty_y], 0
    mov dword [present_dirty_width], 0
    mov dword [present_dirty_height], 0
    mov dword [present_dirty_count], 0
    mov dword [present_lfb_policy], PRESENT_POLICY_MODE13
    mov dword [present_lfb_scale], 1
    mov dword [present_lfb_view_x], 0
    mov dword [present_lfb_view_y], 0
    mov dword [present_lfb_view_width], FB_PRESENT_WIDTH
    mov dword [present_lfb_view_height], FB_PRESENT_HEIGHT
    mov dword [present_lfb_last_view_x], 0xffffffff
    mov dword [present_lfb_last_view_y], 0xffffffff
    mov dword [present_lfb_last_view_width], 0xffffffff
    mov dword [present_lfb_last_view_height], 0xffffffff
    ret

present_set_mode13_geometry:
    mov dword [present_lfb_policy], PRESENT_POLICY_MODE13
    mov dword [present_lfb_scale], 1
    mov dword [present_lfb_view_x], 0
    mov dword [present_lfb_view_y], 0
    mov dword [present_lfb_view_width], FB_PRESENT_WIDTH
    mov dword [present_lfb_view_height], FB_PRESENT_HEIGHT
    ret

present_update_dirty_rect:
    pushad

    mov dword [present_dirty_count], 0
    mov dword [present_dirty_x], 0
    mov dword [present_dirty_y], 0
    mov dword [present_dirty_width], 0
    mov dword [present_dirty_height], 0
    mov dword [present_dirty_min_x], FB_PRESENT_WIDTH
    mov dword [present_dirty_min_y], FB_PRESENT_HEIGHT
    mov dword [present_dirty_max_x], 0
    mov dword [present_dirty_max_y], 0

    cmp byte [video_backend], VIDEO_BACKEND_MODE13
    je .scan_mode13

    mov eax, [framebuffer_source_frame_bytes]
    mov [framebuffer_last_source_bytes], eax
    mov eax, [framebuffer_source_palette_bytes]
    mov [framebuffer_last_palette_bytes], eax
    mov dword [present_dirty_x], 0
    mov dword [present_dirty_y], 0
    mov eax, [present_width_arg]
    mov [present_dirty_width], eax
    mov eax, [present_height_arg]
    mov [present_dirty_height], eax
    mov eax, [present_frame_bytes_arg]
    mov [present_dirty_count], eax
    inc dword [framebuffer_dirty_sequence]
    add [framebuffer_dirty_total_pixels], eax
    jmp .dirty_done

.scan_mode13:

    mov esi, [present_frame_arg]
    mov edi, VGA_GRAPHICS_BUFFER
    xor ebx, ebx

.dirty_y_next:
    cmp ebx, FB_PRESENT_HEIGHT
    jae .dirty_done_scan
    xor ecx, ecx

.dirty_x_next:
    cmp ecx, FB_PRESENT_WIDTH
    jae .dirty_next_row
    mov al, [esi]
    cmp al, [edi]
    je .dirty_same
    inc dword [present_dirty_count]
    cmp ecx, [present_dirty_min_x]
    jae .dirty_min_x_done
    mov [present_dirty_min_x], ecx

.dirty_min_x_done:
    cmp ebx, [present_dirty_min_y]
    jae .dirty_min_y_done
    mov [present_dirty_min_y], ebx

.dirty_min_y_done:
    cmp ecx, [present_dirty_max_x]
    jbe .dirty_max_x_done
    mov [present_dirty_max_x], ecx

.dirty_max_x_done:
    cmp ebx, [present_dirty_max_y]
    jbe .dirty_same
    mov [present_dirty_max_y], ebx

.dirty_same:
    inc esi
    inc edi
    inc ecx
    jmp .dirty_x_next

.dirty_next_row:
    inc ebx
    jmp .dirty_y_next

.dirty_done_scan:
    mov eax, [framebuffer_source_frame_bytes]
    mov [framebuffer_last_source_bytes], eax
    mov eax, [framebuffer_source_palette_bytes]
    mov [framebuffer_last_palette_bytes], eax
    cmp dword [present_dirty_count], 0
    je .dirty_done
    inc dword [framebuffer_dirty_sequence]
    mov eax, [present_dirty_count]
    add [framebuffer_dirty_total_pixels], eax
    mov eax, [present_dirty_min_x]
    mov [present_dirty_x], eax
    mov eax, [present_dirty_min_y]
    mov [present_dirty_y], eax
    mov eax, [present_dirty_max_x]
    sub eax, [present_dirty_min_x]
    inc eax
    mov [present_dirty_width], eax
    mov eax, [present_dirty_max_y]
    sub eax, [present_dirty_min_y]
    inc eax
    mov [present_dirty_height], eax

.dirty_done:
    popad
    ret

present_copy_indexed_shadow:
    push eax
    push ecx
    push esi
    push edi

    mov esi, [present_frame_arg]
    mov edi, VGA_GRAPHICS_BUFFER
    mov ecx, FB_PRESENT_FRAME_BYTES / 4
    cld
    rep movsd

    movzx eax, byte [VGA_GRAPHICS_BUFFER]
    mov [present_sample_first], eax
    movzx eax, byte [VGA_GRAPHICS_BUFFER + 320]
    mov [present_sample_mid], eax
    movzx eax, byte [VGA_GRAPHICS_BUFFER + FB_PRESENT_FRAME_BYTES - 1]
    mov [present_sample_last], eax

    pop edi
    pop esi
    pop ecx
    pop eax
    ret

present_update_visual_proof:
    pushad

    mov esi, [present_palette_arg]
    mov ecx, FB_PRESENT_PALETTE_BYTES
    mov eax, 0x811c9dc5

.palette_hash_next:
    rol eax, 5
    movzx ebx, byte [esi]
    xor eax, ebx
    add eax, 0x01000193
    inc esi
    loop .palette_hash_next
    mov [present_palette_hash], eax

    mov esi, [present_frame_arg]
    mov ecx, [present_frame_bytes_arg]
    mov eax, 0x811c9dc5
    xor edx, edx
    xor edi, edi
    mov byte [present_previous_index], 0

.frame_hash_next:
    rol eax, 5
    movzx ebx, byte [esi]
    xor eax, ebx
    add eax, 0x01000193
    cmp bl, 0
    je .nonzero_done
    inc edx

.nonzero_done:
    cmp ecx, [present_frame_bytes_arg]
    je .transition_done
    cmp bl, byte [present_previous_index]
    je .transition_done
    inc edi

.transition_done:
    mov [present_previous_index], bl
    inc esi
    loop .frame_hash_next

    mov [present_frame_hash], eax
    mov [present_nonzero_count], edx
    mov [present_color_transition_count], edi

    popad
    ret

present_lfb_xrgb8888:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi
    push ebp

    cmp dword [present_lfb_policy], PRESENT_POLICY_ASPECT
    je .aspect
    cmp dword [present_lfb_policy], PRESENT_POLICY_SQUARE
    je .square
    jmp .fail

.aspect:
    call present_lfb_aspect_xrgb8888
    jmp .done_from_render

.square:
    call present_lfb_square_xrgb8888

.done_from_render:
    jc .fail

.ok:
    clc
    jmp .done

.fail:
    stc

.done:
    pop ebp
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

present_select_lfb_geometry:
    push eax
    push ebx
    push ecx
    push edx

    mov eax, [present_width_arg]
    cmp [framebuffer_width], eax
    jb .fail
    mov eax, [present_height_arg]
    cmp [framebuffer_height], eax
    jb .fail

    mov [present_visual_height_arg], eax
    cmp dword [present_width_arg], FB_PRESENT_WIDTH
    jne .visual_height_ready
    cmp dword [present_height_arg], FB_PRESENT_HEIGHT
    jne .visual_height_ready
    mov dword [present_visual_height_arg], FB_PRESENT_ASPECT_HEIGHT

.visual_height_ready:
    mov eax, [framebuffer_width]
    shl eax, 2
    cmp [framebuffer_pitch], eax
    jb .fail

    mov eax, [framebuffer_width]
    xor edx, edx
    mov ebx, [present_width_arg]
    div ebx
    mov ecx, eax
    mov eax, [framebuffer_height]
    xor edx, edx
    mov ebx, [present_visual_height_arg]
    div ebx
    cmp ecx, eax
    jbe .scale_ready
    mov ecx, eax

.scale_ready:
    cmp ecx, 1
    jb .fail
    mov [present_lfb_scale], ecx

    mov eax, [present_visual_height_arg]
    cmp eax, [present_height_arg]
    jne .aspect_policy
    mov dword [present_lfb_policy], PRESENT_POLICY_SQUARE
    jmp .policy_ready

.aspect_policy:
    mov dword [present_lfb_policy], PRESENT_POLICY_ASPECT

.policy_ready:
    mov eax, [present_width_arg]
    mul ecx
    mov [present_lfb_view_width], eax
    mov eax, [present_visual_height_arg]
    mul ecx
    mov [present_lfb_view_height], eax

.compute_center:
    mov eax, [framebuffer_width]
    sub eax, [present_lfb_view_width]
    shr eax, 1
    mov [present_lfb_view_x], eax
    shl eax, 2
    mov [present_lfb_x_offset], eax

    mov eax, [framebuffer_height]
    sub eax, [present_lfb_view_height]
    shr eax, 1
    mov [present_lfb_view_y], eax
    clc
    jmp .done

.fail:
    stc

.done:
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

present_clear_lfb_if_geometry_changed:
    push eax

    mov eax, [present_lfb_view_x]
    cmp eax, [present_lfb_last_view_x]
    jne .clear
    mov eax, [present_lfb_view_y]
    cmp eax, [present_lfb_last_view_y]
    jne .clear
    mov eax, [present_lfb_view_width]
    cmp eax, [present_lfb_last_view_width]
    jne .clear
    mov eax, [present_lfb_view_height]
    cmp eax, [present_lfb_last_view_height]
    jne .clear
    jmp .done

.clear:
    call present_clear_lfb
    mov eax, [present_lfb_view_x]
    mov [present_lfb_last_view_x], eax
    mov eax, [present_lfb_view_y]
    mov [present_lfb_last_view_y], eax
    mov eax, [present_lfb_view_width]
    mov [present_lfb_last_view_width], eax
    mov eax, [present_lfb_view_height]
    mov [present_lfb_last_view_height], eax

.done:
    pop eax
    ret

present_clear_lfb:
    pushad
    mov edi, [framebuffer_addr]
    mov eax, [framebuffer_pitch]
    mul dword [framebuffer_height]
    shr eax, 2
    mov ecx, eax
    xor eax, eax
    cld
    rep stosd
    popad
    ret

present_lfb_start_row:
    push edx
    mov eax, [present_lfb_view_y]
    mul dword [framebuffer_pitch]
    add eax, [present_lfb_x_offset]
    add eax, [framebuffer_addr]
    mov [present_lfb_row], eax
    pop edx
    ret

present_lfb_square_xrgb8888:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    call present_lfb_start_row
    xor ebx, ebx

.source_row_next:
    cmp ebx, [present_height_arg]
    jae .ok
    mov eax, ebx
    mov ecx, [present_width_arg]
    mul ecx
    add eax, [present_frame_arg]
    mov esi, eax
    mov ecx, [present_lfb_scale]

.repeat_row:
    mov edi, [present_lfb_row]
    push esi
    call present_lfb_render_scaled_row
    pop esi
    mov eax, [framebuffer_pitch]
    add [present_lfb_row], eax
    dec ecx
    jnz .repeat_row
    inc ebx
    jmp .source_row_next

.ok:
    clc
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

present_lfb_aspect_xrgb8888:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    call present_lfb_start_row
    xor ebx, ebx

.visual_row_next:
    cmp ebx, [present_visual_height_arg]
    jae .ok
    mov eax, ebx
    mov ecx, [present_height_arg]
    mul ecx
    mov ecx, [present_visual_height_arg]
    div ecx
    mov [present_lfb_source_y], eax
    mov ecx, [present_width_arg]
    mul ecx
    add eax, [present_frame_arg]
    mov esi, eax
    mov ecx, [present_lfb_scale]

.repeat_row:
    mov edi, [present_lfb_row]
    push esi
    call present_lfb_render_scaled_row
    pop esi
    mov eax, [framebuffer_pitch]
    add [present_lfb_row], eax
    dec ecx
    jnz .repeat_row
    inc ebx
    jmp .visual_row_next

.ok:
    clc
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

present_lfb_render_scaled_row:
    push eax
    push ebx
    push ecx
    push edx
    push ebp

    mov ecx, [present_width_arg]

.pixel_next:
    movzx ebx, byte [esi]
    inc esi
    lea edx, [ebx + ebx * 2]
    add edx, [present_palette_arg]
    xor eax, eax
    cmp dword [framebuffer_color_order], FRAMEBUFFER_COLOR_ORDER_XBGR
    je .pack_xbgr
    movzx ebx, byte [edx]
    shl ebx, 16
    or eax, ebx
    movzx ebx, byte [edx + 1]
    shl ebx, 8
    or eax, ebx
    movzx ebx, byte [edx + 2]
    or eax, ebx
    jmp .packed
.pack_xbgr:
    movzx ebx, byte [edx + 2]
    shl ebx, 16
    or eax, ebx
    movzx ebx, byte [edx + 1]
    shl ebx, 8
    or eax, ebx
    movzx ebx, byte [edx]
    or eax, ebx
.packed:
    mov ebp, [present_lfb_scale]

.repeat_pixel:
    mov [edi], eax
    add edi, 4
    dec ebp
    jnz .repeat_pixel
    loop .pixel_next

    pop ebp
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

input_reset_queue:
    mov dword [input_event_head], 0
    mov dword [input_event_tail], 0
    mov dword [input_event_count], 0
    mov dword [input_event_poll_count], 0
    mov dword [input_event_drop_count], 0
    mov dword [input_keyboard_poll_count], 0
    mov dword [input_mouse_event_count], 0
    mov dword [input_mouse_poll_count], 0
    mov dword [input_keyboard_drop_count], 0
    mov dword [input_mouse_drop_count], 0
    mov dword [input_keyboard_last_timestamp], 0
    mov dword [input_mouse_last_timestamp], 0
    mov dword [input_keyboard_modifiers], 0
    mov dword [input_keyboard_down_count], 0
    mov dword [input_keyboard_last_code], 0
    mov dword [input_keyboard_state + 0], 0
    mov dword [input_keyboard_state + 4], 0
    mov dword [input_keyboard_state + 8], 0
    mov dword [input_keyboard_state + 12], 0
    mov dword [input_keyboard_state + 16], 0
    mov dword [input_keyboard_state + 20], 0
    mov dword [input_keyboard_state + 24], 0
    mov dword [input_keyboard_state + 28], 0
    mov dword [input_mouse_buttons], 0
    mov dword [input_mouse_delta_x_total], 0
    mov dword [input_mouse_delta_y_total], 0
    mov dword [input_last_event_device], 0
    mov dword [input_last_event_type], 0
    mov dword [payload_primary_input_event_count], 0
    mov dword [payload_primary_input_last_timestamp], 0
    mov dword [payload_primary_input_last_device], 0
    mov dword [payload_primary_input_last_type], 0
    ret

keyboard_reset_queue:
    mov dword [key_event_head], 0
    mov dword [key_event_tail], 0
    mov dword [keyboard_irq_count], 0
    mov dword [keyboard_event_count], 0
    mov dword [payload_primary_key_event_count], 0
    mov dword [payload_primary_key_down_seen], 0
    mov dword [payload_primary_key_last_event], 0
    mov byte [keyboard_status], INPUT_DEVICE_STATUS_READY
    mov byte [keyboard_extended], 0
    mov byte [keyboard_e1_skip_remaining], 0
    ret

keyboard_queue_scancode:
    push eax
    push ebx
    push ecx
    push edx

    cmp byte [keyboard_e1_skip_remaining], 0
    je .not_e1_sequence
    dec byte [keyboard_e1_skip_remaining]
    mov byte [keyboard_extended], 0
    jmp .done

.not_e1_sequence:
    cmp al, 0xe0
    je .extended_prefix
    cmp al, 0xe1
    je .e1_prefix

    mov bl, al
    mov dl, 1
    test bl, 0x80
    jz .have_scancode
    and bl, 0x7f
    xor dl, dl

.have_scancode:
    test bl, bl
    jz .clear_extended
    mov cl, [keyboard_extended]
    mov byte [keyboard_extended], 0
    movzx ebx, bl
    mov eax, ebx
    test cl, cl
    jz .queue_generic
    or eax, VIBE_INPUT_KEY_PS2_SET1_EXTENDED

.queue_generic:
    call input_queue_key_event
    call keyboard_translate_payload_key

.queue:
    call keyboard_queue_event
    jmp .done

.clear_extended:
    mov byte [keyboard_extended], 0
    jmp .done

.extended_prefix:
    mov byte [keyboard_extended], 1
    jmp .done

.e1_prefix:
    mov byte [keyboard_extended], 0
    mov byte [keyboard_e1_skip_remaining], 5
    jmp .done

.ignore:
    mov byte [keyboard_extended], 0

.done:
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

keyboard_translate_payload_key:
    push ebx

    mov bl, al
    test bl, VIBE_INPUT_KEY_PS2_SET1_EXTENDED
    jnz .extended
    movzx ebx, bl
    and ebx, VIBE_INPUT_KEY_PS2_SET1_SCANCODE_MASK
    mov al, [payload_keycode_map + ebx]
    jmp .done

.extended:
    and bl, VIBE_INPUT_KEY_PS2_SET1_SCANCODE_MASK
    xor al, al
    cmp bl, 0x48
    je .ext_up
    cmp bl, 0x50
    je .ext_down
    cmp bl, 0x4b
    je .ext_left
    cmp bl, 0x4d
    je .ext_right
    cmp bl, 0x1c
    je .ext_enter
    cmp bl, 0x1d
    je .ext_ctrl
    cmp bl, 0x38
    je .ext_alt
    cmp bl, 0x53
    je .ext_backspace
    jmp .done

.ext_up:
    mov al, PAYLOAD_KEY_UPARROW
    jmp .done

.ext_down:
    mov al, PAYLOAD_KEY_DOWNARROW
    jmp .done

.ext_left:
    mov al, PAYLOAD_KEY_LEFTARROW
    jmp .done

.ext_right:
    mov al, PAYLOAD_KEY_RIGHTARROW
    jmp .done

.ext_enter:
    mov al, PAYLOAD_KEY_ENTER
    jmp .done

.ext_ctrl:
    mov al, PAYLOAD_KEY_RCTRL
    jmp .done

.ext_alt:
    mov al, PAYLOAD_KEY_RALT
    jmp .done

.ext_backspace:
    mov al, PAYLOAD_KEY_BACKSPACE

.done:
    pop ebx
    ret

keyboard_queue_event:
    test al, al
    jz .done
    push ebx
    push edx
    push edi

    movzx eax, al
    or eax, KEY_EVENT_VALID
    test dl, dl
    jz .have_packed
    or eax, KEY_EVENT_DOWN

.have_packed:
    mov ebx, [key_event_head]
    mov edx, ebx
    inc edx
    and edx, KEY_QUEUE_MASK
    cmp edx, [key_event_tail]
    jne .space_available
    mov edi, [key_event_tail]
    inc edi
    and edi, KEY_QUEUE_MASK
    mov [key_event_tail], edi

.space_available:
    mov edi, key_event_queue
    mov [edi + ebx * 4], eax
    mov [key_event_head], edx

    pop edi
    pop edx
    pop ebx

    .done:
    ret

input_drop_oldest_event:
    push eax
    push ebx
    push edx
    push esi

    inc dword [input_event_drop_count]
    mov ebx, [input_event_tail]
    mov esi, input_event_queue
    mov edx, ebx
    imul edx, VIBE_INPUT_EVENT_BYTES
    add esi, edx
    mov eax, [esi + VIBE_INPUT_EVENT_DEVICE_ID]
    cmp eax, VIBE_INPUT_DEVICE_KEYBOARD
    je .drop_keyboard
    cmp eax, VIBE_INPUT_DEVICE_MOUSE
    je .drop_mouse
    jmp .advance_tail

.drop_keyboard:
    inc dword [input_keyboard_drop_count]
    jmp .advance_tail

.drop_mouse:
    inc dword [input_mouse_drop_count]

.advance_tail:
    inc ebx
    and ebx, INPUT_EVENT_QUEUE_MASK
    mov [input_event_tail], ebx

    pop esi
    pop edx
    pop ebx
    pop eax
    ret

input_record_generic_abi:
    push edx
    or [input_generic_abi_mask], eax
    mov [input_generic_last_op], eax
    movzx edx, byte [current_user_kind]
    mov [input_generic_last_kind], edx
    mov [input_generic_last_result], ecx

.done:
    pop edx
    ret

input_refresh_keyboard_modifiers:
    push eax

    xor eax, eax
    test dword [input_keyboard_state + 4], 0x00400400
    jz .check_ctrl
    or eax, VIBE_INPUT_MOD_SHIFT

.check_ctrl:
    test dword [input_keyboard_state + 0], 0x20000000
    jnz .set_ctrl
    test dword [input_keyboard_state + 16], 0x20000000
    jz .check_alt

.set_ctrl:
    or eax, VIBE_INPUT_MOD_CTRL

.check_alt:
    test dword [input_keyboard_state + 4], 0x01000000
    jnz .set_alt
    test dword [input_keyboard_state + 20], 0x01000000
    jz .done

.set_alt:
    or eax, VIBE_INPUT_MOD_ALT

.done:
    mov [input_keyboard_modifiers], eax
    pop eax
    ret

input_queue_key_event:
    push eax
    push ebx
    push ecx
    push edx
    push edi

    mov ebx, [input_event_head]
    mov edx, ebx
    inc edx
    and edx, INPUT_EVENT_QUEUE_MASK
    cmp edx, [input_event_tail]
    jne .space_available
    call input_drop_oldest_event

.space_available:
    mov edi, ebx
    imul edi, edi, VIBE_INPUT_EVENT_BYTES
    add edi, input_event_queue
    mov ecx, [timer_ticks]
    mov [edi + VIBE_INPUT_EVENT_TIMESTAMP], ecx
    mov [input_keyboard_last_timestamp], ecx
    mov dword [edi + VIBE_INPUT_EVENT_DEVICE_ID], VIBE_INPUT_DEVICE_KEYBOARD
    mov dword [edi + VIBE_INPUT_EVENT_TYPE], VIBE_INPUT_EVENT_KEY
    mov ecx, [esp + 16]
    and ecx, 0xff
    mov [edi + VIBE_INPUT_EVENT_CODE], ecx
    xor ecx, ecx
    test byte [esp + 4], 0xff
    jz .have_value0
    mov ecx, VIBE_INPUT_KEY_PRESSED

.have_value0:
    mov [edi + VIBE_INPUT_EVENT_VALUE0], ecx
    mov dword [edi + VIBE_INPUT_EVENT_VALUE1], 0
    mov dword [edi + VIBE_INPUT_EVENT_VALUE2], 0
    mov ecx, [esp + 16]
    and ecx, 0xff
    mov [input_keyboard_last_code], ecx
    test byte [esp + 4], 0xff
    jz .key_released
    bt dword [input_keyboard_state], ecx
    jc .key_state_done
    bts dword [input_keyboard_state], ecx
    inc dword [input_keyboard_down_count]
    jmp .key_state_done

.key_released:
    bt dword [input_keyboard_state], ecx
    jnc .key_state_done
    btr dword [input_keyboard_state], ecx
    dec dword [input_keyboard_down_count]

.key_state_done:
    call input_refresh_keyboard_modifiers
    mov dword [input_last_event_device], VIBE_INPUT_DEVICE_KEYBOARD
    mov dword [input_last_event_type], VIBE_INPUT_EVENT_KEY
    mov edx, ebx
    inc edx
    and edx, INPUT_EVENT_QUEUE_MASK
    mov [input_event_head], edx
    inc dword [input_event_count]
    inc dword [keyboard_event_count]

    pop edi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

input_queue_mouse_packet_event:
    push eax
    push ebx
    push ecx
    push edx
    push edi

    mov ebx, [input_event_head]
    mov edx, ebx
    inc edx
    and edx, INPUT_EVENT_QUEUE_MASK
    cmp edx, [input_event_tail]
    jne .space_available
    call input_drop_oldest_event

.space_available:
    mov edi, ebx
    imul edi, edi, VIBE_INPUT_EVENT_BYTES
    add edi, input_event_queue
    mov ecx, [timer_ticks]
    mov [edi + VIBE_INPUT_EVENT_TIMESTAMP], ecx
    mov [input_mouse_last_timestamp], ecx
    mov dword [edi + VIBE_INPUT_EVENT_DEVICE_ID], VIBE_INPUT_DEVICE_MOUSE
    mov dword [edi + VIBE_INPUT_EVENT_TYPE], VIBE_INPUT_EVENT_MOUSE_PACKET
    mov ecx, [esp + 16]
    and ecx, 0x07
    mov [edi + VIBE_INPUT_EVENT_CODE], ecx
    mov ecx, [esp + 16]
    shr ecx, 8
    movsx ecx, cl
    mov [edi + VIBE_INPUT_EVENT_VALUE0], ecx
    mov ecx, [esp + 16]
    shr ecx, 16
    movsx ecx, cl
    mov [edi + VIBE_INPUT_EVENT_VALUE1], ecx
    mov dword [edi + VIBE_INPUT_EVENT_VALUE2], 0
    mov ecx, [esp + 16]
    and ecx, 0x07
    mov [input_mouse_buttons], ecx
    mov ecx, [esp + 16]
    shr ecx, 8
    movsx ecx, cl
    add [input_mouse_delta_x_total], ecx
    mov ecx, [esp + 16]
    shr ecx, 16
    movsx ecx, cl
    add [input_mouse_delta_y_total], ecx
    mov dword [input_last_event_device], VIBE_INPUT_DEVICE_MOUSE
    mov dword [input_last_event_type], VIBE_INPUT_EVENT_MOUSE_PACKET
    mov edx, ebx
    inc edx
    and edx, INPUT_EVENT_QUEUE_MASK
    mov [input_event_head], edx
    inc dword [input_event_count]
    inc dword [input_mouse_event_count]

    pop edi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

mouse_reset_queue:
    mov dword [mouse_event_head], 0
    mov dword [mouse_event_tail], 0
    mov dword [mouse_irq_count], 0
    mov dword [mouse_packet_count], 0
    mov dword [mouse_sync_loss_count], 0
    mov dword [payload_primary_mouse_event_count], 0
    mov dword [payload_primary_mouse_buttons_seen], 0
    mov dword [payload_primary_mouse_delta_x], 0
    mov dword [payload_primary_mouse_delta_y], 0
    mov dword [payload_primary_mouse_last_event], 0
    mov byte [mouse_packet_index], 0
    mov byte [mouse_packet0], 0
    mov byte [mouse_packet1], 0
    mov byte [mouse_packet2], 0
    ret

mouse_queue_byte:
    push eax
    push ebx
    push edx

    mov bl, al
    cmp byte [mouse_packet_index], 0
    je .packet0
    cmp byte [mouse_packet_index], 1
    je .packet1
    cmp byte [mouse_packet_index], 2
    je .packet2
    mov byte [mouse_packet_index], 0
    jmp .packet0

.packet2:
    mov [mouse_packet2], bl
    mov byte [mouse_packet_index], 0
    call mouse_decode_packet
    jmp .done

.packet0:
    test bl, PS2_MOUSE_PACKET_SYNC_BIT
    jnz .packet0_ok
    inc dword [mouse_sync_loss_count]
    jmp .done

.packet0_ok:
    mov [mouse_packet0], bl
    mov byte [mouse_packet_index], 1
    jmp .done

.packet1:
    mov [mouse_packet1], bl
    mov byte [mouse_packet_index], 2

.done:
    pop edx
    pop ebx
    pop eax
    ret

mouse_decode_packet:
    push eax
    push ebx

    mov al, [mouse_packet0]
    test al, PS2_MOUSE_PACKET_OVERFLOW_MASK
    jnz .invalid

    mov bl, [mouse_packet1]
    test al, PS2_MOUSE_PACKET_X_SIGN
    jz .x_nonnegative
    test bl, 0x80
    jz .invalid
    jmp .x_sign_ok

.x_nonnegative:
    test bl, 0x80
    jnz .invalid

.x_sign_ok:
    mov bl, [mouse_packet2]
    test al, PS2_MOUSE_PACKET_Y_SIGN
    jz .y_nonnegative
    test bl, 0x80
    jz .invalid
    jmp .y_sign_ok

.y_nonnegative:
    test bl, 0x80
    jnz .invalid

.y_sign_ok:

    movzx eax, al
    and eax, PS2_MOUSE_PACKET_BUTTON_MASK
    movzx ebx, byte [mouse_packet1]
    shl ebx, 8
    or eax, ebx
    movzx ebx, byte [mouse_packet2]
    shl ebx, 16
    or eax, ebx
    or eax, MOUSE_EVENT_VALID
    call mouse_queue_event
    inc dword [mouse_packet_count]
    jmp .done

.invalid:
    inc dword [mouse_sync_loss_count]
    mov al, [mouse_packet2]
    test al, PS2_MOUSE_PACKET_SYNC_BIT
    jz .done
    test al, PS2_MOUSE_PACKET_OVERFLOW_MASK
    jnz .done
    mov [mouse_packet0], al
    mov byte [mouse_packet_index], 1

.done:
    pop ebx
    pop eax
    ret

mouse_queue_event:
    push ebx
    push edx
    push edi

    mov ebx, [mouse_event_head]
    mov edx, ebx
    inc edx
    and edx, MOUSE_QUEUE_MASK
    cmp edx, [mouse_event_tail]
    jne .space_available
    mov edi, [mouse_event_tail]
    inc edi
    and edi, MOUSE_QUEUE_MASK
    mov [mouse_event_tail], edi

.space_available:
    mov edi, mouse_event_queue
    mov [edi + ebx * 4], eax
    mov [mouse_event_head], edx
    call input_queue_mouse_packet_event

    pop edi
    pop edx
    pop ebx
    ret

payload_primary_record_key_event:
    push eax
    push ebx

    mov [payload_primary_key_last_event], eax
    test eax, KEY_EVENT_DOWN
    jz .done
    mov ebx, eax
    and ebx, 0xff
    cmp bl, PAYLOAD_KEY_UPARROW
    je .seen_up
    cmp bl, PAYLOAD_KEY_DOWNARROW
    je .seen_down
    cmp bl, PAYLOAD_KEY_LEFTARROW
    je .seen_left
    cmp bl, PAYLOAD_KEY_RIGHTARROW
    je .seen_right
    cmp bl, PAYLOAD_KEY_RCTRL
    je .seen_fire
    cmp bl, 32
    je .seen_use
    cmp bl, PAYLOAD_KEY_ESCAPE
    je .seen_menu
    cmp bl, PAYLOAD_KEY_ENTER
    je .seen_enter
    jmp .done

.seen_up:
    or dword [payload_primary_key_down_seen], KEY_PROOF_UP
    jmp .done

.seen_down:
    or dword [payload_primary_key_down_seen], KEY_PROOF_DOWN
    jmp .done

.seen_left:
    or dword [payload_primary_key_down_seen], KEY_PROOF_LEFT
    jmp .done

.seen_right:
    or dword [payload_primary_key_down_seen], KEY_PROOF_RIGHT
    jmp .done

.seen_fire:
    or dword [payload_primary_key_down_seen], KEY_PROOF_FIRE
    jmp .done

.seen_use:
    or dword [payload_primary_key_down_seen], KEY_PROOF_USE
    jmp .done

.seen_menu:
    or dword [payload_primary_key_down_seen], KEY_PROOF_MENU
    jmp .done

.seen_enter:
    or dword [payload_primary_key_down_seen], KEY_PROOF_ENTER

.done:
    pop ebx
    pop eax
    ret

payload_primary_record_mouse_event:
    push eax
    push ebx
    push edx

    mov [payload_primary_mouse_last_event], eax

    mov ebx, eax
    and ebx, 0x07
    or dword [payload_primary_mouse_buttons_seen], ebx

    mov ebx, eax
    shr ebx, 8
    movsx ebx, bl
    test ebx, ebx
    jns .dx_positive
    neg ebx

.dx_positive:
    add dword [payload_primary_mouse_delta_x], ebx

    mov ebx, eax
    shr ebx, 16
    movsx ebx, bl
    test ebx, ebx
    jns .dy_positive
    neg ebx

.dy_positive:
    add dword [payload_primary_mouse_delta_y], ebx

    pop edx
    pop ebx
    pop eax
    ret

payload_primary_record_input_event:
    push eax
    push ebx
    push ecx

    inc dword [payload_primary_input_event_count]
    mov eax, [esi + VIBE_INPUT_EVENT_TIMESTAMP]
    mov [payload_primary_input_last_timestamp], eax
    mov eax, [esi + VIBE_INPUT_EVENT_DEVICE_ID]
    mov [payload_primary_input_last_device], eax
    mov eax, [esi + VIBE_INPUT_EVENT_TYPE]
    mov [payload_primary_input_last_type], eax
    cmp eax, VIBE_INPUT_EVENT_KEY
    je .key
    cmp eax, VIBE_INPUT_EVENT_MOUSE_PACKET
    je .mouse_packet
    jmp .done

.key:
    mov eax, [esi + VIBE_INPUT_EVENT_CODE]
    and eax, 0xff
    test eax, eax
    jz .done
    call keyboard_translate_payload_key
    test al, al
    jz .done
    movzx eax, al
    or eax, KEY_EVENT_VALID
    cmp dword [esi + VIBE_INPUT_EVENT_VALUE0], 0
    je .key_have_packed
    or eax, KEY_EVENT_DOWN

.key_have_packed:
    call payload_primary_record_key_event
    inc dword [payload_primary_key_event_count]
    jmp .done

.mouse_packet:
    mov eax, [esi + VIBE_INPUT_EVENT_CODE]
    and eax, 0x07
    mov ebx, [esi + VIBE_INPUT_EVENT_VALUE0]
    and ebx, 0xff
    shl ebx, 8
    or eax, ebx
    mov ebx, [esi + VIBE_INPUT_EVENT_VALUE1]
    and ebx, 0xff
    shl ebx, 16
    or eax, ebx
    or eax, MOUSE_EVENT_VALID
    call payload_primary_record_mouse_event
    inc dword [payload_primary_mouse_event_count]

.done:
    pop ecx
    pop ebx
    pop eax
    ret

%macro EXCEPTION_NO_ERROR_BODY 1
    push dword 0
    push dword %1
    jmp exception_common
%endmacro

%macro EXCEPTION_ERROR_BODY 1
    push dword %1
    jmp exception_common
%endmacro

%macro IRQ_ENTER 0
    pushad
    xor eax, eax
    mov ax, ds
    push eax
    mov ax, es
    push eax
    mov ax, fs
    push eax
    mov ax, gs
    push eax
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    cld
%endmacro

%macro IRQ_RETURN 0
    pop eax
    mov gs, ax
    pop eax
    mov fs, ax
    pop eax
    mov es, ax
    pop eax
    mov ds, ax
    popad
    iretd
%endmacro

exception_divide_error:
    EXCEPTION_NO_ERROR_BODY 0

exception_debug:
    EXCEPTION_NO_ERROR_BODY 1

exception_nmi:
    EXCEPTION_NO_ERROR_BODY 2

exception_breakpoint:
    EXCEPTION_NO_ERROR_BODY 3

exception_overflow:
    EXCEPTION_NO_ERROR_BODY 4

exception_bound_range:
    EXCEPTION_NO_ERROR_BODY 5

exception_invalid_opcode:
    EXCEPTION_NO_ERROR_BODY 6

exception_device_not_available:
    EXCEPTION_NO_ERROR_BODY 7

exception_double_fault:
    EXCEPTION_ERROR_BODY 8

exception_coprocessor_segment:
    EXCEPTION_NO_ERROR_BODY 9

exception_invalid_tss:
    EXCEPTION_ERROR_BODY 10

exception_segment_not_present:
    EXCEPTION_ERROR_BODY 11

exception_stack_fault:
    EXCEPTION_ERROR_BODY 12

exception_general_protection:
    EXCEPTION_ERROR_BODY 13

page_fault_handler:
    EXCEPTION_ERROR_BODY 14

exception_reserved_15:
    EXCEPTION_NO_ERROR_BODY 15

exception_x87_fpu:
    EXCEPTION_NO_ERROR_BODY 16

exception_alignment_check:
    EXCEPTION_ERROR_BODY 17

exception_machine_check:
    EXCEPTION_NO_ERROR_BODY 18

exception_simd_fpu:
    EXCEPTION_NO_ERROR_BODY 19

exception_virtualization:
    EXCEPTION_NO_ERROR_BODY 20

exception_control_protection:
    EXCEPTION_ERROR_BODY 21

exception_reserved_22:
    EXCEPTION_NO_ERROR_BODY 22

exception_reserved_23:
    EXCEPTION_NO_ERROR_BODY 23

exception_reserved_24:
    EXCEPTION_NO_ERROR_BODY 24

exception_reserved_25:
    EXCEPTION_NO_ERROR_BODY 25

exception_reserved_26:
    EXCEPTION_NO_ERROR_BODY 26

exception_reserved_27:
    EXCEPTION_NO_ERROR_BODY 27

exception_hypervisor:
    EXCEPTION_NO_ERROR_BODY 28

exception_vmm_communication:
    EXCEPTION_ERROR_BODY 29

exception_security:
    EXCEPTION_ERROR_BODY 30

exception_reserved_31:
    EXCEPTION_NO_ERROR_BODY 31

exception_halt:
    push dword 0
    push dword 0xffffffff
    jmp exception_common

exception_common:
    push eax
    xor eax, eax
    mov ax, ds
    push eax
    mov ax, es
    push eax
    mov ax, fs
    push eax
    mov ax, gs
    push eax
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    pop eax
    mov [fault_gs], eax
    pop eax
    mov [fault_fs], eax
    pop eax
    mov [fault_es], eax
    pop eax
    mov [fault_ds], eax
    pop eax
    mov [fault_eax], eax
    mov [fault_ebx], ebx
    mov [fault_ecx], ecx
    mov [fault_edx], edx
    mov [fault_esi], esi
    mov [fault_edi], edi
    mov [fault_ebp], ebp
    mov eax, [esp + EXCEPTION_FRAME_VECTOR]
    mov [fault_vector], eax
    mov eax, [esp + EXCEPTION_FRAME_ERROR]
    mov [fault_error], eax
    mov eax, [esp + EXCEPTION_FRAME_EIP]
    mov [fault_eip], eax
    mov eax, [esp + EXCEPTION_FRAME_CS]
    mov [fault_cs], eax
    mov eax, [esp + EXCEPTION_FRAME_EFLAGS]
    mov [fault_eflags], eax
    mov eax, [esp + EXCEPTION_FRAME_CS]
    test eax, 3
    jz .kernel_frame
    mov eax, [esp + EXCEPTION_FRAME_ESP]
    mov [fault_esp], eax
    mov eax, [esp + EXCEPTION_FRAME_SS]
    mov [fault_ss], eax
    jmp .frame_done

.kernel_frame:
    lea eax, [esp + 20]
    mov [fault_esp], eax
    mov dword [fault_ss], DATA_SEG

.frame_done:
    mov eax, cr2
    mov [fault_cr2], eax
    mov eax, cr3
    mov [fault_cr3], eax
    mov dword [fault_source], FAULT_SOURCE_NONE
    mov dword [fault_mode], FAULT_MODE_NONE
    mov dword [fault_contained], 0
    mov eax, [fault_cs]
    test eax, 3
    jz .kernel_privilege_fault
    mov dword [fault_mode], FAULT_MODE_USER
    jmp .privilege_recorded

.kernel_privilege_fault:
    mov dword [fault_mode], FAULT_MODE_KERNEL

.privilege_recorded:
    mov eax, [current_pid]
    mov [fault_pid], eax
    movzx eax, byte [current_user_kind]
    mov [fault_kind], eax
    mov dword [fault_state], 0
    mov dword [fault_proc_ptr], 0
    mov dword [fault_proc_base], 0
    mov dword [fault_proc_end], 0
    mov dword [fault_proc_brk], 0
    mov dword [fault_proc_heap_start], 0
    mov dword [fault_proc_heap_end], 0
    mov dword [fault_proc_stack_top], 0
    mov dword [fault_proc_entry], 0
    mov esi, [current_process_ptr]
    cmp esi, 0
    je .no_process
    mov [fault_proc_ptr], esi
    mov eax, [esi + PROC_STATE]
    mov [fault_state], eax
    mov eax, [esi + PROC_BASE]
    mov [fault_proc_base], eax
    mov eax, [esi + PROC_END]
    mov [fault_proc_end], eax
    mov eax, [esi + PROC_BRK]
    mov [fault_proc_brk], eax
    mov eax, [esi + PROC_HEAP_START]
    mov [fault_proc_heap_start], eax
    mov eax, [esi + PROC_HEAP_END]
    mov [fault_proc_heap_end], eax
    mov eax, [esi + PROC_STACK_TOP]
    mov [fault_proc_stack_top], eax
    mov eax, [esi + PROC_ENTRY]
    mov [fault_proc_entry], eax

.no_process:
    call fault_capture_instruction_bytes
    mov eax, [current_syscall_number]
    mov [fault_last_syscall], eax
    call fpu_record_exception_if_math

    cmp dword [fault_vector], 14
    jne .not_expected_user_fault
    mov eax, [fault_cs]
    test eax, 3
    jz .not_expected_user_fault
    cmp byte [user_fault_expected], 1
    jne .not_expected_user_fault
    mov byte [user_fault_expected], 0
    mov byte [user_fault_status], 1
    mov byte [user_probe_status], 3
    mov dword [fault_source], FAULT_SOURCE_EXPECTED
    mov dword [fault_mode], FAULT_MODE_USER
    mov dword [fault_contained], 1
    inc dword [fault_expected_recovered_count]
    mov eax, [fault_cr2]
    mov [user_fault_addr], eax
    mov eax, [user_fault_recovery]
    mov dword [user_fault_recovery], 0
    cmp eax, 0
    je .expected_fault_skip_instruction
    mov [esp + EXCEPTION_FRAME_EIP], eax
    jmp .expected_fault_return

.expected_fault_skip_instruction:
    add dword [esp + EXCEPTION_FRAME_EIP], EXPECTED_FAULT_INSTRUCTION_BYTES

.expected_fault_return:
    mov ax, USER_DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    mov ebx, [fault_ebx]
    mov ecx, [fault_ecx]
    mov edx, [fault_edx]
    mov eax, [fault_eax]
    mov esi, [fault_esi]
    mov edi, [fault_edi]
    mov ebp, [fault_ebp]
    add esp, 8
    iretd

.not_expected_user_fault:
    mov eax, [fault_cs]
    test eax, 3
    jz .kernel_panic
    call large_elf_demand_page_fault
    jnc .demand_fault_return
    movzx eax, byte [current_user_kind]
    call user_kind_is_large_payload
    jnc payload_user_fault
    jmp user_process_fault

.demand_fault_return:
    mov eax, [fault_ds]
    mov ds, ax
    mov eax, [fault_es]
    mov es, ax
    mov eax, [fault_fs]
    mov fs, ax
    mov eax, [fault_gs]
    mov gs, ax
    mov ebx, [fault_ebx]
    mov ecx, [fault_ecx]
    mov edx, [fault_edx]
    mov eax, [fault_eax]
    mov esi, [fault_esi]
    mov edi, [fault_edi]
    mov ebp, [fault_ebp]
    add esp, 8
    iretd

.kernel_panic:
    cli
    mov dword [fault_source], FAULT_SOURCE_KERNEL
    mov dword [fault_mode], FAULT_MODE_KERNEL
    mov dword [fault_contained], 0
    inc dword [fault_kernel_panic_count]
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    mov ss, ax
    call kernel_switch_main_stack_and_return
    mov dword [panic_status], PANIC_UNHANDLED_EXCEPTION
    call write_smoke_status
    call panic_dump_fault
    call write_smoke_status

.halt:
    hlt
    jmp .halt

fault_capture_instruction_bytes:
    pushad

    mov dword [fault_insn_phys], 0
    mov dword [fault_insn_offset], 0
    mov dword [fault_insn_word0], 0
    mov dword [fault_insn_word1], 0
    mov dword [fault_insn_word2], 0
    mov dword [fault_insn_word3], 0

    mov esi, [current_process_ptr]
    cmp esi, 0
    je .done
    cmp esi, process_kernel
    je .done
    mov ebx, [esi + PROC_PAGE_DIR]
    test ebx, ebx
    jz .done

    mov eax, [fault_eip]
    call vmm_find_process_pte
    jc .done
    test edx, PTE_PRESENT
    jz .done
    test edx, PTE_USER
    jz .done

    mov eax, edx
    and eax, 0xfffff000
    mov [fault_insn_phys], eax
    mov ecx, [fault_eip]
    and ecx, 0x00000fff
    mov [fault_insn_offset], ecx
    cmp ecx, PAGE_SIZE - 16
    ja .done

    pushfd
    cli
    mov ebx, eax
    mov eax, FORK_COPY_SRC_ALIAS
    mov ecx, PTE_KERNEL_FLAGS
    call vmm_map_page
    jc .alias_fail

    mov esi, FORK_COPY_SRC_ALIAS
    add esi, [fault_insn_offset]
    mov eax, [esi]
    mov [fault_insn_word0], eax
    mov eax, [esi + 4]
    mov [fault_insn_word1], eax
    mov eax, [esi + 8]
    mov [fault_insn_word2], eax
    mov eax, [esi + 12]
    mov [fault_insn_word3], eax

    mov eax, FORK_COPY_SRC_ALIAS
    call vmm_unmap_page
    popfd
    jmp .done

.alias_fail:
    popfd

.done:
    popad
    ret

fpu_record_exception_if_math:
    push eax

    mov eax, [fault_vector]
    cmp eax, 7
    je .device_not_available
    cmp eax, 16
    je .x87_exception
    cmp eax, 19
    je .simd_exception
    jmp .done

.device_not_available:
    inc dword [fpu_nm_exception_count]
    jmp .record

.x87_exception:
    inc dword [fpu_mf_exception_count]
    jmp .record

.simd_exception:
    inc dword [fpu_simd_exception_count]

.record:
    inc dword [fpu_exception_count]
    mov [fpu_last_exception_vector], eax
    mov eax, cr0
    mov [fpu_exception_cr0], eax
    mov eax, cr4
    mov [fpu_exception_cr4], eax
    cmp dword [fault_vector], 7
    je .done
    fnstcw [fpu_exception_control_word]
    fnstsw [fpu_exception_status_word]
    cmp dword [fault_vector], 16
    jne .done
    fnclex

.done:
    pop eax
    ret

panic_dump_fault:
    push eax
    push esi

    mov esi, panic_banner_text
    call print_string

    mov esi, panic_vector_text
    call print_string
    mov eax, [fault_vector]
    call print_hex32
    mov esi, panic_error_text
    call print_string
    mov eax, [fault_error]
    call print_hex32
    mov esi, panic_eip_text
    call print_string
    mov eax, [fault_eip]
    call print_hex32
    call newline

    mov esi, panic_cs_text
    call print_string
    mov eax, [fault_cs]
    call print_hex32
    mov esi, panic_eflags_text
    call print_string
    mov eax, [fault_eflags]
    call print_hex32
    mov esi, panic_esp_text
    call print_string
    mov eax, [fault_esp]
    call print_hex32
    mov esi, panic_ss_text
    call print_string
    mov eax, [fault_ss]
    call print_hex32
    call newline

    mov esi, panic_regs0_text
    call print_string
    mov eax, [fault_eax]
    call print_hex32
    mov esi, panic_ebx_text
    call print_string
    mov eax, [fault_ebx]
    call print_hex32
    mov esi, panic_ecx_text
    call print_string
    mov eax, [fault_ecx]
    call print_hex32
    mov esi, panic_edx_text
    call print_string
    mov eax, [fault_edx]
    call print_hex32
    call newline

    mov esi, panic_regs1_text
    call print_string
    mov eax, [fault_esi]
    call print_hex32
    mov esi, panic_edi_text
    call print_string
    mov eax, [fault_edi]
    call print_hex32
    mov esi, panic_ebp_text
    call print_string
    mov eax, [fault_ebp]
    call print_hex32
    mov esi, panic_cr2_text
    call print_string
    mov eax, [fault_cr2]
    call print_hex32
    call newline

    mov esi, panic_segs_text
    call print_string
    mov eax, [fault_ds]
    call print_hex32
    mov esi, panic_es_text
    call print_string
    mov eax, [fault_es]
    call print_hex32
    mov esi, panic_fs_text
    call print_string
    mov eax, [fault_fs]
    call print_hex32
    mov esi, panic_gs_text
    call print_string
    mov eax, [fault_gs]
    call print_hex32
    call newline

    call panic_dump_page_fault

    mov esi, panic_process_text
    call print_string
    mov eax, [fault_proc_ptr]
    call print_hex32
    mov esi, panic_pid_text
    call print_string
    mov eax, [fault_pid]
    call print_hex32
    mov esi, panic_kind_text
    call print_string
    mov eax, [fault_kind]
    call print_hex32
    mov esi, panic_state_text
    call print_string
    mov eax, [fault_state]
    call print_hex32
    mov esi, panic_syscall_text
    call print_string
    mov eax, [fault_last_syscall]
    call print_hex32
    call newline

    mov esi, panic_faultmeta_text
    call print_string
    mov eax, [fault_source]
    call fault_source_to_string
    call print_string
    mov esi, panic_mode_text
    call print_string
    mov eax, [fault_mode]
    call fault_mode_to_string
    call print_string
    mov esi, panic_contained_text
    call print_string
    mov eax, [fault_contained]
    call print_hex32
    mov esi, panic_counts_text
    call print_string
    mov eax, [fault_expected_recovered_count]
    call print_hex32
    mov al, '/'
    call put_char
    mov eax, [fault_user_contained_count]
    call print_hex32
    mov al, '/'
    call put_char
    mov eax, [payload_lifecycle_fault_count + USER_KIND_PAYLOAD_PRIMARY * 4]
    call print_hex32
    mov al, '/'
    call put_char
    mov eax, [fault_kernel_panic_count]
    call print_hex32
    call newline

    mov esi, panic_memory_text
    call print_string
    mov eax, [fault_proc_base]
    call print_hex32
    mov esi, panic_end_text
    call print_string
    mov eax, [fault_proc_end]
    call print_hex32
    mov esi, panic_brk_text
    call print_string
    mov eax, [fault_proc_brk]
    call print_hex32
    mov esi, panic_stack_text
    call print_string
    mov eax, [fault_proc_stack_top]
    call print_hex32
    call newline

    mov esi, panic_entry_text
    call print_string
    mov eax, [fault_proc_entry]
    call print_hex32
    mov esi, panic_heap_text
    call print_string
    mov eax, [fault_proc_heap_start]
    call print_hex32
    mov al, '/'
    call put_char
    mov eax, [fault_proc_heap_end]
    call print_hex32
    mov esi, panic_cr3_text
    call print_string
    mov eax, [fault_cr3]
    call print_hex32
    call newline

    pop esi
    pop eax
    ret

panic_dump_page_fault:
    cmp dword [fault_vector], 14
    jne .done
    push eax
    push esi

    mov esi, panic_pf_text
    call print_string
    mov eax, [fault_cr2]
    call print_hex32
    mov esi, panic_error_text
    call print_string
    mov eax, [fault_error]
    call print_hex32
    mov esi, panic_reason_text
    call print_string

    mov eax, [fault_error]
    test eax, 0x01
    jz .not_present
    mov esi, panic_pf_protection_text
    jmp .reason_present

.not_present:
    mov esi, panic_pf_not_present_text

.reason_present:
    call print_string
    mov al, '/'
    call put_char

    mov eax, [fault_error]
    test eax, 0x02
    jz .read_access
    mov esi, panic_pf_write_text
    jmp .access_ready

.read_access:
    mov esi, panic_pf_read_text

.access_ready:
    call print_string
    mov al, '/'
    call put_char

    mov eax, [fault_error]
    test eax, 0x04
    jz .kernel_access
    mov esi, panic_pf_user_text
    jmp .priv_ready

.kernel_access:
    mov esi, panic_pf_kernel_text

.priv_ready:
    call print_string
    mov al, '/'
    call put_char

    mov eax, [fault_error]
    test eax, 0x10
    jz .data_access
    mov esi, panic_pf_ifetch_text
    jmp .fetch_ready

.data_access:
    mov esi, panic_pf_data_text

.fetch_ready:
    call print_string
    mov eax, [fault_error]
    test eax, 0x08
    jz .line_done
    mov esi, panic_pf_reserved_text
    call print_string

.line_done:
    call newline

    pop esi
    pop eax

.done:
    ret

fault_source_to_string:
    cmp eax, FAULT_SOURCE_EXPECTED
    je .expected
    cmp eax, FAULT_SOURCE_USER
    je .user
    cmp eax, FAULT_SOURCE_PAYLOAD_PRIMARY
    je .primary_payload
    cmp eax, FAULT_SOURCE_KERNEL
    je .kernel
    cmp eax, FAULT_SOURCE_PAYLOAD_SECONDARY
    je .secondary_payload
    mov esi, smoke_none_text
    ret

.expected:
    mov esi, smoke_expect_text
    ret

.user:
    mov esi, smoke_fault_user_text
    ret

.primary_payload:
    mov esi, smoke_fault_primary_payload_text
    ret

.secondary_payload:
    mov esi, smoke_fault_secondary_payload_text
    ret

.kernel:
    mov esi, smoke_fault_kernel_text
    ret

fault_mode_to_string:
    cmp eax, FAULT_MODE_USER
    je .user
    cmp eax, FAULT_MODE_KERNEL
    je .kernel
    mov esi, smoke_none_text
    ret

.user:
    mov esi, smoke_fault_user_text
    ret

.kernel:
    mov esi, smoke_fault_kernel_text
    ret

user_process_fault:
    call fault_capture_ldso_link_map
    mov dword [fault_source], FAULT_SOURCE_USER
    mov dword [fault_mode], FAULT_MODE_USER
    mov dword [fault_contained], 1
    inc dword [fault_user_contained_count]
    cmp byte [current_user_kind], USER_KIND_PROBE
    jne .mark_faulted
    mov byte [user_probe_status], 2

.mark_faulted:
    call process_mark_current_faulted
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    mov ss, ax
    call kernel_switch_main_stack_and_return
    jmp user_probe_finished

fault_capture_ldso_link_map:
    pushad

    mov dword [fault_ldso_map], 0
    mov dword [fault_ldso_l_addr], 0
    mov dword [fault_ldso_l_ld], 0
    mov dword [fault_ldso_l_info_strtab], 0
    mov dword [fault_ldso_l_info_rpath], 0
    mov dword [fault_ldso_l_info_140], 0
    mov dword [fault_ldso_l_flags_1], 0
    mov dword [fault_ldso_dyn_first_tag], 0
    mov dword [fault_ldso_dyn_first_val], 0
    mov dword [fault_ldso_dyn_strtab_entry], 0
    mov dword [fault_ldso_dyn_strtab_val], 0
    mov dword [fault_ldso_dyn_null_index], 0xffffffff
    mov dword [fault_ldso_dyn_scanned], 0

    cmp dword [fault_vector], 14
    jne .done
    mov eax, [fault_cs]
    test eax, 3
    jz .done
    mov eax, [fault_eip]
    cmp eax, USER_INTERP_BASE
    jb .done
    cmp eax, USER_STACK_BOTTOM
    jae .done
    mov esi, [fault_edi]
    cmp esi, USER_CODE_ADDR
    jb .done
    mov eax, esi
    add eax, 0x000001aa
    jc .done
    cmp eax, USER_STACK_TOP
    jae .done

    mov [fault_ldso_map], esi
    mov eax, [esi]
    mov [fault_ldso_l_addr], eax
    mov eax, [esi + 8]
    mov [fault_ldso_l_ld], eax
    mov eax, [esi + 0x34]
    mov [fault_ldso_l_info_strtab], eax
    mov eax, [esi + 0x5c]
    mov [fault_ldso_l_info_rpath], eax
    mov eax, [esi + 0x140]
    mov [fault_ldso_l_info_140], eax
    movzx eax, byte [esi + 0x1a6]
    mov [fault_ldso_l_flags_1], eax

    mov eax, [fault_ldso_l_ld]
    cmp eax, USER_CODE_ADDR
    jb .done
    cmp eax, LINUX_LARGE_IMAGE_LIMIT
    jae .done
    mov edi, eax
    and edi, 0xfffff000
    add edi, PAGE_SIZE
    jc .done
    sub edi, eax
    shr edi, 3
    cmp edi, 96
    jbe .dynamic_limit_ready
    mov edi, 96

.dynamic_limit_ready:
    cmp edi, 0
    je .done
    mov edx, [eax]
    mov [fault_ldso_dyn_first_tag], edx
    mov edx, [eax + 4]
    mov [fault_ldso_dyn_first_val], edx
    xor ecx, ecx

.dynamic_scan:
    cmp ecx, edi
    jae .dynamic_done
    mov edx, [eax + ecx * 8]
    cmp edx, DT_STRTAB
    je .dynamic_strtab
    cmp edx, DT_NULL
    je .dynamic_null

.dynamic_next:
    inc ecx
    jmp .dynamic_scan

.dynamic_strtab:
    lea ebx, [eax + ecx * 8]
    mov [fault_ldso_dyn_strtab_entry], ebx
    mov ebx, [eax + ecx * 8 + 4]
    mov [fault_ldso_dyn_strtab_val], ebx
    jmp .dynamic_next

.dynamic_null:
    mov [fault_ldso_dyn_null_index], ecx
    inc ecx
    jmp .dynamic_done

.dynamic_done:
    mov [fault_ldso_dyn_scanned], ecx

.done:
    popad
    ret

payload_user_fault:
    push eax
    call payload_kind_to_fault_source
    mov [fault_source], eax
    pop eax
    mov dword [fault_mode], FAULT_MODE_USER
    mov dword [fault_contained], 1
    call payload_lifecycle_fault_kind
    call process_mark_current_faulted
    mov ax, DATA_SEG
    mov ds, ax
    mov es, ax
    mov fs, ax
    mov gs, ax
    mov ss, ax
    call kernel_switch_main_stack_and_return
    jmp payload_user_finished

irq_timer:
    IRQ_ENTER
    inc dword [timer_ticks]
    call clock_tick_from_timer_irq
    mov ebx, esp
    call scheduler_tick
    call clock_note_scheduler_irq_path
    call draw_timer_status
    test dword [timer_ticks], 0x0f
    jnz .status_done
    call write_smoke_status

.status_done:
    call irq_send_timer_eoi
    IRQ_RETURN

irq_keyboard:
    IRQ_ENTER
    inc dword [keyboard_irq_count]
    in al, PS2_STATUS_PORT
    test al, PS2_STATUS_OUTPUT_FULL
    jz .eoi
    test al, PS2_STATUS_AUX_OUTPUT_FULL
    jnz .aux_byte
    in al, PS2_DATA_PORT
    mov byte [keyboard_status], INPUT_DEVICE_STATUS_READY
    call keyboard_queue_scancode

.eoi:
    call irq_send_keyboard_eoi
    IRQ_RETURN

.aux_byte:
    in al, PS2_DATA_PORT
    mov byte [mouse_status], INPUT_DEVICE_STATUS_READY
    call mouse_queue_byte
    jmp .eoi

irq_mouse:
    IRQ_ENTER
    inc dword [mouse_irq_count]
    in al, PS2_STATUS_PORT
    test al, PS2_STATUS_OUTPUT_FULL
    jz .eoi
    test al, PS2_STATUS_AUX_OUTPUT_FULL
    jz .keyboard_byte
    in al, PS2_DATA_PORT
    mov byte [mouse_status], INPUT_DEVICE_STATUS_READY
    call mouse_queue_byte

.eoi:
    call irq_send_mouse_eoi
    IRQ_RETURN

.keyboard_byte:
    in al, PS2_DATA_PORT
    mov byte [keyboard_status], INPUT_DEVICE_STATUS_READY
    call keyboard_queue_scancode
    jmp .eoi

irq_ide_primary:
    IRQ_ENTER
    inc dword [ata_irq_count]
    mov dx, ATA_COMMAND_STATUS
    in al, dx
    movzx eax, al
    mov [ata_irq_status], eax
    mov [ata_last_status], eax
    call irq_send_ide_primary_eoi
    IRQ_RETURN

irq_audio:
    IRQ_ENTER
    inc dword [sb16_irq_count]
    inc dword [audio_irq_count]
    xor ebx, ebx
    mov dx, SB16_DSP_READ_STATUS
    in al, dx
    movzx eax, al
    mov [audio_irq_last_status8], eax
    test al, SB16_DSP_READY
    jz .ack16
    inc dword [sb16_irq_ack8_count]
    inc dword [audio_irq_ack8_count]
    inc ebx

.ack16:
    mov dx, SB16_DSP_ACK16
    in al, dx
    movzx eax, al
    mov [audio_irq_last_status16], eax
    test al, SB16_DSP_READY
    jz .ack_done
    inc dword [sb16_irq_ack16_count]
    inc dword [audio_irq_ack16_count]
    inc ebx

.ack_done:
    cmp ebx, 0
    jne .account_refill
    inc dword [audio_irq_spurious_count]
    jmp .send_eoi

.account_refill:
    cmp byte [sb16_playback_active], 1
    jne .send_eoi
    inc dword [sb16_irq_refill_count]
    inc dword [audio_irq_refill_count]
    xor dword [sb16_irq_half_index], 1
    call sb16_refill_active_half

.send_eoi:
    call irq_send_audio_eoi
    IRQ_RETURN

irq_lapic_spurious:
    IRQ_ENTER
    inc dword [lapic_spurious_irq_count]
    IRQ_RETURN

irq_ignore_master:
    IRQ_ENTER
    call irq_send_legacy_master_eoi
    IRQ_RETURN

irq_ignore_slave:
    IRQ_ENTER
    call irq_send_legacy_slave_eoi
    IRQ_RETURN

irq_send_timer_eoi:
    cmp dword [irq_controller_mode], IRQ_CONTROLLER_APIC
    je irq_send_lapic_eoi
    jmp irq_send_master_eoi

irq_send_keyboard_eoi:
    cmp dword [irq_controller_mode], IRQ_CONTROLLER_APIC
    je irq_send_lapic_eoi
    jmp irq_send_master_eoi

irq_send_audio_eoi:
    cmp dword [irq_controller_mode], IRQ_CONTROLLER_APIC
    je irq_send_lapic_eoi
    jmp irq_send_master_eoi

irq_send_mouse_eoi:
    cmp dword [irq_controller_mode], IRQ_CONTROLLER_APIC
    je irq_send_lapic_eoi
    jmp irq_send_slave_eoi

irq_send_ide_primary_eoi:
    cmp dword [irq_controller_mode], IRQ_CONTROLLER_APIC
    je irq_send_lapic_eoi
    jmp irq_send_slave_eoi

irq_send_legacy_master_eoi:
    cmp dword [irq_controller_mode], IRQ_CONTROLLER_APIC
    je irq_send_lapic_eoi
    jmp irq_send_master_eoi

irq_send_legacy_slave_eoi:
    cmp dword [irq_controller_mode], IRQ_CONTROLLER_APIC
    je irq_send_lapic_eoi
    jmp irq_send_slave_eoi

irq_send_master_eoi:
    push eax
    mov al, 0x20
    out 0x20, al
    inc dword [irq_eoi_master_count]
    mov dword [irq_eoi_last_kind], IRQ_EOI_MASTER
    pop eax
    ret

irq_send_slave_eoi:
    push eax
    mov al, 0x20
    out 0xa0, al
    out 0x20, al
    inc dword [irq_eoi_slave_count]
    inc dword [irq_eoi_master_count]
    mov dword [irq_eoi_last_kind], IRQ_EOI_SLAVE
    pop eax
    ret

irq_send_lapic_eoi:
    push eax
    push esi
    cmp byte [lapic_live_status], LAPIC_LIVE_STATUS_READY
    jne .done
    mov esi, [lapic_mmio_addr]
    test esi, esi
    jz .done
    mov dword [esi + LAPIC_REG_EOI], 0
    inc dword [irq_eoi_lapic_count]
    mov dword [irq_eoi_last_kind], IRQ_EOI_LAPIC

.done:
    pop esi
    pop eax
    ret

draw_timer_status:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov edi, VGA_BUFFER + ((VGA_ROWS - 1) * VGA_COLS * 2)
    mov esi, ticks_status_label

.label_next:
    lodsb
    test al, al
    jz .label_done
    mov ah, 0x0a
    mov [edi], ax
    add edi, 2
    jmp .label_next

.label_done:
    mov edx, [timer_ticks]
    mov ecx, 8

.hex_next:
    rol edx, 4
    mov bl, dl
    and bl, 0x0f
    movzx ebx, bl
    mov al, [hex_digits + ebx]
    mov ah, 0x0a
    mov [edi], ax
    add edi, 2
    loop .hex_next

    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

write_smoke_status:
    pushfd
    cli
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    call pmm_refresh_frame_counters

    cld
    cmp byte [smoke_status_initialized], 1
    je .buffer_ready
    mov edi, SMOKE_STATUS_ADDR
    xor eax, eax
    mov ecx, SMOKE_STATUS_BYTES / 4
    rep stosd
    mov byte [smoke_status_initialized], 1

.buffer_ready:
    mov edi, SMOKE_STATUS_ADDR
    mov esi, smoke_banner_text
    call smoke_copy_string

    mov esi, smoke_exec_text
    call smoke_copy_string
    cmp byte [process_exec_status], 1
    je .exec_ok
    mov esi, smoke_fail_text
    jmp .exec_write

.exec_ok:
    mov esi, smoke_ok_text

.exec_write:
    call smoke_copy_string
    mov esi, smoke_exec_path_text
    call smoke_copy_string
    cmp dword [process_exec_path_ptr], 0
    je .exec_path_empty
    mov esi, [process_exec_path_ptr]
    jmp .exec_path_write

.exec_path_empty:
    mov esi, smoke_dash_text

.exec_path_write:
    call smoke_copy_string
    mov esi, smoke_execsys_text
    call smoke_copy_string
    mov edx, [sys_exec_attempts]
    call smoke_write_hex32
    mov al, '/'
    stosb
    mov edx, [sys_exec_successes]
    call smoke_write_hex32
    mov al, '/'
    stosb
    mov edx, [sys_exec_failures]
    call smoke_write_hex32
    mov al, '/'
    stosb
    mov edx, [sys_exec_handoffs]
    call smoke_write_hex32
    mov al, '/'
    stosb
    mov edx, [sys_exec_scheduled]
    call smoke_write_hex32
    mov al, '/'
    stosb
    mov edx, [sys_exec_rollbacks]
    call smoke_write_hex32
    mov esi, smoke_execmap_text
    call smoke_copy_string
    mov edx, [process_exec_table_resolves]
    call smoke_write_hex32
    mov edx, [process_exec_generic_resolves]
    call smoke_write_slash_hex32
    mov edx, [process_exec_generic_successes]
    call smoke_write_slash_hex32
    mov edx, [process_exec_last_resolve_mode]
    call smoke_write_slash_hex32
    mov edx, [process_exec_last_success_mode]
    call smoke_write_slash_hex32
    mov edx, [process_exec_last_caller_kind]
    call smoke_write_slash_hex32
    mov edx, [process_exec_last_target_kind]
    call smoke_write_slash_hex32
    mov edx, [process_exec_last_generic_pid]
    call smoke_write_slash_hex32
    mov esi, smoke_execcopy_text
    call smoke_copy_string
    mov edx, [process_exec_copy_segment_count]
    call smoke_write_hex32
    mov edx, [process_exec_copy_cr3_switches]
    call smoke_write_slash_hex32
    mov edx, [process_exec_copy_cr3_restores]
    call smoke_write_slash_hex32
    mov edx, [process_exec_copy_last_old_cr3]
    call smoke_write_slash_hex32
    mov edx, [process_exec_copy_last_target_cr3]
    call smoke_write_slash_hex32
    mov edx, [process_exec_copy_last_source]
    call smoke_write_slash_hex32
    mov edx, [process_exec_copy_last_dest]
    call smoke_write_slash_hex32
    mov edx, [process_exec_copy_last_filesz]
    call smoke_write_slash_hex32
    mov edx, [process_exec_copy_last_memsz]
    call smoke_write_slash_hex32
    mov esi, smoke_interp_text
    call smoke_copy_string
    mov edx, [user_interp_status]
    call smoke_write_hex32
    mov edx, [user_interp_path_match]
    call smoke_write_slash_hex32
    mov esi, smoke_execerr_text
    call smoke_copy_string
    mov edx, [process_exec_last_error]
    call smoke_write_hex32
    mov esi, smoke_execbytes_text
    call smoke_copy_string
    mov edx, [process_exec_size]
    call smoke_write_hex32
    mov edx, [process_exec_max_bytes]
    call smoke_write_slash_hex32
    mov edx, [process_exec_sectors_read]
    call smoke_write_slash_hex32
    mov esi, smoke_largeelf_text
    call smoke_copy_string
    mov edx, [large_elf_status]
    call smoke_write_hex32
    mov edx, [large_elf_type]
    call smoke_write_slash_hex32
    mov edx, [large_elf_phnum]
    call smoke_write_slash_hex32
    mov edx, [large_elf_load_count]
    call smoke_write_slash_hex32
    mov edx, [large_elf_interp_status]
    call smoke_write_slash_hex32
    mov edx, [large_elf_interp_match]
    call smoke_write_slash_hex32
    mov edx, [large_elf_image_low]
    call smoke_write_slash_hex32
