    mov al, ' '
    stosb

    mov esi, package_member_status_label + 1
    call smoke_copy_string
    cmp byte [primary_package_parse_status], 1
    je .package_member_ok
    mov esi, fail_status_text
    jmp .package_member_write

.package_member_ok:
