.package_member_write:
    call smoke_copy_string
    mov al, ' '
    stosb

    mov esi, heap_status_label
    call smoke_copy_string
    cmp byte [heap_test_status], 1
    je .heap_ok
    mov esi, fail_status_text
    jmp .heap_write

.heap_ok:
    mov esi, ok_status_text

.heap_write:
    call smoke_copy_string
    mov esi, heap_status_free_label
    call smoke_copy_string
    call heap_free_bytes
    mov edx, eax
    call smoke_write_hex32

    mov al, ' '
    stosb
    mov esi, ticks_status_label
    call smoke_copy_string
    mov edx, [timer_ticks]
    call smoke_write_hex32

    mov al, 13
    stosb
    mov al, 10
    stosb
    mov byte [edi], 0

    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    popfd
    ret

smoke_copy_string:
    lodsb
    test al, al
    jz .done
    stosb
    jmp smoke_copy_string

.done:
    ret

smoke_write_hex32:
    push ebx
    push ecx

    mov ecx, 8

.next:
    rol edx, 4
    mov bl, dl
    and bl, 0x0f
    movzx ebx, bl
    mov al, [hex_digits + ebx]
    stosb
    loop .next

    pop ecx
    pop ebx
    ret

smoke_write_colon_hex32:
    mov al, ':'
    stosb
    jmp smoke_write_hex32

smoke_write_slash_hex32:
    mov al, '/'
    stosb
    jmp smoke_write_hex32

draw_primary_payload_status:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov edi, VGA_BUFFER + ((VGA_ROWS - 3) * VGA_COLS * 2)
    mov ax, (VGA_ATTR << 8) | ' '
    mov ecx, VGA_COLS

.clear_row:
    mov [edi], ax
    add edi, 2
    loop .clear_row

    mov edi, VGA_BUFFER + ((VGA_ROWS - 3) * VGA_COLS * 2)
    mov esi, primary_payload_status_label
    call draw_status_string
    cmp dword [payload_exec_status + USER_KIND_PAYLOAD_PRIMARY * 4], 1
    jne .fail
    cmp dword [payload_exec_load_status + USER_KIND_PAYLOAD_PRIMARY * 4], 1
    jne .fail
    cmp dword [payload_exec_parse_status + USER_KIND_PAYLOAD_PRIMARY * 4], 1
    jne .fail
    cmp byte [payload_load_segment_count], 0
    je .fail
    cmp byte [payload_user_window_status], 1
    jne .fail

    mov esi, ok_status_text
    call draw_status_string
    mov esi, primary_payload_status_entry_label
    call draw_status_string
    mov edx, [payload_exec_entry + USER_KIND_PAYLOAD_PRIMARY * 4]
    call draw_status_hex32
    mov esi, primary_payload_status_mem_label
    call draw_status_string
    mov edx, [payload_exec_segment_memsz + USER_KIND_PAYLOAD_PRIMARY * 4]
    call draw_status_hex32
    mov esi, gfx_status_label
    call draw_status_string
    cmp byte [present_status], 1
    je .gfx_ok
    mov esi, fail_status_text
    call draw_status_string
    jmp .done

.gfx_ok:
    mov esi, ok_status_text
    call draw_status_string
    jmp .done

.fail:
    mov esi, fail_status_text
    call draw_status_string

.done:
    pop edi
    pop esi
    pop edx
    pop ecx
    pop ebx
    pop eax
    ret

draw_heap_status:
    push eax
    push ebx
    push ecx
    push edx
    push esi
    push edi

    mov edi, VGA_BUFFER + ((VGA_ROWS - 2) * VGA_COLS * 2)
