    db '-','=',8,9
    db 'q','w','e','r','t','y','u','i','o','p'
    db '[',']',13
    times 0x1e - ($ - keymap_normal) db 0
    db 'a','s','d','f','g','h','j','k','l'
    db ';',39,'`'
    times 0x2b - ($ - keymap_normal) db 0
    db 92
    db 'z','x','c','v','b','n','m'
    db ',','.','/'
    times 0x39 - ($ - keymap_normal) db 0
    db ' '
    times 128 - ($ - keymap_normal) db 0

