    times 0x01 - ($ - keymap_shift) db 0
    db 27
    db '!','@','#','$','%','^','&','*','(',')'
    db '_','+',8,9
    db 'Q','W','E','R','T','Y','U','I','O','P'
    db '{','}',13
    times 0x1e - ($ - keymap_shift) db 0
    db 'A','S','D','F','G','H','J','K','L'
    db ':',34,'~'
    times 0x2b - ($ - keymap_shift) db 0
    db '|'
    db 'Z','X','C','V','B','N','M'
    db '<','>','?'
    times 0x39 - ($ - keymap_shift) db 0
    db ' '
    times 128 - ($ - keymap_shift) db 0

