    db '[',']',PAYLOAD_KEY_ENTER,PAYLOAD_KEY_RCTRL
    db 'a','s','d','f','g','h','j','k','l'
    db ';',39,'`',PAYLOAD_KEY_RSHIFT,92
    db 'z','x','c','v','b','n','m'
    db ',','.','/',PAYLOAD_KEY_RSHIFT
    times 0x38 - ($ - payload_keycode_map) db 0
